/**
 * Business Logic Validations
 */
export function businessRule(
  rule: (value: any, context?: any) => boolean,
  message: string,
  errorCode?: string
): ValidationRule {
  return (value: any): ValidationResult => {
    if (!rule(value)) {
      return {
        isValid: false,
        message,
        errorCode: errorCode || VALIDATION_ERROR_CODES.CONSTRAINT_VIOLATION,
      };
    }
    return { isValid: true };
  };
}

export function inventoryLevel(
  minLevel: number,
  maxLevel: number,
  message?: string
): ValidationRule {
  return (value: any): ValidationResult => {
    const numValue = Number(value);
    if (isNaN(numValue) || numValue < minLevel || numValue > maxLevel) {
      return {
        isValid: false,
        message: message || `Inventory level must be between ${minLevel} and ${maxLevel}`,
        errorCode: VALIDATION_ERROR_CODES.CONSTRAINT_VIOLATION,
      };
    }
    return { isValid: true };
  };
}

