/**
 * Table cell rendering sensitive/masked custom field values.
 * Allows revealing the plaintext value if the user has appropriate permissions
 * via the custom fields extension revealValue API.
 */
export function MaskedCustomFieldCell({
  entityTypeKey,
  ownerId,
  fieldKey,
  initialMaskedValue = "••••••••",
  valueType,
  language,
  t,
}: MaskedCustomFieldCellProps) {
  const [isRevealed, setIsRevealed] = useState(false);
  const [revealedValue, setRevealedValue] = useState<unknown>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const permissions = useAppStore((state) => state.permissions);
  const roles = useAppStore((state) => state.roles);
  const user = useAppStore((state) => state.user);

  const isSuperAdmin = Boolean(
    !user?.tenantId && (
      permissions.includes("*") ||
      roles.some(
        (r) =>
          r.roleCode === "SYSTEM_SUPER_ADMIN" ||
          r.roleName === "System Super Admin"
      ) ||
      user?.isProtected === true ||
      (user as any)?.isSuperAdmin === true ||
      user?.adminTypeName?.toLowerCase() === "system super admin"
    )
  );

  const isAuthorized = Boolean(
    isSuperAdmin || hasPermission(permissions, CUSTOM_FIELDS_PERMISSIONS.VIEW_SENSITIVE)
  );

  const handleToggle = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!isAuthorized) return;

    if (isRevealed) {
      setIsRevealed(false);
      return;
    }

    if (revealedValue !== null) {
      setIsRevealed(true);
      return;
    }

    const api = getCustomFieldsExtension();
    if (!api?.revealValue || !entityTypeKey) {
      return;
    }

    setLoading(true);
    setError(null);
    try {
      const val = await api.revealValue(entityTypeKey, ownerId, fieldKey);
      setRevealedValue(val);
      setIsRevealed(true);
    } catch (err: any) {
      setError(err?.message || "Failed to reveal");
    } finally {
      setLoading(false);
    }
  };

  const formatted =
    isRevealed && revealedValue !== null
      ? getCustomFieldsExtension()?.formatValueForDisplay?.(
          valueType,
          revealedValue,
          language,
          t
        ) ?? String(revealedValue)
      : initialMaskedValue;

  const tooltipLabel = !isAuthorized
    ? t("customField.sensitive.permissionRequired") ||
      "Requires 'custom-fields.view-sensitive' permission"
    : loading
      ? t("common.loading") || "Loading..."
      : isRevealed
        ? t("common.hide") || "Hide sensitive value"
        : t("common.reveal") || "Reveal sensitive value";

  return (
    <div className="inline-flex items-center gap-1.5 font-mono text-xs text-muted-foreground">
      <span
        className={
          isRevealed ? "font-sans text-sm text-foreground" : "tracking-widest select-none"
        }
      >
        {formatted}
      </span>
      {entityTypeKey && getCustomFieldsExtension()?.revealValue && (
        <TooltipProvider delayDuration={200}>
          <Tooltip>
            <TooltipTrigger asChild>
              <span className="inline-flex">
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  onClick={handleToggle}
                  disabled={loading || !isAuthorized}
                  className="h-6 w-6 rounded p-0.5 text-muted-foreground hover:bg-muted hover:text-foreground disabled:opacity-40"
                  aria-label={tooltipLabel}
                >
                  {loading ? (
                    <Loader2 className="h-3.5 w-3.5 animate-spin text-primary" />
                  ) : isRevealed ? (
                    <EyeOff className="h-3.5 w-3.5" />
                  ) : (
                    <Eye className="h-3.5 w-3.5" />
                  )}
                </Button>
              </span>
            </TooltipTrigger>
            <TooltipContent side="top" align="center">
              {tooltipLabel}
            </TooltipContent>
          </Tooltip>
        </TooltipProvider>
      )}
      {error && <span className="text-destructive text-[10px] ml-1">{error}</span>}
    </div>
  );
}

"use client";

/**
 * Thin Recharts wrapper for generic CRUD dashboards.
 *
 * Series colours default to the shared --chart-N slot palette from
 * `@core/ui/chart`, so call sites stop passing raw hex — pass `color` only
 * to pin an entity to a specific slot, and pass a token read when you do.
 * For richer charts (config-driven tooltips, legends, theming) compose the
 * ChartContainer foundation in `@core/ui/chart` directly.
 *
 * Chrome follows the same law as the rest of the chart system: axes and grid
 * are hairlines, labels are the quietest legible ink, and the series is the
 * only loud mark. Recharts paints its own defaults (#ccc grids, #666 tick
 * text) as SVG attributes, which the Tailwind classes that used to sit here
 * could never override — `className="stroke-muted"` on a CartesianGrid styles
 * the <g>, not the <line> children that carry their own stroke attribute. So
 * the tokens are passed as props, the way Recharts actually reads them.
 */

import {
  ResponsiveContainer,
  LineChart,
  Line,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
} from "recharts";
import { BarChart3 } from "lucide-react";
import { chartColor } from "@core/ui/chart";
import { CustomChartTooltip } from "@core/ui/charts/chart-tooltip";
import { EmptyState } from "@core/ui/empty-state";
import { useI18n } from "@core/providers/i18n-provider";

/* Token reads, as Recharts props rather than classes. Browsers resolve var()
   in SVG presentation attributes, which is the same mechanism the shared
   CHART_TOKEN_PALETTE relies on — so these follow a theme flip with no JS. */
const HAIRLINE = "var(--nx-line)";
const HAIRLINE_HI = "var(--nx-line-hi)";
const INK_QUIET = "var(--nx-ink-3)";
const SURFACE = "var(--nx-surface)";
const CURSOR_FILL = "var(--nx-raised)";

interface ChartProps {
  data: any[];
  type: "line" | "bar";
  dataKey?: string;
  height?: number;
  multiple?: Array<{
    dataKey: string;
    /** Optional slot pin; defaults to the series' palette slot. */
    color?: string;
    name: string;
  }>;
}

export function GenericChart({ data, type, dataKey, height = 300, multiple }: ChartProps) {
  const { t } = useI18n();
  const ChartComponent = type === "line" ? LineChart : BarChart;

  // Same inline read the auth surfaces use; re-resolves on the next render.
  const reducedMotion =
    typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  // An empty dataset used to render a frame of naked axes, which reads as a
  // broken chart rather than as "nothing to plot yet".
  if (!data || data.length === 0) {
    return (
      <div className="flex flex-col justify-center" style={{ height }}>
        <EmptyState size="sm" bare icon={BarChart3} title={t("common.noData")} />
      </div>
    );
  }

  const axisTick = { fill: INK_QUIET, fontSize: 12 };
  // Tabular figures so a column of axis numbers lines up digit for digit.
  const axisTickStyle = { fontVariantNumeric: "tabular-nums" as const };
  const activeDot = { r: 4, strokeWidth: 2, stroke: SURFACE };

  return (
    <ResponsiveContainer width="100%" height={height} minWidth={0} minHeight={0}>
      <ChartComponent data={data} margin={{ top: 8, right: 8, bottom: 0, left: 0 }}>
        {/* Horizontal rules only: vertical grid lines add a second grid the
            reader never asked for and compete with bar edges. */}
        <CartesianGrid strokeDasharray="3 3" stroke={HAIRLINE} vertical={false} />
        <XAxis
          dataKey="name"
          tick={{ ...axisTick, style: axisTickStyle }}
          tickLine={false}
          axisLine={{ stroke: HAIRLINE }}
          tickMargin={8}
        />
        <YAxis
          tick={{ ...axisTick, style: axisTickStyle }}
          tickLine={false}
          axisLine={false}
          width={44}
        />
        {/* The shared tooltip, so a CRUD dashboard and a module dashboard show
            the same anatomy — and so a genuine 0 prints as "0". */}
        <Tooltip
          content={<CustomChartTooltip />}
          cursor={type === "bar" ? { fill: CURSOR_FILL } : { stroke: HAIRLINE_HI, strokeWidth: 1 }}
        />
        {multiple ? (
          <>
            <Legend
              iconType="circle"
              iconSize={8}
              wrapperStyle={{ color: INK_QUIET, fontSize: 12, paddingTop: 8 }}
            />
            {multiple.map((item, index) => {
              const seriesColor = item.color ?? chartColor(index + 1);
              return type === "line" ? (
                <Line
                  key={item.dataKey}
                  type="monotone"
                  dataKey={item.dataKey}
                  stroke={seriesColor}
                  strokeWidth={2}
                  name={item.name}
                  dot={false}
                  activeDot={activeDot}
                  isAnimationActive={!reducedMotion}
                  animationDuration={200}
                />
              ) : (
                <Bar
                  key={item.dataKey}
                  dataKey={item.dataKey}
                  fill={seriesColor}
                  name={item.name}
                  radius={[4, 4, 0, 0]}
                  maxBarSize={48}
                  isAnimationActive={!reducedMotion}
                  animationDuration={200}
                />
              );
            })}
          </>
        ) : type === "line" ? (
          <Line
            type="monotone"
            dataKey={dataKey || "value"}
            stroke={chartColor(1)}
            strokeWidth={2}
            dot={false}
            activeDot={activeDot}
            isAnimationActive={!reducedMotion}
            animationDuration={200}
          />
        ) : (
          <Bar
            dataKey={dataKey || "value"}
            fill={chartColor(1)}
            radius={[4, 4, 0, 0]}
            maxBarSize={48}
            isAnimationActive={!reducedMotion}
            animationDuration={200}
          />
        )}
      </ChartComponent>
    </ResponsiveContainer>
  );
}

import { describe, it, expect, vi, afterEach } from "vitest";
import { render, screen, fireEvent, waitFor, within } from "@testing-library/react";
// `vitest.setup.ts` (which registers jest-dom's matchers at runtime for every
// suite) is itself excluded from tsc's project (see tsconfig.json "exclude"),
// and even so, it imports the plain "@testing-library/jest-dom" entry, which
// only augments Jest's global `expect` types, not Vitest's `Assertion<T>`.
// This is the first *.test.tsx in the repo living outside a `__tests__`
// folder (those are excluded from tsc entirely) that calls a jest-dom
// matcher, so it's the first to need this import for `tsc --noEmit` to see
// `toBeInTheDocument` on Vitest's own `expect()` return type.
import "@testing-library/jest-dom/vitest";
import { GenericCrudView, type CrudConfig } from "./generic-crud-view";
import { registerCustomFieldsExtension, type CustomFieldsExtensionApi } from "@core/crud/customFieldsExtension";
import { useAppStore } from "@core/store/useAppStore";

// GenericCrudView (via @core/hooks/use-permissions, a re-export) and
// GenericForm (which imports it directly) both call usePermissions() from
// this module, which throws outside a PermissionProvider — same pattern used
// in core/providers/__tests__/route-guard.test.tsx. Mocking the underlying
// module here covers both call sites. Every other hook these components call
// (useSettings, useI18n, usePermission, useRestrictedFields,
// useEnhancedDelete/Toast) already has an SSR/no-provider fallback and needs no mock.
vi.mock("@core/providers/permission-provider", () => ({
  usePermissions: () => ({
    permissions: [],
    hasPermission: () => true,
    hasAnyPermission: () => true,
    hasAllPermissions: () => true,
    canAccessPage: () => true,
    roleNames: [],
    isSuperAdmin: true,
  }),
  PermissionGate: ({ children }: { children: unknown }) => children,
}));

// Radix Switch measures its thumb with ResizeObserver; jsdom does not define it.
globalThis.ResizeObserver ??= class {
  observe() {}
  unobserve() {}
  disconnect() {}
} as unknown as typeof ResizeObserver;

// Minimal viewModel double — only the surface GenericCrudView actually reads.
function makeViewModel(overrides: Record<string, unknown> = {}) {
  return {
    items: [],
    loading: false,
    error: null,
    isCreateModalOpen: true,
    isEditModalOpen: false,
    viewModalOpen: false,
    editingItem: null,
    selectedItems: [],
    pagination: {},
    changePage: vi.fn(),
    changePageSize: vi.fn(),
    searchValue: "",
    handleSearchChange: vi.fn(),
    setIsCreateModalOpen: vi.fn(),
    setSelectedItems: vi.fn(),
    refresh: vi.fn(),
    refreshItems: vi.fn(),
    createItem: vi.fn().mockResolvedValue({ id: "new-record-id" }),
    updateItem: vi.fn().mockResolvedValue({}),
    closeEditModal: vi.fn(),
    // Real useCrudViewModel only does anything on these when the screen's
    // hook opted into { deferSuccessEffects: true } (see useCrudViewModel.ts)
    // — this mock always defines them so GenericCrudView's `?.()` call sites
    // exercise real assertions here instead of silently no-op-ing, but real
    // callers built from a plain useCrudViewModel() with no options would
    // not need them called for correct behavior (the hook's own
    // onCreateSuccess/onUpdateSuccess already closed the modal by then).
    confirmCreateSuccess: vi.fn(),
    confirmUpdateSuccess: vi.fn(),
    ...overrides,
  };
}

function registerFakeCustomFieldsExtension(): CustomFieldsExtensionApi {
  const fake: CustomFieldsExtensionApi = {
    getFormFields: vi.fn().mockResolvedValue([
      { name: "__cf__nationality", label: "Nationality", type: "text", section: "Custom Fields" },
    ]),
    saveValues: vi.fn().mockResolvedValue(undefined),
    // Empty by default -- these form-focused tests never populate table rows,
    // so useCustomFieldColumns' own ownerIds.length === 0 gate means this is
    // never actually called here; it only needs to exist to satisfy the type.
    getBulkColumnValues: vi.fn().mockResolvedValue({ columns: [], valuesByOwnerId: {} }),
    InlineAddTrigger: () => null,
  };
  registerCustomFieldsExtension(fake);
  return fake;
}

