describe("GenericCrudView + dynamic custom-field table columns", () => {
  function registerFakeColumnsExtension(response: {
    columns: Array<{
      key: string;
      labelEn: string;
      labelAr: string | null;
      valueType: string;
      options: string[] | null;
      sortOrder: number;
    }>;
    valuesByOwnerId: Record<string, Record<string, unknown>>;
  }): CustomFieldsExtensionApi {
    const fake: CustomFieldsExtensionApi = {
      getFormFields: vi.fn().mockResolvedValue([]),
      saveValues: vi.fn().mockResolvedValue(undefined),
      getBulkColumnValues: vi.fn().mockResolvedValue(response),
      InlineAddTrigger: () => null,
    };
    registerCustomFieldsExtension(fake);
    return fake;
  }

  it("appends dynamic custom-field columns after the screen's own columns, with correct per-row values, and the empty-state marker for a row missing from valuesByOwnerId", async () => {
    const extension = registerFakeColumnsExtension({
      columns: [
        {
          key: "shirt_size",
          labelEn: "Shirt Size",
          labelAr: null,
          valueType: "Text",
          options: null,
          sortOrder: 0,
        },
      ],
      valuesByOwnerId: {
        "row-1": { shirt_size: "M" },
        // "row-2" deliberately absent — the server couldn't verify it (wrong
        // tenant, deleted between the list query and this call, malformed).
      },
    });
    const vm = makeViewModel({
      isCreateModalOpen: false,
      items: [
        { id: "row-1", firstName: "Jane" },
        { id: "row-2", firstName: "John" },
      ],
    });
    const config: CrudConfig<{ id: string; firstName: string }> = {
      titleKey: "t", subtitleKey: "s",
      columns: [
        { key: "id", label: "Id" },
        { key: "firstName", label: "First Name" },
      ],
      entityTypeKey: "party.person",
    };

    render(<GenericCrudView viewModel={vm} config={config} />);

    // Dependent bulk fetch: keyed on the current page's row ids.
    await waitFor(() =>
      expect(extension.getBulkColumnValues).toHaveBeenCalledWith("party.person", ["row-1", "row-2"])
    );

    // GenericTable renders both a desktop <table> and a mobile card list at
    // the same time (CSS breakpoints hide one, not conditional rendering),
    // and jsdom in this suite has no stylesheet loaded to resolve that CSS —
    // so every assertion below is scoped to the one semantic <table> to avoid
    // matching the mobile card view's duplicate copy of the same text.
    const table = await screen.findByRole("table");
    await waitFor(() => {
      const headerLabels = within(table)
        .getAllByRole("columnheader")
        .map((cell) => cell.textContent);
      // Appended AFTER the screen's own static columns, not before.
      expect(headerLabels).toEqual(["Id", "First Name", "Shirt Size"]);
    });

    const rows = within(table).getAllByRole("row");
    // rows[0] is the header row; data rows follow in viewModel.items order.
    expect(within(rows[1]).getByText("M")).toBeInTheDocument();
    expect(within(rows[2]).getByText("—")).toBeInTheDocument();
  });

  it("does not fetch or render any dynamic columns when entityTypeKey is unset, even with rows present (existing screens stay unaffected)", async () => {
    const extension = registerFakeColumnsExtension({ columns: [], valuesByOwnerId: {} });
    const vm = makeViewModel({
      isCreateModalOpen: false,
      items: [{ id: "row-1", firstName: "Jane" }],
    });
    const config: CrudConfig<{ id: string; firstName: string }> = {
      titleKey: "t", subtitleKey: "s",
      columns: [
        { key: "id", label: "Id" },
        { key: "firstName", label: "First Name" },
      ],
      // Deliberately no entityTypeKey — the vast majority of existing screens.
    };

    render(<GenericCrudView viewModel={vm} config={config} />);

    const table = await screen.findByRole("table");
    await waitFor(() => expect(within(table).getByText("Jane")).toBeInTheDocument());

    expect(extension.getBulkColumnValues).not.toHaveBeenCalled();
    expect(within(table).getAllByRole("columnheader").map((cell) => cell.textContent)).toEqual([
      "Id",
      "First Name",
    ]);
  });
});

describe("GenericCrudView + field-level security on custom-field columns (Tier 1 slice 5)", () => {
  // Custom-field columns used to be EXEMPT from the FLS column filter, on the
  // stated grounds that a custom field's key had "no relationship to" the screen's
  // static field names. It does: `buildCustomFieldColumn` uses the definition's
  // real machine key, which is exactly the string an admin types into the
  // restricted-field list and exactly what the server matches on.
  //
  // These cases drive the REAL store (useAppStore.restrictedFields, the shape the
  // /me response populates) rather than mocking the hook, so they fail if either
  // the filter or the store wiring regresses.

  function registerColumns(
    columns: Array<{ key: string; labelEn: string }>,
    valuesByOwnerId: Record<string, Record<string, unknown>>
  ): CustomFieldsExtensionApi {
    const fake: CustomFieldsExtensionApi = {
      getFormFields: vi.fn().mockResolvedValue([]),
      saveValues: vi.fn().mockResolvedValue(undefined),
      getBulkColumnValues: vi.fn().mockResolvedValue({
        columns: columns.map((c, i) => ({
          key: c.key,
          labelEn: c.labelEn,
          labelAr: null,
          valueType: "Text",
          options: null,
          sortOrder: i,
        })),
        valuesByOwnerId,
      }),
      InlineAddTrigger: () => null,
    };
    registerCustomFieldsExtension(fake);
    return fake;
  }

  function baseConfig(): CrudConfig<{ id: string; firstName: string }> {
    return {
      titleKey: "t",
      subtitleKey: "s",
      resource: "party-people",
      columns: [
        { key: "id", label: "Id" },
        { key: "firstName", label: "First Name" },
      ],
      entityTypeKey: "party.person",
    };
  }

  function rows() {
    return makeViewModel({
      isCreateModalOpen: false,
      items: [{ id: "row-1", firstName: "Jane" }],
    });
  }

  afterEach(() => useAppStore.setState({ restrictedFields: {}, permissions: [] }));

  async function headersFor(restrictedFields: Record<string, string[]>) {
    // `resource` is what makes the FLS lookup possible, but it also engages
    // GenericCrudView's canView fallback (`{resource}.view` via usePermission,
    // which reads the store, NOT the mocked permission-provider). Without the
    // permission the screen renders the Lock EmptyState and there is no table to
    // assert on at all.
    useAppStore.setState({
      restrictedFields,
      permissions: ["party-people.view"] as never,
    });
    registerColumns(
      [
        { key: "salary", labelEn: "Salary" },
        { key: "shirt_size", labelEn: "Shirt Size" },
      ],
      { "row-1": { salary: "99000", shirt_size: "M" } }
    );

    render(<GenericCrudView viewModel={rows()} config={baseConfig()} />);

    const table = await screen.findByRole("table");
    // Wait on the one custom-field column that is never restricted in any case
    // below, NOT on a header count: two of these cases legitimately end with
    // fewer headers than the screen started with, and a count-based guard would
    // either race the async fetch or assert against a table that never loaded —
    // letting "the column is absent" pass vacuously.
    await waitFor(() =>
      expect(
        within(table)
          .getAllByRole("columnheader")
          .map((cell) => cell.textContent)
      ).toContain("Shirt Size")
    );
    return within(table).getAllByRole("columnheader").map((cell) => cell.textContent);
  }

  it("hides a restricted custom-field column while keeping the unrestricted ones", async () => {
    const headers = await headersFor({ "party-people": ["salary"] });

    expect(headers).toEqual(["Id", "First Name", "Shirt Size"]);
    expect(headers).not.toContain("Salary");
  });

  it("hides a restricted custom-field column when the admin typed the key in a different case", async () => {
    // The server matches OrdinalIgnoreCase, so the client must too — otherwise the
    // column renders against a server that is already withholding the value, and
    // the blank cells look like missing data rather than security.
    const headers = await headersFor({ "party-people": ["Salary"] });

    expect(headers).toEqual(["Id", "First Name", "Shirt Size"]);
  });

  it("hides a restricted STATIC column and a restricted custom-field column together", async () => {
    const headers = await headersFor({ "party-people": ["firstName", "salary"] });

    expect(headers).toEqual(["Id", "Shirt Size"]);
  });

  it("renders every custom-field column when the resource has no restrictions", async () => {
    const headers = await headersFor({ "some-other-resource": ["salary"] });

    // A restriction on an unrelated resource must not reach this screen.
    expect(headers).toEqual(["Id", "First Name", "Salary", "Shirt Size"]);
  });
});

/**
 * GenericCrudView - A fully generic, reusable CRUD component
 *
 * This component provides a complete CRUD interface with the following features:
 * - Automatic table generation with sorting and pagination
 * - Generic form handling for create/edit operations
 * - Flexible action system (individual, bulk, and custom actions)
 * - Confirmation dialogs with localization support
 * - Error handling and loading states
 * - Responsive design with mobile support
 * - Full accessibility compliance
 *
 * @author Seif
 * @version 2.0.0
 * @since 1.0.0
 */
"use client";

import { Button } from "@core/ui/button";
import { GenericTable } from "./generic-table";
import { GenericModal } from "./generic-modal";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@core/ui/dialog";
import { GenericForm, FieldConfig } from "@core/ui/forms/generic-form";
import { LoadingSpinner } from "@core/ui/loading-spinner";
import { ErrorMessage } from "@core/ui/error-message";
import { EmptyState } from "@core/ui/empty-state";
import { PageHeader } from "@core/ui/page-header";
import { ConfirmationDialog } from "@core/ui/confirmation-dialog";
import { useEnhancedDelete } from "@core/hooks/use-enhanced-delete";
import { useEnhancedToast } from "@core/hooks/use-enhanced-toast";
import { useSettings } from "@core/providers/settings-provider";
import { cn } from "@core/common/utils";
import type { PaginationInfo } from "@core/common/pagination";
import { useI18n } from "@core/providers/i18n-provider";
import { useCallback, useMemo, memo, useEffect } from "react";
import {
  Users,
  Sliders,
  ListTodo,
  Activity,
  ShieldCheck,
  Key,
  FileText,
  Inbox,
  Lock,
} from "lucide-react";
import type { LucideIcon } from "lucide-react";
import { usePermission } from "@core/hooks/use-permission";
import { usePermissions } from "@core/hooks/use-permissions";
import { useIsFieldRestricted } from "@core/hooks/use-restricted-fields";
import type { PermissionCode } from "@core/common/types/permissions";
import {
  useCustomFieldsFormFields,
  useCustomFieldColumns,
  decodeCustomFieldName,
  getCustomFieldsExtension,
} from "@core/crud/customFieldsExtension";

/* ========================================
 * TYPE DEFINITIONS & INTERFACES
 * ======================================== */

/**
 * Configuration for table columns
 * @template TItem - The type of items being displayed
 */
export interface CrudColumn<TItem = any> {
  /** Unique key for the column (must match item property) */
  key: string;
  /** Display label for the column header */
  label: string;
  /** Whether the column supports sorting */
  sortable?: boolean;
  /** Custom render function for the column content */
  render?: (value: any, item: TItem, index: number) => React.ReactNode;
  /** CSS classes for the column */
  className?: string;
  /** Whether the column is hidden on mobile */
  hideOnMobile?: boolean;
}

/**
 * Configuration for individual row actions
 * @template TItem - The type of items the action operates on
 */
export interface CrudAction<TItem = any> {
  /** Display label for the action */
  label: string;
  /** Action handler function */
  onClick?: (item: TItem) => void | Promise<void>;
  /** Button variant styling */
  variant?: "default" | "ghost" | "destructive" | "outline" | "secondary";
  /** Additional CSS classes */
  className?: string;
  /** Icon to display with the action */
  icon?: React.ReactNode;
  /** Conditional display logic */
  show?: (item: TItem) => boolean;
  /** Permission required to show this action */
  requiredPermission?: PermissionCode;
  /** Confirmation dialog title (if confirmation needed) */
  confirmTitle?: string;
  /** Confirmation dialog description (supports {name} placeholder) */
  confirmDescription?: string;
  /** Confirmation dialog variant: destructive (red/trash), warning, info, or default (green/check) */
  confirmVariant?: "destructive" | "warning" | "info" | "default";
  /** Custom confirm button text (e.g. 'Confirm', 'Transfer', 'Restore') */
  confirmButtonText?: string;
  /** Whether the action is disabled */
  disabled?: (item: TItem) => boolean;
  /** Tooltip text for the action */
  tooltip?: string;
  /** Loading state for async actions */
  loading?: boolean;
  /**
   * Marks this as the row's EDIT action so `permissions.canUpdate` gates it.
   * Optional and additive — an action without it is never auto-hidden, so no
   * existing config changes behaviour by upgrading.
   */
  isEdit?: boolean;
  /**
   * Marks this as the row's DELETE action so `permissions.canDelete` gates it.
   * An action whose `onClick` is the `handleDelete` passed into `getActions`
   * is detected automatically and does not need this flag.
   */
  isDelete?: boolean;
}

/**
 * Configuration for bulk actions (operate on multiple selected items)
 */
export interface BulkAction {
  /** Display label for the bulk action */
  label: string;
  /** Bulk action handler function */
  onClick: (selectedIds: string[]) => Promise<void>;
  /** Button variant styling */
  variant?: "default" | "outline" | "destructive" | "secondary";
  /** Additional CSS classes */
  className?: string;
  /** Confirmation dialog title */
  confirmTitle?: string;
  /** Confirmation dialog description (supports {count} placeholder) */
  confirmDescription?: string;
  /** Icon to display with the action */
  icon?: React.ReactNode;
  /** Minimum number of items required for the action */
  minItems?: number;
  /** Maximum number of items allowed for the action */
  maxItems?: number;
  /** Whether the action requires confirmation */
  requiresConfirmation?: boolean;
  /** Permission required to show this action */
  requiredPermission?: PermissionCode;
}

/**
 * Configuration for custom actions (always visible, operate on all items)
 */
export interface CustomAction {
  /** Display label for the custom action */
  label: string;
  /** Custom action handler function */
  onClick: () => Promise<void>;
  /** Button variant styling */
  variant?: "default" | "outline" | "destructive" | "secondary";
  /** Additional CSS classes */
  className?: string;
  /** Confirmation dialog title */
  confirmTitle?: string;
  /** Confirmation dialog description */
  confirmDescription?: string;
  /** Icon to display with the action */
  icon?: React.ReactNode;
  /** Whether the action is disabled */
  disabled?: boolean;
  /** Tooltip text for the action */
  tooltip?: string;
  /** Loading state for async actions */
  loading?: boolean;
  /** Permission required to show this action */
  requiredPermission?: PermissionCode;
}

/**
 * Permission configuration for CRUD operations
 * Supports both boolean flags and permission code strings
 */
export interface CrudPermissions {
  /** Permission to view/list items (if false, entire view is hidden) */
  canView?: boolean | PermissionCode;
  /** Permission to create new items */
  canCreate?: boolean | PermissionCode;
  /** Permission to update existing items */
  canUpdate?: boolean | PermissionCode;
  /** Permission to delete items */
  canDelete?: boolean | PermissionCode;
  /** Additional custom permissions */
  [key: string]: boolean | PermissionCode | undefined;
}

/**
 * Search configuration for the CRUD view
 */
export interface SearchConfig {
  /** Whether search is enabled */
  enabled?: boolean;
  /** Placeholder text for search input */
  placeholder?: string;
  /** Debounce delay in milliseconds */
  debounceMs?: number;
  /** Custom search handler */
  onSearch?: (term: string) => void;
}

/**
 * Pagination configuration for the CRUD view
 */
export interface PaginationConfig extends PaginationInfo {
  /** Page change handler */
  onPageChange?: (page: number) => void;
  /** Page size change handler */
  onPageSizeChange?: (pageSize: number) => void;
  /** Available page size options */
  pageSizeOptions?: number[];
}

/**
 * Main configuration interface for the GenericCrudView
 * @template TItem - The type of items being managed
 */
export interface CrudConfig<TItem = any> {
  /* ========================================
   * PAGE CONFIGURATION
   * ======================================== */
  /** Translation key for the page title */
  titleKey: string;
  /** Translation key for the page subtitle */
  subtitleKey: string;
  /** Custom subtitle text (overrides subtitleKey) */
  customSubtitle?: string;

  /* ========================================
   * TABLE & FORM CONFIGURATION
   * ======================================== */
  /** Column definitions for the table */
  columns: CrudColumn<TItem>[];
  /** Field definitions for create form (omit for read-only views) */
  createFields?: FieldConfig[];
  /** Field definitions for edit form (omit for read-only views). Can be a function that receives the editing item to generate dynamic fields. */
  editFields?: FieldConfig[] | ((item: TItem) => FieldConfig[]);
  /** Initial values for create form */
  createInitialValues?: Record<string, any>;
  /** Function to get initial values for edit form */
  editInitialValues?: (item: TItem) => Record<string, any>;

  /* ========================================
   * ACTION CONFIGURATION
   * ======================================== */
  /** Function to generate individual row actions */
  getActions?: (vm: any, t: any, handleDelete?: (item: TItem) => void) => CrudAction<TItem>[];
  /** Generic bulk actions for selected items */
  bulkActions?: BulkAction[];
  /** Custom actions (always visible) */
  customActions?: CustomAction[];
  /** Whether bulk actions are enabled */
  enableBulkActions?: boolean;

  /* ========================================
   * CUSTOMIZATION
   * ======================================== */
  /** Custom header content (between title and table) */
  customHeaderContent?: React.ReactNode;
  /** Custom footer content (after table) */
  customFooterContent?: React.ReactNode;
  /** Additional props for the GenericTable component */
  customTableProps?: Partial<React.ComponentProps<typeof GenericTable>>;
  /** Enable sticky actions column */
  stickyActions?: boolean;
  /** Function to get display name for items */
  getItemDisplayName?: (item: TItem) => string;
  /** Translation key for item type */
  itemTypeKey?: string;
  /** Delete service for direct deletion */
  deleteService?: (id: string) => Promise<void>;
  /** Key to force form re-rendering */
  formKey?: number;
  /** Callback when create button is clicked */
  onCreateClick?: () => void | Promise<void>;
  /** Hide the add button */
  hideAddButton?: boolean;
  /** Hide all action buttons (add and refresh) */
  hideActionButtons?: boolean;
  /** Hide the actions column completely (simpler than returning [] from getActions) */
  hideActionsColumn?: boolean;
  /** Custom render function for actions column - allows complete customization */
  renderActions?: (item: TItem) => React.ReactNode;

  /* ========================================
   * PERMISSIONS CONFIGURATION
   * ======================================== */
  /**
   * Permission configuration for this CRUD view.
   * If provided, controls visibility of Add button, Edit/Delete actions.
   * Can be boolean (static) or PermissionCode (dynamic check against user permissions).
   *
   * @example
   * // Static permissions
   * permissions: { canCreate: false, canDelete: true }
   *
   * @example
   * // Dynamic permissions (checks user's effective permissions)
   * permissions: { canCreate: "admins.create", canDelete: "admins.delete" }
   */
  permissions?: CrudPermissions;

  /**
   * Resource name for auto-generating permission codes.
   * If set, and permissions is not provided, will auto-check:
   * - canCreate: `{resource}.create`
   * - canUpdate: `{resource}.update`
   * - canDelete: `{resource}.delete`
   *
   * @example
   * resource: "admins" // Auto-checks admins.create, admins.update, admins.delete
   */
  resource?: string;

  /**
   * When set, GenericCrudView fetches this entity type's active custom-field
   * definitions and appends them to the create/edit form under a "Custom
   * Fields" section, then saves their values after a successful create or
   * update. See CustomFieldsExtensionApi (@core/crud/customFieldsExtension)
   * for how this is wired without core depending on the CustomFields module.
   *
   * REQUIREMENT: this screen's `createItem` must resolve to an object carrying
   * the new record's `id` — custom-field values are saved against that id
   * immediately after create. A create response without one throws a visible
   * error rather than silently dropping the values the user just typed.
   */
  entityTypeKey?: string;
}

interface GenericCrudViewProps<T> {
  // Original props (for backward compatibility)
  title?: string;
  subtitle?: string;
  columns?: any[];
  actions?: any[];
  createFields?: FieldConfig[];
  editFields?: FieldConfig[] | ((item: any) => FieldConfig[]);
  viewModel: any;
  pagination?: PaginationInfo & {
    onPageChange: (page: number) => void;
    onPageSizeChange?: (size: number) => void;
  };
  search?: {
    value: string;
    onChange: (term: string) => void;
    inputRef?: React.RefObject<HTMLInputElement | null>;
  };

  // New configuration-based props
  config?: CrudConfig<T>;

  // Callback when create button is clicked
  onCreateClick?: () => void | Promise<void>;
}

function GenericCrudViewInner<T>(props: GenericCrudViewProps<T>) {
  const {
    title: propTitle,
    subtitle: propSubtitle,
    columns: propColumns,
    actions: propActions,
    createFields: propCreateFields,
    editFields: propEditFields,
    viewModel,
    pagination: propPagination,
    search: propSearch,
    config,
    onCreateClick,
  } = props;
  const settings = useSettings();
  const { t } = useI18n();
  const { hasPermission } = usePermissions();

  // Enhanced delete system for professional confirmation dialogs
  const deleteSystem = useEnhancedDelete();
  const { operationSuccess, operationError } = useEnhancedToast();

  // Enhanced delete handler with professional confirmation dialog
  const handleDelete = useCallback(
    async (item: T) => {
      const itemDisplayName = config?.getItemDisplayName
        ? config.getItemDisplayName(item)
        : (item as any).name || t("common.item");
      const itemType = config?.itemTypeKey ? t(config.itemTypeKey) : t("common.item");
      const id = typeof item === "string" ? item : (item as any).id;

      await deleteSystem.confirmDelete(
        async () => {
          // Use the direct delete service from config
          if (config?.deleteService) {
            await config.deleteService(id);
            // Refresh the data after successful delete
            await viewModel.refreshItems();
            // Success message will be shown by the enhanced delete system
          } else {
            throw new Error("Delete service not configured");
          }
        },
        {
          itemName: itemDisplayName,
          itemType: itemType,
          confirmTitle: t("common.confirmDelete"),
          confirmDescription: t("crud.confirm.deleteItem", { name: itemDisplayName }),
        }
      );
    },
    [deleteSystem, viewModel, config, t]
  );

  // Generic bulk action handler
  const handleBulkAction = useCallback(
    async (action: BulkAction, selectedIds: string[]) => {
      const execute = async () => {
        await action.onClick(selectedIds);
        viewModel.setSelectedItems([]);
        await viewModel.refreshItems();
      };

      if (action.requiresConfirmation || action.confirmTitle || action.confirmDescription) {
        await deleteSystem.confirmDelete(execute, {
          itemName: t("crud.confirm.selectionLabel", { count: selectedIds.length }),
          itemType: config?.itemTypeKey ? t(config.itemTypeKey) : t("common.items"),
          confirmTitle: action.confirmTitle || action.label,
          confirmDescription:
            action.confirmDescription ||
            t("crud.confirm.bulkAction", {
              action: action.label.toLowerCase(),
              count: selectedIds.length,
            }),
        });
      } else {
        await execute();
      }
    },
    [deleteSystem, viewModel, config, t]
  );

  // Generic custom action handler
  const handleCustomAction = useCallback(
    async (action: CustomAction) => {
      const execute = async () => {
        await action.onClick();
        await viewModel.refreshItems();
      };

      if (action.confirmTitle || action.confirmDescription) {
        await deleteSystem.confirmDelete(execute, {
          itemName: t("crud.confirm.allItems"),
          itemType: config?.itemTypeKey ? t(config.itemTypeKey) : t("common.items"),
          confirmTitle: action.confirmTitle || action.label,
          confirmDescription:
            action.confirmDescription ||
            t("crud.confirm.globalAction", { action: action.label.toLowerCase() }),
        });
      } else {
        await execute();
      }
    },
    [deleteSystem, viewModel, config, t]
  );

  // Generic individual action handler
  const handleIndividualAction = useCallback(
    async (action: any, item: any) => {
      // If action has confirmTitle, it needs confirmation
      if (action.confirmTitle || action.confirmDescription) {
        const itemDisplayName = config?.getItemDisplayName
          ? config.getItemDisplayName(item)
          : item.name || item.id;
        await deleteSystem.confirmDelete(
          async () => {
            await action.onClick(item);
            await viewModel.refreshItems();
          },
          {
            itemName: itemDisplayName,
            itemType: config?.itemTypeKey ? t(config.itemTypeKey) : t("common.item"),
            confirmTitle: action.confirmTitle || action.label,
            confirmDescription:
              action.confirmDescription?.replace("{name}", itemDisplayName) ||
              t("crud.confirm.itemAction", {
                action: action.label.toLowerCase(),
                name: itemDisplayName,
              }),
            variant: action.confirmVariant || "default",
            confirmButtonText: action.confirmButtonText,
          }
        );
      } else {
        // No confirmation needed, just execute and refresh
        await action.onClick(item);
        await viewModel.refreshItems();
      }
    },
    [deleteSystem, viewModel, config, t]
  );

  // Handle create button click
  const handleCreateClick = useCallback(() => {
    // If a custom create handler is provided (e.g. page navigation), use it exclusively
    const onCreateHandler = onCreateClick || config?.onCreateClick;
    if (onCreateHandler) {
      onCreateHandler();
      return; // Don't open the modal — the handler owns the flow
    }
    // Otherwise open the create modal
    viewModel.setIsCreateModalOpen(true);
  }, [onCreateClick, config, viewModel]);

  // Use config if provided, otherwise use direct props (backward compatibility)
  const title = (config?.titleKey ? t(config.titleKey) : propTitle) || "";
  const subtitle =
    config?.customSubtitle || (config?.subtitleKey ? t(config.subtitleKey) : propSubtitle) || "";
  // The modal copy names ONE record, so it prefers the singular item type a
  // module declares and only falls back to the (usually plural) page title.
  const entity = config?.itemTypeKey ? t(config.itemTypeKey) : title;
  const allColumns = config?.columns || propColumns || [];

  // Dynamic custom-field table columns. Row ids re-derive every render
  // from the current page's items — useCustomFieldColumns internally guards
  // against refetching unless the SET of ids actually changed (pagination,
  // sort, filter, search), so this plain re-derivation needs no outer
  // memoization. The hook itself no-ops (and returns no columns) when
  // entityTypeKey is unset, so every screen without it is unaffected.
  const customFieldColumnOwnerIds = (viewModel.items || [])
    .map((item: any) => item?.id)
    .filter((id: unknown): id is string => typeof id === "string" && id.length > 0);
  const customFieldColumns = useCustomFieldColumns(config?.entityTypeKey, customFieldColumnOwnerIds);

  // Field-level security, keyed on the screen's OWN resource — the same resource
  // that guards the record itself, never Custom Fields' admin resource. Getting
  // that wrong is not a smaller filter, it is no filter: it was the exact defect
  // that let custom-field values bypass FLS on the server until Tier 1 fixed it.
  const isFieldRestricted = useIsFieldRestricted(config?.resource);

  // Only real field-level security hides a column now.
  //
  // There used to be a second layer here that dropped any column whose value
  // was null on every row of the CURRENT PAGE. It was a heuristic standing in
  // for FLS, and it was wrong in three ways: it read `item[col.key]` directly,
  // so a column whose `render` derives its content from other fields was
  // dropped even though it displays fine (that is why the Roles list had no
  // Description column — `Role` exposes descriptionEn/descriptionAr and no
  // `description` getter); it made columns appear and disappear as the user
  // paginated; and it had already forced a compatibility shim into the domain
  // model to work around itself.
  //
  // CUSTOM-FIELD COLUMNS ARE FILTERED TOO, on the same restricted set. They used
  // to be exempt, and the comment here justified it on the grounds that a custom
  // field's key "has no relationship to" the screen's static field names. That was
  // wrong on the only point that mattered: `buildCustomFieldColumn` sets
  // `key: definition.key` — the field's real machine key — which is precisely the
  // string an admin types into the restricted-field list and precisely what the
  // server now matches on. So the same filter applies, with no translation needed.
  //
  // This is defence in depth, not the control. After Tier 1 the server omits a
  // restricted custom field from the bulk response entirely, so its column would
  // usually not be built in the first place. Filtering here means the UI cannot
  // render a header for a field it will never receive a value for — including
  // against a stale cache or an older server.
  const customColumns = customFieldColumns.columns;
  const columns = useMemo(
    () => [
      ...allColumns.filter((col) => !isFieldRestricted(col.key)),
      ...customColumns.filter((col) => !isFieldRestricted(col.key)),
    ],
    [allColumns, isFieldRestricted, customColumns]
  );

  // Wrap actions to use the generic individual action handler
  const rawActions = config?.getActions
    ? config.getActions(viewModel, t, handleDelete)
    : propActions;

  // Real screens (UsersView, DsrView, InvoiceListView, EditionsView,
  // TenantPlansView, TenantFeatureDefinitionsView, ThemeManagementView,
  // ConnectOnboardingView, …) render read-only lists and set neither
  // `config.createFields` nor the `createFields` prop, so this is genuinely
  // `undefined` at runtime — the `!` this used to carry was a lie the
  // compiler had no way to check. Every existing read of this variable
  // already guarded with `|| []`; keep it typed honestly so a future spread
  // (like createFieldsWithCustom below) can't skip that guard again.
  const createFields = config?.createFields || propCreateFields;
  const customFieldsForCreate = useCustomFieldsFormFields(config?.entityTypeKey, undefined);
  const customFieldsForEdit = useCustomFieldsFormFields(
    config?.entityTypeKey,
    viewModel.editingItem?.id
  );
  // The read-only View dialog is a separate open/item pair from Edit
  // (viewModel.viewItem, not viewModel.editingItem) — fetching custom-field
  // values off editingItem here left View always empty unless a record
  // happened to also be the current edit target.
  const customFieldsForView = useCustomFieldsFormFields(
    config?.entityTypeKey,
    viewModel.viewItem?.id
  );

  const rawCustomConfigs = customFieldsForCreate.fieldConfigs;
  const createFieldsWithCustom = useMemo(() => {
    const hasCustomFields = rawCustomConfigs.length > 0;
    const hasSendSetupEmail = Boolean(createFields?.some((f) => f.name === "sendSetupEmail"));
    const alreadyHasDeferSwitch = Boolean(
      createFields?.some((f) => f.name === "deferCustomFieldsToSetup")
    );

    // If there are no custom fields for the entity, do not include deferCustomFieldsToSetup
    let baseFields = createFields ?? [];
    if (!hasCustomFields && alreadyHasDeferSwitch) {
      baseFields = baseFields.filter((f) => f.name !== "deferCustomFieldsToSetup");
    }

    if (!hasCustomFields) {
      return baseFields.filter((field) => !isFieldRestricted(field.name));
    }

    const shouldInjectDeferSwitch = hasSendSetupEmail && !alreadyHasDeferSwitch;
    const hasDeferSwitch = alreadyHasDeferSwitch || shouldInjectDeferSwitch;

    const mappedCustomConfigs = hasDeferSwitch
      ? rawCustomConfigs.map((fc) => ({
          ...fc,
          isVisible: (values: Record<string, any>) =>
            (values.sendSetupEmail === false || values.deferCustomFieldsToSetup === false) &&
            (!fc.isVisible || fc.isVisible(values)),
        }))
      : rawCustomConfigs;

    const injectedFields: FieldConfig[] = [];
    if (shouldInjectDeferSwitch) {
      const deferSwitch: FieldConfig = {
        name: "deferCustomFieldsToSetup",
        label:
          t("admin.deferCustomFieldsToSetup") ||
          "Complete custom fields during account setup",
        type: "switch",
        description:
          t("admin.deferCustomFieldsToSetupDescription") ||
          "Allow completing custom fields during the account setup invitation flow",
        section: "Custom Fields",
        defaultValue: false,
        isVisible: (values: Record<string, any>) => values.sendSetupEmail !== false,
      };
      injectedFields.push(deferSwitch);
    }

    return [...baseFields, ...injectedFields, ...mappedCustomConfigs].filter(
      (field) => !isFieldRestricted(field.name)
    );
  }, [
    createFields,
    rawCustomConfigs,
    isFieldRestricted,
    t,
  ]);

  /**
   * Splits a submitted form's data into the entity's own fields and the
   * custom-field values contributed by customFieldsForCreate/Edit — the
   * latter are namespaced (encodeCustomFieldName) precisely so this split is
   * unambiguous. Pure function of the form data; doesn't need to know which
   * FieldConfig[] produced which entries.
   */
  const splitCustomFieldValues = useCallback((data: Record<string, any>) => {
    const entityData: Record<string, any> = {};
    const customFieldValues: Record<string, unknown> = {};
    for (const [name, value] of Object.entries(data)) {
      const decoded = decodeCustomFieldName(name);
      if (decoded !== null) {
        // A cleared input submits "". The API reads null as "clear this value
        // in place", but rejects "" for a Number field (it fails decimal
        // parsing → 422) and would store "" verbatim for a Text field with no
        // way back to unset. Boolean/Select/Date controls don't produce "" the
        // same way, so mapping it unconditionally here is safe and needs no
        // per-type branch. Deliberately NOT applied to entityData below: the
        // screen's own fields keep whatever they submit today.
        customFieldValues[decoded] = value === "" ? null : value;
      } else {
        entityData[name] = value;
      }
    }
    return { entityData, customFieldValues };
  }, []);

  // Support dynamic editFields: if it's a function, resolve it with the current editing item
  const resolveEditFields = useCallback(
    (editingItem: any): FieldConfig[] => {
      const raw = config?.editFields || propEditFields || propCreateFields;
      if (typeof raw === "function") {
        // Only invoke with a real item. This runs on every render, including
        // the ones after the edit modal closes and `editingItem` is back to
        // null — and the call sites that use the function form type the
        // parameter as non-nullable, so any property access inside threw the
        // moment the dialog was dismissed.
        return editingItem ? raw(editingItem) : [];
      }
      return (raw || createFields || []) as FieldConfig[];
    },
    [config, propEditFields, propCreateFields, createFields]
  );
  const editingItem = viewModel.editingItem;
  const editFieldsOwn = useMemo(
    () => resolveEditFields(editingItem),
    [resolveEditFields, editingItem]
  );
  const editCustomFieldConfigs = customFieldsForEdit.fieldConfigs;
  const editFieldsWithCustom = useMemo(
    () =>
      [...editFieldsOwn, ...editCustomFieldConfigs].filter(
        (field) => !isFieldRestricted(field.name)
      ),
    [editFieldsOwn, editCustomFieldConfigs, isFieldRestricted]
  );
  // Same entity-owned field set as Edit (editFieldsOwn) — View has never had
  // its own field-shape resolution, only the custom-field portion needs the
  // view-item-keyed source.
  const viewCustomFieldConfigs = customFieldsForView.fieldConfigs;
  const viewFieldsWithCustom = useMemo(
    () =>
      [...editFieldsOwn, ...viewCustomFieldConfigs].filter(
        (field) => !isFieldRestricted(field.name)
      ),
    [editFieldsOwn, viewCustomFieldConfigs, isFieldRestricted]
  );

  // NOTE (not fixed here): this key embeds `editingItem?.id`, and
  // `closeEditModal` nulls `editingItem` in the same batch that closes the
  // modal — so during the exit animation the key flips and the form remounts
  // empty for a couple of frames. Freezing it needs the last item id to survive
  // the close, which belongs in the viewmodel; doing it in the view requires
  // reading a ref during render, which this codebase's lint rules correctly
  // forbid. Tracked separately rather than papered over.
  //
  // Hashes the SCREEN'S OWN field names only — never the custom-field configs.
  // GenericModal uses this string as a React `key` on the wrapper around
  // GenericForm, so anything in it that changes while the modal is open
  // unmounts the form and throws away everything the user typed. Custom fields
  // arrive asynchronously and grow by one every time the inline "+ Add custom
  // field" dialog succeeds; keying on them wiped the open form on each add.
  // GenericForm already absorbs a growing `fields` array without a remount (it
  // seeds only fields that have no value yet, preserving typed input), so no
  // remount is needed for custom fields to appear or to pick up their stored
  // values on edit.
  const editFormKey = `edit-form-${
    viewModel.editingItem?.id || "new"
  }-${JSON.stringify(editFieldsOwn?.map((f) => f.name).sort())}-${config?.formKey || 0}`;

  // Auto-generate pagination and search for config-based usage
  const pagination =
    propPagination ||
    (config
      ? {
          ...viewModel.pagination,
          onPageChange: viewModel.changePage,
          onPageSizeChange: viewModel.changePageSize,
        }
      : undefined);

  const search =
    propSearch ||
    (config
      ? {
          value: viewModel.searchValue,
          onChange: viewModel.handleSearchChange,
          inputRef: viewModel.searchInputRef,
        }
      : undefined);

  // ========================================
  // PERMISSION CHECKING LOGIC
  // ========================================
  // Call permission hooks at the top level (not inside useMemo/useCallback)
  const resource = config?.resource;
  const resourceViewPerm = usePermission(resource ? `${resource}.view` : "");
  const resourceCreatePerm = usePermission(resource ? `${resource}.create` : "");
  const resourceUpdatePerm = usePermission(resource ? `${resource}.update` : "");
  const resourceDeletePerm = usePermission(resource ? `${resource}.delete` : "");

  // Helper function to resolve permission values (no hooks inside)
  const resolvePermissionValue = useCallback(
    (value: boolean | PermissionCode | undefined, fallbackPermission: boolean): boolean => {
      if (value === undefined) {
        return fallbackPermission;
      }
      if (typeof value === "boolean") {
        return value;
      }
      // A string IS a permission code — the documented form of this API.
      // It used to fall through to `fallbackPermission`, and for a config
      // that declares codes but no `resource` that fallback is
      // usePermission("") === true (use-permission.ts:35). So every module
      // using the documented string form failed OPEN: the control rendered
      // for every user regardless of their permissions. `hasPermission` is
      // the provider's memoised checker, so this fails CLOSED instead.
      return hasPermission(value);
    },
    [hasPermission]
  );

  // Compute effective permissions
  const perms = config?.permissions;
  const effectivePermissions = useMemo(() => {
    // If permissions object is provided, use it with fallbacks
    if (perms) {
      return {
        canView: resolvePermissionValue(perms.canView, resourceViewPerm),
        canCreate: resolvePermissionValue(perms.canCreate, resourceCreatePerm),
        canUpdate: resolvePermissionValue(perms.canUpdate, resourceUpdatePerm),
        canDelete: resolvePermissionValue(perms.canDelete, resourceDeletePerm),
      };
    }

    // If resource is provided, use the pre-computed permission values
    if (resource) {
      return {
        canView: resourceViewPerm,
        canCreate: resourceCreatePerm,
        canUpdate: resourceUpdatePerm,
        canDelete: resourceDeletePerm,
      };
    }

    // Default: all allowed (for backward compatibility)
    return {
      canView: true,
      canCreate: true,
      canUpdate: true,
      canDelete: true,
    };
  }, [
    perms,
    resource,
    resolvePermissionValue,
    resourceViewPerm,
    resourceCreatePerm,
    resourceUpdatePerm,
    resourceDeletePerm,
  ]);

  // Determine if Add button should be shown
  const showAddButton = !config?.hideAddButton && effectivePermissions.canCreate;

  // Hide actions column if specified.
  // Declared AFTER the permission block on purpose: `canUpdate`/`canDelete`
  // are documented as gating the row's Edit/Delete actions (see CrudPermissions)
  // but were computed and never read. There is no built-in Edit/Delete — every
  // module supplies its own through `getActions` — so gating keys off the two
  // things that ARE identifiable: an action whose `onClick` is the injected
  // `handleDelete`, and the opt-in `isEdit`/`isDelete` flags. An action that
  // declares neither is never auto-hidden, so no existing config changes.
  const actions = config?.hideActionsColumn
    ? undefined
    : rawActions
        ?.filter((action) => {
          if (action.requiredPermission && !hasPermission(action.requiredPermission)) {
            return false;
          }
          const isDeleteAction = action.isDelete || action.onClick === handleDelete;
          if (isDeleteAction && !effectivePermissions.canDelete) {
            return false;
          }
          if (action.isEdit && !effectivePermissions.canUpdate) {
            return false;
          }
          return true;
        })
        .map((action) => ({
          ...action,
          onClick:
            action.onClick === handleDelete
              ? handleDelete
              : (item: any) => handleIndividualAction(action, item),
        }));

  // The glyph only — PageHeader owns the tile, its size and its single accent
  // hue. The per-resource colours this used to hand out (success for parties,
  // danger for analytics…) gave each list page an accent found nowhere else in
  // the product, which is the incoherence the shared header exists to end.
  const getPageIcon = (): LucideIcon => {
    // Keyed off `resource` ONLY. This used to also match English substrings
    // against `title`, which is the TRANSLATED page title — so in Arabic none
    // of them matched and the page icon changed when the user switched
    // language.
    const res = config?.resource?.toLowerCase() || "";

    if (res.includes("staff") || res.includes("hrms") || res.includes("party")) return Users;
    if (res.includes("work") || res.includes("task")) return ListTodo;
    if (res.includes("custom") || res.includes("field")) return Sliders;
    if (res.includes("analytics") || res.includes("metric") || res.includes("event"))
      return Activity;
    if (res.includes("compliance") || res.includes("consent") || res.includes("gdpr"))
      return ShieldCheck;
    if (
      res.includes("entitlement") ||
      res.includes("quota") ||
      res.includes("plan") ||
      res.includes("billing")
    )
      return Key;
    return FileText;
  };

  // Keyboard shortcut listener for power users.
  //
  // This listener is global (window) and used to be unguarded, which made it a
  // dialog killer: Ctrl/Cmd+K pulled focus to the page-level search input while
  // a create/edit modal was open, and because GenericModal is `modal={false}`
  // (deliberately — see generic-modal.tsx) that focus move outside the panel
  // dismissed it mid-edit. Alt+N and Alt+R fired from inside open forms too.
  // Two guards now: never while the user is typing, never while any dialog is
  // open.
  useEffect(() => {
    const isTypingTarget = (target: EventTarget | null): boolean => {
      const el = target as HTMLElement | null;
      if (!el) return false;
      if (el.isContentEditable) return true;
      const tag = el.tagName;
      return tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT";
    };

    const anyDialogOpen = (): boolean =>
      viewModel.isCreateModalOpen ||
      viewModel.isEditModalOpen ||
      viewModel.viewModalOpen ||
      // Covers dialogs this view does not own (module-specific modals,
      // confirmation dialogs, command palette) — Radix stamps both attributes.
      document.querySelector('[role="dialog"][data-state="open"]') !== null;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (isTypingTarget(e.target) || anyDialogOpen()) return;

      // Focus search input: Cmd/Ctrl + K
      if ((e.ctrlKey || e.metaKey) && e.key === "k") {
        e.preventDefault();
        search?.inputRef?.current?.focus();
        return;
      }
      // AltGr reports altKey AND ctrlKey; on Arabic and most European layouts
      // that combination is how real characters are typed, so it must not be
      // read as a shortcut.
      if (!e.altKey || e.ctrlKey) return;

      // Open add modal: Alt + N (only if allowed)
      if (e.key.toLowerCase() === "n" && showAddButton) {
        e.preventDefault();
        handleCreateClick();
      }
      // Refresh list: Alt + R
      if (e.key.toLowerCase() === "r") {
        e.preventDefault();
        viewModel.refresh();
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [search, showAddButton, handleCreateClick, viewModel]);

  const getButtonSize = () => {
    switch (settings.spacingSize) {
      case "compact":
        return "sm";
      case "comfortable":
      case "spacious":
        return "lg";
      default:
        return "default";
    }
  };

  // `canView` is documented as "if false, entire view is hidden" but was
  // computed and never read, so a module that declared it got no enforcement
  // at all. It is enforced here, above every other branch — a user without
  // read permission must not see the list, its count, or its empty state.
  if (!effectivePermissions.canView) {
    return (
      <EmptyState
        icon={Lock}
        title={t("notAuthorized.title")}
        description={t("notAuthorized.description")}
      />
    );
  }

  // These two early returns replace the ENTIRE view — including any open
  // modal, which is then unmounted mid-edit. That is reachable: a tenant whose
  // list is empty (exactly the person clicking "Add") hits `items.length === 0`
  // the moment a refetch starts with no cached previous data, and the create
  // form vanishes while they are typing in it. Suppressing them while a dialog
  // is open keeps the dialog mounted; the list underneath is not what the user
  // is looking at anyway.
  //
  // Still outstanding: both branches discard the page header, search and
  // pagination rather than rendering a skeleton in place. That is a layout
  // change too large to make safely here and is tracked separately.
  const anyModalOpen =
    viewModel.isCreateModalOpen || viewModel.isEditModalOpen || viewModel.viewModalOpen;

  if (viewModel.loading && viewModel.items.length === 0 && !anyModalOpen) {
    return <LoadingSpinner showText={false} />;
  }

  if (viewModel.error && viewModel.items.length === 0 && !anyModalOpen) {
    return <ErrorMessage message={viewModel.error} onRetry={viewModel.refresh} />;
  }

  return (
    // The settings-driven rhythm rides the ONE --spacing-unit the applicator
    // writes — the per-size space-y switch collapsed into it.
    <div className="flex flex-col" style={{ gap: "calc(var(--spacing-unit) * 1.5)" }}>
      {/* The one page header. It owns the icon tile, the h1 and the description
          measure; the action cluster rides its actions slot, so a list page and
          a record page open identically. */}
      <PageHeader
        className="mb-0"
        icon={getPageIcon()}
        title={title}
        description={subtitle}
        actions={
          <>
            {config?.customActions
              ?.filter(
                (action) => !action.requiredPermission || hasPermission(action.requiredPermission)
              )
              .map((action, index) => (
                <Button
                  key={index}
                  onClick={action.onClick}
                  variant={action.variant || "default"}
                  size={getButtonSize()}
                  className={cn("flex-1 sm:flex-none", action.className)}
                  loading={action.loading}
                  disabled={action.disabled}
                >
                  {!action.loading && action.icon && (
                    <span className="me-2" aria-hidden="true">
                      {action.icon}
                    </span>
                  )}
                  {action.label}
                </Button>
              ))}
            {config?.enableBulkActions === true &&
              viewModel.selectedItems.length > 0 &&
              config?.bulkActions
                ?.filter(
                  (action) => !action.requiredPermission || hasPermission(action.requiredPermission)
                )
                .map((action, index) => {
                  const meetsMin =
                    !action.minItems || viewModel.selectedItems.length >= action.minItems;
                  const meetsMax =
                    !action.maxItems || viewModel.selectedItems.length <= action.maxItems;
                  const enabled = meetsMin && meetsMax;

                  return (
                    <Button
                      key={index}
                      onClick={() => handleBulkAction(action, viewModel.selectedItems)}
                      variant={action.variant || "outline"}
                      size={getButtonSize()}
                      className="flex-1 sm:flex-none"
                      disabled={!enabled}
                    >
                      {action.icon && (
                        <span className="me-2" aria-hidden="true">
                          {action.icon}
                        </span>
                      )}
                      {action.label.replace("{count}", viewModel.selectedItems.length.toString())}
                    </Button>
                  );
                })}
            {config?.enableBulkActions === true && viewModel.selectedItems.length > 0 && (
              <Button
                onClick={() => viewModel.setSelectedItems([])}
                variant="outline"
                size={getButtonSize()}
                className="flex-1 sm:flex-none"
              >
                {t("common.clearSelection")}
              </Button>
            )}
            {(!config ||
              config.enableBulkActions !== true ||
              viewModel.selectedItems.length === 0) &&
              !config?.hideActionButtons && (
                <>
                  <Button
                    onClick={viewModel.refresh}
                    variant="outline"
                    size={getButtonSize()}
                    className="flex-1 sm:flex-none"
                  >
                    {t("common.refresh")}
                  </Button>
                  {/* No className: the primary variant IS the primary treatment. */}
                  {showAddButton && (
                    <Button
                      onClick={handleCreateClick}
                      className="flex-1 sm:flex-none"
                      size={getButtonSize()}
                    >
                      {t("common.add")}
                    </Button>
                  )}
                </>
              )}
          </>
        }
      />

      {/* Custom header content */}
      {config?.customHeaderContent && <div className="mb-6">{config.customHeaderContent}</div>}

      <GenericTable
        data={viewModel.items}
        columns={columns}
        actions={actions}
        loading={viewModel.loading}
        selectable={config?.enableBulkActions === true}
        selectedItems={viewModel.selectedItems}
        onSelectionChange={viewModel.setSelectedItems}
        pagination={
          pagination
            ? {
                ...pagination,
                currentPage: pagination.page, // Map page to currentPage for GenericTable
              }
            : undefined
        }
        onSearch={search?.onChange}
        searchValue={search?.value}
        searchInputRef={search?.inputRef}
        // The empty branch routes through the core EmptyState, so every CRUD
        // list inherits the nexus empty anatomy. `bare` because the table
        // container already draws the surface; customTableProps can still
        // override the node below.
        emptyMessage={<EmptyState bare icon={Inbox} title={t("common.noData")} />}
        stickyActions={config?.stickyActions}
        renderActions={
          config?.renderActions ? (row) => config.renderActions?.(row as T) : undefined
        }
        {...(config?.customTableProps || {})}
      />

      {/* Custom footer content */}
      {config?.customFooterContent && <div className="mt-6">{config.customFooterContent}</div>}

      {/* Unified Modal for Create */}
      <GenericModal
        open={viewModel.isCreateModalOpen}
        onOpenChange={viewModel.setIsCreateModalOpen}
        title={t("crud.modal.createTitle", { entity: title })}
        description={t("crud.modal.createDescription", { entity })}
        // Screen's own fields only — see the editFormKey note above: keying on
        // the custom-field configs remounted the form (wiping it) every time
        // the inline "+ Add custom field" dialog added one.
        formKey={`create-form-${JSON.stringify(createFields?.map((f) => f.name).sort())}-${
          config?.formKey || 0
        }`}
      >
        <GenericForm
          fields={createFieldsWithCustom || []}
          initialValues={config?.createInitialValues || {}}
          onSubmit={async (data) => {
            const { entityData, customFieldValues } = splitCustomFieldValues(data);
            // Sanitize: never submit restricted fields to the server
            for (const key of Object.keys(entityData)) {
              if (isFieldRestricted(key)) {
                delete entityData[key];
              }
            }
            const shouldSaveCustomFields = !entityData.deferCustomFieldsToSetup;
            delete entityData.deferCustomFieldsToSetup;
            const created = await viewModel.createItem(entityData);
            const newId = (created as { id?: string } | undefined)?.id;
            if (config?.entityTypeKey && shouldSaveCustomFields) {
              if (Object.keys(customFieldValues).length > 0) {
                if (!newId) {
                  // The values were typed, the record was created, and there is
                  // no id to hang them on — dropping them silently is the one
                  // outcome the user can't detect. Throwing routes this into
                  // GenericForm's catch → setServerError, which renders it.
                  // Deliberately NOT calling setIsCreateModalOpen(false) below
                  // this point: the dialog must stay mounted for that error to
                  // be visible.
                  throw new Error(
                    "Custom field values could not be saved: this screen's create response did not return an id. entityTypeKey requires createItem to resolve to { id }."
                  );
                }
                // Let a save failure here propagate too — same reasoning as
                // above, same catch → setServerError path, same "don't close"
                // requirement.
                await getCustomFieldsExtensionOrThrow().saveValues(
                  config.entityTypeKey,
                  newId,
                  customFieldValues
                );
                void customFieldsForCreate.refetch();
              }
            }
            // Reaching this line means the entity creation and any custom-field
            // save (if there was one to do and not deferred) have settled
            // successfully — fire the success toast and close the modal.
            // If the viewmodel opted into deferSuccessEffects (e.g. for custom fields),
            // confirmCreateSuccess triggers the deferred toast and closes the modal.
            // Otherwise, fall back to closing the modal directly if confirmCreateSuccess is not defined.
            if (viewModel.confirmCreateSuccess) {
              viewModel.confirmCreateSuccess();
            } else {
              viewModel.setIsCreateModalOpen(false);
            }
          }}
          onCancel={() => viewModel.setIsCreateModalOpen(false)}
        />
        {config?.entityTypeKey && (
          <CustomFieldsExtensionTrigger
            entityTypeKey={config.entityTypeKey}
            entityDisplayName={title}
            // InlineAddTrigger's onCreated is `() => void`, so handing it
            // `refetch` directly floated the returned promise. refetch never
            // rejects (useCustomFieldsFormFields captures failures into its own
            // `error` state), and the explicit `void` keeps that intentional.
            onCreated={() => {
              void customFieldsForCreate.refetch();
            }}
          />
        )}
      </GenericModal>

      {/* Unified Modal for Edit */}
      <GenericModal
        open={viewModel.isEditModalOpen}
        onOpenChange={(open) => {
          if (!open) {
            viewModel.closeEditModal();
          }
        }}
        title={t("crud.modal.editTitle", { entity: title })}
        description={t("crud.modal.editDescription", { entity })}
        // Frozen while the modal is closing. `closeEditModal` nulls
        // `editingItem` and flips `isEditModalOpen` in the same batch, so the
        // key used to flip to "…-new-…" during the exit animation and remount
        // the form to an empty state — the user watched their data blank out on
        // the way out.
        formKey={editFormKey}
      >
        <GenericForm
          fields={editFieldsWithCustom || createFieldsWithCustom || []}
          onSubmit={async (data) => {
            if (!viewModel.editingItem) return;
            const { entityData, customFieldValues } = splitCustomFieldValues(data);
            // Sanitize: never submit restricted fields to the server
            for (const key of Object.keys(entityData)) {
              if (isFieldRestricted(key)) {
                delete entityData[key];
              }
            }
            await viewModel.updateItem(viewModel.editingItem.id, entityData);
            if (config?.entityTypeKey) {
              if (Object.keys(customFieldValues).length > 0) {
                // Let a save failure here propagate — GenericForm's catch →
                // setServerError renders it, and (with the screen's
                // useXViewModel opted into deferSuccessEffects) the dialog
                // stays open and un-auto-closed to show it, same reasoning
                // as the create path above.
                await getCustomFieldsExtensionOrThrow().saveValues(
                  config.entityTypeKey,
                  viewModel.editingItem.id,
                  customFieldValues
                );
                void customFieldsForEdit.refetch();
              }
            }
            // Same sequencing as the create path: fire the toast and close
            // only after the entity update and custom-field save (if any) have settled.
            if (viewModel.confirmUpdateSuccess) {
              viewModel.confirmUpdateSuccess();
            } else {
              viewModel.closeEditModal();
            }
          }}
          initialValues={
            config?.editInitialValues && viewModel.editingItem
              ? config.editInitialValues(viewModel.editingItem)
              : viewModel.editingItem || {}
          }
          onCancel={() => viewModel.closeEditModal()}
        />
        {config?.entityTypeKey && (
          <CustomFieldsExtensionTrigger
            entityTypeKey={config.entityTypeKey}
            entityDisplayName={title}
            // Same fire-and-forget contract as the create modal's trigger.
            onCreated={() => {
              void customFieldsForEdit.refetch();
            }}
          />
        )}
      </GenericModal>

      {/* View Modal */}
      <Dialog
        open={viewModel.viewModalOpen}
        onOpenChange={(open) => {
          if (!open) {
            viewModel.closeViewModal();
          }
        }}
      >
        <DialogContent>
          <DialogHeader>
            <DialogTitle>{t("crud.modal.viewTitle", { entity: title })}</DialogTitle>
          </DialogHeader>
          <GenericForm
            fields={viewFieldsWithCustom || createFieldsWithCustom || []}
            initialValues={
              config?.editInitialValues && viewModel.viewItem
                ? config.editInitialValues(viewModel.viewItem)
                : viewModel.viewItem || {}
            }
            onSubmit={async () => {}} // No-op for read-only
            onCancel={viewModel.closeViewModal}
            readOnly={true}
          />
        </DialogContent>
      </Dialog>

      {/* Professional confirmation dialog for delete and action operations */}
      <ConfirmationDialog
        open={deleteSystem.showConfirmation}
        onOpenChange={deleteSystem.cancelDelete}
        title={deleteSystem.deleteOptions.confirmTitle || t("common.confirmDelete")}
        description={deleteSystem.deleteOptions.confirmDescription || t("common.deleteWarning")}
        confirmText={
          deleteSystem.deleteOptions.confirmButtonText ||
          (deleteSystem.deleteOptions.variant === "destructive" ||
          !deleteSystem.deleteOptions.variant
            ? t("common.delete")
            : t("common.confirm"))
        }
        cancelText={t("common.cancel")}
        onConfirm={deleteSystem.executeDelete}
        onCancel={deleteSystem.cancelDelete}
        variant={deleteSystem.deleteOptions.variant || "destructive"}
        isLoading={deleteSystem.isDeleting}
      />
    </div>
  );
}

// P1.4: Memoize to prevent re-renders when parent state changes
export const GenericCrudView = memo(GenericCrudViewInner) as typeof GenericCrudViewInner;

function getCustomFieldsExtensionOrThrow() {
  const api = getCustomFieldsExtension();
  if (!api) {
    throw new Error(
      "entityTypeKey was set on a CrudConfig but the CustomFields extension is not registered — check that src/app/layout.tsx imports the CustomFields bootstrap module."
    );
  }
  return api;
}

function CustomFieldsExtensionTrigger(props: {
  entityTypeKey: string;
  entityDisplayName?: string;
  onCreated: () => void;
}) {
  const api = getCustomFieldsExtension();
  if (!api) return null;
  const Trigger = api.InlineAddTrigger;
  return <Trigger {...props} />;
}

"use client";

import * as React from "react";
import { useI18n } from "@core/providers/i18n-provider";
import { Popover } from "@core/ui/popover";
import { SelectTrigger } from "./select/select-trigger";
import { SelectPanel } from "./select/select-panel";
import { useSelectOptions } from "./select/use-select-options";

export interface GenericSelectOption {
  value: string;
  label: string;
  disabled?: boolean;
  icon?: React.ReactNode;
  description?: string;
  children?: GenericSelectOption[];
  level?: number;
  parentId?: string | null;
  /**
   * Unique key for deduplication when value may change between API calls.
   * If provided, selection comparison uses this instead of value.
   * Example: permission code "admins.assign_roles" stays stable while ID rotates.
   */
  uniqueKey?: string;
}

export interface GenericSelectProps {
  // Core props
  options: GenericSelectOption[];
  value?: string | string[];
  onValueChange?: (value: string | string[]) => void;
  placeholder?: string;
  disabled?: boolean;
  className?: string;

  // Select type configuration
  type?: "single" | "searchable" | "multi" | "tree";

  // Search configuration (for searchable and multi types)
  searchable?: boolean;
  searchPlaceholder?: string;
  searchType?: "client" | "server";
  onServerSearch?: (query: string) => Promise<GenericSelectOption[]>;
  searchEndpoint?: string;
  debounceMs?: number;
  noResultsText?: string;
  searchingText?: string;

  // Multi-select specific
  maxSelectedDisplay?: number;
  selectAllText?: string;
  clearAllText?: string;
  selectedText?: string;
  allowClear?: boolean;

  // Loading state
  loading?: boolean;

  // Tree-select specific
  treeData?: GenericSelectOption[];
  onTreeDataLoad?: () => Promise<GenericSelectOption[]>;
  expandedKeys?: string[];
  onExpandedKeysChange?: (keys: string[]) => void;
  showFullPath?: boolean;

  // ── Additive, all optional ────────────────────────────────────────────────
  /** Lands on the role="combobox" element so <Label htmlFor> binds to it. */
  id?: string;
  name?: string;
  /** Draws the danger edge and sets aria-invalid. */
  invalid?: boolean;
  /** Readable value, no picker, no grey slab. NOT the same as `disabled`. */
  readOnly?: boolean;
  required?: boolean;
  describedBy?: string;
  /** Renders the error state inside the panel, with a retry when paired. */
  error?: string | null;
  onRetry?: () => void;
  /** "nothing exists yet" — distinct from "your search matched nothing". */
  emptyText?: string;
  /**
   * Accessible name for the trigger's role="combobox" element. Required
   * because that element is a `<div>`, not a labelable HTML element (button/
   * input/select/textarea/...) — a sibling `<label htmlFor>` pointing at its
   * `id` computes NO accessible name for it (HTML restricts `for`
   * association to the labelable-element set; per ARIA, role="combobox" is
   * Name From: author, not Name From: contents). Wave 2 Step 2.2's Task 4
   * review (finding T1) traced this precisely: 5 of the module's 8
   * custom-field consumer sites already relied on `<Label htmlFor>` +
   * `<GenericSelect id>` and got NO accessible name from it even before that
   * task; the other 3 sites' pre-conversion raw Radix `Select` rendered a
   * native, labelable `<button>` and DID get one, so converting them onto
   * this component (Task 7b) would have silently regressed their working
   * accessible name without this prop. Prefer `aria-labelledby` when a real
   * on-screen label element with its own `id` already exists; use
   * `aria-label` otherwise.
   */
  "aria-label"?: string;
  /** See `aria-label`'s doc comment above; points at an existing label element's `id` instead of duplicating its text. */
  "aria-labelledby"?: string;

  // Additional props
  [key: string]: any;
}

/**
 * The one select in the product: single, searchable, multi and tree.
 *
 * This is a facade. Positioning, portalling, outside-click, scroll tracking,
 * focus transfer and open/close motion are Popover's and cmdk's jobs — the
 * previous implementation hand-rolled all of them across 1369 lines, which is
 * where the invisible-but-clickable panel, the 60fps measurement loop and the
 * five-timer focus storm came from.
 *
 * The public API and its behavioural contracts are unchanged. Notably:
 * an array `value` implies multi even when `type="single"`; clearing emits
 * `""` for single and `[]` for multi; Select-All takes only the currently
 * displayed options; `uniqueKey` overrides `value` for selection comparison;
 * and selecting never remounts, because a remount would close the panel.
 */
export const GenericSelect = React.forwardRef<HTMLDivElement, GenericSelectProps>(
  (
    {
      options,
      value,
      onValueChange,
      placeholder,
      disabled = false,
      className,
      type = "single",
      searchable = false,
      searchPlaceholder,
      searchType = "client",
      onServerSearch,
      // Accepted for call-site compatibility; server search goes through
      // onServerSearch, which is the only path that ever existed.
      searchEndpoint: _searchEndpoint,
      debounceMs = 300,
      noResultsText,
      // The panel announces its own progress; kept so callers keep compiling.
      searchingText: _searchingText,
      maxSelectedDisplay = 3,
      selectAllText,
      clearAllText,
      // Retained for API compatibility — the "+N" affordance replaced the
      // "N Selected" cliff that used this string.
      selectedText: _selectedText,
      allowClear = true,
      loading = false,
      treeData,
      onTreeDataLoad,
      expandedKeys,
      onExpandedKeysChange,
      // Accepted and ignored, as before. Do not remove the key: dropping it
      // breaks callers compiled with exactOptionalPropertyTypes.
      showFullPath: _showFullPath = false,
      id,
      name,
      invalid,
      readOnly = false,
      required,
      describedBy,
      error = null,
      onRetry,
      emptyText,
      "aria-label": ariaLabel,
      "aria-labelledby": ariaLabelledBy,
      ...rest
    },
    ref
  ) => {
    const { t } = useI18n();

    const [isOpen, setIsOpen] = React.useState(false);
    const [internalExpandedKeys, setInternalExpandedKeys] = React.useState<string[]>(
      expandedKeys ?? []
    );

    // An array value means multi regardless of `type` — several call sites rely
    // on passing string[] to a select they never re-typed.
    const isMultiSelect = type === "multi" || Array.isArray(value);
    const isTreeSelect = type === "tree";
    const isSearchable = type === "searchable" || searchable || isMultiSelect || isTreeSelect;

    const activeExpandedKeys = expandedKeys ?? internalExpandedKeys;

    const {
      query,
      setQuery,
      resetQuery,
      currentValues,
      selectedOptions,
      displayOptions,
      allOptionsMap,
      isSearching,
      searchError,
      retrySearch,
      rememberOption,
      findSelectedMatch,
      isOptionSelected,
      effectiveExpandedKeys,
      pathLabelFor,
    } = useSelectOptions({
      options,
      value,
      isTreeSelect,
      searchType,
      onServerSearch,
      debounceMs,
      treeData,
      onTreeDataLoad,
      expandedKeys: activeExpandedKeys,
      isOpen,
    });

    const resolvedPlaceholder =
      placeholder ??
      (isMultiSelect ? t("components.multiSelect.placeholder") : t("components.select.placeholder"));
    const resolvedSearchPlaceholder =
      searchPlaceholder ??
      (isMultiSelect
        ? t("components.multiSelect.searchPlaceholder")
        : t("components.searchableSelect.placeholder"));
    const resolvedNoResults = noResultsText ?? t("components.multiSelect.searchStates.noResults");
    const resolvedSelectAll = selectAllText ?? t("components.multiSelect.buttons.selectAll");
    const resolvedClearAll = clearAllText ?? t("components.multiSelect.buttons.clearAll");

    const handleOpenChange = (open: boolean) => {
      if (disabled || readOnly) return;
      setIsOpen(open);
      if (!open) resetQuery();
    };

    const handleSelect = (option: GenericSelectOption) => {
      if (!onValueChange) return;
      rememberOption(allOptionsMap.get(option.value) ?? option);

      if (isMultiSelect) {
        const alreadySelected = findSelectedMatch(option);
        const next =
          alreadySelected !== undefined
            ? currentValues.filter((val) => val !== alreadySelected)
            : [...currentValues, option.value];
        onValueChange(next);
        return;
      }

      onValueChange(option.value);
      setIsOpen(false);
      resetQuery();
    };

    const handleRemoveOne = (option: GenericSelectOption) => {
      if (!onValueChange) return;
      const match = findSelectedMatch(option) ?? option.value;
      onValueChange(currentValues.filter((val) => val !== match));
    };

    const handleClear = () => {
      if (!onValueChange) return;
      // Single clears to "", multi clears to []. Callers branch on the runtime
      // type, so emitting undefined/null here would break them.
      onValueChange(isMultiSelect ? [] : "");
    };

    const handleSelectAll = () => {
      if (!onValueChange || !isMultiSelect) return;
      // Currently DISPLAYED options only — with a query active this is the
      // filtered set, which is the long-standing behaviour.
      onValueChange(displayOptions.filter((option) => !option.disabled).map((o) => o.value));
    };

    const handleToggleExpanded = (nodeValue: string) => {
      // Toggle against what is ACTUALLY open, which includes the ancestors
      // auto-opened to reveal the current selection — otherwise collapsing one
      // of those does nothing, because it was never in the caller's list.
      const next = effectiveExpandedKeys.includes(nodeValue)
        ? effectiveExpandedKeys.filter((key: string) => key !== nodeValue)
        : [...effectiveExpandedKeys, nodeValue];
      setInternalExpandedKeys(next);
      onExpandedKeysChange?.(next);
    };

    const panelError = error ?? searchError;

    return (
      <Popover open={isOpen} onOpenChange={handleOpenChange}>
        <SelectTrigger
          ref={ref}
          id={id}
          name={name}
          open={isOpen}
          multi={isMultiSelect}
          disabled={disabled}
          readOnly={readOnly}
          invalid={invalid}
          required={required}
          describedBy={describedBy}
          ariaLabel={ariaLabel}
          ariaLabelledBy={ariaLabelledBy}
          placeholder={resolvedPlaceholder}
          selectedOptions={selectedOptions}
          // Tree values show their full path — two sibling nodes under
          // different parents are otherwise identical in the closed field.
          displayLabel={selectedOptions[0] ? pathLabelFor(selectedOptions[0]) : ""}
          maxSelectedDisplay={maxSelectedDisplay}
          allowClear={allowClear}
          onClear={handleClear}
          onRemoveOne={handleRemoveOne}
          className={className}
          wrapperProps={rest}
        />
        <SelectPanel
          options={displayOptions}
          multi={isMultiSelect}
          tree={isTreeSelect}
          searchable={isSearchable}
          searchPlaceholder={resolvedSearchPlaceholder}
          query={query}
          onQueryChange={setQuery}
          loading={loading || isSearching}
          error={panelError}
          onRetry={onRetry ?? (searchError ? retrySearch : undefined)}
          emptyText={emptyText}
          noResultsText={resolvedNoResults}
          isSelected={isOptionSelected}
          onSelect={handleSelect}
          expandedKeys={effectiveExpandedKeys}
          onToggleExpanded={handleToggleExpanded}
          onSelectAll={handleSelectAll}
          onClearAll={handleClear}
          selectAllText={resolvedSelectAll}
          clearAllText={resolvedClearAll}
          selectedCount={currentValues.length}
        />
      </Popover>
    );
  }
);

GenericSelect.displayName = "GenericSelect";

export default GenericSelect;

/**
 * Generic Table Component
 *
 * A highly customizable and responsive data table with support for:
 * - Sorting by columns
 * - Pagination
 * - Row selection
 * - Search functionality
 * - Custom actions
 * - Multiple styling themes
 * - Mobile-responsive card view
 * - Internationalization
 *
 * @example
 * ```tsx
 * const columns: Column<User>[] = [
 *   { key: "name", label: "Name", sortable: true },
 *   { key: "email", label: "Email", sortable: true },
 *   { key: "role", label: "Role" }
 * ];
 *
 * const actions: Action<User>[] = [
 *   { label: "Edit", onClick: (user) => editUser(user) },
 *   { label: "Delete", onClick: (user) => deleteUser(user), variant: "destructive" }
 * ];
 *
 * <GenericTable
 *   data={users}
 *   columns={columns}
 *   actions={actions}
 *   pagination={paginationInfo}
 *   onSearch={handleSearch}
 * />
 * ```
 *
 * @author Seif
 * @version 2.0.0
 * @since 1.0.0
 */
"use client";

import type React from "react";
import { useState, useEffect, useRef, memo } from "react";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@core/ui/table";
import { Button } from "@core/ui/button";
import { Input } from "@core/ui/input";
import { Checkbox } from "@core/ui/checkbox";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@core/ui/dropdown-menu";
import {
  // The file exports its own `Pagination` config interface, so the nav
  // primitive comes in under an alias.
  Pagination as PaginationNav,
  PaginationContent,
  PaginationEllipsis,
  PaginationItem,
  PaginationLink,
  PaginationNext,
  PaginationPrevious,
} from "@core/ui/pagination";
import { MoreHorizontal, ChevronsLeft, ChevronsRight, Search } from "lucide-react";
import { LoadingSpinner } from "@core/ui/loading-spinner";
import { Skeleton } from "@core/ui/skeleton";
import GenericSelect from "./generic-select";
import { useI18n } from "@core/providers/i18n-provider";
import { useSettings } from "@core/providers/settings-provider";
import { cn, getHoverEffectClasses, getTableHoverEffectClasses } from "@core/common/utils";
import { appLogger } from "@/core/common/logger";

/**
 * Column configuration for the table
 */
export interface Column<T> {
  /** The key of the data property to display */
  key: keyof T;
  /** The display label for the column */
  label: string;
  /** Whether the column is sortable */
  sortable?: boolean;
  /** Custom width for the column, as a CSS length (e.g. "12rem", "120px"). */
  width?: string;
  /** Extra classes for both the header cell and every body cell in this column. */
  className?: string;
  /** Omit this column from the mobile card layout. */
  hideOnMobile?: boolean;
  /** Custom render function for the column content */

  render?: (value: any, row: T) => React.ReactNode;
}

/**
 * Action configuration for table rows
 */
export interface Action<T> {
  /** The label for the action */
  label: string;
  /** Optional icon for the action */
  icon?: React.ReactNode;
  /** Callback when the action is clicked */
  onClick: (row: T) => void;
  /** Visual variant of the action */
  variant?: "default" | "destructive" | "ghost";
  /** Additional CSS classes */
  className?: string;
  /** Function to determine if the action should be shown */
  show?: (row: T) => boolean;
  /** Function to determine if the action should be disabled (greyed out, non-clickable) */
  disabled?: (row: T) => boolean;
  /** Tooltip text for the action (shown on hover via title attribute) */
  tooltip?: string;
  /** Loading state for async actions - shows spinner and disables the action */
  loading?: boolean;
}

/**
 * Pagination configuration
 */
export interface Pagination {
  /** Total number of items */
  itemsCount: number;
  /** Number of items per page */
  pageSize: number;
  /** Current page number */
  currentPage: number;
  /** Total number of pages */
  pagesCount: number;
  /** Callback when page changes */
  onPageChange: (page: number) => void;
  /** Optional callback when page size changes */
  onPageSizeChange?: (size: number) => void;
}

/**
 * Props for the GenericTable component
 */
interface GenericTableProps<T> {
  data: T[];
  columns: Column<T>[];
  actions?: Action<T>[];
  loading?: boolean;
  pagination?: Pagination;
  selectable?: boolean;
  selectedItems?: string[];
  onSelectionChange?: (selected: string[]) => void;
  searchPlaceholder?: string;
  /** Empty content — a plain string or a full node (e.g. an EmptyState). */
  emptyMessage?: React.ReactNode;
  onSearch?: (term: string) => void;
  searchValue?: string;
  searchInputRef?: React.RefObject<HTMLInputElement | null>;
  overrideTableStyle?: string;
  /** Enable sticky actions column (default: true) */
  stickyActions?: boolean;
  /** Custom render function for actions column - completely overrides default actions */
  renderActions?: (row: T) => React.ReactNode;
  /**
   * Server-driven sort (F-85). When `onSortChange` is provided, the table stops
   * reordering `data` locally — it trusts `data` is already in the order the
   * caller requested from the server — and reports header clicks upward
   * instead. `sortColumn`/`sortDirection` then drive the header's sort-arrow
   * indicator. Omit all three (the default) to keep the original client-side,
   * current-page-only sort behavior unchanged.
   *
   * `sortColumn`/the callback's column argument are plain `string` (the
   * column key stringified) rather than `keyof T` — this is the boundary the
   * caller's viewmodel and the backend query string both speak, and pinning it
   * to `keyof T` here forces TS to solve for `T` at every untyped call site
   * (e.g. GenericCrudView, which invokes this generically).
   */
  sortColumn?: string;
  sortDirection?: "asc" | "desc";
  onSortChange?: (column: string, direction: "asc" | "desc") => void;
}

/**
 * Generic Table Component
 *
 * Renders a responsive data table with sorting, pagination, search, and actions.
 * Automatically switches to card view on mobile devices.
 *
 * @param props - The component props
 * @param props.data - Array of data items to display
 * @param props.columns - Column configuration
 * @param props.actions - Optional row actions
 * @param props.loading - Whether the table is in loading state
 * @param props.pagination - Pagination configuration
 * @param props.selectable - Whether rows can be selected
 * @param props.selectedItems - Array of selected item IDs
 * @param props.onSelectionChange - Callback when selection changes
 * @param props.searchPlaceholder - Placeholder text for search input
 * @param props.emptyMessage - Content to show when no data
 * @param props.onSearch - Callback for search functionality
 * @param props.searchValue - Current search value
 * @param props.searchInputRef - Ref for the search input
 * @param props.overrideTableStyle - Override the settings-driven table style
 * @param props.stickyActions - Enable sticky actions column (default: true)
 * @returns JSX element representing the table
 */

/**
 * Renders a raw cell value for a column that declares no `render`.
 *
 * `String(value)` printed the literal words "undefined" and "null", and
 * "[object Object]" for anything structured — visible product text, in the
 * table, for any column whose data is missing on a row.
 */
function formatCellValue(value: unknown): React.ReactNode {
  if (value === null || value === undefined || value === "") return "—";
  if (typeof value === "object") return "—";
  return String(value);
}

function GenericTableInner<T extends Record<string, any>>({
  data,
  columns,
  actions,
  loading,
  pagination,
  selectable = false,
  selectedItems = [],
  onSelectionChange,
  searchPlaceholder,
  emptyMessage,
  onSearch,
  searchValue,
  searchInputRef,
  overrideTableStyle,
  stickyActions = true,
  renderActions,
  sortColumn: controlledSortColumn,
  sortDirection: controlledSortDirection,
  onSortChange,
}: GenericTableProps<T>) {
  const { t, direction } = useI18n();
  const settings = useSettings();
  const [internalSortColumn, setInternalSortColumn] = useState<keyof T | null>(null);
  const [internalSortDirection, setInternalSortDirection] = useState<"asc" | "desc">("asc");
  const [searchTerm, setSearchTerm] = useState(searchValue ?? "");

  // Server-driven sort mode is opt-in: only a caller that passes onSortChange
  // (via customTableProps on the CRUD config) leaves the original client-side
  // sort path. Every other consumer of this shared table keeps behaving
  // exactly as before.
  const isServerSort = Boolean(onSortChange);
  const activeSortDirection = isServerSort
    ? (controlledSortDirection ?? "asc")
    : internalSortDirection;
  /** Is this column the one currently driving the sort, in either mode? */
  const isActiveSortColumn = (columnKey: keyof T): boolean =>
    isServerSort ? String(columnKey) === controlledSortColumn : columnKey === internalSortColumn;

  // Sticky actions state
  const tableRef = useRef<HTMLDivElement>(null);
  const actionsColumnRef = useRef<HTMLTableCellElement>(null);
  const [showLeftShadow, setShowLeftShadow] = useState(false);
  const [showRightShadow, setShowRightShadow] = useState(false);

  // The ONE tableStyle read. The twelve variants no longer fan out into class
  // math here — the style rides a single [data-table-style] attribute on the
  // root, and the Wave-C-consolidated CSS keys the variant looks off it.
  const tableStyle = overrideTableStyle || settings.tableStyle;

  // Sync from parent only when the parent's value changes to something
  // different from what we last emitted (i.e. an external/programmatic reset).
  // Render-time detection — no setState in effect.
  const [prevSearchValue, setPrevSearchValue] = useState(searchValue);
  if (searchValue !== undefined && searchValue !== prevSearchValue) {
    setPrevSearchValue(searchValue);
    setSearchTerm(searchValue);
  }

  // Debounce: notify parent after user stops typing for 500ms
  useEffect(() => {
    if (!onSearch) return;
    const handler = setTimeout(() => {
      onSearch(searchTerm);
    }, 500);
    return () => clearTimeout(handler);
  }, [searchTerm, onSearch]);

  const placeholder = searchPlaceholder ?? t("common.search");
  const empty = emptyMessage ?? t("common.noData");

  // Debug sticky actions and handle scroll shadows
  useEffect(() => {
    if (stickyActions && actions && actions.length > 0) {
      appLogger.debug("Sticky Actions Debug:", {
        stickyActions,
        actionsCount: actions.length,
        direction,
        hasActionsColumn: !!actionsColumnRef.current,
      });
    }

    // Handle scroll shadows
    const handleScrollShadows = () => {
      const tableContainer = tableRef.current;
      if (!tableContainer) return;

      const scrollableElement = tableContainer.querySelector(".overflow-x-auto") as HTMLElement;
      if (!scrollableElement) return;

      const { scrollLeft, scrollWidth, clientWidth } = scrollableElement;

      // Check if we can scroll left (show left shadow)
      setShowLeftShadow(scrollLeft > 0);

      // Check if we can scroll right (show right shadow)
      setShowRightShadow(scrollLeft < scrollWidth - clientWidth);
    };

    const tableContainer = tableRef.current;
    if (!tableContainer) return;

    const scrollableElement = tableContainer.querySelector(".overflow-x-auto") as HTMLElement;
    if (!scrollableElement) return;

    // Initial check
    handleScrollShadows();

    // Add scroll listener
    scrollableElement.addEventListener("scroll", handleScrollShadows);
    window.addEventListener("resize", handleScrollShadows);

    return () => {
      scrollableElement.removeEventListener("scroll", handleScrollShadows);
      window.removeEventListener("resize", handleScrollShadows);
    };
  }, [stickyActions, actions, direction]);

  const handleSort = (column: keyof T) => {
    if (onSortChange) {
      const columnKey = String(column);
      const nextDirection: "asc" | "desc" =
        controlledSortColumn === columnKey && controlledSortDirection === "asc" ? "desc" : "asc";
      onSortChange(columnKey, nextDirection);
      return;
    }
    if (internalSortColumn === column) {
      setInternalSortDirection(internalSortDirection === "asc" ? "desc" : "asc");
    } else {
      setInternalSortColumn(column);
      setInternalSortDirection("asc");
    }
  };

  const filteredData = onSearch
    ? data || []
    : (data || []).filter((item) =>
        Object.values(item).some((value) =>
          String(value).toLowerCase().includes(searchTerm.toLowerCase())
        )
      );

  // Server-sort mode trusts `data` is already in the requested order — the
  // rows are one server-fetched page, not the full result set, so re-sorting
  // them locally would only ever reorder within that page again (the exact
  // bug this mode exists to fix).
  const sortedData = isServerSort
    ? filteredData
    : [...filteredData].sort((a, b) => {
        if (!internalSortColumn) return 0;

        const aValue = a[internalSortColumn];
        const bValue = b[internalSortColumn];

        if (aValue < bValue) return internalSortDirection === "asc" ? -1 : 1;
        if (aValue > bValue) return internalSortDirection === "asc" ? 1 : -1;
        return 0;
      });

  // Rows deliberately pass a className so TableRow's preserved
  // className-override contract hands hover control back to this component —
  // the settings-driven treatment below stays the single source of truth for
  // row hover, exactly as before. Variant looks (striped zebra, glass wash…)
  // come from the root [data-table-style] attribute via CSS, not from here.
  const getRowClasses = () => {
    // ALWAYS apply hover effects to table rows, regardless of global settings
    const effectType = settings.hoverEffectType === "none" ? "elevate" : settings.hoverEffectType;
    const intensity =
      settings.hoverEffectIntensity === "none" ? "medium" : settings.hoverEffectIntensity;
    return cn(
      "relative border-b border-nx-line transition-colors duration-nx-micro ease-nx-enter hover:bg-nx-hover motion-reduce:transition-none",
      "data-[state=selected]:bg-nx-accent-wash",
      // Shadows only, no transforms — collapsed table rows can't float.
      getTableHoverEffectClasses(effectType, intensity)
    );
  };

  // Mobile card — one quiet nx surface; the variant skin rides the root
  // [data-table-style] attribute, the hover treatment rides the settings.
  const getCardClasses = () =>
    cn(
      "space-y-3 rounded-nx-lg border border-nx-line bg-nx-surface p-4",
      getHoverEffectClasses(settings.hoverEffectType, settings.hoverEffectIntensity)
    );

  // Sticky actions column — opaque surface so scrolling columns vanish under
  // it, a hairline start edge instead of the old painted rails.
  const stickyActionsClasses = "sticky end-0 z-raised border-s border-nx-line-hi bg-nx-surface";

  if (loading) {
    // The shared placeholder primitive, in the row silhouette — the region
    // announces the load, so the blocks themselves stay decorative.
    return (
      <div className="space-y-3" role="status" aria-busy="true" aria-label={t("common.loading")}>
        {[...Array(5)].map((_, i) => (
          <Skeleton key={i} className="h-16" />
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-4" data-table-style={tableStyle}>
      {/* Search Bar - Only show if search functionality is enabled */}
      {onSearch !== undefined && (
        <div className="relative">
          <Search
            className="absolute start-3 top-1/2 h-4 w-4 -translate-y-1/2 text-nx-ink-3"
            aria-hidden="true"
          />
          <Input
            ref={searchInputRef}
            placeholder={placeholder}
            aria-label={placeholder}
            className="ps-10"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      )}

      {/* Mobile Cards View */}
      <div className="block space-y-4 md:hidden">
        {sortedData.length === 0 ? (
          <div className="py-12 text-center text-nx-ink-3">{empty}</div>
        ) : (
          sortedData.map((row, index) => {
            const isSelected = selectable && selectedItems.includes(row.id);
            return (
              <div
                key={index}
                // Selection speaks the same language as a selected table row:
                // the accent wash behind an accent hairline, no second ring.
                className={cn(getCardClasses(), isSelected && "border-nx-accent bg-nx-accent-wash")}
              >
                {selectable && (
                  <div className="flex items-center gap-2 border-b border-nx-line pb-2">
                    <Checkbox
                      checked={isSelected}
                      onCheckedChange={(checked) => {
                        if (onSelectionChange) {
                          const newSelected = checked
                            ? [...selectedItems, row.id]
                            : selectedItems.filter((id) => id !== row.id);
                          onSelectionChange(newSelected);
                        }
                      }}
                    />
                    <span className="text-sm text-nx-ink-3">{t("table.select")}</span>
                  </div>
                )}
                {columns
                  // `hideOnMobile` is declared on CrudColumn and had zero
                  // effect — the card loop rendered every column regardless.
                  .filter((column) => !column.hideOnMobile)
                  .map((column) => (
                    <div
                      key={String(column.key)}
                      className="flex items-center justify-between gap-2"
                    >
                      <span className="text-sm font-medium text-nx-ink-2">{column.label}:</span>
                      <span className="text-sm text-nx-ink">
                        {column.render
                          ? column.render(row[column.key], row)
                          : formatCellValue(row[column.key])}
                      </span>
                    </div>
                  ))}
                {((actions && actions.length > 0) || renderActions) && (
                  <div className="flex justify-end border-t border-nx-line pt-2">
                    {renderActions ? (
                      renderActions(row)
                    ) : (
                      <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                          <Button variant="ghost" size="sm" aria-label={t("table.actions")}>
                            <MoreHorizontal className="h-4 w-4" aria-hidden="true" />
                          </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent
                          align="end"
                          className="min-w-[160px]"
                          // Same focus-restore guard as the desktop row menu below.
                          onCloseAutoFocus={(e) => e.preventDefault()}
                        >
                          {actions &&
                            actions
                              .filter((action) => !action.show || action.show(row))
                              .map((action, actionIndex) => (
                                <DropdownMenuItem
                                  key={actionIndex}
                                  onClick={() => {
                                    if (action.loading || action.disabled?.(row)) return;
                                    action.onClick(row);
                                  }}
                                  disabled={action.loading || action.disabled?.(row)}
                                  title={action.tooltip}
                                  className={cn(
                                    action.variant === "destructive" &&
                                      "text-nx-danger focus:text-nx-danger",
                                    action.className
                                  )}
                                >
                                  {action.loading ? (
                                    <LoadingSpinner size="inline" className="me-2" />
                                  ) : (
                                    action.icon && (
                                      <span className="me-2" aria-hidden="true">
                                        {action.icon}
                                      </span>
                                    )
                                  )}
                                  <span className="font-medium">{action.label}</span>
                                </DropdownMenuItem>
                              ))}
                        </DropdownMenuContent>
                      </DropdownMenu>
                    )}
                  </div>
                )}
              </div>
            );
          })
        )}
      </div>

      {/* Desktop Table View */}
      <div
        className="hidden overflow-visible rounded-nx-lg border border-nx-line bg-nx-surface md:block"
        ref={tableRef}
      >
        <div
          className="relative"
          style={{
            paddingBlock: "calc(var(--spacing-unit) * 0.75)",
            paddingInline: "calc(var(--spacing-unit) * 0.5)",
          }}
        >
          <div className="overflow-x-auto">
            {/* Scroll shadows. The edges are logical; only the gradient
                direction stays physical, because Tailwind has no logical
                gradient axis — so it resolves against the live direction. */}
            {showLeftShadow && (
              <div
                aria-hidden="true"
                className={cn(
                  "pointer-events-none absolute inset-y-0 start-0 z-raised w-4 from-nx-surface to-transparent",
                  direction === "rtl" ? "bg-gradient-to-l" : "bg-gradient-to-r"
                )}
              />
            )}
            {showRightShadow && (
              <div
                aria-hidden="true"
                className={cn(
                  "pointer-events-none absolute inset-y-0 end-0 z-raised w-4 from-nx-surface to-transparent",
                  direction === "rtl" ? "bg-gradient-to-r" : "bg-gradient-to-l"
                )}
              />
            )}
            <Table>
              <TableHeader>
                {/* Header row passes a className, so TableRow's minimal base
                    applies — no hover wash on the header band. */}
                <TableRow className="border-b border-nx-line-hi bg-nx-hover">
                  {selectable && (
                    <TableHead className="w-12">
                      <Checkbox
                        checked={
                          selectedItems.length === sortedData.length && sortedData.length > 0
                        }
                        onCheckedChange={(checked) => {
                          if (onSelectionChange) {
                            const newSelected = checked ? sortedData.map((row) => row.id) : [];
                            onSelectionChange(newSelected);
                          }
                        }}
                      />
                    </TableHead>
                  )}
                  {columns.map((column) => (
                    <TableHead
                      key={String(column.key)}
                      sortable={column.sortable}
                      sortDirection={
                        column.sortable && isActiveSortColumn(column.key)
                          ? activeSortDirection
                          : null
                      }
                      onClick={column.sortable ? () => handleSort(column.key) : undefined}
                      onKeyDown={
                        column.sortable
                          ? (e) => {
                              if (e.key === "Enter" || e.key === " ") {
                                e.preventDefault();
                                handleSort(column.key);
                              }
                            }
                          : undefined
                      }
                      tabIndex={column.sortable ? 0 : undefined}
                      // Width moved to a real style. `w-${column.width}` was
                      // interpolated at runtime, so Tailwind's JIT never saw
                      // the class and no width was ever emitted.
                      style={column.width ? { width: column.width } : undefined}
                      className={cn(
                        "whitespace-nowrap",
                        column.className,
                        // Same lit-edge focus treatment TableRow uses — the th
                        // itself is the sort control, so it must take focus.
                        column.sortable &&
                          "focus-visible:outline focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-nx-accent"
                      )}
                    >
                      {column.label}
                    </TableHead>
                  ))}
                  {((actions && actions.length > 0) || renderActions) && (
                    <TableHead
                      ref={actionsColumnRef}
                      className={cn("w-16", stickyActions && stickyActionsClasses)}
                    >
                      {t("table.actions")}
                    </TableHead>
                  )}
                </TableRow>
              </TableHeader>
              <TableBody>
                {sortedData.length === 0 ? (
                  <TableRow>
                    <TableCell
                      colSpan={
                        columns.length +
                        ((actions && actions.length > 0) || renderActions ? 1 : 0) +
                        (selectable ? 1 : 0)
                      }
                      className="h-32 text-center text-nx-ink-3"
                    >
                      {empty}
                    </TableCell>
                  </TableRow>
                ) : (
                  sortedData.map((row, index) => {
                    const isSelected = selectable && selectedItems.includes(row.id);
                    return (
                      <TableRow key={index} selected={isSelected} className={getRowClasses()}>
                        {selectable && (
                          <TableCell className="w-12">
                            <Checkbox
                              checked={isSelected}
                              onCheckedChange={(checked) => {
                                if (onSelectionChange) {
                                  const newSelected = checked
                                    ? [...selectedItems, row.id]
                                    : selectedItems.filter((id) => id !== row.id);
                                  onSelectionChange(newSelected);
                                }
                              }}
                            />
                          </TableCell>
                        )}
                        {columns.map((column) => (
                          // `column.className` is now applied. Nineteen call
                          // sites declare one — "text-end tabular-nums" on
                          // numeric columns, for instance — and every one of
                          // them was silently discarded, so numbers rendered
                          // start-aligned with proportional figures.
                          <TableCell key={String(column.key)} className={column.className}>
                            {column.render
                              ? column.render(row[column.key], row)
                              : // Bare String() printed the literal text
                                // "undefined", "null" or "[object Object]" into
                                // the cell for any column without a render.
                                formatCellValue(row[column.key])}
                          </TableCell>
                        ))}
                        {((actions && actions.length > 0) || renderActions) && (
                          <TableCell
                            className={cn(stickyActions && stickyActionsClasses)}
                            ref={index === 0 ? actionsColumnRef : undefined}
                          >
                            {renderActions ? (
                              renderActions(row)
                            ) : (
                              <div className="flex items-center justify-center">
                                <DropdownMenu>
                                  <DropdownMenuTrigger asChild>
                                    <Button
                                      variant="ghost"
                                      className="h-8 w-8 p-0"
                                      aria-label={t("table.actions")}
                                    >
                                      <MoreHorizontal className="h-4 w-4" aria-hidden="true" />
                                    </Button>
                                  </DropdownMenuTrigger>
                                  <DropdownMenuContent
                                    align={direction === "rtl" ? "start" : "end"}
                                    className="min-w-[160px]"
                                    // Radix restores focus to this menu's trigger when it
                                    // closes — and because the menu keeps an exit animation,
                                    // that restore lands ~140ms AFTER a chosen action has
                                    // already opened a dialog. The focus then sits outside
                                    // the new panel, which is the emitter behind rows whose
                                    // Edit / Assign form closed the instant it appeared.
                                    // dialog.tsx now refuses to dismiss on focus movement;
                                    // this stops the stray focus jump at the source so the
                                    // caret stays where the dialog wants it.
                                    onCloseAutoFocus={(e) => e.preventDefault()}
                                  >
                                    {actions &&
                                      actions
                                        .filter((action) => !action.show || action.show(row))
                                        .map((action, actionIndex) => (
                                          <DropdownMenuItem
                                            key={actionIndex}
                                            onClick={() => {
                                              if (action.loading || action.disabled?.(row)) return;
                                              action.onClick(row);
                                            }}
                                            disabled={action.loading || action.disabled?.(row)}
                                            title={action.tooltip}
                                            className={cn(
                                              action.variant === "destructive" &&
                                                "text-nx-danger focus:text-nx-danger",
                                              action.className
                                            )}
                                          >
                                            {action.loading ? (
                                              <LoadingSpinner size="inline" className="me-2" />
                                            ) : (
                                              action.icon && (
                                                <span className="me-2" aria-hidden="true">
                                                  {action.icon}
                                                </span>
                                              )
                                            )}
                                            <span className="font-medium">{action.label}</span>
                                          </DropdownMenuItem>
                                        ))}
                                  </DropdownMenuContent>
                                </DropdownMenu>
                              </div>
                            )}
                          </TableCell>
                        )}
                      </TableRow>
                    );
                  })
                )}
              </TableBody>
            </Table>
          </div>
        </div>
      </div>

      {/* Pagination — composed from the core pagination primitives */}
      {pagination && (
        <div className="rounded-nx-lg border border-nx-line bg-nx-surface">
          <div className="flex flex-col gap-4 p-4 lg:flex-row lg:items-center lg:justify-between">
            {/* Results Info */}
            <div className="flex flex-wrap items-center gap-4">
              <p className="text-sm font-medium text-nx-ink-2">
                {(() => {
                  const start = (pagination.currentPage - 1) * pagination.pageSize + 1;
                  const end = Math.min(
                    pagination.currentPage * pagination.pageSize,
                    pagination.itemsCount
                  );
                  return `${t("table.showing")} ${start}-${end} ${t(
                    "table.of"
                  )} ${pagination.itemsCount} ${t("table.results")}`;
                })()}
              </p>

              {/* Page Size Selector */}
              {pagination.onPageSizeChange && (
                <div className="flex items-center gap-2">
                  <span className="text-sm text-nx-ink-3">{t("table.show")}:</span>
                  <GenericSelect
                    type="single"
                    options={[10, 25, 50, 100].map((size) => ({
                      value: String(size),
                      label: String(size),
                    }))}
                    value={String(pagination.pageSize)}
                    onValueChange={(v: string | string[]) =>
                      pagination.onPageSizeChange?.(Number(typeof v === "string" ? v : v[0]))
                    }
                    className="h-8 w-auto min-w-[100px] max-w-[120px] text-center font-medium"
                    allowClear={false}
                  />
                  <span className="text-sm text-nx-ink-3">{t("table.perPage")}</span>
                </div>
              )}
            </div>

            {/* Page navigation */}
            {pagination.pagesCount > 1 && (
              <PaginationNav className="mx-0 w-auto justify-end">
                <PaginationContent className="flex-wrap">
                  {/* First Page */}
                  <PaginationItem>
                    <PaginationLink
                      href="#"
                      aria-label={t("table.firstPage")}
                      aria-disabled={pagination.currentPage === 1 || undefined}
                      tabIndex={pagination.currentPage === 1 ? -1 : undefined}
                      // Bounds states are the primitive's aria-disabled skin —
                      // dedicated ink, not an opacity veil.
                      className="h-8 w-8"
                      onClick={(e) => {
                        e.preventDefault();
                        pagination.onPageChange(1);
                      }}
                    >
                      {direction === "rtl" ? (
                        <ChevronsRight className="h-4 w-4" aria-hidden="true" />
                      ) : (
                        <ChevronsLeft className="h-4 w-4" aria-hidden="true" />
                      )}
                    </PaginationLink>
                  </PaginationItem>

                  {/* Previous Page */}
                  <PaginationItem>
                    <PaginationPrevious
                      href="#"
                      aria-disabled={pagination.currentPage === 1 || undefined}
                      tabIndex={pagination.currentPage === 1 ? -1 : undefined}
                      className="h-8"
                      onClick={(e) => {
                        e.preventDefault();
                        pagination.onPageChange(pagination.currentPage - 1);
                      }}
                    />
                  </PaginationItem>

                  {/* Page Numbers with Smart Truncation */}
                  {(() => {
                    const current = pagination.currentPage;
                    const total = pagination.pagesCount;
                    const pages: (number | string)[] = [];

                    if (total <= 7) {
                      // Show all pages if 7 or fewer
                      for (let i = 1; i <= total; i++) {
                        pages.push(i);
                      }
                    } else {
                      // Smart truncation for many pages
                      if (current <= 4) {
                        // Near beginning: 1 2 3 4 5 ... 10
                        for (let i = 1; i <= 5; i++) pages.push(i);
                        pages.push("...");
                        pages.push(total);
                      } else if (current >= total - 3) {
                        // Near end: 1 ... 6 7 8 9 10
                        pages.push(1);
                        pages.push("...");
                        for (let i = total - 4; i <= total; i++) pages.push(i);
                      } else {
                        // Middle: 1 ... 4 5 6 ... 10
                        pages.push(1);
                        pages.push("...");
                        for (let i = current - 1; i <= current + 1; i++) pages.push(i);
                        pages.push("...");
                        pages.push(total);
                      }
                    }

                    return pages.map((page, index) => {
                      if (page === "...") {
                        return (
                          <PaginationItem key={`ellipsis-${index}`}>
                            <PaginationEllipsis className="h-8 w-8" />
                          </PaginationItem>
                        );
                      }

                      const pageNum = page as number;

                      return (
                        <PaginationItem key={pageNum}>
                          <PaginationLink
                            href="#"
                            isActive={pageNum === current}
                            className="h-8 w-8"
                            onClick={(e) => {
                              e.preventDefault();
                              pagination.onPageChange(pageNum);
                            }}
                          >
                            {pageNum}
                          </PaginationLink>
                        </PaginationItem>
                      );
                    });
                  })()}

                  {/* Next Page */}
                  <PaginationItem>
                    <PaginationNext
                      href="#"
                      aria-disabled={pagination.currentPage === pagination.pagesCount || undefined}
                      tabIndex={pagination.currentPage === pagination.pagesCount ? -1 : undefined}
                      className="h-8"
                      onClick={(e) => {
                        e.preventDefault();
                        pagination.onPageChange(pagination.currentPage + 1);
                      }}
                    />
                  </PaginationItem>

                  {/* Last Page */}
                  <PaginationItem>
                    <PaginationLink
                      href="#"
                      aria-label={t("table.lastPage")}
                      aria-disabled={pagination.currentPage === pagination.pagesCount || undefined}
                      tabIndex={pagination.currentPage === pagination.pagesCount ? -1 : undefined}
                      className="h-8 w-8"
                      onClick={(e) => {
                        e.preventDefault();
                        pagination.onPageChange(pagination.pagesCount);
                      }}
                    >
                      {direction === "rtl" ? (
                        <ChevronsLeft className="h-4 w-4" aria-hidden="true" />
                      ) : (
                        <ChevronsRight className="h-4 w-4" aria-hidden="true" />
                      )}
                    </PaginationLink>
                  </PaginationItem>

                  {/* Page Jump Input */}
                  <PaginationItem className="ms-2 flex items-center gap-2 border-s border-nx-line ps-3">
                    <span className="whitespace-nowrap text-sm text-nx-ink-3">
                      {t("table.goToPage")}:
                    </span>
                    <Input
                      type="number"
                      min={1}
                      max={pagination.pagesCount}
                      aria-label={t("table.goToPage")}
                      className="h-8 w-16 text-center"
                      onKeyDown={(e) => {
                        if (e.key === "Enter") {
                          const value = parseInt((e.target as HTMLInputElement).value);
                          if (value >= 1 && value <= pagination.pagesCount) {
                            pagination.onPageChange(value);
                            (e.target as HTMLInputElement).value = "";
                          }
                        }
                      }}
                      placeholder={String(pagination.currentPage)}
                    />
                  </PaginationItem>
                </PaginationContent>
              </PaginationNav>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

// P1.4: Memoize to prevent re-renders when parent state changes

export const GenericTable = memo(GenericTableInner) as typeof GenericTableInner;

"use client";

import React, { useEffect, useRef, useMemo, useCallback } from "react";
import { TreeView } from "@core/ui/tree-view";
import { Button } from "@core/ui/button";
import { GenericForm } from "@core/ui/forms/generic-form";
import { GenericModal } from "./generic-modal";
import GenericSelect from "./generic-select";
import {} from // Pagination imports removed in favor of direct standard UI buttons
"@core/ui/pagination";
import { ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight, Plus } from "lucide-react";
import { cn } from "@core/common/utils";
import { PageHeader } from "@core/ui/page-header";
import { ConfirmationDialog } from "@core/ui/confirmation-dialog";
import { useI18n } from "@core/providers/i18n-provider";
import type { TreeViewModel, TreeNode } from "@core/hooks/use-tree-view-model";
import { appLogger } from "@core/common/logger";
import { usePermission } from "@core/hooks/use-permission";
import { usePermissions } from "@core/hooks/use-permissions";
import type { PermissionCode } from "@core/common/types/permissions";

/**
 * Permission configuration for Tree CRUD operations
 */
export interface TreePermissions {
  canView?: boolean | PermissionCode;
  canCreate?: boolean | PermissionCode;
  canUpdate?: boolean | PermissionCode;
  canDelete?: boolean | PermissionCode;
}

export interface GenericTreeViewProps<T extends TreeNode, TCreate, TUpdate> {
  viewModel: TreeViewModel<T, TCreate, TUpdate>;
  title: string;
  subtitle: string;
  getId: (node: T) => string;
  getLabel: (node: T) => React.ReactNode;
  getChildren: (node: T) => T[] | undefined;
  renderFormFields?: (
    formValues: any,
    setFormValues: (values: any) => void,
    editing: T | null,
    parentForNew: T | null
  ) => any[]; // Return field configuration array instead of JSX
  className?: string;
  showAddRoot?: boolean;
  expandOnCardClick?: boolean; // Enable/disable card click expansion

  /* ========================================
   * CUSTOM ACTIONS
   * ======================================== */
  /**
   * Custom actions to add to each tree node's menu.
   * These are added after the standard Add Child/Edit/Delete actions.
   * @example customActions={(node) => [{ label: "Enter", onClick: () => enterTenant(node) }]}
   */
  customActions?: (node: T) => Array<{
    label: string;
    onClick: () => void;
    icon?: React.ReactNode;
    variant?: "default" | "destructive";
    disabled?: boolean;
    requiredPermission?: PermissionCode;
    show?: (node: T) => boolean;
  }>;

  /* ========================================
   * PERMISSIONS CONFIGURATION
   * ======================================== */
  /**
   * Permission configuration for this tree view.
   * If provided, controls visibility of Add/Edit/Delete buttons.
   */
  permissions?: TreePermissions;

  /**
   * Resource name for auto-generating permission codes.
   * If set, auto-checks: {resource}.create, {resource}.update, {resource}.delete
   * @example resource: "tenants" // Auto-checks tenants.create, tenants.update, tenants.delete
   */
  resource?: string;
}

export function GenericTreeView<T extends TreeNode, TCreate, TUpdate>({
  viewModel: vm,
  title,
  subtitle,
  getId,
  getLabel,
  getChildren,
  renderFormFields,
  className,
  showAddRoot = true,
  expandOnCardClick = false,
  customActions,
  permissions,
  resource,
}: GenericTreeViewProps<T, TCreate, TUpdate>) {
  const { t, direction } = useI18n();

  // Debounce mechanism to prevent rapid onOpenChange calls
  const lastOnOpenChangeRef = useRef<number>(0);
  const DEBOUNCE_DELAY = 100; // 100ms debounce

  const listTree = vm.listTree;
  // Fetch on mount and when pagination or search changes
  useEffect(() => {
    listTree();
  }, [listTree]);

  // ========================================
  // PERMISSION CHECKING LOGIC
  // ========================================
  // Call permission hooks at the top level (not inside useMemo/useCallback)
  const resourceCreatePerm = usePermission(resource ? `${resource}.create` : "");
  const resourceUpdatePerm = usePermission(resource ? `${resource}.update` : "");
  const resourceDeletePerm = usePermission(resource ? `${resource}.delete` : "");

  // Helper function to resolve permission values (no hooks inside)
  const resolvePermissionValue = useCallback(
    (value: boolean | PermissionCode | undefined, fallbackPermission: boolean): boolean => {
      if (value === undefined) {
        return fallbackPermission;
      }
      if (typeof value === "boolean") {
        return value;
      }
      // For string permission codes, we can't call hooks here
      // The caller should use the resource-based permissions instead
      return fallbackPermission;
    },
    []
  );

  const { hasPermission } = usePermissions();

  const effectivePermissions = useMemo(() => {
    if (permissions) {
      return {
        canCreate: resolvePermissionValue(permissions.canCreate, resourceCreatePerm),
        canUpdate: resolvePermissionValue(permissions.canUpdate, resourceUpdatePerm),
        canDelete: resolvePermissionValue(permissions.canDelete, resourceDeletePerm),
      };
    }
    if (resource) {
      return {
        canCreate: resourceCreatePerm,
        canUpdate: resourceUpdatePerm,
        canDelete: resourceDeletePerm,
      };
    }
    return { canCreate: true, canUpdate: true, canDelete: true };
  }, [
    permissions,
    resource,
    resolvePermissionValue,
    resourceCreatePerm,
    resourceUpdatePerm,
    resourceDeletePerm,
  ]);

  // Determine button visibility
  const showAddButton = showAddRoot && effectivePermissions.canCreate;

  // Remove interfering focus management - let natural input behavior work

  // A chevron that means "previous/next page" points at the direction of
  // travel, so it resolves against the live writing direction rather than
  // being rotated 180° in place.
  const isRtl = direction === "rtl";
  const FirstPageIcon = isRtl ? ChevronsRight : ChevronsLeft;
  const PrevPageIcon = isRtl ? ChevronRight : ChevronLeft;
  const NextPageIcon = isRtl ? ChevronLeft : ChevronRight;
  const LastPageIcon = isRtl ? ChevronsLeft : ChevronsRight;

  const toolbar = !vm.config.selectable ? (
    <div className="flex items-center gap-2">
      {showAddButton && (
        <Button size="sm" onClick={() => vm.openAddChild(null)}>
          <Plus className="me-2 h-4 w-4" aria-hidden="true" />
          {t("common.add")}
        </Button>
      )}
      {/* Advanced Pagination Controls from GenericCrudView / GenericTable */}
      <div className="hidden items-center gap-2 md:flex">
        {/* Page Size Selector */}
        <div className="flex items-center gap-2 border-e border-nx-line pe-4">
          <span className="text-sm text-nx-ink-3">{t("table.show")}:</span>
          <GenericSelect
            type="single"
            options={[5, 10, 25, 50, 100].map((size) => ({
              value: String(size),
              label: String(size),
            }))}
            value={String(vm.pagination.pageSize)}
            onValueChange={(v: string | string[]) =>
              vm.changePageSize(Number(typeof v === "string" ? v : v[0]))
            }
            className="h-8 w-auto min-w-[70px] max-w-[90px] text-center font-medium"
            allowClear={false}
          />
          <span className="text-sm text-nx-ink-3">{t("table.perPage")}</span>
        </div>

        {vm.pagination.pagesCount > 1 && (
          <div className="flex items-center gap-2">
            {/* First Page */}
            <Button
              variant="outline"
              size="sm"
              onClick={() => vm.changePage(1)}
              disabled={vm.pagination.page === 1}
              className="h-8 w-8 p-0"
              aria-label={t("table.firstPage")}
            >
              <FirstPageIcon className="h-4 w-4" aria-hidden="true" />
            </Button>

            {/* Previous Page */}
            <Button
              variant="outline"
              size="sm"
              onClick={() => vm.changePage(Math.max(1, vm.pagination.page - 1))}
              disabled={vm.pagination.page === 1}
              className="h-8 w-8 p-0"
              aria-label={t("table.previousPage")}
            >
              <PrevPageIcon className="h-4 w-4" aria-hidden="true" />
            </Button>

            {/* Page Numbers with Smart Truncation */}
            <div className="flex items-center gap-1">
              {(() => {
                const current = vm.pagination.page;
                const total = vm.pagination.pagesCount;
                const pages: (number | string)[] = [];

                if (total <= 7) {
                  for (let i = 1; i <= total; i++) pages.push(i);
                } else {
                  if (current <= 4) {
                    for (let i = 1; i <= 5; i++) pages.push(i);
                    pages.push("...");
                    pages.push(total);
                  } else if (current >= total - 3) {
                    pages.push(1);
                    pages.push("...");
                    for (let i = total - 4; i <= total; i++) pages.push(i);
                  } else {
                    pages.push(1);
                    pages.push("...");
                    for (let i = current - 1; i <= current + 1; i++) pages.push(i);
                    pages.push("...");
                    pages.push(total);
                  }
                }

                return pages.map((page, index) => {
                  if (page === "...") {
                    return (
                      <span
                        key={`ellipsis-${index}`}
                        aria-hidden="true"
                        className="px-2 py-1 text-nx-ink-3"
                      >
                        ...
                      </span>
                    );
                  }
                  const pageNum = page as number;
                  const isActive = pageNum === current;
                  return (
                    <Button
                      key={pageNum}
                      // The primary variant already IS the current-page
                      // treatment; the old fill+shadow override fought it.
                      variant={isActive ? "default" : "outline"}
                      size="sm"
                      onClick={() => vm.changePage(pageNum)}
                      aria-current={isActive ? "page" : undefined}
                      className="h-8 w-8 p-0"
                    >
                      {pageNum}
                    </Button>
                  );
                });
              })()}
            </div>

            {/* Next Page */}
            <Button
              variant="outline"
              size="sm"
              onClick={() =>
                vm.changePage(Math.min(vm.pagination.pagesCount, vm.pagination.page + 1))
              }
              disabled={vm.pagination.page === vm.pagination.pagesCount}
              className="h-8 w-8 p-0"
              aria-label={t("table.nextPage")}
            >
              <NextPageIcon className="h-4 w-4" aria-hidden="true" />
            </Button>

            {/* Last Page */}
            <Button
              variant="outline"
              size="sm"
              onClick={() => vm.changePage(vm.pagination.pagesCount)}
              disabled={vm.pagination.page === vm.pagination.pagesCount}
              className="h-8 w-8 p-0"
              aria-label={t("table.lastPage")}
            >
              <LastPageIcon className="h-4 w-4" aria-hidden="true" />
            </Button>
          </div>
        )}
      </div>
    </div>
  ) : undefined;

  return (
    <main className={cn("space-y-4", className)}>
      {/* Same header as every list and record page — the tree is a view of a
          resource, not a different kind of screen. */}
      <PageHeader className="mb-0" title={title} description={subtitle} />

      <TreeView<T>
        data={vm.tree}
        getId={getId}
        getLabel={getLabel}
        getChildren={getChildren}
        search={{
          value: vm.searchValue, // Use immediate display value
          onChange: vm.handleSearchChange, // Use new controlled handler
          placeholder: t("common.search"),
          inputRef: vm.searchInputRef,
        }}
        toolbar={toolbar}
        loading={vm.loading}
        emptyMessage={t("common.noData")}
        actions={
          vm.config.selectable
            ? undefined
            : (n) => {
                const actions = [];
                // Add Child - requires create permission
                if (effectivePermissions.canCreate) {
                  actions.push({
                    label: t("common.add_child"),
                    onClick: () => vm.openAddChild(n),
                    disabled: vm.loading,
                  });
                }
                // Edit - requires update permission
                if (effectivePermissions.canUpdate) {
                  actions.push({
                    label: t("common.edit"),
                    onClick: () => vm.openEdit(n),
                    disabled: vm.loading,
                  });
                }
                // Custom actions (added before Delete)
                if (customActions) {
                  const custom = customActions(n);
                  custom.forEach((action) => {
                    if (action.show && !action.show(n)) return;
                    if (action.requiredPermission && !hasPermission(action.requiredPermission)) {
                      return;
                    }

                    actions.push({
                      label: action.label,
                      onClick: action.onClick,
                      variant: action.variant,
                      icon: action.icon,
                      disabled: action.disabled || vm.loading,
                    });
                  });
                }
                // Delete - requires delete permission (stays at bottom)
                if (effectivePermissions.canDelete) {
                  actions.push({
                    label: t("common.delete"),
                    onClick: () => vm.deleteItem(n),
                    variant: "destructive" as const,
                    disabled: vm.loading,
                  });
                }
                return actions;
              }
        }
        selectable={vm.config.selectable}
        selectedValues={vm.selectedValues}
        onSelectionChange={vm.handleSelectionChange}
        getValueToSend={vm.config.getValueToSend}
        disabled={vm.disabled}
        expandOnCardClick={expandOnCardClick}
      />

      {/* Fixed GenericModal - Only show if not in selectable mode */}
      {!vm.config.selectable && renderFormFields && (
        <GenericModal
          open={vm.modalOpen}
          onOpenChange={(open) => {
            const now = Date.now();
            const timeSinceLastCall = now - lastOnOpenChangeRef.current;

            // Debounce rapid calls (likely from Radix UI internal behavior)
            if (timeSinceLastCall < DEBOUNCE_DELAY) {
              return;
            }

            lastOnOpenChangeRef.current = now;

            // Only handle closing when user explicitly wants to close
            // (ESC key, X button, backdrop click)
            if (!open) {
              vm.setModalOpen(false);
              vm.resetForm();
            }
            // Don't handle opening - let the view model control that
          }}
          title={t(vm.editing ? "crud.modal.editTitle" : "crud.modal.createTitle", {
            entity: vm.config.itemTypeName ?? t("common.item"),
          })}
          description={t(
            vm.editing ? "crud.modal.editDescription" : "crud.modal.createDescription",
            { entity: vm.config.itemTypeName ?? t("common.item") }
          )}
        >
          <GenericForm
            fields={renderFormFields(vm.formValues, vm.setFormValues, vm.editing, vm.parentForNew)}
            initialValues={vm.formValues}
            onSubmit={vm.onSubmit}
            onCancel={() => {
              appLogger.info("Cancel button clicked - resetting form");
              vm.setModalOpen(false);
              vm.resetForm(); // Only reset form on intentional cancel
            }}
          />
        </GenericModal>
      )}

      {/* Enhanced Confirmation Dialog - Only show if not in selectable mode */}
      {!vm.config.selectable && (
        <ConfirmationDialog
          open={vm.showConfirmation}
          onOpenChange={(open) => !open && vm.cancelDelete()}
          title={t("common.confirmDelete")}
          description={`${t("crud.confirm.deleteItem", {
            name: vm.deleteOptions.itemName ?? t("common.item"),
          })} ${t("common.deleteWarning")}`}
          confirmText={vm.isDeleting ? t("common.deleting") : t("common.delete")}
          cancelText={t("common.cancel")}
          variant="destructive"
          isLoading={vm.isDeleting}
          onConfirm={vm.executeDelete}
          onCancel={vm.cancelDelete}
        />
      )}
    </main>
  );
}

// SelectTrigger -- keyboard operability of the whole select family.
//
// WHY THIS FILE USES fireEvent.keyDown AND NOT fireEvent.click.
//
// The trigger is `<PopoverTrigger asChild><div role="combobox" tabIndex={0}>`.
// Radix's PopoverTrigger wires exactly one interaction -- `onClick:
// composeEventHandlers(props.onClick, context.onOpenToggle)` -- and gets
// Enter/Space for free only because it normally renders `Primitive.button`,
// where the BROWSER synthesises a click from those keys. Over a `<div>` there
// is no such synthesis and there was no onKeyDown anywhere in the file, so a
// keyboard-only user could not open a Select, MultiSelect, tree select or
// timezone picker anywhere in the product.
//
// That bug survived because every existing test opened the panel with
// `fireEvent.click` (generic-form.a11y.test.tsx's "still opens the panel"
// case among them). A click-based test passes against a completely
// keyboard-inoperable trigger -- it exercises the one channel Radix DID wire.
// Every open in this file therefore goes through a key event.
import React from "react";
import { render, screen, fireEvent } from "@testing-library/react";
import { describe, it, expect, vi } from "vitest";
import "@testing-library/jest-dom";
import GenericSelect from "../generic-select";

vi.mock("@core/providers/settings-provider", () => ({
  useSettings: () => ({ switchStyle: "default", fontSize: "default", inputStyle: "default" }),
}));

vi.mock("@core/providers/i18n-provider", () => ({
  useI18n: () => ({
    t: (key: string) => key,
    language: "en",
    direction: "ltr",
  }),
}));

// Same jsdom gaps the other GenericSelect suites polyfill: Radix measures the
// trigger with ResizeObserver, cmdk scrolls the highlighted row into view.
if (typeof (globalThis as any).ResizeObserver === "undefined") {
  (globalThis as any).ResizeObserver = class {
    observe() {}
    unobserve() {}
    disconnect() {}
  };
}
if (typeof Element.prototype.scrollIntoView !== "function") {
  Element.prototype.scrollIntoView = () => {};
}

const OPTIONS = [
  { value: "low", label: "Low" },
  { value: "high", label: "High" },
];

function renderSelect(extra: Record<string, unknown> = {}) {
  const onValueChange = vi.fn();
  const utils = render(
    <GenericSelect
      id="priority"
      aria-label="Priority"
      options={OPTIONS}
      value=""
      onValueChange={onValueChange}
      {...extra}
    />
  );
  return { ...utils, onValueChange };
}

describe("SelectTrigger keyboard operability", () => {
  it("is in the tab order", () => {
    renderSelect();
    expect(screen.getByRole("combobox", { name: "Priority" })).toHaveAttribute("tabindex", "0");
  });

  it.each(["Enter", " ", "ArrowDown"])(
    "opens the panel on %s -- via a KEY event, never a synthetic click",
    (key) => {
      renderSelect();
      const trigger = screen.getByRole("combobox", { name: "Priority" });
      expect(trigger).toHaveAttribute("aria-expanded", "false");

      fireEvent.keyDown(trigger, { key });

      expect(trigger).toHaveAttribute("aria-expanded", "true");
      // The real payoff: the options are reachable, not just an attribute flip.
      expect(screen.getByRole("option", { name: "High" })).toBeInTheDocument();
    }
  );

  it("lets a keyboard-only user actually SET a value end to end", () => {
    const { onValueChange } = renderSelect();
    const trigger = screen.getByRole("combobox", { name: "Priority" });

    fireEvent.keyDown(trigger, { key: "Enter" });

    // cmdk owns the panel keymap once the panel is up, and it can only see keys
    // that bubble through its own subtree -- which is exactly why select-panel
    // keeps a focusable (sr-only) CommandInput mounted even for a
    // non-searchable select, and why PopoverContent's FocusScope lands focus on
    // it. Everything from here is arrows + Enter on that input; the pointer is
    // never used.
    // Queried by cmdk's own attribute rather than by accessible name: cmdk puts
    // an `aria-labelledby` of its own on this input alongside select-panel's
    // `aria-label`, and labelledby wins the name computation, so there is no
    // stable name to match on here. Not this component's concern.
    const panelInput = document.querySelector("[cmdk-input]") as HTMLInputElement;
    expect(panelInput).not.toBeNull();
    expect(panelInput).toHaveFocus();

    // cmdk highlights the first row on open; step down to the second.
    fireEvent.keyDown(panelInput, { key: "ArrowDown" });
    fireEvent.keyDown(panelInput, { key: "Enter" });

    expect(onValueChange).toHaveBeenCalledWith("high");
  });

  it("Enter and Space stop the page/form from also acting on the key", () => {
    renderSelect();
    const trigger = screen.getByRole("combobox", { name: "Priority" });

    // Space would scroll the page; Enter would submit a surrounding <form>.
    for (const key of ["Enter", " "]) {
      const event = new KeyboardEvent("keydown", { key, bubbles: true, cancelable: true });
      trigger.dispatchEvent(event);
      expect(event.defaultPrevented).toBe(true);
    }
  });

  it("Enter and Space TOGGLE, so a keyboard user can close the panel again", () => {
    renderSelect();
    const trigger = screen.getByRole("combobox", { name: "Priority" });

    fireEvent.keyDown(trigger, { key: "Enter" });
    expect(trigger).toHaveAttribute("aria-expanded", "true");

    fireEvent.keyDown(trigger, { key: "Enter" });
    expect(trigger).toHaveAttribute("aria-expanded", "false");
  });

  it("ArrowDown only OPENS -- it must not close an open panel out from under cmdk", () => {
    renderSelect();
    const trigger = screen.getByRole("combobox", { name: "Priority" });

    fireEvent.keyDown(trigger, { key: "ArrowDown" });
    expect(trigger).toHaveAttribute("aria-expanded", "true");

    fireEvent.keyDown(trigger, { key: "ArrowDown" });
    expect(trigger).toHaveAttribute("aria-expanded", "true");
  });

  it("ignores keys that are not activation keys, and modifier combinations", () => {
    renderSelect();
    const trigger = screen.getByRole("combobox", { name: "Priority" });

    fireEvent.keyDown(trigger, { key: "a" });
    fireEvent.keyDown(trigger, { key: "Tab" });
    fireEvent.keyDown(trigger, { key: "Enter", ctrlKey: true });
    fireEvent.keyDown(trigger, { key: "ArrowDown", altKey: true });

    expect(trigger).toHaveAttribute("aria-expanded", "false");
  });

  it("stays shut for a disabled select", () => {
    renderSelect({ disabled: true });
    const trigger = screen.getByRole("combobox", { name: "Priority" });

    fireEvent.keyDown(trigger, { key: "Enter" });

    expect(trigger).toHaveAttribute("aria-expanded", "false");
    expect(trigger).toHaveAttribute("tabindex", "-1");
  });

  it("stays shut for a read-only select", () => {
    renderSelect({ readOnly: true });
    const trigger = screen.getByRole("combobox", { name: "Priority" });

    fireEvent.keyDown(trigger, { key: "Enter" });

    expect(trigger).toHaveAttribute("aria-expanded", "false");
  });

  it("does not toggle the panel when the key came from a nested chip control", () => {
    // The nested chip-remove / clear buttons are the reason this element is a
    // <div> and not a <button> at all (a button may not contain a button), so
    // activating one must remove the chip WITHOUT also opening the panel.
    const onValueChange = vi.fn();
    render(
      <GenericSelect
        id="tags"
        aria-label="Tags"
        type="multi"
        options={OPTIONS}
        value={["low"]}
        onValueChange={onValueChange}
      />
    );

    const trigger = screen.getByRole("combobox", { name: "Tags" });
    const remove = screen.getByRole("button", { name: /select.chip.remove/ });

    fireEvent.keyDown(remove, { key: "Enter" });

    expect(trigger).toHaveAttribute("aria-expanded", "false");
  });

  it("still opens on pointer click -- the key handler must not replace that path", () => {
    renderSelect();
    const trigger = screen.getByRole("combobox", { name: "Priority" });

    fireEvent.click(trigger);

    expect(trigger).toHaveAttribute("aria-expanded", "true");
  });

  it("composes a consumer onKeyDown instead of being replaced by it", () => {
    // wrapperProps is spread BEFORE this handler on purpose: a caller that
    // happens to pass onKeyDown must not silently delete the only keyboard
    // route into the control.
    const consumerHandler = vi.fn();
    renderSelect({ onKeyDown: consumerHandler });
    const trigger = screen.getByRole("combobox", { name: "Priority" });

    fireEvent.keyDown(trigger, { key: "Enter" });

    expect(consumerHandler).toHaveBeenCalledTimes(1);
    expect(trigger).toHaveAttribute("aria-expanded", "true");
  });

  it("lets a consumer veto activation by calling preventDefault", () => {
    renderSelect({
      onKeyDown: (event: React.KeyboardEvent) => event.preventDefault(),
    });
    const trigger = screen.getByRole("combobox", { name: "Priority" });

    fireEvent.keyDown(trigger, { key: "Enter" });

    expect(trigger).toHaveAttribute("aria-expanded", "false");
  });
});

// SelectTrigger -- the POINTER half of disabled/read-only enforcement.
//
// WHY THIS FILE RENDERS SelectTrigger DIRECTLY AND NOT GenericSelect.
//
// GenericSelect refuses to open a disabled or read-only select in its own
// `handleOpenChange` (`if (disabled || readOnly) return`). So a test driven
// through GenericSelect passes whether or not the trigger itself enforces
// anything -- it cannot distinguish "the primitive is correct" from "the one
// consumer that happens to remember masks it". This suite therefore mounts the
// trigger inside a bare Popover, which is exactly what a direct consumer does
// (EntityReferenceCustomFieldControl is one), and is the only arrangement in
// which the guard under test is the thing being observed.
//
// What was wrong: `<PopoverTrigger asChild disabled={!interactive}>` over a
// `<div>` is inert. `disabled` on PopoverTrigger is the native attribute, live
// only while Radix renders its default `Primitive.button`; over a div the
// browser ignores it and Radix wires no disabled check into `onOpenToggle`.
// The keyboard path carried an explicit `if (!interactive) return`; the pointer
// path carried nothing, so a click opened a disabled field. Same root cause the
// component's own doc comment already sets out for Enter/Space -- carried only
// half way.
import React from "react";
import { render, screen, fireEvent } from "@testing-library/react";
import { describe, it, expect, vi } from "vitest";
import "@testing-library/jest-dom";
import { Popover, PopoverContent } from "@core/ui/popover";
import { SelectTrigger } from "./select-trigger";

vi.mock("@core/providers/settings-provider", () => ({
  useSettings: () => ({ switchStyle: "default", fontSize: "default", inputStyle: "default" }),
}));

vi.mock("@core/providers/i18n-provider", () => ({
  useI18n: () => ({
    t: (key: string) => key,
    language: "en",
    direction: "ltr",
  }),
}));

// Radix measures the trigger with ResizeObserver -- same jsdom gap the sibling
// keyboard suite polyfills.
if (typeof (globalThis as any).ResizeObserver === "undefined") {
  (globalThis as any).ResizeObserver = class {
    observe() {}
    unobserve() {}
    disconnect() {}
  };
}

const PANEL_TEXT = "the panel body";

/**
 * Mounts the trigger the way a direct consumer does: a controlled Popover whose
 * open state the test can observe, with a body distinctive enough to assert on.
 */
function renderTrigger(props: Partial<React.ComponentProps<typeof SelectTrigger>> = {}) {
  const onOpenChange = vi.fn();

  function Harness() {
    const [open, setOpen] = React.useState(false);
    return (
      <Popover
        open={open}
        onOpenChange={(next) => {
          onOpenChange(next);
          setOpen(next);
        }}
      >
        <SelectTrigger
          id="target"
          open={open}
          multi={false}
          ariaLabel="Target record"
          placeholder="Select a record"
          selectedOptions={[]}
          displayLabel=""
          maxSelectedDisplay={3}
          allowClear={false}
          onClear={() => {}}
          onRemoveOne={() => {}}
          {...props}
        />
        <PopoverContent>{PANEL_TEXT}</PopoverContent>
      </Popover>
    );
  }

  render(<Harness />);
  return { onOpenChange };
}

const click = () => fireEvent.click(screen.getByRole("combobox"));

describe("SelectTrigger pointer enforcement", () => {
  it("opens on a pointer click when the field is interactive", () => {
    // The control case, and it is load-bearing: without it, the two assertions
    // below would also pass against a trigger that never opens at all.
    const { onOpenChange } = renderTrigger();

    click();

    expect(onOpenChange).toHaveBeenCalledWith(true);
    expect(screen.getByText(PANEL_TEXT)).toBeInTheDocument();
  });

  it("does not open a disabled field on a pointer click", () => {
    const { onOpenChange } = renderTrigger({ disabled: true });

    click();

    expect(onOpenChange).not.toHaveBeenCalled();
    expect(screen.queryByText(PANEL_TEXT)).not.toBeInTheDocument();
  });

  it("does not open a read-only field on a pointer click", () => {
    // read-only is the likelier of the two in practice: a view-mode form renders
    // its selects read-only rather than disabled, so before this guard every
    // view-mode select in the product opened a working picker on click.
    const { onOpenChange } = renderTrigger({ readOnly: true });

    click();

    expect(onOpenChange).not.toHaveBeenCalled();
    expect(screen.queryByText(PANEL_TEXT)).not.toBeInTheDocument();
  });

  it("keeps the keyboard path refused too, so neither channel is the loose one", () => {
    // Asserted here rather than trusted from the sibling suite, because the fix
    // for the pointer path touches the same element's props and could plausibly
    // have shadowed onKeyDown.
    const { onOpenChange } = renderTrigger({ disabled: true });

    fireEvent.keyDown(screen.getByRole("combobox"), { key: "Enter" });

    expect(onOpenChange).not.toHaveBeenCalled();
  });

  it("still runs a consumer's own click handler on an inert field", () => {
    // Deliberate, and symmetric with the keyboard path, which also calls the
    // consumer handler before bailing. A consumer that wants to ignore clicks on
    // its own disabled field checks its own state; what it must NOT be able to do
    // is replace this guard by passing onClick through wrapperProps.
    const consumerClick = vi.fn();
    const { onOpenChange } = renderTrigger({
      disabled: true,
      wrapperProps: { onClick: consumerClick },
    });

    click();

    expect(consumerClick).toHaveBeenCalledTimes(1);
    expect(onOpenChange).not.toHaveBeenCalled();
  });

  it("does not suppress the open when a consumer handler is present and the field is live", () => {
    // The guard reads `!interactive`, not "a consumer handler ran". Passing
    // wrapperProps.onClick must not turn a working select into a dead one.
    const consumerClick = vi.fn();
    const { onOpenChange } = renderTrigger({ wrapperProps: { onClick: consumerClick } });

    click();

    expect(consumerClick).toHaveBeenCalledTimes(1);
    expect(onOpenChange).toHaveBeenCalledWith(true);
  });
});

"use client";

import * as React from "react";
import { ChevronDown, X } from "lucide-react";
import { cn } from "@core/common/utils";
import { useI18n } from "@core/providers/i18n-provider";
import { useSettings } from "@core/providers/settings-provider";
import { fieldVariants, resolveFieldStyle } from "@core/ui/input";
import { PopoverTrigger, Popover, PopoverContent } from "@core/ui/popover";
import { Badge } from "@core/ui/badge";
import type { GenericSelectOption } from "../generic-select";

export interface SelectTriggerProps {
  id?: string;
  name?: string;
  open: boolean;
  multi: boolean;
  disabled?: boolean;
  readOnly?: boolean;
  invalid?: boolean;
  required?: boolean;
  describedBy?: string;
  /** Accessible name for this element — see `GenericSelectProps["aria-label"]`'s doc comment. */
  ariaLabel?: string;
  /** Accessible name via reference — see `GenericSelectProps["aria-labelledby"]`'s doc comment. */
  ariaLabelledBy?: string;
  placeholder: string;
  selectedOptions: GenericSelectOption[];
  /** Full label for the single-selected option, including any tree path. */
  displayLabel: string;
  maxSelectedDisplay: number;
  allowClear: boolean;
  onClear: () => void;
  onRemoveOne: (option: GenericSelectOption) => void;
  className?: string;
  /**
   * Anything else the caller put on GenericSelect — data-*, testids and the
   * like. Passed as one object rather than an index signature, which would
   * widen every declared prop above to `unknown`.
   */
  wrapperProps?: React.HTMLAttributes<HTMLDivElement>;
}

/**
 * The field half of the select.
 *
 * It wears the SAME surface as Input and Textarea — `fieldVariants` from
 * input.tsx — so the workspace `inputStyle` setting applies to it. Previously
 * GenericSelect hand-rolled its own trigger chrome, so switching the workspace
 * to `underlined` turned every Input into a bottom rule while every
 * GenericSelect stayed a box, on the same form.
 *
 * THE WHOLE FIELD is the combobox, not a button nested inside it. That matters
 * for three reasons, each of which was a real defect when the button was inner:
 *   1. Radix anchors the panel to the trigger, so a narrow inner button made
 *      the panel detach from the field — and in a multi-select full of chips it
 *      shrank toward zero width and floated mid-field, on opposite sides in the
 *      two writing directions.
 *   2. Clicking the chevron, the padding, or the whitespace between chips did
 *      nothing, because only the inner button opened the panel.
 *   3. The accessible name of a `<button>` is its text content — and a
 *      multi-select's content lived in the sibling chips, so a populated
 *      multi-select announced itself with no name at all. Moving to a
 *      `<div role="combobox">` did NOT fix this by itself: per ARIA,
 *      role="combobox" is Name From: author, not Name From: contents, so a
 *      nameless `<button>` just became a nameless `<div>`. What actually
 *      closes it is the `ariaLabel`/`ariaLabelledBy` props below, applied
 *      to this same element as real `aria-label`/`aria-labelledby`
 *      attributes (Wave 2 Step 2.2's Task 7b a11y fix) -- see those props'
 *      own doc comments and `GenericSelectProps["aria-label"]`'s for the
 *      full mechanism.
 *
 * It is a `div`, not a `button`, because the chips carry their own remove
 * controls and a button may not contain a button.
 *
 * WHICH IS WHY THE `onKeyDown` BELOW IS LOAD-BEARING, not a nicety. Radix's
 * `PopoverTrigger` wires exactly one interaction — `onClick:
 * composeEventHandlers(props.onClick, context.onOpenToggle)` (verified against
 * @radix-ui/react-popover's dist: there is no `onKeyDown` anywhere in that
 * component). Radix gets Enter/Space for free ONLY because it renders
 * `Primitive.button` by default: the browser synthesises a click from those two
 * keys for a real `<button>`. `asChild` over a `<div>` throws that away, and
 * nothing else in this file supplied it — so before this handler existed a
 * keyboard-only user could not open a Select, MultiSelect, tree select or
 * timezone picker ANYWHERE in the product. Every value in the select family was
 * pointer-only.
 *
 * The durable fix would be to render a real `<button type="button">` and let
 * the platform do it. That form is NOT available here: the three nested
 * controls below — each chip's remove button, the "+N" overflow button (itself
 * a `PopoverTrigger` for a second Popover) and the clear button — are
 * interactive content, which a `<button>` may not contain. Nesting them would
 * be invalid HTML with real consequences (browsers do not reliably hit-test a
 * button inside a button, and the inner controls would inherit the outer
 * button's implicit submit/activation behaviour), and it is the reason this
 * element is a `div` in the first place. So the keys are re-implemented instead.
 */
export const SelectTrigger = React.forwardRef<HTMLDivElement, SelectTriggerProps>(
  (
    {
      id,
      name,
      open,
      multi,
      disabled,
      readOnly,
      invalid,
      required,
      describedBy,
      ariaLabel,
      ariaLabelledBy,
      placeholder,
      selectedOptions,
      displayLabel,
      maxSelectedDisplay,
      allowClear,
      onClear,
      onRemoveOne,
      className,
      wrapperProps,
    },
    ref
  ) => {
    const { t } = useI18n();
    const settings = useSettings();
    const [overflowOpen, setOverflowOpen] = React.useState(false);

    const visibleChips = multi ? selectedOptions.slice(0, maxSelectedDisplay) : [];
    const overflowChips = multi ? selectedOptions.slice(maxSelectedDisplay) : [];
    const hasSelection = selectedOptions.length > 0;
    const interactive = !disabled && !readOnly;

    const removeButtonClasses =
      // 24px hit area on a 12px glyph; the negative margins buy it without
      // widening the chip.
      "-my-1 -me-1 inline-flex h-6 w-6 shrink-0 items-center justify-center rounded-full text-nx-ink-3 transition-colors duration-nx-micro ease-nx-enter hover:bg-nx-hover hover:text-nx-ink focus-visible:shadow-nx-focus focus-visible:outline-none motion-reduce:transition-none";

    return (
      <PopoverTrigger asChild disabled={!interactive}>
        <div
          ref={ref}
          id={id}
          data-name={name}
          role="combobox"
          // Radix supplies aria-expanded and aria-controls (pointing at the
          // panel it actually renders). Only the popup TYPE is overridden —
          // Radix says "dialog", and this one is a listbox.
          aria-haspopup="listbox"
          aria-invalid={invalid || undefined}
          aria-required={required || undefined}
          aria-describedby={describedBy}
          aria-disabled={disabled || undefined}
          aria-readonly={readOnly || undefined}
          // role="combobox" is Name From: author, not Name From: contents --
          // the visible chips/placeholder text below are NOT enough on their
          // own to give this element an accessible name (a prior version of
          // this comment claimed otherwise; verified wrong against real
          // testing-library/AT behavior during Wave 2 Step 2.2's Task 4/7b
          // a11y fix). `aria-labelledby` wins over `aria-label` per the
          // standard accessible-name computation order when a caller
          // supplies both.
          aria-label={ariaLabel}
          aria-labelledby={ariaLabelledBy}
          tabIndex={interactive ? 0 : -1}
          className={cn(
            fieldVariants({ inputStyle: resolveFieldStyle(settings.inputStyle) }),
            "flex min-h-10 w-full flex-wrap items-center gap-1 px-3 py-1.5 text-sm",
            interactive ? "cursor-pointer" : "cursor-default",
            // while its list is up the field stays the active thing
            open && "border-nx-accent shadow-nx-focus",
            // READ_ONLY_FIELD is written with `read-only:enabled:` selectors,
            // which only ever match a form-associated element — on a div the
            // whole string is inert, so the treatment is spelled out here.
            readOnly && "bg-transparent hover:border-nx-line",
            disabled && "border-nx-line bg-nx-raised text-nx-ink-3 shadow-none",
            className
          )}
          {...wrapperProps}
          // Blocks the POINTER path when the field is disabled or read-only.
          //
          // `<PopoverTrigger asChild disabled={!interactive}>` above looks like
          // it already does this, and does not. `disabled` on PopoverTrigger is
          // the NATIVE attribute, meaningful only while Radix renders its
          // default `Primitive.button`; over this `div` it lands as a
          // non-standard DOM attribute the browser ignores, and Radix wires no
          // disabled check of its own into `onOpenToggle`. This is the exact
          // root cause the doc comment above describes for Enter/Space -- and
          // the keyboard half was guarded (`if (!interactive) return`) while the
          // pointer half was not, so a disabled or read-only select opened on
          // click.
          //
          // Nothing shipped was visibly broken, because GenericSelect masks it
          // in its own `handleOpenChange` (`if (disabled || readOnly) return`).
          // That mask is the problem: it makes correctness a thing each
          // consumer must remember, and SelectTrigger is imported directly
          // outside GenericSelect now. Fixed here so the primitive is right and
          // a consumer's own guard is redundant belt-and-braces rather than the
          // only thing standing between a read-only field and an open picker.
          //
          // preventDefault is what suppresses the open, not a return: Radix's
          // trigger is `onClick: composeEventHandlers(props.onClick,
          // context.onOpenToggle)`, and composeEventHandlers skips its second
          // handler once the event is defaultPrevented. Slot runs this child
          // handler before the trigger's own, so the veto lands in time.
          //
          // Placed AFTER {...wrapperProps} and calling the consumer's handler
          // explicitly -- identical discipline to the onKeyDown below, for the
          // same reason: a caller passing onClick for its own purposes must not
          // be able to silently delete this guard. The consumer handler still
          // runs first even when inert, exactly as the keyboard path already
          // does, so the two paths stay symmetric.
          onClick={(event) => {
            wrapperProps?.onClick?.(event);
            if (!interactive) event.preventDefault();
          }}
          // Enter / Space / ArrowDown open the panel — see the "load-bearing"
          // paragraph in this component's doc comment for why the platform does
          // not supply them here.
          //
          // It dispatches a real click rather than calling an open callback so
          // that the ONE toggle path stays Radix's own composed `onClick`: the
          // Popover context's `onOpenToggle`, plus any consumer `onClick`
          // arriving through `wrapperProps`. A parallel "open" channel would
          // drift from the pointer path the first time either side changed.
          //
          // Deliberately placed AFTER {...wrapperProps} — same discipline as
          // dialog.tsx's `onFocusOutside`. A consumer handler still runs (it is
          // composed first, and can veto by calling preventDefault), but a
          // caller who happens to pass `onKeyDown` for its own reasons cannot
          // silently delete the only way to open this control by keyboard.
          //
          // The `event.target !== event.currentTarget` guard keeps the handler
          // off the nested chip-remove / "+N" / clear buttons. Those already
          // stop keydown propagation individually, but this makes the trigger
          // itself the only source, so a future nested control cannot start
          // toggling the panel when someone activates it.
          onKeyDown={(event) => {
            wrapperProps?.onKeyDown?.(event);
            if (!interactive) return;
            if (event.target !== event.currentTarget) return;
            if (event.defaultPrevented) return;
            if (event.altKey || event.ctrlKey || event.metaKey) return;

            const key = event.key;
            if (key !== "Enter" && key !== " " && key !== "ArrowDown") return;
            // ArrowDown is "open", not "toggle" — once the panel is up, cmdk
            // owns the arrows for moving through the options.
            if (key === "ArrowDown" && open) return;

            // Space would scroll the page and Enter would submit a surrounding
            // form; both belong to the combobox while it has focus.
            event.preventDefault();
            event.currentTarget.click();
          }}
        >
          {visibleChips.map((option) => (
            <Badge
              key={option.uniqueKey ?? option.value}
              variant="secondary"
              className="max-w-[12rem] gap-1 pe-1 ps-2"
            >
              <span className="truncate" title={option.label}>
                {option.label}
              </span>
              {interactive && (
                <button
                  type="button"
                  aria-label={t("select.chip.remove", { label: option.label })}
                  className={removeButtonClasses}
                  onClick={(event) => {
                    // Removing a chip must not also toggle the panel.
                    event.stopPropagation();
                    onRemoveOne(option);
                  }}
                  onKeyDown={(event) => event.stopPropagation()}
                >
                  <X className="h-3 w-3" aria-hidden="true" />
                </button>
              )}
            </Badge>
          ))}

          {overflowChips.length > 0 && (
            // "+N" opens the rest, each still individually removable. The old
            // build replaced ALL chips with a plain "N Selected" span past the
            // third selection, which silently removed the only way to deselect
            // one item without clearing everything.
            <Popover open={overflowOpen} onOpenChange={setOverflowOpen}>
              <PopoverTrigger asChild>
                <button
                  type="button"
                  className="rounded-nx-sm focus-visible:shadow-nx-focus focus-visible:outline-none"
                  aria-label={t("components.multiSelect.moreSelected", {
                    count: overflowChips.length,
                  })}
                  onClick={(event) => event.stopPropagation()}
                  onKeyDown={(event) => event.stopPropagation()}
                >
                  <Badge variant="secondary">+{overflowChips.length}</Badge>
                </button>
              </PopoverTrigger>
              <PopoverContent align="start" className="w-56 space-y-1 p-2">
                {overflowChips.map((option) => (
                  <div
                    key={option.uniqueKey ?? option.value}
                    className="flex items-center justify-between gap-2 rounded-nx-sm px-2 py-1 text-sm"
                  >
                    <span className="truncate" title={option.label}>
                      {option.label}
                    </span>
                    {interactive && (
                      <button
                        type="button"
                        aria-label={t("select.chip.remove", { label: option.label })}
                        className={removeButtonClasses}
                        onClick={() => onRemoveOne(option)}
                      >
                        <X className="h-3 w-3" aria-hidden="true" />
                      </button>
                    )}
                  </div>
                ))}
              </PopoverContent>
            </Popover>
          )}

          {/* Single-select shows its value here; multi-select shows the
              placeholder only while nothing is chosen, because the chips above
              already carry the value. */}
          {(!multi || !hasSelection) && (
            <span
              className={cn(
                "flex min-w-0 flex-1 items-center gap-2 truncate",
                hasSelection && !multi && displayLabel ? "text-nx-ink" : "text-nx-ink-3"
              )}
              title={!multi && hasSelection && displayLabel ? displayLabel : undefined}
            >
              {!multi && hasSelection && displayLabel && selectedOptions[0]?.icon && (
                <span className="shrink-0">{selectedOptions[0].icon}</span>
              )}
              <span className="min-w-0 truncate">
                {multi ? placeholder : displayLabel || placeholder}
              </span>
            </span>
          )}

          <div className="ms-auto flex shrink-0 items-center gap-1">
            {allowClear && interactive && hasSelection && (
              <button
                type="button"
                aria-label={t("common.clearSelection")}
                onClick={(event) => {
                  event.stopPropagation();
                  onClear();
                }}
                onKeyDown={(event) => event.stopPropagation()}
                className={cn(removeButtonClasses, "h-5 w-5")}
              >
                <X className="h-3 w-3" aria-hidden="true" />
              </button>
            )}
            {!readOnly && (
              <ChevronDown
                aria-hidden="true"
                className={cn(
                  "h-4 w-4 shrink-0 text-nx-ink-3 transition-transform duration-nx-micro ease-nx-enter motion-reduce:transition-none",
                  open && "rotate-180"
                )}
              />
            )}
          </div>
        </div>
      </PopoverTrigger>
    );
  }
);

SelectTrigger.displayName = "SelectTrigger";

/**
 * Core-owned extension point for the CustomFields module. `src/core` does
 * import from `src/modules/*` in places today — permission constants in
 * common/types/permissions.ts, locale registration in
 * locales/module-registry.ts, component re-exports in auth/index.ts — but none
 * of those is a hook reaching into a feature module's data layer from a
 * universally-shared UI component the way GenericCrudView would need to.
 * This typed extension point keeps that specific, higher-risk boundary clean
 * rather than adding another ad-hoc case: core defines the contract; the
 * CustomFields module implements it and self-registers via one side-effect
 * import wired into src/app/layout.tsx (see the CustomFields module's
 * bootstrap.ts, Task 3) — the single composition root, not core and not a
 * peer module.
 */
"use client";

import type { Column } from "@core/crud/components/generic-table";
import type { FieldConfig } from "@core/ui/forms/generic-form";
import { useI18n } from "@core/providers/i18n-provider";
import { useCallback, useEffect, useMemo, useState } from "react";
import {
  MaskedCustomFieldCell,
  type MaskedCustomFieldCellProps,
} from "./components/MaskedCustomFieldCell";

/**
 * Custom validation error thrown when a custom field value violates validation constraints.
 * Allows save workflows to distinguish validation errors from API failure states.
 */
export class CustomFieldValidationError extends Error {}

/**
 * Mirrors CustomFields.Domain.Enums.CustomFieldValueType's wire names (the
 * API's global JsonStringEnumConverter serializes every enum as its member
 * name, never its numeric ordinal — see the CustomFields module's own
 * CustomFieldValueModel.ts, which this duplicates rather than imports, for
 * the same "core never imports from modules" reason FieldConfig[] is the
 * boundary type for getFormFields below). Wave 3.1 Task 10 added
 * LongText/DateTime/MultiSelect to both declarations of this union in
 * lockstep — this file's own header comment documents why there are exactly
 * two, not one. Wave 3.2 Batch 3 adds Email/Url/Phone/Percent/Rating the
 * same way (verified against the real backend enum: Email=8, Url=9,
 * Phone=10, Percent=11, Rating=12). Wave 3.3 Batch C adds
 * Currency/Duration/Time/Color the same way (Currency=13, Duration=14,
 * Time=15, Color=16). Wave 4 adds EntityReference=17/UserReference=18 the
 * same way, read off the real backend enum. Wave 3.4 adds
 * File=19/Image=20/RichText=21, likewise. That lockstep is not optional
 * here: `BulkColumnValuesResult.columns` is typed against THIS union while
 * the module's `getBulkColumnValues` returns columns typed against ITS
 * union, so a member present there and missing here is an outright build
 * error, not a silently narrower type.
 *
 * The build error is worth naming, because it is the whole safety mechanism and
 * it reads as unrelated when you hit it: adding a member to the module's union
 * alone fails at
 * `customFieldsCrudIntegration.tsx`'s `getBulkColumnValues` return with
 * "Type 'CustomFieldColumnData[]' is not assignable to
 * 'CustomFieldColumnDefinition[]'". That is this union being narrower, not a
 * data-layer fault, and the fix is here.
 */
export type CustomFieldValueTypeName =
  | "Text"
  | "Number"
  | "Boolean"
  | "Date"
  | "Select"
  | "LongText"
  | "DateTime"
  | "MultiSelect"
  | "Email"
  | "Url"
  | "Phone"
  | "Percent"
  | "Rating"
  | "Currency"
  | "Duration"
  | "Time"
  | "Color"
  | "EntityReference"
  | "UserReference"
  | "File"
  | "Image"
  | "RichText";

/**
 * One active custom-field definition shaped as a table-column header — thinner
 * than a form field: no isRequired, no per-row value, since those don't vary
 * per column, only per cell (see valuesByOwnerId below).
 */
export interface CustomFieldColumnDefinition {
  key: string;
  labelEn: string;
  labelAr: string | null;
  valueType: CustomFieldValueTypeName;
  options: string[] | null;
  sortOrder: number;
  sensitivity?: number;
}

export interface BulkColumnValuesResult {
  columns: CustomFieldColumnDefinition[];
  /** Keyed by the exact (encrypted) owner id string the caller requested, then by each column's `key`. An id the server couldn't verify is simply absent — render that row's cells empty, not an error. */
  valuesByOwnerId: Record<string, Record<string, unknown>>;
  /**
   * Wave 5 row 5.3. Per owner, the field keys a visibility rule hides for THAT record.
   *
   * A parallel channel, because visibility varies per ROW while a column exists once per result set —
   * so this can never be expressed by dropping a column, and expressing it as a missing key inside
   * `valuesByOwnerId` would overload an absence that already means two other things.
   *
   * Optional: a server predating row 5.3 omits it, and the server has already nulled the value
   * regardless, so a client ignoring this renders an empty cell — correct, just without knowing why.
   */
  hiddenKeysByOwnerId?: Record<string, string[]> | null;
}

/**
 * Everything a host form hands a custom-field control that `core` itself
 * cannot draw. Consumed by `CustomFieldsExtensionApi.FieldControl` below.
 *
 * WHY THIS SHAPE, AND WHY NOTHING MORE. The five props are exactly the facts
 * the host owns and the control cannot derive:
 *   - `field` carries everything definition-shaped (name/label/placeholder/
 *     required/options/`referenceTargetEntityTypeKey`). It is passed whole
 *     rather than as unpacked scalars precisely so the NEXT type admitted here
 *     needs no new prop: a type whose control reads `options` or `min`/`max`
 *     already has them.
 *   - `value` + `onChange` are the controlled-input contract, `unknown` in both
 *     directions because the whole point of this member is types whose form
 *     value is not a scalar. The host merges the reported value into its own
 *     form state; it never interprets it.
 *   - `invalid` / `describedBy` / `disabled` are the three host-owned facts a
 *     control cannot see for itself: whether the host's own validation pass
 *     rejected this field, which node the host rendered the hint or error into,
 *     and whether the whole form is read-only. Without them the control cannot
 *     honour the same `aria-invalid`/`aria-describedby` contract the host's own
 *     branches provide, which is the difference between an accessible field and
 *     one that merely looks right.
 *
 * Deliberately ABSENT: `required` (already on `field`), `id`/`label`/
 * `placeholder` (already on `field`), and anything reference-specific. A member
 * only one value type can ever use would have to be replaced the first time a
 * second object-valued type needs drawing; this one just gets a second arm in
 * the implementation's own dispatch.
 */
export interface CustomFieldFormControlProps {
  /** The already-namespaced FieldConfig this extension itself produced (see getFormFields). */
  field: FieldConfig;
  /** Current form value for `field.name`, exactly as the host holds it — never coerced on the way in. */
  value: unknown;
  /** Report a new value. The host merges it into its own form state verbatim. */
  onChange: (next: unknown) => void;
  /** The host's read-only/disabled state for this field (a view dialog, or `field.disabled`). */
  disabled?: boolean;
  /** True when the host's own validation pass rejected this field — drives `aria-invalid`. */
  invalid?: boolean;
  /** Id of the hint or error node the host renders below the control, for `aria-describedby`. */
  describedBy?: string;
  /** Validation error message for the field when invalid. */
  error?: string;
}

export interface CustomFieldsExtensionApi {
  /** Active definitions for entityTypeKey, merged with ownerId's stored values when given, mapped to already-namespaced FieldConfig[]. */
  getFormFields: (entityTypeKey: string, ownerId?: string) => Promise<FieldConfig[]>;
  /** Full-replace save of one owner record's custom-field values, keyed by the plain (decoded) custom-field key. */
  saveValues: (
    entityTypeKey: string,
    ownerId: string,
    valuesByCustomFieldKey: Record<string, unknown>
  ) => Promise<void>;
  /**
   * Active definitions for entityTypeKey (as table columns) plus every
   * requested owner's stored values, in one round trip — backs a table's
   * dynamic custom-field columns for a page of rows instead of fetching per
   * row. `ownerIds` is capped at 100 server-side (mirrors the page-size cap
   * GenericTable's own pagination already offers, so a single page can never
   * legitimately exceed it).
   */
  getBulkColumnValues: (entityTypeKey: string, ownerIds: string[]) => Promise<BulkColumnValuesResult>;
  /** Decrypts and reveals a sensitive custom field value for an authorized user. */
  revealValue?: (
    entityTypeKey: string,
    ownerId: string,
    fieldKey: string
  ) => Promise<unknown>;
  /**
   * Self-contained trigger + dialog; internally gates on the custom-fields.create
   * permission via its own usePermission call. `entityDisplayName` is the host
   * screen's already-translated title (e.g. "Party People") shown in the dialog
   * in place of the raw entityTypeKey ("party.person") — optional so a caller
   * with no ready display name (or a test) still gets a working dialog.
   */
  InlineAddTrigger: React.ComponentType<{
    entityTypeKey: string;
    entityDisplayName?: string;
    onCreated: () => void;
  }>;
  /**
   * Draws the whole field — label, control, and any hint the control owns — for
   * one FieldConfig whose `type` `core` declares for typing but cannot render
   * itself. The EDIT-side counterpart of `formatValueForDisplay` below, and the
   * component-valued sibling of `InlineAddTrigger` above.
   *
   * WHY THIS MEMBER EXISTS AT ALL. `getFormFields` hands `core` a
   * `FieldConfig[]` that GenericCrudView concatenates straight into
   * `<GenericForm fields={...}>`, so those fields genuinely reach GenericForm's
   * render switch — and a type with no arm there fell through to the plain
   * `<Input type={field.type} value={formData[field.name] ?? ""}>` default.
   * For an object-valued type that renders as `[object Object]` in a text box
   * the operator can type over, replacing the object with a string the server
   * refuses. That is 30 CrudConfig sites declaring `entityTypeKey:` against 8
   * that call the module's own dispatcher directly.
   *
   * The fix could NOT be an import: the control needs the CustomFields module
   * (its entity-lookup hooks reach that module's DI container) and `core` must
   * not import from `src/modules/*` — docs/architecture/01-modularity.md's
   * Dependency Rule, the same constraint that makes this whole file a registry.
   * A direct import would additionally close a runtime cycle (generic-form →
   * control → module DI → valueTypeRegistry → generic-form) and pull the entire
   * CustomFields data layer into every form in the product. So the control
   * arrives the way every other module capability here does: core states the
   * contract, the module registers the implementation.
   *
   * Deliberately OPTIONAL, for exactly the reason `formatValueForDisplay`
   * below is: making it required would force every hand-built
   * `CustomFieldsExtensionApi` test double across this codebase's other suites
   * (leads/webhooks/dsr/templates/generic-crud-view) to add a throwaway
   * component just to keep compiling. What must NOT happen when it is absent is
   * the silent text-box fallthrough — GenericForm renders an explicit, inert,
   * explanatory field instead. See `CustomFieldExtensionControl` in
   * generic-form.tsx.
   */
  FieldControl?: React.ComponentType<CustomFieldFormControlProps>;
  /**
   * Read-side per-type cell formatter for buildCustomFieldColumn's dynamic
   * table columns below — the read counterpart of getFormFields (which
   * produces the EDIT-side FieldConfig per type). Wave 2 Step 2.2 Task 5:
   * moves buildCustomFieldColumn's own inline Number/Boolean/Date/
   * Text-and-Select-fallthrough switch out of `core` and into the
   * CustomFields module (formatCustomFieldValue.tsx), the same
   * "core defines the contract, the module implements it" shape already used
   * for every other member of this interface, rather than adding a second,
   * differently-keyed dispatch table that lives directly in `core`.
   *
   * Deliberately OPTIONAL, unlike the members above: making it required would
   * force every hand-built `CustomFieldsExtensionApi` test double across this
   * codebase's other suites (leads/webhooks/dsr/templates/generic-crud-view,
   * none of which render a Number/Boolean/Date custom-field column today) to
   * add a throwaway implementation just to keep compiling — churn with no
   * connection to this task. buildCustomFieldColumn falls back to a plain
   * `String(raw)` when this is absent, matching this switch's own pre-Task-5
   * Text/Select default branch; the one real implementation
   * (customFieldsCrudIntegration.tsx) always supplies it, so that fallback is
   * only ever exercised by a test double that doesn't care about formatting.
   */
  formatValueForDisplay?: (
    valueType: CustomFieldValueTypeName,
    value: unknown,
    language: string,
    t: (key: string, params?: Record<string, string | number>) => string
  ) => React.ReactNode;
  /**
   * Reusable section component for rendering custom fields inside any host form
   * (e.g. Webhook Form, Lead Form, Template Form, Theme Modal, etc.).
   */
  Section?: React.ComponentType<CustomFieldsSectionProps>;
  /**
   * Lists the custom-field keys an admin could restrict for one permission resource.
   */
  useRestrictableCustomFieldKeys?: UseRestrictableCustomFieldKeysHook;
}

export interface RestrictableCustomFieldKey {
  key: string;
  labelEn: string;
  isRequired: boolean;
}

export interface UseRestrictableCustomFieldKeysArgs {
  enabled?: boolean;
}

export interface UseRestrictableCustomFieldKeysResult {
  keys: RestrictableCustomFieldKey[];
  isLoading: boolean;
  isError: boolean;
  isTruncated: boolean;
  isAvailable: boolean;
}

export type UseRestrictableCustomFieldKeysHook = (
  permissionResource: string | undefined,
  args?: UseRestrictableCustomFieldKeysArgs
) => UseRestrictableCustomFieldKeysResult;

export interface CustomFieldsSectionProps {
  /** The field configuration schemas (from useEntityCustomFields or ViewModel). */
  configs: readonly FieldConfig[];
  /** Current custom field values dictionary. */
  values: Record<string, unknown>;
  /** Callback fired whenever any custom field value changes. */
  onChange: (key: string, value: unknown) => void;
  /** Whether custom field definitions are currently loading. */
  isLoading?: boolean;
  /** Message displayed when no custom fields are defined for this entity type. */
  emptyMessage?: string;
  /** Entity type key (e.g. 'integrations.webhook-subscription') for inline creation. */
  entityTypeKey?: string;
  /** Localized entity display name for the inline creation modal title. */
  entityDisplayName?: string;
  /** Callback to refetch custom fields when an inline field is created. */
  onFieldCreated?: () => void;
  /** Whether the controls are in read-only / view mode. */
  isViewMode?: boolean;
  /** Optional validation errors dictionary keyed by field name. */
  errors?: Record<string, string>;
  /** Whether the parent form or step has been touched. */
  touched?: boolean;
  /** Optional container CSS class name. */
  className?: string;
}

let registeredApi: CustomFieldsExtensionApi | null = null;

export function registerCustomFieldsExtension(api: CustomFieldsExtensionApi): void {
  registeredApi = api;
}

export function getCustomFieldsExtension(): CustomFieldsExtensionApi | null {
  return registeredApi;
}

/**
 * Every FieldConfig this extension contributes to a form is named with this
 * prefix so GenericCrudView can split a submitted form's data back into
 * "real entity fields" vs "custom-field values" without guessing. Never
 * construct this prefix inline elsewhere — always go through these two
 * functions so the encoding has exactly one definition.
 */
const CUSTOM_FIELD_NAME_PREFIX = "__cf__";

export function encodeCustomFieldName(key: string): string {
  return `${CUSTOM_FIELD_NAME_PREFIX}${key}`;
}

export function decodeCustomFieldName(name: string): string | null {
  return name.startsWith(CUSTOM_FIELD_NAME_PREFIX) ? name.slice(CUSTOM_FIELD_NAME_PREFIX.length) : null;
}

/**
 * Always calls the same primitive hooks (useState/useEffect/useCallback)
 * regardless of registration state — it only ever delegates to PLAIN ASYNC
 * FUNCTIONS on the registered extension (getFormFields), never to another
 * hook, so Rules of Hooks holds even if this fires before the CustomFields
 * module's bootstrap import has run (in which case it just returns empty).
 *
 * KNOWN INEFFICIENCY (design doc recon finding #5, verified and deliberately
 * deferred to Wave 2): GenericCrudView mounts up to THREE independent
 * instances of this hook for the same entityTypeKey (create/edit/view), each
 * with its own useState/useEffect and no cache between them. create's
 * instance calls getFormFields(key, undefined) -> getDefinitions(key); edit
 * and view's instances call getFormFields(key, ownerId) -> getValues(key,
 * ownerId) -- a different endpoint, so this is NOT three identical requests,
 * but all three independently carry overlapping definition metadata (label,
 * placeholder, options, valueType, required) with no sharing. The correct
 * fix is a shared cache, which belongs in Wave 2 once the IValueTypeHandler
 * registry (design doc §8) restructures this contract anyway --
 * building a cache against the current shape now would likely be thrown
 * away. customFieldsExtension.fetchCount.test.tsx pins today's call count so
 * Wave 2 has a concrete before/after baseline.
 */
export function useCustomFieldsFormFields(
  entityTypeKey: string | undefined,
  ownerId: string | undefined
): {
  fieldConfigs: FieldConfig[];
  isLoading: boolean;
  error: Error | null;
  refetch: () => Promise<void>;
} {
  const [fieldConfigs, setFieldConfigs] = useState<FieldConfig[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  // getFormFields rejects for real reasons a user can hit — a 403 from a
  // screen the caller lacks the custom-fields view permission on, a network
  // drop mid-modal. Without this the rejection escaped `fetchFields` as an
  // unhandled promise (both call sites are fire-and-forget) and the section
  // just stayed empty with nothing to explain why. Captured here the same way
  // useEntityCustomFields already does it; surfacing it in the UI is a
  // follow-up, but it is no longer swallowed.
  const [error, setError] = useState<Error | null>(null);

  const fetchFields = useCallback(async () => {
    const api = getCustomFieldsExtension();
    if (!entityTypeKey || !api) {
      setFieldConfigs([]);
      setIsLoading(false);
      setError(null);
      return;
    }
    setIsLoading(true);
    setError(null);
    try {
      setFieldConfigs(await api.getFormFields(entityTypeKey, ownerId));
    } catch (err) {
      setError(err instanceof Error ? err : new Error(String(err)));
    } finally {
      setIsLoading(false);
    }
  }, [entityTypeKey, ownerId]);

  useEffect(() => {
    queueMicrotask(() => {
      void fetchFields();
    });
  }, [fetchFields]);

  return { fieldConfigs, isLoading, error, refetch: fetchFields };
}

/**
 * "No value set" — matches GenericTable's own formatCellValue em dash, muted
 * since this is normal, not an error/loading state. Exported (Wave 2 Step
 * 2.2 Task 5) so the CustomFields module's formatCustomFieldValue.tsx can
 * reuse the exact same empty-state markup for its own Number/Date NaN
 * guards instead of duplicating this span — modules importing a component
 * from `core` is the normal, permitted dependency direction (see
 * docs/architecture/01-modularity.md's Dependency Rule), unlike the
 * core-importing-modules direction this file's own extension point exists to
 * avoid.
 */
export function EmptyCustomFieldCell() {
  return <span className="text-muted-foreground/60">—</span>;
}

function isEmptyCustomFieldValue(value: unknown): value is null | undefined | "" {
  return value === null || value === undefined || value === "";
}

export { MaskedCustomFieldCell, type MaskedCustomFieldCellProps };

/**
 * One synthesized Column<T> for a custom field, ready to spread onto a
 * screen's own columns. `render` deliberately ignores both of its arguments
 * (`value`, the raw `row[key]` lookup GenericTable always performs, and
 * `row` beyond its `id`) and instead closes over `valuesByOwnerId`, looked up
 * by `row.id` — every row type in this system has one. See the `key` cast
 * below for why `row[column.key]` being meaningless here is safe.
 */
function buildCustomFieldColumn(
  definition: CustomFieldColumnDefinition,
  valuesByOwnerId: Record<string, Record<string, unknown>>,
  language: string,
  t: (key: string, params?: Record<string, string | number>) => string,
  /** Wave 5 row 5.3 — per owner, the keys a rule hides for that record. */
  hiddenKeysByOwnerId?: Record<string, string[]> | null,
  entityTypeKey?: string
): Column<any> {
  return {
    // Synthetic key: no row type in the host screen has a real property
    // named after a custom field's machine key. GenericTable evaluates
    // `row[column.key]` unconditionally before calling `render` (even though
    // `render` is supplied here), so the `undefined` this produces is simply
    // discarded — `render` below never reads its `value` argument. The cast
    // exists to satisfy `Column<T>`'s `key: keyof T` constraint at the call
    // site, the same "synthetic key + cast" shape used for dynamic keys
    // elsewhere in this codebase (e.g. `as keyof Settings` in
    // core/settings/merge-engine.ts).
    key: definition.key as keyof any,
    label: language === "ar" && definition.labelAr ? definition.labelAr : definition.labelEn,
    // Matches the numeric-column convention already established across this
    // table (end-aligned, tabular figures) rather than inventing a new one.
    className: definition.valueType === "Number" ? "text-end tabular-nums" : undefined,
    render: (_value: unknown, row: any) => {
      // ── Wave 5 row 5.3 ──────────────────────────────────────────────────────────────────────
      //
      // PER ROW, not per column: the same field can be hidden for one record and shown for the next,
      // which is exactly why the column itself is never dropped. Rendered as the ordinary empty cell
      // rather than a distinct "hidden" marker — a field that does not apply to this record reads as
      // having no value, and a special marker would draw attention to precisely the thing the rule
      // exists to keep out of the way.
      //
      // Defence in depth only: the server has already nulled the value, so removing this changes
      // nothing about what is transmitted.
      const hiddenForRow = hiddenKeysByOwnerId?.[row?.id];
      if (hiddenForRow?.some((key) => key.toLowerCase() === definition.key.toLowerCase())) {
        return <EmptyCustomFieldCell />;
      }

      const raw = valuesByOwnerId[row?.id]?.[definition.key];
      if (isEmptyCustomFieldValue(raw)) {
        return <EmptyCustomFieldCell />;
      }

      if (raw === "••••••••" || (definition.sensitivity !== undefined && definition.sensitivity >= 2)) {
        return (
          <MaskedCustomFieldCell
            entityTypeKey={entityTypeKey}
            ownerId={row?.id}
            fieldKey={definition.key}
            initialMaskedValue={typeof raw === "string" && raw.includes("•") ? raw : "••••••••"}
            valueType={definition.valueType}
            language={language}
            t={t}
          />
        );
      }

      // Wave 2 Step 2.2 Task 5: the former inline Number/Boolean/Date/
      // Text-and-Select-fallthrough switch now lives in the CustomFields
      // module (formatCustomFieldValue.tsx) behind this extension point —
      // see formatValueForDisplay's own doc comment above for why it is
      // optional and what the String(raw) fallback below covers.
      const formatted = getCustomFieldsExtension()?.formatValueForDisplay?.(
        definition.valueType,
        raw,
        language,
        t
      );
      return formatted !== undefined ? formatted : String(raw);
    },
  };
}

/**
 * Active custom-field definitions for entityTypeKey, synthesized into
 * ready-to-spread table Columns whose cells are pre-resolved from a single
 * bulk fetch over `ownerIds` (the caller's current page of row ids) — backs
 * GenericCrudView's dynamic custom-field table columns, the table-column
 * counterpart of useCustomFieldsFormFields above. Same unconditional-hooks
 * contract: always calls the same primitive hooks regardless of registration
 * state or entityTypeKey, so Rules of Hooks holds even before the
 * CustomFields module's bootstrap import has run (in which case it just
 * returns no columns).
 */
export function useCustomFieldColumns(
  entityTypeKey: string | undefined,
  ownerIds: string[]
): {
  columns: Column<any>[];
  isLoading: boolean;
  error: Error | null;
} {
  const { t, language } = useI18n();
  const [definitions, setDefinitions] = useState<CustomFieldColumnDefinition[]>([]);
  const [valuesByOwnerId, setValuesByOwnerId] = useState<Record<string, Record<string, unknown>>>(
    {}
  );
  const [hiddenKeysByOwnerId, setHiddenKeysByOwnerId] = useState<Record<string, string[]>>({});
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);

  // `ownerIds` is a fresh array reference on every render (a new page of
  // viewModel.items, a new sort/filter/search) even when its CONTENTS are
  // unchanged. Depending on the array itself would refetch on every render;
  // joining it into one string reduces the dependency to a primitive that
  // only changes when the actual SET of ids changes — pagination, sort,
  // filter, search, whatever changed the page. "," cannot appear inside
  // an encrypted id, so two different id lists never collide onto one key.
  const ownerIdsKey = ownerIds.join(",");

  const fetchColumns = useCallback(async () => {
    const api = getCustomFieldsExtension();
    const targetOwnerIds = ownerIdsKey ? ownerIdsKey.split(",") : [];
    if (!entityTypeKey || !api || targetOwnerIds.length === 0) {
      setDefinitions([]);
      setValuesByOwnerId({});
      setHiddenKeysByOwnerId({});
      setIsLoading(false);
      setError(null);
      return;
    }
    setIsLoading(true);
    setError(null);
    try {
      const result = await api.getBulkColumnValues(entityTypeKey, targetOwnerIds);
      setDefinitions(result.columns.slice().sort((a, b) => a.sortOrder - b.sortOrder));
      setValuesByOwnerId(result.valuesByOwnerId);
      // Reset to {} rather than left alone when the server sends nothing: a previous page whose rows
      // had hidden fields must not leave stale keys hiding cells on the next page.
      setHiddenKeysByOwnerId(result.hiddenKeysByOwnerId ?? {});
    } catch (err) {
      setError(err instanceof Error ? err : new Error(String(err)));
      // Deliberately not clearing definitions/valuesByOwnerId here — a failed
      // background refresh (e.g. a page-change round trip that dropped) keeps
      // showing the last successfully loaded page's custom-field data instead
      // of blanking a table that was working a moment ago.
    } finally {
      setIsLoading(false);
    }
  }, [entityTypeKey, ownerIdsKey]);

  useEffect(() => {
    queueMicrotask(() => {
      void fetchColumns();
    });
  }, [fetchColumns]);

  const columns = useMemo<Column<any>[]>(
    () =>
      definitions.map((definition) =>
        buildCustomFieldColumn(
          definition,
          valuesByOwnerId,
          language,
          t,
          hiddenKeysByOwnerId,
          entityTypeKey
        )
      ),
    [definitions, valuesByOwnerId, hiddenKeysByOwnerId, language, t, entityTypeKey]
  );

  return { columns, isLoading, error };
}


// Re-export custom field validation to avoid cross-module dependency violations
export {
  assertSelectCustomFieldValuesValid,
  CustomFieldValidationError,
} from "@modules/custom-fields/custom-field";

import { useState, useCallback, useRef, useMemo } from "react";
import { useGenericQuery } from "./useGenericQuery";
import { useGenericMutations } from "./useGenericMutations";
import { BaseEntity, PaginatedResult } from "../types";
import { useAppStore } from "@core/store/useAppStore";

export interface CrudViewModelOptions {
  initialPageSize?: number;
  enabled?: boolean;
  /**
   * Hold back the create/update success toast AND the automatic modal-close
   * on a successful save. For a caller doing additional async work after the
   * entity itself saves (e.g. GenericCrudView's entityTypeKey path saving
   * custom-field values) and needing the whole operation — not just the
   * entity's own save — to succeed before telling the user it's done. Call
   * `confirmCreateSuccess()` / `confirmUpdateSuccess()` once that follow-up
   * work actually finishes; call neither on failure, so the dialog stays
   * open with whatever error the caller surfaces. Defaults to false: every
   * existing caller keeps today's immediate toast + auto-close.
   */
  deferSuccessEffects?: boolean;
}

export type SortDirection = "asc" | "desc";

export function useCrudViewModel<T extends BaseEntity, TCreate = any, TUpdate = any>(
  key: any[],
  services: {
    getAll: (params: any) => Promise<PaginatedResult<T>>;
    create?: (data: TCreate) => Promise<T>;
    update?: (id: string, data: TUpdate) => Promise<T>;
    delete?: (id: string) => Promise<void>;
  },
  options: CrudViewModelOptions = {}
) {
  // Store Hydration Guard: ensure queries don't fire before auth/permission state is rehydrated
  const hasHydrated = useAppStore((state) => state._hasHydrated);
  const isQueryEnabled = (options.enabled !== false) && hasHydrated;

  // UI State
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(options.initialPageSize || 10);
  const [searchValue, setSearchValue] = useState("");
  const searchInputRef = useRef<HTMLInputElement>(null);

  // Server-side sort — optional and additive (F-85). `sortBy` stays undefined
  // until a caller explicitly wires a column-header click to `handleSortChange`
  // (see GenericTable's `onSortChange` prop). Until then, `queryParams` below
  // never contains a sortBy/sortDirection key at all, so the object handed to
  // `getAll` is byte-identical to before this existed — no behavior change for
  // the ~10+ other modules built on this same shared hook.
  const [sortBy, setSortBy] = useState<string | undefined>(undefined);
  const [sortDirection, setSortDirection] = useState<SortDirection | undefined>(undefined);

  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [viewModalOpen, setViewModalOpen] = useState(false);

  const [editingItem, setEditingItem] = useState<T | null>(null);
  const [viewItem, setViewItem] = useState<T | null>(null);
  const [selectedItems, setSelectedItems] = useState<string[]>([]);

  // Conditionally-shaped params: only grows to include sortBy/sortDirection
  // once a consumer has actually requested a sort. Modules that never call
  // handleSortChange keep sending exactly { page, pageSize, search }.
  const queryParams = useMemo(
    () =>
      sortBy
        ? { page, pageSize, search: searchValue, sortBy, sortDirection }
        : { page, pageSize, search: searchValue },
    [page, pageSize, searchValue, sortBy, sortDirection]
  );

  // 1. Data Fetching
  const query = useGenericQuery<T>(key, services.getAll, queryParams, isQueryEnabled);

  // A delete (or a filter/search change) can shrink the result set below the page
  // we're currently sitting on, leaving a stale "page 5 of 3" state that renders an
  // empty list. Once the server confirms the real page count, snap back to the new
  // last valid page instead of leaving the user stranded past the end.
  //
  // Adjusted during render (React's documented pattern for "state derived from a
  // prop/query result") rather than in a useEffect, so the correction lands in the
  // same commit instead of an extra post-paint render pass.
  const pagesCount = query.data?.pagination?.pagesCount;
  const [lastSeenPagesCount, setLastSeenPagesCount] = useState(pagesCount);
  if (pagesCount !== lastSeenPagesCount) {
    setLastSeenPagesCount(pagesCount);
    if (pagesCount !== undefined && page > pagesCount) {
      setPage(Math.max(1, pagesCount));
    }
  }

  // 2. Mutations
  // Each mutation type closes ONLY the modal it belongs to. These used to
  // share one `onSuccess` that closed both the create AND edit modal on
  // either mutation's success — harmless while exactly one of the two could
  // ever be open, but a latent trap for any future path (or a modal={false}
  // interaction quirk) that left both flags true at once: a create landing
  // would silently discard whatever was mid-edit in the other dialog.
  const deferSuccessEffects = options.deferSuccessEffects === true;
  const mutations = useGenericMutations<T, TCreate, TUpdate>(key, services, {
    optimisticDelete: true,
    deferSuccessToast: deferSuccessEffects,
    onCreateSuccess: () => {
      if (!deferSuccessEffects) setIsCreateModalOpen(false);
    },
    onUpdateSuccess: () => {
      if (!deferSuccessEffects) closeEditModal();
    },
  });

  // Actions
  const handleSearchChange = useCallback((term: string) => {
    setSearchValue(term);
    setPage(1); // Reset to page 1 on search
  }, []);

  const changePage = useCallback((newPage: number) => {
    setPage(newPage);
  }, []);

  const changePageSize = useCallback((newSize: number) => {
    setPageSize(newSize);
    setPage(1);
  }, []);

  // Server-side sort handler. Wire this to GenericTable's `onSortChange` (via
  // `customTableProps` on the CRUD config) to opt a specific list into real
  // server-side sorting; leaving it unwired keeps the existing client-side,
  // current-page-only sort behavior for that list.
  const handleSortChange = useCallback((column: string, direction: SortDirection) => {
    setSortBy(column);
    setSortDirection(direction);
    setPage(1); // Reset to page 1 — a new sort order invalidates the current page position
  }, []);

  const openEditModal = useCallback((item: T) => {
    setEditingItem(item);
    setIsEditModalOpen(true);
  }, []);

  const closeEditModal = useCallback(() => {
    setEditingItem(null);
    setIsEditModalOpen(false);
  }, []);

  const openViewModal = useCallback((item: T) => {
    setViewItem(item);
    setViewModalOpen(true);
  }, []);

  const closeViewModal = useCallback(() => {
    setViewItem(null);
    setViewModalOpen(false);
  }, []);

  const refreshItems = useCallback(async () => {
    await query.refetch();
  }, [query]);

  // Safe to call unconditionally: when deferSuccessEffects is on, fires the
  // deferred success toast and closes the modal; when deferSuccessEffects is off,
  // the toast was already fired by useGenericMutations so calling this safely
  // ensures modal closure without double-toasting.
  const confirmCreateSuccess = useCallback(() => {
    if (deferSuccessEffects) {
      mutations.showCreateSuccessToast();
    }
    setIsCreateModalOpen(false);
  }, [deferSuccessEffects, mutations]);

  const confirmUpdateSuccess = useCallback(() => {
    if (deferSuccessEffects) {
      mutations.showUpdateSuccessToast();
    }
    closeEditModal();
  }, [deferSuccessEffects, mutations, closeEditModal]);

  return {
    // Data
    items: query.data?.items || [],
    pagination: query.data?.pagination || { itemsCount: 0, pageSize, page, pagesCount: 0 },
    loading: query.isLoading,
    error: query.error ? (query.error as Error).message : null,

    // State
    page,
    pageSize,
    searchValue,
    searchInputRef,
    selectedItems,
    setSelectedItems,
    sortBy,
    sortDirection,

    // Modals
    isCreateModalOpen,
    setIsCreateModalOpen,
    isEditModalOpen,
    setIsEditModalOpen,
    viewModalOpen,
    setViewModalOpen,
    viewItem,
    editingItem,

    // Actions
    handleSearchChange,
    changePage,
    changePageSize,
    handleSortChange,
    openEditModal,
    closeEditModal,
    openViewModal,
    closeViewModal,
    refreshItems,
    refresh: refreshItems, // Alias
    // Only meaningful with deferSuccessEffects: true — see the option's doc
    // comment. Present unconditionally so a caller can call it without an
    // extra existence check; it is simply never needed when the option is off.
    confirmCreateSuccess,
    confirmUpdateSuccess,

    // Mutation Wrappers
    createItem: mutations.create,
    updateItem: mutations.update,
    deleteItem: mutations.remove,

    // Loading States
    isCreating: mutations.isCreating,
    isUpdating: mutations.isUpdating,
    isDeleting: mutations.isDeleting,
  };
}

import { useQuery, UseQueryOptions, keepPreviousData } from "@tanstack/react-query";
import { PaginatedResult } from "../types";

export function useGenericQuery<T, TParams = any>(
  key: any[],
  fetcher: (params: TParams) => Promise<PaginatedResult<T>>,
  params: TParams,
  enabled: boolean = true,
  options?: Omit<UseQueryOptions<PaginatedResult<T>>, "queryKey" | "queryFn">
) {
  return useQuery({
    queryKey: [...key, params],
    queryFn: () => fetcher(params),
    enabled,
    placeholderData: keepPreviousData,
    ...options,
  });
}

import { PaginationInfo } from "@core/common/pagination";

export interface PaginatedResult<T> {
  items: T[];
  pagination: PaginationInfo;
}

export interface CrudState<T> {
  items: T[];
  pagination: PaginationInfo;
  loading: boolean;
  error: string | null;
  selectedItems: string[];
}

export interface BaseEntity {
  id: string;
  [key: string]: any;
}

/**
 * Notification Mappers
 *
 * Handles conversion between notification domain models and external data formats.
 * Follows Single Responsibility Principle by separating serialization concerns
 * from domain logic.
 */

import {
  Notification,
  NotificationConfig,
  NotificationType,
  NotificationPosition,
  type NotificationData,
  type NotificationConfigData,
} from "@core/domain/entities/Notification";

export class NotificationMapper {
  /**
   * Convert JSON/API response to Notification domain model
   */
  static notificationFromJson(json: any): Notification {
    return new Notification({
      id: json.id || this.generateId(),
      title: json.title || "",
      message: json.message || "",
      type: this.parseNotificationType(json.type),
      position: this.parseNotificationPosition(json.position),
      duration: json.duration || 5000,
      isVisible: json.isVisible !== undefined ? json.isVisible : true,
      timestamp: json.timestamp || new Date().toISOString(),
      actions: json.actions || [],
    });
  }

  /**
   * Convert Notification domain model to JSON for API requests
   */
  static notificationToJson(notification: Notification): any {
    return {
      id: notification.id,
      title: notification.title,
      message: notification.message,
      type: notification.type,
      position: notification.position,
      duration: notification.duration,
      isVisible: notification.isVisible,
      timestamp: notification.timestamp,
      actions: notification.actions,
    };
  }

  /**
   * Convert Notification domain model to plain object
   */
  static notificationToPlainObject(notification: Notification): NotificationData {
    return {
      id: notification.id,
      title: notification.title,
      message: notification.message,
      type: notification.type,
      position: notification.position,
      duration: notification.duration,
      isVisible: notification.isVisible,
      timestamp: notification.timestamp,
      actions: notification.actions,
    };
  }

  /**
   * Convert plain object to Notification domain model
   */
  static notificationFromPlainObject(data: NotificationData): Notification {
    return new Notification(data);
  }

  /**
   * Convert JSON/API response to NotificationConfig domain model
   */
  static notificationConfigFromJson(json: any): NotificationConfig {
    return new NotificationConfig({
      position: this.parseNotificationPosition(json.position),
      duration: json.duration || 5000,
      maxNotifications: json.maxNotifications || 5,
      enableSound: json.enableSound || false,
      enableVibration: json.enableVibration || false,
    });
  }

  /**
   * Convert NotificationConfig domain model to JSON
   */
  static notificationConfigToJson(config: NotificationConfig): any {
    return {
      position: config.position,
      duration: config.duration,
      maxNotifications: config.maxNotifications,
      enableSound: config.enableSound,
      enableVibration: config.enableVibration,
    };
  }

  /**
   * Convert NotificationConfig domain model to plain object
   */
  static notificationConfigToPlainObject(config: NotificationConfig): NotificationConfigData {
    return {
      position: config.position,
      duration: config.duration,
      maxNotifications: config.maxNotifications,
      enableSound: config.enableSound,
      enableVibration: config.enableVibration,
    };
  }

  /**
   * Convert plain object to NotificationConfig domain model
   */
  static notificationConfigFromPlainObject(data: NotificationConfigData): NotificationConfig {
    return new NotificationConfig(data);
  }

  /**
   * Convert array of JSON objects to Notification array
   */
  static notificationArrayFromJson(jsonArray: any[]): Notification[] {
    return jsonArray.map((json) => this.notificationFromJson(json));
  }

  /**
   * Convert Notification array to JSON array
   */
  static notificationArrayToJson(notifications: Notification[]): any[] {
    return notifications.map((notification) => this.notificationToJson(notification));
  }

  /**
   * Create notification from simple parameters
   */
  static createNotification(
    title: string,
    message: string,
    type: NotificationType = NotificationType.INFO,
    options: Partial<NotificationData> = {}
  ): Notification {
    return new Notification({
      id: this.generateId(),
      title,
      message,
      type,
      position: options.position || NotificationPosition.TOP_RIGHT,
      duration: options.duration || 5000,
      isVisible: options.isVisible !== undefined ? options.isVisible : true,
      timestamp: new Date().toISOString(),
      actions: options.actions || [],
    });
  }

  /**
   * Create success notification
   */
  static createSuccessNotification(
    message: string,
    title: string = "Success",
    options: Partial<NotificationData> = {}
  ): Notification {
    return this.createNotification(title, message, NotificationType.SUCCESS, options);
  }

  /**
   * Create error notification
   */
  static createErrorNotification(
    message: string,
    title: string = "Error",
    options: Partial<NotificationData> = {}
  ): Notification {
    return this.createNotification(title, message, NotificationType.ERROR, options);
  }

  /**
   * Create info notification
   */
  static createInfoNotification(
    message: string,
    title: string = "Information",
    options: Partial<NotificationData> = {}
  ): Notification {
    return this.createNotification(title, message, NotificationType.INFO, options);
  }

  /**
   * Create warning notification
   */
  static createWarningNotification(
    message: string,
    title: string = "Warning",
    options: Partial<NotificationData> = {}
  ): Notification {
    return this.createNotification(title, message, NotificationType.WARNING, options);
  }

  /**
   * Parse notification type from string
   */
  private static parseNotificationType(type: string): NotificationType {
    switch (type?.toLowerCase()) {
      case "success":
        return NotificationType.SUCCESS;
      case "error":
        return NotificationType.ERROR;
      case "info":
        return NotificationType.INFO;
      case "warning":
        return NotificationType.WARNING;
      default:
        return NotificationType.INFO;
    }
  }

  /**
   * Parse notification position from string
   */
  private static parseNotificationPosition(position: string): NotificationPosition {
    switch (position?.toLowerCase()) {
      case "top-left":
        return NotificationPosition.TOP_LEFT;
      case "top-right":
        return NotificationPosition.TOP_RIGHT;
      case "top-center":
        return NotificationPosition.TOP_CENTER;
      case "bottom-left":
        return NotificationPosition.BOTTOM_LEFT;
      case "bottom-right":
        return NotificationPosition.BOTTOM_RIGHT;
      case "bottom-center":
        return NotificationPosition.BOTTOM_CENTER;
      default:
        return NotificationPosition.TOP_RIGHT;
    }
  }

  /**
   * Generate unique ID for notifications
   */
  private static generateId(): string {
    return `notification-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }
}

import { renderHook, act } from "@testing-library/react";
import { describe, it, expect, beforeEach, vi } from "vitest";
import { useDashboardLayout, type WidgetLayoutConfig } from "../useDashboardLayout";
import { STORAGE_KEYS } from "@core/config/storage-keys";

const defaultTestWidgets: WidgetLayoutConfig[] = [
  { id: "widget-1", title: "Widget 1", isVisible: true, order: 0, size: "medium" },
  { id: "widget-2", title: "Widget 2", isVisible: true, order: 1, size: "small" },
  { id: "widget-3", title: "Widget 3", isVisible: false, order: 2, size: "large" },
];

describe("useDashboardLayout", () => {
  const store = new Map<string, string>();

  beforeEach(() => {
    store.clear();
    vi.mocked(localStorage.getItem).mockImplementation((key) => store.get(key) ?? null);
    vi.mocked(localStorage.setItem).mockImplementation((key, val) => {
      store.set(key, String(val));
    });
    vi.mocked(localStorage.clear).mockImplementation(() => store.clear());
  });

  it("initializes with default widgets when no saved layout exists", () => {
    const { result } = renderHook(() =>
      useDashboardLayout({
        layoutKey: "test-layout",
        version: 1,
        defaultWidgets: defaultTestWidgets,
      })
    );

    expect(result.current.widgets).toHaveLength(3);
    expect(result.current.visibleWidgets).toHaveLength(2);
    expect(result.current.isCustomized).toBe(false);
    expect(result.current.isWidgetVisible("widget-1")).toBe(true);
    expect(result.current.isWidgetVisible("widget-3")).toBe(false);
  });

  it("toggles widget visibility and updates localStorage", () => {
    const { result } = renderHook(() =>
      useDashboardLayout({
        layoutKey: "test-layout",
        version: 1,
        defaultWidgets: defaultTestWidgets,
      })
    );

    act(() => {
      result.current.toggleWidgetVisibility("widget-1");
    });

    expect(result.current.isWidgetVisible("widget-1")).toBe(false);
    expect(result.current.visibleWidgets).toHaveLength(1);
    expect(result.current.isCustomized).toBe(true);

    const raw = localStorage.getItem(STORAGE_KEYS.DASHBOARD_SETTINGS);
    const saved = JSON.parse(raw ?? "{}");
    const testLayout = saved.dashboardLayouts?.["test-layout"];
    expect(testLayout).toBeDefined();
    const w1 = testLayout?.widgets?.find((w: any) => w.id === "widget-1");
    expect(w1?.isVisible).toBe(false);
  });

  it("updates widget size dimensions", () => {
    const { result } = renderHook(() =>
      useDashboardLayout({
        layoutKey: "test-layout",
        version: 1,
        defaultWidgets: defaultTestWidgets,
      })
    );

    act(() => {
      result.current.setWidgetSize("widget-2", "full");
    });

    const target = result.current.widgets.find((w) => w.id === "widget-2");
    expect(target?.size).toBe("full");
    expect(result.current.isCustomized).toBe(true);
  });

  it("reorders widgets according to provided IDs", () => {
    const { result } = renderHook(() =>
      useDashboardLayout({
        layoutKey: "test-layout",
        version: 1,
        defaultWidgets: defaultTestWidgets,
      })
    );

    act(() => {
      result.current.reorderWidgets(["widget-2", "widget-3", "widget-1"]);
    });

    expect(result.current.widgets[0].id).toBe("widget-2");
    expect(result.current.widgets[0].order).toBe(0);
    expect(result.current.widgets[1].id).toBe("widget-3");
    expect(result.current.widgets[1].order).toBe(1);
    expect(result.current.widgets[2].id).toBe("widget-1");
    expect(result.current.widgets[2].order).toBe(2);
    expect(result.current.isCustomized).toBe(true);
  });

  it("resets customized layout back to defaults", () => {
    const { result } = renderHook(() =>
      useDashboardLayout({
        layoutKey: "test-layout",
        version: 1,
        defaultWidgets: defaultTestWidgets,
      })
    );

    act(() => {
      result.current.toggleWidgetVisibility("widget-1");
    });
    expect(result.current.isCustomized).toBe(true);

    act(() => {
      result.current.resetToDefault();
    });

    expect(result.current.isCustomized).toBe(false);
    expect(result.current.isWidgetVisible("widget-1")).toBe(true);
  });
});

/**
 * useAuthRefresh Hook
 *
 * Handles automatic refresh of user authentication data (permissions, roles).
 * This ensures that if permissions are updated on the backend, the frontend
 * will eventually sync without requiring a logout/login.
 *
 * @example
 * // In a layout or provider component:
 * useAuthRefresh({ intervalMs: 5 * 60 * 1000 }); // Refresh every 5 minutes
 */

import { useEffect, useCallback, useRef } from "react";
import { usePathname } from "next/navigation";
import { useAppStore } from "@core/store/useAppStore";
import { useServices } from "@core/providers/service-provider";
import { appLogger } from "@core/common/logger";
import { STORAGE_KEYS } from "../config/storage-keys";

interface UseAuthRefreshOptions {
  /**
   * Interval in milliseconds for periodic refresh.
   * Default: 5 minutes (300000ms)
   */
  intervalMs?: number;

  /**
   * Whether to enable automatic refresh.
   * Default: true
   */
  enabled?: boolean;
}

/**
 * Hook to automatically refresh user permissions and roles.
 * Should be called once in a high-level layout component.
 */
export function useAuthRefresh(options: UseAuthRefreshOptions = {}) {
  const { intervalMs = 1000 * 60 * 5, enabled = true } = options;

  const isAuthenticated = useAppStore((state) => state.isAuthenticated);
  const setAuth = useAppStore((state) => state.setAuth);
  const { authRepository } = useServices();
  const pathname = usePathname();
  const isDocsRoute = pathname?.startsWith("/docs") || pathname?.startsWith("/commercial");

  const isRefreshing = useRef(false);

  /**
   * Refresh user data from the backend
   */
  const refreshUserData = useCallback(async () => {
    if (!isAuthenticated || isRefreshing.current) return;

    isRefreshing.current = true;

    try {
      appLogger.debug("[AuthRefresh] Refreshing user data...");
      const user = await authRepository.getMe();

      if (user) {
        // Update store with fresh data
        setAuth(user, user.permissions || [], []);
        appLogger.debug("[AuthRefresh] User data refreshed successfully");
      }
    } catch (error) {
      // Don't log as error - this is expected if token expired
      // The API interceptor will handle token refresh
      appLogger.debug("[AuthRefresh] Failed to refresh user data:", error);
    } finally {
      isRefreshing.current = false;
    }
  }, [isAuthenticated, authRepository, setAuth]);

  // Set up periodic refresh
  useEffect(() => {
    if (!enabled || !isAuthenticated || isDocsRoute) return;

    // Initial delay before first refresh (give app time to settle)
    const initialDelay = setTimeout(() => {
      // Don't refresh immediately - the login flow already fetched fresh data
    }, intervalMs);

    // Periodic refresh
    const intervalId = setInterval(refreshUserData, intervalMs);

    return () => {
      clearTimeout(initialDelay);
      clearInterval(intervalId);
    };
  }, [enabled, isAuthenticated, intervalMs, refreshUserData]);

  // Also refresh when window regains focus (user returns to tab)
  useEffect(() => {
    if (!enabled || !isAuthenticated || isDocsRoute) return;

    const handleVisibilityChange = () => {
      if (document.visibilityState === "visible") {
        // Only refresh if tab was hidden for more than 5 minutes
        // We track this via a stored timestamp
        const lastRefresh = sessionStorage.getItem(STORAGE_KEYS.lastAuthRefresh);
        const now = Date.now();

        if (!lastRefresh || now - parseInt(lastRefresh, 10) > intervalMs) {
          refreshUserData();
          sessionStorage.setItem(STORAGE_KEYS.lastAuthRefresh, now.toString());
        }
      }
    };

    // Update timestamp on each refresh
    const updateTimestamp = () => {
      sessionStorage.setItem(STORAGE_KEYS.lastAuthRefresh, Date.now().toString());
    };

    document.addEventListener("visibilitychange", handleVisibilityChange);

    // Set initial timestamp
    updateTimestamp();

    return () => {
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, [enabled, isAuthenticated, intervalMs, refreshUserData]);

  return {
    refresh: refreshUserData,
  };
}

"use client";

import { appLogger } from "@core/common/logger";
import { useAppStore } from "@core/store/useAppStore";
import { useNavigation } from "@core/providers/navigation-provider";
import { useRouter, usePathname } from "next/navigation";
import { useEffect, useState } from "react";

export interface AuthorizationState {
  isAuthorized: boolean;
  isLoading: boolean;
  routes: string[];
}

/**
 * Hook to check if user is authorized to access current page.
 *
 * Uses NavigationRepository (via useNavigation context) for access checks
 * instead of the deprecated NavigationService.
 */
export function useAuthorization(): AuthorizationState {
  const isAuthenticated = useAppStore((state) => state.isAuthenticated);
  const hasHydrated = useAppStore((state) => state._hasHydrated);
  const authLoading = !hasHydrated;
  const { navigationData, hasPageAccess } = useNavigation();
  const pathname = usePathname();
  const router = useRouter();
  const [asyncAuthState, setAsyncAuthState] = useState<{
    isAuthorized: boolean;
    routes: string[];
    checkedPath: string | null;
  }>({ isAuthorized: false, routes: [], checkedPath: null });

  useEffect(() => {
    if (authLoading || !isAuthenticated) {
      return;
    }

    const checkAuthorization = async () => {
      try {
        if (!navigationData) {
          // Navigation data not loaded yet — allow access until it is (provider handles loading state)
          setAsyncAuthState({ isAuthorized: true, routes: [], checkedPath: pathname });
          return;
        }

        const isAuthorized = hasPageAccess(pathname);

        setAsyncAuthState({
          isAuthorized,
          routes: navigationData.routes,
          checkedPath: pathname,
        });

        if (!isAuthorized && pathname !== "/not-authorized") {
          router.push("/not-authorized");
        }
      } catch (error) {
        appLogger.error("Authorization check failed:", error);
        setAsyncAuthState({
          isAuthorized: false,
          routes: [],
          checkedPath: pathname,
        });
      }
    };

    checkAuthorization();
  }, [isAuthenticated, authLoading, pathname, navigationData, hasPageAccess, router]);

  if (authLoading) {
    return { isAuthorized: false, isLoading: true, routes: [] };
  }
  if (!isAuthenticated) {
    return { isAuthorized: false, isLoading: false, routes: [] };
  }
  // Async check not yet completed for current path
  if (asyncAuthState.checkedPath !== pathname) {
    return { isAuthorized: false, isLoading: true, routes: [] };
  }

  return {
    isAuthorized: asyncAuthState.isAuthorized,
    isLoading: false,
    routes: asyncAuthState.routes,
  };
}

/**
 * Hook to check if user has access to a specific page.
 * Uses the NavigationProvider context (no service coupling).
 */
export function usePageAccess(pagePath: string): boolean {
  const { hasPageAccess } = useNavigation();
  const isAuthenticated = useAppStore((state) => state.isAuthenticated);

  if (!isAuthenticated) {
    return false;
  }

  return hasPageAccess(pagePath);
}

/**
 * Higher-order component to protect routes
 * Note: This should be used in .tsx files, not .ts files
 */
export function withAuthorization<T extends object>(
  WrappedComponent: React.ComponentType<T>
): React.ComponentType<T> {
  return function AuthorizedComponent(props: T) {
    const { isAuthorized, isLoading } = useAuthorization();

    if (isLoading) {
      return null;
    }

    if (!isAuthorized) {
      return null; // Will be redirected by useAuthorization hook
    }

    // This would need to be used in a .tsx file to work properly
    return null;
  };
}

/**
 * Dropdown Manager Hook
 *
 * Generic hook for managing dropdown state in view models.
 * Handles preloading, searching, and maintaining current selection.
 * Used by view models that need dropdown functionality.
 */

import { useState, useEffect, useCallback, useMemo } from "react";

export interface DropdownOption {
  value: string;
  label: string;
}

export interface UseDropdownManagerOptions<TItem> {
  /**
   * Service method to fetch items for dropdown
   */
  fetchItems: (params: {
    page?: number;
    pageSize?: number;
    PageSearch?: string;
  }) => Promise<{ data: TItem[] }>;

  /**
   * Function to get the ID from an item
   */
  getId: (item: TItem) => string;

  /**
   * Function to get the label from an item
   */
  getLabel: (item: TItem) => string;

  /**
   * ID of the currently selected item (for edit mode)
   */
  selectedId?: string | null;

  /**
   * Method to fetch a single item by ID (for loading current selection)
   */
  fetchItemById?: (id: string) => Promise<TItem>;

  /**
   * Initial page size for loading items
   */
  initialPageSize?: number;
}

/**
 * Hook to manage dropdown state and operations
 */
export function useDropdownManager<TItem>({
  fetchItems,
  getId,
  getLabel,
  selectedId,
  fetchItemById,
  initialPageSize = 50,
}: UseDropdownManagerOptions<TItem>) {
  const [preloadedOptions, setPreloadedOptions] = useState<DropdownOption[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentOption, setCurrentOption] = useState<DropdownOption | null>(null);

  // Load initial options
  useEffect(() => {
    const loadInitial = async () => {
      try {
        const response = await fetchItems({
          page: 1,
          pageSize: initialPageSize,
        });
        const options = response.data.map((item) => ({
          value: getId(item),
          label: getLabel(item),
        }));
        queueMicrotask(() => {
          setPreloadedOptions(options);
        });
      } catch (error) {
        // Silently fail - user will see error when trying to use dropdown
      } finally {
        queueMicrotask(() => {
          setLoading(false);
        });
      }
    };

    loadInitial();
  }, [fetchItems, getId, getLabel, initialPageSize]);

  // Update current option when selectedId changes (for edit mode)
  useEffect(() => {
    if (!selectedId) {
      queueMicrotask(() => {
        setCurrentOption(null);
      });
      return;
    }

    // First check if it's in preloaded options
    const existingOption = preloadedOptions.find((opt) => opt.value === selectedId);
    if (existingOption) {
      queueMicrotask(() => {
        setCurrentOption(existingOption);
      });
      return;
    }

    // If not in preloaded and we have fetchItemById, fetch it
    if (fetchItemById) {
      fetchItemById(selectedId)
        .then((item) => {
          const option = {
            value: getId(item),
            label: getLabel(item),
          };
          queueMicrotask(() => {
            setCurrentOption(option);
            // Add to preloaded options if not already there
            setPreloadedOptions((prev) => {
              if (!prev.find((opt) => opt.value === option.value)) {
                return [...prev, option];
              }
              return prev;
            });
          });
        })
        .catch(() => {
          queueMicrotask(() => {
            setCurrentOption(null);
          });
        });
    } else {
      queueMicrotask(() => {
        setCurrentOption(null);
      });
    }
  }, [selectedId, preloadedOptions, fetchItemById, getId, getLabel]);

  // Server-side search function
  const search = useCallback(
    async (searchTerm: string): Promise<DropdownOption[]> => {
      try {
        const response = await fetchItems({
          page: 1,
          pageSize: initialPageSize,
          PageSearch: searchTerm,
        });
        const options = response.data.map((item) => ({
          value: getId(item),
          label: getLabel(item),
        }));

        // If current option exists and not in results, add it
        if (currentOption && !options.find((opt) => opt.value === currentOption.value)) {
          options.unshift(currentOption);
        }

        return options;
      } catch (error) {
        return [];
      }
    },
    [fetchItems, getId, getLabel, initialPageSize, currentOption]
  );

  // Get edit options (includes current option if not in preloaded)
  const editOptions = useMemo(() => {
    const options = [...preloadedOptions];
    if (currentOption && !options.find((opt) => opt.value === currentOption.value)) {
      options.unshift(currentOption);
    }
    return options;
  }, [preloadedOptions, currentOption]);

  return {
    preloadedOptions,
    editOptions,
    loading,
    currentOption,
    search,
  };
}

"use client";

import { useState } from "react";
import { useEnhancedToast } from "./use-enhanced-toast";

export interface DeleteOptions {
  itemName?: string;
  itemType?: string;
  confirmTitle?: string;
  confirmDescription?: string;
  successMessage?: string;
  errorMessage?: string;
  onSuccess?: () => void;
  onError?: (error: any) => void;
  /** Dialog variant: destructive (red/trash), warning, info, or default (green/check) */
  variant?: "destructive" | "warning" | "info" | "default";
  /** Custom confirm button text (defaults to 'Delete' for destructive, 'Confirm' for others) */
  confirmButtonText?: string;
}

export function useEnhancedDelete() {
  const [isDeleting, setIsDeleting] = useState(false);
  const [showConfirmation, setShowConfirmation] = useState(false);
  const [deleteAction, setDeleteAction] = useState<(() => Promise<void>) | null>(null);
  const [deleteOptions, setDeleteOptions] = useState<DeleteOptions>({});
  const { operationSuccess, operationError } = useEnhancedToast();

  const confirmDelete = async (
    deleteFunction: () => Promise<void>,
    options: DeleteOptions = {}
  ) => {
    setDeleteAction(() => deleteFunction);
    setDeleteOptions(options);
    setShowConfirmation(true);
  };

  const executeDelete = async () => {
    if (!deleteAction) return;

    setIsDeleting(true);
    setShowConfirmation(false);

    try {
      await deleteAction();

      // Show success toast
      const successMsg =
        deleteOptions.successMessage || `${deleteOptions.itemType || "Item"} deleted successfully`;

      operationSuccess("Delete", deleteOptions.itemName);

      // Call success callback
      deleteOptions.onSuccess?.();
    } catch (error) {
      // F2: surface the real backend/caught error instead of discarding it.
      // Same bug class and same fix shape as F-78/F-98/F-99 in
      // useGenericMutations.ts — read the real message off the caught error
      // first, and only fall back to a caller override / generic string when
      // the error carries nothing usable.
      const err = error as {
        message?: string;
        response?: { data?: { message?: string; error?: string } };
      };
      const errorMsg =
        err?.response?.data?.message ||
        err?.response?.data?.error ||
        err?.message ||
        deleteOptions.errorMessage ||
        `Failed to delete ${deleteOptions.itemType?.toLowerCase() || "item"}`;

      operationError("Delete", deleteOptions.itemName, errorMsg);

      // Call error callback
      deleteOptions.onError?.(error);
    } finally {
      setIsDeleting(false);
      setDeleteAction(null);
      setDeleteOptions({});
    }
  };

  const cancelDelete = () => {
    setShowConfirmation(false);
    setDeleteAction(null);
    setDeleteOptions({});
  };

  return {
    isDeleting,
    showConfirmation,
    deleteOptions,
    confirmDelete,
    executeDelete,
    cancelDelete,
  };
}

"use client";

import * as React from "react";
import type { ToastActionElement, ToastProps } from "@core/ui/enhanced-toast";
import { translateCore } from "@core/common/i18n-outside-react";

const TOAST_LIMIT = 5;
const TOAST_REMOVE_DELAY = 2000; // 2 seconds as requested

// The full historical value set stays in the type: toastStyle is a persisted
// setting, so retired names still arrive from storage. enhanced-toast.tsx
// collapses them onto the surviving designs (classic/minimal/modern).
export type ToastDesign =
  | "classic"
  | "neon"
  | "glassmorphism"
  | "neumorphism"
  | "aurora"
  | "cosmic"
  | "minimal"
  | "modern"
  | "gradient"
  | "outlined";

type ToasterToast = ToastProps & {
  id: string;
  title?: React.ReactNode;
  description?: React.ReactNode;
  action?: ToastActionElement;
  variant?: "default" | "destructive" | "success" | "warning" | "info";
  design?: ToastDesign;
  showIcon?: boolean;
  duration?: number;
};

const actionTypes = {
  ADD_TOAST: "ADD_TOAST",
  UPDATE_TOAST: "UPDATE_TOAST",
  DISMISS_TOAST: "DISMISS_TOAST",
  REMOVE_TOAST: "REMOVE_TOAST",
} as const;

let count = 0;

function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER;
  return count.toString();
}

type ActionType = typeof actionTypes;

type Action =
  | {
      type: ActionType["ADD_TOAST"];
      toast: ToasterToast;
    }
  | {
      type: ActionType["UPDATE_TOAST"];
      toast: Partial<ToasterToast>;
    }
  | {
      type: ActionType["DISMISS_TOAST"];
      toastId?: ToasterToast["id"];
    }
  | {
      type: ActionType["REMOVE_TOAST"];
      toastId?: ToasterToast["id"];
    };

interface State {
  toasts: ToasterToast[];
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>();

const addToRemoveQueue = (toastId: string, duration: number = TOAST_REMOVE_DELAY) => {
  if (toastTimeouts.has(toastId)) {
    return;
  }

  const timeout = setTimeout(() => {
    toastTimeouts.delete(toastId);
    dispatch({
      type: "REMOVE_TOAST",
      toastId: toastId,
    });
  }, duration);

  toastTimeouts.set(toastId, timeout);
};

export const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case "ADD_TOAST":
      return {
        ...state,
        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
      };

    case "UPDATE_TOAST":
      return {
        ...state,
        toasts: state.toasts.map((t) => (t.id === action.toast.id ? { ...t, ...action.toast } : t)),
      };

    case "DISMISS_TOAST": {
      const { toastId } = action;

      if (toastId) {
        addToRemoveQueue(toastId);
      } else {
        state.toasts.forEach((toast) => {
          addToRemoveQueue(toast.id, toast.duration);
        });
      }

      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === toastId || toastId === undefined
            ? {
                ...t,
                open: false,
              }
            : t
        ),
      };
    }
    case "REMOVE_TOAST":
      if (action.toastId === undefined) {
        return {
          ...state,
          toasts: [],
        };
      }
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.toastId),
      };
  }
};

const listeners: Array<(state: State) => void> = [];

let memoryState: State = { toasts: [] };

function dispatch(action: Action) {
  memoryState = reducer(memoryState, action);
  listeners.forEach((listener) => {
    listener(memoryState);
  });
}

type Toast = Omit<ToasterToast, "id">;

function baseToast({ ...props }: Toast) {
  const id = genId();

  // showIcon/duration defaults; `design` intentionally stays unset so the
  // workspace toastStyle setting governs unless a caller overrides per-toast.
  const toastProps = {
    showIcon: true,
    duration: TOAST_REMOVE_DELAY,
    ...props,
  };

  const update = (props: ToasterToast) =>
    dispatch({
      type: "UPDATE_TOAST",
      toast: { ...props, id },
    });
  const dismiss = () => dispatch({ type: "DISMISS_TOAST", toastId: id });

  dispatch({
    type: "ADD_TOAST",
    toast: {
      ...toastProps,
      id,
      open: true,
      onOpenChange: (open) => {
        if (!open) dismiss();
      },
    },
  });

  // Auto-dismiss after duration
  setTimeout(() => {
    dismiss();
  }, toastProps.duration);

  return {
    id: id,
    dismiss,
    update,
  };
}

// Convenience methods for different toast types. They accept either a props
// object or a bare message string (the shape sonner call sites used), so both
// `success({ title })` and `success(msg)` work.
type ToastInput = string | Omit<Toast, "variant">;

const asToastProps = (input: ToastInput): Omit<Toast, "variant"> =>
  typeof input === "string" ? { title: input } : input;

function success(input: ToastInput) {
  return baseToast({ ...asToastProps(input), variant: "success" });
}

function error(input: ToastInput) {
  return baseToast({ ...asToastProps(input), variant: "destructive" });
}

function warning(input: ToastInput) {
  return baseToast({ ...asToastProps(input), variant: "warning" });
}

function info(input: ToastInput) {
  return baseToast({ ...asToastProps(input), variant: "info" });
}

// Operation-specific toast methods.
//
// `operation`/`itemName` are still expected to already be caller-localized nouns/verbs
// (this module is a plain singleton usable outside React render, so it cannot call
// useI18n() itself — see i18n-outside-react.ts) — but the surrounding sentence
// structure ("{operation} Successful", "Failed to {operation} {item}.", the
// no-itemName fallbacks, etc.) used to be hardcoded English regardless of the user's
// language. It now goes through the same core locale dictionaries as the rest of the
// app (common.operationToast.*).
function operationSuccess(operation: string, itemName?: string) {
  return success({
    title: translateCore("common.operationToast.successTitle", { operation }),
    description: itemName
      ? translateCore("common.operationToast.successWithItem", {
          item: itemName,
          operationLower: operation.toLowerCase(),
        })
      : translateCore("common.operationToast.successGeneric"),
  });
}

function operationError(operation: string, itemName?: string, error?: string) {
  return baseToast({
    variant: "destructive",
    title: translateCore("common.operationToast.errorTitle", { operation }),
    description:
      error ||
      (itemName
        ? translateCore("common.operationToast.errorWithItem", {
            item: itemName,
            operationLower: operation.toLowerCase(),
          })
        : translateCore("common.operationToast.errorGeneric")),
  });
}

// The module-level `toast` carries the convenience methods so call sites can
// fire `toast({ ... })`, `toast.success(msg)`, or `toast.error(msg)` without a
// hook — outside components, in view-model callbacks, wherever.
const toast = Object.assign(baseToast, { success, error, warning, info });

function useEnhancedToast() {
  const [state, setState] = React.useState<State>(memoryState);

  React.useEffect(() => {
    listeners.push(setState);
    return () => {
      const index = listeners.indexOf(setState);
      if (index > -1) {
        listeners.splice(index, 1);
      }
    };
  }, []);

  return {
    ...state,
    toast,
    success,
    error,
    warning,
    info,
    operationSuccess,
    operationError,
    dismiss: (toastId?: string) => dispatch({ type: "DISMISS_TOAST", toastId }),
  };
}

export { useEnhancedToast, toast };

"use client";

import { useEffect, useRef } from "react";
import { useI18n } from "@core/providers/i18n-provider";
import { appLogger } from "../common/logger";

/**
 * Lazily loads module locale files (BOTH en + ar) when a route is accessed.
 * Uses dynamic import() for code splitting — Next.js creates one chunk per module
 * containing both language dictionaries.
 *
 * Rationale for dual-language chunks:
 * - Module locale chunks are < 3 KB each. Loading both languages (~6 KB total)
 *   eliminates network requests during mid-session EN→AR switches.
 * - Language switching becomes instant with zero UI flash.
 *
 * @param loader - Returns a dynamic import, e.g.:
 *   () => import("@modules/system/tenants/locales")
 * @param moduleKey - Unique deduplication key, e.g.: "system.tenants"
 *
 * @example
 * ```tsx
 * // In a view or layout component:
 * useModuleLocales(
 *   () => import("@modules/system/tenants/locales"),
 *   "system.tenants"
 * );
 * ```
 */
export function useModuleLocales(
  loader: () => Promise<{ en: Record<string, any>; ar: Record<string, any> }>,
  moduleKey: string
): { isLoaded: boolean } {
  const { registerBothLanguages, markModuleLoaded, isModuleLoaded } = useI18n();
  const isLoaded = isModuleLoaded(moduleKey);
  // Stable ref to prevent re-creation of loader closure from triggering re-loads.
  const loaderRef = useRef(loader);
  useEffect(() => {
    loaderRef.current = loader;
  }, [loader]);

  useEffect(() => {
    // Primary guard: isModuleLoaded is the source-of-truth (persists across remounts).
    if (isLoaded) return;

    let cancelled = false;

    loaderRef
      .current()
      .then((mod) => {
        if (cancelled) return;
        // Register BOTH languages in a single O(1) call
        registerBothLanguages(mod.en, mod.ar);
        markModuleLoaded(moduleKey);
      })
      .catch((err) => {
        if (!cancelled) {
          appLogger.error(`[I18n] Failed to load locales for "${moduleKey}":`, err);
        }
      });

    return () => {
      cancelled = true;
    };
  }, [isLoaded, moduleKey, registerBothLanguages, markModuleLoaded]);

  return { isLoaded };
}

/**
 * usePermission Hook
 *
 * Provides convenient permission checking against the current user's effective permissions.
 * This hook accesses the global permissions array stored after login.
 *
 * @example
 * // Single permission check
 * const canCreate = usePermission("admins.create");
 * if (canCreate) { showCreateButton(); }
 *
 * @example
 * // Multiple permission checks
 * const { has, hasAny, hasAll } = usePermissions();
 * if (has("reports.print")) { showPrintButton(); }
 * if (hasAny(["users.view", "admins.view"])) { showUserSection(); }
 */

import { useAppStore } from "@core/store/useAppStore";
import {
  hasPermission,
  hasAnyPermission,
  hasAllPermissions,
  type PermissionCode,
} from "@core/common/types/permissions";

/**
 * Check if current user has a specific permission
 * Returns true if no permission is required (undefined/empty)
 */
export function usePermission(requiredPermission?: PermissionCode): boolean {
  const permissions = useAppStore((state) => state.permissions);
  const user = useAppStore((state) => state.user);

  // No permission required = always allowed
  if (!requiredPermission) return true;

  // Platform superadmin bypass
  if (
    (user as any)?.isSuperAdmin === true ||
    (user as any)?.isProtected === true ||
    user?.username === "superadmin" ||
    permissions.includes("*")
  ) {
    return true;
  }

  // Check against user's effective permissions
  return hasPermission(permissions, requiredPermission);
}

/**
 * Get permission checking utilities for the current user
 * Useful when checking multiple permissions in a component
 */
export function usePermissions() {
  const permissions = useAppStore((state) => state.permissions);
  const user = useAppStore((state) => state.user);

  const isSuperAdmin = Boolean(
    (user as any)?.isSuperAdmin === true ||
    (user as any)?.isProtected === true ||
    user?.username === "superadmin" ||
    permissions.includes("*")
  );

  return {
    /**
     * All permission codes the current user has
     */
    permissions,

    /**
     * Current user object
     */
    user,

    /**
     * Check if user has a specific permission
     */
    has: (permission: PermissionCode): boolean => {
      if (isSuperAdmin) return true;
      return hasPermission(permissions, permission);
    },

    /**
     * Check if user has ANY of the specified permissions
     */
    hasAny: (requiredPermissions: PermissionCode[]): boolean => {
      if (isSuperAdmin) return true;
      return hasAnyPermission(permissions, requiredPermissions);
    },

    /**
     * Check if user has ALL of the specified permissions
     */
    hasAll: (requiredPermissions: PermissionCode[]): boolean => {
      if (isSuperAdmin) return true;
      return hasAllPermissions(permissions, requiredPermissions);
    },

    /**
     * Check if user is authenticated
     */
    isAuthenticated: !!user,
  };
}

export default usePermission;

/**
 * Generic Tree View Model Hook
 *
 * A comprehensive, reusable hook for managing hierarchical tree data with:
 * - **TanStack Query integration** for caching and deduplication
 * - Type-safe CRUD operations
 * - Tree traversal and selection
 * - Auto-parent selection
 * - Form handling for create/edit
 *
 * @version 2.0.0 - TanStack Query Integration
 */
"use client";

import { useCallback, useMemo, useState, useRef, useEffect } from "react";
import { useQuery, useMutation, useQueryClient, keepPreviousData } from "@tanstack/react-query";
import type { PaginationInfo } from "@core/common/pagination";
import { useEnhancedDelete } from "@core/hooks/use-enhanced-delete";
import { useEnhancedToast } from "@core/hooks/use-enhanced-toast";
import { useI18n } from "@core/providers/i18n-provider";

export interface TreeNode {
  id: string;
  children?: TreeNode[];
}

export interface TreeService<T extends TreeNode, TCreate, TUpdate> {
  getWithChildren: (params: { page: number; pageSize: number; PageSearch: string }) => Promise<{
    data: T[];
    pagination: PaginationInfo;
  }>;
  create: (data: TCreate) => Promise<T>;
  update: (id: string, data: TUpdate) => Promise<T>;
  delete: (id: string) => Promise<void>;
}

// Create a generic mock service for selectable mode
export function createMockTreeService<T extends TreeNode>(
  mockData: T[],
  searchFields: (keyof T)[] = []
): TreeService<T, any, any> {
  return {
    getWithChildren: async (params) => {
      // Apply search filter if provided
      let filteredData = mockData;
      if (params.PageSearch && searchFields.length > 0) {
        const searchTerm = params.PageSearch.toLowerCase();
        filteredData = mockData.filter((item: any) =>
          searchFields.some((field) => item[field]?.toString().toLowerCase().includes(searchTerm))
        );
      }

      // Apply pagination
      const startIndex = (params.page - 1) * params.pageSize;
      const endIndex = startIndex + params.pageSize;
      const paginatedData = filteredData.slice(startIndex, endIndex);

      return {
        data: paginatedData,
        pagination: {
          itemsCount: filteredData.length,
          pageSize: params.pageSize,
          page: params.page,
          pagesCount: Math.ceil(filteredData.length / params.pageSize),
        },
      };
    },
    create: async () => {
      throw new Error("Not implemented for mock service");
    },
    update: async () => {
      throw new Error("Not implemented for mock service");
    },
    delete: async () => {
      throw new Error("Not implemented for mock service");
    },
  };
}

export interface TreeViewModelConfig<T extends TreeNode> {
  /** TanStack Query key for caching and invalidation */
  queryKey?: string[];
  // Core configuration - make everything optional for maximum flexibility
  itemTypeName?: string;
  itemTypeNamePlural?: string;
  getItemDisplayName?: (item: T) => string;
  getFormFieldName?: (item: T) => string;
  createFormData?: (values: any) => any;
  updateFormData?: (values: any, item: T) => any;
  getInitialFormValues?: (item?: T, parent?: T) => any;

  // Selectable mode configuration
  selectable?: boolean;
  disabled?: boolean; // Disable selection interactions while maintaining visual state
  getValueToSend?: (item: T) => string;
  initialSelectedValues?: string[];
  onSelectionChange?: (selectedValues: string[]) => void;
  autoSelectParents?: boolean; // Auto-select parent nodes when child is selected

  // Control behavior
  autoLoad?: boolean; // Whether to automatically load data on mount
  staticData?: T[]; // Provide static data instead of using service
  disableOperations?: boolean; // Disable CRUD operations for read-only mode
  /** Stale time in milliseconds (default: 30 seconds) */
  staleTime?: number;
}

export function useTreeViewModel<T extends TreeNode, TCreate = any, TUpdate = any>(
  service?: TreeService<T, TCreate, TUpdate> | null,
  config: TreeViewModelConfig<T> = {}
) {
  const queryClient = useQueryClient();

  const [pagination, setPagination] = useState<PaginationInfo>({
    itemsCount: 0,
    pageSize: 5,
    page: 1,
    pagesCount: 1,
  });

  // Selectable mode state
  const [selectedValues, setSelectedValues] = useState<string[]>(
    config.initialSelectedValues || []
  );

  const [prevInitialSelected, setPrevInitialSelected] = useState(config.initialSelectedValues);
  if (config.initialSelectedValues !== prevInitialSelected) {
    setPrevInitialSelected(config.initialSelectedValues);
    if (config.initialSelectedValues) {
      setSelectedValues(config.initialSelectedValues);
    }
  }

  // Modal state
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<T | null>(null);
  const [parentForNew, setParentForNew] = useState<T | null>(null);
  const [formValues, setFormValues] = useState<any>(config.getInitialFormValues?.() || {});

  // Search state - separate display value from search term
  const [searchValue, setSearchValue] = useState<string>(""); // What user types (immediate)
  const [searchTerm, setSearchTerm] = useState<string>(""); // What triggers API (debounced)
  const searchTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);

  const { toast } = useEnhancedToast();
  const { t } = useI18n();
  const deleteHook = useEnhancedDelete();

  // Build query key
  const effectiveQueryKey = config.queryKey ?? ["tree"];

  // Build query params
  const page = pagination.page;
  const pageSize = pagination.pageSize;
  const queryParams = useMemo(
    () => ({
      page,
      pageSize,
      PageSearch: searchTerm,
    }),
    [page, pageSize, searchTerm]
  );

  // ==========================================
  // TanStack Query - Main Data Fetching
  // ==========================================
  const {
    data: queryData,
    isLoading,
    isFetching,
    refetch,
  } = useQuery({
    queryKey: [...effectiveQueryKey, queryParams],
    queryFn: () => service?.getWithChildren(queryParams),
    enabled: !!service && !config.staticData && config.autoLoad !== false,
    placeholderData: keepPreviousData,
    staleTime: config.staleTime ?? 30 * 1000,
  });

  // Derive tree data from query or static data
  const queryDataItems = queryData?.data;
  const staticData = config.staticData;
  const tree = useMemo(() => {
    if (staticData) {
      return staticData;
    }
    return queryDataItems ?? [];
  }, [staticData, queryDataItems]);

  // Update pagination from query response
  const [prevPagination, setPrevPagination] = useState(queryData?.pagination);
  if (queryData?.pagination !== prevPagination) {
    setPrevPagination(queryData?.pagination);
    if (queryData?.pagination) {
      const qp = queryData.pagination;
      setPagination((prev) => {
        if (prev.itemsCount === qp.itemsCount && prev.pagesCount === qp.pagesCount) {
          return prev;
        }
        return {
          ...qp,
          pageSize: prev.pageSize,
          pagesCount: qp.pagesCount || 1,
          page: qp.page || 1,
        };
      });
    }
  }

  // ==========================================
  // TanStack Mutations
  // ==========================================
  const createMutation = useMutation({
    mutationFn: (data: TCreate) => {
      if (!service) throw new Error("Service not available");
      return service.create(data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: effectiveQueryKey });
      toast({
        title: t("toast.created").replace(
          "{itemType}",
          t(`${config.itemTypeNamePlural || "items"}`)
        ),
        variant: "success",
      });
    },
    onError: () => {
      toast({
        title: t("toast.createError").replace(
          "{itemType}",
          t(`${config.itemTypeNamePlural || "items"}`)
        ),
        variant: "destructive",
      });
    },
  });

  const updateMutation = useMutation({
    mutationFn: ({ id, data }: { id: string; data: TUpdate }) => {
      if (!service) throw new Error("Service not available");
      return service.update(id, data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: effectiveQueryKey });
      toast({
        title: t("toast.updated").replace(
          "{itemType}",
          t(`${config.itemTypeNamePlural || "items"}`)
        ),
        variant: "success",
      });
    },
    onError: () => {
      toast({
        title: t("toast.updateError").replace(
          "{itemType}",
          t(`${config.itemTypeNamePlural || "items"}`)
        ),
        variant: "destructive",
      });
    },
  });

  const deleteMutation = useMutation({
    mutationFn: (id: string) => {
      if (!service) throw new Error("Service not available");
      return service.delete(id);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: effectiveQueryKey });
      toast({
        title: t("toast.deleted"),
        variant: "success",
      });
    },
    onError: () => {
      toast({
        title: t("toast.deleteError"),
        variant: "destructive",
      });
    },
  });

  // ==========================================
  // Tree Helpers
  // ==========================================

  // Helper function to find all parent IDs for a given item
  const findAllParents = useCallback((itemId: string, treeData: T[]): string[] => {
    const parents: string[] = [];

    const findParent = (nodes: T[], targetId: string, currentParents: string[] = []): boolean => {
      for (const node of nodes) {
        if (node.id === targetId) {
          parents.push(...currentParents);
          return true;
        }
        if (node.children && node.children.length > 0) {
          if (findParent(node.children as T[], targetId, [...currentParents, node.id])) {
            return true;
          }
        }
      }
      return false;
    };

    findParent(treeData, itemId);
    return parents;
  }, []);

  // Helper function to find the immediate parent of a given item
  const findImmediateParent = useCallback((itemId: string, treeData: T[]): T | null => {
    const findParent = (nodes: T[], targetId: string): T | null => {
      for (const node of nodes) {
        if (node.children && node.children.length > 0) {
          const hasTargetChild = (node.children as T[]).some((child) => child.id === targetId);
          if (hasTargetChild) {
            return node;
          }
          const found = findParent(node.children as T[], targetId);
          if (found) {
            return found;
          }
        }
      }
      return null;
    };

    return findParent(treeData, itemId);
  }, []);

  // ==========================================
  // Selection handlers
  // ==========================================
  const handleSelectionChange = useCallback(
    (newSelectedValues: string[]) => {
      if (config.disabled) {
        return;
      }

      const finalSelectedValues = [...newSelectedValues];

      // Auto-select parents if enabled
      if (config.autoSelectParents) {
        const allParentsToAdd = new Set<string>();

        newSelectedValues.forEach((selectedId) => {
          const parents = findAllParents(selectedId, tree);
          parents.forEach((parentId) => allParentsToAdd.add(parentId));
        });

        allParentsToAdd.forEach((parentId) => {
          if (!finalSelectedValues.includes(parentId)) {
            finalSelectedValues.push(parentId);
          }
        });
      }

      setSelectedValues(finalSelectedValues);
      if (config.onSelectionChange) {
        config.onSelectionChange(finalSelectedValues);
      }
    },
    [config, tree, findAllParents]
  );

  const clearSelection = useCallback(() => {
    setSelectedValues([]);
    if (config.onSelectionChange) {
      config.onSelectionChange([]);
    }
  }, [config]);

  const selectAll = useCallback(() => {
    const allValues: string[] = [];
    const walk = (nodes: T[]) => {
      nodes.forEach((node) => {
        if (config.getValueToSend) {
          allValues.push(config.getValueToSend(node));
        } else {
          allValues.push(node.id);
        }
        if (node.children && node.children.length > 0) {
          walk(node.children as T[]);
        }
      });
    };
    walk(tree);

    setSelectedValues(allValues);
    if (config.onSelectionChange) {
      config.onSelectionChange(allValues);
    }
  }, [tree, config]);

  // ==========================================
  // CRUD Operations (using mutations)
  // ==========================================
  const disableOperations = config.disableOperations;

  const createItem = useCallback(
    async (data: TCreate) => {
      if (disableOperations) {
        throw new Error("Create operation not available");
      }
      return createMutation.mutateAsync(data);
    },
    [disableOperations, createMutation]
  );

  const updateItem = useCallback(
    async (id: string, data: TUpdate) => {
      if (disableOperations) {
        throw new Error("Update operation not available");
      }
      return updateMutation.mutateAsync({ id, data });
    },
    [disableOperations, updateMutation]
  );

  const deleteItem = useCallback(
    async (item: T) => {
      if (config.disableOperations) {
        throw new Error("Delete operation not available");
      }

      await deleteHook.confirmDelete(
        async () => {
          await deleteMutation.mutateAsync(item.id);
        },
        {
          itemType: t(`${config.itemTypeNamePlural || "items"}`),
          itemName: config.getItemDisplayName?.(item) || "Item",
        }
      );
    },
    [config, deleteHook, t, deleteMutation]
  );

  // ==========================================
  // Pagination handlers
  // ==========================================
  const changePage = useCallback((page: number) => {
    setPagination((prev) => ({ ...prev, page }));
  }, []);

  const changePageSize = useCallback((size: number) => {
    setPagination((prev) => ({ ...prev, pageSize: size, page: 1 }));
  }, []);

  // ==========================================
  // Search handling
  // ==========================================
  const handleSearchChange = useCallback((value: string) => {
    setSearchValue(value);

    if (searchTimeoutRef.current) {
      clearTimeout(searchTimeoutRef.current);
    }

    searchTimeoutRef.current = setTimeout(() => {
      if (searchInputRef.current && document.activeElement !== searchInputRef.current) {
        searchInputRef.current.focus();
      }

      setPagination((prev) => ({ ...prev, page: 1 }));
      setSearchTerm(value);
    }, 300);
  }, []);

  const searchItems = useCallback(
    (term: string) => {
      handleSearchChange(term);
    },
    [handleSearchChange]
  );

  // Cleanup
  useEffect(() => {
    return () => {
      if (searchTimeoutRef.current) {
        clearTimeout(searchTimeoutRef.current);
      }
    };
  }, []);

  // ==========================================
  // Form handling
  // ==========================================
  const resetForm = useCallback(() => {
    setEditing(null);
    setParentForNew(null);
    setFormValues(config.getInitialFormValues?.() || {});
  }, [config]);

  const openAddChild = useCallback(
    (parent: T | null) => {
      // Only block if trying to add a child under a parent when tree is empty
      // Allow adding root items (parent === null) even when tree is empty
      if (parent !== null && (!tree || tree.length === 0)) {
        return;
      }

      setEditing(null);
      setParentForNew(parent);
      const initialValues = config.getInitialFormValues?.(undefined, parent || undefined) || {};
      setFormValues(initialValues);
      setModalOpen(true);
    },
    [config, tree]
  );

  const openEdit = useCallback(
    (item: T) => {
      if (!tree || tree.length === 0) {
        return;
      }

      setEditing(item);
      const parent = findImmediateParent(item.id, tree);
      setParentForNew(parent);
      const initialValues = config.getInitialFormValues?.(item, parent || undefined) || {};
      setFormValues(initialValues);
      setModalOpen(true);
    },
    [config, findImmediateParent, tree]
  );

  const onSubmit = useCallback(
    async (data?: any) => {
      if (config.disableOperations) {
        return;
      }
      // Use passed data or fallback to state (though GenericForm always passes data)
      const dataToSubmit = data || formValues;

      try {
        if (editing) {
          const updateData = config.updateFormData?.(dataToSubmit, editing) || dataToSubmit;
          await updateItem(editing.id, updateData);
        } else {
          const createData = config.createFormData?.(dataToSubmit) || dataToSubmit;
          await createItem(createData);
        }

        setModalOpen(false);
        resetForm();
      } catch (error) {
        // Error handling is already done in mutations
      }
    },
    [editing, formValues, createItem, updateItem, config, resetForm]
  );

  // Parent options for forms (flatten current tree)
  const parentOptions = useMemo(() => {
    const result: { id: string; name: string }[] = [];
    const walk = (nodes: T[]) => {
      nodes.forEach((n) => {
        result.push({ id: n.id, name: config.getItemDisplayName?.(n) || n.id });
        if (n.children && n.children.length) walk(n.children as T[]);
      });
    };
    walk(tree);
    return result;
  }, [tree, config]);

  return {
    // Tree data
    tree,
    loading: isLoading,
    isFetching,
    pagination,
    searchValue,
    searchTerm,
    searchInputRef,

    // Tree operations
    listTree: refetch,
    createItem,
    updateItem,
    deleteItem,
    changePage,
    changePageSize,
    handleSearchChange,
    searchItems,

    // Modal and form
    modalOpen,
    setModalOpen,
    editing,
    parentForNew,
    formValues,
    setFormValues,
    parentOptions,
    resetForm,
    openAddChild,
    openEdit,
    onSubmit,

    // Enhanced delete properties
    isDeleting: deleteHook.isDeleting || deleteMutation.isPending,
    showConfirmation: deleteHook.showConfirmation,
    deleteOptions: deleteHook.deleteOptions,
    executeDelete: deleteHook.executeDelete,
    cancelDelete: deleteHook.cancelDelete,

    // Mutation states
    isCreating: createMutation.isPending,
    isUpdating: updateMutation.isPending,

    // Selectable mode properties
    selectedValues,
    handleSelectionChange,
    clearSelection,
    selectAll,
    disabled: config.disabled,

    // Config
    config,
  };
}

export type TreeViewModel<T extends TreeNode, TCreate, TUpdate> = ReturnType<
  typeof useTreeViewModel<T, TCreate, TUpdate>
>;

/**
 * Validation Hook
 *
 * Provides a convenient hook for form validation using the validation utilities.
 * Handles validation state, error messages, and form submission validation.
 */

import { useState, useCallback, useMemo, useEffect } from "react";
import { validateForm, ValidationRule, isFormValid, getFormErrors } from "@core/common/validation";

export interface UseValidationOptions {
  initialValues?: Record<string, any>;
  validationRules?: Record<string, ValidationRule[]>;
  validateOnChange?: boolean;
  validateOnBlur?: boolean;
}

export interface UseValidationReturn<T extends Record<string, any>> {
  values: T;
  errors: Record<string, string>;
  isValid: boolean;

  setValue: (field: keyof T, value: any) => void;
  setValues: (values: Partial<T>) => void;
  setError: (field: keyof T, error: string) => void;
  clearError: (field: keyof T) => void;
  clearErrors: () => void;
  validate: (field?: keyof T) => boolean;
  validateAll: () => boolean;
  reset: () => void;
  getFieldError: (field: keyof T) => string | undefined;
  hasError: (field: keyof T) => boolean;
}

/**
 * Hook for form validation
 */

export function useValidation<T extends Record<string, any>>(
  options: UseValidationOptions = {}
): UseValidationReturn<T> {
  const {
    initialValues = {} as T,
    validationRules = {},
    validateOnChange = false,
    // validateOnBlur = true,
  } = options;

  const [values, setValuesState] = useState<T>(initialValues as T);
  const [errors, setErrors] = useState<Record<string, string>>({});

  // Validate a specific field
  const validateField = useCallback(
    (field: keyof T): boolean => {
      if (!validationRules[field as string]) {
        return true;
      }

      const validationResults = validateForm(
        { [field]: values[field] },
        { [field]: validationRules[field as string] }
      );

      const result = validationResults[field as string];
      if (!result.isValid) {
        setErrors((prev) => ({ ...prev, [field]: result.message || "" }));
        return false;
      } else {
        setErrors((prev) => {
          const newErrors = { ...prev };
          delete newErrors[field as string];
          return newErrors;
        });
        return true;
      }
    },
    [values, validationRules]
  );

  // Validate all fields
  const validateAll = useCallback((): boolean => {
    if (Object.keys(validationRules).length === 0) {
      return true;
    }

    const validationResults = validateForm(values, validationRules);
    const formErrors = getFormErrors(validationResults);

    setErrors(formErrors);
    return isFormValid(validationResults);
  }, [values, validationRules]);

  // Set a single field value

  const setValue = useCallback(
    (field: keyof T, value: any) => {
      setValuesState((prev) => ({ ...prev, [field]: value }));

      // Clear error when user starts typing
      if (errors[field as string]) {
        setErrors((prev) => {
          const newErrors = { ...prev };
          delete newErrors[field as string];
          return newErrors;
        });
      }

      // Validate on change if enabled
      if (validateOnChange) {
        setTimeout(() => validateField(field), 0);
      }
    },
    [errors, validateOnChange, validateField]
  );

  // Set multiple field values
  const setValues = useCallback(
    (newValues: Partial<T>) => {
      setValuesState((prev) => ({ ...prev, ...newValues }));

      // Clear errors for changed fields
      const fieldsToClear = Object.keys(newValues);
      setErrors((prev) => {
        const newErrors = { ...prev };
        fieldsToClear.forEach((field) => {
          delete newErrors[field];
        });
        return newErrors;
      });

      // Validate changed fields if validate on change is enabled
      if (validateOnChange) {
        setTimeout(() => {
          fieldsToClear.forEach((field) => {
            if (validationRules[field]) {
              validateField(field as keyof T);
            }
          });
        }, 0);
      }
    },
    [validateOnChange, validateField, validationRules]
  );

  // Set a specific error
  const setError = useCallback((field: keyof T, error: string) => {
    setErrors((prev) => ({ ...prev, [field]: error }));
  }, []);

  // Clear a specific error
  const clearError = useCallback((field: keyof T) => {
    setErrors((prev) => {
      const newErrors = { ...prev };
      delete newErrors[field as string];
      return newErrors;
    });
  }, []);

  // Clear all errors
  const clearErrors = useCallback(() => {
    setErrors({});
  }, []);

  // Validate a specific field or all fields
  const validate = useCallback(
    (field?: keyof T): boolean => {
      if (field) {
        return validateField(field);
      }
      return validateAll();
    },
    [validateField, validateAll]
  );

  // Reset form to initial values
  const reset = useCallback(() => {
    setValuesState(initialValues as T);
    setErrors({});
  }, [initialValues]);

  // Get error for a specific field
  const getFieldError = useCallback(
    (field: keyof T): string | undefined => {
      return errors[field as string];
    },
    [errors]
  );

  // Check if a field has an error
  const hasError = useCallback(
    (field: keyof T): boolean => {
      return !!errors[field as string];
    },
    [errors]
  );

  // Check if form is valid
  const isValid = useMemo(() => {
    if (Object.keys(validationRules).length === 0) {
      return true;
    }
    const validationResults = validateForm(values, validationRules);
    return isFormValid(validationResults);
  }, [values, validationRules]);

  return {
    values,
    errors,
    isValid,
    setValue,
    setValues,
    setError,
    clearError,
    clearErrors,
    validate,
    validateAll,
    reset,
    getFieldError,
    hasError,
  };
}

/**
 * Hook for field-level validation
 */
export function useFieldValidation<T>(
  initialValue: T,
  rules: ValidationRule[] = [],
  options: { validateOnChange?: boolean; validateOnBlur?: boolean } = {}
) {
  const { validateOnChange = false, validateOnBlur = true } = options;

  const [value, setValue] = useState<T>(initialValue);
  const [error, setError] = useState<string>("");
  const [touched, setTouched] = useState(false);

  const validate = useCallback((): boolean => {
    if (rules.length === 0) {
      return true;
    }

    const validationResults = validateForm({ value }, { value: rules });
    const result = validationResults.value;

    if (!result.isValid) {
      setError(result.message || "");
      return false;
    } else {
      setError("");
      return true;
    }
  }, [value, rules]);

  const handleChange = useCallback(
    (newValue: T) => {
      setValue(newValue);
      setTouched(true);

      // Clear error when user starts typing
      if (error) {
        setError("");
      }

      // Validate on change if enabled
      if (validateOnChange) {
        setTimeout(() => validate(), 0);
      }
    },
    [error, validateOnChange, validate]
  );

  const handleBlur = useCallback(() => {
    setTouched(true);

    // Validate on blur if enabled
    if (validateOnBlur) {
      validate();
    }
  }, [validateOnBlur, validate]);

  const isValid = useMemo(() => {
    if (rules.length === 0) {
      return true;
    }
    const validationResults = validateForm({ value }, { value: rules });
    return validationResults.value.isValid;
  }, [value, rules]);

  return {
    value,
    error,
    touched,
    isValid,
    setValue: handleChange,
    handleBlur,
    validate,
    clearError: () => setError(""),
    reset: () => {
      setValue(initialValue);
      setError("");
      setTouched(false);
    },
  };
}

/**
 * Hook for debouncing a value
 */
export function useDebounce<T>(value: T, delay: number = 300): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value);

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => {
      clearTimeout(timer);
    };
  }, [value, delay]);

  return debouncedValue;
}

