"use client";

import type React from "react";
import {
  createContext,
  useContext,
  useState,
  useEffect,
  useCallback,
  useMemo,
  useRef,
} from "react";
import { ar as coreAr } from "@core/locales/ar";
import { en as coreEn } from "@core/locales/en";
import { allModulesEn, allModulesAr } from "@core/locales/module-registry";
import { deepMerge } from "@core/utils/deep-merge";
import { STORAGE_KEYS } from "@core/config/storage-keys";

// ─── TYPES ──────────────────────────────────────────────────
export type Language = "ar" | "en";
type Direction = "rtl" | "ltr";
type TranslationDict = Record<string, unknown>;

interface I18nContextType {
  language: Language;
  direction: Direction;
  setLanguage: (lang: Language) => void;
  t: (key: string, params?: Record<string, string | number>) => string;
  registerBothLanguages: (en: TranslationDict, ar: TranslationDict) => void;
  markModuleLoaded: (moduleKey: string) => void;
  isModuleLoaded: (moduleKey: string) => boolean;
}

const I18nContext = createContext<I18nContextType | undefined>(undefined);

// ─── DEV-MODE MISSING-KEY SURFACING ─────────────────────────
// In development we make missing translation keys LOUD instead of
// silently returning the bare key (which historically leaked raw keys
// like "signup.discovery.seePlans" to the UI, and turned the common
// `t(key) || "fallback"` pattern into dead code).
//
// In production we stay graceful — return the bare key, never throw —
// so a single missing key can never blank out or crash a screen.
const isDev = process.env.NODE_ENV !== "production";
const warnedMissingKeys = new Set<string>();

// ─── SSR LOCALE COOKIE (R8) ──────────────────────────────────
// Mirrors the resolved language into a cookie under the SAME name as the
// localStorage key above it (STORAGE_KEYS.LANGUAGE / "scr_lang") so the root
// server layout can read it with next/headers `cookies()` and emit the
// correct <html lang dir> before first paint — localStorage does not exist
// yet at request time, so without this the server always guesses and the
// client effect below has to correct it after mount.
function persistLanguageCookie(lang: Language) {
  if (typeof document === "undefined") return;
  document.cookie = `${STORAGE_KEYS.LANGUAGE}=${lang}; path=/; max-age=31536000; samesite=lax`;
}

function reportMissingKey(key: string, language: Language): string {
  if (isDev && !warnedMissingKeys.has(`${language}:${key}`)) {
    warnedMissingKeys.add(`${language}:${key}`);

    console.warn(`[i18n] missing key: "${key}" (language: "${language}")`);
  }
  return key;
}

// ─── I18N PROVIDER (v8.0 — Zero-Flash + Deep Merge) ─────
//
// Architecture:
// 1. ALL module translations are eagerly loaded via module-registry.ts
//    using deepMerge — available on the VERY FIRST render, zero flash.
// 2. `useModuleLocales()` hook is still safe to call — it becomes a
//    harmless no-op since translations are already in the registry.
// 3. Both EN + AR dictionaries are synchronous — instant language switching.
// 4. Deep merge (from @core/utils/deep-merge) ensures modules sharing
//    the same top-level namespace (e.g. "entitlements") never clobber
//    each other's keys — both at build-time and lazy-load runtime.
//
export function I18nProvider({ children }: { children: React.ReactNode }) {
  // ─── EAGER REGISTRY — All translations available on first render ────
  const registryRef = useRef<Record<Language, TranslationDict>>({
    en: deepMerge({}, coreEn, allModulesEn),
    ar: deepMerge({}, coreAr, allModulesAr),
  });
  const loadedModulesRef = useRef<Set<string>>(new Set());

  const [language, setLanguage] = useState<Language>(() => {
    if (typeof window === "undefined") return "ar";
    const saved = localStorage.getItem(STORAGE_KEYS.LANGUAGE) as Language;
    if (saved === "en" || saved === "ar") return saved;
    const tenantPref = localStorage.getItem(STORAGE_KEYS.PREF_LANG) as Language;
    if (tenantPref === "en" || tenantPref === "ar") return tenantPref;
    return "en";
  });
  const [, forceUpdate] = useState(0);

  const direction: Direction = language === "ar" ? "rtl" : "ltr";

  // ─── REGISTRATION (both languages at once) ────────────────
  // Uses shared deepMerge utility to safely merge lazy-loaded module
  // locales without clobbering sibling keys under shared namespaces.
  const registerBothLanguages = useCallback(
    (enTranslations: TranslationDict, arTranslations: TranslationDict) => {
      deepMerge(registryRef.current.en, enTranslations);
      deepMerge(registryRef.current.ar, arTranslations);
      forceUpdate((n) => n + 1);
    },
    []
  );

  // ─── MODULE TRACKING ──────────────────────────────────────
  const markModuleLoaded = useCallback((moduleKey: string) => {
    loadedModulesRef.current.add(moduleKey);
  }, []);

  const isModuleLoaded = useCallback((moduleKey: string) => {
    return loadedModulesRef.current.has(moduleKey);
  }, []);

  // ─── TRANSLATION FUNCTION ─────────────────────────────────
  const t = useCallback(
    (key: string, params?: Record<string, any>): string => {
      if (!key || typeof key !== "string") return key || "";
      const keys = key.split(".");
      let value: any = registryRef.current[language];

      for (const k of keys) {
        if (value && typeof value === "object" && k in value) {
          value = value[k];
        } else {
          return reportMissingKey(key, language); // path not found
        }
      }

      if (typeof value === "string") {
        // Simple interpolation: replace {{param}} and {param} with actual values
        if (params) {
          let interpolated = value.replace(/\{\{(\w+)\}\}/g, (match, paramKey) => {
            return params[paramKey] !== undefined ? String(params[paramKey]) : match;
          });
          interpolated = interpolated.replace(/\{(\w+)\}/g, (match, paramKey) => {
            return params[paramKey] !== undefined ? String(params[paramKey]) : match;
          });
          return interpolated;
        }
        return value;
      }

      // Resolved to a non-string leaf (object/array) — treat as a miss.
      return reportMissingKey(key, language);
    },
    [language]
  );

  // ─── LANGUAGE SWITCH ──────────────────────────────────────
  const handleSetLanguage = useCallback((lang: Language) => {
    setLanguage(lang);
    localStorage.setItem(STORAGE_KEYS.LANGUAGE, lang);
    persistLanguageCookie(lang);
    document.documentElement.setAttribute("dir", lang === "ar" ? "rtl" : "ltr");
    document.documentElement.setAttribute("lang", lang);

    // Update body class for font
    if (lang === "ar") {
      document.body.classList.add("font-arabic");
      document.body.classList.remove("font-english");
    } else {
      document.body.classList.add("font-english");
      document.body.classList.remove("font-arabic");
    }
  }, []);

  // ─── HYDRATION: Apply saved language's DOM side-effects on mount ──
  // R8 — this <html> can carry writes from up to three sources: the server
  // (this provider's own cookie, read in the root layout), this effect, and
  // DocsI18nProvider on docs routes. DocsI18nProvider already guards itself;
  // this one now does too — read first, compare, only touch the DOM when this
  // provider's own target actually differs, so a cookie that already matches
  // produces zero writes instead of an unconditional (and possibly redundant)
  // one.
  useEffect(() => {
    const targetDir = language === "ar" ? "rtl" : "ltr";
    if (document.documentElement.getAttribute("dir") !== targetDir) {
      document.documentElement.setAttribute("dir", targetDir);
    }
    if (document.documentElement.getAttribute("lang") !== language) {
      document.documentElement.setAttribute("lang", language);
    }
    const fontClass = language === "ar" ? "font-arabic" : "font-english";
    const staleFontClass = language === "ar" ? "font-english" : "font-arabic";
    if (!document.body.classList.contains(fontClass)) {
      document.body.classList.add(fontClass);
    }
    if (document.body.classList.contains(staleFontClass)) {
      document.body.classList.remove(staleFontClass);
    }
    // Backfills the cookie for sessions that only ever had the localStorage
    // value (e.g. existing users, before this cookie existed), so the very
    // next request already gets the correct SSR <html lang dir>.
    persistLanguageCookie(language);
  }, []);

  // ─── STABLE CONTEXT VALUE ─────────────────────────────────
  const contextValue = useMemo<I18nContextType>(
    () => ({
      language,
      direction,
      setLanguage: handleSetLanguage,
      t,
      registerBothLanguages,
      markModuleLoaded,
      isModuleLoaded,
    }),
    [
      language,
      direction,
      handleSetLanguage,
      t,
      registerBothLanguages,
      markModuleLoaded,
      isModuleLoaded,
    ]
  );

  return <I18nContext.Provider value={contextValue}>{children}</I18nContext.Provider>;
}

// ─── CONSUMER HOOK ──────────────────────────────────────────
export function useI18n() {
  const context = useContext(I18nContext);
  if (context === undefined) {
    // SSR/prerender fallback — returns raw keys (safe, no state leak)
    return {
      language: "ar" as const,
      direction: "rtl" as const,
      setLanguage: () => {},
      t: (key: string, _params?: Record<string, string | number>) => key,
      registerBothLanguages: () => {},
      markModuleLoaded: () => {},
      isModuleLoaded: () => false,
    };
  }
  return context;
}

"use client";

import React, { createContext, useContext, useMemo, useCallback } from "react";
import { useAppStore } from "@core/store/useAppStore";
import {
  PermissionCode,
  hasPermission as checkPermission,
  hasAnyPermission as checkAnyPermission,
  hasAllPermissions as checkAllPermissions,
  PAGE_PERMISSIONS,
} from "@core/common/types/permissions";

interface PermissionContextType {
  /**
   * All permissions the current user has
   */
  permissions: PermissionCode[];

  /**
   * Check if user has a specific permission
   */
  hasPermission: (permission: PermissionCode) => boolean;

  /**
   * Check if user has ANY of the specified permissions
   */
  hasAnyPermission: (permissions: PermissionCode[]) => boolean;

  /**
   * Check if user has ALL of the specified permissions
   */
  hasAllPermissions: (permissions: PermissionCode[]) => boolean;

  /**
   * Check if user can access a specific page
   */
  canAccessPage: (path: string) => boolean;

  /**
   * Get the user's role names
   */
  roleNames: string[];

  /**
   * Whether the user is a platform super admin (no tenant claim/context, highest system operator)
   */
  isPlatformSuperAdmin: boolean;

  /**
   * Whether the user is a tenant super admin (belongs to a tenant and holds tenant super admin role)
   */
  isTenantSuperAdmin: boolean;

  /**
   * Whether the user is a super admin (alias for isPlatformSuperAdmin for platform-level operations)
   */
  isSuperAdmin: boolean;
}

const PermissionContext = createContext<PermissionContextType | undefined>(undefined);

interface PermissionProviderProps {
  children: React.ReactNode;
}

/**
 * Helper to match resolved pathnames with Next.js dynamic page templates in PAGE_PERMISSIONS.
 * Example: matches "/roles/123" with "/roles/[id]"
 */
function matchesRoutePattern(pathname: string, pattern: string): boolean {
  const pathSegs = pathname.split("/").filter(Boolean);
  const patternSegs = pattern.split("/").filter(Boolean);

  if (pathSegs.length !== patternSegs.length) return false;

  for (let i = 0; i < patternSegs.length; i++) {
    const patternSeg = patternSegs[i];
    const pathSeg = pathSegs[i];

    if (patternSeg.startsWith("[") && patternSeg.endsWith("]")) {
      continue;
    }

    if (patternSeg !== pathSeg) {
      return false;
    }
  }

  return true;
}

function getRequiredPermissionsForPath(pathname: string): PermissionCode[] | undefined {
  // Try exact match first
  if (PAGE_PERMISSIONS[pathname]) {
    return PAGE_PERMISSIONS[pathname];
  }

  // Try matching dynamic route patterns
  for (const pattern of Object.keys(PAGE_PERMISSIONS)) {
    if (pattern.includes("[") && matchesRoutePattern(pathname, pattern)) {
      return PAGE_PERMISSIONS[pattern];
    }
  }

  return undefined;
}

/**
 * PermissionProvider
 *
 * Provides permission checking utilities throughout the app.
 * Must be placed inside providers that have access to auth state.
 *
 * @example
 * // In layout
 * <PermissionProvider>
 *   <App />
 * </PermissionProvider>
 *
 * // In component
 * const { hasPermission } = usePermissions();
 * if (hasPermission('admins.create')) { ... }
 */
export function PermissionProvider({ children }: PermissionProviderProps) {
  const permissions = useAppStore((state) => state.permissions);
  const roles = useAppStore((state) => state.roles);
  const user = useAppStore((state) => state.user);

  const roleNames = useMemo(() => {
    return roles.map((r) => r.roleName);
  }, [roles]);

  const isPlatformSuperAdmin = useMemo(() => {
    // A user is a PLATFORM Super Admin ONLY if they belong to NO tenant (system-level)
    // and hold platform-wide superadmin privileges.
    if (user?.tenantId) {
      return false;
    }
    return (
      permissions.includes("*") ||
      roles.some((r) => r.roleCode === "SYSTEM_SUPER_ADMIN" || r.roleName === "System Super Admin") ||
      user?.isProtected === true ||
      (user as any)?.isSuperAdmin === true ||
      user?.adminTypeName?.toLowerCase() === "system super admin" ||
      user?.username === "superadmin"
    );
  }, [permissions, roles, user]);

  const isTenantSuperAdmin = useMemo(() => {
    if (!user?.tenantId) return false;
    return (
      roles.some(
        (r) =>
          r.roleCode?.endsWith("_SUPER_ADMIN") ||
          r.roleName?.toLowerCase().includes("super")
      ) || Boolean(user?.adminTypeName?.toLowerCase().includes("super"))
    );
  }, [roles, user]);

  // Backward-compatibility: isSuperAdmin aliases isPlatformSuperAdmin
  const isSuperAdmin = isPlatformSuperAdmin;

  const hasPermission = useCallback(
    (permission: PermissionCode): boolean => {
      if (isPlatformSuperAdmin || isTenantSuperAdmin) {
        return true;
      }
      return checkPermission(permissions, permission);
    },
    [permissions, isPlatformSuperAdmin, isTenantSuperAdmin]
  );

  const hasAnyPermission = useCallback(
    (requiredPermissions: PermissionCode[]): boolean => {
      if (isPlatformSuperAdmin || isTenantSuperAdmin) {
        return true;
      }
      return checkAnyPermission(permissions, requiredPermissions);
    },
    [permissions, isPlatformSuperAdmin, isTenantSuperAdmin]
  );

  const hasAllPermissions = useCallback(
    (requiredPermissions: PermissionCode[]): boolean => {
      if (isPlatformSuperAdmin || isTenantSuperAdmin) {
        return true;
      }
      return checkAllPermissions(permissions, requiredPermissions);
    },
    [permissions, isPlatformSuperAdmin, isTenantSuperAdmin]
  );

  const canAccessPage = useCallback(
    (path: string): boolean => {
      if (isPlatformSuperAdmin || isTenantSuperAdmin) {
        return true;
      }

      if (path === "/venue" || path.startsWith("/venue/")) {
        return true;
      }

      const requiredPermissions = getRequiredPermissionsForPath(path);

      // If no permissions defined for page, allow access (authenticated only)
      if (!requiredPermissions || requiredPermissions.length === 0) {
        return true;
      }

      return checkAllPermissions(permissions, requiredPermissions);
    },
    [permissions, isPlatformSuperAdmin, isTenantSuperAdmin]
  );

  const value = useMemo(
    () => ({
      permissions,
      hasPermission,
      hasAnyPermission,
      hasAllPermissions,
      canAccessPage,
      roleNames,
      isPlatformSuperAdmin,
      isTenantSuperAdmin,
      isSuperAdmin,
    }),
    [
      permissions,
      hasPermission,
      hasAnyPermission,
      hasAllPermissions,
      canAccessPage,
      roleNames,
      isPlatformSuperAdmin,
      isTenantSuperAdmin,
      isSuperAdmin,
    ]
  );

  return <PermissionContext.Provider value={value}>{children}</PermissionContext.Provider>;
}

/**
 * usePermissions Hook
 *
 * Provides permission checking utilities for RBAC.
 *
 * @example
 * const { hasPermission, hasAnyPermission, canAccessPage, isSuperAdmin } = usePermissions();
 *
 * if (hasPermission('admins.create')) {
 *   // Show create button
 * }
 *
 * if (canAccessPage('/system/admins')) {
 *   // Allow access
 * }
 */
export function usePermissions(): PermissionContextType {
  const context = useContext(PermissionContext);

  if (context === undefined) {
    throw new Error("usePermissions must be used within a PermissionProvider");
  }

  return context;
}

/**
 * PermissionGate Component
 *
 * Conditionally renders children based on permissions.
 *
 * @example
 * <PermissionGate permission="admins.create">
 *   <Button>Create Admin</Button>
 * </PermissionGate>
 *
 * <PermissionGate permissions={['admins.update', 'admins.delete']} requireAll={false}>
 *   <ActionsMenu />
 * </PermissionGate>
 */
interface PermissionGateProps {
  /**
   * Single permission to check
   */
  permission?: PermissionCode;

  /**
   * Multiple permissions to check
   */
  permissions?: PermissionCode[];

  /**
   * If true, requires ALL permissions. If false, requires ANY permission.
   * Default: false (any permission)
   */
  requireAll?: boolean;

  /**
   * Content to render if permission check passes
   */
  children: React.ReactNode;

  /**
   * Optional fallback content if permission check fails
   */
  fallback?: React.ReactNode;
}

export function PermissionGate({
  permission,
  permissions,
  requireAll = false,
  children,
  fallback = null,
}: PermissionGateProps) {
  const { hasPermission, hasAnyPermission, hasAllPermissions } = usePermissions();

  let allowed = false;

  if (permission) {
    allowed = hasPermission(permission);
  } else if (permissions && permissions.length > 0) {
    allowed = requireAll ? hasAllPermissions(permissions) : hasAnyPermission(permissions);
  } else {
    // No permissions specified, allow by default
    allowed = true;
  }

  return <>{allowed ? children : fallback}</>;
}

"use client";

/**
 * TenantBrandingProvider
 *
 * After authentication, fetches the current user's tenant branding
 * via GET /tenants/my/branding and exposes it to all layout components.
 * System admins (no tenant) receive null → uses platform defaults.
 */

import { createContext, useContext, useEffect, useState, type ReactNode } from "react";
import { TENANTS_ENDPOINTS } from "@core/config/api-endpoints";
import { getModuleApiService } from "@core/services/api-factory";
import { useResolvedFileUrl } from "@core/hooks/use-resolved-file-url";
import { BRAND } from "@core/config/branding";
import { useAppStore } from "@core/store/useAppStore";
import { STORAGE_KEYS } from "@core/config/storage-keys";
import { useTheme } from "next-themes";
import { useI18n } from "@core/providers/i18n-provider";
import { secureTokenService } from "@core/common/secure-token-service";

// ─── Types ────────────────────────────────────────────────

export interface TenantBrandingData {
  tenantId: string;
  name: string;
  companyName: string | null;
  logoUrl: string | null;
  faviconUrl: string | null;
  primaryColor: string | null;
  secondaryColor: string | null;
  // Customization system (login-relevant, safe for pre-auth)
  loginBrandingJson: string | null;
  loginTextOverridesJson: string | null;
  customFeaturesJson: string | null;
  slotConfigJson: string | null;
  dashboardThemeJson: string | null;
  termsOfServiceUrl: string | null;
  privacyPolicyUrl: string | null;
  isSafeMode: boolean;
  // M11: Admin override control — determines which settings admins can customize
  allowAdminThemeOverride: boolean;
  allowedAdminSettingsJson: string | null;
  // Gap #10: Version for stale-cache detection
  settingsVersion: number;
}

export interface TenantBrandingContextValue {
  /** Display name: companyName → name → BRAND.name */
  appName: string;
  /** Resolved absolute logo URL or default */
  logoUrl: string;
  /** Favicon URL if available */
  faviconUrl: string | null;
  /** Company name for footer/header */
  companyName: string;
  /** Primary color from tenant settings */
  primaryColor: string | null;
  /** Whether branding has been fetched */
  isLoading: boolean;
  /** Whether user is on a tenant (vs system admin) */
  isTenantContext: boolean;
}

// ─── Context ──────────────────────────────────────────────

const TenantBrandingContext = createContext<TenantBrandingContextValue>({
  appName: BRAND.name,
  logoUrl: "/brand/app-logo-1024.png",
  faviconUrl: null,
  companyName: BRAND.name,
  primaryColor: null,
  isLoading: true,
  isTenantContext: false,
});

// ─── Hook ─────────────────────────────────────────────────

export function useTenantBranding(): TenantBrandingContextValue {
  return useContext(TenantBrandingContext);
}

// ─── Provider ─────────────────────────────────────────────

interface TenantBrandingProviderProps {
  children: ReactNode;
}

export function TenantBrandingProvider({ children }: TenantBrandingProviderProps) {
  const isAuthenticated = useAppStore((s) => s.isAuthenticated);
  const user = useAppStore((s) => s.user);
  const setSidebarOpen = useAppStore((s) => s.setSidebarOpen);
  const { setTheme } = useTheme();
  const { setLanguage } = useI18n();
  const [branding, setBranding] = useState<TenantBrandingData | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const [hasToken, setHasToken] = useState(() => secureTokenService.hasToken());

  useEffect(() => {
    const unsubscribe = secureTokenService.subscribe(() => {
      setHasToken(secureTokenService.hasToken());
    });
    return unsubscribe;
  }, []);

  const username = user?.username;

  useEffect(() => {
    if (!isAuthenticated || !user || !hasToken) {
      if (!isAuthenticated || !user) {
        queueMicrotask(() => {
          setIsLoading(false);
        });
      }
      return;
    }

    let cancelled = false;

    async function fetchBranding() {
      try {
        const api = getModuleApiService("IDENTITY");
        const data = await api.get<TenantBrandingData>(TENANTS_ENDPOINTS.TENANTS.MY_BRANDING);

        if (!cancelled && data) {
          setBranding(data);
        }
      } catch {
        // System admin or error → use platform defaults
        if (!cancelled) {
          setBranding(null);
        }
      } finally {
        if (!cancelled) {
          setIsLoading(false);
          // Signal SettingsProvider that branding fetch is done
          // (even if dashboardThemeJson is null — SettingsProvider should finalize)
          window.dispatchEvent(new Event("tenant-branding-loaded"));
        }
      }
    }

    fetchBranding();
    return () => {
      cancelled = true;
    };
    // Depend on username, not tenantId: MY_BRANDING is resolved server-side from
    // the auth token (no tenantId param sent), so this array only needs to detect
    // "different session, please refetch" -- and user.tenantId is
    // IIdEncryptionService.Encrypt(guid), a fresh ciphertext on every /Admins/me
    // response for the SAME tenant, which retriggers this effect on every user
    // refresh instead of settling (same bug as navigation-provider.tsx's
    // contextKey). Drill-down tenant switches are unaffected: enterTenantWorld
    // already forces a full page reload, which remounts this provider anyway.
  }, [isAuthenticated, username, hasToken]);

  // Build the context value with fallbacks.
  // Hooks run unconditionally regardless of `branding` — each already
  // handles empty/undefined input and resolves once branding arrives.
  const resolvedLogoUrl = useResolvedFileUrl(branding?.logoUrl);
  const resolvedFaviconUrl = useResolvedFileUrl(branding?.faviconUrl);
  const appName = branding?.companyName ?? branding?.name ?? BRAND.name;
  const logoUrl = branding?.logoUrl ? resolvedLogoUrl || "/brand/app-logo-1024.png" : "/brand/app-logo-1024.png";
  const faviconUrl = branding?.faviconUrl ? resolvedFaviconUrl || null : null;
  const companyName = branding?.companyName ?? branding?.name ?? BRAND.name;
  const primaryColor = branding?.primaryColor ?? null;
  const isTenantContext = branding !== null;

  // ── Gap 2: Swap browser favicon when tenant branding is available ──
  useEffect(() => {
    if (typeof document === "undefined" || !faviconUrl) return;
    let link = document.querySelector("link[rel~='icon']") as HTMLLinkElement | null;
    if (!link) {
      link = document.createElement("link");
      link.rel = "icon";
      document.head.appendChild(link);
    }
    link.href = faviconUrl;
  }, [faviconUrl]);

  // ── Gap 2b: Update document title with tenant name ──
  useEffect(() => {
    if (typeof document === "undefined" || !isTenantContext) return;
    const originalTitle = document.title;
    document.title = document.title.replace(BRAND.name, appName);
    return () => {
      document.title = originalTitle;
    };
  }, [appName, isTenantContext]);

  // ── Gap 3: Inject tenant primary color as CSS variable ──
  useEffect(() => {
    if (typeof document === "undefined") return;
    const root = document.documentElement;
    if (primaryColor) {
      root.style.setProperty("--tenant-primary", primaryColor);
    }
    return () => {
      root.style.removeProperty("--tenant-primary");
    };
  }, [primaryColor]);

  // ══════════════════════════════════════════════════════════
  // GLOBAL PREFS SYNC — Parse DashboardThemeJson, sync to localStorage,
  // and apply as defaults when no manual override exists.
  //
  // DashboardThemeJson contains two categories:
  //   1. Basic prefs: { theme, language, sidebarCollapsed }
  //   2. Dashboard appearance: { colorTheme, layoutTemplate, cardStyle, ... }
  //
  // Priority (4-layer merge per analysis Section 9):
  //   Layer 1: Platform defaults (hardcoded defaultSettings)
  //   Layer 3: Tenant defaults (DashboardThemeJson → scr_pref_dashboard_settings)
  //   Layer 4: Admin overrides (localStorage dashboard-settings)
  // ══════════════════════════════════════════════════════════
  const dashboardThemeJson = branding?.dashboardThemeJson;
  useEffect(() => {
    if (typeof window === "undefined" || !dashboardThemeJson) return;

    try {
      const prefs = JSON.parse(dashboardThemeJson);

      // 1. Write basic pref keys (backward compat for theme/i18n/sidebar providers)
      if (prefs.theme) localStorage.setItem(STORAGE_KEYS.PREF_THEME, prefs.theme);
      if (prefs.language) localStorage.setItem(STORAGE_KEYS.PREF_LANG, prefs.language);
      if (prefs.sidebarCollapsed !== undefined)
        localStorage.setItem(STORAGE_KEYS.PREF_SIDEBAR_COLLAPSED, String(prefs.sidebarCollapsed));

      // 2. Write the FULL DashboardThemeJson + override control as tenant defaults for settings-provider (Layer 3)
      // M11: Enrich with AllowAdminThemeOverride + AllowedAdminSettingsJson so SettingsProvider
      // can enforce path-level access control during the 4-layer merge.
      const enrichedDefaults = {
        ...prefs,
        _allowAdminOverride: branding.allowAdminThemeOverride ?? true,
        _allowedAdminPaths: branding.allowedAdminSettingsJson
          ? JSON.parse(branding.allowedAdminSettingsJson)
          : null,
        // Gap #10: Include version so SettingsProvider can detect stale admin caches
        _settingsVersion: branding.settingsVersion ?? 0,
      };
      localStorage.setItem(STORAGE_KEYS.PREF_DASHBOARD_SETTINGS, JSON.stringify(enrichedDefaults));

      // 3. Apply basic prefs as defaults ONLY when no manual override exists
      const currentTheme = localStorage.getItem("theme");
      if (!currentTheme && prefs.theme) {
        setTheme(prefs.theme);
      }

      const currentLang = localStorage.getItem(STORAGE_KEYS.LANGUAGE);
      if (!currentLang && prefs.language) {
        setLanguage(prefs.language as "en" | "ar");
      }

      try {
        const stored = localStorage.getItem("app-storage");
        const hasSidebar = stored && JSON.parse(stored).state?.sidebarOpen !== undefined;
        if (!hasSidebar && prefs.sidebarCollapsed !== undefined) {
          setSidebarOpen(!prefs.sidebarCollapsed);
        }
      } catch {
        /* ignore */
      }

      // 4. Signal SettingsProvider to re-merge with the now-populated tenant defaults
      // This eliminates FOUC — SettingsProvider listens for this event and re-applies the 4-layer merge
      window.dispatchEvent(new Event("tenant-branding-loaded"));
    } catch {
      /* invalid JSON — skip */
    }
  }, [dashboardThemeJson, setTheme, setLanguage, setSidebarOpen]);

  const value: TenantBrandingContextValue = {
    appName,
    logoUrl,
    faviconUrl,
    companyName,
    primaryColor,
    isLoading,
    isTenantContext,
  };

  return <TenantBrandingContext.Provider value={value}>{children}</TenantBrandingContext.Provider>;
}

"use client";

/**
 * useAdminSettingsSync — Production-grade server-first admin preferences
 *
 * ARCHITECTURE NOTE: This is a core infrastructure hook, not a module ViewModel.
 * Direct getModuleApiService usage is accepted for cross-cutting core concerns
 * (same pattern as TenantBrandingProvider, NotificationProvider, SignalRProvider).
 * See: frontend-architecture.md — exception for core/providers/ layer.
 *
 * Returns `isSettingsReady` boolean that gates the main UI rendering.
 *
 * FOUC strategy: OPTIMISTIC RENDER + SILENT RECONCILE
 *   - If localStorage has cached settings from a previous session → render immediately
 *   - If localStorage is completely empty (first-ever device) → show shimmer until fetch completes
 *   - In the background, fetch AdminSettingsJson from server → reconcile silently
 *
 * Edge Cases Handled:
 *   1. FOUC Prevention (optimistic render)
 *   2. Tab Close Data Loss (keepalive fetch)
 *   3. 409 Concurrency Conflict (field-level last-write-wins)
 *   4. Payload Size Bomb (8KB client-side guard)
 *   5. JWT Expired Before beforeunload (deferred flush pattern)
 *
 * @module core/providers
 */

import { useEffect, useRef, useCallback, useState } from "react";
import { useAppStore } from "@core/store/useAppStore";
import { STORAGE_KEYS } from "@core/config/storage-keys";
import { TENANTS_ENDPOINTS } from "@core/config/api-endpoints";
import { getModuleApiService } from "@core/services/api-factory";
import { secureTokenService } from "@core/common/secure-token-service";
import { appLogger } from "@core/common/logger";
import { defaultSettings } from "@core/settings/defaults";

// ── Constants ──
const DEBOUNCE_MS = 2000;
const MAX_PAYLOAD_BYTES = 8000; // 8KB soft limit (column is 10KB)
const SAVE_ENDPOINT = TENANTS_ENDPOINTS.TENANTS.ADMIN_PREFERENCES;

// ── Types ──
interface AdminSettingsPayload {
  adminSettingsJson: string;
}

/**
 * Hook that manages the full admin settings lifecycle with 5 critical edge case protections.
 *
 * Must be mounted in the authenticated layout (above SettingsProvider consumption points).
 */
export function useAdminSettingsSync() {
  const isAuthenticated = useAppStore((s) => s.isAuthenticated);
  // MustChangePasswordMiddleware 403s every backend route except a tiny whitelist —
  // syncing preferences while mcp=true is a guaranteed rejection (confirmed live).
  // The admin is about to be logged out and redirected anyway once they change it.
  const mustChangePassword = useAppStore((s) => s.mustChangePassword);

  const [hasToken, setHasToken] = useState(() => secureTokenService.hasToken());

  useEffect(() => {
    const unsubscribe = secureTokenService.subscribe(() => {
      setHasToken(secureTokenService.hasToken());
    });
    return unsubscribe;
  }, []);

  // ── Smart initial state: CACHE-AWARE ──
  // If localStorage has cached settings from a previous session → render immediately
  // with those cached values (optimistic render, zero shimmer for returning users).
  // If localStorage is empty (fresh login, first device, or post-logout) → gate
  // rendering with isSettingsReady=false + isTransitioning=true so DashboardLayout
  // shows a loading shimmer UNTIL the server data (settings + branding + routes) arrives.
  // This eliminates the visible flash: defaults-layout → actual-layout.
  const [hasInitialCache] = useState(() => {
    if (typeof window === "undefined") return true; // SSR: assume ready
    return !!localStorage.getItem(STORAGE_KEYS.DASHBOARD_SETTINGS);
  });
  const [isSettingsReady, setIsSettingsReady] = useState(hasInitialCache);
  // isTransitioning=true blocks DashboardLayout from rendering content.
  // For fresh login: start true so the shimmer shows from the very first frame.
  // For returning users with cache: start false (no shimmer unless server reconciles
  // a different layoutTemplate later).
  const [isTransitioning, setIsTransitioning] = useState(!hasInitialCache);

  const debounceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const hasPendingChanges = useRef(false);
  const latestPayload = useRef<string | null>(null);
  const changedFieldsSinceLastSync = useRef<Set<string>>(new Set());

  // ── Load admin settings from server (with deferred flush check) ──
  const loadAdminSettings = useCallback(async () => {
    if (!isAuthenticated || !hasToken || mustChangePassword) return;

    // Pre-flight: if there are NO cached settings (first login or post-logout),
    // show the transition shimmer BEFORE the API call starts. This prevents the
    // visible flash of default layout → actual layout during the ~1-2s fetch.
    const hasCache = !!localStorage.getItem(STORAGE_KEYS.DASHBOARD_SETTINGS);
    if (!hasCache) {
      setIsTransitioning(true);
    }

    try {
      const api = getModuleApiService("IDENTITY");

      // Edge Case 5: Check for deferred flush from a previous session
      const pendingFlush = localStorage.getItem(STORAGE_KEYS.PENDING_SETTINGS_FLUSH);
      if (pendingFlush) {
        try {
          await api.put<void>(SAVE_ENDPOINT, {
            adminSettingsJson: pendingFlush,
          });
          appLogger.info("Deferred settings flush successful — cleared PENDING_SETTINGS_FLUSH");
        } catch (flushErr) {
          appLogger.warn("Deferred flush failed, will retry next login", flushErr);
        } finally {
          // Always clear, even on failure — prevents infinite retry loops
          localStorage.removeItem(STORAGE_KEYS.PENDING_SETTINGS_FLUSH);
        }
      }

      // Fetch latest settings from server
      const response = await api.get<{ adminSettingsJson: string | null }>(SAVE_ENDPOINT);

      if (response?.adminSettingsJson) {
        const serverSettings = response.adminSettingsJson;

        const cachedSettings = localStorage.getItem(STORAGE_KEYS.DASHBOARD_SETTINGS);

        // Silent reconcile: only update if server differs from cache
        if (serverSettings !== cachedSettings) {
          // Check if the layoutTemplate will change — if so, briefly show
          // the shimmer to prevent a visible layout switch flash.
          let layoutChanged = false;
          try {
            const server = JSON.parse(serverSettings) as Record<string, unknown>;
            if (cachedSettings) {
              // Returning user: compare cached vs server layout
              const cached = JSON.parse(cachedSettings) as Record<string, unknown>;
              layoutChanged = cached.layoutTemplate !== server.layoutTemplate;
            } else {
              // First login / fresh device: compare default layout vs server layout.
              // Without this, the UI would render with the default layout and then
              // visibly flash to the server's layout (e.g. "classic").
              // Read the default rather than naming it: this used to hardcode
              // "nexus", so moving the platform default would silently make every
              // fresh device claim the layout had changed when it had not.
              layoutChanged =
                server.layoutTemplate != null &&
                server.layoutTemplate !== defaultSettings.layoutTemplate;
            }
          } catch {
            // Non-fatal: if parse fails, treat as no layout change
          }

          if (layoutChanged) {
            // Show shimmer BEFORE updating localStorage so the old layout
            // doesn't flash. The shimmer will hide until the new layout
            // chunk is downloaded and rendered.
            setIsTransitioning(true);
          }

          localStorage.setItem(STORAGE_KEYS.DASHBOARD_SETTINGS, serverSettings);
          // Notify SettingsProvider to re-merge layers
          window.dispatchEvent(new Event("admin-settings-loaded"));
          appLogger.info("Admin settings reconciled from server (silent update)");

          if (layoutChanged) {
            // Allow time for React to commit the new layout chunk before
            // removing the shimmer. 800ms covers slow-ish connections while
            // keeping the perceived load time acceptable. The dynamic import
            // has a loading fallback, so even if 800ms isn't enough the user
            // sees a shimmer (not a blank frame).
            setTimeout(() => setIsTransitioning(false), 800);
          }
        }
      }
    } catch (err) {
      // Non-fatal: cached settings (if any) are already rendered
      appLogger.warn("Failed to fetch admin settings from server", err);
    } finally {
      setIsSettingsReady(true);
      // Ensure isTransitioning is always cleared — covers all paths:
      // 1. Pre-flight set it true (no cache) but server returned same/null layout
      // 2. Layout changed → we need 300ms for React to commit the new layout chunk
      // 3. API error → clear immediately so the UI unblocks
      if (!hasCache) {
        // Give React time to commit the new layout before removing shimmer
        setTimeout(() => setIsTransitioning(false), 800);
      }
    }
  }, [isAuthenticated, mustChangePassword]);

  // ── Save settings to server (debounced) ──
  const saveToServer = useCallback(
    async (payload: string) => {
      if (!isAuthenticated || mustChangePassword) return;

      // Edge Case 4: Payload size guard
      const payloadSize = new Blob([payload]).size;
      if (payloadSize > MAX_PAYLOAD_BYTES) {
        window.dispatchEvent(
          new CustomEvent("admin-settings-size-error", {
            detail: {
              message: `Settings payload too large (${Math.round(payloadSize / 1024)}KB / ${MAX_PAYLOAD_BYTES / 1000}KB limit). Some settings may not be saved.`,
            },
          })
        );
        appLogger.error(
          `Admin settings payload exceeds ${MAX_PAYLOAD_BYTES}B limit: ${payloadSize}B`
        );
        return;
      }

      try {
        const api = getModuleApiService("IDENTITY");
        await api.put<void>(SAVE_ENDPOINT, {
          adminSettingsJson: payload,
        } satisfies AdminSettingsPayload);

        // Success — clear the changed fields tracker
        changedFieldsSinceLastSync.current.clear();
        hasPendingChanges.current = false;
        appLogger.info("Admin settings synced to server");
      } catch (err: unknown) {
        // Edge Case 3: 409 Concurrency Conflict — field-level last-write-wins merge
        if (
          err &&
          typeof err === "object" &&
          "status" in err &&
          (err as { status: number }).status === 409
        ) {
          try {
            const api = getModuleApiService("IDENTITY");
            const serverResponse = await api.get<{
              adminSettingsJson: string | null;
            }>(SAVE_ENDPOINT);

            if (serverResponse?.adminSettingsJson) {
              const serverData = JSON.parse(serverResponse.adminSettingsJson);
              const localData = JSON.parse(payload);
              const merged = { ...serverData };
              const overriddenFields: string[] = [];

              // Local fields that changed since last sync WIN over server
              for (const field of changedFieldsSinceLastSync.current) {
                if (field in localData) {
                  // If the field is dashboardLayouts, do a deep key-level merge
                  // so layouts for different pages do not clobber one another across tabs
                  if (
                    field === "dashboardLayouts" &&
                    typeof localData[field] === "object" &&
                    localData[field] !== null &&
                    typeof serverData[field] === "object" &&
                    serverData[field] !== null
                  ) {
                    merged[field] = {
                      ...serverData[field],
                      ...localData[field],
                    };
                  } else {
                    merged[field] = localData[field];
                  }

                  if (JSON.stringify(serverData[field]) !== JSON.stringify(merged[field])) {
                    overriddenFields.push(field);
                  }
                }
              }

              // Save the merged result immediately (no debounce)
              const mergedPayload = JSON.stringify(merged);
              localStorage.setItem(STORAGE_KEYS.DASHBOARD_SETTINGS, mergedPayload);
              window.dispatchEvent(new Event("admin-settings-loaded"));

              await api.put<void>(SAVE_ENDPOINT, {
                adminSettingsJson: mergedPayload,
              });

              changedFieldsSinceLastSync.current.clear();
              hasPendingChanges.current = false;

              // Notify user about the conflict resolution
              if (overriddenFields.length > 0) {
                window.dispatchEvent(
                  new CustomEvent("admin-settings-conflict", {
                    detail: {
                      message: `Updated from another session: ${overriddenFields.join(", ")}`,
                      fields: overriddenFields,
                    },
                  })
                );
              }

              appLogger.info("409 resolved with field-level merge", overriddenFields);
            }
          } catch (mergeErr) {
            appLogger.error("Failed to resolve 409 conflict — local changes may be lost", mergeErr);
          }
        } else {
          appLogger.error("Failed to sync admin settings to server", err);
        }
      }
    },
    [isAuthenticated, mustChangePassword]
  );

  // ── Listen for SettingsProvider changes ──
  useEffect(() => {
    if (!isAuthenticated) return;

    const handleSettingsChanged = (e: Event) => {
      const customEvent = e as CustomEvent<{ changedField: string | null }>;
      const changedField = customEvent.detail?.changedField;

      // Track which field changed (for 409 field-level merge)
      if (changedField) {
        changedFieldsSinceLastSync.current.add(changedField);
      }

      // Read the latest settings from localStorage (written by SettingsProvider)
      const currentSettings = localStorage.getItem(STORAGE_KEYS.DASHBOARD_SETTINGS);
      if (!currentSettings) return;

      latestPayload.current = currentSettings;
      hasPendingChanges.current = true;

      // Debounce the server save
      if (debounceTimer.current) clearTimeout(debounceTimer.current);
      debounceTimer.current = setTimeout(() => {
        if (latestPayload.current) {
          saveToServer(latestPayload.current);
        }
      }, DEBOUNCE_MS);
    };

    window.addEventListener("settings-changed", handleSettingsChanged);
    return () => {
      window.removeEventListener("settings-changed", handleSettingsChanged);
      if (debounceTimer.current) clearTimeout(debounceTimer.current);
    };
  }, [isAuthenticated, saveToServer]);

  // ── Initial load on authentication & token availability ──
  useEffect(() => {
    if (isAuthenticated && hasToken) {
      queueMicrotask(() => {
        loadAdminSettings();
      });
    }
  }, [isAuthenticated, hasToken, loadAdminSettings]);

  // ── Edge Case 2 & 5: beforeunload flush ──
  useEffect(() => {
    if (!isAuthenticated) return;

    const handleBeforeUnload = () => {
      if (!hasPendingChanges.current || !latestPayload.current) return;

      // Cancel the pending debounce timer
      if (debounceTimer.current) clearTimeout(debounceTimer.current);

      const payloadBody = JSON.stringify({
        adminSettingsJson: latestPayload.current,
      } satisfies AdminSettingsPayload);
      const url = `${process.env.NEXT_PUBLIC_IDENTITY_API_URL}${SAVE_ENDPOINT}`;

      // Check if we still have a valid JWT
      const token = secureTokenService.getAccessToken();

      if (token) {
        // JWT exists — use fetch with keepalive + Authorization header
        // (keepalive: true allows request to outlive the page AND supports custom headers)
        try {
          fetch(url, {
            method: "PUT",
            headers: {
              "Content-Type": "application/json",
              Authorization: `Bearer ${token}`,
            },
            body: payloadBody,
            keepalive: true,
          });
        } catch {
          // fetch with keepalive failed — fall through to deferred flush
          localStorage.setItem(STORAGE_KEYS.PENDING_SETTINGS_FLUSH, latestPayload.current);
        }
      } else {
        // JWT is missing/expired — store payload for deferred flush on next login.
        // The loadAdminSettings() effect checks for this key before fetching.
        localStorage.setItem(STORAGE_KEYS.PENDING_SETTINGS_FLUSH, latestPayload.current);
        appLogger.warn(
          "beforeunload: JWT expired — payload stored for deferred flush on next login"
        );
      }

      hasPendingChanges.current = false;
    };

    window.addEventListener("beforeunload", handleBeforeUnload);
    return () => window.removeEventListener("beforeunload", handleBeforeUnload);
  }, [isAuthenticated]);

  return { isSettingsReady, isTransitioning };
}

import { WorkspaceGroup } from "@core/navigation/domain/entities/WorkspaceGroup";

type WithMenuItems = {
  menuItems?: Array<{ href?: string | null; children?: Array<{ href?: string | null }> }>;
};

export function firstPageOf(ws: WithMenuItems): string | null {
  const findHref = (items: any[]): string | null => {
    for (const item of items) {
      if (item.href && !item.href.startsWith("#") && item.href !== "/") return item.href;
      if (item.children && item.children.length > 0) {
        const childHref = findHref(item.children);
        if (childHref) return childHref;
      }
    }
    return null;
  };
  return findHref(ws.menuItems ?? []);
}

/**
 * The workspace accent as a complete CSS colour.
 *
 * NOTE FOR CONSUMERS: this returns an `oklch(...)` **function string**, not a
 * hex value. Appending two hex digits to it for alpha — `` `${accent}80` `` —
 * produces `oklch(0.6 0.18 262)80`, which is invalid CSS, and the browser drops
 * the entire declaration without warning. That silently blanked the workspace
 * loader and the transition overlay for as long as they existed.
 *
 * To vary opacity use `color-mix(in oklch, ${accent} 50%, transparent)`, which
 * is agnostic to the colour's notation.
 */
export function getAccentColor(ws: WorkspaceGroup | null): string | null {
  if (!ws || ws.colorHue === null || ws.colorHue === undefined) return null;
  // Delegates to WorkspaceGroup.accentColor — single source for the
  // dark(L0.68)/light(L0.46) lightness split matching the --nx-accent ladder.
  return ws.accentColor;
}

"use client";

import axios, {
  AxiosInstance,
  AxiosError,
  AxiosRequestConfig,
  InternalAxiosRequestConfig,
} from "axios";
import type { IApiService } from "../interfaces/api.interface";
import { appLogger } from "@core/common/logger";
import { secureTokenService } from "@core/common/secure-token-service";
import { authBroadcast } from "@core/common/broadcast-auth";
import { STORAGE_KEYS } from "../config/storage-keys";
import { DownloadInterceptedError, isExternalAbort } from "../errors/download-intercepted";
import { translateCore } from "@core/common/i18n-outside-react";

/**
 * Generate a UUID v4 string.
 * Uses crypto.randomUUID() when available (secure contexts / HTTPS),
 * falls back to crypto.getRandomValues() (available in ALL contexts).
 * Both paths are cryptographically secure.
 */
function generateUUID(): string {
  if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
    return crypto.randomUUID();
  }
  // Fallback: manual UUID v4 via crypto.getRandomValues()
  const bytes = new Uint8Array(16);
  crypto.getRandomValues(bytes);
  bytes[6] = (bytes[6] & 0x0f) | 0x40; // version 4
  bytes[8] = (bytes[8] & 0x3f) | 0x80; // variant 10
  const hex = Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("");
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

/**
 * S0.15: Enterprise-grade CSRF token store.
 *
 * OWASP Signed Double-Submit Cookie pattern with cross-origin SPA delivery.
 *
 * The backend issues a fresh HMAC-signed CSRF token on EVERY response via
 * the X-CSRF-Token response header (exposed via CORS). We capture it here
 * and echo it back on state-changing requests (POST/PUT/PATCH/DELETE).
 *
 * Why NOT read document.cookie:
 *   The __Host- cookie is set on the BACKEND domain (onrender.com), but the
 *   frontend is on admin.scripe.org. Same-Origin Policy prevents JS on one domain
 *   from reading cookies set by another domain via document.cookie.
 *
 * Why this is still CSRF-safe:
 *   This token is HMAC-signed server-side with a secret + JWT jti.
 *   An attacker on evil.com:
 *     a) Cannot read the X-CSRF-Token response header (CORS blocks it)
 *     b) Cannot forge a valid HMAC without the server secret
 *     c) Cannot replay a token (it's session-bound via jti)
 *
 * Reference: OWASP CSRF Cheat Sheet — Signed Double-Submit Cookie
 */
let _csrfToken: string | null = null;

function getCsrfToken(): string | null {
  return _csrfToken;
}

function setCsrfToken(token: string | null): void {
  if (token) _csrfToken = token;
}

// P1.5: Cache language in module-level variable — avoids localStorage.getItem() on every request
//
// Reads STORAGE_KEYS.LANGUAGE ("scr_lang" — see i18n-provider.tsx, the only writer of this
// key). This used to read a bare "language" key that nothing in the app ever wrote, so
// cachedLanguage was permanently stuck on its "en" default and every request's
// Accept-Language header silently ignored the user's actual selected UI language — an
// Arabic-speaking user's server-localized error messages (e.g. via ILocalizer) would
// always come back in English regardless of their language preference.
let cachedLanguage: string =
  typeof window !== "undefined" ? localStorage.getItem(STORAGE_KEYS.LANGUAGE) || "en" : "en";
if (typeof window !== "undefined") {
  window.addEventListener("storage", (e) => {
    if (e.key === STORAGE_KEYS.LANGUAGE && e.newValue) cachedLanguage = e.newValue;
  });
  // Also intercept direct writes from same tab
  const originalSetItem = localStorage.setItem;
  localStorage.setItem = function (key: string, value: string) {
    originalSetItem.call(this, key, value);
    if (key === STORAGE_KEYS.LANGUAGE) cachedLanguage = value;
  };
}

/**
 * API Service Implementation using Axios
 *
 * Enterprise-grade HTTP client with:
 * - Automatic token refresh on 401
 * - Request/Response interceptors
 * - Typed responses
 * - AbortController support
 */
export class ApiService implements IApiService {
  private axiosInstance: AxiosInstance;
  private axiosPublic: AxiosInstance;

  // private tokenKey = "auth-token"; // DEPRECATED: Use SecureTokenService
  // private refreshTokenKey = "refresh-token"; // DEPRECATED: Use SecureTokenService
  private refreshHandler: (() => Promise<string | null>) | null = null;
  private isRefreshing = false;
  private refreshPromise: Promise<string | null> | null = null;
  private failedQueue: Array<{
    resolve: (token: string | null) => void;
    reject: (error: Error) => void;
  }> = [];

  // Retry configuration
  private readonly maxRetries = 3;
  private readonly retryDelayMs = 1000; // Base delay for exponential backoff
  private readonly retryableStatusCodes = [500, 502, 503, 504];

  // Tenant context for X-Tenant-Context header
  // Eagerly read from sessionStorage so the header is set BEFORE any React effects run.
  // Without this, TanStack Query fires dashboard queries during render (before useEffect),
  // and they go out without the tenant context header.
  private tenantContextId: string | null = (() => {
    if (typeof window !== "undefined") {
      try {
        const saved = sessionStorage.getItem(STORAGE_KEYS.tenant_context);
        if (saved) {
          const parsed = JSON.parse(saved);
          if (parsed?.id) return parsed.id;
        }
      } catch {
        // Ignore parse errors
      }
    }
    return null;
  })();

  // Logout handler — set externally to avoid circular dependency
  // (ApiService cannot import useAppStore directly)
  private logoutHandler: (() => void) | null = null;

  constructor(baseUrl: string = process.env.NEXT_PUBLIC_API_URL || "/api") {
    // A leading "/" means same-origin relative (the documented dev/monolith default,
    // e.g. "/api") — it must stay relative. Coercing it into `https://${baseUrl}`
    // produces an authority-less "https:///api" URL that resolves to a bogus host
    // (F-03). Only a bare host with no scheme (e.g. "api.scripe.org") needs coercion.
    const normalizedBaseUrl =
      baseUrl.startsWith("http") || baseUrl.startsWith("/") ? baseUrl : `https://${baseUrl}`;

    // Authenticated instance
    this.axiosInstance = axios.create({
      baseURL: normalizedBaseUrl,
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        "ngrok-skip-browser-warning": "true",
      },
      withCredentials: true, // equivalent to credentials: 'include'
    });

    // Public instance (no auth interceptors)
    this.axiosPublic = axios.create({
      baseURL: normalizedBaseUrl,
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        "ngrok-skip-browser-warning": "true",
      },
      withCredentials: true,
    });

    this.setupInterceptors();
  }

  /**
   * Setup request and response interceptors
   */
  private setupInterceptors(): void {
    // Request interceptor - add auth token and tenant context
    this.axiosInstance.interceptors.request.use(
      (config: InternalAxiosRequestConfig) => {
        const token = this.getAuthToken();
        if (token) {
          config.headers.Authorization = `Bearer ${token}`;
          appLogger.auth("Token added to request");
        }

        // Add tenant context header if set
        if (this.tenantContextId) {
          config.headers["X-Tenant-Context"] = this.tenantContextId;
          appLogger.api(`Tenant context: ${this.tenantContextId}`);
        }

        // P1.5: Use cached language instead of reading localStorage per request
        config.headers["Accept-Language"] = cachedLanguage;

        // P6.3: Request replay protection (timestamp + nonce)
        const isMutating = ["post", "put", "patch", "delete"].includes(
          (config.method ?? "").toLowerCase()
        );
        if (isMutating) {
          // Replay protection: unique timestamp + nonce per request
          config.headers["X-Request-Timestamp"] = Date.now().toString();
          config.headers["X-Request-Nonce"] = generateUUID();

          // S0.15: CSRF protection — OWASP Signed Double-Submit Cookie pattern.
          // Token was captured from X-CSRF-Token response header on last response.
          // The token is HMAC-SHA256 signed server-side (secret + JWT jti),
          // so it cannot be forged by an attacker on another origin.
          const csrfToken = getCsrfToken();
          if (csrfToken) {
            config.headers["X-CSRF-Token"] = csrfToken;
          }
        }

        // Fix for 415 Unsupported Media Type with FormData
        if (config.data instanceof FormData) {
          // Let browser set Content-Type with boundary
          delete config.headers["Content-Type"];
        }

        appLogger.api(`${config.method?.toUpperCase()} ${config.url}`);
        return config;
      },
      (error) => Promise.reject(error)
    );

    // Response interceptor - capture CSRF token and handle 401
    this.axiosInstance.interceptors.response.use(
      (response) => {
        // S0.15: Capture fresh HMAC-signed CSRF token from every response.
        // Backend rotates it on every response; we always use the latest.
        const freshCsrfToken = response.headers["x-csrf-token"];
        if (freshCsrfToken) setCsrfToken(freshCsrfToken);

        appLogger.api(`Success: ${response.status}`);
        return response;
      },
      async (error: AxiosError) => {
        const originalRequest = error.config as InternalAxiosRequestConfig & { _retry?: boolean };

        // Handle 401 - attempt token refresh
        if (error.response?.status === 401 && !originalRequest._retry) {
          originalRequest._retry = true;

          // If a fresh token was already stored while this request was in-flight (e.g. via RouteGuard or broadcast),
          // retry immediately with the fresh token without triggering another refresh cycle.
          const activeToken = secureTokenService.getAccessToken();
          const sentToken = originalRequest.headers?.Authorization?.toString().replace(/^Bearer\s+/i, "") ?? "";
          if (activeToken && activeToken !== sentToken) {
            appLogger.auth("Newer token already present in secureTokenService — retrying request immediately");
            if (originalRequest.headers) {
              originalRequest.headers.Authorization = `Bearer ${activeToken}`;
            }
            return this.axiosInstance(originalRequest);
          }

          // Issue #8: DI timing race — if no refresh handler is wired yet,
          // just reject the promise instead of calling handleUnauthorized.
          // The route-guard will handle session restore.
          if (!this.refreshHandler) {
            appLogger.auth("No refresh handler set yet (DI timing race), rejecting request");
            return Promise.reject(error);
          }

          if (this.isRefreshing) {
            // Queue this request until refresh completes
            return new Promise((resolve, reject) => {
              this.failedQueue.push({ resolve, reject });
            }).then((token) => {
              if (token && originalRequest.headers) {
                originalRequest.headers.Authorization = `Bearer ${token}`;
              }
              return this.axiosInstance(originalRequest);
            });
          }

          this.isRefreshing = true;

          try {
            this.refreshPromise = this.refreshHandler();
            const newToken = await this.refreshPromise;

            if (newToken) {
              appLogger.auth("Token refreshed successfully");
              // Retry queued requests
              this.failedQueue.forEach(({ resolve }) => resolve(newToken));
              this.failedQueue = [];

              if (originalRequest.headers) {
                originalRequest.headers.Authorization = `Bearer ${newToken}`;
              }
              return this.axiosInstance(originalRequest);
            }

            // Refresh failed
            this.failedQueue.forEach(({ reject }) => reject(new Error("Token refresh failed")));
            this.failedQueue = [];
            this.handleUnauthorized();
            return Promise.reject(error);
          } catch (refreshError) {
            appLogger.auth("Token refresh failed:", refreshError);
            this.failedQueue.forEach(({ reject }) => reject(refreshError as Error));
            this.failedQueue = [];
            this.handleUnauthorized();
            return Promise.reject(refreshError);
          } finally {
            this.isRefreshing = false;
            this.refreshPromise = null;
          }
        }

        // Global check: if IDM or another download manager intercepted the download,
        // we throw DownloadInterceptedError BEFORE the error gets mangled.
        if (isExternalAbort(error)) {
          return Promise.reject(new DownloadInterceptedError());
        }

        // Handle 403 — three cases, checked in order:
        if (error.response?.status === 403) {
          const data = (error.response.data ?? {}) as {
            error?: string;
            errorCode?: string;
            message?: string;
          };

          // Case 1: Drill-down tenant-context checks (TenantContextMiddleware on the
          // backend) — always resolved by silently clearing the bad context, never a
          // hard redirect. TENANT_CONTEXT_FORBIDDEN/INVALID/OUT_OF_SCOPE are the three
          // codes that middleware can emit (see TenantContextMiddleware.cs).
          const tenantContextCodes = new Set([
            "TENANT_CONTEXT_FORBIDDEN",
            "TENANT_CONTEXT_INVALID",
            "TENANT_CONTEXT_OUT_OF_SCOPE",
          ]);
          if (data.error && tenantContextCodes.has(data.error)) {
            appLogger.warn(`Tenant context rejected (${data.error}) - clearing context`);
            this.setTenantContext(null);
            if (typeof window !== "undefined") {
              sessionStorage.removeItem(STORAGE_KEYS.tenant_context);
            }
            return Promise.reject(
              new Error(data.message || translateCore("errors.auth.tenantContextForbidden"))
            );
          }

          // Case 2: A scoped, business-rule rejection from our own Result/Error
          // pipeline (see Core.Application.Common.ErrorResponse.FromError on the
          // backend). A response shaped this way carries `errorCode` because it
          // reached us through a controller action that ran and made a business
          // decision about THIS specific request/record — e.g. "you can't edit this
          // particular record because X" — not "you may not be on this page at all".
          // Show it inline; do not navigate the user away from what they were doing.
          if (data.errorCode) {
            appLogger.warn(`Business-rule 403 (${data.errorCode}) — surfacing inline, not redirecting`);
            // Attach the parsed body as `details`, exactly as every other rejection path in this
            // file does (the generic authenticated path and the public instance's, both below).
            //
            // WHY THIS MATTERS AND WHAT BREAKS WITHOUT IT: `IApiService` deliberately exposes no
            // HTTP status codes to callers, so `error.details` — the `ErrorResponse` body, carrying
            // both `statusCode` and `errorCode` — is the ONLY machine-readable classification a
            // caller ever gets. Rejecting with a bare `new Error(message)` here left the localized
            // server message as the sole signal, and a caller keying on a message works in English
            // and silently stops working in Arabic. So every structured business-rule 403 arrived
            // indistinguishable from an unclassifiable failure, and any caller wanting to branch on
            // one had nothing to branch on. Concretely, the entity-lookup picker classifies a 403
            // into a distinct "you do not have permission to view this type of record" state
            // (EntityLookupError) keyed on `details.errorCode` / `details.statusCode`; with the body
            // dropped, that state was correct code that could not be reached in production.
            const businessError = new Error(
              data.message || translateCore("errors.auth.forbidden")
            ) as Error & { details?: unknown; status?: number };
            businessError.details = error.response?.data ?? data;
            businessError.status = 403;
            return Promise.reject(businessError);
          }

          // Case 3: No structured error body — a real authorization/permission failure
          // from the ASP.NET Core authorization middleware itself (a policy failure
          // before the request ever reached a controller action returns an empty
          // body), or a controller not yet migrated to ErrorResponse. Treated
          // conservatively as "you have no business being on this page" and hard
          // redirected, same as before.
          appLogger.warn("Permission denied (403) — redirecting to /not-authorized");
          if (
            typeof window !== "undefined" &&
            !window.location.pathname.startsWith("/not-authorized") &&
            !window.location.pathname.startsWith("/login")
          ) {
            window.location.href = "/not-authorized";
          }
          return Promise.reject(new Error(data.message || translateCore("errors.auth.forbidden")));
        }

        // Log other errors
        const message = this.extractErrorMessage(error);
        appLogger.error(`API Error: ${message}`);
        const errObj = new Error(message) as any;
        errObj.details = error.response?.data;
        errObj.status = error.response?.status;
        return Promise.reject(errObj);
      }
    );

    // Public instance - log requests and add Accept-Language
    this.axiosPublic.interceptors.request.use((config: InternalAxiosRequestConfig) => {
      // P1.5: Use cached language instead of reading localStorage per request
      config.headers["Accept-Language"] = cachedLanguage;

      appLogger.api(`${config.method?.toUpperCase()} ${config.url} (public)`);
      return config;
    });

    this.axiosPublic.interceptors.response.use(
      (response) => {
        // S0.15: Also capture CSRF token from public responses (e.g., login).
        // This seeds the token before any authenticated mutations.
        const freshCsrfToken = response.headers["x-csrf-token"];
        if (freshCsrfToken) setCsrfToken(freshCsrfToken);

        appLogger.api(`Success: ${response.status}`);
        return response;
      },
      (error: AxiosError) => {
        // Global check: IDM interception
        if (isExternalAbort(error)) {
          return Promise.reject(new DownloadInterceptedError());
        }

        const message = this.extractErrorMessage(error);
        appLogger.error(`API Error: ${message}`);
        const errObj = new Error(message) as any;
        errObj.details = error.response?.data;
        return Promise.reject(errObj);
      }
    );
  }

  /**
   * Extract error message from Axios error
   */
  private extractErrorMessage(error: AxiosError): string {
    if (error.response?.data) {
      const data = error.response.data as unknown;
      if (typeof data === "string" && data.trim() !== "") {
        return data;
      }
      if (typeof data === "object" && data !== null) {
        const obj = data as Record<string, unknown>;
        if (typeof obj.message === "string" && obj.message.trim() !== "") {
          return obj.message;
        }
        if (typeof obj.error === "string" && obj.error.trim() !== "") {
          return obj.error;
        }
        if (obj.errors && typeof obj.errors === "object" && !Array.isArray(obj.errors)) {
          for (const val of Object.values(obj.errors as Record<string, unknown>)) {
            if (Array.isArray(val)) {
              const first = val.find((m) => typeof m === "string" && m.trim() !== "");
              if (first) return first;
            } else if (typeof val === "string" && val.trim() !== "") {
              return val;
            }
          }
        }
        if (typeof obj.title === "string" && obj.title.trim() !== "") {
          return obj.title;
        }
      }
      return `HTTP ${error.response.status}`;
    }
    if (error.code === "ECONNABORTED") {
      return translateCore("errors.network.timeout");
    }
    if (error.code === "ERR_NETWORK") {
      return translateCore("errors.network.offline");
    }
    return error.message || translateCore("errors.network.unknown");
  }

  /**
   * Calculate delay for exponential backoff
   * @param attempt - Current retry attempt (0-indexed)
   * @returns Delay in milliseconds with jitter
   */
  private getRetryDelay(attempt: number): number {
    // Exponential backoff: 1s, 2s, 4s... with random jitter
    const exponentialDelay = this.retryDelayMs * Math.pow(2, attempt);
    const jitter = Math.random() * 500; // Add 0-500ms jitter
    return exponentialDelay + jitter;
  }

  /**
   * Check if error is retryable
   */
  private isRetryableError(error: AxiosError): boolean {
    if (error.code === "ERR_NETWORK" || error.code === "ECONNABORTED") {
      return true; // Network errors are retryable
    }
    if (error.response?.status && this.retryableStatusCodes.includes(error.response.status)) {
      return true; // 5xx errors are retryable
    }
    return false;
  }

  /**
   * Sleep helper for retry delay
   */
  private sleep(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  /**
   * Execute request with automatic retry on 5xx errors
   * Uses exponential backoff with jitter
   */
  private async withRetry<T>(
    requestFn: () => Promise<T>,
    retries: number = this.maxRetries
  ): Promise<T> {
    let lastError: Error | null = null;

    for (let attempt = 0; attempt <= retries; attempt++) {
      try {
        return await requestFn();
      } catch (error) {
        lastError = error as Error;

        if (error instanceof AxiosError && this.isRetryableError(error)) {
          if (attempt < retries) {
            const delay = this.getRetryDelay(attempt);
            appLogger.warn(
              `Request failed, retrying in ${Math.round(delay)}ms (attempt ${attempt + 1}/${retries})`
            );
            await this.sleep(delay);
            continue;
          }
        }

        // Non-retryable error or max retries reached
        throw error;
      }
    }

    throw lastError || new Error("Request failed after retries");
  }

  /**
   * Unwrap response data (handles { data: T } wrapper)
   */
  private unwrap<T>(data: unknown): T {
    if (data && typeof data === "object" && "data" in data) {
      const response = data as { data: T; pagination?: unknown; meta?: unknown };
      // Preserve full structure if it has pagination or meta
      if ("pagination" in response || "meta" in response) {
        return data as T;
      }
      return response.data;
    }
    return data as T;
  }

  /**
   * Handle unauthorized - clear tokens and trigger store-based logout.
   * Uses Zustand store instead of window.location.href to preserve SPA state
   * and let RouteGuard handle the redirect.
   */
  private handleUnauthorized(): void {
    if (typeof window !== "undefined" && window.location.pathname !== "/login") {
      appLogger.warn("Unauthorized - clearing tokens and triggering store logout");
      this.clearTokens();
      // Broadcast to other tabs so they also log out
      authBroadcast.broadcastLogout();
      // Use the externally-set logout handler (wired by ServiceProvider)
      // This avoids circular dependency from require('@core/store/useAppStore')
      if (this.logoutHandler) {
        this.logoutHandler();
      }
    }
  }

  /**
   * Build config with AbortSignal
   */
  private buildConfig(signal?: AbortSignal, params?: Record<string, unknown>): AxiosRequestConfig {
    const config: AxiosRequestConfig = {};
    if (signal) {
      config.signal = signal;
    }
    if (params) {
      config.params = params;
    }
    return config;
  }

  // ============================================
  // Authenticated Methods
  // ============================================

  async get<T>(
    endpoint: string,
    params?: Record<string, unknown>,
    signal?: AbortSignal
  ): Promise<T> {
    const response = await this.axiosInstance.get(endpoint, this.buildConfig(signal, params));
    return this.unwrap<T>(response.data);
  }

  async getBlob(endpoint: string, signal?: AbortSignal): Promise<Blob> {
    try {
      const config: AxiosRequestConfig = { responseType: "blob" };
      if (signal) config.signal = signal;
      const response = await this.axiosInstance.get(endpoint, config);
      return response.data as Blob;
    } catch (error) {
      // Global detection: if the download was intercepted by an external
      // download manager (IDM, FDM, etc.), throw a typed error so callers
      // can treat it as success instead of failure.
      if (isExternalAbort(error)) {
        throw new DownloadInterceptedError();
      }
      throw error;
    }
  }

  async postBlob(endpoint: string, data?: unknown, signal?: AbortSignal): Promise<Blob> {
    try {
      const config: AxiosRequestConfig = { responseType: "blob" };
      if (signal) config.signal = signal;
      const response = await this.axiosInstance.post(endpoint, data, config);
      return response.data as Blob;
    } catch (error) {
      if (isExternalAbort(error)) {
        throw new DownloadInterceptedError();
      }
      throw error;
    }
  }

  async post<T>(endpoint: string, data?: unknown, signal?: AbortSignal): Promise<T> {
    const response = await this.axiosInstance.post(endpoint, data, this.buildConfig(signal));
    return this.unwrap<T>(response.data);
  }

  async put<T>(endpoint: string, data?: unknown, signal?: AbortSignal): Promise<T> {
    const response = await this.axiosInstance.put(endpoint, data, this.buildConfig(signal));
    return this.unwrap<T>(response.data);
  }

  async patch<T>(endpoint: string, data?: unknown, signal?: AbortSignal): Promise<T> {
    const response = await this.axiosInstance.patch(endpoint, data, this.buildConfig(signal));
    return this.unwrap<T>(response.data);
  }

  async delete<T>(endpoint: string, signal?: AbortSignal): Promise<T> {
    const response = await this.axiosInstance.delete(endpoint, this.buildConfig(signal));
    return this.unwrap<T>(response.data);
  }

  // ============================================
  // Public Methods (No Auth)
  // ============================================

  async getPublic<T>(
    endpoint: string,
    params?: Record<string, unknown>,
    signal?: AbortSignal
  ): Promise<T> {
    const response = await this.axiosPublic.get(endpoint, this.buildConfig(signal, params));
    return this.unwrap<T>(response.data);
  }

  async postPublic<T>(endpoint: string, data?: unknown, signal?: AbortSignal): Promise<T> {
    const response = await this.axiosPublic.post(endpoint, data, this.buildConfig(signal));
    return this.unwrap<T>(response.data);
  }

  // ============================================
  // Retry-Enabled Methods (Auto-retry on 5xx)
  // ============================================

  /**
   * GET request with automatic retry on 5xx errors
   * Uses exponential backoff: 1s, 2s, 4s with jitter
   */
  async getWithRetry<T>(
    endpoint: string,
    params?: Record<string, unknown>,
    signal?: AbortSignal
  ): Promise<T> {
    return this.withRetry(() => this.get<T>(endpoint, params, signal));
  }

  /**
   * POST request with automatic retry on 5xx errors
   */
  async postWithRetry<T>(endpoint: string, data?: unknown, signal?: AbortSignal): Promise<T> {
    return this.withRetry(() => this.post<T>(endpoint, data, signal));
  }

  /**
   * PUT request with automatic retry on 5xx errors
   */
  async putWithRetry<T>(endpoint: string, data?: unknown, signal?: AbortSignal): Promise<T> {
    return this.withRetry(() => this.put<T>(endpoint, data, signal));
  }

  // ============================================
  // Special Methods
  // ============================================

  async putWithRefresh<T>(
    endpoint: string,
    data?: unknown,
    refreshEndpoint?: string,
    signal?: AbortSignal
  ): Promise<T> {
    const response = await this.put<T>(endpoint, data, signal);

    // If 204 No Content, fetch updated data
    if (response === null) {
      appLogger.api("204 response, fetching updated data...");
      const refreshUrl = refreshEndpoint || endpoint;
      return this.get<T>(refreshUrl, undefined, signal);
    }

    return response;
  }

  // ============================================
  // Token Management
  // ============================================

  setAuthToken(token: string | null): void {
    if (typeof window !== "undefined") {
      if (token) {
        secureTokenService.setAccessToken(token);
        appLogger.auth("Token saved");
      } else {
        secureTokenService.clearTokens();
        appLogger.auth("Tokens cleared");
      }
    }
  }

  getAuthToken(): string | null {
    if (typeof window !== "undefined") {
      return secureTokenService.getAccessToken();
    }
    return null;
  }

  clearTokens(): void {
    if (typeof window !== "undefined") {
      secureTokenService.clearTokens();
      appLogger.auth("All tokens cleared");
    }
  }

  /**
   * Set the refresh handler for automatic token refresh
   */
  setRefreshHandler(handler: () => Promise<string | null>): void {
    this.refreshHandler = handler;
    appLogger.auth("Refresh handler set");
  }

  /**
   * Set the logout handler called when auth is irrecoverably lost.
   * Wired by ServiceProvider to call useAppStore.getState().logout()
   * without circular dependency.
   */
  setLogoutHandler(handler: () => void): void {
    this.logoutHandler = handler;
    appLogger.auth("Logout handler set");
  }

  // ============================================
  // Tenant Context Management
  // ============================================

  /**
   * Set the current tenant context for X-Tenant-Context header
   * @param tenantId - The tenant ID to scope requests to, or null to clear
   */
  setTenantContext(tenantId: string | null): void {
    this.tenantContextId = tenantId;
    if (tenantId) {
      appLogger.api(`Tenant context set: ${tenantId}`);
    } else {
      appLogger.api("Tenant context cleared");
    }
  }

  /**
   * Get the current tenant context ID
   */
  getTenantContext(): string | null {
    return this.tenantContextId;
  }
}

import { appLogger } from "@core/common/logger";
import {
  Notification,
  NotificationConfig,
  NotificationQueue,
  NotificationType,
  type NotificationData,
} from "@core/domain/entities/Notification";
import { NotificationMapper } from "@core/domain/mappers/NotificationMapper";

export interface INotificationService {
  success(message: string, title?: string, options?: Partial<NotificationData>): void;
  error(message: string, title?: string, options?: Partial<NotificationData>): void;
  info(message: string, title?: string, options?: Partial<NotificationData>): void;
  warning(message: string, title?: string, options?: Partial<NotificationData>): void;
  add(notification: Notification): void;
  remove(id: string): void;
  clear(): void;
  getAll(): Notification[];
  getVisible(): Notification[];
  getByType(type: NotificationType): Notification[];
  updateConfig(config: NotificationConfig): void;
  getConfig(): NotificationConfig;
}

export class NotificationService implements INotificationService {
  private queue: NotificationQueue;
  private config: NotificationConfig;

  constructor(config?: NotificationConfig) {
    this.config = config || NotificationConfig.getDefault();
    this.queue = new NotificationQueue(this.config);
  }

  /**
   * Show success notification
   */
  success(
    message: string,
    title: string = "Success",
    options: Partial<NotificationData> = {}
  ): void {
    const notification = NotificationMapper.createSuccessNotification(message, title, options);
    this.add(notification);
    appLogger.info("Success notification:", { title, message });
  }

  /**
   * Show error notification
   */
  error(message: string, title: string = "Error", options: Partial<NotificationData> = {}): void {
    const notification = NotificationMapper.createErrorNotification(message, title, options);
    this.add(notification);
    appLogger.error("Error notification:", { title, message });
  }

  /**
   * Show info notification
   */
  info(
    message: string,
    title: string = "Information",
    options: Partial<NotificationData> = {}
  ): void {
    const notification = NotificationMapper.createInfoNotification(message, title, options);
    this.add(notification);
    appLogger.info("Info notification:", { title, message });
  }

  /**
   * Show warning notification
   */
  warning(
    message: string,
    title: string = "Warning",
    options: Partial<NotificationData> = {}
  ): void {
    const notification = NotificationMapper.createWarningNotification(message, title, options);
    this.add(notification);
    appLogger.warn("Warning notification:", { title, message });
  }

  /**
   * Add notification to queue
   */
  add(notification: Notification): void {
    this.queue.add(notification);

    // Auto-remove after duration
    if (notification.duration > 0) {
      setTimeout(() => {
        this.remove(notification.id);
      }, notification.duration);
    }
  }

  /**
   * Remove notification by ID
   */
  remove(id: string): void {
    this.queue.remove(id);
  }

  /**
   * Clear all notifications
   */
  clear(): void {
    this.queue.clear();
  }

  /**
   * Get all notifications
   */
  getAll(): Notification[] {
    return this.queue.getAll();
  }

  /**
   * Get visible notifications
   */
  getVisible(): Notification[] {
    return this.queue.getVisible();
  }

  /**
   * Get notifications by type
   */
  getByType(type: NotificationType): Notification[] {
    return this.queue.getByType(type);
  }

  /**
   * Update configuration
   */
  updateConfig(config: NotificationConfig): void {
    this.config = config;
    this.queue.updateConfig(config);
  }

  /**
   * Get current configuration
   */
  getConfig(): NotificationConfig {
    return this.config;
  }

  /**
   * Create custom notification
   */
  createNotification(
    title: string,
    message: string,
    type: NotificationType = NotificationType.INFO,
    options: Partial<NotificationData> = {}
  ): Notification {
    return NotificationMapper.createNotification(title, message, type, options);
  }

  /**
   * Show notification with custom duration
   */
  showWithDuration(
    message: string,
    duration: number,
    type: NotificationType = NotificationType.INFO,
    title?: string
  ): void {
    const notification = this.createNotification(
      title || this.getDefaultTitle(type),
      message,
      type,
      { duration }
    );
    this.add(notification);
  }

  /**
   * Show notification with actions
   */
  showWithActions(
    message: string,
    actions: any[],
    type: NotificationType = NotificationType.INFO,
    title?: string
  ): void {
    const notification = this.createNotification(
      title || this.getDefaultTitle(type),
      message,
      type,
      { actions }
    );
    this.add(notification);
  }

  /**
   * Get default title based on type
   */
  private getDefaultTitle(type: NotificationType): string {
    switch (type) {
      case NotificationType.SUCCESS:
        return "Success";
      case NotificationType.ERROR:
        return "Error";
      case NotificationType.INFO:
        return "Information";
      case NotificationType.WARNING:
        return "Warning";
      default:
        return "Notification";
    }
  }
}

import React from "react";
import { render, screen, waitFor, fireEvent } from "@testing-library/react";
import { describe, it, expect, vi } from "vitest";
import { Dialog, DialogContent, DialogTitle } from "../dialog";

/**
 * Dialog outside-click allowlist tests.
 *
 * DialogContent's onInteractOutside/onPointerDownOutside handlers call
 * e.preventDefault() when the outside-click target is inside one of six
 * allowlisted portal selectors (dropdown/select/date-picker/popper/listbox/
 * option), so pointer-downs inside those live portals never dismiss the
 * dialog. Any other outside click falls through to Radix's default dismiss
 * behavior and closes it.
 */

vi.mock("@core/providers/i18n-provider", () => ({
  useI18n: () => ({
    t: (key: string) => key,
    direction: "ltr",
  }),
}));

function renderDialog(onOpenChange: (open: boolean) => void) {
  return render(
    <div>
      {/* Sits outside the Dialog's portal tree — a plain non-allowlisted node. */}
      <button type="button">outside-plain</button>
      {/* Simulates a live portal (e.g. a Select's popper content) rendered
          outside the DialogContent DOM subtree but allowlisted by selector. */}
      <div data-radix-popper-content-wrapper="">
        <div role="listbox">
          <div role="option">option-1</div>
        </div>
      </div>
      <Dialog open onOpenChange={onOpenChange}>
        <DialogContent>
          <DialogTitle>Test dialog</DialogTitle>
          <button type="button">inside</button>
        </DialogContent>
      </Dialog>
    </div>
  );
}

// Radix's DismissableLayer registers its `pointerdown` listener on
// `document` inside a `setTimeout(0)` (so the open-triggering pointerdown
// itself is never seen), and — for a non-"touch" pointerType — dispatches
// onPointerDownOutside synchronously from that same listener. So a real
// test has to: wait a tick for the listener to attach, then fire a
// `pointerdown` (not click) whose `pointerType` is anything but "touch".
function pointerDownOutside(target: Element) {
  fireEvent.pointerDown(target, { pointerId: 1, button: 0, pointerType: "mouse" });
}

describe("Dialog outside-click allowlist", () => {
  it("does not close when the outside click lands inside an allowlisted portal selector", async () => {
    const onOpenChange = vi.fn();
    // Radix marks every sibling of the modal `aria-hidden="true"` while open
    // (its aria-hide side effect), so the allowlisted portal content below
    // is invisible to `getByRole`/`getByText` even though it's live DOM —
    // query it directly off `baseElement` instead.
    const { baseElement } = renderDialog(onOpenChange);

    expect(screen.getByText("Test dialog")).toBeInTheDocument();

    // Let DismissableLayer's effect (setTimeout(0)) attach its listener.
    await new Promise((resolve) => setTimeout(resolve, 0));

    const option = baseElement.querySelector("[role='option']");
    expect(option).not.toBeNull();
    pointerDownOutside(option as Element);

    await waitFor(() => {
      expect(onOpenChange).not.toHaveBeenCalledWith(false);
    });
    expect(screen.getByText("Test dialog")).toBeInTheDocument();
  });

  it("closes when the outside click lands on a non-allowlisted element", async () => {
    const onOpenChange = vi.fn();
    const { baseElement } = renderDialog(onOpenChange);

    expect(screen.getByText("Test dialog")).toBeInTheDocument();

    await new Promise((resolve) => setTimeout(resolve, 0));

    const outsideButton = baseElement.querySelector("button");
    expect(outsideButton).not.toBeNull();
    expect(outsideButton?.textContent).toBe("outside-plain");
    pointerDownOutside(outsideButton as Element);

    await waitFor(() => {
      expect(onOpenChange).toHaveBeenCalledWith(false);
    });
  });
});

import React from "react";
import { render, screen, fireEvent } from "@testing-library/react";
import { describe, it, expect, vi } from "vitest";
import "@testing-library/jest-dom";
import { RadioGroup, RadioGroupItem } from "../radio-group";

// Polyfill ResizeObserver for Radix useSize in jsdom
if (typeof (globalThis as any).ResizeObserver === "undefined") {
  (globalThis as any).ResizeObserver = class {
    observe() {}
    unobserve() {}
    disconnect() {}
  };
}

vi.mock("@core/providers/settings-provider", () => ({
  useSettings: () => ({ radioStyle: "default" }),
}));

describe("RadioGroup and RadioGroupItem", () => {
  it("renders radio group with options and allows selection", () => {
    const onValueChange = vi.fn();

    render(
      <form>
        <RadioGroup value="custom" onValueChange={onValueChange}>
          <div className="flex items-center gap-2">
            <RadioGroupItem value="custom" id="opt-custom" />
            <label htmlFor="opt-custom">Custom Options</label>
          </div>
          <div className="flex items-center gap-2">
            <RadioGroupItem value="optionSet" id="opt-optionSet" />
            <label htmlFor="opt-optionSet">Shared Option Set</label>
          </div>
        </RadioGroup>
      </form>
    );

    const radios = screen.getAllByRole("radio");
    expect(radios).toHaveLength(2);

    expect(radios[0]).toHaveAttribute("data-state", "checked");
    expect(radios[0]).toHaveAttribute("aria-checked", "true");

    expect(radios[1]).toHaveAttribute("data-state", "unchecked");
    expect(radios[1]).toHaveAttribute("aria-checked", "false");

    fireEvent.click(radios[1]);
    expect(onValueChange).toHaveBeenCalledWith("optionSet");
  });

  it("renders Radix hidden bubble input inside form context with aria-hidden", () => {
    const { container } = render(
      <form>
        <RadioGroup value="optionSet">
          <RadioGroupItem value="custom" id="opt-1" />
          <RadioGroupItem value="optionSet" id="opt-2" />
        </RadioGroup>
      </form>
    );

    const hiddenInputs = container.querySelectorAll('input[type="radio"][aria-hidden="true"]');
    expect(hiddenInputs.length).toBeGreaterThanOrEqual(1);

    hiddenInputs.forEach((input) => {
      expect(input).toHaveAttribute("aria-hidden", "true");
      expect(input).toHaveAttribute("tabindex", "-1");
    });
  });
});

// Slider -- aria-label forwarding fix (Wave 3.2 Batch 3, CustomFields Rating).
//
// Radix's own SliderThumb computes its accessible name from ITS OWN
// `aria-label` prop, falling back to a generic library-default "Value" label
// if none is given -- NOT from an `id` passed to `Slider`/`SliderPrimitive.Root`,
// which lands on the Root `<span>` instead (verified directly against
// @radix-ui/react-slider's source before writing this fix: `id` flows into
// Root's own `...sliderProps` spread, never down to Thumb). Before this batch,
// `@core/ui/slider.tsx` never forwarded an `aria-label` to the Thumb at all --
// no consumer anywhere in the app could give a Slider a real per-instance
// accessible name, a latent gap this batch's own CustomFields Rating control
// surfaced (its own renderCustomFieldControl.test.tsx exercises this same fix
// end-to-end; this file pins the primitive's own contract in isolation).
import React from "react";
import { render, screen } from "@testing-library/react";
import { describe, it, expect } from "vitest";
import "@testing-library/jest-dom";
import { Slider } from "../slider";

// jsdom has no ResizeObserver -- @radix-ui/react-use-size's Thumb-sizing
// effect calls it unconditionally on mount (needed for the CSS custom
// properties driving the thumb's in-bounds offset), throwing before a single
// assertion runs otherwise. Same polyfill renderCustomFieldControl.test.tsx
// already carries for GenericSelect's own trigger-width tracking.
if (typeof (globalThis as any).ResizeObserver === "undefined") {
  (globalThis as any).ResizeObserver = class {
    observe() {}
    unobserve() {}
    disconnect() {}
  };
}

describe("Slider", () => {
  it("gives the Thumb a REAL accessible name when aria-label is passed (verified via getByRole, not assumed)", () => {
    render(<Slider aria-label="Rating" value={[3]} min={1} max={5} step={1} />);
    expect(screen.getByRole("slider", { name: "Rating" })).toBeInTheDocument();
  });

  it("does not put the aria-label on the Root -- it must land on the Thumb specifically", () => {
    const { container } = render(
      <Slider aria-label="Rating" value={[3]} min={1} max={5} step={1} />
    );
    // The Root is the outer <span> Radix renders for SliderPrimitive.Root --
    // it must NOT carry the consumer's aria-label (that would be the old,
    // ineffective place to put it: Root has no accessible role a screen
    // reader singles out, only the Thumb's role="slider" does).
    const root = container.firstElementChild;
    expect(root).not.toHaveAttribute("aria-label", "Rating");
    // Exactly one element in the whole tree carries this aria-label: the Thumb.
    expect(container.querySelectorAll('[aria-label="Rating"]')).toHaveLength(1);
  });

  it("is backward compatible: a consumer that passes no aria-label keeps today's default Thumb label, not a broken/undefined one", () => {
    render(<Slider value={[3]} min={1} max={5} step={1} />);
    // Still a real, focusable slider role -- just without a per-instance
    // name. Radix's own library-default fallback label still applies
    // (unchanged behavior for every pre-existing consumer of this component
    // that never passed aria-label).
    const thumb = screen.getByRole("slider");
    expect(thumb).toBeInTheDocument();
  });

  it("reflects min/max/value onto the Thumb's aria-value* attributes", () => {
    render(<Slider aria-label="Rating" value={[4]} min={1} max={5} step={1} />);
    const thumb = screen.getByRole("slider", { name: "Rating" });
    expect(thumb).toHaveAttribute("aria-valuemin", "1");
    expect(thumb).toHaveAttribute("aria-valuemax", "5");
    expect(thumb).toHaveAttribute("aria-valuenow", "4");
  });

  // aria-valuetext forwarding -- the same gap as aria-label, and fixed the same
  // way. Radix computes aria-valuenow/min/max onto the Thumb but has no notion
  // of a human-readable value, and an aria-valuetext left on Root lands on a
  // <span> with no role="slider", so a screen reader announces the bare number
  // where the control means something else ("3 of 5 stars", "Medium").
  it("gives the Thumb a REAL aria-valuetext when one is passed", () => {
    render(
      <Slider aria-label="Rating" aria-valuetext="3 of 5 stars" value={[3]} min={1} max={5} />
    );
    expect(screen.getByRole("slider", { name: "Rating" })).toHaveAttribute(
      "aria-valuetext",
      "3 of 5 stars"
    );
  });

  it("does not leave aria-valuetext on the Root -- it must land on the Thumb specifically", () => {
    const { container } = render(
      <Slider aria-label="Rating" aria-valuetext="3 of 5 stars" value={[3]} min={1} max={5} />
    );
    expect(container.firstElementChild).not.toHaveAttribute("aria-valuetext");
    expect(container.querySelectorAll('[aria-valuetext="3 of 5 stars"]')).toHaveLength(1);
  });

  it("is backward compatible: no aria-valuetext means no attribute at all", () => {
    render(<Slider aria-label="Rating" value={[3]} min={1} max={5} />);
    expect(screen.getByRole("slider", { name: "Rating" })).not.toHaveAttribute("aria-valuetext");
  });

  // The knob's border is the ENTIRE visual boundary of a focusable control, so
  // WCAG 1.4.11 wants 3:1 against both the fill it sits on and the surface
  // behind it. Measured against globals.css: --nx-line-hi (#3f4347 dark,
  // #aeb4ad light) gives 1.95:1 on --nx-surface, 1.64:1 on the knob's own
  // --nx-raised-2, and 2.11:1 on light #ffffff -- the edge was effectively
  // invisible everywhere it appears. --nx-ink-3 gives 6.06:1 / 5.11:1 dark and
  // 4.72:1 / 3.82:1 light against those same pairs. Asserted on the class
  // because jsdom computes no colours; the numbers live in the component's own
  // comment next to the change.
  it("draws the thumb border on a token that clears 3:1 in both themes", () => {
    render(<Slider aria-label="Rating" value={[3]} min={1} max={5} />);
    const thumb = screen.getByRole("slider", { name: "Rating" });
    expect(thumb).toHaveClass("border-nx-ink-3");
    expect(thumb.className).not.toMatch(/(^|\s)border-nx-line-hi(\s|$)/);
  });

  it("still drops the disabled thumb to the quiet hairline -- inert is exempt from 1.4.11", () => {
    render(<Slider aria-label="Rating" value={[3]} min={1} max={5} disabled />);
    const thumb = screen.getByRole("slider", { name: "Rating" });
    expect(thumb).toHaveClass("group-data-[disabled]:border-nx-line");
  });
});

"use client";

/**
 * GenericChart — the LEGACY Chart.js wrapper.
 *
 * New chart work composes the Recharts foundation in `@core/ui/chart`
 * (ChartContainer + the chartColor/--chart-1..8 palette helpers); this
 * wrapper stays only for canvas-rendered Chart.js call sites. Chart.js
 * paints to <canvas>, so CSS var() reads never reach it — every colour in
 * this file is resolved from the computed token values at call time and
 * re-resolved when the theme flips.
 *
 * The chrome follows the same law as the Recharts side: axes, grids and the
 * legend are hairlines and quiet ink, the series is the only loud thing, and
 * nothing on the canvas moves once the entry animation has settled.
 */

import React, { useRef, useEffect, useMemo, useState } from "react";
import { useTheme } from "next-themes";
import { Chart, registerables, ChartConfiguration, ChartOptions, ChartData } from "chart.js";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@core/ui/card";
import { Button } from "@core/ui/button";
import { Checkbox } from "@core/ui/checkbox";
import { EmptyState } from "@core/ui/empty-state";
import { ErrorMessage } from "@core/ui/error-message";
import { BarChart3, Download, Maximize2, RotateCcw, Filter } from "lucide-react";
import { cn } from "@core/common/utils";
import { useI18n } from "@core/providers/i18n-provider";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@core/ui/collapsible";

// Register all Chart.js components
Chart.register(...registerables);

/* Canvas needs literal colour strings, so this resolves an HSL-triplet
   token from the computed styles at call time. The SSR fallback is a
   neutral mid grey; real values arrive on the first client render. Alpha
   goes through the hsl slash channel, never string concatenation. */
const FALLBACK_TRIPLET = "0 0% 50%";

const readToken = (name: string, alpha?: number) => {
  if (typeof window === "undefined") return `hsl(${FALLBACK_TRIPLET})`;
  const triplet =
    getComputedStyle(document.documentElement).getPropertyValue(name).trim() || FALLBACK_TRIPLET;
  return alpha == null ? `hsl(${triplet})` : `hsl(${triplet} / ${alpha})`;
};

/* The --nx- shell tokens hold COMPLETE colour values (#hex / rgba() /
   oklch()), not HSL triplets, so they must not go through readToken's hsl()
   wrapper — wrapping silently produces an invalid colour and Chart.js falls
   back to its own #666 defaults. That is exactly what happened to the legend:
   it carried no colour at all and painted Chart.js grey on the dark ground. */
const readShellToken = (name: string, fallback: string) => {
  if (typeof window === "undefined") return fallback;
  return getComputedStyle(document.documentElement).getPropertyValue(name).trim() || fallback;
};

/* Shared empty default for every optional object prop. A fresh `{}` per render
   changes identity every time, which re-ran the build effect on every render
   and pushed a chart.update() through with it. */
const NO_OVERRIDES = {} as const;

/** One axis of the declared `scales` prop — `false` means "hide this axis". */
type AxisSpec =
  | boolean
  | { display?: boolean; title?: string; stacked?: boolean; beginAtZero?: boolean }
  | undefined;

export interface GenericChartProps {
  title: string;
  description: string;
  data: ChartData;
  options?: ChartOptions;
  type: "line" | "bar" | "pie" | "doughnut" | "radar" | "scatter" | "bubble";
  className?: string;
  exportable?: boolean;
  resizable?: boolean;
  filterable?: boolean;
  onReset?: () => void;
  // Advanced customization options
  height?: number | string;
  width?: number | string;
  theme?: "light" | "dark" | "auto";
  animation?: boolean | { duration?: number; easing?: string };
  responsive?: boolean;
  maintainAspectRatio?: boolean;
  plugins?: {
    legend?: boolean | { position?: "top" | "bottom" | "left" | "right"; display?: boolean };
    tooltip?: boolean | { enabled?: boolean; mode?: string; intersect?: boolean };
    title?: boolean | { display?: boolean; text?: string; position?: string };
  };
  scales?: {
    x?: boolean | { display?: boolean; title?: string; stacked?: boolean };
    y?: boolean | { display?: boolean; title?: string; stacked?: boolean; beginAtZero?: boolean };
  };
  elements?: {
    point?: { radius?: number; hoverRadius?: number; borderWidth?: number };
    line?: { tension?: number; borderWidth?: number };
    bar?: { borderWidth?: number; borderRadius?: number };
  };
  interaction?: {
    mode?: "nearest" | "index" | "point" | "dataset";
    intersect?: boolean;
  };
  // Data transformation options
  dataTransform?: {
    sort?: boolean;
    reverse?: boolean;
    filter?: (item: any) => boolean;
    map?: (item: any) => any;
  };
  // Export options
  exportOptions?: {
    formats?: ("png" | "jpeg" | "pdf" | "svg")[];
    filename?: string;
    quality?: number;
  };
  // Loading and error states
  loading?: boolean;
  error?: string | null;
  onError?: (error: Error) => void;
  // Accessibility
  ariaLabel?: string;
  ariaDescription?: string;
}

export function GenericChart({
  title,
  description,
  data,
  options = NO_OVERRIDES,
  type,
  className,
  exportable = true,
  resizable = true,
  filterable = true,
  onReset,
  height = 400,
  width = "100%",
  // `theme` is inert by design: every colour on this canvas is resolved from
  // the live computed tokens, so the chart already follows next-themes. Kept
  // in the signature so existing call sites keep type-checking.
  theme = "auto",
  animation = true,
  responsive = true,
  maintainAspectRatio = false,
  plugins = NO_OVERRIDES,
  scales = NO_OVERRIDES,
  elements = NO_OVERRIDES,
  interaction = NO_OVERRIDES,
  dataTransform = NO_OVERRIDES,
  exportOptions = NO_OVERRIDES,
  loading = false,
  error = null,
  onError,
  ariaLabel,
  ariaDescription,
}: GenericChartProps) {
  const { t } = useI18n();
  const { resolvedTheme } = useTheme();
  const chartRef = useRef<Chart | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const plotRef = useRef<HTMLDivElement>(null);
  const filterRef = useRef<HTMLDivElement>(null);
  const descriptionId = React.useId();
  // Held in a ref so an inline `onError={…}` at a call site does not give the
  // build effect a new identity on every render. Synced in an effect rather
  // than during render (a render-phase ref write is a side effect): this effect
  // is declared before the build effect, so it commits the latest handler first
  // in the same pass, while `onError` itself stays out of the build deps.
  const onErrorRef = useRef(onError);
  useEffect(() => {
    onErrorRef.current = onError;
  }, [onError]);
  const [isFilterOpen, setIsFilterOpen] = useState(false);
  // Seeded from the real dataset count. Seeding with [] meant every
  // `!visibleDatasets[index]` read `!undefined` on the first render, so a
  // freshly mounted chart drew nothing at all until the dataset count changed.
  const [visibleDatasets, setVisibleDatasets] = useState<boolean[]>(() =>
    new Array(data.datasets?.length ?? 0).fill(true)
  );

  // Handle click outside to close filter. The ref sits on the wrapper, not on
  // the panel, so a mousedown on the trigger itself is "inside" and the
  // disclosure toggles once instead of closing and reopening.
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterRef.current && !filterRef.current.contains(event.target as Node)) {
        setIsFilterOpen(false);
      }
    };
    const handleEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") setIsFilterOpen(false);
    };

    if (isFilterOpen) {
      document.addEventListener("mousedown", handleClickOutside);
      document.addEventListener("keydown", handleEscape);
    }

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      document.removeEventListener("keydown", handleEscape);
    };
  }, [isFilterOpen]);

  // Initialize visible datasets (render-time, no setState in effect)
  const prevDatasetCountRef = useRef(data.datasets?.length ?? 0);
  const datasetCount = data.datasets?.length ?? 0;
  if (datasetCount !== prevDatasetCountRef.current) {
    prevDatasetCountRef.current = datasetCount;
    setVisibleDatasets(new Array(datasetCount).fill(true));
  }

  // Filter datasets based on visibility, and apply the declared dataTransform
  // to each series — sort/reverse/filter/map were part of the published API
  // and were silently ignored.
  const filteredData = useMemo(() => {
    const { sort, reverse, filter, map } = dataTransform;

    const transform = (points: unknown) => {
      if (!Array.isArray(points)) return points;
      let next = points;
      if (filter) next = next.filter(filter);
      if (map) next = next.map(map);
      // Numeric-aware: Array.prototype.sort's default is lexicographic, which
      // orders 10 before 9 and quietly lies about the shape of the series.
      if (sort)
        next = [...next].sort((a, b) =>
          typeof a === "number" && typeof b === "number"
            ? a - b
            : String(a).localeCompare(String(b))
        );
      if (reverse) next = [...next].reverse();
      return next;
    };

    return {
      ...data,
      datasets:
        data.datasets?.map((dataset: any, index: number) => ({
          ...dataset,
          data: transform(dataset.data),
          // `?? true` so a dataset that arrives before the count sync still
          // draws rather than starting life hidden.
          hidden: !(visibleDatasets[index] ?? true),
        })) || [],
    };
  }, [data, visibleDatasets, dataTransform]);

  const handleDatasetToggle = (index: number) => {
    const newVisibleDatasets = [...visibleDatasets];
    newVisibleDatasets[index] = !newVisibleDatasets[index];
    setVisibleDatasets(newVisibleDatasets);
  };

  const toggleAllDatasets = () => {
    const allVisible = visibleDatasets.every((visible) => visible);
    setVisibleDatasets(new Array(data.datasets?.length || 0).fill(!allVisible));
  };

  // ── Which of the four states are we in ───────────────────────────
  // A chart with no series is not a chart with empty axes — it is an empty
  // state, and it says so.
  const hasSeries = (data.datasets ?? []).some(
    (dataset: any) => Array.isArray(dataset?.data) && dataset.data.length > 0
  );
  const status: "error" | "loading" | "empty" | "ready" = error
    ? "error"
    : loading
      ? "loading"
      : hasSeries
        ? "ready"
        : "empty";
  const isReady = status === "ready";

  useEffect(() => {
    const canvas = canvasRef.current;
    // The canvas only exists in the ready state; when it goes away with the
    // chart still alive, the instance is pointing at a detached node.
    if (!canvas) {
      chartRef.current?.destroy();
      chartRef.current = null;
      return;
    }
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const prefersReducedMotion =
      typeof window !== "undefined" &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    // Entry animation: ~300ms, and none at all under reduced motion. The
    // previous 2000ms easeInOutQuart replayed on every rebuild and read as
    // the chart re-drawing itself rather than settling.
    const resolvedAnimation = (
      prefersReducedMotion || animation === false
        ? false
        : {
            duration: 300,
            easing: "easeOutQuart",
            ...(typeof animation === "object" ? animation : {}),
          }
    ) as ChartOptions["animation"];

    // Chrome ink, resolved from the computed token values — which change when
    // the theme does, so resolvedTheme is a real dependency. The previous
    // hardcoded rgba(255,255,255,·) made every axis label invisible in light
    // mode; the legend carried no colour at all.
    const inkPrimary = readShellToken("--nx-ink", readToken("--foreground"));
    const inkLegend = readShellToken("--nx-ink-2", readToken("--muted-foreground"));
    const inkTicks = readShellToken("--nx-ink-3", readToken("--muted-foreground"));
    const hairline = readShellToken("--nx-line", readToken("--border", 0.5));
    const popoverSurface = readShellToken("--nx-popover", readToken("--popover"));

    // Declared-but-ignored props, wired. Each one reads `false` as "off",
    // an object as an override, and anything else as the considered default.
    const legendProp = plugins.legend;
    const legendObject = typeof legendProp === "object" ? legendProp : undefined;
    const tooltipProp = plugins.tooltip;
    const tooltipObject = typeof tooltipProp === "object" ? tooltipProp : undefined;
    const titleProp = plugins.title;
    const titleObject = typeof titleProp === "object" ? titleProp : undefined;

    const axis = (spec: AxisSpec) => {
      const config = typeof spec === "object" && spec !== null ? spec : {};
      return {
        display: spec === false ? false : config.display !== false,
        stacked: config.stacked ?? false,
        ...(config.beginAtZero != null ? { beginAtZero: config.beginAtZero } : {}),
        // Grid lines are the quietest mark on the canvas; the axis border is
        // the same hairline, so the plot frame reads as one weight.
        grid: { color: hairline, drawTicks: false },
        border: { color: hairline },
        ticks: { color: inkTicks, font: { size: 11 }, padding: 8 },
        ...(config.title
          ? {
              title: {
                display: true,
                text: config.title,
                color: inkLegend,
                font: { size: 11, weight: 500 as const },
              },
            }
          : {}),
      };
    };

    // Pie/doughnut have no cartesian axes at all; everything else gets the
    // same hairline frame on both.
    const scaleOptions =
      type === "pie" || type === "doughnut" ? {} : { x: axis(scales.x), y: axis(scales.y) };

    const chartOptions: ChartOptions = {
      responsive,
      maintainAspectRatio,
      plugins: {
        legend: {
          display: legendProp === false ? false : legendObject?.display !== false,
          position: legendObject?.position ?? ("top" as const),
          labels: {
            // A legend is a key, not a headline: quiet ink, normal weight,
            // round point styles that match the series dots.
            color: inkLegend,
            usePointStyle: true,
            pointStyle: "circle" as const,
            boxWidth: 8,
            boxHeight: 8,
            padding: 16,
            font: { size: 12 },
          },
        },
        tooltip: {
          enabled: tooltipProp === false ? false : tooltipObject?.enabled !== false,
          ...(tooltipObject?.mode ? { mode: tooltipObject.mode as "index" } : {}),
          ...(tooltipObject?.intersect != null ? { intersect: tooltipObject.intersect } : {}),
          backgroundColor: popoverSurface,
          titleColor: inkPrimary,
          bodyColor: inkLegend,
          borderColor: hairline,
          borderWidth: 1,
          cornerRadius: 10,
          displayColors: true,
          usePointStyle: true,
          padding: 10,
          titleFont: { size: 12, weight: 500 as const },
          bodyFont: { size: 12 },
        },
        title: {
          display: titleProp === true || titleObject?.display === true,
          text: titleObject?.text ?? "",
          color: inkPrimary,
          font: { size: 13, weight: 500 as const },
        },
      } as ChartOptions["plugins"],
      scales: scaleOptions as ChartOptions["scales"],
      elements: {
        // Restrained marks. The 3px stroke and 0.4 tension this replaces made
        // every series read as a heavy hand-drawn curve — over-smoothing
        // invents inflections the data does not have.
        point: {
          radius: 2.5,
          hoverRadius: 5,
          borderWidth: 2,
          hoverBorderWidth: 2,
          ...elements.point,
        },
        line: { borderWidth: 2, tension: 0.25, ...elements.line },
        bar: { borderRadius: 4, borderWidth: 0, borderSkipped: false, ...elements.bar },
      } as ChartOptions["elements"],
      animation: resolvedAnimation,
      interaction: {
        intersect: false,
        mode: "index",
        ...interaction,
      } as ChartOptions["interaction"],
      ...options,
    };

    // Theme flips and data changes go through chart.update(): the canvas
    // stays alive and Chart.js animates the delta. The old destroy/new on
    // every change blanked the chart and replayed the entry animation.
    // Only a chart-type switch pays the destroy/recreate cost — Chart.js
    // cannot morph type in place.
    const existing = chartRef.current;
    if (existing && (existing.config as { type?: string }).type === type) {
      existing.data = filteredData;
      existing.options = chartOptions;
      existing.update(prefersReducedMotion ? "none" : undefined);
      return;
    }

    existing?.destroy();
    try {
      chartRef.current = new Chart(ctx, {
        type,
        data: filteredData,
        options: chartOptions,
      } as ChartConfiguration);
    } catch (constructionError) {
      // onError was declared and never called; a chart that cannot be built
      // should tell its owner rather than throwing through the render tree.
      chartRef.current = null;
      onErrorRef.current?.(constructionError as Error);
    }
  }, [
    filteredData,
    options,
    type,
    animation,
    responsive,
    maintainAspectRatio,
    resolvedTheme,
    plugins,
    scales,
    elements,
    interaction,
    isReady,
  ]);

  // Destroy only on unmount — the update path above reuses the instance.
  useEffect(() => {
    return () => {
      chartRef.current?.destroy();
      chartRef.current = null;
    };
  }, []);

  const handleExport = () => {
    const chart = chartRef.current;
    if (!chart) return;
    // exportOptions was declared and ignored. png/jpeg are what a canvas can
    // hand back directly; pdf/svg would need a renderer this wrapper does not
    // carry, so they fall through to png rather than silently producing an
    // empty file.
    const requested = exportOptions.formats?.[0];
    const format = requested === "jpeg" ? "jpeg" : "png";
    const quality = exportOptions.quality ?? 1;
    const url = chart.toBase64Image(`image/${format}`, quality);
    const link = document.createElement("a");
    link.download = `${exportOptions.filename ?? title.toLowerCase().replace(/\s+/g, "-")}.${format}`;
    link.href = url;
    link.click();
  };

  const handleMaximize = () => {
    // Fullscreening the bare canvas put the plot on a black void with no
    // title and no axis room. The plot wrapper carries its own surface — and
    // the request rejects whenever the gesture is not user-activated, which
    // used to surface as an unhandled promise rejection.
    const node = plotRef.current;
    if (!node) return;
    void node.requestFullscreen().catch((fullscreenError: Error) => {
      onErrorRef.current?.(fullscreenError);
    });
  };

  const allVisible = visibleDatasets.every((visible) => visible);

  return (
    <Card className={cn("w-full", className)}>
      <CardHeader className="pb-4">
        <div className="flex items-start justify-between gap-4">
          <div className="min-w-0">
            <CardTitle className="truncate text-lg font-semibold">{title}</CardTitle>
            <CardDescription className="mt-1">{description}</CardDescription>
          </div>
          {/* Toolbar. Every control is icon-only, so every control carries a
              name — the four buttons here shipped completely unlabelled. They
              go disabled together whenever there is nothing to act on. */}
          <div className="flex shrink-0 items-center gap-2">
            {filterable && data.datasets && data.datasets.length > 1 && (
              <div className="relative" ref={filterRef}>
                <Collapsible open={isFilterOpen} onOpenChange={setIsFilterOpen}>
                  <CollapsibleTrigger asChild>
                    <Button
                      variant="outline"
                      size="sm"
                      className="h-8 w-8 p-0"
                      aria-label={t("common.filter")}
                      disabled={!isReady}
                    >
                      <Filter className="h-4 w-4" aria-hidden="true" />
                    </Button>
                  </CollapsibleTrigger>
                  <CollapsibleContent className="absolute end-0 top-full z-popover mt-2 w-64 rounded-nx-md border border-nx-line bg-nx-popover p-3 shadow-nx-popover">
                    <div className="space-y-2">
                      <div className="flex items-center justify-between gap-2">
                        <h4 className="text-xs font-medium uppercase tracking-wide text-nx-ink-3">
                          {t("common.filter")}
                        </h4>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={toggleAllDatasets}
                          className="h-8 px-2 text-xs"
                        >
                          {allVisible ? t("common.deselectAll") : t("common.selectAll")}
                        </Button>
                      </div>
                      <div className="border-t border-nx-line pt-1">
                        {data.datasets.map((dataset: any, index: number) => {
                          // The panel doubles as the legend, so each row shows
                          // the swatch it toggles — colour is never the only
                          // signal, the label carries the meaning.
                          const swatch =
                            typeof dataset.borderColor === "string"
                              ? dataset.borderColor
                              : typeof dataset.backgroundColor === "string"
                                ? dataset.backgroundColor
                                : undefined;
                          return (
                            <div
                              key={index}
                              className="flex h-8 items-center gap-2.5 rounded-nx-sm px-1 transition-colors duration-nx-micro ease-nx-enter hover:bg-nx-hover motion-reduce:transition-none"
                            >
                              <Checkbox
                                id={`dataset-${index}`}
                                checked={visibleDatasets[index] ?? true}
                                onCheckedChange={() => handleDatasetToggle(index)}
                              />
                              {swatch && (
                                <span
                                  aria-hidden="true"
                                  className="h-2 w-2 shrink-0 rounded-full"
                                  style={{ backgroundColor: swatch }}
                                />
                              )}
                              <label
                                htmlFor={`dataset-${index}`}
                                className="min-w-0 flex-1 cursor-pointer truncate text-sm leading-none text-nx-ink"
                              >
                                {dataset.label}
                              </label>
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  </CollapsibleContent>
                </Collapsible>
              </div>
            )}
            {exportable && (
              <Button
                variant="outline"
                size="sm"
                onClick={handleExport}
                className="h-8 w-8 p-0"
                aria-label={t("common.download")}
                disabled={!isReady}
              >
                <Download className="h-4 w-4" aria-hidden="true" />
              </Button>
            )}
            {resizable && (
              <Button
                variant="outline"
                size="sm"
                onClick={handleMaximize}
                className="h-8 w-8 p-0"
                aria-label={t("layout.click_to_expand")}
                disabled={!isReady}
              >
                <Maximize2 className="h-4 w-4" aria-hidden="true" />
              </Button>
            )}
            {onReset && (
              <Button
                variant="outline"
                size="sm"
                onClick={onReset}
                className="h-8 w-8 p-0"
                aria-label={t("common.reset")}
              >
                <RotateCcw className="h-4 w-4" aria-hidden="true" />
              </Button>
            )}
          </div>
        </div>
      </CardHeader>
      <CardContent>
        {/* The inline height/width is the in-card size, so fullscreen has to
            override it — hence the important flags on the fullscreen rules. */}
        <div
          ref={plotRef}
          className="relative [&:fullscreen]:!h-full [&:fullscreen]:!w-full [&:fullscreen]:bg-nx-surface [&:fullscreen]:p-6"
          style={{
            height: typeof height === "number" ? `${height}px` : height,
            width: typeof width === "number" ? `${width}px` : width,
          }}
        >
          {status === "error" && (
            <div className="flex h-full flex-col justify-center">
              <ErrorMessage size="sm" message={error ?? t("common.error")} onRetry={onReset} />
            </div>
          )}

          {status === "loading" && <ChartPlaceholder type={type} label={t("common.loading")} />}

          {status === "empty" && (
            <div className="flex h-full flex-col justify-center">
              <EmptyState size="sm" bare icon={BarChart3} title={t("common.noData")} />
            </div>
          )}

          {isReady && (
            <>
              {/* ariaLabel/ariaDescription were declared and destructured but
                  never reached the DOM — the canvas was unlabelled to a reader.
                  The description goes through aria-describedby: aria-description
                  is a draft attribute that most readers still ignore. */}
              <canvas
                ref={canvasRef}
                className="h-full w-full"
                role="img"
                aria-label={ariaLabel ?? title}
                aria-describedby={ariaDescription ? descriptionId : undefined}
              />
              {ariaDescription && (
                <span id={descriptionId} className="sr-only">
                  {ariaDescription}
                </span>
              )}
            </>
          )}
        </div>
      </CardContent>
    </Card>
  );
}

/**
 * The shape of what is coming, held still.
 *
 * A loading chart used to be a blank box. This is the plot frame with the
 * silhouette the chart will actually take — bars for cartesian types, a ring
 * for pie/doughnut — drawn in the raised fill step. Deliberately motionless:
 * a shimmer at rest is the exact idle animation this system does not do.
 */
function ChartPlaceholder({ type, label }: { type: string; label: string }) {
  const isRadial = type === "pie" || type === "doughnut";

  return (
    <div
      role="status"
      aria-label={label}
      className="flex h-full w-full items-center justify-center rounded-nx-md border border-nx-line bg-nx-hover p-4"
    >
      {isRadial ? (
        <span
          aria-hidden="true"
          className="aspect-square h-full max-h-40 rounded-full border-[12px] border-nx-raised-2"
        />
      ) : (
        <span aria-hidden="true" className="flex h-full w-full items-end gap-3">
          {[45, 72, 38, 88, 56, 66].map((barHeight) => (
            <span
              key={barHeight}
              className="flex-1 rounded-nx-sm bg-nx-raised-2"
              style={{ height: `${barHeight}%` }}
            />
          ))}
        </span>
      )}
    </div>
  );
}

/* Categorical palette — reads over the global --chart-1..8 tokens, the same
   slots the Recharts foundation exposes as CHART_TOKEN_PALETTE in
   @core/ui/chart. The getters resolve at read time (browser only), so a
   theme flip re-reads fresh values. The demo-era hex/gradient/monochrome
   sets died with their only consumers, the settings showcase demos. */
const CHART_SLOT_COUNT = 8;

export const GENERIC_COLORS = {
  /** Solid series colours for slots 1..8, resolved to literal hsl() strings. */
  get primary(): string[] {
    return Array.from({ length: CHART_SLOT_COUNT }, (_, i) => readToken(`--chart-${i + 1}`));
  },
  /** The same slots at 25% alpha — soft fills for area/bar backgrounds. */
  get soft(): string[] {
    return Array.from({ length: CHART_SLOT_COUNT }, (_, i) => readToken(`--chart-${i + 1}`, 0.25));
  },
};

// Utility functions for creating Generic chart data
export const ChartUtils = {
  createGradient: (ctx: CanvasRenderingContext2D, color1: string, color2: string) => {
    const gradient = ctx.createLinearGradient(0, 0, 0, 400);
    gradient.addColorStop(0, color1);
    gradient.addColorStop(1, color2);
    return gradient;
  },

  generateData: (count: number, min: number = 0, max: number = 100) => {
    return Array.from({ length: count }, () => Math.floor(Math.random() * (max - min + 1)) + min);
  },

  generateTimeSeriesData: (days: number, baseValue: number = 50) => {
    return Array.from({ length: days }, (_, i) => {
      const trend = Math.sin(i * 0.1) * 20;
      const noise = (Math.random() - 0.5) * 10;
      return Math.max(0, baseValue + trend + noise);
    });
  },
};

/**
 * CodeEditorField — CodeMirror-powered code editor for the Customizer Studio
 *
 * Uses a dual-mode approach:
 * - Compact inline editor in the sidebar (CodeMirror with minimal chrome)
 * - Full-screen modal with tabs, preview, and template snippets
 *
 * Features:
 * - Full syntax highlighting (HTML, CSS)
 * - Line numbers, bracket matching, auto-close
 * - Dark theme matching VS Code
 * - Dual-pane (code + live preview) in modal
 * - Template snippets for quick insertion
 */
"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { cn } from "@/core/common/utils";
import { Code, Eye, X, Maximize2, FileCode2, Copy, Check, Zap } from "lucide-react";
import { useI18n } from "@core/providers/i18n-provider";
