// ── Modal Editor ─────────────────────────────────────────
function CodeEditorModal({
  tabs,
  activeTabId,
  onActiveTabChange,
  showPreview,
  renderPreview,
  onClose,
}: {
  tabs: CodeEditorTab[];
  activeTabId: string;
  onActiveTabChange: (id: string) => void;
  showPreview?: boolean;
  renderPreview?: () => React.ReactNode;
  onClose: () => void;
}) {
  const { t } = useI18n();
  const [showPreviewPane, setShowPreviewPane] = useState(false);
  const [showSnippets, setShowSnippets] = useState(false);
  const [copiedSnippet, setCopiedSnippet] = useState<string | null>(null);
  const activeTab = tabs.find((t) => t.id === activeTabId) || tabs[0];

  // Close on Escape
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [onClose]);

  const handleInsertSnippet = useCallback(
    (code: string) => {
      if (activeTab) {
        const newValue = activeTab.value ? activeTab.value + "\n\n" + code : code;
        activeTab.onChange(newValue);
        setCopiedSnippet(code);
        setTimeout(() => setCopiedSnippet(null), 1500);
      }
    },
    [activeTab]
  );

  const snippets = activeTab?.language === "css" ? CSS_SNIPPETS : HTML_SNIPPETS;

  const editorRef = useCodeMirrorEditor({
    language: activeTab?.language || "html",
    value: activeTab?.value || "",
    onChange: activeTab?.onChange || (() => {}),
    minHeight: "100%",
  });

  // Chrome on tokens, code on the syntax theme. The shell used to hard-code
  // VS Code's palette top to bottom — including a solid blue status bar — so
  // the editor was the one dialog in the product that ignored both the theme
  // and the workspace accent.
  const chromeButton =
    "inline-flex min-h-8 items-center gap-1.5 rounded-nx-sm px-2.5 py-1 text-xs font-medium transition-colors duration-nx-micro ease-nx-enter motion-reduce:transition-none focus-visible:outline-none focus-visible:shadow-nx-focus";

  return createPortal(
    <div
      className="fixed inset-0 z-modal flex items-center justify-center bg-scrim p-4"
      onClick={onClose}
    >
      <div
        role="dialog"
        aria-modal="true"
        aria-label={t("studio.builder.codeEditor")}
        className="flex h-[85vh] max-h-[750px] w-full max-w-[1100px] flex-col overflow-hidden rounded-nx-lg border border-nx-line bg-nx-surface shadow-nx-modal"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="flex items-center justify-between gap-3 border-b border-nx-line bg-nx-raised px-4 py-2.5">
          <div className="flex items-center gap-3">
            <FileCode2 className="h-4 w-4 text-nx-accent" aria-hidden="true" />
            <span className="text-sm font-medium text-nx-ink">
              {t("studio.builder.codeEditor")}
            </span>
            {/* Tabs — the active one carries the surface step and the lit
                bottom edge, the same language as the app's Tabs primitive */}
            <div className="ms-4 flex items-center gap-0.5">
              {tabs.map((tab) => (
                // UI-EXCEPTION: compact studio layout
                <button
                  key={tab.id}
                  onClick={() => {
                    onActiveTabChange(tab.id);
                    setShowPreviewPane(false);
                  }}
                  aria-pressed={activeTabId === tab.id}
                  className={cn(
                    chromeButton,
                    activeTabId === tab.id
                      ? "bg-nx-surface text-nx-ink shadow-[inset_0_-2px_0_0_var(--nx-accent)]"
                      : "text-nx-ink-3 hover:bg-nx-hover hover:text-nx-ink"
                  )}
                >
                  {tab.label}
                </button>
              ))}
            </div>
          </div>
          <div className="flex items-center gap-2">
            {/* Snippets toggle */}
            <button
              onClick={() => setShowSnippets(!showSnippets)}
              aria-pressed={showSnippets}
              className={cn(
                chromeButton,
                showSnippets
                  ? "bg-nx-accent-wash text-nx-accent"
                  : "text-nx-ink-3 hover:bg-nx-hover hover:text-nx-ink"
              )}
            >
              <Zap className="h-3.5 w-3.5" aria-hidden="true" />
              {t("studio.builder.snippets")}
            </button>
            {showPreview && renderPreview && (
              <button
                onClick={() => setShowPreviewPane(!showPreviewPane)}
                aria-pressed={showPreviewPane}
                className={cn(
                  chromeButton,
                  showPreviewPane
                    ? "bg-nx-accent-wash text-nx-accent"
                    : "text-nx-ink-3 hover:bg-nx-hover hover:text-nx-ink"
                )}
              >
                {showPreviewPane ? (
                  <>
                    <Code className="h-3.5 w-3.5" aria-hidden="true" />{" "}
                    {t("studio.builder.codeOnly")}
                  </>
                ) : (
                  <>
                    <Eye className="h-3.5 w-3.5" aria-hidden="true" />{" "}
                    {t("studio.builder.preview")}
                  </>
                )}
              </button>
            )}
            <button
              onClick={onClose}
              className={cn(chromeButton, "px-2 text-nx-ink-3 hover:bg-nx-hover hover:text-nx-ink")}
              aria-label={t("studio.builder.escToClose")}
            >
              <X className="h-4 w-4" aria-hidden="true" />
            </button>
          </div>
        </div>

        {/* Body */}
        <div className="flex flex-1 overflow-hidden">
          {/* Snippets Panel */}
          {showSnippets && (
            <div className="w-64 flex-shrink-0 overflow-y-auto border-e border-nx-line bg-nx-raised">
              <div className="border-b border-nx-line p-3">
                <h3 className="text-xs font-semibold uppercase tracking-wide text-nx-ink-3">
                  {activeTab?.language === "css" ? "CSS" : "HTML"}{" "}
                  {t("studio.builder.templates")}
                </h3>
              </div>
              <div className="space-y-1.5 p-2">
                {snippets.map((s) => (
                  <button
                    key={s.name}
                    onClick={() => handleInsertSnippet(s.code)}
                    className="group w-full rounded-nx-sm px-3 py-2.5 text-start transition-colors duration-nx-micro ease-nx-enter hover:bg-nx-hover focus-visible:shadow-nx-focus focus-visible:outline-none motion-reduce:transition-none"
                  >
                    <div className="flex items-center justify-between gap-2">
                      <span className="text-xs font-medium text-nx-ink">{s.name}</span>
                      {copiedSnippet === s.code ? (
                        <Check className="h-3 w-3 text-nx-success" aria-hidden="true" />
                      ) : (
                        <Copy
                          className="h-3 w-3 text-nx-ink-3 transition-colors duration-nx-micro ease-nx-enter group-hover:text-nx-ink-2 motion-reduce:transition-none"
                          aria-hidden="true"
                        />
                      )}
                    </div>
                    <pre className="mt-1.5 line-clamp-3 whitespace-pre-wrap font-mono text-[11px] leading-relaxed text-nx-ink-3">
                      {s.code.slice(0, 100)}...
                    </pre>
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Editor */}
          <div className="min-w-0 flex-1 overflow-hidden">
            {showPreviewPane && renderPreview ? (
              <div className="flex h-full">
                <div
                  ref={editorRef}
                  className="h-full w-1/2 overflow-auto border-e border-nx-line"
                />
                <div className="h-full w-1/2 overflow-auto bg-nx-ground p-6 text-nx-ink">
                  {renderPreview()}
                </div>
              </div>
            ) : (
              <div ref={editorRef} className="h-full overflow-auto" />
            )}
          </div>
        </div>

        {/* Footer — a status strip, not a blue banner: hairline top edge,
            tertiary ink, tabular line count. */}
        <div className="flex items-center justify-between gap-4 border-t border-nx-line bg-nx-raised px-4 py-2 text-xs text-nx-ink-3">
          <span className="tabular-nums">
            {activeTab?.language.toUpperCase()} • {activeTab?.value?.split("\n").length || 0}{" "}
            {t("studio.builder.lines")}
          </span>
          <span className="truncate">
            {t("studio.builder.escToClose")} •{" "}
            {t("studio.builder.autoSave")}
          </span>
        </div>
      </div>
    </div>,
    document.body
  );
}

// ── Main Component ───────────────────────────────────────
export function CodeEditorField({
  tabs,
  height = 120,
  label,
  description,
  showPreview = false,
  renderPreview,
  className,
}: CodeEditorFieldProps) {
  useModuleLocales(() => import("@modules/customization/studio/locales"), "customization-studio");
  const { t } = useI18n();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [activeTab, setActiveTab] = useState(tabs[0]?.id || "");

  const activeTabData = tabs.find((tab) => tab.id === activeTab) || tabs[0];

  const editorRef = useCodeMirrorEditor({
    language: activeTabData?.language || "html",
    value: activeTabData?.value || "",
    onChange: activeTabData?.onChange || (() => {}),
    placeholderText:
      activeTabData?.language === "html"
        ? '<div class="my-block">\n  <h2>Hello</h2>\n  <p>World</p>\n</div>'
        : ".my-block {\n  color: #fff;\n  padding: 1rem;\n}",
    minHeight: `${height}px`,
  });

  return (
    <div className={cn("space-y-2", className)}>
      {/* Label → hint → control, on the same type ladder as every other field
          (it used to run 10px label / 9px warning-coloured hint) */}
      {label && <span className="text-xs font-medium text-nx-ink-2">{label}</span>}
      {description && <p className="text-xs leading-relaxed text-nx-ink-3">{description}</p>}

      {/* Tab Selector (inline) */}
      {tabs.length > 1 && (
        <div className="flex items-center gap-1 rounded-nx-control border border-nx-line bg-nx-raised p-0.5">
          {tabs.map((tab) => (
            // UI-EXCEPTION: compact studio layout
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              aria-pressed={activeTab === tab.id}
              className={cn(
                "min-h-8 flex-1 rounded-nx-sm px-2 py-1 text-xs font-medium transition-colors duration-nx-micro ease-nx-enter focus-visible:shadow-nx-focus focus-visible:outline-none motion-reduce:transition-none",
                activeTab === tab.id
                  ? "bg-nx-surface text-nx-ink shadow-nx-sm"
                  : "text-nx-ink-3 hover:text-nx-ink"
              )}
            >
              {tab.label}
            </button>
          ))}
        </div>
      )}

      {/* Inline CodeMirror Editor — hairline frame on the field ground; the
          syntax theme paints its own surface inside it */}
      <div
        ref={editorRef}
        className="w-full overflow-hidden rounded-nx-control border border-nx-line bg-nx-ground"
        style={{ maxHeight: height * 1.5 }}
      />

      {/* Open Full Editor — a secondary action, not an accent-washed banner */}
      <button
        onClick={() => setIsModalOpen(true)}
        className="flex min-h-9 w-full items-center justify-center gap-2 rounded-nx-control border border-dashed border-nx-line px-3 py-2 text-xs font-medium text-nx-ink-2 transition-colors duration-nx-micro ease-nx-enter hover:border-nx-line-hi hover:bg-nx-hover hover:text-nx-ink focus-visible:border-nx-accent focus-visible:shadow-nx-focus focus-visible:outline-none motion-reduce:transition-none"
      >
        <Maximize2 className="h-3.5 w-3.5" aria-hidden="true" />
        {t("studio.builder.openEditor")}
      </button>

      {/* CodeMirror Modal */}
      {isModalOpen && (
        <CodeEditorModal
          tabs={tabs}
          activeTabId={activeTab}
          onActiveTabChange={setActiveTab}
          showPreview={showPreview}
          renderPreview={renderPreview}
          onClose={() => setIsModalOpen(false)}
        />
      )}
    </div>
  );
}

"use client";

import React, { useState, useEffect, useCallback, useMemo, useRef } from "react";
import { ChevronLeft, ChevronRight, Calendar, Clock } from "lucide-react";
import {  cn , resolveIntlLocale } from "@core/common/utils";
import { useSettings } from "@core/providers/settings-provider";
import { useI18n } from "@core/providers/i18n-provider";

// Wave C collapse: 6 calendar skins reduce to "default" (the nexus token
// treatment) and "elegant" (the accent take — accent-washed header, the
// signature glow on the selected day). The retired skins were the same grid
// with different wallpaper, so they all read nearest to "default".
export type CalendarVariant = "default" | "elegant";

const LEGACY_CALENDAR_VARIANT: Partial<Record<string, CalendarVariant>> = {
  modern: "default",
  glass: "default",
  minimal: "default",
  dark: "default",
};

// Stored settings can hold values the map no longer knows; unknowns fall back
// to "default" so first paint is always a styled calendar.
export const resolveCalendarVariant = (value: string | null | undefined): CalendarVariant => {
  if (value === "default" || value === "elegant") return value;
  return (value && LEGACY_CALENDAR_VARIANT[value]) || "default";
};

interface CustomCalendarProps {
  value?: string;
  onChange?: (value: string) => void;
  onClose?: () => void;
  type?: "date" | "datetime-local";
  className?: string;
  /** Earliest selectable day (any parseable date string). Additive — undefined keeps every day selectable. */
  minDate?: string;
  /** Latest selectable day (any parseable date string). Additive — undefined keeps every day selectable. */
  maxDate?: string;
  /** Per-day veto for booking-style rules the min/max window cannot express. */
  isDateDisabled?: (date: Date) => boolean;
  /**
   * Move focus into the day grid when this calendar mounts.
   *
   * Opt-in, and `false` by default, because the two consumers are not the same
   * shape. `DatePicker` mounts this component only while its panel is open and
   * portals it to `document.body` — there, taking focus is the whole fix (see
   * the `rovingDay` and focus-management comments below). The Settings preview
   * stage renders a calendar permanently inline as page content; grabbing focus
   * on mount there would hijack the page on every visit.
   */
  autoFocus?: boolean;
}

// Helper: Parse date safely
function parseDateSafe(dateStr: string | null | undefined): Date | null {
  if (!dateStr) return null;
  try {
    const date = new Date(dateStr);
    return isNaN(date.getTime()) ? null : date;
  } catch {
    return null;
  }
}

// Helper: Get locale-aware week start day (0 = Sunday, 6 = Saturday)
function getWeekStartDay(locale: string): number {
  // Arabic/Middle Eastern locales typically start on Saturday (6)
  // Western locales typically start on Sunday (0)
  return locale.startsWith("ar") ? 6 : 0;
}

// Helper: Get locale-aware weekday names
function getWeekDays(locale: string): string[] {
  const formatter = new Intl.DateTimeFormat(locale, { weekday: "short" });
  const weekStart = getWeekStartDay(locale);
  return Array.from({ length: 7 }, (_, i) => {
    const date = new Date(2024, 0, weekStart + i + 1); // Use a fixed week (Jan 2024)
    return formatter.format(date);
  });
}

// Helper: Calculate first day of month adjusted for locale
function getFirstDayOfMonth(date: Date, locale: string): number {
  const firstDay = new Date(date.getFullYear(), date.getMonth(), 1).getDay();
  const localeStart = getWeekStartDay(locale);
  return (firstDay - localeStart + 7) % 7;
}

export function CustomCalendar({
  value = "",
  onChange,
  onClose,
  type = "date",
  className,
  minDate,
  maxDate,
  isDateDisabled,
  autoFocus = false,
}: CustomCalendarProps) {
  const { calendarStyle, borderRadius } = useSettings();
  const { t, language, direction } = useI18n();

  const locale = resolveIntlLocale(language);
  const variant = resolveCalendarVariant(calendarStyle);

  // Safe date initialization
  const [currentDate, setCurrentDate] = useState(() => {
    const parsed = parseDateSafe(value);
    return parsed || new Date();
  });

  const [selectedDate, setSelectedDate] = useState<Date | null>(parseDateSafe(value));

  const [selectedTime, setSelectedTime] = useState(() => {
    if (value && type === "datetime-local") {
      const parts = value.split("T");
      return parts[1]?.split(":")?.slice(0, 2).join(":") || "12:00";
    }
    return "12:00";
  });

  const [viewMode, setViewMode] = useState<"calendar" | "month" | "year">("calendar");
  const [focusedDate, setFocusedDate] = useState<number | null>(null);

  const [yearRangeStart, setYearRangeStart] = useState(() => {
    const currentYear = new Date().getFullYear();
    return Math.floor((currentYear - 12) / 10) * 10;
  });

  const calendarContainerRef = useRef<HTMLDivElement>(null);
  const gridRef = useRef<HTMLDivElement>(null);

  // Reset view mode when value changes
  useEffect(() => {
    queueMicrotask(() => {
      if (value) {
        const parsed = parseDateSafe(value);
        if (parsed) {
          setCurrentDate(parsed);
          setSelectedDate(parsed);
          if (type === "datetime-local") {
            const parts = value.split("T");
            if (parts[1]) {
              setSelectedTime(parts[1].split(":")?.slice(0, 2).join(":") || "12:00");
            }
          }
        }
      }
      setViewMode("calendar");
      setFocusedDate(null);
    });
  }, [value, type]);

  // ── Selectable-range guard ──────────────────────────────
  // Day-granular: minDate clamps to the start of its day, maxDate to the end,
  // and the predicate gets the candidate day for booking-style veto rules.

  const minDateObj = useMemo(() => {
    const d = parseDateSafe(minDate);
    if (d) d.setHours(0, 0, 0, 0);
    return d;
  }, [minDate]);

  const maxDateObj = useMemo(() => {
    const d = parseDateSafe(maxDate);
    if (d) d.setHours(23, 59, 59, 999);
    return d;
  }, [maxDate]);

  const isDisabledDate = useCallback(
    (date: Date): boolean => {
      if (minDateObj && date < minDateObj) return true;
      if (maxDateObj && date > maxDateObj) return true;
      return isDateDisabled ? isDateDisabled(date) : false;
    },
    [minDateObj, maxDateObj, isDateDisabled]
  );

  // Memoize months array (remove duplicate)
  const months = useMemo(
    () => [
      t("months.jan"),
      t("months.feb"),
      t("months.mar"),
      t("months.apr"),
      t("months.may"),
      t("months.jun"),
      t("months.jul"),
      t("months.aug"),
      t("months.sep"),
      t("months.oct"),
      t("months.nov"),
      t("months.dec"),
    ],
    [t]
  );

  // Get locale-aware weekdays
  const weekDays = useMemo(() => getWeekDays(locale), [locale]);

  // The Settings borderRadius, mapped onto the nx radius ladder — same ladder
  // as the trigger it drops out of, so the two corners agree.
  const borderRadiusClass = useMemo(() => {
    switch (borderRadius) {
      case "none":
        return "rounded-none";
      case "small":
        return "rounded-nx-sm";
      case "large":
      case "full":
        return "rounded-nx-lg";
      default:
        return "rounded-nx-md";
    }
  }, [borderRadius]);

  // The calendar surface. Border and shadow belong to the popover wrapper in
  // date-picker (the only consumer) — doubling them here drew a seam.
  const calendarStyles = useMemo(
    () => cn("w-full bg-nx-popover", borderRadiusClass),
    [borderRadiusClass]
  );

  const headerStyles =
    variant === "elegant"
      ? "p-4 border-b border-nx-line bg-nx-accent-wash"
      : "p-4 border-b border-nx-line";

  // Every day cell is a 40px target with tabular figures, so the grid columns
  // line up whatever the digits are. Four states, four distinct readings:
  //   unavailable  ink-3 + a strike, so a blocked booking day is legible at a
  //                glance instead of being a slightly paler number
  //   selected     the accent fill (elegant adds the ONE signature glow)
  //   today        an accent lit EDGE, not a fill — today is a marker, the
  //                selection is the statement, and the two must never look
  //                the same
  //   other-month  ink-3, hover lifts it one ink step
  const getButtonStyles = useCallback(
    (isSelected = false, isToday = false, isOtherMonth = false, isDisabled = false) => {
      const baseStyles = cn(
        "flex h-10 w-10 items-center justify-center rounded-nx-sm text-sm tabular-nums",
        "transition-[color,background-color,box-shadow] duration-nx-micro ease-nx-enter motion-reduce:transition-none",
        "focus-visible:outline-none focus-visible:shadow-nx-focus",
        "disabled:cursor-not-allowed disabled:hover:bg-transparent"
      );

      if (isDisabled) {
        return cn(baseStyles, "text-nx-ink-3 line-through decoration-1");
      }

      if (isSelected) {
        return cn(
          baseStyles,
          "bg-nx-accent-fill font-semibold text-nx-on-fill",
          // the signature glow — the selected day is elegant's ONE lit element
          variant === "elegant" ? "shadow-nx-glow" : ""
        );
      }

      if (isToday) {
        return cn(
          baseStyles,
          "font-semibold text-nx-accent shadow-[inset_0_0_0_1px_var(--nx-accent)] hover:bg-nx-accent-wash"
        );
      }

      if (isOtherMonth) {
        return cn(baseStyles, "text-nx-ink-3 hover:bg-nx-hover hover:text-nx-ink-2");
      }

      return cn(baseStyles, "text-nx-ink hover:bg-nx-hover");
    },
    [variant]
  );

  // The time field is a field: same sunken ground, same hover lift, same lit
  // edge as every Input in the product.
  const timeInputStyles = cn(
    "h-10 w-full rounded-nx-control border border-nx-line bg-nx-ground px-3 py-2 text-sm tabular-nums text-nx-ink",
    "outline-none transition-[border-color,box-shadow] duration-nx-micro ease-nx-enter motion-reduce:transition-none",
    "hover:border-nx-line-hi focus-visible:border-nx-accent focus-visible:shadow-nx-focus"
  );

  // Shared chrome for the header/nav/footer controls — same focus law as the
  // day grid, hover on the ink-derived tint, and a 32px minimum box so a month
  // step is a real pointer target rather than a 16px chevron.
  const controlButtonStyles =
    "inline-flex min-h-8 items-center justify-center rounded-nx-sm transition-colors duration-nx-micro ease-nx-enter motion-reduce:transition-none hover:bg-nx-hover focus-visible:outline-none focus-visible:shadow-nx-focus";

  const getDaysInMonth = useCallback((date: Date) => {
    return new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
  }, []);

  const getFirstDayAdjusted = useCallback(
    (date: Date) => {
      return getFirstDayOfMonth(date, locale);
    },
    [locale]
  );

  // Format date using local time components
  const formatDateLocal = useCallback((date: Date): string => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");
    return `${year}-${month}-${day}`;
  }, []);

  // Resolve the actual Date a grid cell represents (other-month cells belong
  // to the adjacent month; day > 15 in an other-month cell means "previous").
  const resolveCellDate = useCallback(
    (day: number, isOtherMonth = false): Date => {
      if (isOtherMonth) {
        // Set to first day of month before shifting to avoid overflow edge cases
        const tempDate = new Date(currentDate.getFullYear(), currentDate.getMonth(), 1);
        tempDate.setMonth(tempDate.getMonth() + (day > 15 ? -1 : 1));
        return new Date(tempDate.getFullYear(), tempDate.getMonth(), day);
      }
      return new Date(currentDate.getFullYear(), currentDate.getMonth(), day);
    },
    [currentDate]
  );

  // ── The day grid's single tab stop ──────────────────────────────
  //
  // A roving tabindex is only reachable if EXACTLY ONE cell carries
  // tabIndex={0} in every state. This grid used to manage none and sometimes
  // two.
  //
  // NONE was the blocker: `isFocused` was `focusedDate === day || (!focusedDate
  // && isSelected)`, `focusedDate` starts null, and an EMPTY date field has no
  // selected day — so every cell in the month rendered tabIndex={-1}. Nothing
  // focused the panel on open either, and `DatePicker` portals it to
  // document.body, so Tab from the field walked straight past the whole
  // calendar into the page behind it. The window keydown listener below only
  // reacts to events whose target is already inside the calendar, which nothing
  // could ever become. Net effect: an empty Date / DateTime field could not be
  // set by keyboard at all.
  //
  // TWO was the quieter bug: `focusedDate === day` compared day NUMBERS with no
  // regard for which month the cell belongs to, so a `focusedDate` of 3 lit
  // both the current month's 3rd and the trailing "3" borrowed from the next
  // month. Other-month cells are now pinned to -1 unconditionally: they are
  // never the roving target, because the arrow keys step the month first and
  // only then focus the day, by which point it belongs to the current month.
  //
  // This is derived rather than an effect that seeds `focusedDate`, so there is
  // no render in which the grid has no tab stop, and no ordering question
  // between the seed and the keyboard handler that reads it.
  const rovingDay = useMemo(() => {
    const daysInMonth = getDaysInMonth(currentDate);
    const isInView = (date: Date) =>
      date.getMonth() === currentDate.getMonth() &&
      date.getFullYear() === currentDate.getFullYear();

    let preferred: number;
    if (focusedDate !== null) {
      preferred = focusedDate;
    } else if (selectedDate && isInView(selectedDate)) {
      preferred = selectedDate.getDate();
    } else {
      const today = new Date();
      preferred = isInView(today) ? today.getDate() : 1;
    }
    // A month step can leave `focusedDate` past the end of a shorter month
    // (the 31st, then PageDown into February).
    preferred = Math.min(Math.max(preferred, 1), daysInMonth);

    // `disabled` outranks tabIndex: a disabled <button> is not focusable, so a
    // roving target parked on a blocked day (a future minDate, a booking veto)
    // would leave the grid unreachable all over again. Walk out to the nearest
    // selectable day — forward first, because a min-bounded window opens that
    // way.
    if (!isDisabledDate(resolveCellDate(preferred))) return preferred;
    for (let step = 1; step < daysInMonth; step++) {
      const after = preferred + step;
      if (after <= daysInMonth && !isDisabledDate(resolveCellDate(after))) return after;
      const before = preferred - step;
      if (before >= 1 && !isDisabledDate(resolveCellDate(before))) return before;
    }
    // Nothing in this month is selectable. Keep the preferred cell as the tab
    // stop so the state stays deterministic; the header's month/year controls
    // and the footer buttons are still reachable, which is how the user gets
    // to a month that has something in it.
    return preferred;
  }, [currentDate, focusedDate, selectedDate, getDaysInMonth, isDisabledDate, resolveCellDate]);

  // Submit the selected date and time
  const submitDateAndTime = useCallback(
    (dateToSubmit: Date) => {
      if (type === "date") {
        const dateString = formatDateLocal(dateToSubmit);
        onChange?.(dateString);
        onClose?.();
      } else {
        const dateString = `${formatDateLocal(dateToSubmit)}T${selectedTime}`;
        onChange?.(dateString);
        onClose?.();
      }
    },
    [type, selectedTime, formatDateLocal, onChange, onClose]
  );

  const handleDateSelect = useCallback(
    (day: number, isOtherMonth = false) => {
      const newDate = resolveCellDate(day, isOtherMonth);
      if (isDisabledDate(newDate)) return;

      setSelectedDate(newDate);
      setFocusedDate(day);

      if (type === "date") {
        const dateString = formatDateLocal(newDate);
        onChange?.(dateString);
        onClose?.();
      } else {
        const dateString = `${formatDateLocal(newDate)}T${selectedTime}`;
        onChange?.(dateString);
      }
    },
    [resolveCellDate, isDisabledDate, type, selectedTime, formatDateLocal, onChange, onClose]
  );

  const handleDateDoubleClick = useCallback(
    (day: number, isOtherMonth = false) => {
      const newDate = resolveCellDate(day, isOtherMonth);
      if (isDisabledDate(newDate)) return;

      setSelectedDate(newDate);
      submitDateAndTime(newDate);
    },
    [resolveCellDate, isDisabledDate, submitDateAndTime]
  );

  const handleTimeChange = useCallback(
    (time: string) => {
      setSelectedTime(time);
      if (selectedDate) {
        const dateString = `${formatDateLocal(selectedDate)}T${time}`;
        onChange?.(dateString);
      }
    },
    [selectedDate, formatDateLocal, onChange]
  );

  // Navigate month - FIX: Handle edge case (Jan 31 -> Feb)
  const navigateMonth = useCallback((direction: "prev" | "next") => {
    setCurrentDate((prev) => {
      const newDate = new Date(prev);
      // Set to first day to avoid month overflow issues
      newDate.setDate(1);
      if (direction === "prev") {
        newDate.setMonth(prev.getMonth() - 1);
      } else {
        newDate.setMonth(prev.getMonth() + 1);
      }
      return newDate;
    });
    setViewMode("calendar");
    setFocusedDate(null);
  }, []);

  const handleMonthClick = useCallback(() => {
    setViewMode("month");
    setFocusedDate(null);
  }, []);

  const handleYearClick = useCallback(() => {
    setViewMode("year");
    setFocusedDate(null);
    const currentYear = currentDate.getFullYear();
    setYearRangeStart(Math.floor((currentYear - 12) / 10) * 10);
  }, [currentDate]);

  const handleMonthSelect = useCallback((monthIndex: number) => {
    setCurrentDate((prev) => {
      const newDate = new Date(prev);
      // Fix edge case: set to first day before changing month
      newDate.setDate(1);
      newDate.setMonth(monthIndex);
      return newDate;
    });
    setViewMode("calendar");
    setFocusedDate(null);
  }, []);

  const handleYearSelect = useCallback(
    (year: number) => {
      setCurrentDate((prev) => {
        const newDate = new Date(prev);
        newDate.setDate(1); // Set to first day to avoid month overflow
        newDate.setFullYear(year);
        return newDate;
      });
      if (year < yearRangeStart || year >= yearRangeStart + 12) {
        setYearRangeStart(Math.floor((year - 6) / 12) * 12);
      }
      setViewMode("calendar");
      setFocusedDate(null);
    },
    [yearRangeStart]
  );

  const navigateYearRange = useCallback((direction: "prev" | "next") => {
    setYearRangeStart((prev) => (direction === "prev" ? prev - 12 : prev + 12));
  }, []);

  // Keyboard navigation
  const getDateByOffset = useCallback(
    (offset: number): { day: number; isOtherMonth: boolean } | null => {
      const daysInMonth = getDaysInMonth(currentDate);
      const firstDay = getFirstDayAdjusted(currentDate);
      // The arrows step from the cell that actually holds the tab stop. This
      // read used to be `focusedDate || selectedDate?.getDate() || 1`, which
      // disagreed with the rendered grid whenever `focusedDate` was null: on an
      // empty field the visible tab stop is today, but the first arrow press
      // jumped as if from the 1st.
      const today = rovingDay;

      const totalDays = Math.ceil((firstDay + daysInMonth) / 7) * 7;
      const currentIndex = firstDay + (today - 1);
      const newIndex = currentIndex + offset;

      if (newIndex < 0) {
        // Previous month
        const prevMonth = new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 0);
        const daysInPrevMonth = prevMonth.getDate();
        const day = daysInPrevMonth + newIndex + 1;
        return { day: Math.max(1, day), isOtherMonth: true };
      } else if (newIndex >= totalDays) {
        // Next month
        const day = newIndex - totalDays + 1;
        return { day, isOtherMonth: true };
      } else if (newIndex < firstDay) {
        // Previous month (within current view)
        const prevMonth = new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 0);
        const daysInPrevMonth = prevMonth.getDate();
        const day = daysInPrevMonth - (firstDay - newIndex - 1);
        return { day, isOtherMonth: true };
      } else if (newIndex >= firstDay + daysInMonth) {
        // Next month (within current view)
        const day = newIndex - (firstDay + daysInMonth) + 1;
        return { day, isOtherMonth: true };
      } else {
        // Current month
        const day = newIndex - firstDay + 1;
        return { day, isOtherMonth: false };
      }
    },
    [currentDate, rovingDay, getDaysInMonth, getFirstDayAdjusted]
  );

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent | KeyboardEvent) => {
      if (viewMode !== "calendar") {
        if (e.key === "Escape") {
          e.preventDefault();
          setViewMode("calendar");
        }
        return;
      }

      const daysInMonth = getDaysInMonth(currentDate);

      switch (e.key) {
        case "ArrowLeft":
          e.preventDefault();
          const leftDate = getDateByOffset(-1);
          if (leftDate) {
            if (leftDate.isOtherMonth) {
              navigateMonth("prev");
              setTimeout(() => setFocusedDate(leftDate.day), 0);
            } else {
              setFocusedDate(leftDate.day);
              handleDateSelect(leftDate.day, false);
            }
          }
          break;

        case "ArrowRight":
          e.preventDefault();
          const rightDate = getDateByOffset(1);
          if (rightDate) {
            if (rightDate.isOtherMonth) {
              navigateMonth("next");
              setTimeout(() => setFocusedDate(rightDate.day), 0);
            } else {
              setFocusedDate(rightDate.day);
              handleDateSelect(rightDate.day, false);
            }
          }
          break;

        case "ArrowUp":
          e.preventDefault();
          const upDate = getDateByOffset(-7);
          if (upDate) {
            if (upDate.isOtherMonth) {
              if (upDate.day > 15) {
                navigateMonth("prev");
              } else {
                navigateMonth("next");
              }
              setTimeout(() => setFocusedDate(upDate.day), 0);
            } else {
              setFocusedDate(upDate.day);
              handleDateSelect(upDate.day, false);
            }
          }
          break;

        case "ArrowDown":
          e.preventDefault();
          const downDate = getDateByOffset(7);
          if (downDate) {
            if (downDate.isOtherMonth) {
              if (downDate.day > 15) {
                navigateMonth("prev");
              } else {
                navigateMonth("next");
              }
              setTimeout(() => setFocusedDate(downDate.day), 0);
            } else {
              setFocusedDate(downDate.day);
              handleDateSelect(downDate.day, false);
            }
          }
          break;

        case "Home":
          e.preventDefault();
          setFocusedDate(1);
          handleDateSelect(1, false);
          break;

        case "End":
          e.preventDefault();
          setFocusedDate(daysInMonth);
          handleDateSelect(daysInMonth, false);
          break;

        case "PageUp":
          e.preventDefault();
          navigateMonth("prev");
          break;

        case "PageDown":
          e.preventDefault();
          navigateMonth("next");
          break;

        case "Enter":
        case " ":
          e.preventDefault();
          if (selectedDate && !isDisabledDate(selectedDate)) {
            submitDateAndTime(selectedDate);
          }
          break;

        case "Escape":
          e.preventDefault();
          onClose?.();
          break;
      }
    },
    [
      viewMode,
      currentDate,
      selectedDate,
      getDaysInMonth,
      getDateByOffset,
      navigateMonth,
      handleDateSelect,
      isDisabledDate,
      submitDateAndTime,
      onClose,
    ]
  );

  // Keyboard event listener
  useEffect(() => {
    const handleWindowKeyDown = (event: KeyboardEvent) => {
      if (calendarContainerRef.current?.contains(event.target as Node)) {
        handleKeyDown(event as any);
      }
    };

    window.addEventListener("keydown", handleWindowKeyDown);
    return () => window.removeEventListener("keydown", handleWindowKeyDown);
  }, [handleKeyDown]);

  const renderCalendarDays = useCallback(() => {
    const daysInMonth = getDaysInMonth(currentDate);
    const firstDay = getFirstDayAdjusted(currentDate);
    const today = new Date();
    const days = [];

    // Previous month's trailing days
    const prevMonth = new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 0);
    const daysInPrevMonth = prevMonth.getDate();

    for (let i = firstDay - 1; i >= 0; i--) {
      const day = daysInPrevMonth - i;
      const dateKey = `prev-${day}`;
      const cellDisabled = isDisabledDate(resolveCellDate(day, true));
      days.push(
        <button
          key={dateKey}
          onClick={() => handleDateSelect(day, true)}
          onDoubleClick={() => handleDateDoubleClick(day, true)}
          onKeyDown={handleKeyDown}
          className={getButtonStyles(false, false, true, cellDisabled)}
          aria-label={`${day} ${t("common.ofPreviousMonth")}, ${months[prevMonth.getMonth()]} ${prevMonth.getFullYear()}`}
          aria-disabled={cellDisabled || undefined}
          disabled={cellDisabled}
          role="gridcell"
          // Never the roving target — see the `rovingDay` comment.
          tabIndex={-1}
          data-day={day}
          data-other-month="true"
        >
          {day}
        </button>
      );
    }

    // Current month's days
    for (let day = 1; day <= daysInMonth; day++) {
      const isSelected = selectedDate
        ? selectedDate.getDate() === day &&
          selectedDate.getMonth() === currentDate.getMonth() &&
          selectedDate.getFullYear() === currentDate.getFullYear()
        : false;

      const isToday =
        today.getDate() === day &&
        today.getMonth() === currentDate.getMonth() &&
        today.getFullYear() === currentDate.getFullYear();

      // Exactly one current-month cell is the tab stop, in every state.
      const isFocused = day === rovingDay && viewMode === "calendar";

      const cellDisabled = isDisabledDate(resolveCellDate(day));

      days.push(
        <button
          key={day}
          onClick={() => handleDateSelect(day)}
          onDoubleClick={() => handleDateDoubleClick(day)}
          onKeyDown={handleKeyDown}
          className={getButtonStyles(isSelected, isToday, false, cellDisabled)}
          aria-label={`${day} ${months[currentDate.getMonth()]} ${currentDate.getFullYear()}${isToday ? `, ${t("common.today")}` : ""}`}
          aria-current={isSelected ? "date" : undefined}
          aria-disabled={cellDisabled || undefined}
          disabled={cellDisabled}
          role="gridcell"
          tabIndex={isFocused ? 0 : -1}
          data-day={day}
        >
          {day}
        </button>
      );
    }

    // Next month's leading days
    const totalCells = Math.ceil((firstDay + daysInMonth) / 7) * 7;
    const remainingCells = totalCells - (firstDay + daysInMonth);

    for (let day = 1; day <= remainingCells; day++) {
      const dateKey = `next-${day}`;
      const cellDisabled = isDisabledDate(resolveCellDate(day, true));
      days.push(
        <button
          key={dateKey}
          onClick={() => handleDateSelect(day, true)}
          onDoubleClick={() => handleDateDoubleClick(day, true)}
          onKeyDown={handleKeyDown}
          className={getButtonStyles(false, false, true, cellDisabled)}
          aria-label={`${day} ${t("common.ofNextMonth")}, ${months[(currentDate.getMonth() + 1) % 12]} ${currentDate.getMonth() === 11 ? currentDate.getFullYear() + 1 : currentDate.getFullYear()}`}
          aria-disabled={cellDisabled || undefined}
          disabled={cellDisabled}
          role="gridcell"
          // Never the roving target — see the `rovingDay` comment.
          tabIndex={-1}
          data-day={day}
          data-other-month="true"
        >
          {day}
        </button>
      );
    }

    return days;
  }, [
    currentDate,
    selectedDate,
    rovingDay,
    viewMode,
    getDaysInMonth,
    getFirstDayAdjusted,
    months,
    getButtonStyles,
    handleDateSelect,
    handleDateDoubleClick,
    handleKeyDown,
    isDisabledDate,
    resolveCellDate,
    t,
  ]);

  // ── Focus follows the tab stop ──────────────────────────────────
  //
  // A roving tabindex only works if DOM focus and the tab stop move together.
  // Three cases, and each is a real one:
  //
  //   1. On open (`autoFocus`) nothing in the panel had focus. This is the half
  //      of the blocker that tabIndex alone cannot fix: `DatePicker` portals the
  //      panel to document.body, so without moving focus here Tab from the field
  //      goes to the page behind the calendar and the window keydown listener
  //      above — which only reacts to targets already inside the calendar —
  //      never fires for anything.
  //   2. While the grid already holds focus, an arrow key changes `rovingDay`;
  //      the previously focused cell has just dropped to tabIndex={-1} and focus
  //      has to follow, or the ring and the tab stop drift apart.
  //   3. A month step (PageUp/PageDown, or an arrow crossing the edge) unmounts
  //      the focused cell, which parks activeElement on <body>. Nobody owns
  //      focus then, so reclaiming it is safe — and it is the only way keyboard
  //      navigation survives a month boundary.
  //
  // Case 3 is gated on having focused the grid at least once, so the inline
  // Settings-stage calendar (autoFocus={false}, never focused) cannot grab focus
  // off a quiet page. And because the reclaim requires activeElement to be body
  // or inside the grid, a focus trap that pulls focus elsewhere — a Radix modal
  // Dialog hosting this picker — is left alone rather than fought over.
  const gridOwnsFocusRef = useRef(false);

  useEffect(() => {
    if (viewMode !== "calendar") return;
    const grid = gridRef.current;
    if (!grid) return;

    const cell = grid.querySelector<HTMLElement>(
      `[data-day="${rovingDay}"]:not([data-other-month])`
    );
    if (!cell) return;

    const active = document.activeElement;
    const focusIsInGrid = !!active && grid.contains(active);
    if (focusIsInGrid) gridOwnsFocusRef.current = true;

    const shouldTakeFocusOnOpen = autoFocus && !gridOwnsFocusRef.current;
    const mayReclaimFocus =
      gridOwnsFocusRef.current && (focusIsInGrid || !active || active === document.body);
    if (!shouldTakeFocusOnOpen && !mayReclaimFocus) return;

    gridOwnsFocusRef.current = true;
    if (active !== cell) cell.focus();
    // `currentDate` is a dependency even though it is not read directly: a month
    // step can land on the SAME rovingDay number in a different month, and case
    // 3 above still has to run for the newly mounted cell.
  }, [autoFocus, viewMode, rovingDay, currentDate]);

  // RTL-aware navigation icons
  // In RTL: left button = next (→), right button = previous (←)
  // In LTR: left button = previous (←), right button = next (→)
  const PrevIcon = direction === "rtl" ? ChevronRight : ChevronLeft;
  const NextIcon = direction === "rtl" ? ChevronLeft : ChevronRight;

  return (
    <div
      ref={calendarContainerRef}
      data-calendar-content="true"
      className={cn(calendarStyles, "h-full min-w-[320px]", className)}
      tabIndex={-1}
      role="application"
      aria-label={t("common.calendar")}
    >
      {/* Header */}
      <div className={headerStyles}>
        <div className="flex items-center justify-between">
          <button
            onClick={() => {
              if (viewMode === "year") {
                navigateYearRange("prev");
              } else {
                navigateMonth("prev");
              }
            }}
            className={cn(controlButtonStyles, "p-1 text-nx-ink-2 hover:text-nx-ink")}
            aria-label={
              viewMode === "year" ? t("common.previousYearRange") : t("common.previousMonth")
            }
          >
            <PrevIcon className="h-4 w-4" aria-hidden="true" />
          </button>

          <div className="flex items-center gap-2">
            <Calendar className="h-4 w-4 text-nx-accent" aria-hidden="true" />
            <div className="flex items-center gap-1">
              <button
                onClick={handleMonthClick}
                className={cn(controlButtonStyles, "px-2 py-1 text-sm font-semibold text-nx-ink")}
                aria-label={t("common.selectMonth")}
                aria-expanded={viewMode === "month"}
              >
                {months[currentDate.getMonth()]}
              </button>
              <button
                onClick={handleYearClick}
                className={cn(controlButtonStyles, "px-2 py-1 text-sm font-semibold text-nx-ink")}
                aria-label={t("common.selectYear")}
                aria-expanded={viewMode === "year"}
              >
                {currentDate.getFullYear()}
              </button>
            </div>
          </div>

          <button
            onClick={() => {
              if (viewMode === "year") {
                navigateYearRange("next");
              } else {
                navigateMonth("next");
              }
            }}
            className={cn(controlButtonStyles, "p-1 text-nx-ink-2 hover:text-nx-ink")}
            aria-label={
              viewMode === "year" ? t("common.nextYearRange") : t("common.nextMonth")
            }
          >
            <NextIcon className="h-4 w-4" aria-hidden="true" />
          </button>
        </div>
      </div>

      {/* Calendar/Month/Year View */}
      <div className="p-4">
        {viewMode === "calendar" && (
          <>
            {/* Week Days */}
            <div className="mb-2 grid grid-cols-7 gap-1" role="row">
              {weekDays.map((day, index) => (
                <div
                  key={index}
                  className="flex h-10 w-10 items-center justify-center text-xs font-medium text-nx-ink-3"
                  role="columnheader"
                  aria-label={day}
                >
                  {day}
                </div>
              ))}
            </div>

            {/* Calendar Days */}
            <div
              ref={gridRef}
              className="grid grid-cols-7 gap-1"
              role="grid"
              aria-label={`${months[currentDate.getMonth()]} ${currentDate.getFullYear()}`}
            >
              {renderCalendarDays()}
            </div>
          </>
        )}

        {viewMode === "month" && (
          <div
            className="grid grid-cols-3 gap-2"
            role="listbox"
            aria-label={t("common.selectMonth")}
          >
            {months.map((month, index) => {
              const isSelected = currentDate.getMonth() === index;
              return (
                <button
                  key={index}
                  onClick={() => handleMonthSelect(index)}
                  onKeyDown={handleKeyDown}
                  className={cn(
                    "h-12 rounded-nx-control px-3 text-sm font-medium",
                    "transition-[color,background-color] duration-nx-micro ease-nx-enter motion-reduce:transition-none",
                    "focus-visible:shadow-nx-focus focus-visible:outline-none",
                    isSelected
                      ? "bg-nx-accent-fill font-semibold text-nx-on-fill"
                      : "text-nx-ink hover:bg-nx-hover"
                  )}
                  role="option"
                  aria-selected={isSelected}
                  aria-label={month}
                >
                  {month}
                </button>
              );
            })}
          </div>
        )}

        {viewMode === "year" && (
          <>
            <div
              className="mb-2 grid grid-cols-4 gap-2"
              role="listbox"
              aria-label={t("common.selectYear")}
            >
              {Array.from({ length: 12 }, (_, i) => {
                const year = yearRangeStart + i;
                const isSelected = currentDate.getFullYear() === year;
                const isCurrentYear = new Date().getFullYear() === year;
                return (
                  <button
                    key={year}
                    onClick={() => handleYearSelect(year)}
                    onKeyDown={handleKeyDown}
                    className={cn(
                      "h-12 rounded-nx-control px-3 text-sm font-medium tabular-nums",
                      "transition-[color,background-color,box-shadow] duration-nx-micro ease-nx-enter motion-reduce:transition-none",
                      "focus-visible:shadow-nx-focus focus-visible:outline-none",
                      isSelected
                        ? "bg-nx-accent-fill font-semibold text-nx-on-fill"
                        : isCurrentYear
                          ? // the current year gets the same lit edge as today
                            // in the day grid — one language for "you are here"
                            "font-semibold text-nx-accent shadow-[inset_0_0_0_1px_var(--nx-accent)] hover:bg-nx-accent-wash"
                          : "text-nx-ink hover:bg-nx-hover"
                    )}
                    role="option"
                    aria-selected={isSelected}
                    aria-label={year.toString()}
                  >
                    {year}
                  </button>
                );
              })}
            </div>
            {/* Range stepper — the arrows are the SAME RTL-aware icons the
                month nav uses, not `←`/`→` glyphs picked by a direction
                ternary. Digits are tabular so the two ranges stay the same
                width as the decade rolls. */}
            <div className="mt-2 flex items-center justify-between gap-2 border-t border-nx-line pt-2">
              <button
                onClick={() => navigateYearRange("prev")}
                onKeyDown={handleKeyDown}
                className={cn(
                  controlButtonStyles,
                  "gap-1 px-2 py-1 text-xs tabular-nums text-nx-ink-2 hover:text-nx-ink"
                )}
                aria-label={`${yearRangeStart - 12} - ${yearRangeStart - 1}`}
              >
                <PrevIcon className="h-3 w-3" aria-hidden="true" />
                {yearRangeStart - 12} – {yearRangeStart - 1}
              </button>
              <span className="text-xs tabular-nums text-nx-ink-2" aria-live="polite">
                {yearRangeStart} – {yearRangeStart + 11}
              </span>
              <button
                onClick={() => navigateYearRange("next")}
                onKeyDown={handleKeyDown}
                className={cn(
                  controlButtonStyles,
                  "gap-1 px-2 py-1 text-xs tabular-nums text-nx-ink-2 hover:text-nx-ink"
                )}
                aria-label={`${yearRangeStart + 12} - ${yearRangeStart + 23}`}
              >
                {yearRangeStart + 12} – {yearRangeStart + 23}
                <NextIcon className="h-3 w-3" aria-hidden="true" />
              </button>
            </div>
          </>
        )}
      </div>

      {/* Time Picker for datetime-local */}
      {type === "datetime-local" && (
        <div className="border-t border-nx-line p-4">
          <div className="mb-2 flex items-center gap-2">
            <Clock className="h-4 w-4 text-nx-accent" aria-hidden="true" />
            <label htmlFor="time-input" className="text-sm font-medium text-nx-ink">
              {t("common.time")}
            </label>
          </div>
          <input
            id="time-input"
            type="time"
            value={selectedTime}
            onChange={(e) => handleTimeChange(e.target.value)}
            className={timeInputStyles}
            aria-label={t("common.selectTime")}
          />
        </div>
      )}

      {/* Action Buttons */}
      <div className="flex justify-end gap-2 border-t border-nx-line p-4">
        <button
          onClick={onClose}
          onKeyDown={handleKeyDown}
          className={cn(controlButtonStyles, "px-3 py-1.5 text-sm text-nx-ink-2 hover:text-nx-ink")}
          aria-label={t("common.cancel")}
        >
          {t("common.cancel")}
        </button>
        {type === "datetime-local" && (
          <button
            onClick={() => {
              if (selectedDate && !isDisabledDate(selectedDate)) {
                const dateString = `${formatDateLocal(selectedDate)}T${selectedTime}`;
                onChange?.(dateString);
              }
              onClose?.();
            }}
            onKeyDown={handleKeyDown}
            className={cn(
              // hover lights the top inner edge instead of fading the fill —
              // opacity math on a filled control reads as "disabled", not "hot"
              "inline-flex min-h-8 items-center rounded-nx-control bg-nx-accent-fill px-3 py-1.5 text-sm font-medium text-nx-on-fill",
              "transition-shadow duration-nx-micro ease-nx-enter motion-reduce:transition-none",
              "hover:shadow-[inset_0_1px_0_0_color-mix(in_srgb,var(--nx-on-fill)_35%,transparent)]",
              "focus-visible:shadow-nx-focus focus-visible:outline-none"
            )}
            aria-label={t("common.ok")}
          >
            {t("common.ok")}
          </button>
        )}
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import * as DialogPrimitive from "@radix-ui/react-dialog";
import { X } from "lucide-react";

import { cn } from "@core/common/utils";
import { useI18n } from "@core/providers/i18n-provider";

const Dialog = DialogPrimitive.Root;

const DialogTrigger = DialogPrimitive.Trigger;

const DialogPortal = DialogPrimitive.Portal;

const DialogClose = DialogPrimitive.Close;

/* ── The overlay family's shared surface language ────────────────────────────
 *
 * Dialog, AlertDialog and Sheet are one object seen from three angles, so they
 * read from the recipes below instead of three near-identical class strings
 * that drift apart on the next edit. They already had drifted: the sheet ran a
 * 500ms enter against the dialog's 200ms, and each file re-typed the scrim.
 *
 * Exported so alert-dialog.tsx and sheet.tsx compose them rather than copy
 * them. The strings stay literal (never assembled from fragments at runtime)
 * because Tailwind scans source text for class names.
 */

/** ONE scrim for the whole app: the token wash on the named overlay step of
 *  the z ladder. Split out from the animated variant below because vaul's
 *  drawer fades the scrim itself, tracking the drag — it needs the paint
 *  without the keyframes, and `animate-none` cannot switch the keyframes off
 *  (the `data-[state=open]:` variant carries an extra attribute selector, so
 *  it outranks a bare utility). */
export const overlayScrimSurfaceClasses = "fixed inset-0 z-overlay bg-scrim";

/** The scrim plus its fade on the token pair — 200ms in, ~2/3 out. A fade is
 *  the one movement reduced motion keeps, so no motion-safe split is needed. */
export const overlayScrimClasses = `${overlayScrimSurfaceClasses} duration-nx-standard ease-nx-enter data-[state=closed]:duration-nx-micro data-[state=closed]:ease-nx-exit data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0`;

/** The floating panel itself: nx popover surface behind a hairline, the modal
 *  step of the shadow ladder (these genuinely float, so a shadow is earned),
 *  and the 24px inset every modal in the product shares. */
export const modalSurfaceClasses =
  "gap-4 border-nx-line bg-nx-popover p-6 text-nx-ink shadow-nx-modal";

/** Enter 200ms on the enter curve, exit at the ~2/3 micro step on the exit
 *  curve. No bounce, no spring — the panel arrives and leaves, it does not
 *  perform. */
export const modalMotionClasses =
  "duration-nx-standard ease-nx-enter data-[state=closed]:duration-nx-micro data-[state=closed]:ease-nx-exit data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=open]:fade-in-0 data-[state=closed]:fade-out-0";

/** The dismiss affordance shared by Dialog and Sheet.
 *
 *  Was a bare 16px glyph on `opacity-70 hover:opacity-100` — a 16px hit target
 *  (half the 32px floor), opacity math instead of ink tokens, and a
 *  `data-[state=open]` pair cargo-culted from the *trigger*: a Close button has
 *  no open state, so those two classes could never match anything. Now a real
 *  32px control that picks up a hover tint and the lit-edge focus ring. */
export const overlayCloseButtonClasses =
  "absolute end-4 top-4 inline-flex h-8 w-8 items-center justify-center rounded-nx-sm text-nx-ink-3 transition-colors duration-nx-micro ease-nx-enter motion-reduce:transition-none hover:bg-nx-hover hover:text-nx-ink focus-visible:text-nx-ink focus-visible:outline-none focus-visible:shadow-nx-focus disabled:pointer-events-none disabled:text-nx-ink-3";

/** Header column shared by every overlay: real hierarchy (title, then a
 *  quieter description) and an inline-end inset so a long title never runs
 *  under the close button. Start-aligned at every width — the shadcn
 *  `text-center sm:text-left` default centres exactly the strings that read
 *  worst centred (long titles, RTL) and flips alignment mid-breakpoint. */
export const overlayHeaderClasses = "flex flex-col gap-1.5 pe-8 text-start";

/** ONE action-bar order for the whole family, so muscle memory transfers
 *  between a Dialog, an AlertDialog and a Sheet:
 *
 *    DOM order = cancel/secondary first, primary last.
 *
 *  At >= sm that puts the primary on the inline-end edge (justify-end and
 *  flex-end both follow the writing direction, so RTL is free). Below sm the
 *  column reverses, which stacks the primary on TOP where the thumb is. */
export const overlayFooterClasses =
  "flex flex-col-reverse gap-2 sm:flex-row sm:items-center sm:justify-end";

/**
 * Wheel/touch scroll-chain guard for a hand-rolled non-modal scrim.
 *
 * Radix's own scroll lock (react-remove-scroll) only mounts inside
 * DialogOverlayImpl, and DialogOverlay itself renders nothing at all when
 * the Root is `modal={false}` (`context.modal ? <DialogOverlayImpl/> : null`
 * in @radix-ui/react-dialog) — see GenericModal's own comment
 * (generic-modal.tsx) for the first place this was worked out. Every
 * non-modal dialog that re-adds its own scrim in place of Radix's therefore
 * has to re-supply this too: without it, a wheel/touch gesture over the
 * scrim scroll-chains straight into the page behind it. React's
 * root-delegated wheel/touch handlers are passive and cannot cancel, so this
 * attaches a real, non-passive pair directly to the scrim node; it dies with
 * the node when the portal unmounts.
 */
export function useScrimScrollLock() {
  return React.useCallback((node: HTMLDivElement | null) => {
    if (!node) return;
    const cancelScroll = (event: Event) => event.preventDefault();
    node.addEventListener("wheel", cancelScroll, { passive: false });
    node.addEventListener("touchmove", cancelScroll, { passive: false });
  }, []);
}

/**
 * The hand-rolled scrim itself, factored out so every `modal={false}` dialog
 * in the family (GenericModal today; InlineAddCustomFieldDialog and its
 * handful of hand-rolled hosts as of Wave 5 row 5.6) renders the exact same
 * recipe instead of a fifth near-identical copy. Not wired into GenericModal
 * itself — that component's scrim predates this extraction and stays as-is
 * (its own deliberate `modal={false}` choice is not to be disturbed) — but
 * every *new* non-modal dialog should reach for this rather than re-deriving
 * it.
 *
 * Render this as a sibling of Content inside the same Portal, exactly where
 * Radix's own Overlay would go — it fully replaces that overlay, it is not
 * layered alongside it.
 */
export function NonModalScrim({ open }: { open: boolean }) {
  const lockScrimScroll = useScrimScrollLock();
  return (
    <div
      ref={lockScrimScroll}
      aria-hidden="true"
      data-state={open ? "open" : "closed"}
      className={overlayScrimClasses}
    />
  );
}

const DialogOverlay = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Overlay>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Overlay>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Overlay
    ref={ref}
    // The scrim pushes the page back by taking light away, not by blurring it.
    // This previously applied backdrop-blur twice — once through Tailwind and
    // once through an inline style added to survive purging — which is the
    // single most expensive thing to put under a modal on a low-end device,
    // and an explicit ban in DESIGN.md ("no glassmorphism as default").
    className={cn(overlayScrimClasses, className)}
    {...props}
  />
));
DialogOverlay.displayName = DialogPrimitive.Overlay.displayName;

interface DialogContentProps extends React.ComponentPropsWithoutRef<
  typeof DialogPrimitive.Content
> {
  /**
   * "drawer" pins the panel to the inline-end edge and slides it in from
   * there. Consumers used to smuggle this in through className (right-edge
   * plus important-translate positional overrides) and the component sniffed
   * the strings back out — an explicit variant replaces that contract, and
   * the slide follows the writing direction instead of being welded to the
   * right edge.
   */
  variant?: "default" | "drawer";
}

const DialogContent = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Content>,
  DialogContentProps
>(({ className, children, dir, variant = "default", onFocusOutside, ...props }, ref) => {
  const { t, direction } = useI18n();
  const isRtl = (dir || direction) === "rtl";

  const positionClasses =
    variant === "drawer"
      ? cn(
          "fixed inset-y-0 end-0 z-modal grid w-full max-w-lg rounded-s-nx-lg border-s",
          modalSurfaceClasses,
          modalMotionClasses,
          // tailwindcss-animate slides are physical, so the logical end edge
          // resolves against the live direction here. motion-safe keeps only
          // the crossfade under reduced motion.
          isRtl
            ? "motion-safe:data-[state=open]:slide-in-from-left motion-safe:data-[state=closed]:slide-out-to-left"
            : "motion-safe:data-[state=open]:slide-in-from-right motion-safe:data-[state=closed]:slide-out-to-right"
        )
      : cn(
          // The gutter is deliberate: `w-full` let the panel butt against both
          // viewport edges on a phone, which is also why the corners had to be
          // square below sm. With 16px of air on each side the large radius
          // token applies at every width and the panel reads as an object.
          "fixed left-[50%] top-[50%] z-modal grid w-[calc(100%-2rem)] max-w-lg translate-x-[-50%] translate-y-[-50%] rounded-nx-lg border",
          modalSurfaceClasses,
          modalMotionClasses,
          // The 1/2 and 48% "slides" are the centering, not decoration: while
          // a tailwindcss-animate animation runs, its keyframe transform
          // replaces the translate utilities above, so the counter-translate
          // must ride inside the animation vars. They stay outside motion-safe
          // on purpose — dropping them under reduced motion would make the
          // panel jump to the corner, not calm down. Only the zoom is motion.
          "motion-safe:data-[state=open]:zoom-in-95 motion-safe:data-[state=closed]:zoom-out-95 data-[state=open]:slide-in-from-left-1/2 data-[state=open]:slide-in-from-top-[48%] data-[state=closed]:slide-out-to-left-1/2 data-[state=closed]:slide-out-to-top-[48%]"
        );

  return (
    <DialogPortal>
      <DialogOverlay />
      <DialogPrimitive.Content
        ref={ref}
        dir={dir ?? direction}
        aria-describedby={props["aria-describedby"] ?? undefined}
        className={cn(positionClasses, className)}
        /* ── Focus is NOT suppressed here, and that is deliberate ────────────
         *
         * This file used to prevent BOTH `onOpenAutoFocus` and
         * `onCloseAutoFocus` ("prevent auto focus to allow dropdown inputs to
         * work"). The stated goal was real — a body-portalled select or
         * date-picker search input must be able to take focus out of the panel —
         * but the two preventDefaults were not what delivered it, and each one
         * broke something load-bearing. Traced through the installed Radix
         * sources rather than assumed:
         *
         *   onCloseAutoFocus. DialogContentModal composes the consumer handler
         *   with its own `(event) => { event.preventDefault();
         *   context.triggerRef.current?.focus(); }`, and composeEventHandlers
         *   skips the second handler once the first has called preventDefault.
         *   So preventing it here did not merely skip FocusScope's restore — it
         *   deleted Radix's trigger refocus too. Close a dialog and focus was
         *   simply gone: nothing selected, keyboard position lost, next Tab
         *   starting from the top of the document. DialogContentNonModal has the
         *   same shape, so `modal={false}` hosts (GenericModal and friends) lost
         *   it as well.
         *
         *   onOpenAutoFocus. FocusScope focuses its first tabbable candidate on
         *   mount only if that event was not default-prevented, and its trap
         *   re-focuses `lastFocusedElementRef`, which is only ever assigned from
         *   a focusin landing INSIDE the content. Prevented, the panel started
         *   out owning no focus and the ref stayed null, so the trap had nothing
         *   to pull focus back to. Meanwhile DialogContentModal still calls
         *   `hideOthers(content)` — the rest of the page IS aria-hidden. The net
         *   state was the worst of both: a screen-reader user left outside the
         *   dialog, on a page hidden from them, Tab walking a hidden document.
         *
         * What actually keeps body-portalled inputs alive is three things, none
         * of which is autofocus suppression:
         *
         *   1. `modal={false}` on the Root. Every dialog in this product that
         *      hosts form fields sets it (GenericModal, plus the hand-rolled
         *      hosts that re-add their own scrim — see NonModalScrim above).
         *      Non-modal mode passes `trapFocus: false` and skips hideOthers
         *      outright, so there is no trap to escape from in the first place.
         *      GenericModal's own comment has said exactly this all along.
         *   2. The `onInteractOutside` / `onPointerDownOutside` allow-lists just
         *      below, and the unconditional `onFocusOutside` veto further down.
         *      Those are what stop a live portal from DISMISSING the dialog,
         *      which is what the original bug report actually described.
         *   3. For a genuinely modal dialog, Radix's own layering: every
         *      Popover/Select/DropdownMenu content mounts its own FocusScope,
         *      and focusScopesStack.add() PAUSES the dialog's scope while it is
         *      open. So a GenericSelect panel inside a modal dialog keeps its
         *      search input focused without any help from this file.
         *
         * Known limit, recorded rather than papered over: a HAND-ROLLED body
         * portal (DatePicker's calendar) inside a genuinely modal DialogContent
         * mounts no FocusScope, so it never pauses the dialog's trap and focus
         * is pulled back to the dialog. That is not a regression from this
         * change — the trap already engaged as soon as the user focused anything
         * inside the dialog — and the answer for form-hosting dialogs is
         * `modal={false}`, which is what they all use. Fixing it for the modal
         * case would mean changing where DatePicker portals to, which would
         * break its fixed-position maths under the dialog's own transform.
         *
         * A consumer that genuinely needs different behaviour still overrides
         * both handlers through {...props} below (DocsSearch does).
         */
        onInteractOutside={(e) => {
          // Allow interaction with dropdown portals (Select, DatePicker, etc.)
          const target = e.target as Element;
          if (
            target.closest("[data-dropdown-portal]") ||
            target.closest("[data-searchable-select]") ||
            target.closest("[data-date-picker]") ||
            target.closest("[data-radix-popper-content-wrapper]") ||
            target.closest("[role='listbox']") ||
            target.closest("[role='option']")
          ) {
            e.preventDefault();
          }
        }}
        onPointerDownOutside={(e) => {
          // Block closing for non-left clicks (e.g., right-click)
          const orig = (e as any).detail?.originalEvent as PointerEvent | MouseEvent | undefined;
          const button = (orig && "button" in orig ? (orig as any).button : 0) as number;
          if (button !== 0) {
            e.preventDefault();
          }
          // Allow interaction with dropdown portals (Select, DatePicker, etc.)
          const target = e.target as Element;
          if (
            target.closest("[data-dropdown-portal]") ||
            target.closest("[data-searchable-select]") ||
            target.closest("[data-date-picker]") ||
            target.closest("[data-radix-popper-content-wrapper]") ||
            target.closest("[role='listbox']") ||
            target.closest("[role='option']")
          ) {
            e.preventDefault();
          }
        }}
        {...props}
        // A dialog is NEVER dismissed by focus movement — only by pointer-down
        // on the scrim, Escape, or an explicit Close.
        //
        // This is exactly what Radix's own DialogContentModal does. GenericModal
        // opts out of MODAL MODE with modal={false} (deliberately: the focus trap
        // breaks the body-portalled select and date-picker search inputs), which
        // means react-dismissable-layer's undeferred `focusin` listener is live
        // there and fired on the FIRST focus event anywhere outside, dismissing
        // the dialog instantly.
        //
        // The concrete symptom: opening Edit / Assign-to-groups from a table row
        // menu closed the form the moment the menu's exit animation finished and
        // it restored focus to the row's trigger button. The allow-list this
        // replaces only covered six dropdown-portal selectors, and a <Button>
        // inside a <td> matched none of them.
        //
        // THIS handler — not the autofocus suppression that used to sit above —
        // is what keeps a live body-portalled panel from closing the dialog it
        // was opened from. That distinction is the whole point of the block
        // above; do not re-conflate them.
        //
        // Deliberately placed AFTER {...props}: a consumer's own handler still
        // runs (composed below) but cannot re-open this dismissal channel. The
        // other handlers stay before {...props} so consumers keep overriding
        // them — PaymentWallDialog relies on that to stay non-dismissible, and
        // DocsSearch passes its own (now redundant) open/close autofocus
        // handlers through the same channel.
        onFocusOutside={(e) => {
          onFocusOutside?.(e);
          e.preventDefault();
        }}
      >
        {children}
        {/* type="button" so a dialog wrapping a <form> cannot submit it by
            dismissing. The label reads from the existing common.close key —
            it was a hardcoded English string that screen readers announced
            untranslated in the Arabic build. */}
        <DialogPrimitive.Close type="button" className={overlayCloseButtonClasses}>
          <X className="h-4 w-4" aria-hidden="true" />
          <span className="sr-only">{t("common.close")}</span>
        </DialogPrimitive.Close>
      </DialogPrimitive.Content>
    </DialogPortal>
  );
});
