const MEDIA_FILE: FieldConfig = {
  name: "__cf__waiver",
  label: "Waiver",
  type: "media-file",
  referenceTargetEntityTypeKey: "media.file",
};
const MEDIA_IMAGE: FieldConfig = {
  name: "__cf__photo",
