  getCustomFieldsExtension,
  decodeCustomFieldName,
  type CustomFieldFormControlProps,
} from "@core/crud/customFieldsExtension";

/**
 * Field option for select, radio, and other choice-based inputs
 */
export interface FieldOption {
  /** The value of the option (submitted to backend) */
  value: string;
  /** The display label for the option */
  label: string;
  /** Whether this option is disabled */
  disabled?: boolean;
  /** Nested options for hierarchical structures (e.g., tree selects) */
  children?: FieldOption[];
  /** Unique key for deduplication when value may change between API calls */
  uniqueKey?: string;
}

/**
 * Configuration object for form fields
 *
 * Defines the structure and behavior of individual form fields,
 * including validation, styling, and conditional logic.
 */
export interface FieldConfig {
  name: string;
  label?: string; // Optional for hidden fields
  type:
    | "text"
    | "password"
    | "email"
    | "number"
    // Wave 3.3 Batch C (CustomFields' Currency/Duration value types).
    // "currency" backs a real, dedicated CurrencyCustomFieldControl (a
    // paired amount + ISO 4217 code control -- see that file's own header
    // comment for why Currency could not simply reuse "number" the way
    // Percent does: two independently required pieces need two inputs, not
    // one). "duration" backs DurationCustomFieldControl (a number input with
    // an explicit, localized "minutes" unit annotation -- reusing bare
    // "number" here would make Duration indistinguishable from
    // Number/Percent inside that shared dispatcher, and re-introduce PD-2's
    // "a bare number whose unit is implicit" ambiguity at the UI layer).
    //
    // THIS COMPONENT DOES DRAW BOTH, through the same extension registry
    // "entity-reference" below goes through -- see
    // `EXTENSION_DRAWN_FIELD_TYPES`. The claim that used to stand here ("not
    // consumed by this component's own render switch ... none of them mounts
    // a <GenericForm> over these fields") was true of the 8 hand-wired
    // CustomFields sites and false of everything else: generic-crud-view.tsx
    // concatenates the extension's own fieldConfigs into the `fields` it
    // hands <GenericForm>, so on the ~30 CrudConfig sites that declare an
    // `entityTypeKey` both types genuinely reached the switch, missed it, and
    // fell through to `<Input type={field.type} value={formData[name] ?? ""}>`
    // -- a text box that painted a Currency object as `[object Object]` and
    // replaced it with a string on the first keystroke, exactly the defect
    // "entity-reference" was fixed for.
    //
    // Only "currency" is object-valued, so only it needs a required-emptiness
    // rule of its own (`OBJECT_VALUED_EMPTINESS_CHECKS`). "duration" is a
    // plain minutes number, and the pre-existing scalar arm already treats a
    // stored `0` as filled -- which is the answer the backend wants, since
    // DurationValueTypeHandler accepts zero and only rejects negatives.
    | "currency"
    | "duration"
    // Wave 4 (CustomFields' EntityReference/UserReference value types). Both
    // map here: they differ only in which target entity type their picker is
    // fed, which is data, not a control kind.
    //
    // THIS COMPONENT DOES DRAW IT, but never by importing the control. Earlier
    // waves left this type with no render arm on purpose -- the control needs
    // the CustomFields module (the entity-lookup search/resolve hooks, which
    // reach that module's DI container), `core` must not import from
    // `src/modules/*` (docs/architecture/01-modularity.md's Dependency Rule),
    // and a direct import would additionally close a runtime cycle
    // (generic-form -> control -> module DI -> valueTypeRegistry ->
    // generic-form) and pull the whole CustomFields data layer into every form
    // in the product. That comment named the honest route itself, and this is
    // it: `CustomFieldsExtensionApi.FieldControl`, reached through the same
    // registry every other module capability arrives by. See
    // `EXTENSION_DRAWN_FIELD_TYPES` and `CustomFieldExtensionControl` below.
    //
    // Leaving the arm out was not a neutral "later": custom-field FieldConfigs
    // genuinely reach this component (generic-crud-view.tsx concatenates
    // useCustomFieldsFormFields's fieldConfigs into the `fields` it hands
    // <GenericForm>, and `visibleFields` filters only on isVisible/permissions),
    // so an unhandled type fell through to the plain `<Input type={field.type}>`
    // default -- a text box showing `[object Object]` that replaced the stored
    // object with a string the moment anyone typed in it.
    //
    // It is also in the required-validation `customTypes` set below: a required
    // reference submitted blank has to be caught in this path too, and a
    // reference value is an object, which the old emptiness check waved through
    // -- see `isRequiredFieldEmpty` below.
    | "entity-reference"
    // Wave 3.4 (CustomFields' File/Image/RichText value types). All three are
    // EXTENSION-DRAWN, like "entity-reference" above and for the same
    // Dependency-Rule reason: their controls live in the CustomFields module and
    // `core` must not import from `src/modules/*`.
    //
    // WHY THREE NEW MEMBERS RATHER THAN REUSING "file", "image" AND "richtext",
    // which already exist a few lines below and already render. Because all
    // three of those render arms produce a DIFFERENT VALUE SHAPE than these
    // types accept, and this component's own history is the argument: the
    // `[object Object]` defect "entity-reference" was added to fix was exactly a
    // custom-field type routed to an arm whose value shape did not match.
    //   - "file" renders `<Input type="file">`, whose value is a browser `File`.
    //   - "image" renders `<ImageUploader>`, whose value is a base64 string.
    //   - "richtext" renders `<RichTextEditor value={formData[name] ?? ""}
    //     onChange={(value) => handleChange(name, value)}>`, i.e. a bare string.
    // A File/Image value is `{ entityTypeKey, entityId }` -- a reference to a
    // media row -- and a RichText value is `{ html }`. The server refuses each of
    // the three wrong shapes outright (RichText's refusal is deliberate: the
    // input-sanitization middleware's carve-out for the values route is the PATH
    // `values.*.html`, so a bare string arrives with every tag already stripped
    // and storing it would silently destroy the operator's markup). So pointing
    // at the existing member would not be a shortcut, it would ship a field that
    // 422s on every save on the ~30 CrudConfig screens where this component
    // draws custom fields itself.
    //
    // Adding the new types TO the existing members' render arms was the other
    // option and is worse: it would make those three arms permanently dead and
    // permanently seize the three most generically-named members of this union
    // for "a reference to a media row" and "prose in an object envelope", so a
    // real upload field could never use them again.
    //
    // "media-file" and "media-image" are TWO members, not one shared media key,
    // because both value types pin the same target entity type and nothing else
    // carries the image-only restriction -- see the catalog entries in the
    // CustomFields module for the full reasoning. Both are object-valued, so
    // both need an `OBJECT_VALUED_EMPTINESS_CHECKS` rule; "rich-text" is object-
    // valued too and needs its own, since a blank `{ html: "" }` envelope is an
    // unfilled field.
    | "media-file"
    | "media-image"
    | "rich-text"
    | "phone"
    | "tel"
    | "url"
    | "textarea"
    | "bilingual-options"
    | "richtext"
    | "select"
    | "searchable-select"
    | "server-select"
    | "multi-select"
    | "tree"
    | "switch"
    | "checkbox"
    | "radio"
    | "slider"
    | "range"
    | "hidden"
    | "date"
    | "datetime"
    | "datetime-local"
    | "time"
    | "month"
    | "week"
    | "color"
    | "file"
    | "image";
  placeholder?: string;
  searchPlaceholder?: string; // For searchable selects
  defaultCountry?: string; // For phone/tel inputs (ISO country code e.g. "EG", "SA", "US")
  required?: boolean | ((formData: Record<string, any>) => boolean);
  options?: FieldOption[];
  treeData?: FieldOption[]; // For tree select type
  defaultValue?: any;
  // Input specific options
  min?: number | string; // For number, date, range inputs
  max?: number | string; // For number, date, range inputs
  step?: number | string; // For number, range inputs
  /**
   * For "bilingual-options": the form key holding the SECOND (Arabic) newline-separated list. The
   * control edits both halves together and writes both keys, because the two are positionally
   * aligned and editing one without the other would misalign every option after the edit.
   */
  pairedName?: string;
  rows?: number; // For textarea
  cols?: number; // For textarea
  /** For "bilingual-options": the "add another option" button's label. */
  addLabel?: string;
  /** For "bilingual-options": the per-row remove button's accessible label. */
  removeLabel?: string;
  /** For "bilingual-options": the hint shown when no options exist yet. */
  emptyHint?: string;
  /**
   * For "entity-reference": the entity type the field's DEFINITION is pinned to, i.e. what the
   * picker should offer. Absent/null means the definition does not say, which is a real state (an
   * unpinned EntityReference accepts any registered entity type, so there is no single answer) and
   * not merely an unwired one.
   *
   * A CARRIER ONLY — this component never reads it, and still does not: the whole `field` is handed
   * to `CustomFieldsExtensionApi.FieldControl` (or to renderCustomFieldControl.tsx at the 8
   * hand-wired sites), and the pin is read there, because the control needs the CustomFields module
   * and `core` must not import from `src/modules/*` — see the `"entity-reference"` member's own
   * comment above. Passing `field` whole rather than unpacked scalars is exactly what keeps this
   * carrier working without a new prop on the extension contract.
   * The field travels here rather than in a module-side side-channel because `FieldConfig[]` IS the
   * boundary type the extension hands across that line; a parallel map keyed by field name would
   * have to be threaded through every one of the nine consumer sites separately.
   *
   * NOT consulted by `isRequiredFieldEmpty`, on purpose: whether a reference is filled is a question
   * about the VALUE's two pieces, and a pin says nothing about whether the user picked anything.
   */
  referenceTargetEntityTypeKey?: string | null;
  accept?: string; // For file inputs and image uploader
  multiple?: boolean; // For file inputs and multi-select
  // Image uploader specific options
  maxSize?: number; // Max file size in bytes (default: 5MB)
  showPreview?: boolean; // Whether to show image preview (default: true)
  aspectRatio?: string; // e.g., "16/9", "1/1"
  // Searchable select specific options
  searchType?: "client" | "server";
  onServerSearch?: (query: string) => Promise<FieldOption[]>;
  searchEndpoint?: string;
  debounceMs?: number;
  allowClear?: boolean;
  noResultsText?: string;
  searchingText?: string;
  // Dynamic field behavior
  dependsOn?: string; // Field name this field depends on
  isVisible?: (formData: Record<string, any>) => boolean; // Function to determine visibility
  onChange?: (value: any, formData: Record<string, any>) => void | Record<string, any>; // Callback when field value changes, can return object to update multiple fields
  loading?: boolean; // Show loading state
  disabled?: boolean; // Disable field
  // Validation
  pattern?: string; // For text inputs
  patternError?: string; // Custom error message when pattern fails
  minLength?: number; // For text inputs
  maxLength?: number; // For text inputs
  // Permissions
  requiredPermission?: PermissionCode;
  requiredPermissions?: PermissionCode[];
  // Helper/description text (shown below the field)
  description?: string;
  // Browser autocomplete & password manager control
  autoComplete?: string;
  // Section layout (absent on every field = current flat single-column behaviour)
  section?: string; // Title of the hairline-ruled group; consecutive fields with the same section are grouped
  colSpan?: 1 | 2; // Width in the two-column section grid; any colSpan in a group switches it to sm:grid-cols-2
}

/**
 * Wave K collapse: formStyle used to re-skin the FIELDS — cyan-on-black
 * "neon", slate "elegant", green "organic", orange "retro", a glass wash and a
 * gradient card, all in raw colour literals with dark: forks. Field skin has
 * exactly one owner now (Settings inputStyle, applied inside Input / Textarea
 * / Select), so formStyle keeps only what it can honestly control: the
 * CONTAINER and the DENSITY. Retired decorative values resolve onto the
 * nearest survivor; the stored-value migration itself is Wave C's job.
 */
const FORM_CONTAINER: Record<string, "flat" | "card" | "minimal"> = {
  card: "card",
  modern: "card",
  glass: "card",
  minimal: "minimal",
};

/**
 * Props for the GenericForm component
 */
interface GenericFormProps {
  fields: FieldConfig[];
  initialValues?: Record<string, any>;
  onSubmit: (data: Record<string, any>) => Promise<void>;
  onCancel: () => void;
  readOnly?: boolean; // New prop for read-only mode
  showErrorSummary?: boolean; // Optional prop to render top error summary banner (default: false)
}

/**
 * Generic Form Component
 *
 * Renders a dynamic form based on field configuration with support for:
 * - Multiple input types (text, select, date, file, etc.)
 * - Conditional field visibility
 * - Internationalization
 * - Dynamic styling based on settings
 * - Form validation
 * - Read-only mode
 *
 * @param props - The component props
 * @param props.fields - Array of field configurations
 * @param props.initialValues - Initial form values
 * @param props.onSubmit - Callback when form is submitted
 * @param props.onCancel - Callback when form is cancelled
 * @param props.readOnly - Whether the form is in read-only mode
 * @returns JSX element representing the form
 */
/**
 * Stable identity for the omitted-prop case. An inline `initialValues = {}`
 * default is re-created on EVERY render of this component, so the re-init
 * effect below saw changed deps forever and re-entered itself.
 */
const NO_INITIAL_VALUES: Record<string, any> = {};

/**
 * Field types whose form value is a multi-piece OBJECT envelope rather than a
 * scalar or an array, each paired with the rule that decides whether ITS
 * envelope counts as unfilled — because "is this required field empty" cannot
 * be answered from the envelope alone, and the answer is not the same question
 * for two different envelopes.
 *
 * A MAP, not a set with a switch beside it. The predecessor here was a
 * `Set<FieldConfig["type"]>` whose single member's shape was then hardcoded
 * inline in `isRequiredFieldEmpty` as `{ entityTypeKey, entityId }` — fine for
 * one member, and a drift trap the moment a second type with a DIFFERENT shape
 * joined it, because membership and shape lived in two places. Currency is that
 * second type (`{ amount, currencyCode }` — nothing to do with a reference's two
 * fields), so the type and its own rule are bound together here and cannot
 * disagree.
 *
 * Each predicate is only ever called with a non-null `object` (the scalar and
 * array arms run first, and a non-object on an object-valued field fails closed
 * before dispatch), so no predicate re-checks that.
 *
 * `"datetime"` is deliberately absent, and that is a finding rather than an
 * omission: its value IS a two-piece `{ value, timeZoneId }` object on the wire,
 * but this component converts every date-family value through
 * `toDateInputValue`/`fromDateInputValue`, so what reaches the check is always a
 * STRING. Admitting it would change a shipped type's behaviour on a guess about
 * a shape that never arrives here. Pinned by a test in
 * generic-form.requiredObjectValue.test.tsx.
 *
 * `"duration"` is absent because it is not object-valued at all — see its own
 * `FieldConfig["type"]` member comment above.
 */
const OBJECT_VALUED_EMPTINESS_CHECKS: Partial<
  Record<FieldConfig["type"], (value: object) => boolean>
> = {
  /**
   * Mirrors the backend's own write gate rather than inventing a rule:
   * `EntityReferenceValueTypeHandler.Validate` refuses a reference unless BOTH
   * the target type key and the encrypted id are present and non-blank, so a
   * half-blank reference is not a storable value and "required" must not accept
   * one.
   *
   * PRESENCE, not shape: this does not try to judge whether `entityId` is a
   * well-formed encrypted id. A malformed-but-present value is a FORMAT problem
   * with its own message, not a missing one.
   *
   * The body moved into `referenceEnvelopeIsEmpty` below when Wave 3.4's two
   * media types joined it: they hold the same envelope, and three inline copies
   * of one rule is how one of them ends up corrected and the other two do not.
   */
  "entity-reference": referenceEnvelopeIsEmpty,
  /**
   * Currency's rule is read off `CurrencyValueTypeHandler` (backend
   * CustomFields.Application/ValueTypes), whose two methods answer two
   * different questions and have to be composed rather than picked between:
   *
   *   - `IsEmpty` returns true only when the amount AND the code are both
   *     missing. That is "nothing to save", and it is already caught before this
   *     predicate runs: the control emits `null` when the user blanks the last
   *     populated piece, and the scalar arm rejects `null`.
   *   - `Validate` (which runs for everything `IsEmpty` let through) requires
   *     BOTH pieces. So a half-blank Currency is not "empty" server-side — it is
   *     a 422. The handler's own comment is explicit that this is deliberate:
   *     treating a half-blank as empty "would silently skip Validate and let a
   *     genuinely-entered (but incomplete ...) amount or code through with no
   *     error".
   *
   * A required field is satisfied only by a value the server will actually
   * store, so this refuses a half-blank — the same composition, and the same
   * presence-not-shape scope, as the reference rule above. The code's alpha-3
   * GRAMMAR is not checked here; that is `pattern` on the control's own input
   * (mirroring `IsValidCurrencyCode`) and the server's `currencyCodeInvalid`,
   * not a missing-value verdict.
   *
   * `amount` is checked for MISSING-ness, never truthiness: `0` is a legitimate
   * amount and `-1` is too (the handler enforces no minimum — a credit or a
   * refund is a real currency value), so the blank test mirrors the handler's own
   * `Amount is null || (Amount is string s && IsNullOrWhiteSpace(s))` exactly.
   */
  currency: (value) => {
    const money = value as { amount?: unknown; currencyCode?: unknown };
    const amountMissing =
      money.amount === undefined ||
      money.amount === null ||
      (typeof money.amount === "string" && money.amount.trim() === "");
    const codeMissing =
      typeof money.currencyCode !== "string" || money.currencyCode.trim() === "";
    return amountMissing || codeMissing;
  },
  /**
   * Wave 3.4. File and Image (CustomFields' two media reference types) hold the
   * SAME `{ entityTypeKey, entityId }` envelope a general reference does -- on
   * the backend `FileValueTypeHandler` literally extends
   * `EntityReferenceValueTypeHandler` -- so the rule is `"entity-reference"`'s,
   * reused by reference to it rather than re-derived, which is what keeps a
   * later correction to one from silently leaving the other two behind.
   *
   * SHARED BUT STILL THREE ENTRIES, not one entry under a shared key: the two
   * media types deliberately carry two different `FieldConfig["type"]` members
   * (only two keys can express "this one is images-only"), and this map is keyed
   * by that member, so each needs its own line. Predicate identity is the
   * mechanism that keeps them honest about being the same rule.
   *
   * The presence-not-shape scope carries over too. Whether the referenced media
   * row is actually OWNED by the record being edited -- the backend's owner-pair
   * fence, and the whole reason `media.file` is a legal reference target at all
   * -- is not a question this layer can answer at all: it needs the media row.
   * A required field being "filled" therefore means "the operator picked
   * something", never "the server will accept it".
   */
  "media-file": referenceEnvelopeIsEmpty,
  "media-image": referenceEnvelopeIsEmpty,
  /**
   * Wave 3.4. RichText's envelope is `{ html }` and blank markup is an unfilled
   * field, so a required rich-text field is not satisfied by an empty editor.
   *
   * WHITESPACE COUNTS AS BLANK, matching `RichTextValueTypeHandler.IsEmpty`
   * exactly (`string.IsNullOrWhiteSpace(input.Html)`) -- a field the operator
   * cleared should read as cleared, and an editor that leaves a stray newline
   * behind has not stored a value.
   *
   * MARKUP THAT RENDERS TO NOTHING (`<p></p>`) IS NOT BLANK HERE, and that is
   * the backend's decision reproduced rather than a gap: deciding whether markup
   * renders to nothing means parsing it, which that handler's own comment
   * declines to do on every field of every save. The control avoids producing
   * this state (it emits `null` when the editor is empty) so it is reachable
   * only from stored or out-of-band data, and it is refused server-side by
   * nothing -- an empty paragraph is a value the server stores. Treating it as
   * filled is therefore the answer that agrees with the server, which is the
   * whole contract of this map.
   */
  "rich-text": (value) => {
    const rich = value as { html?: unknown };
    return typeof rich.html !== "string" || rich.html.trim() === "";
  },
};

/**
 * The reference-envelope rule, extracted so the three field types that share it
 * (`"entity-reference"` and Wave 3.4's two media types) share the FUNCTION and
 * not merely a copy of its body. Mirrors the backend's own write gate:
 * `EntityReferenceValueTypeHandler.Validate` refuses a reference unless BOTH the
 * target type key and the encrypted id are present and non-blank, so a
 * half-blank reference is not a storable value and "required" must not accept
 * one.
 *
 * PRESENCE, not shape: this does not try to judge whether `entityId` is a
 * well-formed encrypted id. A malformed-but-present value is a FORMAT problem
 * with its own message, not a missing one.
 *
 * @param value The field's current value, already known to be a non-null object.
 * @returns True when the envelope is missing either piece, i.e. counts as unfilled.
 */
function referenceEnvelopeIsEmpty(value: object): boolean {
  const ref = value as { entityTypeKey?: unknown; entityId?: unknown };
  return (
    typeof ref.entityTypeKey !== "string" ||
    ref.entityTypeKey.trim() === "" ||
    typeof ref.entityId !== "string" ||
    ref.entityId.trim() === ""
  );
}

/**
 * Field types this component declares for `FieldConfig["type"]`'s typing but
 * cannot draw itself, and therefore routes to
 * `CustomFieldsExtensionApi.FieldControl`.
 *
 * A set rather than a `field.type === "entity-reference"` literal in the three
 * places that need it (the label suppression, the render arm, and the
 * required-validation set in `handleSubmit`) so admitting the next such type is
 * one line here, not three scattered comparisons that can drift apart. Kept
 * deliberately SEPARATE from `OBJECT_VALUED_EMPTINESS_CHECKS` above: "core
 * cannot draw this" and "this value is a multi-piece object" are different
 * questions with different answers, and `"duration"` is the proof — extension-
 * drawn and a plain scalar.
 *
 * `"currency"` and `"duration"` joined `"entity-reference"` once the
 * verification the previous author deferred was actually done. That note asked
 * for one thing — check each control's labelling against this component's field
 * anatomy rather than assuming it — and the answer differs per control, which is
 * why it could not be assumed:
 *
 *   - `DurationCustomFieldControl` renders `<Label htmlFor={fc.name}>` over a
 *     real `<input type="number" id={fc.name}>` and NO `aria-label`, so its
 *     accessible name comes from that native `for`/`id` pair. Keeping this
 *     component's own label would emit a SECOND `<label for>` pointing at the
 *     same input — and per the accname spec every matching `<label>` is
 *     concatenated, so the field would have announced its own name twice
 *     ("Setup BufferSetup Buffer") on top of showing two identical visible
 *     labels. Suppression required.
 *   - `CurrencyCustomFieldControl` renders its own `<Label htmlFor={fc.name}>`
 *     too, but its amount input ALSO carries an `aria-label`
 *     (`customField.currency.amountLabel`), which wins over any `<label>` in the
 *     accname cascade — so there the duplicate would have been purely visual
 *     rather than announced. Suppression required for a different reason, and
 *     the two really are not the same case.
 *   - `EntityReferenceCustomFieldControl` is the third distinct case, the one
 *     already documented below: its trigger is a `role="combobox"` div that no
 *     `<label for>` can name at all.
 *
 * Three controls, three mechanisms, one conclusion. What the check ALSO turned
 * up is why it mattered beyond labels. This component's `<form>` carries no
 * `noValidate`, so a control that fails native constraint validation does not
 * merely get styled — the form never fires `submit` at all. Both controls'
 * number inputs shipped with no `step`, which defaults to 1, and
 * `DurationCustomFieldControl`'s `min={0}` pins its step base at 0: a stored
 * `1.5` minutes (a documented, supported value) was therefore unsubmittable the
 * moment Duration was drawn here. Fixed at that control (`step="any"`), not here.
 * Currency's amount turned out NOT to have the same live defect — no `min`, so
 * its step base tracks its own value — which is exactly the kind of thing
 * "verify, don't assume" was asking for; it carries the same declaration as a
 * guard, with its own reasoning recorded in that file.
 */
/*
 * Wave 3.4 admits `"media-file"`, `"media-image"` and `"rich-text"`, and the
 * per-control labelling check this set's comment demands was done for each
 * rather than inherited from the three above:
 *
 *   - `MediaReferenceCustomFieldControl` renders its own `<Label htmlFor={id}>`
 *     over a `role="group"` region, and the group carries an `aria-label`.
 *     Keeping this component's label would show two identical visible labels;
 *     the announced name comes from the group's own `aria-label`, so the
 *     duplicate would be visual only -- Currency's case exactly.
 *   - `RichTextCustomFieldControl` renders its own `<Label htmlFor={id}>` and
 *     binds it to the editor's contenteditable region by `aria-labelledby`,
 *     because `<Label htmlFor>` alone names nothing on a `role="textbox"` div.
 *     A second `<label for>` from here would be concatenated into the announced
 *     name per the accname spec -- Duration's case, arrived at by a different
 *     mechanism. Suppression required for all three.
 *
 * Membership here also carries two consequences these types genuinely need, and
 * that is why it is the right set rather than a fourth ad-hoc condition: the
 * spread into `handleSubmit`'s `customTypes` (none of the three has a native
 * `required` attribute the browser could enforce -- the media control has no
 * form element in it at all) and the label suppression above.
 */
const EXTENSION_DRAWN_FIELD_TYPES = new Set<FieldConfig["type"]>([
  "entity-reference",
  "currency",
  "duration",
  "media-file",
  "media-image",
  "rich-text",
]);

/**
 * One field of a type only the CustomFields module can draw — plus the explicit
 * state for when that module is not present.
 *
 * THE FALLBACK IS THE POINT. `core` is usable with no CustomFields module
 * registered (every hand-built `CustomFieldsExtensionApi` test double in this
 * codebase omits `FieldControl`, and `FieldControl` is optional for exactly that
 * reason), and the one thing that path must never do is what the bug did: fall
 * through to `<Input type="entity-reference" value={formData[name] ?? ""}>`,
 * which renders a stored reference object as `[object Object]` in an editable
 * text box and replaces it with a string on the first keystroke. So this renders
 * an inert, explanatory field instead.
 *
 * WHAT IT DOES NOT SHOW is deliberate: not the held value, for any of the three
 * types it now covers. The sharpest case is a reference, whose `entityId` is an
 * ENCRYPTED foreign primary key that only the resolve hook inside the very
 * module that is missing can turn into a human name — printing it would leak an
 * opaque id into the page and read as data corruption. Currency and Duration
 * hold nothing secret, but printing a value with no way to edit it invites the
 * operator to believe the field is merely read-only rather than broken, and the
 * uniform inert statement says the true thing for all three. The value itself is
 * untouched in every case — there is no `onChange` path here, so whatever was
 * loaded is still in `formData` and is resubmitted verbatim.
 *
 * THE COPY REUSES `errors.module.*`, a CORE locale key pair, which matters more
 * than it looks: a module locale key (`customField.*`) is registered by the very
 * module whose absence produced this state, so on the path that actually renders
 * it `t()` would return the bare key. `module-error-boundary.tsx` already
 * composes these same two keys the same way, for the same fact.
 *
 * A11Y: the label/`aria-invalid`/`aria-describedby` contract this component's
 * other branches provide is kept. The label is rendered here rather than by the
 * shared header above (see `EXTENSION_DRAWN_FIELD_TYPES` in that condition),
 * because each registered control renders its own label — the alternative was
 * two visible labels on the same field. `role="group"` is what makes `aria-label`
 * and `aria-describedby` actually exposed on a `<div>`; `aria-disabled` rather
 * than `disabled` because there is no widget here to disable, only a statement.
 */
function CustomFieldExtensionControl({
  field,
  value,
  onChange,
  disabled,
  invalid,
  describedBy,
}: CustomFieldFormControlProps) {
  const { t } = useI18n();
  // Read at render, not through a hook: this is a plain module-level variable
  // lookup (the same way buildCustomFieldColumn reads it), and registration
  // happens once from the app's composition root before any screen mounts.
  const FieldControl = getCustomFieldsExtension()?.FieldControl;

  if (FieldControl) {
    return (
      <FieldControl
        field={field}
        value={value}
        onChange={onChange}
        disabled={disabled}
        invalid={invalid}
        describedBy={describedBy}
      />
    );
  }

  return (
    <div className="space-y-2">
      <Label htmlFor={field.name} className="text-start">
        {field.label}
        {isFieldRequired(field) && (
          <span className="text-destructive ms-1" aria-hidden="true">
            *
          </span>
        )}
      </Label>
      {/* eslint-disable-next-line jsx-a11y/role-supports-aria-props --
          `aria-invalid` is a GLOBAL ARIA state (WAI-ARIA 1.1 promoted it to
          §6.5 Global States and Properties, and 1.2 keeps it there), so it is
          valid on any role including `group`. The rule's role table is
          aria-query's older per-role list, which predates that promotion — the
          warning is the plugin being out of date, not this markup being wrong.
          It is kept rather than dropped because this component's every other
          branch sets it, and the required-field pass genuinely does reject this
          field; `aria-describedby` alone would leave the rejection unannounced
          as a state. */}
      <div
        id={field.name}
        role="group"
        aria-label={field.label ?? field.name}
        aria-disabled="true"
        aria-invalid={invalid || undefined}
        aria-describedby={describedBy}
        // Matches Input's own disabled skin (input.tsx: border-nx-line,
        // bg-nx-raised, text-nx-ink-3, no shadow) so it reads as a field that
        // is present but inoperable, not as a paragraph that lost its box.
        className="flex min-h-10 w-full cursor-not-allowed items-center rounded-nx-control border border-nx-line bg-nx-raised px-3 py-2 text-sm text-nx-ink-3"
      >
        {t("errors.module.description", { module: t("errors.module.unnamed") })}
      </div>
    </div>
  );
}

/**
 * Whether a required field counts as unfilled at submit time.
 *
 * THE BUG THIS EXISTS FOR: the check used to be, inline and in one expression,
 * `val === undefined || val === null || val === "" || (Array.isArray(val) &&
 * val.length === 0)`. Every arm of that tests a scalar or an array, so ANY
 * object passed — `{}` included, and `{ entityTypeKey: "hrms.staff-member",
 * entityId: "" }` in particular. A required entity-reference field with nothing
 * actually picked therefore validated as filled, submitted, and came back a 422
 * from the server (or, worse, wrote a half-blank the server then had to refuse)
 * instead of showing the user "this field is required" next to the field.
 *
 * The scalar and array arms are reproduced here byte-for-byte and are reached
 * first, so behaviour for every field type that existed before is unchanged: a
 * type with no entry in `OBJECT_VALUED_EMPTINESS_CHECKS` still falls through to
 * `false` for a non-empty scalar and for any object, exactly as before. Only a
 * field whose type declares an object rule gets one.
 *
 * That scalar arm is also, on inspection, already the RIGHT rule for
 * `"duration"` — the other type admitted to the extension-drawn set alongside
 * Currency — rather than merely a harmless one. Duration's stored value is bare
 * minutes, and `DurationValueTypeHandler.IsEmpty` is `null || whitespace-only
 * string`, with `Validate` accepting zero outright ("a zero-minute
 * buffer/duration is a legitimate value") and rejecting only negatives. Blank,
 * absent and zero are therefore three distinguishable states server-side, and
 * the arm above already distinguishes them the same way: `undefined`/`null`/`""`
 * are refused, while `0` and `"0"` fall through as filled. No new arm, and
 * specifically no `String(val).trim()` generalisation — that would silently
 * start rejecting whitespace on every scalar type in the product, and a
 * `<input type="number">` cannot produce a whitespace value anyway (the value
 * sanitisation algorithm yields `""` for anything it cannot parse).
 *
 * A non-object value on an object-valued field fails closed: no scalar can ever
 * be a reference, and none can be a `{ amount, currencyCode }` pair either.
 *
 * Both object shapes are restated in `OBJECT_VALUED_EMPTINESS_CHECKS` rather
 * than imported from the CustomFields module's own model, and that is required
 * rather than sloppy: `core` cannot import from `src/modules/*`
 * (docs/architecture/01-modularity.md's Dependency Rule — the same constraint
 * that makes core/crud/customFieldsExtension.tsx a registry instead of an
 * import, and that makes this file's `FieldConfig[]` the boundary type in the
 * first place). If a wire shape ever changes, both have to change.
 *
 * @param field The field being validated; its `type` selects the strategy.
 * @param val The current form value for that field.
 * @returns True when the value should be reported as a missing required field.
 */
/**
 * Determines whether a field is required, evaluating dynamic predicates against formData if provided.
 */
export function isFieldRequired(
  field: FieldConfig,
  formData?: Record<string, any>
): boolean {
  if (typeof field.required === "function") {
    return Boolean(field.required(formData ?? {}));
  }
  return Boolean(field.required);
}

function isRequiredFieldEmpty(field: FieldConfig, val: unknown): boolean {
  if (val === undefined || val === null || val === "") return true;
  if (typeof val === "string" && val.trim() === "") return true;
  if (Array.isArray(val)) return val.length === 0;

  const isEnvelopeEmpty = OBJECT_VALUED_EMPTINESS_CHECKS[field.type];
  if (isEnvelopeEmpty) {
    if (typeof val !== "object") return true;
    return isEnvelopeEmpty(val);
  }

  return false;
}

export function GenericForm({
  fields,
  initialValues = NO_INITIAL_VALUES,
  onSubmit,
  onCancel,
  readOnly = false,
  showErrorSummary = false,
}: GenericFormProps) {
  const settings = useSettings();
  const { t, direction } = useI18n();
  const { hasPermission, hasAnyPermission } = usePermissions();

  // Helper function to initialize form data with default values
  const initializeFormData = React.useCallback(
    (currentFields: FieldConfig[], currentInitialValues: Record<string, any>) => {
      const data = { ...currentInitialValues };
      // Set default values for fields that have them and convert dates for HTML inputs
      currentFields.forEach((field) => {
        if (field.defaultValue !== undefined && data[field.name] === undefined) {
          data[field.name] = field.defaultValue;
        }
        // Convert date fields from API format to HTML input format
        if (
          (field.type === "date" ||
            field.type === "datetime" ||
            field.type === "datetime-local" ||
            field.type === "time" ||
            field.type === "month" ||
            field.type === "week") &&
          data[field.name]
        ) {
          data[field.name] = toDateInputValue(data[field.name]);
        }
      });
      return data;
    },
    []
  );

  const [formData, setFormData] = useState<Record<string, any>>(() =>
    initializeFormData(fields, initialValues)
  );
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});
  /** Rejection from onSubmit. The form used to swallow these entirely. */
  const [serverError, setServerError] = useState<string | null>(null);

  // Re-initialize form data when fields change (for dynamic forms)
  // IMPORTANT: Only populate values for NEW fields that don't exist in the current
  // form data. Never overwrite existing user-typed values with initialValues.
  // The updater MUST return the previous object unchanged when it adds nothing.
  // It used to spread unconditionally, so every run produced a new state
  // reference, React re-rendered, the effect re-ran on its unstable deps, and
  // the form span out on "Maximum update depth exceeded" (React error #185).
  // Bailing out on the no-op keeps that loop closed even if a caller rebuilds
  // `fields` or `initialValues` on every render.
  React.useEffect(() => {
    queueMicrotask(() => {
      setFormData((prevData) => {
        let added = false;
        const preservedData = { ...prevData };
        fields.forEach((field) => {
          // Only set default/initial value if this field has NO value yet
          if (preservedData[field.name] === undefined) {
            if (field.defaultValue !== undefined) {
              preservedData[field.name] = field.defaultValue;
              added = true;
            } else if (initialValues[field.name] !== undefined) {
              preservedData[field.name] = initialValues[field.name];
              added = true;
            }
          }
        });
        return added ? preservedData : prevData;
      });
    });
  }, [fields, initialValues]);

  const handleChange = (name: string, value: any, extraKeys?: Record<string, any>) => {
    // Clear error when user changes the field
    if (errors[name]) {
      setErrors((prev) => {
        const next = { ...prev };
        delete next[name];
        return next;
      });
    }

    setFormData((prev) => {
      // `extraKeys` lets ONE control own more than one form key -- used by the bilingual options
      // editor, whose two newline lists are positionally aligned and must be written together or
      // every option after an edit shifts onto the wrong translation. Merged before the field's own
      // onChange runs, so a caller can still override.
      const newData = { ...prev, [name]: value, ...(extraKeys ?? {}) };

      // Find the field that changed and call its onChange callback if it exists
      const field = fields.find((f) => f.name === name);
      if (field?.onChange) {
        const result = field.onChange(value, newData);
        // If onChange returns an object, merge it into newData to update multiple fields
        if (result && typeof result === "object" && !Array.isArray(result)) {
          return { ...newData, ...result };
        }
      }

      return newData;
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    // Re-entrancy guard: the fields stay editable while a submit is in flight,
    // and Enter in any of them re-fires this handler.
    if (loading) return;
    setServerError(null);

    // Validate required fields for custom components (select, searchable-select, etc.)
    // Native HTML inputs handle required validation via browser, but custom components need manual checks
    const customTypes = new Set([
      "select",
      "searchable-select",
      "server-select",
      "multi-select",
      "tree",
      "switch",
      "checkbox",
      "radio",
      "slider",
      "range",
      "phone",
      "tel",
      "date",
      "datetime",
      "datetime-local",
      "time",
      "month",
      "week",
      "image",
      "richtext",
      // Every extension-drawn type, BY CONSTRUCTION rather than by a literal
      // list that has to be remembered. Wave 4 listed "entity-reference" here
      // by hand because the reference picker is a custom control with no native
      // `required` attribute for the browser to enforce; spreading the set is
      // the same membership, plus the guarantee that the next type admitted
      // there cannot be forgotten here.
      //
      // And it must not be, for a stronger reason than "these controls happen
      // to be custom": for an extension-drawn type this component has NO
      // knowledge of what the registered module renders — Duration's control
      // does carry a native `required`, but `CustomFieldExtensionControl`'s
      // no-module-registered fallback is an inert `role="group"` div with no
      // form control in it at all. Native constraint validation therefore
      // cannot be relied on for any member, whatever today's module happens to
      // draw.
      //
      // These reach this submit path via generic-crud-view.tsx, which
      // concatenates the CustomFields extension's fieldConfigs into
      // <GenericForm>'s own `fields`.
      ...EXTENSION_DRAWN_FIELD_TYPES,
    ]);

    const shouldDeferCustomFields = Boolean(formData.deferCustomFieldsToSetup);

    const newErrors: Record<string, string> = {};
    fields.forEach((field) => {
      // Skip fields that aren't visible
      if (field.isVisible && !field.isVisible(formData)) return;

      // Skip custom fields if deferred to the account setup phase
      if (shouldDeferCustomFields && decodeCustomFieldName(field.name) !== null) {
        return;
      }

      const val = formData[field.name];

      // Format validation for phone/tel inputs when a value is provided
      if (
        (field.type === "phone" || field.type === "tel") &&
        typeof val === "string" &&
        val.trim() !== "" &&
        !isValidPhoneNumber(val)
      ) {
        newErrors[field.name] = t("validation.invalidPhone");
        return;
      }
      // Format validation for email inputs when a value is provided
      if (
        (field.type === "email" || field.name.toLowerCase().includes("email")) &&
        typeof val === "string" &&
        val.trim() !== "" &&
        !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val.trim())
      ) {
        newErrors[field.name] = t("validation.invalidEmail");
        return;
      }

      // Pattern validation for inputs with pattern attribute
      if (
        (field as any).pattern &&
        typeof val === "string" &&
        val.trim() !== "" &&
        !new RegExp((field as any).pattern).test(val)
      ) {
        newErrors[field.name] = (field as any).patternError || t("validation.patternMismatch") || "Invalid format";
        return;
      }

      // Check required
      const required = isFieldRequired(field, formData);
      if (!required) return;

      if (isRequiredFieldEmpty(field, val)) {
        newErrors[field.name] = t("validation.required");
      }
    });

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      // Auto-scroll and focus first invalid field in DOM order
      const firstErrorField = visibleFields.find((f) => newErrors[f.name]);
      if (firstErrorField) {
        setTimeout(() => {
          const el =
            document.getElementById(firstErrorField.name) ||
            document.querySelector(`[name="${firstErrorField.name}"]`) ||
            document.querySelector(`[data-field-name="${firstErrorField.name}"]`);
          if (el) {
            el.scrollIntoView?.({ behavior: "smooth", block: "center" });
            const focusTarget =
              el instanceof HTMLInputElement ||
              el instanceof HTMLTextAreaElement ||
              el instanceof HTMLSelectElement ||
              el instanceof HTMLButtonElement
                ? el
                : el.querySelector<HTMLElement>("input, textarea, button, select, [tabindex]:not([tabindex='-1'])") || el;
            if (focusTarget && typeof focusTarget.focus === "function") {
              focusTarget.focus({ preventScroll: true });
            }
          }
        }, 50);
      }
      return;
    }

    setErrors({});
    setLoading(true);
    try {
      // Convert date fields back to ISO format for API
      const submitData = { ...formData };
      fields.forEach((field) => {
        if (
          field.type === "date" ||
          field.type === "datetime" ||
          field.type === "datetime-local" ||
          field.type === "time" ||
          field.type === "month" ||
          field.type === "week"
        ) {
          // The value is only a string when it came through the date-input
          // conversion. `initialValues` and `defaultValue` bypass that on the
          // re-init path, so a Date object or a number can land here — and
          // calling .trim() on it threw inside an async handler, which React
          // does not surface: the form just sat there while the rejection
          // escaped as an unhandled promise.
          const raw = submitData[field.name];
          const asString = typeof raw === "string" ? raw : "";
          if (asString.trim() !== "") {
            const converted = fromDateInputValue(asString);
            // Only set if conversion was successful (not empty string)
            if (converted && converted.trim() !== "") {
              submitData[field.name] = converted;
            } else {
              // Remove if conversion failed or resulted in empty
              delete submitData[field.name];
            }
          } else {
            // Remove empty strings or undefined values for date fields
            delete submitData[field.name];
          }
        }

        // A number field submitted its raw input string, so consumers received
        // "12" where the API expects 12 — and every caller had to remember to
        // coerce. Empty stays empty rather than becoming 0.
        if (field.type === "number") {
          const raw = submitData[field.name];
          if (raw !== "" && raw !== null && raw !== undefined) {
            const asNumber = Number(raw);
            if (!Number.isNaN(asNumber)) submitData[field.name] = asNumber;
          }
        }
      });
      await onSubmit(submitData);
    } catch (error) {
      // Parse ASP.NET RFC 7807/9110 and standard API validation errors into field-level errors
      const parsed = parseApiValidationError(
        error,
        fields.map((f) => f.name)
      );
      if (parsed.hasFieldErrors) {
        setErrors((prev) => ({ ...prev, ...parsed.fieldErrors }));
        const firstErrorField = visibleFields.find((f) => parsed.fieldErrors[f.name]);
        if (firstErrorField) {
          setTimeout(() => {
            const el =
              document.getElementById(firstErrorField.name) ||
              document.querySelector(`[name="${firstErrorField.name}"]`) ||
              document.querySelector(`[data-field-name="${firstErrorField.name}"]`);
            if (el) {
              el.scrollIntoView?.({ behavior: "smooth", block: "center" });
              const focusTarget =
                el instanceof HTMLInputElement ||
                el instanceof HTMLTextAreaElement ||
                el instanceof HTMLSelectElement ||
                el instanceof HTMLButtonElement
                  ? el
                  : el.querySelector<HTMLElement>(
                      "input, textarea, button, select, [tabindex]:not([tabindex='-1'])"
                    ) || el;
              if (focusTarget && typeof focusTarget.focus === "function") {
                focusTarget.focus({ preventScroll: true });
              }
            }
          }, 50);
        }
      }
      setServerError(
        parsed.summaryMessage || (error instanceof Error ? error.message : String(error))
      );
    } finally {
      setLoading(false);
    }
  };

  const getFormSpacing = () => {
    switch (settings.spacingSize) {
      case "compact":
        return "space-y-3";
      case "comfortable":
        return "space-y-6";
      case "spacious":
        return "space-y-8";
      default:
        return "space-y-4";
    }
  };

  const getFieldSpacing = () => {
    // Use formStyle for spacing if available, otherwise fallback to spacingSize
    const style = settings.formStyle || settings.spacingSize;
    switch (style) {
      case "compact":
        return "space-y-1";
      case "spacious":
        return "space-y-4";
      case "inline":
        return "flex items-center gap-4";
      case "modern":
        return "space-y-3";
      case "glass":
        return "space-y-3";
      case "minimal":
        return "space-y-2";
      case "card":
        return "space-y-3";
      default:
        // Handle spacingSize fallback for comfortable
        if (settings.spacingSize === "comfortable") {
          return "space-y-3";
        }
        return "space-y-2";
    }
  };

  const getGridGap = () => {
    switch (settings.spacingSize) {
      case "compact":
        return "gap-3";
      case "comfortable":
        return "gap-6";
      case "spacious":
        return "gap-8";
      default:
        return "gap-4";
    }
  };

  const getInputHeight = () => {
    switch (settings.spacingSize) {
      case "compact":
        return "h-9";
      case "comfortable":
        return "h-12";
      case "spacious":
        return "h-14";
      default:
        return "h-10";
    }
  };

  const getButtonSize = () => {
    switch (settings.spacingSize) {
      case "compact":
        return "sm";
      case "comfortable":
      case "spacious":
        return "lg";
      default:
        return "default";
    }
  };

  const getSeparatorSpacing = () => {
    switch (settings.spacingSize) {
      case "compact":
        return "pt-4 mt-4";
      case "comfortable":
        return "pt-8 mt-8";
      case "spacious":
        return "pt-10 mt-10";
      default:
        return "pt-6 mt-6";
    }
  };

  const getFormContainerClasses = () => {
    const baseClasses = "w-full max-h-[70vh] overflow-y-auto";

    switch (FORM_CONTAINER[settings.formStyle] ?? "flat") {
      case "card":
        // a real slab: hairline frame, surface fill, one radius step off the
        // ladder — no gradient, no blur, no coloured shadow
        return cn(baseClasses, "rounded-nx-lg border border-nx-line bg-nx-surface p-6");
      case "minimal":
        return cn(baseClasses, "p-4");
      default:
        return cn(baseClasses, "p-6");
    }
  };

  // Label styling belongs to the Label primitive (ink step, size ladder,
  // disabled ink). The form only decides whether a run of fields is a section.
  const getLabelClasses = () => "";

  // The field surface is Input/Textarea/Select's own business; the form only
  // hands down the height its density asks for.
  const getInputClasses = (baseInputClasses: string) => baseInputClasses;

  // Visibility and permission rules are unchanged; they run before section grouping
  const visibleFields = fields.filter((field) => {
    // Check visibility function
    if (field.isVisible && !field.isVisible(formData)) return false;
    // Check permissions
    if (field.requiredPermission && !hasPermission(field.requiredPermission)) return false;
    if (
      field.requiredPermissions &&
      field.requiredPermissions.length > 0 &&
      !hasAnyPermission(field.requiredPermissions)
    )
      return false;
    return true;
  });

  // Consecutive fields sharing a `section` render as one titled, hairline-ruled group.
  // Runs with neither section nor colSpan keep the flat single-column flow untouched.
  const fieldGroups: { section?: string; fields: FieldConfig[] }[] = [];
  visibleFields.forEach((field) => {
    const last = fieldGroups[fieldGroups.length - 1];
    if (last && last.section === field.section) {
      last.fields.push(field);
    } else {
      fieldGroups.push({ section: field.section, fields: [field] });
    }
  });

  return (
    <div className={cn(getFormContainerClasses(), "text-start")} dir={direction}>
      <form
        onSubmit={handleSubmit}
        className={getFormSpacing()}
        aria-busy={loading || undefined}
        autoComplete="off"
        data-1p-ignore="true"
        data-bwignore="true"
        data-lpignore="true"
        data-protonpass-ignore="true"
        data-dashlane-ignore="true"
      >
        {showErrorSummary && Object.keys(errors).length > 0 && (
          <div
            role="alert"
            className="rounded-nx-md border border-destructive/30 bg-destructive/10 p-3.5 text-destructive"
          >
            <div className="flex items-start gap-2.5">
              <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" />
              <div className="space-y-1 text-xs">
                <p className="font-semibold">{t("validation.correctErrorsTitle")}</p>
                <ul className="list-disc ps-4 space-y-0.5 text-[11px] text-destructive/90">
                  {Object.entries(errors).map(([fieldName, errMsg]) => {
                    const f = fields.find((item) => item.name === fieldName);
                    const label = f?.label ? t(f.label) : fieldName;
                    return (
                      <li key={fieldName}>
                        <span className="font-medium">{label}:</span> {errMsg}
                      </li>
                    );
                  })}
                </ul>
              </div>
            </div>
          </div>
        )}

        {fieldGroups.map((group, groupIndex) => {
          // The two-column grid engages only when a grouped field opts in via colSpan
          const gridded = group.fields.some((f) => f.colSpan !== undefined && f.type !== "hidden");
          const renderedFields = group.fields.map((field) => {
            // Field anatomy, one shape for every type: label → control →
            // hint/error. The ids wire the control to whichever of the two it
            // actually has, so a screen reader reads the hint and the error in
            // that order and never announces an empty node.
            const hintId = field.description ? `${field.name}-hint` : undefined;
            const errorId = errors[field.name] ? `${field.name}-error` : undefined;
            // The error REPLACES the hint in the row below, so the description
            // points at whichever one is actually on screen — a dangling
            // aria-describedby is worse than none.
            const describedBy = errorId ?? hintId;
            const invalid = Boolean(errors[field.name]);
            // Read-only is NOT disabled: text fields stay focusable and
            // selectable so a value can be copied out of a view dialog, while
            // pickers and toggles (which have nothing to copy) go inert.
            const inert = field.disabled || readOnly;
            // Boolean, not the number itself — a bare `maxLength &&` would
            // render a literal 0 into the form when a caller passes 0.
            const counted = Boolean(
              field.maxLength && (!field.type || field.type === "text" || field.type === "textarea")
            );

            return field.type === "hidden" ? (
              <input
                key={field.name}
                type="hidden"
                name={field.name}
                value={formData[field.name] ?? ""}
              />
            ) : (
              <div
                key={field.name}
                className={cn("relative", getFieldSpacing(), gridded && field.colSpan === 2 && "sm:col-span-2")}
              >
                {/* Switch and checkbox label themselves on their own row.
                    Extension-drawn types are excluded because every one of
                    their controls renders its own `<Label htmlFor={name}>` over
                    its own control — verified per control, not assumed, and the
                    failure keeping this label would cause is NOT the same for
                    all three: see `EXTENSION_DRAWN_FIELD_TYPES` above for the
                    reference control's un-nameable `role="combobox"` div, for
                    Duration's doubled native `for`/`id` accessible name, and for
                    Currency's purely visual duplicate. The label is not lost: it
                    moves into whichever branch of
                    `CustomFieldExtensionControl` actually renders. */}
                {field.type !== "switch" &&
                  field.type !== "checkbox" &&
                  !EXTENSION_DRAWN_FIELD_TYPES.has(field.type) && (
                    <div className="flex items-center gap-1">
                      <Label htmlFor={field.name} className={cn(getLabelClasses(), "text-start")}>
                        {field.label}
                      </Label>
                      {isFieldRequired(field, formData) && (
                        <span className="text-destructive text-sm font-medium" aria-hidden="true">
                          *
                        </span>
                      )}
                    </div>
                  )}
                {field.type === "select" ? (
                  <GenericSelect
                    id={field.name}
                    // Task 7b a11y fix (Wave 2 Step 2.2, T1): the trigger is a
                    // role="combobox" div, not a labelable HTML element, so
                    // the <Label htmlFor> above computes NO accessible name
                    // for it. Same `label ?? name` fallback as
                    // renderCustomFieldControl.tsx's Select branch.
                    aria-label={field.label ?? field.name}
                    invalid={invalid}
                    required={isFieldRequired(field, formData)}
                    describedBy={describedBy}
                    // `loading` reached only the searchable branch, so a plain
                    // select waiting on its options rendered as an empty list
                    // rather than as loading.
                    loading={field.loading}
                    type="single"
                    options={
                      field.options?.map((opt) => ({
                        value: opt.value,
                        label: opt.label,
                        disabled: opt.disabled,
                      })) || []
                    }
                    value={formData[field.name] ?? ""}
                    onValueChange={(value: string | string[]) =>
                      handleChange(field.name, typeof value === "string" ? value : value[0])
                    }
                    placeholder={field.placeholder}
                    disabled={inert}
                    className={getInputClasses(getInputHeight())}
                  />
                ) : field.type === "searchable-select" || field.type === "server-select" ? (
                  <GenericSelect
                    id={field.name}
                    aria-label={field.label ?? field.name}
                    invalid={invalid}
                    required={isFieldRequired(field, formData)}
                    describedBy={describedBy}
                    type="searchable"
                    options={
                      field.options?.map((opt) => ({
                        value: opt.value,
                        label: opt.label,
                        disabled: opt.disabled,
                      })) || []
                    }
                    value={formData[field.name] ?? ""}
                    onValueChange={(value: string | string[]) =>
                      handleChange(field.name, typeof value === "string" ? value : value[0])
                    }
                    placeholder={field.placeholder}
                    searchPlaceholder={field.searchPlaceholder}
                    searchType={field.searchType || "client"}
                    onServerSearch={
                      field.onServerSearch
                        ? async (query: string) => {
                            const results = await field.onServerSearch!(query);
                            return results.map((r) => ({
                              value: r.value,
                              label: r.label,
                            }));
                          }
                        : undefined
                    }
                    searchEndpoint={field.searchEndpoint}
                    debounceMs={field.debounceMs}
                    loading={field.loading}
                    noResultsText={field.noResultsText}
                    searchingText={field.searchingText}
                    disabled={inert}
                    className={getInputClasses(getInputHeight())}
                    // Stable key to avoid remounting (which closes dropdown) on each selection
                    key={`searchable-select-${field.name}`}
                  />
                ) : field.type === "multi-select" ? (
                  <GenericSelect
                    id={field.name}
                    aria-label={field.label ?? field.name}
                    invalid={invalid}
                    required={field.required}
                    describedBy={describedBy}
                    loading={field.loading}
                    type="multi"
                    options={
                      field.options?.map((opt) => ({
                        value: opt.value,
                        label: opt.label,
                        uniqueKey: opt.uniqueKey,
                      })) || []
                    }
                    value={formData[field.name] || []}
                    onValueChange={(value: string | string[]) => handleChange(field.name, value)}
                    placeholder={field.placeholder}
                    searchPlaceholder={field.searchPlaceholder}
                    searchType={field.searchType}
                    onServerSearch={
                      field.onServerSearch
                        ? async (query: string) => {
                            const results = await field.onServerSearch!(query);
                            return results.map((r) => ({
                              value: r.value,
                              label: r.label,
                              uniqueKey: r.uniqueKey,
                            }));
                          }
                        : undefined
                    }
                    searchEndpoint={field.searchEndpoint}
                    debounceMs={field.debounceMs}
                    allowClear={field.allowClear}
                    noResultsText={field.noResultsText}
                    searchingText={field.searchingText}
                    maxSelectedDisplay={3}
                    disabled={inert}
                    className={getInputClasses(getInputHeight())}
                    // Stable key to avoid remounting (which closes dropdown) on each selection
                    key={`multi-select-${field.name}`}
                  />
                ) : field.type === "tree" ? (
                  <GenericSelect
                    id={field.name}
                    aria-label={field.label ?? field.name}
                    invalid={invalid}
                    required={isFieldRequired(field, formData)}
                    describedBy={describedBy}
                    loading={field.loading}
                    type="tree"
                    treeData={field.treeData || []}
                    value={formData[field.name] ?? ""}
                    onValueChange={(value: string | string[]) =>
                      handleChange(field.name, typeof value === "string" ? value : value[0])
                    }
                    placeholder={field.placeholder}
                    searchPlaceholder={field.searchPlaceholder}
                    disabled={inert}
                    className={getInputClasses(getInputHeight())}
                  />
                ) : EXTENSION_DRAWN_FIELD_TYPES.has(field.type) ? (
                  // The whole field, label included, comes from the CustomFields
                  // module through the extension registry — or, when no module is
                  // registered, from the explicit inert state
                  // `CustomFieldExtensionControl` renders instead. What must never
                  // happen here is falling through to the text `<Input>` below.
                  //
                  // `formData[field.name]` is passed RAW, with no `?? ""`
                  // normalisation: the fallthrough's `?? ""` is precisely what
                  // turned an absent object value into an empty string the server
                  // then refused. Absent stays `undefined`, and the control decides
                  // what "no value" means for its own type — which for Currency is
                  // `null` (both pieces blank) and for Duration is `""`, two
                  // different answers that only the controls can give.
                  <CustomFieldExtensionControl
                    field={field}
                    value={formData[field.name]}
                    onChange={(next) => handleChange(field.name, next)}
                    disabled={inert}
                    invalid={invalid}
                    describedBy={describedBy}
                  />
                ) : field.type === "bilingual-options" ? (
                  <BilingualOptionsEditor
                    id={field.name}
                    value={formData[field.name] ?? ""}
                    valueAr={field.pairedName ? (formData[field.pairedName] ?? "") : ""}
                    // Writes BOTH halves in one update. handleChange merges an object returned by
                    // the field's own onChange, so the paired key travels with the primary one and
                    // the two lists can never be persisted out of step.
                    onChange={(next) =>
                      handleChange(
                        field.name,
                        next.en,
                        field.pairedName ? { [field.pairedName]: next.ar } : undefined
                      )
                    }
                    disabled={field.disabled || inert}
                    readOnly={readOnly}
                    labelEn={field.placeholder ?? "English"}
                    labelAr={field.searchPlaceholder ?? "العربية"}
                    addLabel={field.addLabel ?? "Add option"}
                    removeLabel={field.removeLabel ?? "Remove"}
                    emptyHint={field.emptyHint ?? ""}
                  />
                ) : field.type === "phone" || field.type === "tel" ? (
                  <PhoneInput
                    id={field.name}
                    value={formData[field.name] ?? ""}
                    onChange={(value) => handleChange(field.name, value)}
                    placeholder={field.placeholder}
                    disabled={inert}
                    defaultCountry={field.defaultCountry as any}
                    error={errors[field.name]}
                    className={cn(getInputHeight(), "text-start")}
                  />
                ) : field.type === "textarea" ? (
                  <Textarea
                    id={field.name}
                    value={formData[field.name] ?? ""}
                    onChange={(e) => handleChange(field.name, e.target.value)}
                    required={isFieldRequired(field, formData)}
                    className={cn(
                      getInputClasses("min-h-20"),
                      "text-start",
                      invalid && "border-destructive focus-visible:ring-destructive"
                    )}
                    placeholder={field.placeholder}
                    rows={field.rows || 4}
                    disabled={field.disabled}
                    readOnly={readOnly}
                    minLength={field.minLength}
                    maxLength={field.maxLength}
                    aria-describedby={describedBy}
                    aria-invalid={invalid || undefined}
                    dir={direction}
                  />
                ) : field.type === "richtext" ? (
                  <RichTextEditor
                    value={formData[field.name] ?? ""}
                    onChange={(value) => handleChange(field.name, value)}
                    placeholder={field.placeholder}
                    // TipTap editor exposes readOnly (not disabled); honour both the
                    // per-field flag and the form-level read-only mode
                    readOnly={field.disabled || readOnly}
                    // px string — the editor feeds this into a CSS custom property
                    minHeight={field.rows ? `${field.rows * 20}px` : "200px"}
                    className="text-start"
                  />
                ) : field.type === "switch" ? (
                  // A switch labels itself on the row; the hint lands in the
                  // shared row below, like every other field type.
                  <div className="flex items-center justify-between gap-3">
                    <Label htmlFor={field.name} className="text-start">
                      {field.label}
                      {isFieldRequired(field, formData) && (
                        <span className="text-destructive ms-1" aria-hidden="true">
                          *
                        </span>
                      )}
                    </Label>
                    <Switch
                      id={field.name}
                      checked={formData[field.name] || false}
                      onCheckedChange={(checked) => handleChange(field.name, checked)}
                      disabled={inert}
                      aria-describedby={describedBy}
                    />
                  </div>
                ) : field.type === "checkbox" ? (
                  <div className="flex items-center gap-2">
                    <Checkbox
                      id={field.name}
                      checked={formData[field.name] || false}
                      onCheckedChange={(checked) => handleChange(field.name, checked)}
                      disabled={inert}
                      design={settings.checkboxStyle}
                      aria-describedby={describedBy}
                      aria-invalid={invalid || undefined}
                    />
                    <Label htmlFor={field.name} className="cursor-pointer text-start">
                      {field.label}
                      {isFieldRequired(field, formData) && (
                        <span className="text-destructive ms-1" aria-hidden="true">
                          *
                        </span>
                      )}
                    </Label>
                  </div>
                ) : field.type === "radio" ? (
                  <RadioGroup
                    value={formData[field.name] ?? ""}
                    onValueChange={(value) => handleChange(field.name, value)}
                    disabled={inert}
                    design={settings.radioStyle}
                    aria-describedby={describedBy}
                    aria-invalid={invalid || undefined}
                  >
                    {field.options?.map((option) => (
                      <div key={option.value} className="flex items-center gap-2">
                        <RadioGroupItem
                          value={option.value}
                          id={`${field.name}-${option.value}`}
                          design={settings.radioStyle}
                        />
                        <Label
                          htmlFor={`${field.name}-${option.value}`}
                          className="cursor-pointer text-start"
                        >
                          {option.label}
                        </Label>
                      </div>
                    ))}
                  </RadioGroup>
                ) : field.type === "slider" || field.type === "range" ? (
                  <div className="space-y-2">
                    <Slider
                      value={[formData[field.name] ?? field.min ?? 0]}
                      onValueChange={(value) => handleChange(field.name, value[0])}
                      min={Number(field.min) || 0}
                      max={Number(field.max) || 100}
                      step={Number(field.step) || 1}
                      disabled={inert}
                      className="w-full"
                      aria-describedby={describedBy}
                    />
                    {/* the read-out is data: tertiary ink, tabular figures so
                        the number stops jittering as it counts */}
                    <div className="flex items-baseline justify-between text-xs text-nx-ink-3">
                      <span>{t("common.value")}</span>
                      <span className="font-medium tabular-nums text-nx-ink-2">
                        {formData[field.name] ?? field.min ?? 0}
                      </span>
                    </div>
                  </div>
                ) : field.type === "date" ||
                  field.type === "datetime" ||
                  field.type === "datetime-local" ||
                  field.type === "time" ||
                  field.type === "month" ||
                  field.type === "week" ? (
                  <DatePicker
                    id={field.name}
                    type={field.type === "datetime" ? "datetime-local" : (field.type as any)}
                    value={formData[field.name] ?? ""}
                    onChange={(value) => handleChange(field.name, value)}
                    required={isFieldRequired(field, formData)}
                    className={cn(getInputClasses(getInputHeight()), invalid && "border-destructive focus-visible:ring-destructive")}
                    placeholder={field.placeholder}
                    disabled={inert}
                  />
                ) : field.type === "image" ? (
                  <ImageUploader
                    id={field.name}
                    value={formData[field.name] ?? ""}
                    onChange={(base64) => handleChange(field.name, base64)}
                    onRemove={() => handleChange(field.name, "")}
                    placeholder={field.placeholder}
                    required={isFieldRequired(field, formData)}
                    disabled={inert}
                    className={getInputClasses(getInputHeight())}
                    accept={field.accept || "image/*"}
                    maxSize={field.maxSize}
                    showPreview={field.showPreview !== false}
                    aspectRatio={field.aspectRatio}
                  />
                ) : field.type === "file" ? (
                  <Input
                    id={field.name}
                    type="file"
                    onChange={(e) => {
                      const files = e.target.files;
                      if (field.multiple) {
                        handleChange(field.name, files ? Array.from(files) : []);
                      } else {
                        handleChange(field.name, files?.[0] || null);
                      }
                    }}
                    required={isFieldRequired(field, formData)}
                    className={cn(getInputClasses(getInputHeight()), "text-start", invalid && "border-destructive focus-visible:ring-destructive")}
                    accept={field.accept}
                    multiple={field.multiple}
                    disabled={inert}
                    aria-describedby={describedBy}
                    aria-invalid={invalid || undefined}
                    dir={direction}
                  />
                ) : field.type === "password" ? (
                  <div className="relative w-full overflow-hidden rounded-nx-control">
                    <PasswordInput
                      id={field.name}
                      value={formData[field.name] ?? ""}
                      onChange={(e) => handleChange(field.name, e.target.value)}
                      required={isFieldRequired(field, formData)}
                      className={cn(getInputClasses(getInputHeight()), "text-start", invalid && "border-destructive focus-visible:ring-destructive")}
                      placeholder={field.placeholder}
                      disabled={field.disabled}
                      readOnly={readOnly}
                      autoComplete={field.autoComplete ?? "new-password"}
                      data-1p-ignore="true"
                      data-bwignore="true"
                      data-lpignore="true"
                      data-protonpass-ignore="true"
                      data-dashlane-ignore="true"
                      aria-describedby={describedBy}
                      aria-invalid={invalid || undefined}
                      showStrengthIndicator={true} // Enable for admin forms
                    />
                  </div>
                ) : (
                  <div className="relative w-full overflow-hidden rounded-nx-control">
                    <Input
                      id={field.name}
                      type={field.type}
                      value={formData[field.name] ?? ""}
                      onChange={(e) => handleChange(field.name, e.target.value)}
                      required={isFieldRequired(field, formData)}
                      className={cn(getInputClasses(getInputHeight()), "text-start", invalid && "border-destructive focus-visible:ring-destructive")}
                      placeholder={field.placeholder}
                      min={field.min}
                      max={field.max}
                      step={field.step}
                      pattern={field.pattern}
                      minLength={field.minLength}
                      maxLength={field.maxLength}
                      disabled={field.disabled}
                      readOnly={readOnly}
                      autoComplete={field.autoComplete ?? "off"}
                      data-1p-ignore="true"
                      data-bwignore="true"
                      data-lpignore="true"
                      data-protonpass-ignore="true"
                      data-dashlane-ignore="true"
                      aria-describedby={describedBy}
                      aria-invalid={invalid || undefined}
                      dir={direction}
                    />
                  </div>
                )}

                {/* Hint and error share one row with the character counter, so
                    the block never jumps as messages come and go. The hint is
                    always available (it used to render for switches only); the
                    error replaces it when the field goes invalid. */}
                {(field.description || errors[field.name] || counted) && (
                  <div className="flex items-start justify-between gap-3">
                    <div className="min-w-0 flex-1">
                      {errors[field.name] ? (
                        <p id={errorId} className="text-xs font-medium text-destructive flex items-center gap-1.5">
                          <AlertCircle className="h-3.5 w-3.5 shrink-0 text-destructive" />
                          <span>{errors[field.name]}</span>
                        </p>
                      ) : field.description ? (
                        <p id={hintId} className="text-xs leading-relaxed text-nx-ink-3">
                          {field.description}
                        </p>
                      ) : null}
                    </div>
                    {counted && (
                      <span className="shrink-0 text-xs tabular-nums text-nx-ink-3">
                        {(formData[field.name] ?? "").length}/{field.maxLength}
                      </span>
                    )}
                  </div>
                )}
              </div>
            );
          });

          // Position-based key: a legacy flat form is always one group ("flat:0"),
          // so reconciliation stays identical to the pre-section render
          const groupKey = `${group.section ?? "flat"}:${groupIndex}`;

          // Absent section and colSpan = exactly the legacy flat single-column flow
          if (!group.section && !gridded) {
            return <React.Fragment key={groupKey}>{renderedFields}</React.Fragment>;
          }

          return (
            <section key={groupKey} className="space-y-3">
              {group.section && (
                <h3 className="border-b border-nx-line pb-2 text-sm font-medium text-nx-ink">
                  {group.section}
                </h3>
              )}
              <div
                className={
                  gridded
                    ? cn("grid grid-cols-1 items-start sm:grid-cols-2", getGridGap())
                    : getFormSpacing()
                }
              >
                {renderedFields}
              </div>
            </section>
          );
        })}

        {serverError && (
          <div role="alert" className="pt-2">
            <ErrorMessage message={serverError} size="sm" />
          </div>
        )}

        <Separator />

        {/* Actions read in DOM order (cancel, then save) and the row is
            reversed once so the primary always lands on the inline END — no
            per-direction order forks, and no gradient on the submit: Button
            owns its own paint. */}
        {!readOnly && (
          <div
            className={cn(
              "flex flex-col-reverse sm:flex-row sm:justify-end",
              getGridGap(),
              getSeparatorSpacing()
            )}
          >
            <Button
              type="button"
              variant="outline"
              onClick={onCancel}
              className={getInputHeight()}
              disabled={loading}
              size={getButtonSize()}
            >
              {t("common.cancel")}
            </Button>
            <Button
              type="submit"
              loading={loading}
              className={getInputHeight()}
              size={getButtonSize()}
            >
              {t("common.save")}
            </Button>
          </div>
        )}
        {readOnly && (
          <div className={cn("flex justify-center", getSeparatorSpacing())}>
            <Button
              type="button"
              variant="outline"
              onClick={onCancel}
              className={getInputHeight()}
              size={getButtonSize()}
            >
              {t("common.close")}
            </Button>
          </div>
        )}
      </form>
    </div>
  );
}

/**
 * ImageUploadField — Reusable image upload component
 *
 * Supports two modes via tabs:
 * 1. Upload: Drag-and-drop or file picker, uploads to server
 * 2. URL: Paste an external URL directly
 *
 * Resolves stored values intelligently:
 * - Full URLs (http/https) → displayed as-is
 * - Relative paths → prefixed with NEXT_PUBLIC_File_URL (server-hosted files)
 */
"use client";

import { useRef, useState, useCallback } from "react";
import { useI18n } from "@core/providers/i18n-provider";
import { cn, resolveFileUrl } from "@core/common/utils";
import { useResolvedFileUrl } from "@core/hooks/use-resolved-file-url";
import { Button } from "@core/ui/button";
import { Input } from "@core/ui/input";
import { Label } from "@core/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@core/ui/tabs";
import { LoadingSpinner } from "@core/ui/loading-spinner";
import { Upload, Link2, Trash2, ImageIcon, Check, X } from "lucide-react";
import { SYSTEM_ENDPOINTS } from "@core/config/api-endpoints";
import { getCoreContainer } from "@core/di";
import Image from "next/image";

// ─── Props ──────────────────────────────────────────────────────
interface ImageUploadFieldProps {
  /** Current stored value — either a relative server path or a full URL */
  value: string;
  /** Called with the new value (relative path after upload, or full URL) */
  onChange: (value: string) => void;
  /** Label displayed above the component */
  label?: string;
  /** Description / help text */
  description?: string;
  /** Max file size in bytes (default: 2MB) */
  maxSizeBytes?: number;
  /** Accepted file types (default: image/*) */
  accept?: string;
  /** Whether the field is disabled */
  disabled?: boolean;
}

// ─── Helpers ────────────────────────────────────────────────────
function isExternalUrl(value: string): boolean {
  return /^https?:\/\//i.test(value);
}

// ─── Component ──────────────────────────────────────────────────
export function ImageUploadField({
  value,
  onChange,
  label,
  description,
  maxSizeBytes = 2 * 1024 * 1024,
  accept = "image/png,image/jpeg,image/webp,image/svg+xml,image/gif,image/x-icon",
  disabled = false,
}: ImageUploadFieldProps) {
  const { t, direction } = useI18n();
  const inputRef = useRef<HTMLInputElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [urlInput, setUrlInput] = useState("");
  const [activeTab, setActiveTab] = useState<string>("upload");

  const maxSizeMB = Math.round(maxSizeBytes / (1024 * 1024));

  // Resolved display URL
  // If we just uploaded a file, show the local blob URL (previewUrl),
  // otherwise ensure the value is resolved so newly uploaded relative paths preview correctly.
  // The hook runs unconditionally (not inside the `||` chain) so hook order
  // stays stable regardless of whether previewUrl is set.
  const resolvedValueUrl = useResolvedFileUrl(value);
  const displayUrl = previewUrl || resolvedValueUrl || "";

  // ─── File validation ──────────────────
  const validateFile = useCallback(
    (file: File): boolean => {
      setError(null);
      const allowedExts = accept.split(",").map((t) => t.trim());
      if (
        !allowedExts.some((ext) => file.type === ext || file.type.startsWith(ext.replace("*", "")))
      ) {
        setError(t("imageUpload.invalidType"));
        return false;
      }
      if (file.size > maxSizeBytes) {
        setError(t("imageUpload.tooLarge", { max: maxSizeMB }));
        return false;
      }
      return true;
    },
    [accept, maxSizeBytes, maxSizeMB, t]
  );

  // ─── File handling ────────────────────
  const uploadFile = useCallback(
    async (file: File) => {
      setIsUploading(true);
      setError(null);
      try {
        const formData = new FormData();
        formData.append("file", file);
        const api = getCoreContainer().apiService;
        const result = await api.post<{ url: string }>(SYSTEM_ENDPOINTS.UPLOADS.IMAGE, formData);
        // Append cache-buster so browser fetches the new image (not a stale cached one)
        const resolved = resolveFileUrl(result.url);
        const cacheBusted = resolved.includes("?")
          ? `${resolved}&v=${Date.now()}`
          : `${resolved}?v=${Date.now()}`;
        onChange(cacheBusted);
        setPreviewUrl(null); // Clear preview, use the resolved value
      } catch (err: any) {
        setError(err?.message || t("imageUpload.uploadFailed"));
        setPreviewUrl(null);
      } finally {
        setIsUploading(false);
      }
    },
    [onChange, t]
  );

  const handleFile = useCallback(
    (file: File) => {
      if (!validateFile(file)) return;
      // Show local preview immediately
      const url = URL.createObjectURL(file);
      setPreviewUrl(url);
      // Upload to server
      uploadFile(file);
    },
    [validateFile, uploadFile]
  );

  // ─── Drag & drop ──────────────────────
  const handleDrop = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault();
      setIsDragging(false);
      const file = e.dataTransfer.files[0];
      if (file) handleFile(file);
    },
    [handleFile]
  );

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  }, []);

  const handleDragLeave = useCallback(() => {
    setIsDragging(false);
  }, []);

  // ─── URL paste ────────────────────────
  const handleUrlConfirm = () => {
    if (!urlInput.trim()) return;
    if (!isExternalUrl(urlInput.trim())) {
      setError(t("imageUpload.invalidUrl"));
      return;
    }
    setError(null);
    onChange(urlInput.trim());
    setUrlInput("");
  };

  // ─── Remove ───────────────────────────
  const handleRemove = () => {
    onChange("");
    setPreviewUrl(null);
    setUrlInput("");
    setError(null);
    if (inputRef.current) inputRef.current.value = "";
  };

  return (
    <div className="space-y-3">
      {/* Field anatomy: label → hint → control → error */}
      {label && <Label>{label}</Label>}
      {description && (
        <p className="-mt-1.5 text-xs leading-relaxed text-nx-ink-3">{description}</p>
      )}

      {/* Filled state — the value itself is the proof, so it gets a real row:
          thumbnail on the neutral raised step (never white, which blows out in
          dark), the stored path in mono, and the destructive action at a 32px
          target. Uploading reports on the same row instead of replacing it. */}
      {displayUrl && (
        <div className="flex items-center gap-3 rounded-nx-control border border-nx-line bg-nx-surface p-3">
          <Image
            src={displayUrl}
            alt=""
            width={56}
            height={56}
            unoptimized
            className="h-14 w-14 shrink-0 rounded-nx-sm border border-nx-line bg-nx-raised object-contain p-1"
            onError={(e) => {
              (e.target as HTMLImageElement).style.display = "none";
            }}
          />
          <div className="min-w-0 flex-1">
            <p className="truncate font-mono text-xs text-nx-ink-2">{value}</p>
            {isUploading && (
              <div className="mt-1 flex items-center gap-1.5 text-xs text-nx-ink-3">
                <LoadingSpinner size="inline" showText={false} />
                <span>{t("imageUpload.uploading")}</span>
              </div>
            )}
          </div>
          <Button
            variant="ghost"
            size="icon"
            className="h-8 w-8 shrink-0 text-nx-ink-3 hover:text-nx-danger"
            onClick={handleRemove}
            disabled={disabled || isUploading}
            aria-label={t("common.remove")}
          >
            <Trash2 className="h-4 w-4" aria-hidden="true" />
          </Button>
        </div>
      )}

      {/* Tabs: Upload | URL */}
      <Tabs value={activeTab} onValueChange={setActiveTab} dir={direction}>
        <TabsList className="grid h-9 w-full grid-cols-2">
          <TabsTrigger value="upload" className="gap-1.5 text-xs">
            <Upload className="h-3.5 w-3.5" />
            {t("imageUpload.uploadTab")}
          </TabsTrigger>
          <TabsTrigger value="url" className="gap-1.5 text-xs">
            <Link2 className="h-3.5 w-3.5" />
            {t("imageUpload.urlTab")}
          </TabsTrigger>
        </TabsList>

        {/* Upload Tab — a drop zone is a control: it is keyboard-reachable,
            announces itself, and has four designed states (empty, hover,
            dragging, uploading/inert). Dragging is the ONE moment light
            collects: accent edge plus the accent wash, no scale, no bounce. */}
        <TabsContent value="upload" className="mt-3">
          <div
            role="button"
            tabIndex={disabled || isUploading ? -1 : 0}
            aria-disabled={disabled || isUploading || undefined}
            aria-label={t("imageUpload.dragDrop")}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
            onClick={() => !disabled && !isUploading && inputRef.current?.click()}
            onKeyDown={(e) => {
              if (disabled || isUploading) return;
              if (e.key === "Enter" || e.key === " ") {
                e.preventDefault();
                inputRef.current?.click();
              }
            }}
            className={cn(
              "flex cursor-pointer flex-col items-center justify-center gap-2 rounded-nx-control border border-dashed p-6 text-center",
              "transition-[border-color,background-color,box-shadow] duration-nx-micro ease-nx-enter motion-reduce:transition-none",
              "focus-visible:border-nx-accent focus-visible:shadow-nx-focus focus-visible:outline-none",
              isDragging
                ? "border-nx-accent bg-nx-accent-wash"
                : "border-nx-line bg-nx-ground hover:border-nx-line-hi hover:bg-nx-hover",
              (disabled || isUploading) &&
                "cursor-not-allowed border-nx-line bg-nx-raised hover:border-nx-line hover:bg-nx-raised"
            )}
          >
            {isUploading ? (
              <LoadingSpinner size="sm" showText={false} className="py-0" />
            ) : (
              <ImageIcon
                className={cn("h-8 w-8", isDragging ? "text-nx-accent" : "text-nx-ink-3")}
                aria-hidden="true"
              />
            )}
            <div>
              <p className="text-sm font-medium text-nx-ink">
                {isUploading ? t("imageUpload.uploading") : t("imageUpload.dragDrop")}
              </p>
              <p className="mt-1 text-xs text-nx-ink-3">
                PNG, JPG, SVG, WebP ·{" "}
                <span className="tabular-nums">
                  {t("imageUpload.maxSize")} {maxSizeMB}MB
                </span>
              </p>
            </div>
          </div>

          <input
            ref={inputRef}
            type="file"
            accept={accept}
            className="hidden"
            disabled={disabled || isUploading}
            onChange={(e) => {
              const file = e.target.files?.[0];
              if (file) handleFile(file);
              // Reset so the same file can be re-selected
              e.target.value = "";
            }}
          />
        </TabsContent>

        {/* URL Tab */}
        <TabsContent value="url" className="mt-3">
          <div className="flex items-center gap-2">
            <Input
              value={urlInput}
              onChange={(e) => {
                setUrlInput(e.target.value);
                setError(null);
              }}
              placeholder={t("imageUpload.urlPlaceholder")}
              className="flex-1 font-mono text-sm"
              aria-invalid={Boolean(error) || undefined}
              disabled={disabled}
              onKeyDown={(e) => {
                if (e.key === "Enter") {
                  e.preventDefault();
                  handleUrlConfirm();
                }
              }}
            />
            <Button
              size="sm"
              onClick={handleUrlConfirm}
              disabled={disabled || !urlInput.trim()}
              className="shrink-0 gap-1.5"
            >
              <Check className="h-3.5 w-3.5" />
              {t("imageUpload.apply")}
            </Button>
          </div>
          <p className="mt-1.5 text-xs leading-relaxed text-nx-ink-3">{t("imageUpload.urlHelp")}</p>
        </TabsContent>
      </Tabs>

      {/* Error — one line, danger ink, announced politely. No banner, no fill:
          the message is six words and the control above it is already wrong. */}
      {error && (
        <p role="status" className="flex items-start gap-1.5 text-xs font-medium text-nx-danger">
          <X className="mt-px h-3.5 w-3.5 shrink-0" aria-hidden="true" />
          {error}
        </p>
      )}
    </div>
  );
}

"use client";

import React, { useState } from "react";
import type { MenuItem } from "@core/navigation";
import * as LucideIcons from "lucide-react";
import {
  LayoutDashboard,
  ArrowLeft,
  ArrowRight,
  PanelLeftClose,
  PanelRightClose,
  PanelLeftOpen,
  PanelRightOpen,
} from "lucide-react";
import { cn, resolveBilingualLabel } from "@core/common/utils";

// ── Focus law ─────────────────────────────────────────────────────────────────
// Every interactive element in the nexus shell wears this instead of a bare
// `outline-none`: invisible keyboard focus is an a11y defect, not a style.
// One token — --nx-focus — draws the whole ring (a 1px inset accent edge plus a
// 3px accent-wash halo), so the rail cannot drift from the rest of the product
// the way a hand-picked outline width/offset pair already had.
export const NX_FOCUS_RING = "focus-visible:outline-none focus-visible:shadow-nx-focus";

// ── Icon resolver ─────────────────────────────────────────────────────────────
export function DynamicIcon({ name, size = 18 }: { name: string; size?: number }) {
  const PascalName = name?.replace(/(^|[-_])(\w)/g, (_, __, c: string) => c.toUpperCase());
  const Icon = (LucideIcons as Record<string, any>)[PascalName ?? ""];
  if (Icon) return <Icon width={size} height={size} strokeWidth={1.8} />;
  return <LayoutDashboard width={size} height={size} strokeWidth={1.8} />;
}

import { Tooltip, TooltipContent, TooltipTrigger } from "@core/ui/tooltip";
import Image from "next/image";

// NOTE: no TooltipProvider here — the rail mounts ONE provider at its nav
// root (~150ms delay). One provider per button meant N providers per render
// and no shared delay grouping across the rail.

// ── Root item button ──────────────────────────────────────────────────────────
export interface RootItemButtonProps {
  item: MenuItem;
  isActive: boolean;
  isRTL: boolean;
  language: string;
  onClick: (item: MenuItem) => void;
}

export function RootItemButton({ item, isActive, isRTL, language, onClick }: RootItemButtonProps) {
  const [hovered, setHovered] = useState(false);
  const btnRef = React.useRef<HTMLButtonElement>(null);
  const label =
    resolveBilingualLabel(item.nameEn, item.nameAr, language) ||
    resolveBilingualLabel(item.nameAr, item.nameEn, language) ||
    item.name;

  // ── Token colours — theme resolves in CSS, no isDark branch ──────────────
  // Active = the lit thing: accent icon + wash; the glowing inline-start edge
  // light itself is the ActiveIndicator, which slides to this button.
  const bgColor = (() => {
    if (isActive) return "var(--nx-accent-wash)";
    if (hovered) return "var(--nx-raised)";
    return "transparent";
  })();

  const iconColor = (() => {
    if (isActive) return "var(--nx-accent)";
    if (hovered) return "var(--nx-ink)";
    return "var(--nx-ink-2)";
  })();

  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <button
          ref={btnRef}
          type="button"
          aria-label={label}
          aria-pressed={isActive}
          onClick={() => onClick(item)}
          onMouseEnter={() => setHovered(true)}
          onMouseLeave={() => setHovered(false)}
          className={cn(
            // Scoped property list. Transitioning every property also animated
            // width/height/margin, so each rail reflow became a 200ms slide.
            "group relative flex items-center justify-center transition-[color,background-color,border-color,box-shadow] duration-nx-standard ease-nx-enter motion-reduce:transition-none",
            NX_FOCUS_RING
          )}
          style={{
            width: 44,
            height: 44,
            flexShrink: 0,
            borderRadius: "var(--nx-radius-md)",
            cursor: "pointer",
            border: isActive
              ? "1px solid color-mix(in oklch, var(--nx-accent) 25%, transparent)"
              : "1px solid transparent",
            background: bgColor,
            color: iconColor,
            margin: "4px 0",
          }}
        >
          <DynamicIcon name={item.icon} size={20} />
        </button>
      </TooltipTrigger>
      <TooltipContent side={isRTL ? "left" : "right"} sideOffset={16}>
        {label}
      </TooltipContent>
    </Tooltip>
  );
}

// ── Back button (module mode) ─────────────────────────────────────────────────
export interface BackButtonProps {
  isRTL: boolean;
  label: string;
  onClick: () => void;
}

export function BackButton({ isRTL, label, onClick }: BackButtonProps) {
  const [hovered, setHovered] = useState(false);
  const btnRef = React.useRef<HTMLButtonElement>(null);

  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <button
          ref={btnRef}
          type="button"
          aria-label={label}
          onClick={onClick}
          onMouseEnter={() => setHovered(true)}
          onMouseLeave={() => setHovered(false)}
          className={cn(
            "group relative flex items-center justify-center transition-[color,background-color,border-color,box-shadow] duration-nx-standard ease-nx-enter motion-reduce:transition-none",
            NX_FOCUS_RING
          )}
          style={{
            width: 44,
            height: 44,
            flexShrink: 0,
            borderRadius: "var(--nx-radius-md)",
            cursor: "pointer",
            border: "1px solid transparent",
            background: hovered ? "var(--nx-raised)" : "transparent",
            color: hovered ? "var(--nx-ink)" : "var(--nx-ink-2)",
            marginBottom: 8,
          }}
        >
          {/* The glyph used to slide toward the inline start on hover. Hover in
              this system is colour and hairline — nothing moves. */}
          {isRTL ? (
            <ArrowRight width={20} height={20} strokeWidth={2} />
          ) : (
            <ArrowLeft width={20} height={20} strokeWidth={2} />
          )}
        </button>
      </TooltipTrigger>
      <TooltipContent side={isRTL ? "left" : "right"} sideOffset={16}>
        {label}
      </TooltipContent>
    </Tooltip>
  );
}

// ── Panel Toggle Button ───────────────────────────────────────────────────────
export interface TogglePanelButtonProps {
  isRTL: boolean;
  label: string;
  isCollapsed: boolean;
  onClick: () => void;
}

export function TogglePanelButton({ isRTL, label, isCollapsed, onClick }: TogglePanelButtonProps) {
  const [hovered, setHovered] = useState(false);
  const btnRef = React.useRef<HTMLButtonElement>(null);

  // Determine icon based on RTL and collapsed state
  let Icon = PanelLeftClose;
  if (isRTL) {
    Icon = isCollapsed ? PanelRightOpen : PanelRightClose;
  } else {
    Icon = isCollapsed ? PanelLeftOpen : PanelLeftClose;
  }

  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <button
          ref={btnRef}
          type="button"
          aria-label={label}
          onClick={onClick}
          onMouseEnter={() => setHovered(true)}
          onMouseLeave={() => setHovered(false)}
          className={cn(
            "group relative flex items-center justify-center transition-[color,background-color,border-color,box-shadow] duration-nx-standard ease-nx-enter motion-reduce:transition-none",
            NX_FOCUS_RING
          )}
          style={{
            width: 44,
            height: 44,
            flexShrink: 0,
            borderRadius: "var(--nx-radius-md)",
            cursor: "pointer",
            border: "1px solid transparent",
            background: hovered ? "var(--nx-raised)" : "transparent",
            color: hovered ? "var(--nx-ink)" : "var(--nx-ink-2)",
            marginBottom: 8,
          }}
        >
          <Icon width={20} height={20} strokeWidth={2} />
        </button>
      </TooltipTrigger>
      <TooltipContent side={isRTL ? "left" : "right"} sideOffset={16}>
        {label}
      </TooltipContent>
    </Tooltip>
  );
}

// ── Divider ───────────────────────────────────────────────────────────────────
export function Divider() {
  return (
    <div
      style={{
        width: 32,
        height: 1,
        background: "var(--nx-line)",
        margin: "12px 0",
        flexShrink: 0,
      }}
    />
  );
}

// ── Primary Rail Logo ─────────────────────────────────────────────────────────
export interface PrimaryRailLogoProps {
  tenantLogoUrl?: string | null;
  isModuleMode: boolean;
  language: string;
  onClick: () => void;
}

export function PrimaryRailLogo({
  tenantLogoUrl,
  isModuleMode,
  language,
  onClick,
}: PrimaryRailLogoProps) {
  return (
    <div
      className={cn(
        "flex shrink-0 cursor-pointer items-center justify-center transition-[color,background-color,border-color,box-shadow] duration-nx-panel ease-nx-enter motion-reduce:transition-none",
        NX_FOCUS_RING
      )}
      style={{
        width: 48,
        height: 48,
        borderRadius: "var(--nx-radius-lg)",
        // accent (L0.68/0.46) into accent-fill (L0.50) — a token gradient that
        // deepens naturally in both themes instead of a hardcoded indigo pair
        background: tenantLogoUrl
          ? "transparent"
          : "linear-gradient(135deg, var(--nx-accent) 0%, var(--nx-accent-fill) 100%)",
        marginBottom: isModuleMode ? 12 : 20,
        // No resting shadow. The hand-rolled `0 6px 20px accent` bloom read as a
        // second glow next to the ActiveIndicator (the screen gets one), and as
        // an inline style it also out-specified the focus ring, so the mark was
        // unfocusable-looking under the keyboard.
        overflow: "hidden",
        flexShrink: 0,
      }}
      onClick={onClick}
      role="link"
      tabIndex={0}
      onKeyDown={(e) => {
        // role="link" on a div is invisible to the keyboard without this
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          onClick();
        }
      }}
      aria-label={resolveBilingualLabel("Go to Home", "الصفحة الرئيسية", language)}
    >
      {tenantLogoUrl ? (
        <Image
          src={tenantLogoUrl}
          alt={resolveBilingualLabel("Logo", "شعار", language)}
          width={48}
          height={48}
          priority
          unoptimized
          style={{
            width: 48,
            height: 48,
            objectFit: "contain",
            borderRadius: "var(--nx-radius-lg)",
          }}
          onError={(e) => {
            e.currentTarget.style.display = "none";
          }}
        />
      ) : (
        <Image
          src="/brand/app-logo.svg"
          alt=""
          width={28}
          height={28}
          priority
          style={{ width: 28, height: 28, objectFit: "contain" }}
          aria-hidden="true"
        />
      )}
    </div>
  );
}

// ── Active Indicator ──────────────────────────────────────────────────────────
// The accent inline-start edge light. Its --nx-glow is THE one glow on
// screen — nothing else in the shell may wear one while it is visible.
export interface ActiveIndicatorProps {
  indicatorTop: number;
  indicatorColor: string;
  indicatorVisible: boolean;
  isRTL: boolean;
}

export function ActiveIndicator({
  indicatorTop,
  indicatorColor,
  indicatorVisible,
}: ActiveIndicatorProps) {
  return (
    <div
      // Scoped to the three properties this element actually moves. Animating
      // every property also interpolated its width, height and background on
      // each workspace accent change.
      className="z-raised transition-[top,opacity,transform] duration-nx-panel ease-nx-enter motion-reduce:transition-none"
      style={{
        position: "absolute",
        insetInlineStart: 0,
        top: indicatorTop, // aligned with container's own 4px top-padding — no extra offset needed
        width: 4,
        height: 44,
        background: indicatorColor,
        borderStartStartRadius: 0,
        borderEndStartRadius: 0,
        borderStartEndRadius: "var(--nx-radius-sm)",
        borderEndEndRadius: "var(--nx-radius-sm)",
        opacity: indicatorVisible ? 1 : 0,
        transform: indicatorVisible ? "scaleY(1)" : "scaleY(0.3)",
        boxShadow: "var(--nx-glow)",
      }}
    />
  );
}

"use client";

/**
 * NexusPrimaryRail
 *
 * Architecture (per wireframes):
 *
 *  ┌──────────┬
 *  │   LOGO   │  ← Click = navigate home
 *  ├──────────┤
 *  │ Admin    │  ← Current workspace root menu items (icon buttons)
 *  │ items... │
 *  ├──────────┤
 *  │ ════════ │  ← Divider (only if pinned workspaces exist)
 *  ├──────────┤
 *  │  [CRM]   │  ← PINNED workspaces (scrollable)
 *  │  [HRMS]  │     Pin/unpin from the App Launcher.
 *  │  [...]   │     Sorted by pinSortOrder (backend-authoritative).
 *  ├──────────┤
 *  │ ════════ │
 *  ├──────────┤
 *  │  [⊞]    │  ← App Launcher — opens grid overlay
 *  │  [🔔]   │  ← Notifications
 *  │  [👤]   │  ← User Profile
 *  └──────────┘
 *
 * Clicking an Admin root item → secondary rail shows its children.
 * Clicking a pinned workspace icon → full workspace transition.
 *
 * Colour: everything reads --nx-* tokens (globals.css) — light/dark resolves
 * in CSS, so this file carries no isDark branches. The one --nx-glow on this
 * screen belongs to the ActiveIndicator edge light.
 */

import React, { useCallback, useMemo } from "react";
import { useWorkspace } from "@core/providers/workspace-provider";
import { useI18n } from "@core/providers/i18n-provider";
import { useSettings } from "@core/providers/settings-provider";
import type { MenuItem } from "@core/navigation";
import { NotificationBell } from "@core/ui/notification";
import { UserProfileDropdown } from "@core/ui/user-profile-dropdown";
import { cn, resolveBilingualLabel } from "@core/common/utils";
import { LayoutGrid } from "lucide-react";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@core/ui/tooltip";
import { DynamicIcon, NX_FOCUS_RING } from "./_parts/primary-rail-parts";
import { useTenantBranding } from "@core/providers/tenant-branding-provider";
import { useRouter } from "next/navigation";
import { useNavigationStore } from "@core/navigation/store/useNavigationStore";
import { useWorkspaceTransitionContext } from "./nexus-layout";
import { toast } from "@core/hooks/use-enhanced-toast";
import { startRoutingProgress } from "@core/ui/routing-progress-bar";
import { usePermissions } from "@core/providers/permission-provider";
import {
  BackButton,
  Divider,
  RootItemButton,
  PrimaryRailLogo,
  ActiveIndicator,
} from "./_parts/primary-rail-parts";

interface NexusPrimaryRailProps {
  onTogglePanel?: () => void;
  isPanelCollapsed?: boolean;
  onOpenAppLauncher?: () => void;
}

// ── Helper to find the first leaf route with a valid href and permission ──────
function findFirstLeafRoute(
  item: MenuItem,
  canAccessPage: (path: string) => boolean
): string | null {
  // First try to find a route the user has permission to access
  const findAccessible = (curr: MenuItem): string | null => {
    if (curr.href && canAccessPage(curr.href)) return curr.href;
    if (curr.children && curr.children.length > 0) {
      const sorted = [...curr.children].sort((a, b) => a.order - b.order);
      for (const child of sorted) {
        const route = findAccessible(child);
        if (route) return route;
      }
    }
    return null;
  };

  const accessibleRoute = findAccessible(item);
  if (accessibleRoute) return accessibleRoute;

  // Fallback to absolute first leaf route if none are accessible
  const findAny = (curr: MenuItem): string | null => {
    if (curr.href) return curr.href;
    if (curr.children && curr.children.length > 0) {
      const sorted = [...curr.children].sort((a, b) => a.order - b.order);
      for (const child of sorted) {
        const route = findAny(child);
        if (route) return route;
      }
    }
    return null;
  };

  return findAny(item);
}

// ── Primary Rail ──────────────────────────────────────────────────────────────
export function NexusPrimaryRail({
  onTogglePanel,
  isPanelCollapsed = false,
  onOpenAppLauncher,
}: NexusPrimaryRailProps) {
  const router = useRouter();
  const { canAccessPage } = usePermissions();
  const { logoUrl: tenantLogoUrl } = useTenantBranding();
  const {
    activeWorkspace,
    rootMenuItems,
    activeRootItem,
    setActiveRootItemId,
    isModuleMode,
    workspaceGroups,
  } = useWorkspace();
  const { language, direction, t } = useI18n();
  const { showNotifications } = useSettings();
  const { switchWorkspace, goBackWorkspace } = useWorkspaceTransitionContext();

  const isRTL = direction === "rtl";

  // ── Handle admin root item click ─────────────────────────────────────────
  const handleRootItemClick = useCallback(
    (item: MenuItem) => {
      setActiveRootItemId(item.id);
      const hasChildren = Boolean(item.children && item.children.length > 0);
      if (hasChildren) {
        // Auto-open panel if it was collapsed when clicking an item with children
        if (isPanelCollapsed && onTogglePanel) {
          onTogglePanel();
        }
      }
      // Auto nav to first page of that menu item
      const firstRoute = findFirstLeafRoute(item, canAccessPage);
      if (firstRoute) {
        startRoutingProgress();
        router.push(firstRoute);
      }
    },
    [setActiveRootItemId, isPanelCollapsed, onTogglePanel, router, canAccessPage]
  );

  // ── Handle module workspace click → full workspace transition ────────────
  // Bug 6 fix: locked workspaces show a toast instead of silently trying to
  // switch. Bug 1 fix: clicking the active workspace is a no-op (the store
  // already guards against self-switch, but we skip the network round-trip).
  const handleModuleClick = useCallback(
    (wsKey: string, isLocked: boolean) => {
      if (isLocked) {
        // Show contextual toast — the workspace is locked
        const ws = workspaceGroups.find((g) => g.workspaceKey === wsKey);
        const name = resolveBilingualLabel(
          ws?.workspaceNameEn || wsKey,
          ws?.workspaceNameAr || ws?.workspaceNameEn || wsKey,
          language
        );
        toast({
          title: t("chrome.workspaceLockedToast.title", { name }),
          description: t("chrome.workspaceLockedToast.description"),
          variant: "default",
          duration: 3000,
        });
        return;
      }
      // Self-switch guard: do nothing if already on this workspace
      if (activeWorkspace?.workspaceKey === wsKey) return;
      switchWorkspace(wsKey);
    },
    [switchWorkspace, workspaceGroups, activeWorkspace, language, t, toast]
  );

  // Filter out "modules-group" from root items (it's legacy; workspaces are in the rail now)
  const adminRootItems = useMemo(
    () => rootMenuItems.filter((item) => item.slug !== "modules-group"),
    [rootMenuItems]
  );

  const activeWorkspaceKey = activeWorkspace?.workspaceKey;

  // Pinned workspaces — sorted by pinSortOrder, then alphabetically as tiebreaker.
  // Rules:
  //   1. The ACTIVE workspace is always excluded (you're already there — no point showing it).
  //   2. The FIRST workspace in sort order is ALWAYS included, even without a DB pin row.
  //      This ensures the admin always has a quick-jump to their primary workspace.
  //      "First-accessible is always pinned" replaces the old "Admin is always pinned" UX.
  const pinnedWorkspaces = useMemo(() => {
    const activeKey = activeWorkspaceKey;

    // Sort all workspaces by sortOrder to reliably find the first one
    const sorted = [...workspaceGroups].sort((a, b) => a.workspaceSortOrder - b.workspaceSortOrder);
    const primaryWorkspace = sorted[0];

    const pinned = sorted.filter(
      (ws) =>
        ws.workspaceKey !== activeKey && // never show active
        !ws.isLocked && // never pin locked workspaces
        (ws.isPinned || ws.workspaceKey === primaryWorkspace?.workspaceKey) // pinned OR first-accessible
    );

    // Sort: pinSortOrder asc, then alphabetical. Primary (sort 0) always floats first.
    return pinned.sort((a, b) => {
      // Primary workspace always goes first in the pinned section
      if (a.workspaceKey === primaryWorkspace?.workspaceKey) return -1;
      if (b.workspaceKey === primaryWorkspace?.workspaceKey) return 1;
      const aOrder = a.pinSortOrder ?? Infinity;
      const bOrder = b.pinSortOrder ?? Infinity;
      return aOrder !== bOrder
        ? aOrder - bOrder
        : a.workspaceNameEn.localeCompare(b.workspaceNameEn);
    });
  }, [workspaceGroups, activeWorkspaceKey]);

  // Primary admin workspace: the admin-type workspace with the lowest sort order.
  // The back button shows ONLY when the admin actually has an admin workspace in their
  // accessible list. CRM-only operators never see a back button.
  const primaryAdminKey = useMemo(
    () =>
      workspaceGroups
        .filter((ws) => ws.isAdminWorkspace && !ws.isLocked)
        .sort((a, b) => a.workspaceSortOrder - b.workspaceSortOrder)[0]?.workspaceKey ?? null,
    [workspaceGroups]
  );
  const isOnPrimaryAdmin = activeWorkspaceKey === primaryAdminKey;
  // Only show back button when:
  //   1. Admin has an admin workspace in their access list
  //   2. A workspace IS selected (not on the Hub page where activeWorkspace is null)
  //   3. Not already on the primary admin workspace
  const showBackButton = primaryAdminKey !== null && activeWorkspace !== null && !isOnPrimaryAdmin;

  const hasPinnedWorkspaces = pinnedWorkspaces.length > 0;

  // Calculate index for the magic indicator (admin items only)
  const activeIndex = adminRootItems.findIndex((i) => i.id === activeRootItem?.id);

  let indicatorTop = -100; // Hidden offscreen by default
  // The verified workspace accent — --nx-accent tracks --workspace-hue in CSS
  const indicatorColor = "var(--nx-accent)";
  let indicatorVisible = false;

  if (activeIndex >= 0) {
    // Each button is 44px tall with margin: "4px 0".
    // Flexbox margins DO NOT collapse, so the stride between buttons is 44 + 8 = 52px.
    // The first button is offset by its own margin-top: 4px.
    indicatorTop = activeIndex * 52 + 4;
    indicatorVisible = true;
  }

  return (
    <nav
      aria-label={t("navigation.primaryNav")}
      className="relative z-raised flex flex-shrink-0 flex-col items-center"
      style={{
        width: "var(--nexus-primary-w)",
        minWidth: "var(--nexus-primary-w)",
        maxWidth: "var(--nexus-primary-w)",
        height: "100%",
        /* Critical: block horizontal scroll caused by absolute-positioned tooltips */
        overflowX: "hidden",
        overflowY: "hidden",
        background: "var(--nx-ground)",
        borderInlineEnd: "1px solid var(--nx-line)",
        padding: "16px 0",
        /* theme-switch crossfade — colour only, so it survives reduced motion */
        transition:
          "background var(--nx-t-standard) var(--nx-ease-enter), border-color var(--nx-t-standard) var(--nx-ease-enter)",
        boxSizing: "border-box",
      }}
    >
      {/* ONE tooltip provider for the whole rail — shared ~150ms delay grouping
          instead of the previous provider-per-button setup */}
      <TooltipProvider delayDuration={150}>
        {/* ── Logo mark — click navigates home ───────────────────── */}
        <PrimaryRailLogo
          tenantLogoUrl={tenantLogoUrl}
          isModuleMode={isModuleMode}
          language={language}
          onClick={() => {
            // Clear workspace key so Hub page shows clean state
            // (secondary rail collapses, back button hides, admin items clear)
            useNavigationStore.getState().setActiveWorkspace(null);
            startRoutingProgress();
            router.push("/");
          }}
        />

        {/* ── Back button — visible only when admin has an admin workspace AND is not on it ── */}
        {/* CRM-only operators never see this — they have no admin workspace in their access list. */}
        {showBackButton && (
          <>
            <BackButton
              isRTL={isRTL}
              label={t("chrome.backToAdmin")}
              onClick={goBackWorkspace}
            />
            <Divider />
          </>
        )}

        {/* ── Scrollable area: Admin items + Pinned workspace icons ── */}
        <div
          className="nexus-rail-scroll relative flex w-full flex-1 flex-col items-center"
          style={{
            padding: "4px 0 16px",
            overflowY: "auto",
            overflowX: "hidden",
            scrollbarWidth: "none" /* Firefox: completely hidden by default */,
          }}
          onMouseEnter={(e) => e.currentTarget.classList.add("is-hovered")}
          onMouseLeave={(e) => e.currentTarget.classList.remove("is-hovered")}
        >
          {/* Magic Sliding Indicator (admin root items only) — carries the ONE
              --nx-glow on this screen */}
          <ActiveIndicator
            indicatorTop={indicatorTop}
            indicatorColor={indicatorColor}
            indicatorVisible={indicatorVisible}
            isRTL={isRTL}
          />

          {/* Admin root items as icon buttons */}
          {adminRootItems.map((item) => (
            <RootItemButton
              key={item.id}
              item={item}
              isActive={activeRootItem?.id === item.id}
              isRTL={isRTL}
              language={language}
              onClick={handleRootItemClick}
            />
          ))}

          {/* ── Pinned workspaces (individual icons below divider) ────────── */}
          {/* Only pinned workspaces show here. Pin/unpin from App Launcher (⊞ button) */}
          {hasPinnedWorkspaces && (
            <>
              <Divider />
              {pinnedWorkspaces.map((ws) => {
                const isActive = activeWorkspace?.workspaceKey === ws.workspaceKey;
                // Pins keep their own workspace colour; the token is the fallback
                const wsAccent = ws.accentColor || "var(--nx-accent)";
                const wsLabel = resolveBilingualLabel(
                  ws.workspaceNameEn || ws.workspaceNameAr,
                  ws.workspaceNameAr || ws.workspaceNameEn,
                  language
                );

                return (
                  <ModuleWorkspaceButton
                    key={ws.workspaceKey}
                    label={wsLabel}
                    abbreviation={ws.abbreviation}
                    icon={ws.workspaceIcon}
                    accentColor={wsAccent}
                    isActive={isActive}
                    isRTL={isRTL}
                    isLocked={ws.isLocked}
                    onClick={() => handleModuleClick(ws.workspaceKey, ws.isLocked)}
                  />
                );
              })}
            </>
          )}
        </div>

        {/* ── Bottom actions ─────────────────────────────────────── */}
        <div className="relative flex shrink-0 flex-col items-center gap-2 pb-2 pt-4">
          {/* {onTogglePanel && (
            <TogglePanelButton
              isRTL={isRTL}
              isCollapsed={isPanelCollapsed}
              label={t("navigation.togglePanel")}
              onClick={onTogglePanel}
            />
          )} */}

          {/* App Launcher (⊞) — opens searchable workspace grid overlay */}
          {onOpenAppLauncher && (
            <Tooltip>
              <TooltipTrigger asChild>
                <button
                  type="button"
                  aria-label={t("shell.launcher.title")}
                  onClick={onOpenAppLauncher}
                  className={cn(
                    "flex items-center justify-center rounded-nx-md border border-transparent text-nx-ink-2 transition-[color,background-color,border-color,box-shadow] duration-nx-standard ease-nx-enter hover:border-nx-line-hi hover:bg-nx-raised hover:text-nx-ink motion-reduce:transition-none",
                    NX_FOCUS_RING
                  )}
                  style={{ width: 44, height: 44 }}
                >
                  <LayoutGrid size={20} aria-hidden="true" />
                </button>
              </TooltipTrigger>
              <TooltipContent side={isRTL ? "left" : "right"} sideOffset={16}>
                {t("shell.launcher.title")}
              </TooltipContent>
            </Tooltip>
          )}

          <Divider />

          {/* ── Identity cluster ──────────────────────────────────────────
              Notifications sit DIRECTLY above the profile avatar: one
              "this is you, this is yours" group at the foot of the rail.

              The bell still honours the showNotifications setting — the
              regression that hid it for everyone was the setting's DEFAULT
              (false in settings/defaults.ts while nothing read the flag), not
              this wiring. Default is true now; an admin who switches it off
              collapses the cluster to the avatar alone and the rhythm holds. */}
          <div className="flex w-full flex-col items-center gap-2">
            {showNotifications && (
              <Tooltip>
                <TooltipTrigger asChild>
                  <div className="flex items-center justify-center">
                    <NotificationBell
                      iconClassName="h-[20px] w-[20px]"
                      className="h-[44px] w-[44px] rounded-nx-md border border-transparent text-nx-ink-2 transition-[color,background-color,border-color,box-shadow] duration-nx-standard ease-nx-enter hover:border-nx-line-hi hover:bg-nx-raised hover:text-nx-ink motion-reduce:transition-none"
                    />
                  </div>
                </TooltipTrigger>
                <TooltipContent side={isRTL ? "left" : "right"} sideOffset={16}>
                  {t("nav.notifications")}
                </TooltipContent>
              </Tooltip>
            )}

            {/* The open menu lights its own trigger (data-state=open → accent
                edge) instead of the old scale-on-hover/press pair: light
                collects on the active thing, transforms are noise. */}
            <UserProfileDropdown
              variant="compact"
              showName={false}
              side={isRTL ? "left" : "right"}
              align="end"
              className="h-[40px] w-[40px] cursor-pointer rounded-full border-[1.5px] border-nx-line !p-0 shadow-nx-sm transition-[border-color,box-shadow,background-color] duration-nx-micro ease-nx-enter hover:border-nx-line-hi hover:bg-nx-hover data-[state=open]:border-nx-accent motion-reduce:transition-none"
            />
          </div>
        </div>
      </TooltipProvider>
    </nav>
  );
}

// ── Module Workspace Button (colored pill icon) ────────────────────────────────

interface ModuleWorkspaceButtonProps {
  label: string;
  abbreviation: string;
  icon: string;
  accentColor: string;
  isActive: boolean;
  isRTL: boolean;
  /** Backend-driven: true = module not licensed for current tenant */
  isLocked?: boolean;
  onClick: () => void;
}

function ModuleWorkspaceButton({
  label,
  abbreviation,
  icon,
  accentColor,
  isActive,
  isRTL,
  isLocked = false,
  onClick,
}: ModuleWorkspaceButtonProps) {
  const [hovered, setHovered] = React.useState(false);
  const { language, t } = useI18n();
  const lockedLabel = `${label} (${t("chrome.section.locked")})`;

  // Identity colour stays per-workspace (accentColor is data, not styling);
  // every neutral state reads an --nx-* token so no theme branch is needed.
  const bgColor = (() => {
    if (isActive) return `color-mix(in oklch, ${accentColor} 13%, transparent)`;
    if (hovered) return "var(--nx-raised)";
    return "transparent";
  })();

  const iconColor = (() => {
    if (isActive) return accentColor;
    if (hovered) return "var(--nx-ink)";
    return "var(--nx-ink-3)";
  })();

  const borderColor = (() => {
    if (isActive) return `color-mix(in oklch, ${accentColor} 33%, transparent)`;
    if (hovered) return "var(--nx-line-hi)";
    return "transparent";
  })();

  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <button
          type="button"
          aria-label={isLocked ? lockedLabel : label}
          aria-pressed={isActive}
          aria-disabled={isLocked}
          onClick={isLocked ? undefined : onClick}
          onMouseEnter={() => setHovered(true)}
          onMouseLeave={() => setHovered(false)}
          className={cn(
            "group relative flex items-center justify-center transition-[color,background-color,border-color,box-shadow] duration-nx-standard ease-nx-enter motion-reduce:transition-none",
            // An active pin is the only lit thing when it renders (the rail
            // filters the active workspace out of pins, so in practice at most
            // one glow ever exists on screen). It lives in a class, not inline:
            // an inline box-shadow beat the focus ring, so an active pin showed
            // no keyboard focus at all.
            isActive && "shadow-nx-glow",
            NX_FOCUS_RING
          )}
          style={{
            width: 44,
            height: 44,
            flexShrink: 0,
            borderRadius: "var(--nx-radius-md)",
            cursor: isLocked ? "not-allowed" : "pointer",
            border: `1.5px solid ${isLocked ? "var(--nx-line)" : borderColor}`,
            background: isLocked ? "color-mix(in oklch, var(--nx-ink) 4%, transparent)" : bgColor,
            color: isLocked ? "var(--nx-ink-3)" : iconColor,
            margin: "4px 0",
            opacity: isLocked ? 0.55 : 1,
          }}
        >
          {/* Active edge ring — STATIC.
              This carried `animate-pulse`, an unbounded 2s opacity loop that
              ran for as long as a workspace was active, i.e. permanently. That
              is the idle pulse the product owner reported seeing on the rail,
              and it breaks the brand law directly: light collects on the
              active thing, never as an idle animation. The ring itself is the
              correct signal and stays — a lit accent edge on the active pin,
              paired with the --nx-glow box-shadow above. Only the loop is
              gone, so there is no longer any motion to gate on reduced-motion
              and nothing about the active state is lost. */}
          {isActive && (
            <div
              style={{
                position: "absolute",
                inset: -2,
                borderRadius: "var(--nx-radius-lg)",
                border: `2px solid color-mix(in oklch, ${accentColor} 25%, transparent)`,
                pointerEvents: "none",
              }}
            />
          )}
          {/* Lock overlay for locked modules */}
          {isLocked && (
            <div
              style={{
                position: "absolute",
                bottom: 2,
                insetInlineEnd: 2,
                width: 14,
                height: 14,
                borderRadius: "50%",
                background: "var(--nx-surface)",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                fontSize: 8,
                color: "hsl(var(--warning))",
                border: "1px solid hsl(var(--warning) / 0.3)",
                pointerEvents: "none",
              }}
            >
              🔒
            </div>
          )}
          <DynamicIcon name={icon} size={20} />
        </button>
      </TooltipTrigger>
      <TooltipContent side={isRTL ? "left" : "right"} sideOffset={16}>
        {isLocked ? lockedLabel : label}
      </TooltipContent>
    </Tooltip>
  );
}

"use client";

/**
 * NexusTopbar
 *
 * 56px header for the Nexus Dual-Rail Layout, on the --nx- token layer.
 * - Panel toggle uses the same custom SVG icons as navigation-header.tsx (PanelMenuIcon / PanelCollapseIcon)
 * - Breadcrumbs are RTL-aware (flex-row-reverse + mirrored chevron)
 * - Background derived from --nx-surface + settings card style (glass/solid/default)
 * - Home button shown whenever pathname !== "/"
 * - Search palette trigger
 *
 * Settings behaviour (the topbar rides inside the layout's scroll region):
 * - stickyHeader: sticky pins it to the top edge; off lets it scroll away
 * - showBreadcrumbs: swaps the breadcrumb trail for a plain spacer
 * - showNotifications: gates the mobile-controls notification bell
 * - collapsibleSidebar: off hides the desktop panel toggle (mobile keeps its hamburger)
 *
 * Colour resolves in CSS per theme — no resolvedTheme reads, no hydration
 * placeholder needed.
 */

import { useI18n } from "@core/providers/i18n-provider";
import { useWorkspace } from "@core/providers/workspace-provider";
import { useSettings } from "@core/providers/settings-provider";
import { LanguageSwitcher, NxThemeSwitcher } from "@core/ui/layout/common";
import { usePathname, useRouter } from "next/navigation";
import { useAppStore } from "@core/store/useAppStore";
import { BRAND } from "@core/config/branding";
import { cn, resolveBilingualLabel } from "@core/common/utils";
import {
  TopbarBreadcrumbs,
  TopbarContextPill,
  TopbarHomeButton,
  TopbarMobileControls,
  TopbarPanelToggle,
  TopbarSearchButton,
} from "./_parts/topbar-parts";
import { useNavigationStore } from "@/core/navigation/store/useNavigationStore";
import { startRoutingProgress } from "@core/ui/routing-progress-bar";

interface NexusTopbarProps {
  onMobileMenuOpen: () => void;
  onTogglePanel?: () => void;
  onOpenSearch?: () => void;
  isPanelCollapsed?: boolean;
}

export function NexusTopbar({
  onMobileMenuOpen,
  onTogglePanel,
  onOpenSearch,
  isPanelCollapsed,
}: NexusTopbarProps) {
  const { direction, language, t } = useI18n();
  const { activeWorkspace, activeRootItem, isModuleMode } = useWorkspace();
  const { cardStyle, showBreadcrumbs, showNotifications, stickyHeader, collapsibleSidebar } =
    useSettings();
  const pathname = usePathname();
  const router = useRouter();
  const user = useAppStore((s) => s.user);
  const tenantCode = useAppStore((s) => s.tenantCode);

  const isRTL = direction === "rtl";

  // ── Breadcrumb segments ───────────────────────────────────────────────────
  const breadcrumbOverride = useNavigationStore((s) => s.breadcrumbOverride);
  const segments = pathname.split("/").filter(Boolean);
  const pageName = segments[segments.length - 1] ?? "";
  const parentName = segments[segments.length - 2] ?? "";
  const formattedPage = pageName.replace(/-/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());

  const workspaceName =
    activeWorkspace?.getLocalizedName(language) ?? BRAND?.name ?? t("chrome.section.platform");
  const activeRootName = activeRootItem
    ? resolveBilingualLabel(
        activeRootItem.nameEn || activeRootItem.nameAr,
        activeRootItem.nameAr || activeRootItem.nameEn,
        language
      )
    : null;

  const isIdString = (str: string): boolean => {
    if (!str) return false;
    const isGuid =
      /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/.test(str);
    if (isGuid) return true;
    const isEncrypted = str.length >= 20 && /^[a-zA-Z0-9_\-+ /=]+$/.test(str);
    return isEncrypted;
  };

  const formatParentSegmentAsTitle = (parentSegment: string): string => {
    if (!parentSegment) return t("common.details");
    let word = parentSegment.replace(/[-_]/g, " ");
    if (word.toLowerCase().endsWith("s") && word.length > 1) {
      word = word.slice(0, -1);
    }
    const capitalized = word.replace(/\b\w/g, (c) => c.toUpperCase());
    return t("navigation.entityDetailsTitle", { entity: capitalized });
  };

  let displayPageName = formattedPage;
  if (breadcrumbOverride) {
    displayPageName = breadcrumbOverride;
  } else if (isIdString(pageName)) {
    displayPageName = formatParentSegmentAsTitle(parentName);
  } else if (activeRootItem && activeRootItem.children) {
    let bestMatch: any = null;
    let maxLen = 0;
    const search = (nodes: any[]) => {
      for (const item of nodes) {
        if (item.href && (pathname === item.href || pathname.startsWith(item.href + "/"))) {
          if (item.href.length > maxLen) {
            maxLen = item.href.length;
            bestMatch = item;
          }
        }
        if (item.children) search(item.children);
      }
    };
    search(activeRootItem.children);
    if (bestMatch) {
      displayPageName = resolveBilingualLabel(
        bestMatch.nameEn || bestMatch.nameAr || formattedPage,
        bestMatch.nameAr || bestMatch.nameEn || formattedPage,
        language
      );
    }
  }

  // ── Context pill text ────────────────────────────────────────────────────
  const tenantName =
    (user as any)?.tenantName ??
    (user?.firstName
      ? `${user.firstName} ${user?.lastName ?? ""}`.trim()
      : (BRAND?.name ?? t("chrome.section.platform")));

  // ── Background — derived from cardStyle setting, surface token only ───────
  // Glass is the ONE opt-in frosted surface in this system, so it keeps its
  // blur. The default branch used to be "subtle glass" — a frost nobody asked
  // for, applied to the bar every page scrolls under. Default and solid are the
  // same thing now: an opaque surface step behind a hairline.
  const bgStyle = (() => {
    if (cardStyle === "glass") {
      return {
        background: "color-mix(in oklch, var(--nx-surface, hsl(var(--card))) 62%, transparent)",
        backdropFilter: "blur(16px)",
        WebkitBackdropFilter: "blur(16px)",
      };
    }
    return {
      background: "var(--nx-surface, hsl(var(--card)))",
      backdropFilter: "none",
    };
  })();

  // ── Home route — context-aware, backend-authoritative per workspace ───────────
  // Platform context (no tenant): use platformHomeRoute > homeRoute > "/"
  // Tenant context: use homeRoute > "/"
  const isPlatformContext = tenantCode === null;
  const workspaceHomeRoute = isPlatformContext
    ? (activeWorkspace?.platformHomeRoute ?? activeWorkspace?.homeRoute ?? "/")
    : (activeWorkspace?.homeRoute ?? "/");
  const isOnHome =
    pathname === workspaceHomeRoute || (workspaceHomeRoute === "/" && pathname === "/");

  return (
    <header
      data-nexus-topbar=""
      // Sticky pins the bar to the scroll region's top edge; z-sticky keeps
      // passing content (z-raised and below) under the glass. Non-sticky just
      // flows — it scrolls away with the page.
      className={cn(stickyHeader ? "sticky top-0 z-sticky" : "relative z-raised")}
      style={{
        height: 56,
        minHeight: 56,
        flexShrink: 0,
        borderBottom: "1px solid var(--nx-line, hsl(var(--border)))",
        display: "flex",
        alignItems: "center",
        paddingInlineStart: 20,
        paddingInlineEnd: 12,
        gap: 12,
        direction: isRTL ? "rtl" : "ltr",
        ...bgStyle,
      }}
    >
      {/* Mobile hamburger / Desktop Panel Toggle */}
      {(() => {
        const hasSubmenu = Boolean(activeRootItem?.children && activeRootItem.children.length > 0);
        return (
          <TopbarPanelToggle
            isRTL={isRTL}
            isPanelCollapsed={isPanelCollapsed}
            collapsible={collapsibleSidebar && hasSubmenu}
            ariaLabel={t("navigation.togglePanel")}
            onToggle={() => {
              if (typeof window !== "undefined" && window.innerWidth < 1024) {
                onMobileMenuOpen();
              } else if (onTogglePanel) {
                onTogglePanel();
              }
            }}
          />
        );
      })()}

      {/* Breadcrumbs — the spacer keeps the right-side controls parked at the
          inline end when the trail is switched off */}
      {showBreadcrumbs ? (
        <TopbarBreadcrumbs
          isRTL={isRTL}
          workspaceName={workspaceName}
          activeRootName={activeRootName}
          displayPageName={displayPageName}
        />
      ) : (
        <div aria-hidden style={{ flex: 1, minWidth: 0 }} />
      )}

      {/* Right-side controls */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 8,
          flexShrink: 0,
        }}
      >
        <TopbarContextPill isModuleMode={isModuleMode} tenantName={tenantName} />

        <TopbarSearchButton
          onOpenSearch={onOpenSearch}
          placeholder={t("navigation.searchPlaceholder")}
        />

        {!isOnHome && (
          <TopbarHomeButton
            ariaLabel={t("chrome.goToHome")}
            onClick={() => {
              startRoutingProgress();
              router.push(workspaceHomeRoute);
            }}
          />
        )}

        <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
          <NxThemeSwitcher buttonClassName="h-[33px] w-[33px] text-nx-ink-3 hover:text-nx-ink hover:bg-nx-raised rounded-nx-control transition-[color,background-color,border-color,box-shadow] duration-nx-micro motion-reduce:transition-none" />
          <LanguageSwitcher buttonClassName="h-[33px] w-[46px] text-nx-ink-3 hover:text-nx-ink hover:bg-nx-raised rounded-nx-control transition-[color,background-color,border-color,box-shadow] duration-nx-micro motion-reduce:transition-none" />
        </div>

        <TopbarMobileControls showNotifications={showNotifications} />
      </div>
    </header>
  );
}

"use client";

import * as React from "react";
import { Check, ChevronsUpDown } from "lucide-react";
import * as RPNInput from "react-phone-number-input";
import flags from "react-phone-number-input/flags";
import { getExampleNumber, parsePhoneNumberFromString } from "libphonenumber-js";
import examples from "libphonenumber-js/examples.mobile.json";

import { Button } from "@core/ui/button";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@core/ui/command";
import { Popover, PopoverContent, PopoverTrigger } from "@core/ui/popover";
import { resolveFieldStyle } from "@core/ui/input";
import { cn } from "@core/common/utils";
import { useI18n } from "@core/providers/i18n-provider";
import { useSettings } from "@core/providers/settings-provider";

import en from "react-phone-number-input/locale/en.json";
import ar from "react-phone-number-input/locale/ar.json";

export interface PhoneInputProps extends Omit<
  React.InputHTMLAttributes<HTMLInputElement>,
  "onChange" | "value"
> {
  value?: string;
  onChange?: (value: string) => void;
  error?: string;
  defaultCountry?: RPNInput.Country;
}

/**
 * Detect user's default country code based on their browser language and timezone.
 * Returns a fallback country code if detection fails.
 */
function detectUserCountry(): RPNInput.Country {
  if (typeof navigator !== "undefined" && navigator.languages) {
    for (const lang of navigator.languages) {
      const parts = lang.split("-");
      if (parts.length === 2 && parts[1].length === 2) {
        return parts[1].toUpperCase() as RPNInput.Country;
      }
    }
  }

  try {
    const tz = Intl.DateTimeFormat().resolvedOptions().timeZone;
    if (tz) {
      const tzLower = tz.toLowerCase();
      if (tzLower.includes("cairo") || tzLower.includes("egypt")) return "EG";
      if (tzLower.includes("riyadh") || tzLower.includes("saudi")) return "SA";
      if (tzLower.includes("dubai") || tzLower.includes("uae")) return "AE";
      if (tzLower.includes("london") || tzLower.includes("europe/london")) return "GB";
      if (tzLower.includes("paris")) return "FR";
      if (tzLower.includes("berlin")) return "DE";
      if (tzLower.includes("tokyo")) return "JP";
      if (tzLower.includes("sydney")) return "AU";
      if (tzLower.includes("casablanca")) return "MA";
      if (tzLower.includes("tunis")) return "TN";
      if (
        tzLower.includes("new_york") ||
        tzLower.includes("los_angeles") ||
        tzLower.includes("chicago") ||
        tzLower.includes("america")
      ) {
        return "US";
      }
    }
  } catch {
    /* ignore */
  }

  return "US";
}

/**
 * Formats a mobile number placeholder dynamically based on the active country.
 */
function getPlaceholderForCountry(country?: RPNInput.Country, fallback?: string): string {
  if (!country) return fallback || "Enter phone number";
  try {
    const example = getExampleNumber(country, examples);
    if (example) {
      return example.formatInternational();
    }
  } catch {
    /* ignore */
  }
  return fallback || "Enter phone number";
}

/**
 * Gets the expected national phone number length for a country.
 */
function getExpectedLengthForCountry(country?: RPNInput.Country): number {
  if (!country) return 10;
  try {
    const example = getExampleNumber(country, examples);
    if (example) {
      return example.nationalNumber.length;
    }
  } catch {
    /* ignore */
  }
  return 10;
}

/**
 * Computes the length of the currently entered national number digits.
 */
function getEnteredLength(value: string, country?: RPNInput.Country): number {
  if (!value) return 0;
  try {
    const phoneNumber = parsePhoneNumberFromString(value, country);
    if (phoneNumber) {
      return phoneNumber.nationalNumber.length;
    }
  } catch {
    /* ignore */
  }

  // Fallback to manual digits parsing
  const digits = value.replace(/\D/g, "");
  if (country) {
    try {
      const callingCode = RPNInput.getCountryCallingCode(country);
      if (digits.startsWith(callingCode)) {
        return digits.length - callingCode.length;
      }
    } catch {
      /* ignore */
    }
  }
  return digits.length;
}

const PhoneInput = React.forwardRef<HTMLInputElement, PhoneInputProps>(
  ({ className, onChange, value = "", error, defaultCountry, ...props }, ref) => {
    const { language, direction, t } = useI18n();
    const settings = useSettings();
    const isRTL = direction === "rtl";
    const labels = language === "ar" ? ar : en;

    const handleValueChange = React.useCallback(
      (val?: string) => {
        onChange?.(val || "");
      },
      [onChange]
    );

    const detectedDefaultCountry = React.useMemo(() => {
      return defaultCountry || detectUserCountry();
    }, [defaultCountry]);

    const [activeCountry, setActiveCountry] = React.useState<RPNInput.Country | undefined>(
      detectedDefaultCountry
    );

    // Sync state when defaultCountry changes
    React.useEffect(() => {
      if (defaultCountry) {
        queueMicrotask(() => {
          setActiveCountry(defaultCountry);
        });
      }
    }, [defaultCountry]);

    // Sync activeCountry when value changes (e.g. paste or typing international code)
    React.useEffect(() => {
      if (!value) return;
      try {
        const parsed = RPNInput.parsePhoneNumber(value);
        if (parsed?.country) {
          queueMicrotask(() => {
            setActiveCountry(parsed.country);
          });
        }
      } catch {
        /* ignore */
      }
    }, [value]);

    // The Settings inputStyle values, mapped onto the same token-backed
    // treatments as the Wave-A Input recipe (legacy stored values fall back
    // to default through resolveFieldStyle).
    const inputStyle = settings.inputStyle;
    const resolvedStyle = resolveFieldStyle(inputStyle);
    const containerRoundedClass =
      resolvedStyle === "underlined"
        ? "rounded-none border-0 border-b border-nx-line px-0"
        : resolvedStyle === "rounded"
          ? "rounded-full px-1"
          : resolvedStyle === "filled"
            ? "rounded-nx-control border-transparent bg-nx-raised"
            : "rounded-nx-control";

    // Focus lights the edge — the composite field carries the Input recipe on
    // focus-within: border to accent plus the --nx-focus inset line/wash ring.
    const focusClasses =
      resolvedStyle === "underlined"
        ? "focus-within:border-nx-accent"
        : "focus-within:border-nx-accent focus-within:shadow-nx-focus";

    // The select's outer corners are always the field's start side; logical
    // classes resolve them per direction, so no isRTL fork is needed here.
    const selectRoundedClass =
      resolvedStyle === "underlined"
        ? "rounded-none"
        : resolvedStyle === "rounded"
          ? "rounded-s-full"
          : "rounded-s-nx-control";

    // The number input is remount-sensitive (a new component identity drops
    // focus mid-typing), so it is memoised with EMPTY deps. aria-invalid
    // therefore rides down as a prop on RPNInput below — the library forwards
    // unknown props to this component — instead of being closed over here.
    const PhoneInputComponent = React.useMemo(() => {
      return React.forwardRef<HTMLInputElement, any>(
        function PhoneInputComponent(inputProps, inputRef) {
          return (
            <input
              {...inputProps}
              ref={inputRef}
              className={cn(
                // the composite frame owns the surface; the input contributes
                // only type and ink — inert ink comes from the token, never
                // from a half-transparent value
                "h-full w-full flex-1 bg-transparent px-3 py-2 text-base tabular-nums placeholder:text-nx-ink-3 focus:outline-none disabled:cursor-not-allowed disabled:text-nx-ink-3 md:text-sm",
                inputProps.className
              )}
            />
          );
        }
      );
    }, []);

    const isDisabled = props.disabled;
    const CountrySelectComponent = React.useMemo(() => {
      return function CountrySelectComponent({
        value: countryVal,
        onChange: onCountryChange,
        options,
      }: any) {
        return (
          <CountrySelect
            value={countryVal}
            onChange={(newCountry) => {
              onCountryChange(newCountry);
              setActiveCountry(newCountry);
            }}
            options={options}
            disabled={isDisabled}
            labels={labels}
            roundedClass={selectRoundedClass}
            isRTL={isRTL}
          />
        );
      };
    }, [isDisabled, labels, selectRoundedClass, isRTL]);

    const placeholder =
      props.placeholder ||
      getPlaceholderForCountry(activeCountry, t("components.phoneInput.placeholder"));

    const expectedLength = getExpectedLengthForCountry(activeCountry);

    const enteredLength = getEnteredLength(value, activeCountry);

    return (
      <div className="w-full">
        <RPNInput.default
          ref={ref as any}
          className={cn(
            // The shared field surface: sunken ground behind a hairline, the
            // same hover lift and inert slab Input wears — a composite field
            // must not read as a different control from a plain one.
            "flex items-center border border-nx-line bg-nx-ground text-sm text-nx-ink transition-[border-color,background-color,box-shadow] duration-nx-micro ease-nx-enter motion-reduce:transition-none",
            "hover:border-nx-line-hi",
            "has-[input:disabled]:cursor-not-allowed has-[input:disabled]:border-nx-line has-[input:disabled]:bg-nx-raised has-[input:disabled]:shadow-none",
            containerRoundedClass,
            focusClasses,
            // Error re-hues the lit edge to the measured danger token — same
            // geometry as --nx-focus, different hue, so the field reads wrong
            // without shouting.
            error &&
              "border-nx-danger focus-within:border-nx-danger focus-within:shadow-[inset_0_0_0_1px_var(--nx-danger),0_0_0_3px_color-mix(in_srgb,var(--nx-danger)_18%,transparent)] hover:border-nx-danger",
            className
          )}
          dir={direction}
          style={{
            background: props.style?.background,
            borderColor: error ? undefined : props.style?.borderColor,
            color: props.style?.color,
          }}
          flagComponent={FlagComponent}
          countrySelectComponent={CountrySelectComponent}
          inputComponent={PhoneInputComponent}
          value={value}
          onChange={handleValueChange}
          defaultCountry={detectedDefaultCountry}
          labels={labels}
          placeholder={placeholder}
          // forwarded to the inner input by the library, so the number field
          // announces itself as invalid the moment the frame turns danger
          aria-invalid={error ? true : undefined}
          {...props}
        />
        {/* Hint row: instruction on the start edge, live digit count on the
            end. Tabular figures so the counter does not shuffle as it fills,
            and it goes success-ink only at the exact expected length. */}
        {activeCountry && (
          <div
            className="mt-1.5 flex items-center justify-between gap-3 px-1 text-xs text-nx-ink-3"
            dir={direction}
          >
            <span>{t("components.phoneInput.enterNational")}</span>
            <span
              className={cn(
                "shrink-0 font-mono tabular-nums transition-colors duration-nx-micro ease-nx-enter motion-reduce:transition-none",
                enteredLength === expectedLength && "font-semibold text-nx-success"
              )}
            >
              {enteredLength}/{expectedLength} {t("components.phoneInput.digits")}
            </span>
          </div>
        )}
      </div>
    );
  }
);
PhoneInput.displayName = "PhoneInput";

type CountrySelectOption = { label: string; value: RPNInput.Country };

interface CountrySelectProps {
  disabled?: boolean;
  value: RPNInput.Country;
  onChange: (value: RPNInput.Country) => void;
  options: CountrySelectOption[];
  labels: Record<string, string>;
  roundedClass: string;
  isRTL: boolean;
}

const CountrySelect = ({
  disabled,
  value,
  onChange,
  options,
  labels,
  roundedClass,
  isRTL,
}: CountrySelectProps) => {
  const [open, setOpen] = React.useState(false);
  const { t } = useI18n();

  const handleSelect = React.useCallback(
    (country: RPNInput.Country) => {
      onChange(country);
      setOpen(false);
    },
    [onChange]
  );

  const triggerOption = options.find((option) => option.value === value);
  const countryName = triggerOption ? labels[triggerOption.value] || triggerOption.label : "";

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          type="button"
          variant="ghost"
          className={cn(
            // Rides Button's own focus treatment (the --nx-focus lit edge);
            // z-raised keeps the lit trigger above the field's hairline.
            "flex h-full shrink-0 items-center gap-2 rounded-none border-0 bg-transparent px-3 text-nx-ink hover:bg-nx-hover focus-visible:z-raised disabled:text-nx-ink-3",
            roundedClass,
            "border-e border-nx-line"
          )}
          disabled={disabled}
          aria-label={countryName || t("components.phoneInput.searchPlaceholder")}
        >
          <FlagComponent country={value} countryName={countryName} />
          {value && (
            <span className="text-sm font-medium tabular-nums">
              +{RPNInput.getCountryCallingCode(value)}
            </span>
          )}
          <ChevronsUpDown
            className={cn("h-4 w-4 shrink-0 text-nx-ink-3", disabled && "hidden")}
            aria-hidden="true"
          />
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-[300px] p-0" align={isRTL ? "end" : "start"}>
        <Command>
          <CommandInput placeholder={t("components.phoneInput.searchPlaceholder")} />
          <CommandList>
            <CommandEmpty>{t("components.phoneInput.emptyState")}</CommandEmpty>
            <CommandGroup>
              {options
                .filter((x) => x.value)
                .map((option) => {
                  const name = labels[option.value] || option.label;
                  return (
                    <CommandItem
                      className="flex cursor-pointer items-center gap-2"
                      key={option.value}
                      onSelect={() => handleSelect(option.value)}
                    >
                      <FlagComponent country={option.value} countryName={name} />
                      <span className="flex-1 truncate text-sm">{name}</span>
                      {/* dial codes are a column of digits — tabular figures
                          keep them aligned down the list */}
                      <span className="shrink-0 font-mono text-sm tabular-nums text-nx-ink-3">
                        +{RPNInput.getCountryCallingCode(option.value)}
                      </span>
                      <Check
                        className={cn(
                          "h-4 w-4 shrink-0 text-nx-accent",
                          option.value === value ? "visible" : "invisible"
                        )}
                        aria-hidden="true"
                      />
                    </CommandItem>
                  );
                })}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
};

const FlagComponent = ({ country, countryName }: RPNInput.FlagProps) => {
  const Flag = flags[country];

  // No flag art for a country renders the neutral raised swatch alone —
  // never an emoji placeholder, which rendered as tofu on several platforms.
  return (
    <span className="flex h-4 w-6 shrink-0 items-center justify-center overflow-hidden rounded-nx-sm border border-nx-line bg-nx-raised-2">
      {Flag ? <Flag title={countryName} /> : null}
    </span>
  );
};
FlagComponent.displayName = "FlagComponent";

export { PhoneInput };
export { isValidPhoneNumber } from "react-phone-number-input";
export type { Country } from "react-phone-number-input";

"use client";

import React, { useCallback, useState } from "react";
import { useEditor, EditorContent } from "@tiptap/react";
import StarterKit from "@tiptap/starter-kit";
import Underline from "@tiptap/extension-underline";
import { TextStyle } from "@tiptap/extension-text-style";
import Color from "@tiptap/extension-color";
import Highlight from "@tiptap/extension-highlight";
import TextAlign from "@tiptap/extension-text-align";
import ImageExtension from "@tiptap/extension-image";
import Link from "@tiptap/extension-link";
import Placeholder from "@tiptap/extension-placeholder";
import CharacterCount from "@tiptap/extension-character-count";
import Subscript from "@tiptap/extension-subscript";
import Superscript from "@tiptap/extension-superscript";
import { cn } from "@core/common/utils";
import { Textarea } from "@core/ui/textarea";
import { useI18n } from "@core/providers/i18n-provider";
import type { VariableDefinition } from "./VariablePicker";
import { EditorToolbar } from "./EditorToolbar";
import { EmailHtmlBlock } from "./extensions/EmailHtmlBlock";

// ─── Types ──────────────────────────────────────────────────
export interface RichTextEditorProps {
  value: string;
  onChange: (html: string) => void;
  placeholder?: string;
  maxLength?: number;
  minHeight?: string | number;
  className?: string;
  /** Available template variables for variable picker */
  variables?: VariableDefinition[];
  /** Enable image upload — provide handler that returns URL */
  onImageUpload?: (file: File) => Promise<string>;
  /** Show/hide HTML source toggle */
  showSourceToggle?: boolean;
  /** Error state */
  error?: boolean;
  /** Read-only mode */
  readOnly?: boolean;
  /**
   * A11Y FORWARDING — the four props below land on the CONTENTEDITABLE itself,
   * not on the bordered wrapper, and they exist because nothing else can put
   * them there. The thing that takes focus and receives typing is the
   * ProseMirror element TipTap creates inside `<EditorContent>`; a caller can
   * wrap this component in as many labelled divs as it likes and the element the
   * screen reader actually lands on stays a nameless generic `<div>`. TipTap's
   * only channel for attributes on that element is `editorProps.attributes`,
   * which is why these are props here rather than spread props on a wrapper.
   *
   * ADDITIVE AND INERT WHEN OMITTED. Every attribute below is emitted only if
   * its prop was supplied, so a caller that passes none — which is every
   * pre-existing caller — gets byte-identical DOM. Same shape as the
   * `i18nKeyPrefix` prop ColorPickerField grew for the same reason: a core
   * primitive gaining an opt-in seam rather than a second copy of the primitive.
   *
   * Id of the contenteditable, so a sibling `<Label htmlFor>` is real DOM wiring
   * and a host's `aria-describedby` can point at this field.
   */
  id?: string;
  /**
   * Accessible NAME for the editing region. Supplying it also turns on
   * `role="textbox"` and `aria-multiline="true"` on the contenteditable, and the
   * coupling is deliberate rather than convenient: `contenteditable` confers no
   * implicit ARIA role in HTML-AAM, so without a role the region is announced as
   * generic content — but a `role="textbox"` with NO name is worse than a
   * generic div, because it promises a form field and then cannot say which one.
   * So the role arrives with the name or not at all.
   */
  ariaLabel?: string;
  /**
   * Space-separated id list for `aria-describedby` on the contenteditable.
   * COMPOSE rather than overwrite when a host has supplied one of its own —
   * `aria-describedby` is a list, and dropping the host's id silences its error
   * text.
   */
  ariaDescribedBy?: string;
  /**
   * Sets `aria-invalid` on the contenteditable. Separate from `error`, which is
   * purely the visual border state: a caller may want the red edge without
   * announcing invalidity (mid-typing over a length cap, say), and the two were
   * conflated exactly once before being split here.
   */
  ariaInvalid?: boolean;
}

// ─── Email HTML Serializer ──────────────────────────────────
/**
 * Custom HTML serializer that walks the editor document and replaces
 * emailHtmlBlock wrapper divs with their stored raw HTML content.
 * This is what makes email-safe HTML (tables, buttons, social links)
 * survive the TipTap roundtrip.
 */
function getEmailSafeHTML(editor: ReturnType<typeof useEditor>): string {
  if (!editor) return "";

  // Get standard TipTap HTML
  const html = editor.getHTML();

  // Replace emailHtmlBlock wrappers with their stored raw HTML
  // The wrapper has the pattern: <div data-email-html-block="true" data-email-html="...">...</div>
  const wrapper = document.createElement("div");
  wrapper.innerHTML = html;

  const blocks = wrapper.querySelectorAll('div[data-email-html-block="true"]');
  blocks.forEach((block) => {
    const rawHtml = block.getAttribute("data-email-html") || "";
    if (rawHtml) {
      const fragment = document.createRange().createContextualFragment(rawHtml);
      block.replaceWith(fragment);
    }
  });

  return wrapper.innerHTML;
}

// ─── Main Component ─────────────────────────────────────────
export function RichTextEditor({
  value,
  onChange,
  placeholder,
  maxLength,
  minHeight = "200px",
  className,
  variables,
  onImageUpload,
  showSourceToggle = true,
  error,
  readOnly = false,
  id,
  ariaLabel,
  ariaDescribedBy,
  ariaInvalid,
}: RichTextEditorProps) {
  const { t } = useI18n();
  const [sourceMode, setSourceMode] = useState(false);
  const [sourceHtml, setSourceHtml] = useState("");

  /**
   * Built by omission, not by emitting empty strings: an `aria-label=""` is a
   * name of zero length, which the accname algorithm treats as "author supplied
   * no name" in some engines and as an empty name in others. Absent is the only
   * unambiguous way to say nothing. See `ariaLabel`'s own doc comment for why
   * `role`/`aria-multiline` are gated on the NAME rather than emitted always.
   */
  const editorAttributes: Record<string, string> = {};
  if (id) editorAttributes.id = id;
  if (ariaLabel) {
    editorAttributes.role = "textbox";
    editorAttributes["aria-multiline"] = "true";
    editorAttributes["aria-label"] = ariaLabel;
  }
  if (ariaDescribedBy) editorAttributes["aria-describedby"] = ariaDescribedBy;
  if (ariaInvalid) editorAttributes["aria-invalid"] = "true";

  // The default used to be a hardcoded "Start typing..." baked into the
  // signature, which the Arabic build rendered in English. TipTap reads the
  // option once at construction, so this resolves before the editor is built.
  const resolvedPlaceholder = placeholder ?? t("editor.placeholder");

  const editor = useEditor({
    extensions: [
      StarterKit.configure({
        heading: { levels: [1, 2, 3] },
        link: false,
        underline: false,
      }),
      Underline,
      TextStyle,
      Color,
      Highlight.configure({ multicolor: true }),
      TextAlign.configure({
        types: ["heading", "paragraph"],
      }),
      ImageExtension.configure({
        HTMLAttributes: {
          class: "max-w-full h-auto rounded-nx-sm",
        },
      }),
      Link.configure({
        openOnClick: false,
        HTMLAttributes: {
          class: "text-nx-accent underline cursor-pointer",
          target: "_blank",
          rel: "noopener noreferrer",
        },
      }),
      Placeholder.configure({ placeholder: resolvedPlaceholder }),
      Subscript,
      Superscript,
      EmailHtmlBlock,
      ...(maxLength ? [CharacterCount.configure({ limit: maxLength })] : [CharacterCount]),
    ],
    content: value,
    editable: !readOnly,
    // The ONLY channel TipTap offers for attributes on the contenteditable it
    // creates -- see the a11y-forwarding props' doc comment above for why a
    // wrapper cannot substitute.
    editorProps: { attributes: editorAttributes },
    onUpdate: ({ editor: e }) => {
      const html = getEmailSafeHTML(e);
      onChange(html);
    },
    immediatelyRender: false,
  });

  // Sync external value changes
  React.useEffect(() => {
    if (editor && value !== getEmailSafeHTML(editor)) {
      editor.commands.setContent(value, { emitUpdate: false });
    }
  }, [value]);

  const toggleSource = useCallback(() => {
    if (!editor) return;
    if (sourceMode) {
      // Apply source HTML to editor
      editor.commands.setContent(sourceHtml, { emitUpdate: false });
      onChange(sourceHtml);
      setSourceMode(false);
    } else {
      // Copy editor HTML to source
      setSourceHtml(getEmailSafeHTML(editor));
      setSourceMode(true);
    }
  }, [editor, sourceMode, sourceHtml, onChange]);

  if (!editor) return null;

  const charCount = editor.storage.characterCount?.characters() ?? 0;

  return (
    <div
      className={cn(
        "overflow-hidden rounded-nx-lg border border-nx-line bg-nx-surface",
        "transition-[border-color,box-shadow] duration-nx-micro ease-nx-enter motion-reduce:transition-none",
        error && "border-nx-danger",
        // The lit edge, not an offset halo: the same --nx-focus ring every
        // other field in the system wears, raised to focus-within because the
        // thing that actually takes focus is the contenteditable inside.
        !error && "focus-within:border-nx-accent focus-within:shadow-nx-focus",
        className
      )}
    >
      {/* Toolbar */}
      {!readOnly && (
        <EditorToolbar
          editor={editor}
          variables={variables}
          onImageUpload={onImageUpload}
          showSourceToggle={showSourceToggle}
          sourceMode={sourceMode}
          onToggleSource={toggleSource}
        />
      )}

      {/* Editor / Source */}
      {sourceMode ? (
        // The shared field primitive rather than a bare textarea. Its own focus
        // ring is suppressed on purpose: the container above already lights the
        // whole editor edge, and two concentric rings read as an error.
        <Textarea
          value={sourceHtml}
          onChange={(e) => setSourceHtml(e.target.value)}
          className="rounded-none border-0 bg-nx-ground p-4 font-mono text-sm focus-visible:shadow-none"
          style={{ minHeight }}
          spellCheck={false}
          aria-label={t("editor.sourceLabel")}
        />
      ) : (
        <EditorContent
          editor={editor}
          className={cn(
            "prose prose-sm dark:prose-invert max-w-none px-4 py-3",
            "[&_.tiptap]:min-h-[var(--editor-min-h)] [&_.tiptap]:outline-none",
            "[&_.tiptap_p.is-editor-empty:first-child::before]:content-[attr(data-placeholder)]",
            "[&_.tiptap_p.is-editor-empty:first-child::before]:text-nx-ink-3",
            // The logical float, not the physical one: in the Arabic build the
            // placeholder floated away from the caret and sat under the first
            // typed word.
            "[&_.tiptap_p.is-editor-empty:first-child::before]:float-start",
            "[&_.tiptap_p.is-editor-empty:first-child::before]:h-0",
            "[&_.tiptap_p.is-editor-empty:first-child::before]:pointer-events-none"
          )}
          style={{ "--editor-min-h": minHeight } as React.CSSProperties}
        />
      )}

      {/* Footer: Character Count */}
      {maxLength && (
        <div className="flex items-center justify-end border-t border-nx-line bg-nx-raised px-3 py-1.5">
          <span
            className={cn(
              "text-xs tabular-nums",
              charCount > maxLength ? "font-medium text-nx-danger" : "text-nx-ink-3"
            )}
          >
            {/* The ratio is a glance-read for the eye; a screen reader gets the
                sentence instead of "one two three four slash five thousand". */}
            <span aria-hidden="true">
              {charCount.toLocaleString()}/{maxLength.toLocaleString()}
            </span>
            <span className="sr-only">
              {t("editor.characterCount", { count: charCount, max: maxLength })}
            </span>
          </span>
        </div>
      )}
    </div>
  );
}

export default RichTextEditor;

/**
 * EmailHtmlBlock — Custom TipTap Node Extension
 *
 * Treats email-safe HTML (tables, buttons, social links) as an opaque,
 * non-editable block inside the editor. This prevents TipTap/ProseMirror
 * from stripping <table>, <style>, inline styles, and other email-specific
 * markup that it cannot natively represent.
 *
 * The raw HTML is stored in the `html` attribute and rendered via a React
 * NodeView. On serialisation (`getHTML()`), the raw HTML is stored as a
 * data attribute and post-processed by `getEmailSafeHTML()` in RichTextEditor.
 */

import { mergeAttributes, Node, ReactNodeViewRenderer } from "@tiptap/react";
import EmailHtmlBlockView from "../EmailHtmlBlockView";

export interface EmailHtmlBlockOptions {
  /** HTML attributes added to the wrapper element in the editor */
  HTMLAttributes: Record<string, string>;
}

declare module "@tiptap/react" {
  interface Commands<ReturnType> {
    emailHtmlBlock: {
      /**
       * Insert an opaque email HTML block at the current cursor position.
       */
      insertEmailHtmlBlock: (attrs: {
        html: string;
        label?: string;
        blockType?: string;
      }) => ReturnType;
    };
  }
}

export const EmailHtmlBlock = Node.create<EmailHtmlBlockOptions>({
  name: "emailHtmlBlock",

  group: "block",

  // Treated as a single atom — not editable inline
  atom: true,

  // Draggable in editor
  draggable: true,

  // Isolating prevents cursor from entering
  isolating: true,

  addOptions() {
    return {
      HTMLAttributes: {},
    };
  },

  addAttributes() {
    return {
      /** The raw email HTML stored verbatim */
      html: {
        default: "",
        parseHTML: (el: HTMLElement) => el.getAttribute("data-email-html") || "",
        renderHTML: (attrs: Record<string, unknown>) => ({
          "data-email-html": attrs.html as string,
        }),
      },
      /** A human-friendly label (e.g. "CTA Button", "Social Links") */
      label: {
        default: "Email Block",
        parseHTML: (el: HTMLElement) => el.getAttribute("data-label") || "Email Block",
        renderHTML: (attrs: Record<string, unknown>) => ({
          "data-label": attrs.label as string,
        }),
      },
      /** Block type for icon differentiation */
      blockType: {
        default: "generic",
        parseHTML: (el: HTMLElement) => el.getAttribute("data-block-type") || "generic",
        renderHTML: (attrs: Record<string, unknown>) => ({
          "data-block-type": attrs.blockType as string,
        }),
      },
    };
  },

  parseHTML() {
    return [
      {
        tag: 'div[data-email-html-block="true"]',
      },
    ];
  },

  renderHTML({ HTMLAttributes }) {
    return [
      "div",
      mergeAttributes(this.options.HTMLAttributes, HTMLAttributes, {
        "data-email-html-block": "true",
      }),
    ];
  },

  renderText({ node }) {
    return (node.attrs.label as string) || "Email Block";
  },

  addNodeView() {
    return ReactNodeViewRenderer(EmailHtmlBlockView);
  },

  addCommands() {
    return {
      insertEmailHtmlBlock:
        (attrs: { html: string; label?: string; blockType?: string }) =>
        ({ commands }: any) => {
          return commands.insertContent({
            type: this.name,
            attrs,
          });
        },
    };
  },
});

export default EmailHtmlBlock;

"use client";

import React, { useState } from "react";
import { cn } from "@core/common/utils";
import { Button } from "@core/ui/button";
import { Input } from "@core/ui/input";
import { EmptyState } from "@core/ui/empty-state";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@core/ui/dropdown-menu";
import { ChevronRight, ChevronDown, Folder, FolderOpen, MoreHorizontal } from "lucide-react";
import { Checkbox } from "@core/ui/checkbox";
import { useI18n } from "@core/providers/i18n-provider";
import { useSettings } from "@core/providers/settings-provider";

/**
 * TreeView — hierarchy, two ways.
 *
 * Wave C collapsed 12 skins to two honest structures. Wave K makes them
 * actually different from each other and honest about depth:
 *
 *  • "lines" was drawing a bordered CARD for every row AND a connector rail
 *    beside it, so the hierarchy was stated twice and neither statement was
 *    legible. A lines row is now a flat, borderless target — the rail alone
 *    carries the structure, which is the entire point of the variant.
 *  • both variants inherited `shadowIntensity`, so at "strong" every node in a
 *    600-row tree wore `shadow-2xl`. Nothing in a tree floats; the shadow is
 *    gone from the node styling and the setting keeps applying everywhere it
 *    describes something that does.
 *  • the leaf glyph was a Folder — a folder that contains nothing — sitting
 *    beside a `Circle` in the toggle column, so a leaf carried two icons and
 *    neither meant anything. Branches keep the folder; leaves get the toggle
 *    column's rail dot and nothing else.
 *  • the child count wore a `GitBranch` icon. This is a taxonomy tree, not a
 *    repository; it is a tabular-nums count chip now.
 *  • the loading state pulsed. Static fill steps instead.
 *  • surfaces/ink/hairlines moved off the pre-nexus muted/card/primary tokens
 *    and off `bg-card/60 backdrop-blur` (an unrequested glass surface leaking
 *    in from the cardStyle setting).
 */
export type TreeVariant = "lines" | "cards";

const LEGACY_TREE_VARIANT: Partial<Record<string, TreeVariant>> = {
  minimal: "lines",
  bubble: "cards",
  modern: "cards",
  glass: "cards",
  elegant: "cards",
  professional: "cards",
  gradient: "cards",
  neon: "cards",
  organic: "cards",
  corporate: "cards",
};

// Stored settings can hold values the map no longer knows; unknowns fall back
// to "lines" so first paint is always a styled tree.
export const resolveTreeVariant = (value: string | null | undefined): TreeVariant => {
  if (value === "lines" || value === "cards") return value;
  return (value && LEGACY_TREE_VARIANT[value]) || "lines";
};

export interface TreeAction {
  label: string;
  onClick: () => void;
  variant?: "default" | "destructive" | "ghost";
  icon?: React.ReactNode;
  disabled?: boolean;
}

export interface TreeViewProps<T> {
  data: T[];
  getId: (node: T) => string;
  getLabel: (node: T) => React.ReactNode;
  getChildren: (node: T) => T[] | undefined;
  search?: {
    value: string;
    onChange: (v: string) => void;
    placeholder?: string;
    inputRef?: React.RefObject<HTMLInputElement | null>;
  };
  actions?: (node: T) => TreeAction[];
  loading?: boolean;
  toolbar?: React.ReactNode;
  emptyMessage?: string;
  defaultExpanded?: boolean;
  onExpandChange?: (expandedIds: string[]) => void;
  className?: string;
  variant?: TreeVariant; // override; otherwise uses settings.treeStyle
  headerComponent?: React.ReactNode;
  footerComponent?: React.ReactNode;
  aboveTreeComponent?: React.ReactNode;
  belowTreeComponent?: React.ReactNode;
  // Selectable functionality
  selectable?: boolean;
  selectedValues?: string[];
  onSelectionChange?: (selectedValues: string[]) => void;
  getValueToSend?: (node: T) => string;
  disabled?: boolean;
  // Card click expansion
  expandOnCardClick?: boolean; // New prop to enable/disable card click expansion
}

// Helper component to defer evaluating actions(node)
function NodeActions<T>({
  node,
  actions,
  direction,
}: {
  node: T;
  actions: (node: T) => TreeAction[];
  direction: string;
}) {
  const [open, setOpen] = useState(false);

  return (
    <DropdownMenu open={open} onOpenChange={setOpen}>
      <DropdownMenuTrigger asChild>
        {/* 32px minimum: the trigger was 28px, below the hit-target floor. */}
        <Button variant="ghost" size="icon" className="h-8 w-8 shrink-0 text-nx-ink-3">
          <MoreHorizontal aria-hidden="true" className="h-4 w-4" />
        </Button>
      </DropdownMenuTrigger>
      {open && (
        <DropdownMenuContent align={direction === "rtl" ? "start" : "end"}>
          {actions(node).map((a, idx) => (
            <DropdownMenuItem
              key={idx}
              onClick={a.onClick}
              disabled={a.disabled}
              className={cn(
                a.variant === "destructive" && "text-destructive focus:text-destructive"
              )}
            >
              {a.icon && <span className="me-2 shrink-0">{a.icon}</span>}
              {a.label}
            </DropdownMenuItem>
          ))}
        </DropdownMenuContent>
      )}
    </DropdownMenu>
  );
}

export function TreeView<T>({
  data,
  getId,
  getLabel,
  getChildren,
  search,
  actions,
  loading,
  toolbar,
  emptyMessage,
  defaultExpanded = false,
  onExpandChange,
  className,
  variant,
  headerComponent,
  footerComponent,
  aboveTreeComponent,
  belowTreeComponent,
  selectable = false,
  selectedValues = [],
  onSelectionChange,
  getValueToSend,
  disabled = false,
  expandOnCardClick = false, // Default to false for backward compatibility
}: TreeViewProps<T>) {
  const { direction, t } = useI18n();
  const settings = useSettings();

  const computedVariant: TreeVariant = resolveTreeVariant(variant ?? settings.treeStyle);

  const [expanded, setExpanded] = useState<Record<string, boolean>>({});
  const [isAllExpanded, setIsAllExpanded] = useState<boolean>(defaultExpanded);

  // Initialize expand state whenever data changes
  const [prevData, setPrevData] = useState(data);
  const [prevDefaultExpanded, setPrevDefaultExpanded] = useState(defaultExpanded);

  if (data !== prevData || defaultExpanded !== prevDefaultExpanded) {
    setPrevData(data);
    setPrevDefaultExpanded(defaultExpanded);
    const next: Record<string, boolean> = {};
    const walk = (nodes: T[]) => {
      nodes.forEach((n) => {
        const id = getId(n);
        const children = getChildren(n) ?? [];

        // Only set defaultExpanded if the node hasn't been manually toggled before
        if (!(id in expanded)) {
          next[id] = defaultExpanded;
        } else {
          next[id] = expanded[id];
        }

        if (children.length > 0) walk(children);
      });
    };
    walk(data);
    setExpanded(next);

    // Update isAllExpanded based on current state
    const allExpanded = Object.values(next).every(Boolean);
    setIsAllExpanded(allExpanded);
  }

  const handleToggleNode = (id: string) => {
    setExpanded((prev) => {
      const next = { ...prev, [id]: !prev[id] };
      onExpandChange?.(Object.keys(next).filter((k) => next[k]));
      return next;
    });
  };

  const getAllIds = (nodes: T[]): string[] => {
    const ids: string[] = [];
    nodes.forEach((node) => {
      ids.push(getId(node));
      const children = getChildren(node) ?? [];
      if (children.length > 0) {
        ids.push(...getAllIds(children));
      }
    });
    return ids;
  };

  const expandAll = () => {
    const all: Record<string, boolean> = {};
    const allIds = getAllIds(data);
    allIds.forEach((id) => (all[id] = true));
    onExpandChange?.(allIds);
    setExpanded(all);
    setIsAllExpanded(true);
  };

  const collapseAll = () => {
    const all: Record<string, boolean> = {};
    getAllIds(data).forEach((id) => (all[id] = false));
    onExpandChange?.([]);
    setExpanded(all);
    setIsAllExpanded(false);
  };

  // ── Selection logic ─────────────────────────────────────
  // Lives at the TreeView level so every walk starts from the ROOT data.
  // The old per-level copy searched only the current subtree, so selecting a
  // node deeper than level 1 never found (or auto-selected) its ancestors.

  const findNodeByValue = (nodes: T[], targetValue: string): T | null => {
    if (!getValueToSend) return null;
    for (const node of nodes) {
      if (getValueToSend(node) === targetValue) return node;
      const found = findNodeByValue(getChildren(node) ?? [], targetValue);
      if (found) return found;
    }
    return null;
  };

  const getAllChildrenValues = (node: T): string[] => {
    const children = getChildren(node) ?? [];
    const values: string[] = [];

    children.forEach((child) => {
      if (getValueToSend) {
        values.push(getValueToSend(child));
        values.push(...getAllChildrenValues(child));
      }
    });

    return values;
  };

  const getAllParentValues = (targetValue: string): string[] => {
    const parents: string[] = [];

    const findParents = (nodes: T[], currentParents: string[]): boolean => {
      for (const node of nodes) {
        if (!getValueToSend) return false;
        const nodeVal = getValueToSend(node);
        const children = getChildren(node) ?? [];

        if (children.some((child) => getValueToSend(child) === targetValue)) {
          parents.push(...currentParents, nodeVal);
          return true;
        }

        if (findParents(children, [...currentParents, nodeVal])) {
          return true;
        }
      }
      return false;
    };

    findParents(data, []);
    return parents;
  };

  const isNodeIndeterminate = (node: T): boolean => {
    const children = getChildren(node) ?? [];
    if (children.length === 0 || !getValueToSend) return false;

    const nodeValue = getValueToSend(node);
    if (selectedValues.includes(nodeValue)) return false;

    const childrenValues = getAllChildrenValues(node);
    return childrenValues.some((childValue) => selectedValues.includes(childValue));
  };

  const handleSelectionChange = (nodeValue: string, checked: boolean) => {
    if (!onSelectionChange || !getValueToSend) return;

    const node = findNodeByValue(data, nodeValue);
    if (!node) return;

    let newSelection = [...selectedValues];

    if (checked) {
      // Add the node
      if (!newSelection.includes(nodeValue)) {
        newSelection.push(nodeValue);
      }

      // Auto-select all parents (walked from the root, so any depth works)
      getAllParentValues(nodeValue).forEach((parentValue) => {
        if (!newSelection.includes(parentValue)) {
          newSelection.push(parentValue);
        }
      });
    } else {
      // Remove the node
      newSelection = newSelection.filter((val) => val !== nodeValue);

      // Remove all children
      const childrenValues = getAllChildrenValues(node);
      newSelection = newSelection.filter((val) => !childrenValues.includes(val));
    }

    onSelectionChange(newSelection);
  };

  const spacingSize = settings.spacingSize;
  const density =
    spacingSize === "compact"
      ? { pad: "px-2 py-1.5", childPad: "ps-4" }
      : spacingSize === "spacious"
        ? { pad: "px-4 py-3", childPad: "ps-8" }
        : spacingSize === "comfortable"
          ? { pad: "px-3 py-2.5", childPad: "ps-6" }
          : { pad: "px-3 py-2", childPad: "ps-6" };

  // The borderRadius setting, mapped onto the nx ladder — the same mapping
  // Button uses, so a tree row and a button never disagree about a corner.
  const borderRadiusSetting = settings.borderRadius;
  const radius =
    borderRadiusSetting === "none"
      ? "rounded-none"
      : borderRadiusSetting === "small"
        ? "rounded-nx-sm"
        : borderRadiusSetting === "large"
          ? "rounded-nx-lg"
          : borderRadiusSetting === "full"
            ? "rounded-full"
            : "rounded-nx-control";

  const searchInputRef = search?.inputRef;
  const searchValue = search?.value;
  const searchOnChange = search?.onChange;
  const searchPlaceholder = search?.placeholder;

  const Toolbar = (
    <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
      <div className="relative w-full sm:max-w-sm">
        {search && searchOnChange && (
          <Input
            ref={searchInputRef as any}
            value={searchValue}
            onChange={(e) => searchOnChange(e.target.value)}
            placeholder={searchPlaceholder ?? t("common.search")}
            className="w-full"
            autoComplete="off"
          />
        )}
      </div>
      <div className="flex items-center gap-2">
        <Button variant="outline" size="sm" onClick={isAllExpanded ? collapseAll : expandAll}>
          {isAllExpanded ? t("common.collapseAll") : t("common.expandAll")}
        </Button>
        {toolbar}
      </div>
    </div>
  );

  if (loading) {
    return (
      <div className={cn("space-y-4", className)}>
        {headerComponent}
        {/* Static fill steps in the shape of the toolbar and six rows — a
            placeholder is the absence of a tree, and absence does not pulse. */}
        <div className="space-y-2" role="status" aria-busy="true" aria-label={t("common.loading")}>
          <div aria-hidden="true" className="h-9 w-56 rounded-nx-control bg-nx-raised-2" />
          {[...Array(6)].map((_, i) => (
            <div
              key={i}
              aria-hidden="true"
              // Each step indents a little further than the last, so the
              // placeholder reads as a hierarchy rather than a stack of bars.
              className="h-10 rounded-nx-control bg-nx-raised-2"
              style={{ marginInlineStart: `${(i % 3) * 16}px` }}
            />
          ))}
        </div>
        {footerComponent}
      </div>
    );
  }

  if (!data || data.length === 0) {
    return (
      <div className={cn("space-y-4", className)}>
        {headerComponent}
        {Toolbar}
        {aboveTreeComponent}
        {/* The shared empty anatomy, so an empty tree reads exactly like an
            empty table or an empty section — not like a stray grey sentence. */}
        <EmptyState icon={FolderOpen} title={emptyMessage ?? t("common.noData")} />
        {belowTreeComponent}
        {footerComponent}
      </div>
    );
  }

  return (
    <div className={cn("space-y-4", className)}>
      {headerComponent}
      {Toolbar}
      {aboveTreeComponent}
      <div className={cn("relative", computedVariant === "cards" ? "space-y-2" : "")}>
        <TreeList<T>
          nodes={data}
          variant={computedVariant}
          getId={getId}
          getLabel={getLabel}
          getChildren={getChildren}
          expanded={expanded}
          onToggle={handleToggleNode}
          direction={direction}
          actions={actions}
          density={density}
          radius={radius}
          selectable={selectable}
          selectedValues={selectedValues}
          onSelect={handleSelectionChange}
          isNodeIndeterminate={isNodeIndeterminate}
          getValueToSend={getValueToSend}
          disabled={disabled}
          expandOnCardClick={expandOnCardClick}
        />
      </div>
      {belowTreeComponent}
      {footerComponent}
    </div>
  );
}

// Node styling for the two surviving tree structures.
const NODE_MOTION =
  "transition-[background-color,border-color] duration-nx-micro ease-nx-enter motion-reduce:transition-none";

function getNodeStyling(
  variant: TreeVariant,
  level: number,
  density: { pad: string; childPad: string },
  radius: string,
  selected: boolean
) {
  if (variant === "cards") {
    // Stacked panels: a hairline slab per node, brightening on hover. No
    // shadow — a node is anchored in its parent, it does not float above it.
    return cn(
      "border bg-nx-surface",
      NODE_MOTION,
      density.pad,
      radius,
      selected
        ? "border-nx-accent bg-nx-accent-wash"
        : "border-nx-line hover:border-nx-line-hi hover:bg-nx-hover"
    );
  }

  // lines — the connector rail states the hierarchy, so the row states nothing:
  // no border, no surface of its own, just a hover target.
  return cn(
    "border border-transparent bg-transparent",
    NODE_MOTION,
    density.pad,
    radius,
    level === 0 ? "font-semibold" : "font-normal",
    selected ? "border-nx-accent bg-nx-accent-wash" : "hover:bg-nx-hover"
  );
}

function TreeList<T>({
  nodes,
  variant,
  getId,
  getLabel,
  getChildren,
  expanded,
  onToggle,
  direction,
  actions,
  level = 0,
  density,
  radius,
  selectable = false,
  selectedValues = [],
  onSelect,
  isNodeIndeterminate,
  getValueToSend,
  disabled = false,
  expandOnCardClick = false,
}: {
  nodes: T[];
  variant: TreeVariant;
  getId: (node: T) => string;
  getLabel: (node: T) => React.ReactNode;
  getChildren: (node: T) => T[] | undefined;
  expanded: Record<string, boolean>;
  onToggle: (id: string) => void;
  direction: "ltr" | "rtl";
  actions?: (node: T) => TreeAction[];
  level?: number;
  density: { pad: string; childPad: string };
  radius: string;
  selectable?: boolean;
  selectedValues?: string[];
  onSelect?: (nodeValue: string, checked: boolean) => void;
  isNodeIndeterminate?: (node: T) => boolean;
  getValueToSend?: (node: T) => string;
  disabled?: boolean;
  expandOnCardClick?: boolean;
}) {
  // Cheap ARIA-tree keyboard support: Up/Down move between the visible rows
  // (collapsed children are unmounted, so the DOM order IS the visible order),
  // the inline-end arrow expands, the inline-start arrow collapses, and
  // Enter/Space toggles selection (or expansion when not selectable).
  const handleRowKeyDown = (
    e: React.KeyboardEvent<HTMLDivElement>,
    node: T,
    id: string,
    hasChildren: boolean,
    isOpen: boolean
  ) => {
    if (disabled) return;
    const expandKey = direction === "rtl" ? "ArrowLeft" : "ArrowRight";
    const collapseKey = direction === "rtl" ? "ArrowRight" : "ArrowLeft";
    const row = e.currentTarget;

    const moveFocus = (offset: number) => {
      const tree = row.closest('[role="tree"]');
      if (!tree) return;
      const rows = Array.from(tree.querySelectorAll<HTMLElement>('[role="treeitem"]'));
      rows[rows.indexOf(row) + offset]?.focus();
    };

    if (e.key === "ArrowDown") {
      e.preventDefault();
      moveFocus(1);
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      moveFocus(-1);
    } else if (e.key === expandKey) {
      e.preventDefault();
      if (hasChildren && !isOpen) onToggle(id);
      else if (hasChildren && isOpen) moveFocus(1);
    } else if (e.key === collapseKey) {
      e.preventDefault();
      if (hasChildren && isOpen) onToggle(id);
    } else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      if (selectable && getValueToSend && onSelect) {
        const nodeValue = getValueToSend(node);
        onSelect(nodeValue, !selectedValues.includes(nodeValue));
      } else if (hasChildren) {
        onToggle(id);
      }
    }
  };

  return (
    <ul
      role={level === 0 ? "tree" : "group"}
      className={cn("m-0 list-none p-0", variant === "lines" && level > 0 ? "relative" : "")}
    >
      {nodes.map((node, index) => {
        const id = getId(node);
        const label = getLabel(node);
        const nodeValue = getValueToSend ? getValueToSend(node) : "";
        const children = getChildren(node) ?? [];
        const hasChildren = children.length > 0;
        const isOpen = expanded[id];
        const selected = selectable && getValueToSend ? selectedValues.includes(nodeValue) : false;
        const indeterminate =
          selectable && getValueToSend ? (isNodeIndeterminate?.(node) ?? false) : false;

        const nodeBase = getNodeStyling(variant, level, density, radius, selected);

        return (
          <li key={id} role="none" className={cn("group relative", variant === "cards" && "mb-2")}>
            {/* Node row — the focusable treeitem */}
            <div
              role="treeitem"
              aria-level={level + 1}
              aria-expanded={hasChildren ? isOpen : undefined}
              aria-selected={selectable ? selected : undefined}
              // Static roving tabindex: Tab lands on the first root row; the
              // arrow keys move focus from there.
              tabIndex={level === 0 && index === 0 ? 0 : -1}
              onKeyDown={(e) => handleRowKeyDown(e, node, id, hasChildren, isOpen)}
              className={cn(
                "flex items-center gap-2",
                nodeBase,
                "focus-visible:shadow-nx-focus focus-visible:outline-none",
                disabled && "cursor-not-allowed",
                expandOnCardClick && hasChildren && !disabled ? "cursor-pointer" : ""
              )}
              onClick={() => {
                // Handle card click expansion if enabled and node has children
                if (expandOnCardClick && hasChildren && !disabled) {
                  onToggle(id);
                }
              }}
            >
              {/* Toggle column — 32px whether or not the node has children, so
                  every label on a level shares one optical column. A leaf gets
                  the rail dot in place of the chevron; it used to get a
                  disabled BUTTON, which is a control that promises nothing. */}
              {hasChildren ? (
                <button
                  type="button"
                  // Out of the tab order: the treeitem row carries the keyboard
                  // interaction and the aria-expanded state.
                  tabIndex={-1}
                  className={cn(
                    "grid h-8 w-8 shrink-0 place-items-center rounded-nx-sm text-nx-ink-2",
                    NODE_MOTION,
                    disabled
                      ? "cursor-not-allowed text-nx-ink-3"
                      : "hover:bg-nx-hover hover:text-nx-ink"
                  )}
                  onClick={(e) => {
                    e.stopPropagation();
                    if (!disabled) {
                      onToggle(id);
                    }
                  }}
                  disabled={disabled}
                  aria-label={isOpen ? "Collapse" : "Expand"}
                >
                  {isOpen ? (
                    <ChevronDown className="h-4 w-4" />
                  ) : (
                    <ChevronRight className="h-4 w-4 rtl:rotate-180" />
                  )}
                </button>
              ) : (
                <span aria-hidden="true" className="grid h-8 w-8 shrink-0 place-items-center">
                  <span className="h-1 w-1 rounded-full bg-nx-ink-3" />
                </span>
              )}

              {/* Checkbox for selectable mode */}
              {selectable && getValueToSend && (
                <div
                  className={cn(
                    "grid h-8 w-8 shrink-0 place-items-center rounded-nx-sm",
                    NODE_MOTION,
                    disabled ? "cursor-not-allowed" : "cursor-pointer hover:bg-nx-hover"
                  )}
                  onClick={(e) => {
                    e.stopPropagation();
                    if (!disabled) {
                      onSelect?.(nodeValue, !selected);
                    }
                  }}
                >
                  <Checkbox
                    checked={selected}
                    disabled={disabled}
                    ref={(ref) => {
                      if (ref && indeterminate) {
                        (ref as any).indeterminate = true;
                      }
                    }}
                    onCheckedChange={(checked) =>
                      !disabled && onSelect?.(nodeValue, checked === true)
                    }
                    className="pointer-events-none"
                    tabIndex={-1}
                  />
                </div>
              )}

              {/* Icon + Label */}
              <div
                className={cn(
                  "flex min-w-0 flex-1 items-center gap-2",
                  selectable && !disabled ? "cursor-pointer" : ""
                )}
                onClick={(e) => {
                  if (selectable && getValueToSend && !disabled) {
                    e.stopPropagation();
                    onSelect?.(nodeValue, !selected);
                  }
                }}
              >
                {/* Only branches carry a folder. A leaf is not an empty
                    container, so it does not get drawn as one. */}
                {hasChildren &&
                  (isOpen ? (
                    <FolderOpen
                      aria-hidden="true"
                      className={cn(
                        "h-4 w-4 shrink-0",
                        selected ? "text-nx-accent" : "text-nx-ink-2"
                      )}
                    />
                  ) : (
                    <Folder
                      aria-hidden="true"
                      className={cn(
                        "h-4 w-4 shrink-0",
                        selected ? "text-nx-accent" : "text-nx-ink-2"
                      )}
                    />
                  ))}
                {/* One type size across levels: depth is stated by the rail and
                    the indent, weight by getNodeStyling. A per-level font size
                    made a deep tree shrink into illegibility. */}
                <span
                  className={cn(
                    "truncate text-sm",
                    selected ? "font-medium text-nx-accent" : "text-nx-ink",
                    disabled && "text-nx-ink-3"
                  )}
                >
                  {label}
                </span>
                {level === 0 && hasChildren && (
                  <span className="ms-1 shrink-0 rounded-nx-sm border border-nx-line px-1.5 py-0.5 text-[11px] font-medium tabular-nums leading-none text-nx-ink-3">
                    {children.length}
                  </span>
                )}
              </div>

              {/* Actions */}
              {actions && <NodeActions node={node} actions={actions} direction={direction} />}
            </div>

            {/* Children — ONE recursive call site for both variants. The old
                per-variant copies drifted (the gradient copy dropped the
                disabled/expandOnCardClick props); a single call site cannot. */}
            {hasChildren && isOpen && (
              <div
                className={
                  variant === "lines"
                    ? "ms-4 mt-0.5 border-s border-nx-line"
                    : "mt-2 space-y-2 ps-8"
                }
              >
                <div className={variant === "lines" ? density.childPad : undefined}>
                  <TreeList<T>
                    nodes={children}
                    variant={variant}
                    getId={getId}
                    getLabel={getLabel}
                    getChildren={getChildren}
                    expanded={expanded}
                    onToggle={onToggle}
                    direction={direction}
                    actions={actions}
                    level={level + 1}
                    density={density}
                    radius={radius}
                    selectable={selectable}
                    selectedValues={selectedValues}
                    onSelect={onSelect}
                    isNodeIndeterminate={isNodeIndeterminate}
                    getValueToSend={getValueToSend}
                    disabled={disabled}
                    expandOnCardClick={expandOnCardClick}
                  />
                </div>
              </div>
            )}
          </li>
        );
      })}
    </ul>
  );
}

"use client";

/**
 * UserProfileDropdown — the identity cluster's anchor.
 *
 * Wave I2 elevation. What changed, and why:
 *
 *  • COLOUR: every literal is gone. The panel used to branch on
 *    `resolvedTheme === "dark"` for its surface, border, shadow and every
 *    separator (`#0d1117`, `bg-white/[0.03]`, `border-white/20`…), which meant
 *    the menu had its own private theme instead of the shell's. It now reads
 *    --nx-* tokens only, so light/dark resolve in CSS and there is no isDark
 *    ternary left in this file.
 *  • ACCENT: the avatar gradient concatenated a workspace accent string with a
 *    hardcoded indigo second stop per theme. --nx-accent/--nx-accent-fill are
 *    derived from --workspace-hue/--workspace-chroma in CSS, so the SAME
 *    workspace-accent data path now paints it, correctly, in both themes.
 *  • IDENTITY: the header shows avatar + name + email (the account's actual
 *    address), with the admin type as a quiet chip instead of a second grey
 *    line indistinguishable from the name.
 *  • HIERARCHY: navigation items are one semantic group; sign-out is separated
 *    and destructive-tinted so it can never be mistaken for a nav row.
 *  • FOCUS: the highlighted row wears the lit inline-start edge (the same
 *    2px accent bar the checkbox/radio items use) — light collects on the
 *    focused thing. Trigger focus rides the shared Button --nx-focus ring.
 *  • MOTION: 140ms (--nx-t-micro) on the chevron and row crossfades, with a
 *    reduced-motion path; the panel's own enter/exit belongs to the primitive.
 *
 * Every prop, handler and data path is unchanged: variants, showName, side,
 * align, className, the showUserAvatar gate, profile/settings navigation and
 * the logout call all behave exactly as before.
 */

import { useState } from "react";
import { useRouter } from "next/navigation";
import { Avatar, AvatarFallback, AvatarImage } from "@core/ui/avatar";
import { Button } from "@core/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuShortcut,
  DropdownMenuTrigger,
} from "@core/ui/dropdown-menu";
import { ChevronDown, Settings, User, LogOut } from "lucide-react";
import type { LucideIcon } from "lucide-react";
import { useAppStore } from "@core/store/useAppStore";
import { useAuthLogout } from "@modules/auth/core/src/presentation/viewmodels/useAuthLogout";
import { useI18n } from "@core/providers/i18n-provider";
import { cn } from "@core/common/utils";
import { useResolvedFileUrl } from "@core/hooks/use-resolved-file-url";
import { useSettings } from "@core/providers/settings-provider";
import { appLogger } from "@core/common/logger";

interface UserProfileDropdownProps {
  variant?: "default" | "compact" | "minimal" | "elegant" | "floating" | "navigation";
  showName?: boolean;
  className?: string;
  side?: "top" | "right" | "bottom" | "left";
  align?: "start" | "center" | "end";
}

/**
 * One menu row. `shortcut` is rendered only when a REAL binding exists —
 * nothing in this menu is bound today (the only global chord in the shell is
 * ⌘K for the search palette, which is not a row here), so no hint is invented.
 * Wire a binding and set the field; the hint renders itself.
 */
interface ProfileMenuRow {
  key: string;
  icon: LucideIcon;
  label: string;
  onClick: () => void;
  shortcut?: string;
}

// The avatar mark: accent (L0.68 dark / L0.46 light) into accent-fill (L0.50).
// Both track --workspace-hue, so the mark carries the active workspace's
// identity and stays legible against --nx-on-fill in either theme.
const AVATAR_MARK = "linear-gradient(135deg, var(--nx-accent) 0%, var(--nx-accent-fill) 100%)";

// Shared row shape. The lit inline-start edge appears only on the highlighted
// row (Radix sets data-highlighted for both pointer and keyboard focus).
const ROW_BASE = cn(
  "group relative flex cursor-pointer select-none items-center gap-2.5 px-2.5 py-2 text-sm font-medium",
  "transition-colors duration-nx-micro ease-nx-enter motion-reduce:transition-none",
  "before:absolute before:inset-y-1.5 before:start-0 before:w-0.5 before:rounded-full before:bg-transparent before:transition-colors before:duration-nx-micro motion-reduce:before:transition-none"
);

export function UserProfileDropdown({
  variant = "default",
  showName = true,
  className,
  side,
  align = "end",
}: UserProfileDropdownProps) {
  const user = useAppStore((state) => state.user);
  const { logout } = useAuthLogout();
  const { t } = useI18n();
  const router = useRouter();
  const [isOpen, setIsOpen] = useState(false);
  const settings = useSettings();
  // Hooks must run unconditionally — called before the early return below.
  const resolvedAvatarUrl = useResolvedFileUrl(user?.profileImageUrl);

  if (!user || !settings.showUserAvatar) return null;

  const avatarUrl = resolvedAvatarUrl || undefined;

  const getInitials = () => {
    const firstName = user.firstName || "";
    const lastName = user.lastName || "";
    const firstInitial = firstName.charAt(0)?.toUpperCase() || "";
    const lastInitial = lastName.charAt(0)?.toUpperCase() || "";
    return `${firstInitial}${lastInitial}` || "U";
  };

  const getDisplayName = () => {
    const firstName = user.firstName || "";
    const lastName = user.lastName || "";
    return `${firstName} ${lastName}`.trim() || user.username || "User";
  };

  const displayName = getDisplayName();
  const roleLabel = user.adminTypeName || (user as any).role || t("common.user");
  // The account's address is the header's second line; username is the fallback
  // when the account carries no email. Never repeat the display name.
  const emailLine = (user.email || user.username || "").trim();
  const showEmailLine = emailLine.length > 0 && emailLine !== displayName;

  const handleProfileClick = () => {
    router.push("/profile");
    setIsOpen(false);
  };

  const handleSettingsClick = () => {
    router.push("/settings");
    setIsOpen(false);
  };

  const handleSignOut = async () => {
    try {
      await logout();
      setIsOpen(false);
    } catch (error) {
      appLogger.error("Logout failed:", error);
    }
  };

  const navRows: ProfileMenuRow[] = [
    { key: "profile", icon: User, label: t("nav.profile"), onClick: handleProfileClick },
    { key: "settings", icon: Settings, label: t("nav.settings"), onClick: handleSettingsClick },
  ];

  const getAvatarSize = () => {
    switch (variant) {
      case "compact":
        return "h-8 w-8";
      case "minimal":
        return "h-7 w-7";
      case "floating":
        return "h-9 w-9";
      case "navigation":
        return "h-8 w-8";
      default:
        return "h-9 w-9";
    }
  };

  const getTextSize = () => {
    switch (variant) {
      case "compact":
        return "text-xs";
      case "minimal":
        return "text-xs";
      case "floating":
        return "text-sm";
      case "navigation":
        return "text-sm";
      default:
        return "text-sm";
    }
  };

  return (
    <DropdownMenu open={isOpen} onOpenChange={setIsOpen}>
      <DropdownMenuTrigger asChild>
        <Button
          variant="ghost"
          // Icon-only variants (rail, mobile) render no visible label, so the
          // trigger carries one. When the name IS visible the label would only
          // duplicate — and risk contradicting — the rendered text.
          aria-label={showName ? undefined : displayName}
          className={cn(
            "flex h-10 items-center gap-2 p-2 text-nx-ink hover:bg-nx-hover",
            variant === "navigation" && "h-9",
            variant === "floating" && "rounded-full",
            className
          )}
        >
          <Avatar className={cn(getAvatarSize(), "shadow-nx-sm")}>
            {avatarUrl && <AvatarImage src={avatarUrl} alt={displayName} />}
            <AvatarFallback
              delayMs={600}
              style={{ background: AVATAR_MARK }}
              className="text-sm font-semibold text-nx-on-fill"
            >
              {getInitials()}
            </AvatarFallback>
          </Avatar>

          {showName && (
            <div className="flex min-w-0 items-center gap-2">
              <div className="min-w-0 text-start">
                <p className={cn("max-w-[120px] truncate font-medium text-nx-ink", getTextSize())}>
                  {displayName}
                </p>
                <p className="max-w-[120px] truncate text-xs text-nx-ink-2">{roleLabel}</p>
              </div>
              <ChevronDown
                aria-hidden="true"
                className={cn(
                  "flex-shrink-0 text-nx-ink-3 transition-transform duration-nx-micro ease-nx-enter motion-reduce:transition-none",
                  isOpen && "rotate-180",
                  variant === "compact" ? "h-3 w-3" : "h-4 w-4"
                )}
              />
            </div>
          )}
        </Button>
      </DropdownMenuTrigger>

      <DropdownMenuContent
        align={align}
        className="w-64 p-1.5"
        side={side || "bottom"}
        sideOffset={8}
      >
        {/* ── Identity header ──────────────────────────────────────────────
            A sunken slab: --nx-ground sits below --nx-popover in BOTH themes
            (dark #0C0B12 under #1B1926, light #F7F6FB under #FFFFFF), so the
            header reads as its own plane without a per-theme branch. */}
        <div className="mb-1 flex items-center gap-3 rounded-nx-control border border-nx-line bg-nx-ground p-2.5">
          <Avatar className="h-10 w-10 shrink-0 shadow-nx-sm">
            {avatarUrl && <AvatarImage src={avatarUrl} alt={displayName} />}
            <AvatarFallback
              delayMs={600}
              style={{ background: AVATAR_MARK }}
              className="text-sm font-semibold text-nx-on-fill"
            >
              {getInitials()}
            </AvatarFallback>
          </Avatar>
          <div className="min-w-0 flex-1 text-start">
            <p className="truncate text-sm font-semibold leading-tight text-nx-ink">
              {displayName}
            </p>
            {showEmailLine && (
              <p className="mt-0.5 truncate text-xs leading-tight text-nx-ink-2" title={emailLine}>
                {emailLine}
              </p>
            )}
            <span className="mt-1.5 inline-flex max-w-full truncate rounded-nx-sm border border-nx-line bg-nx-surface px-1.5 py-0.5 text-[10px] font-medium leading-4 text-nx-ink-2">
              {roleLabel}
            </span>
          </div>
        </div>

        <DropdownMenuSeparator />

        {/* ── Navigation group ─────────────────────────────────────────── */}
        <DropdownMenuGroup>
          {navRows.map(({ key, icon: Icon, label, onClick, shortcut }) => (
            <DropdownMenuItem
              key={key}
              onClick={onClick}
              className={cn(
                ROW_BASE,
                "text-nx-ink focus:bg-nx-hover focus:text-nx-ink data-[highlighted]:before:bg-nx-accent"
              )}
            >
              <Icon
                aria-hidden="true"
                className="h-4 w-4 shrink-0 text-nx-ink-3 transition-colors duration-nx-micro group-data-[highlighted]:text-nx-accent motion-reduce:transition-none"
              />
              <span className="truncate">{label}</span>
              {shortcut && <DropdownMenuShortcut>{shortcut}</DropdownMenuShortcut>}
            </DropdownMenuItem>
          ))}
        </DropdownMenuGroup>

        <DropdownMenuSeparator />

        {/* ── Destructive: sign out ────────────────────────────────────── */}
        <DropdownMenuItem
          onClick={handleSignOut}
          className={cn(
            ROW_BASE,
            "text-destructive focus:bg-destructive/10 focus:text-destructive data-[highlighted]:before:bg-destructive"
          )}
        >
          <LogOut aria-hidden="true" className="h-4 w-4 shrink-0" />
          <span className="truncate">{t("nav.logout")}</span>
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/**
 * Communication Module DI Container
 *
 * Provides dependency injection for communication submodules:
 * Message Composer, Send (Notification Sender), Templates
 *
 * Backend API: Identity
 */
import { getModuleApiService } from "@core/services/api-factory";

// Services
import { EmailService } from "./message-composer/src/data/services/EmailService";
import { NotificationSenderService } from "./send/src/data/services/NotificationSenderService";
import { MessageTemplateService } from "./templates/src/data/services/MessageTemplateService";

// Repositories
import { EmailRepository } from "./message-composer/src/data/repositories/EmailRepository";
import { NotificationSenderRepository } from "./send/src/data/repositories/NotificationSenderRepository";
import { MessageTemplateRepository } from "./templates/src/data/repositories/MessageTemplateRepository";

// Interfaces
import type { IEmailRepository } from "./message-composer/src/domain/interfaces/IEmailRepository";
import type { INotificationSenderRepository } from "./send/src/domain/interfaces/INotificationSenderRepository";
import type { IMessageTemplateRepository } from "./templates/src/domain/interfaces/IMessageTemplateRepository";

export interface CommunicationContainer {
  emailRepository: IEmailRepository;
  notificationSenderRepository: INotificationSenderRepository;
  messageTemplateRepository: IMessageTemplateRepository;
}

let _container: CommunicationContainer | null = null;

/**
 * Get the communication container (lazy initialization)
 */
export function getCommunicationContainer(): CommunicationContainer {
  if (typeof window === "undefined") {
    const dummyProxy = new Proxy({} as any, {
      get() {
        return () => Promise.resolve({});
      },
    });
    return {
      emailRepository: dummyProxy,
      notificationSenderRepository: dummyProxy,
      messageTemplateRepository: dummyProxy,
    };
  }

  if (!_container) {
    const apiService = getModuleApiService("COMMUNICATION");

    _container = {
      emailRepository: new EmailRepository(new EmailService(apiService)),
      notificationSenderRepository: new NotificationSenderRepository(
        new NotificationSenderService(apiService)
      ),
      messageTemplateRepository: new MessageTemplateRepository(
        new MessageTemplateService(apiService)
      ),
    };
  }

  return _container;
}

/**
 * Communication container accessor (for use in components)
 */
export const communicationContainer = {
  get emailRepository() {
    return getCommunicationContainer().emailRepository;
  },
  get notificationSenderRepository() {
    return getCommunicationContainer().notificationSenderRepository;
  },
  get messageTemplateRepository() {
    return getCommunicationContainer().messageTemplateRepository;
  },
};

// NotificationSenderView -- accessible-name coverage for the Category and
// Type GenericSelect fields (Wave 1 closure, Task 6).
//
// Both fields sit next to a `<Label htmlFor={categoryId}>` / `<Label
// htmlFor={typeId}>` whose id DOES match the GenericSelect's own `id` prop --
// unlike FeatureDefinitionFormFields.tsx's dangling reference, this one looks
// completely correct in review. It still computed NO accessible name: the
// GenericSelect trigger is a role="combobox" `<div>`, not a labelable HTML
// element, so `for`/`htmlFor` association is a no-op for it regardless of
// whether the ids match (see generic-select.tsx's own `id` prop doc comment).
// These tests assert the real accessible name via `getByRole`'s `name`
// option -- the discriminating check that fails without `aria-label` and
// passes with it, same technique as generic-form.a11y.test.tsx and
// renderCustomFieldControl.test.tsx.
import React from "react";
import { render, screen } from "@testing-library/react";
import { describe, it, expect, beforeEach, vi } from "vitest";
import "@testing-library/jest-dom/vitest";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";

vi.mock("@core/providers/i18n-provider", () => ({
  useI18n: () => ({ t: (key: string) => key, language: "en", direction: "ltr" }),
}));

vi.mock("@core/hooks/use-enhanced-toast", () => ({
  useEnhancedToast: () => ({ success: vi.fn(), error: vi.fn() }),
}));

const { mockSearchTargets, mockSend } = vi.hoisted(() => ({
  mockSearchTargets: vi.fn().mockResolvedValue([]),
  mockSend: vi.fn().mockResolvedValue(undefined),
}));

vi.mock("@modules/communication/di", () => ({
  communicationContainer: {
    notificationSenderRepository: {
      searchTargets: mockSearchTargets,
      send: mockSend,
    },
  },
}));

// jsdom has no ResizeObserver -- GenericSelect's trigger tracks its own width
// on mount regardless of open state (same stub as generic-form.a11y.test.tsx).
if (typeof (globalThis as any).ResizeObserver === "undefined") {
  (globalThis as any).ResizeObserver = class {
    observe() {}
    unobserve() {}
    disconnect() {}
  };
}

if (typeof Element.prototype.scrollIntoView !== "function") {
  Element.prototype.scrollIntoView = () => {};
}

import { NotificationSenderView } from "./NotificationSenderView";

function renderView() {
  const queryClient = new QueryClient({
    defaultOptions: { queries: { retry: false }, mutations: { retry: false } },
  });
  return render(
    <QueryClientProvider client={queryClient}>
      <NotificationSenderView />
    </QueryClientProvider>
  );
}

describe("NotificationSenderView GenericSelect accessible names", () => {
  beforeEach(() => {
    mockSearchTargets.mockClear();
    mockSend.mockClear();
  });

  it("labels the Category select via aria-label, reachable by its visible label text", () => {
    renderView();
    expect(
      screen.getByRole("combobox", { name: "messaging.notifications.category" })
    ).toBeInTheDocument();
  });

  it("labels the Type select via aria-label, reachable by its visible label text", () => {
    renderView();
    expect(
      screen.getByRole("combobox", { name: "messaging.notifications.type" })
    ).toBeInTheDocument();
  });
});

// UI-EXCEPTION: compact studio layout
"use client";

import { useMemo, useCallback, useRef } from "react";
import { useRouter } from "next/navigation";
import { GenericCrudView } from "@core/crud/components/generic-crud-view";
import type { CrudConfig, CrudAction } from "@core/crud/components/generic-crud-view";
import { useMessageTemplatesViewModel } from "../viewmodels/useMessageTemplatesViewModel";
import { PreviewDialog } from "../components/PreviewDialog";
import type {
  MessageTemplate,
  TemplateCategory,
  ExportedTemplate,
} from "../../domain/entities/MessageTemplate";
import { Badge } from "@core/ui/badge";
import { Button } from "@core/ui/button";
import { Copy, Eye, Pencil, Trash2, Download, Upload, BarChart3 } from "lucide-react";
import { formatUtc } from "@core/common/utils";
import { useEnhancedToast } from "@core/hooks/use-enhanced-toast";

// Template category is a taxonomy, not a status — painting "security" in the
// destructive token reads as "this failed", and reusing the same wash for
// "marketing"/"notification" made them indistinguishable. One neutral chip
// for every category; the label text is what tells them apart.
//
// TemplateCategory values are lowercase (backend contract); the
// `messaging.templates.categories.*` locale keys are PascalCase, so the
// lookup capitalizes before translating — the raw lowercase value rendered
// untranslated in the Arabic build otherwise.
function categoryLabel(value: TemplateCategory, t: (key: string) => string): string {
  const key = value.charAt(0).toUpperCase() + value.slice(1);
  return t(`messaging.templates.categories.${key}`);
}

/**
 * Presentation UI component rendering the message templates view.
 * Arranges layout boundaries and accessibility targets (WCAG, tab index) using the core design library (@core/ui/*). Coordinates text fields, submit indicators, and validation warning messages.
 */
export function MessageTemplatesView() {
  const router = useRouter();
  const {
    vm,
    configBase,
    handleClone,
    handlePreview,
    isCloning,
    previewResult,
    previewOpen,
    setPreviewOpen,
    isPreviewLoading,
    t,
  } = useMessageTemplatesViewModel();
  const { success } = useEnhancedToast();
  const fileInputRef = useRef<HTMLInputElement>(null);

  // ─── Export ────────────────────────────────────────────────
  const handleExport = useCallback(
    (item: MessageTemplate) => {
      const exported: ExportedTemplate = {
        key: item.key,
        channel: item.channel,
        subject: item.subject,
        body: item.body,
        language: item.language,
        description: item.description,
        placeholderSchema: item.placeholderSchema,
        designVariables: item.designVariables,
        category: item.category,
        tags: item.tags,
        exportedAt: new Date().toISOString(),
        version: item.version,
      };
      const blob = new Blob([JSON.stringify(exported, null, 2)], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `template-${item.key}.json`;
      a.click();
      URL.revokeObjectURL(url);
      success({ title: t("messaging.templates.exportSuccess") });
    },
    [success, t]
  );

  const handleImportClick = useCallback(() => {
    fileInputRef.current?.click();
  }, []);

  const handleImportFile = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = () => {
        try {
          const data = JSON.parse(reader.result as string);
          // Navigate to template creation form with imported data
          const params = new URLSearchParams({
            key: data.key || "",
            channel: data.channel || "Email",
            subject: data.subject || "",
            body: data.body || "",
            language: data.language || "en",
            description: data.description || "",
            imported: "true",
          });
          router.push(`/communication/templates/new?${params.toString()}`);
        } catch {
          success({ title: t("messaging.templates.importError") });
        }
      };
      reader.readAsText(file);
      // Reset so same file can be re-imported
      e.target.value = "";
    },
    [router, success, t]
  );

  // Navigate to full-page form instead of opening modal
  const handleCreateClick = useCallback(() => {
    router.push("/communication/templates/new");
  }, [router]);

  const handleEdit = useCallback(
    (item: MessageTemplate) => {
      router.push(`/communication/templates/${item.id}/edit`);
    },
    [router]
  );

  // Columns with JSX render functions defined in View (not ViewModel)
  const config: CrudConfig<MessageTemplate> = useMemo(
    () => ({
      ...configBase,
      createFields: [], // No modal form — we navigate to full-page form
      // Override: navigate to full-page form instead of modal
      onCreateClick: handleCreateClick,
      columns: [
        {
          key: "key",
          label: t("messaging.templates.key"),
          sortable: true,
        },
        {
          key: "category",
          label: t("messaging.templates.category"),
          render: (value: TemplateCategory | undefined) => {
            if (!value)
              return (
                <Badge variant="outline" className="text-xs">
                  —
                </Badge>
              );
            return (
              <Badge variant="secondary" className="text-xs">
                {categoryLabel(value, t)}
              </Badge>
            );
          },
        },
        {
          key: "channel",
          label: t("messaging.templates.channel"),
        },
        {
          key: "language",
          label: t("messaging.templates.language"),
        },
        {
          key: "isActive",
          label: t("common.status"),
          render: (value: boolean) => (
            <Badge variant={value ? "success" : "secondary"}>
              {value ? t("common.active") : t("common.inactive")}
            </Badge>
          ),
        },
        {
          key: "usageCount",
          label: t("messaging.templates.usage"),
          render: (value: number | undefined, item: MessageTemplate) => (
            <div className="flex items-center gap-1.5">
              <BarChart3 className="h-3.5 w-3.5 text-nx-ink-3" aria-hidden="true" />
              <span className="font-medium">{value ?? 0}</span>
              {item.lastUsedAt && (
                <span className="text-xs text-nx-ink-3">
                  · {formatUtc(item.lastUsedAt, "MMM d")}
                </span>
              )}
            </div>
          ),
        },
        {
          key: "version",
          label: t("messaging.templates.version"),
          render: (value: number) => (
            <Badge variant="outline" className="font-mono text-xs">
              v{value}
            </Badge>
          ),
        },
        {
          key: "createdAt",
          label: t("common.createdAt"),
          render: (value: string) => (value ? formatUtc(value, "MMM d, yyyy") : "-"),
        },
      ],
      getActions: (_vm: any, _t: any, handleDelete?: any): CrudAction<MessageTemplate>[] => [
        {
          label: t("common.edit"),
          icon: <Pencil className="h-4 w-4" aria-hidden="true" />,
          onClick: (item: MessageTemplate) => handleEdit(item),
        },
        {
          label: t("messaging.templates.preview"),
          icon: <Eye className="h-4 w-4" aria-hidden="true" />,
          onClick: (item: MessageTemplate) => handlePreview(item),
        },
        {
          label: t("messaging.templates.clone"),
          icon: <Copy className="h-4 w-4" aria-hidden="true" />,
          onClick: (item: MessageTemplate) => handleClone(item.id),
          disabled: () => isCloning,
        },
        {
          label: t("messaging.templates.export"),
          icon: <Download className="h-4 w-4" aria-hidden="true" />,
          onClick: (item: MessageTemplate) => handleExport(item),
        },
        {
          label: t("common.delete"),
          icon: <Trash2 className="h-4 w-4" aria-hidden="true" />,
          onClick: handleDelete,
          confirmTitle: t("messaging.templates.deleteTitle"),
          confirmDescription: t("messaging.templates.deleteDescription"),
          confirmVariant: "destructive" as const,
        },
      ],
    }),
    [
      configBase,
      t,
      handlePreview,
      handleClone,
      isCloning,
      handleEdit,
      handleCreateClick,
      handleExport,
    ]
  );

  return (
    <>
      {/* Import/Export Toolbar */}
      <div className="mb-4 flex justify-end">
        <div className="flex gap-2">
          <Button
            variant="outline"
            size="sm"
            className="h-8 gap-1.5 text-xs"
            onClick={handleImportClick}
          >
            <Upload className="h-3.5 w-3.5" aria-hidden="true" />
            {t("messaging.templates.import")}
          </Button>
          <input
            ref={fileInputRef}
            type="file"
            accept=".json"
            className="hidden"
            onChange={handleImportFile}
          />
        </div>
      </div>

      <GenericCrudView viewModel={vm} config={config} onCreateClick={handleCreateClick} />

      <PreviewDialog
        open={previewOpen}
        onOpenChange={setPreviewOpen}
        result={previewResult}
        isLoading={isPreviewLoading}
      />
    </>
  );
}

import { describe, it, expect, vi, beforeEach } from "vitest";
