"use client";

import { useId, useState } from "react";
import {
  useTemplateFormViewModel,
  MESSAGE_TEMPLATE_ENTITY_TYPE_KEY,
} from "../viewmodels/useTemplateFormViewModel";
import { Button } from "@core/ui/button";
import { Input } from "@core/ui/input";
import { Label } from "@core/ui/label";
import { Textarea } from "@core/ui/textarea";
import { Switch } from "@core/ui/switch";
import { DEFAULT_VARIABLES } from "@core/ui/rich-text-editor/VariablePicker";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@core/ui/select";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@core/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@core/ui/tabs";
import { ArrowLeft, Save, Settings, Palette, Braces, Eye, Tag, RotateCcw } from "lucide-react";
import { LoadingSpinner } from "@core/ui/loading-spinner";
import { ErrorMessage } from "@core/ui/error-message";
import { ConfirmationDialog } from "@core/ui/confirmation-dialog";
import { CustomFieldsSection } from "@core/components/custom-fields";
import dynamic from "next/dynamic";

// Lazy-load heavy components (RichTextEditor ~150KB+ TipTap, sidebar panels)
const RichTextEditor = dynamic(
  () =>
    import("@core/ui/rich-text-editor/RichTextEditor").then((m) => ({ default: m.RichTextEditor })),
  { ssr: false }
);
const PlaceholderSchemaBuilder = dynamic(
  () =>
    import("../components/PlaceholderSchemaBuilder").then((m) => ({
      default: m.PlaceholderSchemaBuilder,
    })),
  { ssr: false }
);
const DesignVariablesPanel = dynamic(
  () =>
    import("../components/DesignVariablesPanel").then((m) => ({ default: m.DesignVariablesPanel })),
  { ssr: false }
);
const TemplateLivePreview = dynamic(
  () =>
    import("../components/TemplateLivePreview").then((m) => ({ default: m.TemplateLivePreview })),
  { ssr: false }
);



/**
 * Presentation UI component rendering the template form view.
 * Arranges layout boundaries and accessibility targets (WCAG, tab index) using the core design library (@core/ui/*). Coordinates text fields, submit indicators, and validation warning messages.
 */
export function TemplateFormView({ templateId: _templateId }: { templateId?: string } = {}) {
  const vm = useTemplateFormViewModel();
  const fieldIdBase = useId();
  const [resetDesignDialogOpen, setResetDesignDialogOpen] = useState(false);

  // Edit mode has three real states: the initial fetch, a settled failure
  // (bad id, deleted template, network error), and a settled success. A
  // failed fetch must show an error with a retry — never fall through to the
  // form's default empty values, which would look like a legitimate blank
  // edit and silently create a duplicate on submit instead of updating the
  // template the admin thought they were editing.
  if (vm.mode === "edit" && vm.isFetching) {
    return <LoadingSpinner />;
  }

  if (vm.mode === "edit" && vm.fetchError) {
    return <ErrorMessage message={vm.t("common.error")} onRetry={() => vm.refetch()} fullHeight />;
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Button
          variant="ghost"
          size="icon"
          onClick={vm.handleCancel}
          aria-label={vm.t("common.back")}
        >
          <ArrowLeft className="h-5 w-5" aria-hidden="true" />
        </Button>
        <div>
          <h1 className="text-balance text-xl font-bold leading-tight tracking-tight text-nx-ink">
            {vm.title}
          </h1>
          <p className="text-nx-ink-2">
            {vm.mode === "create"
              ? vm.t("messaging.templates.createDescription")
              : vm.t("messaging.templates.editDescription")}
          </p>
        </div>
      </div>

      {/* Form */}
      <div className="grid grid-cols-1 gap-6 lg:grid-cols-3">
        {/* Main content — left 2/3 */}
        <div className="space-y-6 lg:col-span-2">
          {/* Subject */}
          <Card>
            <CardHeader>
              <CardTitle>{vm.t("messaging.templates.subject")}</CardTitle>
              <CardDescription>{vm.t("messaging.templates.subjectDescription")}</CardDescription>
            </CardHeader>
            <CardContent>
              <Input
                value={vm.form.subject}
                onChange={(e) => vm.updateField("subject", e.target.value)}
                placeholder={vm.t("messaging.templates.subjectPlaceholder")}
              />
            </CardContent>
          </Card>

          {/* Body — Rich Text Editor */}
          <Card>
            <CardHeader>
              <CardTitle>{vm.t("messaging.templates.body")}</CardTitle>
              <CardDescription>{vm.t("messaging.templates.bodyDescription")}</CardDescription>
            </CardHeader>
            <CardContent>
              <RichTextEditor
                value={vm.form.body}
                onChange={(html) => vm.updateField("body", html)}
                placeholder={vm.t("messaging.templates.bodyPlaceholder")}
                minHeight="400px"
                variables={DEFAULT_VARIABLES}
                showSourceToggle
              />
            </CardContent>
          </Card>

          {/* Description */}
          <Card>
            <CardHeader>
              <CardTitle>{vm.t("messaging.templates.descriptionLabel")}</CardTitle>
            </CardHeader>
            <CardContent>
              <Textarea
                value={vm.form.description}
                onChange={(e) => vm.updateField("description", e.target.value)}
                placeholder={vm.t("messaging.templates.descriptionPlaceholder")}
                rows={3}
              />
            </CardContent>
          </Card>
        </div>

        {/* Sidebar — right 1/3 */}
        <div className="space-y-6">
          {/* Tabbed sidebar for Settings, Placeholders, Design */}
          <Card>
            <Tabs defaultValue="settings">
              <CardHeader className="pb-3">
                <TabsList className="h-auto w-full flex-wrap gap-1 p-1">
                  <TabsTrigger
                    value="settings"
                    className="min-w-0 flex-1 gap-1 px-2 text-xs"
                    aria-label={vm.t("messaging.templates.settings")}
                  >
                    <Settings className="h-3.5 w-3.5 shrink-0" aria-hidden="true" />
                    <span className="hidden truncate sm:inline">
                      {vm.t("messaging.templates.settings")}
                    </span>
                  </TabsTrigger>
                  <TabsTrigger
                    value="placeholders"
                    className="min-w-0 flex-1 gap-1 px-2 text-xs"
                    aria-label={vm.t("messaging.templates.placeholders")}
                  >
                    <Braces className="h-3.5 w-3.5 shrink-0" aria-hidden="true" />
                    <span className="hidden truncate sm:inline">
                      {vm.t("messaging.templates.placeholders")}
                    </span>
                  </TabsTrigger>
                  <TabsTrigger
                    value="design"
                    className="min-w-0 flex-1 gap-1 px-2 text-xs"
                    aria-label={vm.t("messaging.templates.design.title")}
                  >
                    <Palette className="h-3.5 w-3.5 shrink-0" aria-hidden="true" />
                    <span className="hidden truncate sm:inline">
                      {vm.t("messaging.templates.design.title")}
                    </span>
                  </TabsTrigger>
                  <TabsTrigger
                    value="preview"
                    className="min-w-0 flex-1 gap-1 px-2 text-xs"
                    aria-label={vm.t("common.preview")}
                  >
                    <Eye className="h-3.5 w-3.5 shrink-0" aria-hidden="true" />
                    <span className="hidden truncate sm:inline">{vm.t("common.preview")}</span>
                  </TabsTrigger>
                  <TabsTrigger
                    value="customFields"
                    className="min-w-0 flex-1 gap-1 px-2 text-xs"
                    aria-label={vm.t("messaging.templates.customFieldsTitle")}
                  >
                    <Tag className="h-3.5 w-3.5 shrink-0" aria-hidden="true" />
                    <span className="hidden truncate sm:inline">
                      {vm.t("messaging.templates.customFieldsTitle")}
                    </span>
                  </TabsTrigger>
                </TabsList>
              </CardHeader>

              {/* Settings Tab */}
              <TabsContent value="settings">
                <CardContent className="space-y-5 pt-0">
                  {/* Template Key (create only) */}
                  {vm.mode === "create" && (
                    <div className="space-y-2">
                      <Label htmlFor={`${fieldIdBase}-key`}>{vm.t("messaging.templates.key")}</Label>
                      <Input
                        id={`${fieldIdBase}-key`}
                        value={vm.form.key}
                        onChange={(e) => vm.updateField("key", e.target.value)}
                        placeholder={vm.t("messaging.templates.keyPlaceholder")}
                      />
                    </div>
                  )}

                  {/* Channel (create only) */}
                  {vm.mode === "create" && (
                    <div className="space-y-2">
                      <Label htmlFor={`${fieldIdBase}-channel`}>
                        {vm.t("messaging.templates.channel")}
                      </Label>
                      <Select
                        value={vm.form.channel}
                        onValueChange={(v) => vm.updateField("channel", v as any)}
                      >
                        <SelectTrigger id={`${fieldIdBase}-channel`}>
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          {vm.channelOptions.map((opt) => (
                            <SelectItem key={opt.value} value={opt.value}>
                              {opt.label}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                  )}

                  {/* Language (create only) */}
                  {vm.mode === "create" && (
                    <div className="space-y-2">
                      <Label htmlFor={`${fieldIdBase}-language`}>
                        {vm.t("messaging.templates.language")}
                      </Label>
                      <Select
                        value={vm.form.language}
                        onValueChange={(v) => vm.updateField("language", v)}
                      >
                        <SelectTrigger id={`${fieldIdBase}-language`}>
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          {vm.languageOptions.map((opt) => (
                            <SelectItem key={opt.value} value={opt.value}>
                              {opt.label}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                  )}

                  {/* Active toggle */}
                  <div className="flex items-center justify-between">
                    <Label htmlFor={`${fieldIdBase}-active`}>{vm.t("common.active")}</Label>
                    <Switch
                      id={`${fieldIdBase}-active`}
                      checked={vm.form.isActive}
                      onCheckedChange={(v) => vm.updateField("isActive", v)}
                    />
                  </div>

                  {/* Category */}
                  <div className="space-y-2">
                    <Label htmlFor={`${fieldIdBase}-category`}>
                      {vm.t("messaging.templates.category")}
                    </Label>
                    <Select
                      value={vm.form.category}
                      onValueChange={(v) => vm.updateField("category", v as any)}
                    >
                      <SelectTrigger id={`${fieldIdBase}-category`}>
                        <SelectValue placeholder={vm.t("messaging.templates.selectCategory")} />
                      </SelectTrigger>
                      <SelectContent>
                        {vm.categoryOptions.map((opt) => (
                          <SelectItem key={opt.value} value={opt.value}>
                            {vm.t(`messaging.templates.categories.${opt.label}`)}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                </CardContent>
              </TabsContent>

              {/* Placeholders Tab */}
              <TabsContent value="placeholders">
                <CardContent className="pt-0">
                  <PlaceholderSchemaBuilder
                    fields={vm.form.placeholderSchema}
                    onChange={vm.updatePlaceholderFields}
                    templateBody={vm.form.body + " " + vm.form.subject}
                  />
                </CardContent>
              </TabsContent>

              {/* Design Variables Tab */}
              <TabsContent value="design">
                <CardContent className="space-y-4 pt-0">
                  {vm.canResetDesign && (
                    <div className="flex justify-end">
                      <Button
                        type="button"
                        variant="outline"
                        size="sm"
                        onClick={() => setResetDesignDialogOpen(true)}
                        disabled={vm.isResettingDesign}
                      >
                        <RotateCcw className="me-1.5 h-3.5 w-3.5" />
                        {vm.t("messaging.templates.resetDesignAction")}
                      </Button>
                    </div>
                  )}
                  <DesignVariablesPanel
                    value={vm.form.designVariables}
                    onChange={vm.updateDesignVariables}
                  />
                </CardContent>
              </TabsContent>

              <ConfirmationDialog
                open={resetDesignDialogOpen}
                onOpenChange={setResetDesignDialogOpen}
                variant="warning"
                title={vm.t("messaging.templates.resetDesignAction")}
                description={vm.t("messaging.templates.resetDesignConfirm")}
                isLoading={vm.isResettingDesign}
                onConfirm={vm.handleResetDesign}
              />

              {/* Live Preview Tab */}
              <TabsContent value="preview">
                <CardContent className="pt-0">
                  <TemplateLivePreview
                    body={vm.form.body}
                    subject={vm.form.subject}
                    designVariables={vm.form.designVariables}
                  />
                </CardContent>
              </TabsContent>

              {/* Custom Fields Tab */}
              <TabsContent value="customFields">
                <CardContent className="space-y-5 pt-0">
                  <CustomFieldsSection
                    configs={vm.customFieldConfigs}
                    values={vm.customFieldValues}
                    onChange={vm.updateCustomFieldValue}
                    isLoading={vm.customFieldsLoading}
                    emptyMessage={vm.t("messaging.templates.noCustomFields")}
                    entityTypeKey={MESSAGE_TEMPLATE_ENTITY_TYPE_KEY}
                    entityDisplayName={vm.t("messaging.templates.title")}
                    onFieldCreated={() => void vm.refetchCustomFields()}
                  />
                </CardContent>
              </TabsContent>
            </Tabs>
          </Card>

          {/* Actions */}
          <Card>
            <CardContent className="space-y-3 pt-6">
              <Button
                className="w-full"
                onClick={vm.handleSubmit}
                disabled={!vm.form.body}
                loading={vm.isSaving}
              >
                {!vm.isSaving && <Save className="me-2 h-4 w-4" aria-hidden="true" />}
                {vm.isSaving ? vm.t("common.saving") : vm.t("common.save")}
              </Button>
              <Button
                variant="outline"
                className="w-full"
                onClick={vm.handleCancel}
                disabled={vm.isSaving}
              >
                {vm.t("common.cancel")}
              </Button>
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}

/**
 * Consent Domain Entity
 */

export type ConsentAction = "Granted" | "Withdrawn";

/**
 * Domain model representing a Consent Status Data structure.
 * Bundles read-only attributes, computed properties, and copy builders for safe mutation state transfers.
 */
export interface ConsentStatusData {
  purposeId: string;
  purposeKey: string;
  purposeName: string;
  currentAction: ConsentAction;
  requiresReConsent: boolean;
  lastUpdatedAt: string;
  consentVersion?: string;
}

/**
 * Domain model representing a Consent Status structure.
 * Bundles read-only attributes, computed properties, and copy builders for safe mutation state transfers.
 */
export class ConsentStatus {
  constructor(private readonly data: ConsentStatusData) {}

  get purposeId() {
    return this.data.purposeId;
  }
  get purposeKey() {
    return this.data.purposeKey ?? "";
  }
  get purposeName() {
    return this.data.purposeName ?? this.data.purposeKey ?? "";
  }
  get currentAction() {
    return this.data.currentAction;
  }
  get isGranted() {
    return this.data.currentAction === "Granted";
  }
  get requiresReConsent() {
    return this.data.requiresReConsent ?? false;
  }
  get lastUpdatedAt() {
    return new Date(this.data.lastUpdatedAt);
  }
  get consentVersion() {
    return this.data.consentVersion ?? "1.0";
  }

  copyWith(updates: Partial<ConsentStatusData>): ConsentStatus {
    return new ConsentStatus({ ...this.data, ...updates });
  }
}

/**
 * Domain model representing a Record Consent Request structure.
 * Bundles read-only attributes, computed properties, and copy builders for safe mutation state transfers.
 */
export interface RecordConsentRequest {
  purposeId: string;
  action: ConsentAction;
  consentVersion: string;
  collectionMethod?: string;
}

/**
 * Domain model representing a Consent Analytics structure.
 * Bundles read-only attributes, computed properties, and copy builders for safe mutation state transfers.
 */
export class ConsentAnalytics {
  constructor(private readonly data: any) {}

  get optInRates(): Record<string, number> {
    return this.data.optInRates ?? {};
  }
  get totalSubjects() {
    return this.data.totalSubjects ?? 0;
  }
  get subjectsRequiringReConsent() {
    return this.data.subjectsRequiringReConsent ?? 0;
  }
  get generatedAt() {
    return new Date(this.data.generatedAt);
  }
}

/**
 * Compliance Module DI Container
 *
 * Central dependency injection for all compliance sub-modules.
 * Follows the entitlements/di.ts pattern exactly.
 *
 * Architecture:
 * - Services implement IService interfaces (API calls only)
 * - Repositories use IService interfaces and map Models → Entities
 * - ViewModels use IRepository interfaces (never Services directly)
 */
import { getModuleApiService } from "@core/services/api-factory";

// ── Service Implementations ──────────────────────────────────────────────────
import { DashboardService } from "./dashboard/src/data/services/DashboardService";
import { DsrService } from "./dsr/src/data/services/DsrService";
import { ConsentService } from "./consent/src/data/services/ConsentService";
import { RetentionService } from "./retention/src/data/services/RetentionService";
import { InventoryService } from "./inventory/src/data/services/InventoryService";
import { ReportService } from "./reports/src/data/services/ReportService";
import { RegulationService } from "./regulations/src/data/services/RegulationService";

// ── Repository Implementations ───────────────────────────────────────────────
import { DashboardRepository } from "./dashboard/src/data/repositories/DashboardRepository";
import { DsrRepository } from "./dsr/src/data/repositories/DsrRepository";
import { ConsentRepository } from "./consent/src/data/repositories/ConsentRepository";
import { RetentionRepository } from "./retention/src/data/repositories/RetentionRepository";
import { InventoryRepository } from "./inventory/src/data/repositories/InventoryRepository";
import { ReportRepository } from "./reports/src/data/repositories/ReportRepository";
import { RegulationRepository } from "./regulations/src/data/repositories/RegulationRepository";

// ── Repository Interfaces (exposed to consumers) ─────────────────────────────
import type { IDashboardRepository } from "./dashboard/src/domain/interfaces/IDashboardRepository";
import type { IDsrRepository } from "./dsr/src/domain/interfaces/IDsrRepository";
import type { IConsentRepository } from "./consent/src/domain/interfaces/IConsentRepository";
import type { IRetentionRepository } from "./retention/src/domain/interfaces/IRetentionRepository";
import type { IInventoryRepository } from "./inventory/src/domain/interfaces/IInventoryRepository";
import type { IReportRepository } from "./reports/src/domain/interfaces/IReportRepository";
import type { IRegulationRepository } from "./regulations/src/domain/interfaces/IRegulationRepository";

// ── Service Interfaces (used internally for DI wiring) ───────────────────────
import type { IDashboardService } from "./dashboard/src/domain/interfaces/IDashboardService";
import type { IDsrService } from "./dsr/src/domain/interfaces/IDsrService";
import type { IConsentService } from "./consent/src/domain/interfaces/IConsentService";
import type { IRetentionService } from "./retention/src/domain/interfaces/IRetentionService";
import type { IInventoryService } from "./inventory/src/domain/interfaces/IInventoryService";
import type { IReportService } from "./reports/src/domain/interfaces/IReportService";
import type { IRegulationService } from "./regulations/src/domain/interfaces/IRegulationService";

// ── Container Interface ───────────────────────────────────────────────────────

export interface ComplianceContainer {
  dashboardRepository: IDashboardRepository;
  dsrRepository: IDsrRepository;
  consentRepository: IConsentRepository;
  retentionRepository: IRetentionRepository;
  inventoryRepository: IInventoryRepository;
  reportRepository: IReportRepository;
  regulationRepository: IRegulationRepository;
}

let _container: ComplianceContainer | null = null;

/**
 * Get the compliance container (lazy initialization)
 */
export function getComplianceContainer(): ComplianceContainer {
  if (typeof window === "undefined") {
    const dummyProxy = new Proxy({} as any, {
      get() {
        return () => Promise.resolve({});
      },
    });
    return {
      dashboardRepository: dummyProxy,
      dsrRepository: dummyProxy,
      consentRepository: dummyProxy,
      retentionRepository: dummyProxy,
      inventoryRepository: dummyProxy,
      reportRepository: dummyProxy,
      regulationRepository: dummyProxy,
    };
  }

  if (!_container) {
    const apiService = getModuleApiService("COMPLIANCE");

    // ── Create Services (typed as interfaces) ──
    const dashboardService: IDashboardService = new DashboardService(apiService);
    const dsrService: IDsrService = new DsrService(apiService);
    const consentService: IConsentService = new ConsentService(apiService);
    const retentionService: IRetentionService = new RetentionService(apiService);
    const inventoryService: IInventoryService = new InventoryService(apiService);
    const reportService: IReportService = new ReportService(apiService);
    const regulationService: IRegulationService = new RegulationService(apiService);

    // ── Create Repositories (IService → IRepository mapping) ──
    _container = {
      dashboardRepository: new DashboardRepository(dashboardService),
      dsrRepository: new DsrRepository(dsrService),
      consentRepository: new ConsentRepository(consentService),
      retentionRepository: new RetentionRepository(retentionService),
      inventoryRepository: new InventoryRepository(inventoryService),
      reportRepository: new ReportRepository(reportService),
      regulationRepository: new RegulationRepository(regulationService),
    };
  }

  return _container;
}

/**
 * Compliance container accessor (for use in components and viewmodels)
 */
export const complianceContainer = {
  get dashboardRepository() {
    return getComplianceContainer().dashboardRepository;
  },
  get dsrRepository() {
    return getComplianceContainer().dsrRepository;
  },
  get consentRepository() {
    return getComplianceContainer().consentRepository;
  },
  get retentionRepository() {
    return getComplianceContainer().retentionRepository;
  },
  get inventoryRepository() {
    return getComplianceContainer().inventoryRepository;
  },
  get reportRepository() {
    return getComplianceContainer().reportRepository;
  },
  get regulationRepository() {
    return getComplianceContainer().regulationRepository;
  },
};

