    await waitFor(() => expect(onSubmit).toHaveBeenCalled());
    expect(onSubmit.mock.calls[0][0]).toMatchObject({ subjectEmail: "subject@example.com" });
    await waitFor(() => expect(onOpenChange).toHaveBeenCalledWith(false));
  });

  it("stays open and does not reset when onSubmit rejects (useDsrViewModel already toasted why)", async () => {
    const onSubmit = vi.fn().mockRejectedValue(new Error("boom"));
    const onOpenChange = vi.fn();
    render(
      <SubmitDsrModal
        {...baseProps({
          onSubmit,
          onOpenChange,
          customFieldConfigs: [PRIORITY_FIELD],
        })}
      />
    );

    fireEvent.change(screen.getByLabelText("compliance.subjectEmail"), {
      target: { value: "subject@example.com" },
    });
    fireEvent.click(screen.getByText("compliance.submitDsr", { selector: "#dsr-submit-confirm" }));

    await waitFor(() => expect(onSubmit).toHaveBeenCalled());
    expect(onOpenChange).not.toHaveBeenCalledWith(false);
    // The email the user typed is still there -- nothing was reset.
    expect(screen.getByLabelText("compliance.subjectEmail")).toHaveValue("subject@example.com");
  });

  it("renders the inline add-custom-field trigger and reports creation via onCustomFieldsCreated", async () => {
    const onCustomFieldsCreated = vi.fn();
    registerFakeCustomFieldsExtension({
      InlineAddTrigger: ({ onCreated }) => (
        <button type="button" onClick={onCreated}>
          inline-add
        </button>
      ),
    });

    render(<SubmitDsrModal {...baseProps({ onCustomFieldsCreated })} />);

    fireEvent.click(screen.getByText("inline-add"));
    expect(onCustomFieldsCreated).toHaveBeenCalled();
  });
});

"use client";

import { useState, useMemo } from "react";
import { useRouter } from "next/navigation";
import { useI18n } from "@core/providers/i18n-provider";
import { useModuleLocales } from "@core/hooks/use-module-locales";
import { useRegulationViewModel } from "../viewmodels/useRegulationViewModel";
import { Button } from "@core/ui/button";
import { PageHeader } from "@core/ui/page-header";
import { EmptyState } from "@core/ui/empty-state";
import { ErrorMessage } from "@core/ui/error-message";
import { Skeleton } from "@core/ui/skeleton";
import { GenericModal } from "@core/crud/components/generic-modal";
import { GenericForm } from "@core/ui/forms/generic-form";
import { usePermission } from "@core/hooks/use-permission";
import { SYSTEM_PERMISSIONS } from "@core/common/types/permissions";
import { useAppStore } from "@core/store/useAppStore";
import { ChevronLeft, ChevronRight, RefreshCw, BookOpen, Plus } from "lucide-react";
import { RegulationCard } from "../components/RegulationCard";

import type { Regulation } from "../../domain/entities/Regulation";

// Loading and loaded share one grid so the page does not resettle on arrival.
const CARD_GRID = "grid grid-cols-1 gap-6 lg:grid-cols-2";

/**
 * Presentation UI component rendering the regulation view.
 * Arranges layout boundaries and accessibility targets (WCAG, tab index) using the core design library (@core/ui/*). Coordinates text fields, submit indicators, and validation warning messages.
 */
export function RegulationView() {
  useModuleLocales(() => import("../../../locales"), "compliance-regulations");
  const { t, direction } = useI18n();
  const router = useRouter();
  const BackIcon = direction === "rtl" ? ChevronRight : ChevronLeft;

  // RegulationProfile carries no TenantId — it's platform-global, seeded-once
  // reference data shared by every tenant, so only platform admins (no
  // tenantCode) may manage it; a tenant-scoped admin only views it.
  const { tenantCode } = useAppStore();
  const hasRegulationManage = usePermission(SYSTEM_PERMISSIONS.COMPLIANCE_REGULATIONS_MANAGE);
  const canCreate = hasRegulationManage && !tenantCode;
  const canUpdate = hasRegulationManage && !tenantCode;

  const [modalMode, setModalMode] = useState<"create" | "edit" | null>(null);
  const [selectedRegulation, setSelectedRegulation] = useState<Regulation | null>(null);

  const {
    regulations,
    isLoading,
    isError,
    refetch,
    createRegulation,
    updateRegulation,
    getFormFields,
  } = useRegulationViewModel();

  const handleCreate = async (data: Record<string, any>) => {
    await createRegulation(data as any);
    setModalMode(null);
  };

  const handleUpdate = async (data: Record<string, any>) => {
    if (!selectedRegulation) return;
    await updateRegulation({ id: selectedRegulation.id, data: data as any });
    setModalMode(null);
  };

  const openCreateModal = () => {
    setSelectedRegulation(null);
    setModalMode("create");
  };

  const openEditModal = (regulation: Regulation) => {
    setSelectedRegulation(regulation);
    setModalMode("edit");
  };

  const closeModals = (open: boolean) => {
    if (!open) setModalMode(null);
  };

  const fields = getFormFields();

  const initialValues = useMemo(() => {
    if (modalMode === "edit" && selectedRegulation) {
      return {
        code: selectedRegulation.code,
        name: selectedRegulation.name,
        jurisdiction: selectedRegulation.jurisdiction,
        dsrDeadlineDays: selectedRegulation.dsrDeadlineDays,
        referenceUrl: selectedRegulation.referenceUrl,
        isActive: selectedRegulation.isActive,
      };
    }
    return {
      isActive: true,
      dsrDeadlineDays: 30,
    };
  }, [modalMode, selectedRegulation]);

  const activeCount = regulations.filter((regulation) => regulation.isActive).length;

  const addButton = (
    <Button onClick={openCreateModal} size="sm">
      <Plus className="me-2 h-4 w-4 shrink-0" aria-hidden="true" />
      {t("compliance.regulations.addRegulation")}
    </Button>
  );

  return (
    <div className="flex flex-col" style={{ gap: "calc(var(--spacing-unit) * 1.5)" }}>
      <PageHeader
        className="mb-0"
        icon={BookOpen}
        title={t("compliance.regulations.title")}
        description={t("compliance.regulations.description")}
        eyebrow={
          <Button variant="ghost" size="sm" onClick={() => router.push("/compliance")}>
            <BackIcon className="me-2 h-4 w-4 shrink-0" aria-hidden="true" />
            {t("common.back")}
          </Button>
        }
        meta={[
          { label: t("common.total"), value: regulations.length.toLocaleString() },
          { label: t("compliance.regulations.active"), value: activeCount.toLocaleString() },
        ]}
        actions={
          <>
            <Button
              id="compliance-regulations-refresh"
              variant="outline"
              size="sm"
              onClick={() => refetch()}
              loading={isLoading}
            >
              {!isLoading && <RefreshCw className="me-2 h-4 w-4 shrink-0" aria-hidden="true" />}
              {t("common.refresh")}
            </Button>
            {canCreate && addButton}
          </>
        }
      />

      {isLoading ? (
        <div className={CARD_GRID} role="status" aria-busy="true" aria-label={t("common.loading")}>
          {Array.from({ length: 4 }).map((_, index) => (
            <Skeleton key={index} className="h-64 w-full rounded-nx-lg" />
          ))}
        </div>
      ) : isError ? (
        <ErrorMessage message={t("compliance.regulations.loadFailed")} onRetry={() => refetch()} />
      ) : regulations.length === 0 ? (
        <EmptyState
          icon={BookOpen}
          title={t("compliance.regulations.noRegulations")}
          description={t("compliance.regulations.noRegulationsDesc")}
          action={canCreate ? addButton : undefined}
        />
      ) : (
        <div className={CARD_GRID}>
          {regulations.map((reg) => (
            <RegulationCard
              key={reg.id}
              regulation={reg}
              onEdit={canUpdate ? openEditModal : undefined}
            />
          ))}
        </div>
      )}

      {/* Generic Modal with Form */}
      <GenericModal
        open={modalMode !== null}
        onOpenChange={closeModals}
        title={
          modalMode === "edit"
            ? t("compliance.regulations.editRegulation")
            : t("compliance.regulations.addRegulation")
        }
        description={
          modalMode === "edit"
            ? `${t("compliance.regulations.code")}: ${selectedRegulation?.code}`
            : t("compliance.regulations.addRegulation")
        }
        size="md"
        formKey={
          modalMode === "edit" ? `edit-regulation-${selectedRegulation?.id}` : "create-regulation"
        }
      >
        <GenericForm
          fields={fields}
          initialValues={initialValues}
          onSubmit={modalMode === "edit" ? handleUpdate : handleCreate}
          onCancel={() => closeModals(false)}
          readOnly={false}
        />
      </GenericModal>
    </div>
  );
}

"use client";

import { useState, useMemo } from "react";
import { useRouter } from "next/navigation";
import { RefreshCw, ChevronLeft, ChevronRight, Clock, Plus } from "lucide-react";
import { PolicyCard } from "../components/PolicyCard";
import { useRetentionViewModel } from "../viewmodels/useRetentionViewModel";
import type { RetentionPolicy } from "../../domain/entities/RetentionPolicy";
import { useI18n } from "@core/providers/i18n-provider";
import { useModuleLocales } from "@core/hooks/use-module-locales";
import { Button } from "@core/ui/button";
import { PageHeader } from "@core/ui/page-header";
import { EmptyState } from "@core/ui/empty-state";
import { ErrorMessage } from "@core/ui/error-message";
import { Skeleton } from "@core/ui/skeleton";
import { GenericModal } from "@core/crud/components/generic-modal";
import { GenericForm } from "@core/ui/forms/generic-form";
import { usePermission } from "@core/hooks/use-permission";
import { SYSTEM_PERMISSIONS } from "@core/common/types/permissions";
import { useAppStore } from "@/core/store/useAppStore";

// Loading and loaded share one grid so the page does not resettle on arrival.
const CARD_GRID = "grid grid-cols-1 gap-4 md:grid-cols-2";

// ── Main View ─────────────────────────────────────────────────────────────────

/**
 * Presentation UI component rendering the retention view.
 * Arranges layout boundaries and accessibility targets (WCAG, tab index) using the core design library (@core/ui/*). Coordinates text fields, submit indicators, and validation warning messages.
 */
export function RetentionView() {
  // Distinct from the inventory view's key: both used "compliance", so whichever
  // page mounted first marked the dictionary loaded and the other rendered raw
  // translation keys.
  useModuleLocales(() => import("../../../locales"), "compliance-retention");
  const { t, direction } = useI18n();
  const router = useRouter();
  const BackIcon = direction === "rtl" ? ChevronRight : ChevronLeft;
  const { tenantCode } = useAppStore();
  const hasPermission = usePermission(SYSTEM_PERMISSIONS.COMPLIANCE_RETENTION_MANAGE);
  const canCreate = hasPermission && !!tenantCode;

  const [modalMode, setModalMode] = useState<"create" | "edit" | null>(null);
  const [selectedPolicy, setSelectedPolicy] = useState<RetentionPolicy | null>(null);

  const {
    policies,
    activeCount,
    totalCount,
    isLoading,
    isError,
    refetch,
    createPolicy,
    updatePolicy,
    getFormFields,
  } = useRetentionViewModel();

  const handleCreate = async (data: Record<string, any>) => {
    await createPolicy(data as any);
    setModalMode(null);
  };

  const handleUpdate = async (data: Record<string, any>) => {
    if (!selectedPolicy) return;
    await updatePolicy({ id: selectedPolicy.id, data: data as any });
    setModalMode(null);
  };

  const openCreateModal = () => {
    setSelectedPolicy(null);
    setModalMode("create");
  };

  const openEditModal = (policy: RetentionPolicy) => {
    setSelectedPolicy(policy);
    setModalMode("edit");
  };

  const closeModals = (open: boolean) => {
    if (!open) setModalMode(null);
  };

  const fields = getFormFields();

  const initialValues = useMemo(() => {
    if (modalMode === "edit" && selectedPolicy) {
      return {
        category: selectedPolicy.category,
        retentionDays: selectedPolicy.retentionDays,
        expiryAction: selectedPolicy.expiryAction,
        isActive: selectedPolicy.isActive,
      };
    }
    return {
      isActive: true,
      retentionDays: 365,
    };
  }, [modalMode, selectedPolicy]);

  const addButton = (
    <Button onClick={openCreateModal} size="sm">
      <Plus className="me-2 h-4 w-4 shrink-0" aria-hidden="true" />
      {t("compliance.addPolicy")}
    </Button>
  );

  return (
    <div className="flex flex-col" style={{ gap: "calc(var(--spacing-unit) * 1.5)" }}>
      <PageHeader
        className="mb-0"
        icon={Clock}
        title={t("compliance.retentionTitle")}
        description={t("compliance.retentionDescription")}
        eyebrow={
          <Button variant="ghost" size="sm" onClick={() => router.push("/compliance")}>
            <BackIcon className="me-2 h-4 w-4 shrink-0" aria-hidden="true" />
            {t("common.back")}
          </Button>
        }
        meta={[
          { label: t("compliance.active"), value: activeCount.toLocaleString() },
          { label: t("common.total"), value: totalCount.toLocaleString() },
        ]}
        actions={
          <>
            <Button
              id="compliance-retention-refresh"
              variant="outline"
              size="sm"
              onClick={() => refetch()}
              loading={isLoading}
            >
              {!isLoading && <RefreshCw className="me-2 h-4 w-4 shrink-0" aria-hidden="true" />}
              {t("common.refresh")}
            </Button>
            {canCreate && addButton}
          </>
        }
      />

      {/* Content */}
      {isLoading ? (
        <div className={CARD_GRID} role="status" aria-busy="true" aria-label={t("common.loading")}>
          {Array.from({ length: 4 }).map((_, index) => (
            <Skeleton key={index} className="h-48 w-full rounded-nx-lg" />
          ))}
        </div>
      ) : isError ? (
        <ErrorMessage message={t("compliance.policiesLoadFailed")} onRetry={() => refetch()} />
      ) : policies.length === 0 ? (
        <EmptyState
          icon={Clock}
          title={t("compliance.noPolicies")}
          description={t("compliance.noPoliciesDesc")}
          action={canCreate ? addButton : undefined}
        />
      ) : (
        <div className={CARD_GRID}>
          {policies.map((policy: RetentionPolicy) => (
            <PolicyCard key={policy.id} policy={policy} onEdit={openEditModal} />
          ))}
        </div>
      )}

      {/* Generic Modal with Form */}
      <GenericModal
        open={modalMode !== null}
        onOpenChange={closeModals}
        title={modalMode === "edit" ? t("compliance.updatePolicy") : t("compliance.addPolicy")}
        description={
          modalMode === "edit"
            ? `${t("compliance.retentionCategory")}: ${selectedPolicy?.category}`
            : t("compliance.addPolicy")
        }
        size="sm"
        formKey={modalMode === "edit" ? `edit-policy-${selectedPolicy?.id}` : "create-policy"}
      >
        <GenericForm
          fields={fields}
          initialValues={initialValues}
          onSubmit={modalMode === "edit" ? handleUpdate : handleCreate}
          onCancel={() => closeModals(false)}
          readOnly={false}
        />
      </GenericModal>
    </div>
  );
}

// FILE-EXCEPTION: file length
/**
 * AccessibilityPanel v2 — Full accessibility settings + WCAG audit
 *
 * Two sections:
 * 1. Settings — Actionable controls persisted to the draft
 * 2. Audit — Real-time WCAG checker with auto-fix buttons
 *
 * @module customization/presentation/components
 */
"use client";
// UI-EXCEPTION: compact studio layout — native <button> used for pixel-precise
// compact controls (toggle switches, gradient pickers, layout thumbnails, etc.)
// where @core/ui/button's padding/sizing would break the layout.

import { useI18n } from "@core/providers/i18n-provider";

import { useState } from "react";
import {
  CheckCircle2,
  AlertTriangle,
  XCircle,
  Info,
  Eye,
  Target,
  Layers,
  Zap,
  Focus,
  MonitorSpeaker,
  ScanEye,
  Paintbrush,
  Type,
  MousePointer2,
  ImageOff,
  Hand,
  ChevronDown,
  ChevronRight,
  Wand2,
  Accessibility,
  Brain,
  BookOpen,
  RotateCcw,
} from "lucide-react";
import { cn } from "@/core/common/utils";
import { Switch } from "@core/ui/switch";
import { Input } from "@core/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@core/ui/select";
import { ColorInput } from "./ColorInput";
import { SliderInput } from "./SliderInput";
import type { StudioDraftProps as StudioDraft } from "../../domain/entities/StudioDraft";
import {
  useAccessibilityChecker,
  type AccessibilityCheck,
  type CheckSeverity,
  type CheckCategory,
} from "../hooks/useAccessibilityChecker";

interface AccessibilityPanelProps {
  draft: StudioDraft;
  updateDraft: <K extends keyof StudioDraft>(field: K, value: StudioDraft[K]) => void;
  batchUpdateDraft: (updates: Partial<StudioDraft>) => void;
}

// ── Collapsible Section ───────────────────────────────

function Section({
  icon: Icon,
  title,
  subtitle,
  color,
  defaultOpen = true,
  children,
}: {
  icon: typeof Focus;
  title: string;
  subtitle?: string;
  color: string;
  defaultOpen?: boolean;
  children: React.ReactNode;
}) {
  const [open, setOpen] = useState(defaultOpen);
  const Arrow = open ? ChevronDown : ChevronRight;

  return (
    <div className="rounded-nx-md border border-nx-line bg-nx-raised">
      <button
        type="button"
        aria-expanded={open}
        className="flex w-full items-center gap-2.5 px-3.5 py-2.5 text-start transition-colors duration-nx-micro ease-nx-enter hover:bg-nx-hover focus-visible:shadow-nx-focus focus-visible:outline-none motion-reduce:transition-none"
        onClick={() => setOpen(!open)}
      >
        <Icon className={cn("h-4 w-4 shrink-0", color)} aria-hidden="true" />
        <div className="min-w-0 flex-1">
          <p className="text-xs font-semibold text-nx-ink">{title}</p>
          {subtitle && <p className="text-[10px] text-nx-ink-3">{subtitle}</p>}
        </div>
        <Arrow className="h-3.5 w-3.5 text-nx-ink-3" aria-hidden="true" />
      </button>
      {open && <div className="space-y-3 border-t border-nx-line px-3.5 py-3">{children}</div>}
    </div>
  );
}

// ── Setting Row ───────────────────────────────────────

function SettingRow({
  label,
  description,
  children,
}: {
  label: string;
  description?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="flex items-center justify-between gap-3">
      <div className="min-w-0 flex-1">
        <p className="text-xs font-medium text-nx-ink">{label}</p>
        {description && <p className="text-[10px] leading-tight text-nx-ink-3">{description}</p>}
      </div>
      <div className="shrink-0">{children}</div>
    </div>
  );
}

// ── Severity Visuals ──────────────────────────────────

const SEVERITY_CONFIG: Record<
  CheckSeverity,
  { icon: typeof CheckCircle2; className: string; bgClass: string }
> = {
  pass: { icon: CheckCircle2, className: "text-success", bgClass: "bg-success/10" },
  warn: { icon: AlertTriangle, className: "text-warning", bgClass: "bg-warning/10" },
  fail: { icon: XCircle, className: "text-destructive", bgClass: "bg-destructive/10" },
  info: { icon: Info, className: "text-info", bgClass: "bg-info/10" },
};

const CATEGORY_CONFIG: Record<
  CheckCategory,
  { icon: typeof Eye; labelKey: string; color: string }
> = {
  contrast: { icon: Eye, labelKey: "studio.a11y.category.contrast", color: "text-nx-accent" },
  target: { icon: Target, labelKey: "studio.a11y.category.target", color: "text-info" },
  overlay: { icon: Layers, labelKey: "studio.a11y.category.overlay", color: "text-warning" },
  motion: { icon: Zap, labelKey: "studio.a11y.category.motion", color: "text-info" },
};

// ── Color Swatch ──────────────────────────────────────

function ColorSwatch({ color }: { color: string }) {
  return (
    <span
      className="inline-block h-4 w-4 shrink-0 rounded-nx-sm border border-nx-line shadow-nx-sm"
      style={{ backgroundColor: color }}
      aria-hidden="true"
    />
  );
}

// ── Audit Check Item ──────────────────────────────────

function CheckItem({ check, onFix }: { check: AccessibilityCheck; onFix?: () => void }) {
  const { t } = useI18n();
  const severity = SEVERITY_CONFIG[check.severity];
  const Icon = severity.icon;

  return (
    <div
      className={cn(
        "flex items-start gap-3 rounded-nx-md border border-nx-line px-3 py-2.5",
        severity.bgClass
      )}
    >
      <Icon className={cn("mt-0.5 h-4 w-4 shrink-0", severity.className)} aria-hidden="true" />
      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-2">
          <span className="text-xs font-medium text-nx-ink">{t(check.labelKey)}</span>
        </div>
        {check.details && (
          <p className="mt-0.5 font-mono text-[10px] text-nx-ink-3">{check.details}</p>
        )}
        {check.colorA && check.colorB && (
          <div className="mt-1.5 flex items-center gap-1.5">
            <ColorSwatch color={check.colorA} />
            <span className="text-[10px] text-nx-ink-3">{t("studio.a11y.onColor")}</span>
            <ColorSwatch color={check.colorB} />
          </div>
        )}
      </div>
      {check.autoFix && onFix && (
        <button
          type="button"
          className="mt-0.5 flex shrink-0 items-center gap-1 rounded-nx-control border border-nx-line bg-nx-surface px-2 py-1 text-[10px] font-medium text-nx-ink transition-colors duration-nx-micro ease-nx-enter hover:bg-nx-hover focus-visible:shadow-nx-focus focus-visible:outline-none motion-reduce:transition-none"
          onClick={onFix}
          aria-label={t("studio.a11y.autoFix")}
        >
          <Wand2 className="h-3 w-3" aria-hidden="true" />
          {t("studio.a11y.fix")}
        </button>
      )}
    </div>
  );
}

// ── Category Section (Audit) ──────────────────────────

function CategorySection({
  category,
  checks,
  onFixCheck,
}: {
  category: CheckCategory;
  checks: AccessibilityCheck[];
  onFixCheck: (fix: Partial<StudioDraft>) => void;
}) {
  const { t } = useI18n();
  if (checks.length === 0) return null;

  const config = CATEGORY_CONFIG[category];
  const CatIcon = config.icon;

  return (
    <div className="space-y-2">
      <div className="flex items-center gap-2">
        <CatIcon className={cn("h-4 w-4", config.color)} aria-hidden="true" />
        <h3 className="text-[10px] font-semibold uppercase tracking-wider text-nx-ink-3">
          {t(config.labelKey)}
        </h3>
      </div>
      <div className="space-y-1.5">
        {checks.map((check) => (
          <CheckItem
            key={check.id}
            check={check}
            onFix={check.autoFix ? () => onFixCheck(check.autoFix!) : undefined}
          />
        ))}
      </div>
    </div>
  );
}

// ── Summary Badge ─────────────────────────────────────

function SummaryBadge({
  count,
  severity,
  label,
}: {
  count: number;
  severity: CheckSeverity;
  label: string;
}) {
  const config = SEVERITY_CONFIG[severity];
  const Icon = config.icon;
  if (count === 0) return null;

  return (
    <div className={cn("flex items-center gap-1.5 rounded-full px-3 py-1", config.bgClass)}>
      <Icon className={cn("h-3.5 w-3.5", config.className)} aria-hidden="true" />
      <span className={cn("text-xs font-semibold", config.className)}>
        {count} {label}
      </span>
    </div>
  );
}

