// ── Main Panel ────────────────────────────────────────

/**
 * Presentation UI component rendering the accessibility panel.
 * Arranges layout boundaries and accessibility targets (WCAG, tab index) using the core design library (@core/ui/*). Coordinates text fields, submit indicators, and validation warning messages.
 */
export function AccessibilityPanel({
  draft,
  updateDraft,
  batchUpdateDraft,
}: AccessibilityPanelProps) {
  const { t } = useI18n();
  const { summary, byCategory } = useAccessibilityChecker(draft);

  const scorePercent =
    summary.total > 0 ? Math.round(((summary.pass + summary.info) / summary.total) * 100) : 100;

  const scoreColor =
    summary.fail > 0 ? "text-destructive" : summary.warn > 0 ? "text-warning" : "text-success";

  const handleAutoFix = (fix: Partial<StudioDraft>) => {
    batchUpdateDraft(fix);
  };

  return (
    <div className="space-y-4">
      {/* ── Score Header ── */}
      <div className="flex flex-col items-center gap-3 rounded-nx-md border border-nx-line bg-nx-raised p-4">
        <div className="relative flex h-20 w-20 items-center justify-center">
          <svg className="h-20 w-20 -rotate-90" viewBox="0 0 80 80">
            <circle
              cx="40"
              cy="40"
              r="34"
              fill="none"
              stroke="currentColor"
              strokeWidth="6"
              className="text-nx-line"
            />
            <circle
              cx="40"
              cy="40"
              r="34"
              fill="none"
              stroke="currentColor"
              strokeWidth="6"
              strokeDasharray={`${2 * Math.PI * 34}`}
              strokeDashoffset={`${2 * Math.PI * 34 * (1 - scorePercent / 100)}`}
              strokeLinecap="round"
              className={scoreColor}
            />
          </svg>
          <span className={cn("absolute text-lg font-bold tabular-nums", scoreColor)}>
            {scorePercent}%
          </span>
        </div>
        <div className="flex flex-wrap items-center justify-center gap-2">
          <SummaryBadge
            count={summary.pass}
            severity="pass"
            label={t("studio.a11y.severity.pass")}
          />
          <SummaryBadge
            count={summary.warn}
            severity="warn"
            label={t("studio.a11y.severity.warn")}
          />
          <SummaryBadge
            count={summary.fail}
            severity="fail"
            label={t("studio.a11y.severity.fail")}
          />
          <SummaryBadge
            count={summary.info}
            severity="info"
            label={t("studio.a11y.severity.info")}
          />
        </div>
        <p className="text-center text-[10px] text-nx-ink-3">
          {t("studio.a11y.summary.description")}
        </p>
      </div>

      {/* ── Accessibility Profiles (One-Click Presets) ── */}
