            onCheckedChange={(v) => updateDraft("a11yHideImages", v)}
          />
        </SettingRow>
        <SettingRow
          label={t("studio.a11y.settings.tooltips")}
          description={t("studio.a11y.settings.tooltipsDesc")}
        >
