        unoptimized
        className="h-full w-full object-cover"
        onError={(e) => {
          e.currentTarget.style.display = "none";
        }}
      />
    </div>
  );
}

// SaveAsThemeModal -- Wave 2 Step 2.2, Task 11
//
// This site had NO test coverage of any kind before this task -- confirmed by
// search across src/modules/admin/customization/branding (no *.test.* files
// existed anywhere in the module). It is a plain presentational component
// (all custom-fields state comes in via props, no internal viewmodel/hook),
// which makes it straightforward to exercise directly, the same way
// TenantPlanStepCustomFields.test.tsx and SubmitDsrModal.customfields.test.tsx
// already do for their own sites: a direct render with props, proving all 5
// FieldConfig["type"] kinds round-trip through the shared renderer end-to-end
// via this site's own real wiring
// (`onChange: (v) => onCustomFieldChange(fc.name, v)`).
import React from "react";
import { render, screen, fireEvent } from "@testing-library/react";
import { describe, it, expect, vi } from "vitest";
import "@testing-library/jest-dom";
import {
  registerCustomFieldsExtension,
  type CustomFieldsExtensionApi,
} from "@core/crud/customFieldsExtension";
import { SaveAsThemeModal } from "./SaveAsThemeModal";

vi.mock("@core/providers/settings-provider", () => ({
  useSettings: () => ({ switchStyle: "default", fontSize: "default", inputStyle: "default" }),
}));

vi.mock("@core/providers/i18n-provider", () => ({
  useI18n: () => ({ t: (key: string) => key, language: "en", direction: "ltr" }),
}));

// jsdom has no ResizeObserver -- GenericSelect's trigger tracks its own width
// on mount regardless of open state (same stub as renderCustomFieldControl.test.tsx).
if (typeof (globalThis as any).ResizeObserver === "undefined") {
  (globalThis as any).ResizeObserver = class {
    observe() {}
    unobserve() {}
    disconnect() {}
  };
}

// jsdom also has no scrollIntoView -- cmdk calls it on the highlighted row's
// layout effect as soon as a GenericSelect panel's option list mounts.
if (typeof Element.prototype.scrollIntoView !== "function") {
  Element.prototype.scrollIntoView = () => {};
}

function registerFakeCustomFieldsExtension(
  overrides: Partial<CustomFieldsExtensionApi> = {}
): CustomFieldsExtensionApi {
  const fake: CustomFieldsExtensionApi = {
    getFormFields: vi.fn().mockResolvedValue([]),
    saveValues: vi.fn().mockResolvedValue(undefined),
    getBulkColumnValues: vi.fn().mockResolvedValue({ columns: [], valuesByOwnerId: {} }),
    InlineAddTrigger: () => null,
    ...overrides,
  };
  registerCustomFieldsExtension(fake);
  return fake;
}

// One FieldConfig per FieldConfig["type"] this catalog produces -- same 5
// kinds renderCustomFieldControl.tsx's own switch handles.
const TEXT_FIELD = { name: "__cf__nickname", label: "Nickname", type: "text" as const };
const NUMBER_FIELD = { name: "__cf__score", label: "Score", type: "number" as const };
const SWITCH_FIELD = { name: "__cf__featured", label: "Featured", type: "switch" as const };
const DATE_FIELD = { name: "__cf__startdate", label: "Start Date", type: "date" as const };
const SELECT_FIELD = {
  name: "__cf__mood",
  label: "Mood",
  type: "select" as const,
  options: [
    { value: "Bold", label: "Bold" },
    { value: "Calm", label: "Calm" },
  ],
};
const ALL_FIELD_TYPES = [TEXT_FIELD, NUMBER_FIELD, SWITCH_FIELD, DATE_FIELD, SELECT_FIELD];

function renderModal(overrides: Partial<React.ComponentProps<typeof SaveAsThemeModal>> = {}) {
  return render(
    <SaveAsThemeModal
      isOpen
      onClose={vi.fn()}
      getDraftJson={() => JSON.stringify({ tokens: { "color.primary": "#123456" } })}
      onSaveTheme={vi.fn().mockResolvedValue(undefined)}
      customFieldConfigs={[]}
      customFieldsLoading={false}
      customFieldValues={{}}
      onCustomFieldChange={vi.fn()}
      onCustomFieldsCreated={vi.fn()}
      {...overrides}
    />
  );
}

describe("SaveAsThemeModal + custom fields", () => {
  it("renders a text input for a custom field and reports changes", () => {
    registerFakeCustomFieldsExtension();
    const onCustomFieldChange = vi.fn();
    renderModal({
      customFieldConfigs: [{ name: "cf_nickname", type: "text", label: "Nickname" }],
      onCustomFieldChange,
    });

    fireEvent.change(screen.getByLabelText("Nickname"), { target: { value: "a" } });
    expect(onCustomFieldChange).toHaveBeenCalledWith("cf_nickname", "a");
  });

  // The core proof this task requires: round-tripping a value of each of the
  // 5 custom field types through the shared renderer end-to-end (render ->
  // change -> captured onCustomFieldChange value), through this site's own
  // real wiring, not just the isolated unit-level renderer tests.
  it("round-trips a value of each of the 5 custom field types through the shared renderer end-to-end", () => {
    registerFakeCustomFieldsExtension();
    const onCustomFieldChange = vi.fn();
    renderModal({ customFieldConfigs: ALL_FIELD_TYPES, onCustomFieldChange });

    fireEvent.change(screen.getByLabelText("Nickname"), { target: { value: "Mo" } });
    expect(onCustomFieldChange).toHaveBeenCalledWith("__cf__nickname", "Mo");

    fireEvent.change(screen.getByLabelText("Score"), { target: { value: "42" } });
    expect(onCustomFieldChange).toHaveBeenCalledWith("__cf__score", "42");

    fireEvent.click(screen.getByRole("switch", { name: "Featured" }));
    expect(onCustomFieldChange).toHaveBeenCalledWith("__cf__featured", true);

    // Scoped to `input`: Wave 3.1 Task 12 gave the DatePicker trigger its own
    // real aria-label equal to the field's label, so a bare
    // `getByLabelText("Start Date")` is now ambiguous by design -- see
    // renderCustomFieldControl.tsx's Date branch.
    fireEvent.change(screen.getByLabelText("Start Date", { selector: "input" }), {
      target: { value: "2026-08-17" },
    });
    expect(onCustomFieldChange).toHaveBeenCalledWith("__cf__startdate", "2026-08-17");

    const trigger = screen.getByRole("combobox", { name: "Mood" });
    fireEvent.click(trigger);
    fireEvent.click(screen.getByRole("option", { name: "Calm" }));
    expect(onCustomFieldChange).toHaveBeenCalledWith("__cf__mood", "Calm");
  });

  it("shows the empty-state message when there are no custom fields and not loading", () => {
    registerFakeCustomFieldsExtension();
    renderModal({ customFieldConfigs: [], customFieldsLoading: false });
    expect(screen.getByText("studio.saveTheme.noCustomFields")).toBeInTheDocument();
  });

  it("does not show the empty-state message while loading", () => {
    registerFakeCustomFieldsExtension();
    renderModal({ customFieldConfigs: [], customFieldsLoading: true });
    expect(screen.queryByText("studio.saveTheme.noCustomFields")).not.toBeInTheDocument();
  });

  // Wave 5 row 5.6 (design spec §5.4; pre-plan R2's "hand-rolled" shape):
  // hosts InlineAddCustomFieldDialog (now a modal={false} Sheet) via
  // ThemeCustomFieldsAddTrigger, so this dialog's own outer Dialog must also
  // be modal={false} -- see WebhookForm.customfields.test.tsx's identical
  // test for the full aria-hidden mechanism this proves against.
  it("renders as a non-modal dialog: a sentinel outside it stays reachable via getByRole while it is open", () => {
    registerFakeCustomFieldsExtension();

    render(
      <div>
        <button type="button">host-page-sentinel</button>
        <SaveAsThemeModal
          isOpen
          onClose={vi.fn()}
          getDraftJson={() => JSON.stringify({ tokens: { "color.primary": "#123456" } })}
          onSaveTheme={vi.fn().mockResolvedValue(undefined)}
          customFieldConfigs={[]}
          customFieldsLoading={false}
          customFieldValues={{}}
          onCustomFieldChange={vi.fn()}
          onCustomFieldsCreated={vi.fn()}
        />
      </div>
    );

    expect(screen.getByRole("dialog", { name: "studio.saveTheme.title" })).toBeInTheDocument();
    expect(screen.getByRole("button", { name: "host-page-sentinel" })).toBeInTheDocument();
  });

  it("renders the inline add-custom-field trigger and reports creation via onCustomFieldsCreated", () => {
    const onCustomFieldsCreated = vi.fn();
    registerFakeCustomFieldsExtension({
      InlineAddTrigger: ({ onCreated }) => (
        <button type="button" onClick={onCreated}>
          inline-add
        </button>
      ),
    });

    renderModal({ onCustomFieldsCreated });

    fireEvent.click(screen.getByText("inline-add"));
    expect(onCustomFieldsCreated).toHaveBeenCalled();
  });
});

/**
 * StudioSidebar -- 11-tab sidebar for the Ultimate Customizer Studio
 * All labels localized via t()
 */
"use client";
// UI-EXCEPTION: compact studio layout -- native <button> used for pixel-precise
// compact controls (toggle switches, gradient pickers, layout thumbnails, etc.)
// where @core/ui/button's padding/sizing would break the layout.

import { useMemo } from "react";
import {
  Layout,
  Palette,
  Type,
  Settings2,
  Layers,
  Blocks,
  Paintbrush,
  ScanEye,
  Store,
  LayoutGrid,
  LayoutDashboard,
} from "lucide-react";
import { cn } from "@/core/common/utils";
import { LayoutPanel } from "./LayoutPanel";
import { BrandingPanel } from "./BrandingPanel";
import { BlockPanel } from "./BlockPanel";
import type {
  StudioDraftProps as StudioDraft,
  StudioPanel,
  AuthPageId,
  AuthPageOverride,
} from "../../domain/entities/StudioDraft";
import type {
  LoginSlotId,
  ContentBlock,
} from "@modules/auth/core/domain/entities/LoginBrandingTypes";
import { StylePanel } from "./StylePanel";
import { AdvancedPanel } from "./AdvancedPanel";
import { AccessibilityPanel } from "./AccessibilityPanel";
import { ThemeMarketplacePanel } from "./ThemeMarketplacePanel";
import { BuilderPanel } from "./builder/BuilderPanel";
import { DashboardBuilderTab } from "./DashboardBuilderTab";
import type { DashboardThemeSettings } from "../../domain/entities/StudioDraft";
import { useI18n } from "@core/providers/i18n-provider";

interface StudioSidebarProps {
  activePanel: StudioPanel;
  setActivePanel: (panel: StudioPanel) => void;
  draft: StudioDraft;
  updateDraft: <K extends keyof StudioDraft>(field: K, value: StudioDraft[K]) => void;
  batchUpdateDraft: (updates: Partial<StudioDraft>) => void;
  addBlock: (slotId: LoginSlotId, block: ContentBlock) => void;
  removeBlock: (slotId: LoginSlotId, index: number) => void;
  moveBlock: (slotId: LoginSlotId, fromIndex: number, direction: "up" | "down") => void;
  updateBlock: (slotId: LoginSlotId, index: number, block: ContentBlock) => void;
  // Theme marketplace callbacks
  onThemeApplied?: () => void;
  onPreviewTheme?: (themeDataJson: string) => void;
  onExitPreview?: () => void;
  // Multi-page branding
  activeAuthPage: AuthPageId;
  getPageOverride: (pageId: AuthPageId) => AuthPageOverride;
  setPageOverride: (
    pageId: AuthPageId,
    field: keyof AuthPageOverride,
    value: AuthPageOverride[keyof AuthPageOverride]
  ) => void;
  /** When true, builder canvas is rendered externally (full-width) */
  isBuilderMode?: boolean;
}

const TABS: { id: StudioPanel; icon: typeof Layout; labelKey: string; section?: string }[] = [
  // Login customization
  { id: "layout", icon: Layout, labelKey: "studio.tab.layout", section: "login" },
  { id: "builder", icon: LayoutGrid, labelKey: "studio.tab.builder", section: "login" },
  { id: "branding", icon: Paintbrush, labelKey: "studio.tab.branding", section: "login" },
  { id: "appearance", icon: Palette, labelKey: "studio.tab.appearance", section: "login" },
  { id: "typography", icon: Type, labelKey: "studio.tab.typography", section: "login" },
  { id: "spacing", icon: Settings2, labelKey: "studio.tab.spacing", section: "login" },
  { id: "blocks", icon: Blocks, labelKey: "studio.tab.blocks", section: "login" },
  // Dashboard customization
  {
    id: "dashboard",
    icon: LayoutDashboard,
    labelKey: "studio.tab.dashboard",
    section: "dashboard",
  },
  // System
  { id: "advanced", icon: Layers, labelKey: "studio.tab.advanced", section: "system" },
  { id: "accessibility", icon: ScanEye, labelKey: "studio.tab.accessibility", section: "system" },
  { id: "themes", icon: Store, labelKey: "studio.tab.themes", section: "system" },
];

/**
 * Presentation UI component rendering the studio sidebar.
 * Arranges layout boundaries and accessibility targets (WCAG, tab index) using the core design library (@core/ui/*).
 */
export function StudioSidebar(props: StudioSidebarProps) {
  const { t } = useI18n();
  const {
    activePanel,
    setActivePanel,
    draft,
    updateDraft,
    batchUpdateDraft,
    addBlock,
    removeBlock,
    moveBlock,
    updateBlock,
    activeAuthPage,
    getPageOverride,
    setPageOverride,
  } = props;

  const currentPageOverride = getPageOverride(activeAuthPage);

  // Dashboard settings wired to draft persistence
  const handleDashboardUpdate = (updates: Partial<DashboardThemeSettings>) => {
    updateDraft("dashboardSettings", { ...draft.dashboardSettings, ...updates });
  };

  // Group tabs by section for visual separation
  const tabSections = useMemo(() => {
    const sections: { section: string; tabs: typeof TABS }[] = [];
    let currentSection = "";
    for (const tab of TABS) {
      const section = tab.section || "other";
      if (section !== currentSection) {
        currentSection = section;
        sections.push({ section, tabs: [] });
      }
      sections[sections.length - 1].tabs.push(tab);
    }
    return sections;
  }, []);

  return (
    <div className="flex h-full border-e border-nx-line bg-nx-surface">
      {/* Tab Strip */}
      <div className="scrollbar-thin flex w-14 flex-col items-center gap-0.5 overflow-y-auto border-e border-nx-line bg-nx-raised py-3">
        {tabSections.map((section, si) => (
          <div key={section.section} className="flex w-full flex-col items-center gap-1">
            {/* Section divider (not for first section) */}
            {si > 0 && <div className="my-1 h-px w-6 bg-nx-line" />}
            {section.tabs.map((tab) => {
              const Icon = tab.icon;
              const isActive = activePanel === tab.id;
              return (
                <button
                  key={tab.id}
                  type="button"
                  onClick={() => setActivePanel(tab.id)}
                  aria-label={t(tab.labelKey)}
                  aria-pressed={isActive}
                  className={cn(
                    "group relative flex h-10 w-10 items-center justify-center rounded-nx-control transition-colors duration-nx-micro ease-nx-enter focus-visible:shadow-nx-focus focus-visible:outline-none motion-reduce:transition-none",
                    isActive
                      ? "bg-nx-accent-fill text-nx-on-fill"
                      : "text-nx-ink-2 hover:bg-nx-hover hover:text-nx-ink"
                  )}
                >
                  <Icon className="h-4 w-4" aria-hidden="true" />
                  {/* Active indicator */}
                  {isActive && (
                    <div className="absolute -end-[5px] top-1/2 h-5 w-[3px] -translate-y-1/2 rounded-full bg-nx-accent" />
                  )}
                </button>
              );
            })}
          </div>
        ))}
      </div>

      {/* Panel Content */}
      <div className="scrollbar-thin w-[340px] overflow-y-auto">
        {/* Panel Header */}
        <div className="sticky top-0 z-sticky border-b border-nx-line bg-nx-surface px-4 py-3">
          <h2 className="text-sm font-semibold text-nx-ink">
            {t(TABS.find((tab) => tab.id === activePanel)?.labelKey || "")}
          </h2>
        </div>

        {/* Active Panel */}
        <div className="p-4">
          {activePanel === "layout" && (
            <LayoutPanel
              selectedLayout={currentPageOverride.layout}
              onSelectLayout={(layout) => setPageOverride(activeAuthPage, "layout", layout)}
              activeAuthPage={activeAuthPage}
              pageOverride={currentPageOverride}
              onUpdatePageField={(field, value) => setPageOverride(activeAuthPage, field, value)}
              canvasMode={
                activeAuthPage === "login"
                  ? draft.canvasMode
                  : (currentPageOverride as any).canvasMode || "layout"
              }
              onCanvasModeChange={(mode) => {
                if (activeAuthPage === "login") {
                  updateDraft("canvasMode", mode);
                } else {
                  setPageOverride(activeAuthPage, "canvasMode" as any, mode);
                }
              }}
            />
          )}
          {activePanel === "branding" && <BrandingPanel draft={draft} updateDraft={updateDraft} />}
          {(activePanel === "appearance" ||
            activePanel === "typography" ||
            activePanel === "spacing") && (
            <StylePanel
              activeSection={activePanel}
              draft={draft}
              updateDraft={updateDraft}
              batchUpdateDraft={batchUpdateDraft}
            />
          )}
          {activePanel === "blocks" && (
            <BlockPanel
              draft={draft}
              addBlock={addBlock}
              removeBlock={removeBlock}
              moveBlock={moveBlock}
              updateBlock={updateBlock}
            />
          )}
          {activePanel === "advanced" && <AdvancedPanel draft={draft} updateDraft={updateDraft} />}
          {activePanel === "accessibility" && (
            <AccessibilityPanel
              draft={draft}
              updateDraft={updateDraft}
              batchUpdateDraft={batchUpdateDraft}
            />
          )}
          {activePanel === "themes" && (
            <ThemeMarketplacePanel
              onApplySuccess={props.onThemeApplied}
              onPreviewTheme={props.onPreviewTheme}
              onExitPreview={props.onExitPreview}
            />
          )}
          {activePanel === "builder" && (
            <BuilderPanel
              draft={draft}
              updateDraft={updateDraft}
              sidebarOnly={!!props.isBuilderMode}
              activeAuthPage={activeAuthPage}
            />
          )}
          {activePanel === "dashboard" && (
            <DashboardBuilderTab
              settings={draft.dashboardSettings}
              onUpdate={handleDashboardUpdate}
            />
          )}
        </div>
      </div>
    </div>
  );
}

