/**
 * StylePanel — Appearance + Typography + Spacing
 * Complete light/dark isolation with section-independent backgrounds.
 * Uses ImageUploadField for bg images, Select for fonts, Slider for sizes.
 */
"use client";
// UI-EXCEPTION: compact studio layout — native <button> used for pixel-precise
// compact controls (toggle switches, gradient pickers, layout thumbnails, etc.)
// where @core/ui/button's padding/sizing would break the layout.

import {
  Ruler,
  Sun,
  Moon,
  Palette,
  Square,
  Globe,
  Image as ImageIcon,
  ArrowUp,
  ArrowUpRight,
  ArrowRight,
  ArrowDownRight,
  ArrowDown,
  ArrowDownLeft,
  ArrowLeft,
  ArrowUpLeft,
  Circle,
} from "lucide-react";
import { cn } from "@/core/common/utils";
import { useI18n } from "@core/providers/i18n-provider";

import { ColorInput } from "./ColorInput";
import { SliderInput } from "./SliderInput";
import { Switch } from "@core/ui/switch";
import { ImageUploadField } from "@core/ui/image-upload-field";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@core/ui/select";
import type {
  StudioDraftProps as StudioDraft,
  StudioPanel,
} from "../../domain/entities/StudioDraft";
import { COLOR_PRESETS, FONT_OPTIONS_EN, FONT_OPTIONS_AR } from "../../domain/entities/StudioDraft";

interface StylePanelProps {
  activeSection: StudioPanel;
  draft: StudioDraft;
  updateDraft: <K extends keyof StudioDraft>(field: K, value: StudioDraft[K]) => void;
  batchUpdateDraft: (updates: Partial<StudioDraft>) => void;
}

// NOTE: `COLOR_THEME_SWATCHES` (@core/settings/defaults) is a hue/chroma accent-swatch
// list for the workspace's OWN accent picker and currently has zero consumers anywhere
// in src/. It is not a drop-in replacement for `COLOR_PRESETS` below, which carries full
// light+dark, multi-role login-page palettes (bg/surface/text/border/etc per preset) from
// a domain file outside this package's ownership. Substituting one for the other would
// both lose real preset data and require inventing new oklch-to-hex colour math with no
// existing helper — see escalations.

const DIRECTION_ICONS: Partial<Record<string, typeof ArrowUp>> = {
  top: ArrowUp,
  topRight: ArrowUpRight,
  right: ArrowRight,
  bottomRight: ArrowDownRight,
  bottom: ArrowDown,
  bottomLeft: ArrowDownLeft,
  left: ArrowLeft,
  topLeft: ArrowUpLeft,
  center: Circle,
  topCenter: ArrowUp,
  bottomCenter: ArrowDown,
  centerLeft: ArrowLeft,
  centerRight: ArrowRight,
};

const GRADIENT_DIRECTIONS = [
  { value: "to top", key: "top" },
  { value: "to top right", key: "topRight" },
  { value: "to right", key: "right" },
  { value: "to bottom right", key: "bottomRight" },
  { value: "to bottom", key: "bottom" },
  { value: "to bottom left", key: "bottomLeft" },
  { value: "to left", key: "left" },
  { value: "to top left", key: "topLeft" },
];

// ── Layout Section Map: how many visual bg sections each layout has ──
const LAYOUT_SECTION_MAP: Record<string, { sections: 1 | 2; labels?: [string, string] }> = {
  // 1-section layouts — single page background
  centered: { sections: 1 },
  minimal: { sections: 1 },
  "fullscreen-form": { sections: 1 },
  floating: { sections: 1 },
  spotlight: { sections: 1 },
  "glass-morphism": { sections: 1 },
  mosaic: { sections: 1 },
  overlay: { sections: 1 },
  "branded-full": { sections: 1 },
  // 2-section layouts — split/stacked with independent areas
  "split-right": { sections: 2, labels: ["formSide", "brandingPanel"] },
  "split-left": { sections: 2, labels: ["formSide", "brandingPanel"] },
  asymmetric: { sections: 2, labels: ["formSide", "brandingPanel"] },
  "sidebar-compact": { sections: 2, labels: ["formSide", "brandingPanel"] },
  carousel: { sections: 2, labels: ["formSide", "brandingPanel"] },
  "dual-panel": { sections: 2, labels: ["formSide", "brandingPanel"] },
  "split-diagonal": { sections: 2, labels: ["formSide", "brandingPanel"] },
  stacked: { sections: 2, labels: ["heroSection", "formArea"] },
  "vertical-split": { sections: 2, labels: ["heroSection", "formArea"] },
  "gradient-wave": { sections: 2, labels: ["heroSection", "formArea"] },
  magazine: { sections: 2, labels: ["heroSection", "formArea"] },
  immersive: { sections: 2, labels: ["heroSection", "formArea"] },
  "corner-card": { sections: 2, labels: ["heroSection", "formArea"] },
};

// ═══════════════════════════════════════════════════
// BgControls — extracted as a stable module-level component
// (defining it inside the render function created a new component identity
//  on every re-render, causing React to unmount/remount all inputs, losing focus)
// ═══════════════════════════════════════════════════

const IMAGE_FIT_OPTIONS = [
  { value: "cover" as const, labelKey: "studio.background.fitCover" },
  { value: "contain" as const, labelKey: "studio.background.fitContain" },
  { value: "fill" as const, labelKey: "studio.background.fitFill" },
  { value: "none" as const, labelKey: "studio.background.fitNone" },
  { value: "scale-down" as const, labelKey: "studio.background.fitScaleDown" },
];

const IMAGE_POSITION_OPTIONS = [
  { value: "top left", key: "topLeft" },
  { value: "top center", key: "topCenter" },
  { value: "top right", key: "topRight" },
  { value: "center left", key: "centerLeft" },
  { value: "center", key: "center" },
  { value: "center right", key: "centerRight" },
  { value: "bottom left", key: "bottomLeft" },
  { value: "bottom center", key: "bottomCenter" },
  { value: "bottom right", key: "bottomRight" },
];

interface BgControlsProps {
  prefix: string;
  bgType: "solid" | "gradient" | "image";
  bgColor: string;
  bgGradientDirection: string;
  bgGradientFrom: string;
  bgGradientTo: string;
  bgImageUrl: string;
  bgImageFit: "cover" | "contain" | "fill" | "none" | "scale-down";
  bgImagePosition: string;
  bgOverlayEnabled: boolean;
  bgOverlayColor: string;
  bgOverlayOpacity: number;
  bgBlur: number;
  hideImage?: boolean;
  copyFromLightUrl?: string;
  updateDraft: <K extends keyof StudioDraft>(field: K, value: StudioDraft[K]) => void;
}

function BgControls({
  prefix,
  bgType,
  bgColor,
  bgGradientDirection,
  bgGradientFrom,
  bgGradientTo,
  bgImageUrl,
  bgImageFit,
  bgImagePosition,
  bgOverlayEnabled,
  bgOverlayColor,
  bgOverlayOpacity,
  bgBlur,
  hideImage,
  copyFromLightUrl,
  updateDraft,
}: BgControlsProps) {
  const { t } = useI18n();
  const f = (field: string): keyof StudioDraft => {
    if (prefix === "") return field as keyof StudioDraft;
    const stripped = field.startsWith("bg") ? field.slice(2) : field;
    return `${prefix}${stripped}` as keyof StudioDraft;
  };

  return (
    <div className="space-y-3">
      <div className="grid grid-cols-3 gap-1.5">
        {(hideImage
          ? (["solid", "gradient"] as const)
          : (["solid", "gradient", "image"] as const)
        ).map((type) => (
          <button
            key={type}
            type="button"
            onClick={() => updateDraft(f("bgType"), type as any)}
            className={cn(
              "h-7 rounded-nx-control border text-[10px] font-medium transition-colors duration-nx-micro ease-nx-enter focus-visible:shadow-nx-focus focus-visible:outline-none motion-reduce:transition-none",
              bgType === type
                ? "border-nx-accent bg-nx-accent-wash text-nx-accent"
                : "border-nx-line text-nx-ink-2 hover:border-nx-line-hi"
            )}
          >
            {t(`studio.background.${type}`)}
          </button>
        ))}
      </div>

      {bgType === "solid" && (
        <ColorInput
          label={t("studio.colors.background")}
          value={bgColor}
          onChange={(v) => updateDraft(f("bgColor"), v as any)}
        />
      )}

      {bgType === "gradient" && (
        <div className="space-y-2">
          <div className="grid grid-cols-4 gap-1">
            {GRADIENT_DIRECTIONS.map((dir) => {
              const Icon = DIRECTION_ICONS[dir.key] ?? ArrowUp;
              const label = t(`studio.direction.${dir.key}`);
              return (
                <button
                  key={dir.value}
                  type="button"
                  onClick={() => updateDraft(f("bgGradientDirection"), dir.value as any)}
                  aria-label={label}
                  className={cn(
                    "flex h-6 items-center justify-center rounded-nx-control border transition-colors duration-nx-micro ease-nx-enter focus-visible:shadow-nx-focus focus-visible:outline-none motion-reduce:transition-none",
                    bgGradientDirection === dir.value
                      ? "border-nx-accent bg-nx-accent-wash text-nx-accent"
                      : "border-nx-line text-nx-ink-2 hover:border-nx-line-hi"
                  )}
                >
                  <Icon className="h-3 w-3" aria-hidden="true" />
                </button>
              );
            })}
          </div>
          <ColorInput
            label={t("studio.background.from")}
            value={bgGradientFrom}
            onChange={(v) => updateDraft(f("bgGradientFrom"), v as any)}
          />
          <ColorInput
            label={t("studio.background.to")}
            value={bgGradientTo}
            onChange={(v) => updateDraft(f("bgGradientTo"), v as any)}
          />
          <div
            className="h-8 w-full rounded-nx-control border border-nx-line"
            style={{
              background: `linear-gradient(${bgGradientDirection}, ${bgGradientFrom}, ${bgGradientTo})`,
            }}
          />
        </div>
      )}

      {bgType === "image" && (
        <>
          {copyFromLightUrl && (
            <button
              type="button"
              onClick={() => updateDraft(f("bgImageUrl"), copyFromLightUrl as any)}
              className="flex h-7 w-full items-center justify-center gap-1.5 rounded-nx-control border border-warning/40 bg-warning/10 text-[10px] font-medium text-warning transition-colors duration-nx-micro ease-nx-enter hover:bg-warning/20 focus-visible:shadow-nx-focus focus-visible:outline-none motion-reduce:transition-none"
            >
              <Sun className="h-3 w-3" aria-hidden="true" />
              {t("studio.background.useLight")}
            </button>
          )}
          <ImageUploadField
            value={bgImageUrl}
            onChange={(v) => updateDraft(f("bgImageUrl"), v as any)}
            label={t("studio.background.imageUrl")}
            maxSizeBytes={5 * 1024 * 1024}
            accept="image/png,image/jpeg,image/webp,image/gif"
          />
          <div className="space-y-1.5">
            <span className="text-[10px] font-medium text-nx-ink-3">
              {t("studio.background.imageFit")}
            </span>
            <div className="grid grid-cols-5 gap-1">
              {IMAGE_FIT_OPTIONS.map((opt) => (
                <button
                  key={opt.value}
                  type="button"
                  onClick={() => updateDraft(f("bgImageFit"), opt.value as any)}
                  className={cn(
                    "h-6 rounded-nx-control border text-[9px] font-medium transition-colors duration-nx-micro ease-nx-enter focus-visible:shadow-nx-focus focus-visible:outline-none motion-reduce:transition-none",
                    bgImageFit === opt.value
                      ? "border-nx-accent bg-nx-accent-wash text-nx-accent"
                      : "border-nx-line text-nx-ink-2 hover:border-nx-line-hi"
                  )}
                >
                  {t(opt.labelKey)}
                </button>
              ))}
            </div>
          </div>
          <div className="space-y-1.5">
            <span className="text-[10px] font-medium text-nx-ink-3">
              {t("studio.background.imagePosition")}
            </span>
            <div className="grid w-24 grid-cols-3 gap-1">
              {IMAGE_POSITION_OPTIONS.map((opt) => {
                const Icon = DIRECTION_ICONS[opt.key] ?? Circle;
                const label = t(`studio.direction.${opt.key}`);
                return (
                  <button
                    key={opt.value}
                    type="button"
                    onClick={() => updateDraft(f("bgImagePosition"), opt.value as any)}
                    aria-label={label}
                    className={cn(
                      "flex h-6 w-8 items-center justify-center rounded-nx-control border transition-colors duration-nx-micro ease-nx-enter focus-visible:shadow-nx-focus focus-visible:outline-none motion-reduce:transition-none",
                      bgImagePosition === opt.value
                        ? "border-nx-accent bg-nx-accent-wash text-nx-accent"
                        : "border-nx-line text-nx-ink-2 hover:border-nx-line-hi"
                    )}
                  >
                    <Icon className="h-3 w-3" aria-hidden="true" />
                  </button>
                );
              })}
            </div>
          </div>
        </>
      )}

      <div className="flex items-center justify-between">
        <span className="text-[10px] font-medium text-nx-ink-3">
          {t("studio.background.overlay")}
        </span>
        <Switch
          checked={bgOverlayEnabled}
          onCheckedChange={(v) => updateDraft(f("bgOverlayEnabled"), v as any)}
        />
      </div>
      {bgOverlayEnabled && (
        <>
          <ColorInput
            label={t("studio.background.overlayColor")}
            value={bgOverlayColor}
            onChange={(v) => updateDraft(f("bgOverlayColor"), v as any)}
          />
          <SliderInput
            label={t("studio.background.overlayOpacity")}
            value={bgOverlayOpacity}
            min={0}
            max={1}
            step={0.05}
            unit=""
            onChange={(v) => updateDraft(f("bgOverlayOpacity"), v as any)}
          />
        </>
      )}
      <SliderInput
        label={t("studio.background.blur")}
        value={bgBlur}
        min={0}
        max={20}
        onChange={(v) => updateDraft(f("bgBlur"), v as any)}
      />
    </div>
  );
}

// ── PresetDots — also extracted as a stable component ──
function PresetDots({
  mode,
  onApply,
}: {
  mode: "light" | "dark";
  onApply: (c: Partial<StudioDraft>) => void;
}) {
  const { t } = useI18n();
  return (
    <div className="grid grid-cols-3 gap-1.5">
      {COLOR_PRESETS.map((preset, i) => {
        const dots =
          mode === "light"
            ? [preset.colors.primaryColor, preset.colors.bgColor, preset.colors.surfaceColor]
            : [
                preset.colors.darkPrimaryColor,
                preset.colors.darkBgColor,
                preset.colors.darkSurfaceColor,
              ];
        return (
          <button
            key={i}
            type="button"
            onClick={() => onApply(preset.colors)}
            className="flex flex-col items-center gap-1 rounded-nx-md border border-nx-line p-1.5 transition-colors duration-nx-micro ease-nx-enter hover:border-nx-line-hi hover:bg-nx-hover focus-visible:shadow-nx-focus focus-visible:outline-none motion-reduce:transition-none"
          >
            <div className="flex gap-0.5">
              {dots.map((c, ci) => (
                <div
                  key={ci}
                  className="h-3 w-3 rounded-full border border-nx-line"
                  style={{ backgroundColor: c }}
                />
              ))}
            </div>
            <span className="text-[9px] text-nx-ink-3">{t(preset.labelKey)}</span>
          </button>
        );
      })}
    </div>
  );
}

/**
 * Presentation UI component rendering the style panel.
 * Arranges layout boundaries and accessibility targets (WCAG, tab index) using the core design library (@core/ui/*). Coordinates text fields, submit indicators, and validation warning messages.
 */
export function StylePanel({
  activeSection,
  draft,
  updateDraft,
  batchUpdateDraft,
}: StylePanelProps) {
  const { t } = useI18n();

  // ══════════════════════════════════════════════════════
  // APPEARANCE (merged Colors + Background)
  // ══════════════════════════════════════════════════════
  if (activeSection === "appearance") {
    const layoutInfo = LAYOUT_SECTION_MAP[draft.layout] || { sections: 1 };
    const sectionCount = layoutInfo.sections;
    const isMultiSection = sectionCount > 1;
    const sectionLabels = layoutInfo.labels || ["formSide", "brandingPanel"];

    const lightPresetKeys: (keyof StudioDraft)[] = [
      "primaryColor",
      "secondaryColor",
      "bgColor",
      "surfaceColor",
      "textColor",
      "mutedColor",
      "borderColor",
      "errorColor",
      "successColor",
    ];
    const darkPresetKeys: (keyof StudioDraft)[] = [
      "darkPrimaryColor",
      "darkSecondaryColor",
      "darkBgColor",
      "darkSurfaceColor",
      "darkTextColor",
      "darkMutedColor",
      "darkBorderColor",
      "darkErrorColor",
      "darkSuccessColor",
    ];

    const applyPreset = (presetColors: Partial<StudioDraft>, keys: (keyof StudioDraft)[]) => {
      const filtered: Partial<StudioDraft> = {};
      for (const key of keys) {
        if (key in presetColors) (filtered as any)[key] = (presetColors as any)[key];
      }
      batchUpdateDraft(filtered);
    };

    // ── Section label helper ──
    const sectionLabel = (idx: 0 | 1) => {
      const key = sectionLabels[idx];
      return t(`studio.background.${key}`);
    };

    return (
      <div className="space-y-5">
        {/* ─── SECTION MODE (multi-section layouts only) ─── */}
        {isMultiSection && (
          <div className="space-y-2 rounded-nx-md border border-nx-line bg-nx-raised p-3">
            <div className="flex items-center justify-between">
              <h4 className="flex items-center gap-1.5 text-[11px] font-semibold uppercase tracking-wider text-nx-ink-3">
                <Ruler className="h-3.5 w-3.5" aria-hidden="true" />
                {t("studio.background.panelBg")}
              </h4>
              <span className="rounded-full bg-nx-accent-wash px-2 py-0.5 text-[9px] font-bold text-nx-accent">
                {sectionCount} {t("studio.background.sectionCount")}
              </span>
            </div>
            <div className="grid grid-cols-2 gap-1.5">
              {(["unified", "independent"] as const).map((mode) => (
                <button
                  key={mode}
                  type="button"
                  onClick={() => updateDraft("splitBgMode", mode)}
                  className={cn(
                    "h-7 rounded-nx-control border text-[10px] font-medium transition-colors duration-nx-micro ease-nx-enter focus-visible:shadow-nx-focus focus-visible:outline-none motion-reduce:transition-none",
                    draft.splitBgMode === mode
                      ? "border-nx-accent bg-nx-accent-wash text-nx-accent"
                      : "border-nx-line text-nx-ink-2 hover:border-nx-line-hi"
                  )}
                >
                  {mode === "unified"
                    ? t("studio.background.panelSame")
                    : t("studio.background.panelIndependent")}
                </button>
              ))}
            </div>
            <p className="text-[10px] text-nx-ink-3">
              {draft.splitBgMode === "unified"
                ? t("studio.background.panelSameDesc")
                : `${sectionLabel(0)} + ${sectionLabel(1)} — ${t("studio.background.panelIndependentDesc")}`}
            </p>
          </div>
        )}

        {/* ═══════════════ LIGHT THEME ═══════════════ */}
        <div className="space-y-3 rounded-nx-md border border-nx-line bg-gradient-to-b from-warning/10 to-transparent p-3">
          <h4 className="flex items-center gap-1.5 text-[11px] font-semibold uppercase tracking-wider text-nx-ink-3">
            <Sun className="h-3.5 w-3.5" aria-hidden="true" />
            {t("studio.appearance.lightTheme")}
          </h4>

          {/* Light Presets */}
          <div className="space-y-1.5">
            <h5 className="text-[10px] font-semibold uppercase tracking-wider text-nx-ink-3">
              {t("studio.colors.presets")}
            </h5>
            <PresetDots mode="light" onApply={(c) => applyPreset(c, lightPresetKeys)} />
          </div>

          {/* Light Page Background — shows as "Full Page" if unified/1-section, as section label if separated */}
          <div className="space-y-2 border-t border-nx-line pt-3">
            <h5 className="flex items-center gap-1.5 text-[10px] font-semibold uppercase tracking-wider text-nx-ink-3">
              {isMultiSection && draft.splitBgMode === "independent" ? (
                <>
                  <Square className="h-3 w-3" aria-hidden="true" />
                  {sectionLabel(0)}
                </>
              ) : (
                <>
                  <Globe className="h-3 w-3" aria-hidden="true" />
                  {t("studio.background.fullPage")}
                </>
              )}
            </h5>
            <BgControls
              prefix=""
              bgType={draft.bgType}
              bgColor={draft.bgColor}
              bgGradientDirection={draft.bgGradientDirection}
              bgGradientFrom={draft.bgGradientFrom}
              bgGradientTo={draft.bgGradientTo}
              bgImageUrl={draft.bgImageUrl}
              bgImageFit={draft.bgImageFit}
              bgImagePosition={draft.bgImagePosition}
              bgOverlayEnabled={draft.bgOverlayEnabled}
              bgOverlayColor={draft.bgOverlayColor}
              bgOverlayOpacity={draft.bgOverlayOpacity}
              bgBlur={draft.bgBlur}
              updateDraft={updateDraft}
            />
          </div>

          {/* Light Color Palette */}
          <div className="space-y-2 border-t border-nx-line pt-3">
            <h5 className="flex items-center gap-1.5 text-[10px] font-semibold uppercase tracking-wider text-nx-ink-3">
              <Palette className="h-3 w-3" aria-hidden="true" />
              {t("studio.colors.lightPalette")}
            </h5>
            <ColorInput
              label={t("studio.colors.primary")}
              value={draft.primaryColor}
              onChange={(v) => updateDraft("primaryColor", v)}
            />
            <ColorInput
              label={t("studio.colors.secondary")}
              value={draft.secondaryColor}
              onChange={(v) => updateDraft("secondaryColor", v)}
            />
            <ColorInput
              label={t("studio.colors.surface")}
              value={draft.surfaceColor}
              onChange={(v) => updateDraft("surfaceColor", v)}
            />
            <ColorInput
              label={t("studio.colors.text")}
              value={draft.textColor}
              onChange={(v) => updateDraft("textColor", v)}
            />
            <ColorInput
              label={t("studio.colors.muted")}
              value={draft.mutedColor}
              onChange={(v) => updateDraft("mutedColor", v)}
            />
            <ColorInput
              label={t("studio.colors.border")}
              value={draft.borderColor}
              onChange={(v) => updateDraft("borderColor", v)}
            />
            <ColorInput
              label={t("studio.colors.error")}
              value={draft.errorColor}
              onChange={(v) => updateDraft("errorColor", v)}
            />
            <ColorInput
              label={t("studio.colors.success")}
              value={draft.successColor}
              onChange={(v) => updateDraft("successColor", v)}
            />
          </div>

          {/* Light Section 2 Bg (multi-section + independent only) */}
          {isMultiSection && draft.splitBgMode === "independent" && (
            <div className="space-y-2 border-t border-nx-line pt-3">
              <h5 className="flex items-center gap-1.5 text-[10px] font-semibold uppercase tracking-wider text-nx-ink-3">
                <ImageIcon className="h-3 w-3" aria-hidden="true" />
                {sectionLabel(1)}
              </h5>
              <BgControls
                prefix="panelBg"
                bgType={draft.panelBgType}
                bgColor={draft.panelBgColor}
                bgGradientDirection={draft.panelBgGradientDirection}
                bgGradientFrom={draft.panelBgGradientFrom}
                bgGradientTo={draft.panelBgGradientTo}
                bgImageUrl={draft.panelBgImageUrl}
                bgImageFit={draft.panelBgImageFit}
                bgImagePosition={draft.panelBgImagePosition}
                bgOverlayEnabled={draft.panelBgOverlayEnabled}
                bgOverlayColor={draft.panelBgOverlayColor}
                bgOverlayOpacity={draft.panelBgOverlayOpacity}
                bgBlur={draft.panelBgBlur}
                updateDraft={updateDraft}
              />
            </div>
          )}
        </div>

        {/* ═══════════════ DARK THEME ═══════════════ */}
        <div className="space-y-3 rounded-nx-md border border-nx-line bg-gradient-to-b from-info/10 to-transparent p-3">
          <h4 className="flex items-center gap-1.5 text-[11px] font-semibold uppercase tracking-wider text-nx-ink-3">
            <Moon className="h-3.5 w-3.5" aria-hidden="true" />
            {t("studio.appearance.darkTheme")}
          </h4>

          {/* Dark Presets */}
          <div className="space-y-1.5">
            <h5 className="text-[10px] font-semibold uppercase tracking-wider text-nx-ink-3">
              {t("studio.colors.presets")}
            </h5>
            <PresetDots mode="dark" onApply={(c) => applyPreset(c, darkPresetKeys)} />
          </div>

          {/* Dark Page Background */}
          <div className="space-y-2 border-t border-nx-line pt-3">
            <h5 className="flex items-center gap-1.5 text-[10px] font-semibold uppercase tracking-wider text-nx-ink-3">
              {isMultiSection && draft.splitBgMode === "independent" ? (
                <>
                  <Square className="h-3 w-3" aria-hidden="true" />
                  {sectionLabel(0)}
                </>
              ) : (
                <>
                  <Globe className="h-3 w-3" aria-hidden="true" />
                  {t("studio.background.fullPage")}
                </>
              )}
            </h5>
            <BgControls
              prefix="darkBg"
              bgType={draft.darkBgType}
              bgColor={draft.darkBgColor}
              bgGradientDirection={draft.darkBgGradientDirection}
              bgGradientFrom={draft.darkBgGradientFrom}
              bgGradientTo={draft.darkBgGradientTo}
              bgImageUrl={draft.darkBgImageUrl}
              bgImageFit={draft.darkBgImageFit}
              bgImagePosition={draft.darkBgImagePosition}
              bgOverlayEnabled={draft.darkBgOverlayEnabled}
              bgOverlayColor={draft.darkBgOverlayColor}
              bgOverlayOpacity={draft.darkBgOverlayOpacity}
              bgBlur={draft.darkBgBlur}
              copyFromLightUrl={draft.bgImageUrl || undefined}
              updateDraft={updateDraft}
            />
          </div>

          {/* Dark Color Palette */}
          <div className="space-y-2 border-t border-nx-line pt-3">
            <h5 className="flex items-center gap-1.5 text-[10px] font-semibold uppercase tracking-wider text-nx-ink-3">
              <Palette className="h-3 w-3" aria-hidden="true" />
              {t("studio.colors.darkPalette")}
            </h5>
            <ColorInput
              label={t("studio.colors.primary")}
              value={draft.darkPrimaryColor}
              onChange={(v) => updateDraft("darkPrimaryColor", v)}
            />
            <ColorInput
              label={t("studio.colors.secondary")}
              value={draft.darkSecondaryColor}
              onChange={(v) => updateDraft("darkSecondaryColor", v)}
            />
            <ColorInput
              label={t("studio.colors.surface")}
              value={draft.darkSurfaceColor}
              onChange={(v) => updateDraft("darkSurfaceColor", v)}
            />
            <ColorInput
              label={t("studio.colors.text")}
              value={draft.darkTextColor}
              onChange={(v) => updateDraft("darkTextColor", v)}
            />
            <ColorInput
              label={t("studio.colors.muted")}
              value={draft.darkMutedColor}
              onChange={(v) => updateDraft("darkMutedColor", v)}
            />
            <ColorInput
              label={t("studio.colors.border")}
              value={draft.darkBorderColor}
              onChange={(v) => updateDraft("darkBorderColor", v)}
            />
            <ColorInput
              label={t("studio.colors.error")}
              value={draft.darkErrorColor}
              onChange={(v) => updateDraft("darkErrorColor", v)}
            />
            <ColorInput
              label={t("studio.colors.success")}
              value={draft.darkSuccessColor}
              onChange={(v) => updateDraft("darkSuccessColor", v)}
            />
          </div>

          {/* Dark Section 2 Bg (multi-section + independent only) */}
          {isMultiSection && draft.splitBgMode === "independent" && (
            <div className="space-y-2 border-t border-nx-line pt-3">
              <h5 className="flex items-center gap-1.5 text-[10px] font-semibold uppercase tracking-wider text-nx-ink-3">
                <ImageIcon className="h-3 w-3" aria-hidden="true" />
                {sectionLabel(1)}
              </h5>
              <BgControls
                prefix="darkPanelBg"
                bgType={draft.darkPanelBgType}
                bgColor={draft.darkPanelBgColor}
                bgGradientDirection={draft.darkPanelBgGradientDirection}
                bgGradientFrom={draft.darkPanelBgGradientFrom}
                bgGradientTo={draft.darkPanelBgGradientTo}
                bgImageUrl={draft.darkPanelBgImageUrl}
                bgImageFit={draft.darkPanelBgImageFit}
                bgImagePosition={draft.darkPanelBgImagePosition}
                bgOverlayEnabled={draft.darkPanelBgOverlayEnabled}
                bgOverlayColor={draft.darkPanelBgOverlayColor}
                bgOverlayOpacity={draft.darkPanelBgOverlayOpacity}
                bgBlur={draft.darkPanelBgBlur}
                copyFromLightUrl={draft.panelBgImageUrl || undefined}
                updateDraft={updateDraft}
              />
            </div>
          )}
        </div>
      </div>
    );
  }

  // ══════════════════════════════════════════════════════
  // TYPOGRAPHY
  // ══════════════════════════════════════════════════════
  if (activeSection === "typography") {
    return (
      <div className="space-y-5">
        {/* Body Font (English) */}
        <div className="space-y-1.5">
          <label className="text-[11px] font-semibold uppercase tracking-wider text-nx-ink-3">
            {t("studio.typography.fontFamily")}
          </label>
          <Select value={draft.fontFamily} onValueChange={(v) => updateDraft("fontFamily", v)}>
            <SelectTrigger className="h-9 text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {FONT_OPTIONS_EN.map((font) => (
                <SelectItem
                  key={font}
                  value={font}
                  className="text-xs"
                  style={{ fontFamily: font }}
                >
                  {font}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {/* Body Font (Arabic) */}
        <div className="space-y-1.5">
          <label className="text-[11px] font-semibold uppercase tracking-wider text-nx-ink-3">
            {t("studio.typography.fontFamilyAr")}
          </label>
          <Select value={draft.fontFamilyAr} onValueChange={(v) => updateDraft("fontFamilyAr", v)}>
            <SelectTrigger className="h-9 text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {FONT_OPTIONS_AR.map((font) => (
                <SelectItem
                  key={font}
                  value={font}
                  className="text-xs"
                  style={{ fontFamily: font }}
                >
                  {font}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {/* Heading Font */}
        <div className="space-y-1.5">
          <label className="text-[11px] font-semibold uppercase tracking-wider text-nx-ink-3">
            {t("studio.typography.headingFont")}
          </label>
          <Select
            value={draft.headingFont || draft.fontFamily}
            onValueChange={(v) => updateDraft("headingFont", v)}
          >
            <SelectTrigger className="h-9 text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {FONT_OPTIONS_EN.map((font) => (
                <SelectItem
                  key={font}
                  value={font}
                  className="text-xs"
                  style={{ fontFamily: font }}
                >
                  {font}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {/* Heading Size */}
        <SliderInput
          label={t("studio.typography.headingSize")}
          value={draft.headingSize}
          min={20}
          max={56}
          onChange={(v) => updateDraft("headingSize", v)}
        />

        {/* Body Size */}
        <SliderInput
          label={t("studio.typography.bodySize")}
          value={draft.bodySize}
          min={10}
          max={22}
          onChange={(v) => updateDraft("bodySize", v)}
        />

        {/* Heading Weight */}
        <SliderInput
          label={t("studio.typography.headingWeight")}
          value={draft.headingWeight}
          min={300}
          max={900}
          step={100}
          onChange={(v) => updateDraft("headingWeight", v)}
        />

        {/* Body Weight */}
        <SliderInput
          label={t("studio.typography.bodyWeight")}
          value={draft.bodyWeight}
          min={300}
          max={700}
          step={100}
          onChange={(v) => updateDraft("bodyWeight", v)}
        />

        {/* Line Height */}
        <SliderInput
          label={t("studio.typography.lineHeight")}
          value={draft.lineHeight}
          min={1}
          max={2.5}
          step={0.1}
          unit=""
          onChange={(v) => updateDraft("lineHeight", v)}
        />

        {/* Letter Spacing */}
        <SliderInput
          label={t("studio.typography.letterSpacing")}
          value={draft.letterSpacing}
          min={-2}
          max={4}
          step={0.5}
          unit="px"
          onChange={(v) => updateDraft("letterSpacing", v)}
        />
      </div>
    );
  }

  // ══════════════════════════════════════════════════════
  // SPACING & SHAPE
  // ══════════════════════════════════════════════════════
  if (activeSection === "spacing") {
    return (
      <div className="space-y-5">
        <SliderInput
          label={t("studio.spacing.borderRadius")}
          value={draft.borderRadius}
          min={0}
          max={24}
          onChange={(v) => updateDraft("borderRadius", v)}
        />
        <SliderInput
          label={t("studio.spacing.formWidth")}
          value={draft.formWidth}
          min={320}
          max={560}
          step={10}
          onChange={(v) => updateDraft("formWidth", v)}
        />
        <SliderInput
          label={t("studio.spacing.cardPadding")}
          value={draft.cardPadding}
          min={16}
          max={48}
          step={4}
          onChange={(v) => updateDraft("cardPadding", v)}
        />
        <SliderInput
          label={t("studio.spacing.elementGap")}
          value={draft.elementGap}
          min={8}
          max={32}
          step={4}
          onChange={(v) => updateDraft("elementGap", v)}
        />
        <SliderInput
          label={t("studio.spacing.inputHeight")}
          value={draft.inputHeight}
          min={36}
          max={52}
          step={2}
          onChange={(v) => updateDraft("inputHeight", v)}
        />
        <SliderInput
          label={t("studio.spacing.btnRadius")}
          value={draft.btnRadius}
          min={0}
          max={24}
          onChange={(v) => updateDraft("btnRadius", v)}
        />
        <div className="space-y-1.5">
          <label className="text-[11px] font-semibold uppercase tracking-wider text-nx-ink-3">
            {t("studio.spacing.btnSize")}
          </label>
          <div className="grid grid-cols-3 gap-1.5">
            {(["sm", "md", "lg"] as const).map((size) => (
              <button
                key={size}
                type="button"
                onClick={() => updateDraft("btnSize", size)}
                className={cn(
                  "h-8 rounded-nx-control border text-xs font-medium transition-colors duration-nx-micro ease-nx-enter focus-visible:shadow-nx-focus focus-visible:outline-none motion-reduce:transition-none",
                  draft.btnSize === size
                    ? "border-nx-accent bg-nx-accent-wash text-nx-accent"
                    : "border-nx-line text-nx-ink-2 hover:border-nx-line-hi"
                )}
              >
                {size.toUpperCase()}
              </button>
            ))}
          </div>
        </div>
      </div>
    );
  }

  return null;
}

// UI-EXCEPTION: compact studio layout
/**
 * BuilderCanvas — The main DnD canvas for the page builder
 *
 * Dual-mode canvas supporting both:
 *   - **Absolute (free-form)**: Components positioned via x/y pixel coordinates (DEFAULT)
 *   - **Grid**: Components positioned via CSS Grid columns/rows (fallback)
 *
 * Features:
 *   - Snap grid overlay (8px, toggleable)
 *   - Zoom controls (50% → 200%)
 *   - Drop zones for palette → canvas drag
 *   - Position mode toggle
 *   - Overlap detection warnings
 *
 * This is the STUDIO-SIDE canvas (not the preview iframe).
 */
"use client";

import { useDroppable } from "@dnd-kit/core";
import { SortableContext, rectSortingStrategy } from "@dnd-kit/sortable";
import { cn } from "@/core/common/utils";
import { useI18n } from "@core/providers/i18n-provider";
import { Grid3X3, Move, ZoomIn, ZoomOut, Magnet, AlertTriangle } from "lucide-react";
import type { CanvasComponent, PositionMode } from "../../../domain/entities/CanvasComponent";
import {
  CANVAS_GRID_COLUMNS,
  CANVAS_WIDTH,
  CANVAS_HEIGHT,
  SNAP_GRID_SIZE,
} from "../../../domain/entities/CanvasComponent";
import { GridOverlay } from "./GridOverlay";
import { DraggableCanvasItem } from "./DraggableCanvasItem";

/** Parse "N / M" grid string → starting position number */
function parseGridStart(span: string): number {
  const match = span.match(/(\d+)/);
  return match ? parseInt(match[1], 10) : 1;
}

/**
 * Sort components by grid position (row first, then column) for grid mode.
 * This ensures SortableContext items match the visual DOM order,
 * which is critical for dnd-kit's rectSortingStrategy to work correctly.
 */
function sortByGridPosition(components: CanvasComponent[]): CanvasComponent[] {
  return [...components].sort((a, b) => {
    const rowA = parseGridStart(a.gridRow);
    const rowB = parseGridStart(b.gridRow);
    if (rowA !== rowB) return rowA - rowB;
    const colA = parseGridStart(a.gridColumn);
    const colB = parseGridStart(b.gridColumn);
    return colA - colB;
  });
}

interface BuilderCanvasProps {
  components: CanvasComponent[];
  selectedComponentId: string | null;
  canvasGridRows: number;
  snapToGrid: boolean;
  positionMode: PositionMode;
  zoom: number;
  overlappingIds: Set<string>;
  onSelectComponent: (id: string | null) => void;
  onSetPositionMode: (mode: PositionMode) => void;
  onSetZoom: (zoom: number) => void;
  onSetSnapToGrid: (snap: boolean) => void;
  /** When true, renders at full available width (outside sidebar) */
  fullWidth?: boolean;
}

const ZOOM_STEPS = [50, 75, 100, 125, 150, 200];

export function BuilderCanvas({
  components,
  selectedComponentId,
  canvasGridRows,
  snapToGrid,
  positionMode,
  zoom,
  overlappingIds,
  onSelectComponent,
  onSetPositionMode,
  onSetZoom,
  onSetSnapToGrid,
  fullWidth = false,
}: BuilderCanvasProps) {
  const { t } = useI18n();
  const { setNodeRef, isOver } = useDroppable({ id: "builder-canvas" });
  const scale = zoom / 100;

  const nextZoom = () => {
    const idx = ZOOM_STEPS.indexOf(zoom);
    if (idx < ZOOM_STEPS.length - 1) onSetZoom(ZOOM_STEPS[idx + 1]);
  };
  const prevZoom = () => {
    const idx = ZOOM_STEPS.indexOf(zoom);
    if (idx > 0) onSetZoom(ZOOM_STEPS[idx - 1]);
  };

  const isAbsolute = positionMode === "absolute";

  return (
    <div className={cn("flex flex-col gap-2", fullWidth ? "h-full w-full" : "w-full")}>
      {/* ── Toolbar ── */}
      <div className="flex items-center justify-between gap-2 px-1">
        {/* Position mode toggle */}
        <div className="flex items-center gap-1 rounded-nx-control bg-nx-raised p-0.5">
          {/* UI-EXCEPTION: compact studio layout */}
          <button
            onClick={() => onSetPositionMode("absolute")}
            className={cn(
              "flex items-center gap-1.5 rounded-nx-sm px-2.5 py-1 text-[11px] font-medium transition-[color,background-color,box-shadow] duration-nx-micro ease-nx-enter focus-visible:shadow-nx-focus focus-visible:outline-none motion-reduce:transition-none",
              isAbsolute
                ? "bg-nx-surface text-nx-ink shadow-nx-sm"
                : "text-nx-ink-3 hover:text-nx-ink-2"
            )}
            title={t("studio.builder.freeForm")}
          >
            <Move className="h-3 w-3" aria-hidden="true" />
            <span>{t("studio.builder.freeForm")}</span>
          </button>
          <button
            onClick={() => onSetPositionMode("grid")}
            className={cn(
              "flex items-center gap-1.5 rounded-nx-sm px-2.5 py-1 text-[11px] font-medium transition-[color,background-color,box-shadow] duration-nx-micro ease-nx-enter focus-visible:shadow-nx-focus focus-visible:outline-none motion-reduce:transition-none",
              !isAbsolute
                ? "bg-nx-surface text-nx-ink shadow-nx-sm"
                : "text-nx-ink-3 hover:text-nx-ink-2"
            )}
            title={t("studio.builder.grid")}
          >
            <Grid3X3 className="h-3 w-3" aria-hidden="true" />
            <span>{t("studio.builder.grid")}</span>
          </button>
        </div>

        {/* Right controls: snap + zoom */}
        <div className="flex items-center gap-2">
          {/* Snap toggle */}
          <button
            onClick={() => onSetSnapToGrid(!snapToGrid)}
            className={cn(
              "flex items-center gap-1 rounded-nx-sm px-2 py-1 text-[11px] transition-colors duration-nx-micro ease-nx-enter focus-visible:shadow-nx-focus focus-visible:outline-none motion-reduce:transition-none",
              snapToGrid ? "bg-nx-accent-wash text-nx-accent" : "text-nx-ink-3 hover:text-nx-ink-2"
            )}
            title={t("studio.builder.snapToGrid")}
          >
            <Magnet className="h-3 w-3" aria-hidden="true" />
            <span className="hidden tabular-nums sm:inline">{SNAP_GRID_SIZE}px</span>
          </button>

          {/* Zoom controls */}
          <div className="flex items-center gap-0.5 rounded-nx-sm bg-nx-raised">
            <button
              onClick={prevZoom}
              disabled={zoom <= ZOOM_STEPS[0]}
              className="flex h-6 w-6 items-center justify-center rounded-s-nx-sm transition-colors duration-nx-micro ease-nx-enter hover:bg-nx-hover focus-visible:shadow-nx-focus focus-visible:outline-none disabled:pointer-events-none disabled:text-nx-ink-3 motion-reduce:transition-none"
              aria-label={t("studio.builder.zoomOut")}
            >
              <ZoomOut className="h-3 w-3" aria-hidden="true" />
            </button>
            <span className="w-8 text-center font-mono text-[10px] tabular-nums text-nx-ink-3">
              {zoom}%
            </span>
            <button
              onClick={nextZoom}
              disabled={zoom >= ZOOM_STEPS[ZOOM_STEPS.length - 1]}
              className="flex h-6 w-6 items-center justify-center rounded-e-nx-sm transition-colors duration-nx-micro ease-nx-enter hover:bg-nx-hover focus-visible:shadow-nx-focus focus-visible:outline-none disabled:pointer-events-none disabled:text-nx-ink-3 motion-reduce:transition-none"
              aria-label={t("studio.builder.zoomIn")}
            >
              <ZoomIn className="h-3 w-3" aria-hidden="true" />
            </button>
          </div>
        </div>
      </div>

      {/* Overlap warning */}
      {overlappingIds.size > 0 && (
        <div className="flex items-center gap-1.5 rounded-nx-sm bg-destructive/10 px-2 py-1 text-[11px] text-destructive">
          <AlertTriangle className="h-3 w-3 flex-shrink-0" aria-hidden="true" />
          <span>{t("studio.builder.overlapCount", { count: overlappingIds.size / 2 })}</span>
        </div>
      )}

      {/* ── Canvas container (scrollable + zoomable) ── */}
      <div className="overflow-auto rounded-nx-lg border border-nx-line bg-nx-ground">
        <div
          style={{
            transform: `scale(${scale})`,
            transformOrigin: "top left",
            width: isAbsolute ? `${CANVAS_WIDTH}px` : undefined,
            minHeight: isAbsolute ? `${CANVAS_HEIGHT}px` : undefined,
          }}
        >
          <div
            ref={setNodeRef}
            className={cn(
              "relative overflow-hidden rounded-nx-lg border-2 border-dashed transition-[border-color,background-color] duration-nx-micro ease-nx-enter motion-reduce:transition-none",
              isOver ? "border-nx-accent bg-nx-accent-wash" : "border-nx-line bg-nx-raised"
            )}
            onClick={(e) => {
              if (e.target === e.currentTarget || (e.target as HTMLElement).dataset.canvasArea) {
                onSelectComponent(null);
              }
            }}
            style={{
              minHeight: isAbsolute ? `${CANVAS_HEIGHT}px` : `${canvasGridRows * 60}px`,
              width: isAbsolute ? `${CANVAS_WIDTH}px` : undefined,
            }}
          >
            {/* Grid Overlay */}
            <GridOverlay gridRows={canvasGridRows} show={snapToGrid && !isAbsolute} />

            {/* Snap grid for free-form mode */}
            {snapToGrid && isAbsolute && (
              <div
                aria-hidden="true"
                className="pointer-events-none absolute inset-0 z-0 opacity-[0.04]"
                style={{
                  backgroundImage: `
                    linear-gradient(to right, currentColor 1px, transparent 1px),
                    linear-gradient(to bottom, currentColor 1px, transparent 1px)
                  `,
                  backgroundSize: `${SNAP_GRID_SIZE}px ${SNAP_GRID_SIZE}px`,
                }}
              />
            )}

            {/* Column number labels (top) — grid mode only */}
            {snapToGrid && !isAbsolute && (
              <div
                aria-hidden="true"
                className="pointer-events-none absolute end-0 start-0 top-0 z-10"
                style={{
                  display: "grid",
                  gridTemplateColumns: `repeat(${CANVAS_GRID_COLUMNS}, 1fr)`,
                  padding: "0 8px",
                }}
              >
                {Array.from({ length: CANVAS_GRID_COLUMNS }, (_, i) => (
                  <div
                    key={`col-label-${i}`}
                    className="flex h-5 items-center justify-center font-mono text-[8px] tabular-nums text-nx-ink-3"
                  >
                    {i + 1}
                  </div>
                ))}
              </div>
            )}

            {/* ── Absolute (free-form) mode ── */}
            {isAbsolute ? (
              <div
                className="relative z-20 w-full"
                data-canvas-area="true"
                style={{ minHeight: `${CANVAS_HEIGHT}px` }}
              >
                {components
                  .sort((a, b) => a.zIndex - b.zIndex)
                  .map((comp) => (
                    <DraggableCanvasItem
                      key={comp.id}
                      component={comp}
                      isSelected={selectedComponentId === comp.id}
                      isOverlapping={overlappingIds.has(comp.id)}
                      positionMode="absolute"
                      zoom={zoom}
                      onSelect={() => onSelectComponent(comp.id)}
                    />
                  ))}
              </div>
            ) : (
              /* ── Grid mode ── */
              (() => {
                // Sort by grid position (row start, then column start) so
                // the SortableContext items array matches the visual layout.
                const parseStart = (s: string) => parseInt(s.split("/")[0]?.trim(), 10) || 1;
                const gridSorted = [...components].sort((a, b) => {
                  const rowDiff = parseStart(a.gridRow) - parseStart(b.gridRow);
                  if (rowDiff !== 0) return rowDiff;
                  return parseStart(a.gridColumn) - parseStart(b.gridColumn);
                });
                return (
                  <SortableContext
                    items={gridSorted.map((c) => c.id)}
                    strategy={rectSortingStrategy}
                  >
                    <div
                      className="relative z-20 h-full w-full p-2"
                      style={{
                        display: "grid",
                        gridTemplateColumns: `repeat(${CANVAS_GRID_COLUMNS}, 1fr)`,
                        gridTemplateRows: `repeat(${canvasGridRows}, minmax(${fullWidth ? "1fr" : "60px"}, 1fr))`,
                        gap: "6px",
                        minHeight: fullWidth ? "100%" : `${canvasGridRows * 60}px`,
                        paddingTop: snapToGrid ? "20px" : "8px",
                      }}
                    >
                      {gridSorted.map((comp) => (
                        <DraggableCanvasItem
                          key={comp.id}
                          component={comp}
                          isSelected={selectedComponentId === comp.id}
                          isOverlapping={overlappingIds.has(comp.id)}
                          positionMode="grid"
                          zoom={zoom}
                          onSelect={() => onSelectComponent(comp.id)}
                        />
                      ))}
                    </div>
                  </SortableContext>
                );
              })()
            )}

            {/* Empty state */}
            {components.length === 0 && (
              <div className="absolute inset-0 z-30 flex items-center justify-center">
                <div className="text-center text-nx-ink-3">
                  <div className="mx-auto mb-3 flex h-12 w-12 items-center justify-center rounded-nx-lg bg-nx-raised">
                    <svg
                      className="h-6 w-6 text-nx-ink-3"
                      viewBox="0 0 24 24"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="1.5"
                      aria-hidden="true"
                    >
                      <rect x="3" y="3" width="18" height="18" rx="2" />
                      <line x1="3" y1="9" x2="21" y2="9" />
                      <line x1="9" y1="3" x2="9" y2="21" />
                    </svg>
                  </div>
                  <p className="text-sm font-medium text-nx-ink-2">
                    {t("studio.builder.canvas.empty")}
                  </p>
                  <p className="mt-1 text-xs text-nx-ink-3">
                    {t("studio.builder.canvas.emptyHint")}
                  </p>
                </div>
              </div>
            )}

            {/* Drop indicator overlay — static highlight, not a looping animation:
                isOver is a real, actively-held drag-hover state (not idle/decorative),
                but per motion doctrine only genuine loading states may loop, so this
                renders as a single steady highlight instead of an infinite pulse. */}
            {isOver && (
              <div
                aria-hidden="true"
                className="pointer-events-none absolute inset-0 z-40 rounded-nx-lg"
              >
                <div className="absolute inset-0 rounded-nx-lg border-2 border-nx-accent bg-nx-accent-wash" />
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

// UI-EXCEPTION: compact studio layout
/**
 * BuilderPanel — Main panel for the DnD page builder
 *
 * REBUILT: Canvas is now rendered OUTSIDE the sidebar (in CustomizerStudioView).
 * This panel only contains: toolbar, palette, layer list, and props panel.
 * DndContext wraps the entire builder experience (set in CustomizerStudioView).
 * DragOverlay + onDragEnd handlers are defined here but rendered at the
 * CustomizerStudioView level so palette→canvas drag works across the split.
 */
"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { cn } from "@/core/common/utils";
import { Input } from "@core/ui/input";
import { Label } from "@core/ui/label";
import { Button } from "@core/ui/button";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from "@core/ui/dialog";
import { Badge } from "@core/ui/badge";
import {
  Undo2,
  Redo2,
  RotateCcw,
  Rows3,
  Grid3X3,
  LayoutTemplate,
  ChevronDown,
  Save,
  AlertTriangle,
  Trash2,
} from "lucide-react";
import { useI18n } from "@core/providers/i18n-provider";
import { useBuilderStore } from "../../viewmodels/useBuilderStore";
import { BuilderPalette } from "./BuilderPalette";
import { BuilderCanvas } from "./BuilderCanvas";
import { BuilderPropsPanel } from "./BuilderPropsPanel";
import { ComponentOrderList } from "./ComponentOrderList";
import type {
  CanvasComponent,
  CanvasComponentType,
  CanvasBackground,
} from "../../../domain/entities/CanvasComponent";
import { layoutToTemplate, getAllLayoutTemplates } from "../../../domain/entities/LayoutTemplates";

// ── Grid Overlap Detection ──────────────────────────────
function parseGridRange(span: string): [number, number] {
  const parts = span.split("/").map((s) => parseInt(s.trim(), 10));
  return [parts[0] || 1, parts[1] || (parts[0] || 1) + 1];
}

interface OverlapWarning {
  a: string;
  b: string;
}

function detectOverlaps(components: CanvasComponent[]): OverlapWarning[] {
  const visible = components.filter((c) => c.visible);
  const warnings: OverlapWarning[] = [];
  for (let i = 0; i < visible.length; i++) {
    for (let j = i + 1; j < visible.length; j++) {
      const a = visible[i],
        b = visible[j];
      const [ac1, ac2] = parseGridRange(a.gridColumn);
      const [ar1, ar2] = parseGridRange(a.gridRow);
      const [bc1, bc2] = parseGridRange(b.gridColumn);
      const [br1, br2] = parseGridRange(b.gridRow);
      if (ac1 < bc2 && bc1 < ac2 && ar1 < br2 && br1 < ar2) {
        warnings.push({ a: a.type, b: b.type });
      }
    }
  }
  return warnings;
}

interface BuilderPanelProps {
  draft: {
    canvasComponents: CanvasComponent[];
    canvasGridRows: number;
    canvasBackground: CanvasBackground;
  };
  updateDraft: (field: any, value: any) => void;
  /** When true, only render sidebar content (palette/props/layers) — canvas is rendered externally */
  sidebarOnly?: boolean;
  /** Currently active auth page tab */
  activeAuthPage?: string;
}

export function BuilderPanel({
  draft,
  updateDraft,
  sidebarOnly = false,
  activeAuthPage,
}: BuilderPanelProps) {
  const { t } = useI18n();
  const store = useBuilderStore();
  const [showTemplates, setShowTemplates] = useState(false);
  const [saveDialogOpen, setSaveDialogOpen] = useState(false);
  const [templateName, setTemplateName] = useState("");
  const savedTemplates = store.savedTemplates;
  const [showSaved, setShowSaved] = useState(false);

  // Load saved templates on mount
  useEffect(() => {
    setTimeout(() => {
      store.loadSavedTemplates();
    }, 0);
  }, [store]);

  // Overlap detection
  const storeComponents = store.components;
  const overlapWarnings = useMemo(() => detectOverlaps(storeComponents), [storeComponents]);

  // ── Note: Builder initialization, page switching, and draft syncing are ALL ──
  // ── handled by CustomizerStudioView's SYNC effects. BuilderPanel is DISPLAY-ONLY. ──
  // ── DO NOT add store.initialize(), store.setActivePage(), or updateDraft() here ──
  // ── as they will conflict with the view's sync logic and cause cross-page leakage. ──

  // ── Keyboard Shortcuts ──
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === "z" && !e.shiftKey) {
        e.preventDefault();
        store.undo();
      }
      if ((e.ctrlKey || e.metaKey) && e.key === "z" && e.shiftKey) {
        e.preventDefault();
        store.redo();
      }
      if ((e.key === "Delete" || e.key === "Backspace") && store.selectedComponentId) {
        if (
          (e.target as HTMLElement).tagName === "INPUT" ||
          (e.target as HTMLElement).tagName === "TEXTAREA"
        )
          return;
        e.preventDefault();
        store.removeComponent(store.selectedComponentId);
      }
      if (e.key === "Escape") {
        store.selectComponent(null);
      }
    };

    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [store]);

  // Quick add from palette
  const handleQuickAdd = useCallback(
    (type: CanvasComponentType) => {
      store.addComponent(type);
    },
    [store]
  );

  // Selected component
  const selectedComponent = store.selectedComponentId
    ? store.components.find((c) => c.id === store.selectedComponentId) || null
    : null;

  const sidebarContent = (
    <div className="space-y-4">
      {/* Toolbar: Undo/Redo + Canvas Settings */}
      <div className="flex items-center gap-2 border-b border-nx-line pb-3">
        <Button
          variant="outline"
          size="sm"
          className="h-7 w-7 p-0"
          disabled={!store.canUndo}
          onClick={store.undo}
          title={`${t("studio.builder.undo")} (Ctrl+Z)`}
          aria-label={t("studio.builder.undo")}
        >
          <Undo2 className="h-3.5 w-3.5" aria-hidden="true" />
        </Button>
        <Button
          variant="outline"
          size="sm"
          className="h-7 w-7 p-0"
          disabled={!store.canRedo}
          onClick={store.redo}
          title={`${t("studio.builder.redo")} (Ctrl+Shift+Z)`}
          aria-label={t("studio.builder.redo")}
        >
          <Redo2 className="h-3.5 w-3.5" aria-hidden="true" />
        </Button>

        <div className="flex-1" />

        {/* Snap to grid toggle */}
        <Button
          variant={store.snapToGrid ? "default" : "outline"}
          size="sm"
          className="h-7 gap-1 px-2 text-xs"
          onClick={() => store.setSnapToGrid(!store.snapToGrid)}
          title={t("studio.builder.canvas.snap")}
          aria-label={t("studio.builder.canvas.snap")}
        >
          <Grid3X3 className="h-3 w-3" aria-hidden="true" />
        </Button>

        {/* Reset */}
        <Button
          variant="outline"
          size="sm"
          className="h-7 w-7 p-0 text-nx-ink-3 hover:text-nx-danger"
          onClick={store.reset}
          title={t("studio.builder.reset")}
          aria-label={t("studio.builder.reset")}
        >
          <RotateCcw className="h-3.5 w-3.5" aria-hidden="true" />
        </Button>
      </div>

      {/* Canvas Grid Rows */}
      <div className="flex items-center gap-2">
        <Rows3 className="h-3.5 w-3.5 text-nx-ink-3" aria-hidden="true" />
        <Label className="flex-1 text-[10px] text-nx-ink-3">
          {t("studio.builder.canvas.rows")}
        </Label>
        <Input
          type="number"
          min={4}
          max={20}
          value={store.canvasGridRows}
          onChange={(e) => store.setCanvasGridRows(parseInt(e.target.value, 10) || 8)}
          className="h-7 w-16 text-center text-xs"
        />
      </div>

      {/* Inline Canvas (only when not sidebarOnly) */}
      {!sidebarOnly && (
        <BuilderCanvas
          components={store.components}
          selectedComponentId={store.selectedComponentId}
          canvasGridRows={store.canvasGridRows}
          snapToGrid={store.snapToGrid}
          positionMode={store.positionMode}
          zoom={store.zoom}
          overlappingIds={new Set(overlapWarnings.map((_, i) => `overlap_${i}`))} // Quick mock, not actually used here since sidebarOnly=false is rare now
          onSelectComponent={store.selectComponent}
          onSetPositionMode={store.setPositionMode}
          onSetZoom={store.setZoom}
          onSetSnapToGrid={store.setSnapToGrid}
        />
      )}

      {/* Component Order / Layer List */}
      <ComponentOrderList
        components={store.components}
        selectedComponentId={store.selectedComponentId}
        onSelectComponent={store.selectComponent}
        onToggleVisibility={store.toggleVisibility}
      />

      {/* Selected Component Props — shown right after layers for discoverability */}
      {selectedComponent && (
        <BuilderPropsPanel
          component={selectedComponent}
          positionMode={store.positionMode}
          onUpdate={(id, updates) => store.updateComponent(id, updates)}
          onUpdateProps={(id, props) => {
            const comp = store.components.find((c) => c.id === id);
            if (comp) {
              store.updateComponent(id, {
                props: { ...comp.props, ...props },
              });
            }
          }}
          onRemove={store.removeComponent}
          onDuplicate={store.duplicateComponent}
          onToggleVisibility={store.toggleVisibility}
          onReorderZ={store.reorderZ}
          onLock={store.lockComponent}
          onUnlock={store.unlockComponent}
          onResize={store.resizeComponent}
        />
      )}

      {/* Start from Template */}
      <div className="space-y-2">
        <Button
          variant="outline"
          size="sm"
          className="h-8 w-full gap-1.5 text-xs"
          onClick={() => setShowTemplates((p) => !p)}
          aria-expanded={showTemplates}
        >
          <LayoutTemplate className="h-3.5 w-3.5" aria-hidden="true" />
          {t("studio.builder.fromTemplate")}
          <ChevronDown
            className={cn(
              "ms-auto h-3 w-3 transition-transform duration-nx-micro ease-nx-enter motion-reduce:transition-none",
              showTemplates && "rotate-180"
            )}
            aria-hidden="true"
          />
        </Button>
        {showTemplates && (
          <div className="grid max-h-48 grid-cols-2 gap-1.5 overflow-y-auto rounded-nx-lg border border-nx-line bg-nx-raised p-2">
            {getAllLayoutTemplates().map(({ layout, label }) => (
              <button
                key={layout}
                className="truncate rounded-nx-sm border border-nx-line bg-nx-ground px-2 py-1.5 text-start text-[10px] font-medium text-nx-ink transition-colors duration-nx-micro ease-nx-enter hover:border-nx-accent hover:bg-nx-accent-wash focus-visible:shadow-nx-focus focus-visible:outline-none motion-reduce:transition-none"
                onClick={() => {
                  const tmpl = layoutToTemplate(layout);
                  store.loadTemplate(tmpl.components, tmpl.gridRows, tmpl.background);
                  setShowTemplates(false);
                }}
              >
                {t(
                  `studio.layout.${label.replace(/-([a-z])/g, (_, c: string) => c.toUpperCase())}`
                )}
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Save as Template + Saved Templates */}
      <div className="flex items-center gap-1.5">
        <Button
          variant="outline"
          size="sm"
          className="h-8 flex-1 gap-1.5 text-xs"
          onClick={() => {
            setTemplateName("");
            setSaveDialogOpen(true);
          }}
          disabled={store.components.length === 0}
        >
          <Save className="h-3.5 w-3.5" aria-hidden="true" />
          {t("studio.builder.saveTemplate")}
        </Button>
        {savedTemplates.length > 0 && (
          <Button
            variant="outline"
            size="sm"
            className="h-8 px-2 text-xs"
            onClick={() => setShowSaved((p) => !p)}
            aria-expanded={showSaved}
            aria-label={t("studio.builder.loadTemplate")}
          >
            <span className="tabular-nums">{savedTemplates.length}</span>
            <ChevronDown
              className={cn(
                "ms-0.5 h-3 w-3 transition-transform duration-nx-micro ease-nx-enter motion-reduce:transition-none",
                showSaved && "rotate-180"
              )}
              aria-hidden="true"
            />
          </Button>
        )}
      </div>

      {/* Saved Templates List */}
      {showSaved && savedTemplates.length > 0 && (
        <div className="max-h-36 space-y-1 overflow-y-auto rounded-nx-lg border border-nx-line bg-nx-raised p-2">
          {savedTemplates.map((tmpl) => (
            <div key={tmpl.id} className="flex items-center gap-2">
              <button
                className="flex-1 truncate rounded-nx-sm border border-nx-line bg-nx-ground px-2 py-1.5 text-start text-[10px] font-medium text-nx-ink transition-colors duration-nx-micro ease-nx-enter hover:border-nx-accent hover:bg-nx-accent-wash focus-visible:shadow-nx-focus focus-visible:outline-none motion-reduce:transition-none"
                onClick={() => {
                  store.loadTemplate(tmpl.components, tmpl.gridRows, tmpl.background);
                  setShowSaved(false);
                }}
              >
                {tmpl.name}
              </button>
              <button
                className="rounded-nx-sm p-1 text-nx-ink-3 transition-colors duration-nx-micro ease-nx-enter hover:text-nx-danger focus-visible:shadow-nx-focus focus-visible:outline-none motion-reduce:transition-none"
                onClick={() => {
                  store.deleteTemplate(tmpl.id);
                }}
                title={t("studio.builder.deleteTemplate")}
                aria-label={t("studio.builder.deleteTemplate")}
              >
                <Trash2 className="h-3 w-3" aria-hidden="true" />
              </button>
            </div>
          ))}
        </div>
      )}

      {/* Save Template Dialog */}
      <Dialog open={saveDialogOpen} onOpenChange={setSaveDialogOpen}>
        <DialogContent className="sm:max-w-[400px]">
          <DialogHeader>
            <DialogTitle>{t("studio.builder.saveTemplate")}</DialogTitle>
            <DialogDescription>{t("studio.builder.saveTemplateDesc")}</DialogDescription>
          </DialogHeader>
          <div className="space-y-2 py-2">
            <Label htmlFor="template-name" className="text-xs">
              {t("studio.builder.templateName")}
            </Label>
            <Input
              id="template-name"
              value={templateName}
              onChange={(e) => setTemplateName(e.target.value)}
              placeholder={t("studio.builder.templateNamePlaceholder")}
              className="h-8 text-sm"
              autoFocus
            />
          </div>
          <DialogFooter>
            <Button variant="outline" size="sm" onClick={() => setSaveDialogOpen(false)}>
              {t("common.cancel")}
            </Button>
            <Button
              size="sm"
              disabled={!templateName.trim()}
              onClick={() => {
                store.saveTemplate(templateName);
                setSaveDialogOpen(false);
              }}
            >
              <Save className="me-1 h-3.5 w-3.5" aria-hidden="true" />
              {t("common.save")}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Responsive Validation Warnings */}
      {overlapWarnings.length > 0 && (
        <div className="space-y-1.5 rounded-nx-lg border border-warning/30 bg-warning/5 p-2.5">
          <div className="flex items-center gap-1.5 text-warning">
            <AlertTriangle className="h-3.5 w-3.5" aria-hidden="true" />
            <span className="text-xs font-semibold">{t("studio.builder.validationWarnings")}</span>
            <Badge
              variant="outline"
              className="ms-auto h-4 border-warning/30 px-1 text-[10px] tabular-nums"
            >
              {overlapWarnings.length}
            </Badge>
          </div>
          {overlapWarnings.map((w, i) => (
            <p key={i} className="ps-5 text-[10px] text-warning/80">
              {t("studio.builder.overlapPair", { a: w.a, b: w.b })}
            </p>
          ))}
        </div>
      )}

      {/* Component Palette */}
      <BuilderPalette
        components={store.components}
        onQuickAdd={handleQuickAdd}
        activeAuthPage={activeAuthPage}
      />
    </div>
  );

  // DndContext is now at CustomizerStudioView level (wraps both sidebar + canvas)
  return sidebarContent;
}

// UI-EXCEPTION: compact studio layout
/**
 * Builder Components Index — All 14 canvas component renderers
 *
 * These are preview-side renderers used by CanvasRenderer inside
 * the LoginPreviewShell iframe. They consume CSS design tokens
 * from the studio for consistent styling.
 *
 * NOTE: These render in the PREVIEW iframe, not the studio sidebar.
 * They produce the actual visual output the admin sees.
 */
"use client";

import { useResolvedFileUrl } from "@core/hooks/use-resolved-file-url";
import { sanitizeCss, sanitizeRichHtml } from "@core/common/sanitize";
import { useI18n } from "@core/providers/i18n-provider";

import { Button } from "@core/ui/button";
import { Input } from "@core/ui/input";
import { Label } from "@core/ui/label";
import {
  Eye,
  EyeOff,
  Lock,
  User,
  Quote as QuoteIcon,
  Check,
  ArrowLeft,
  ArrowRight,
} from "lucide-react";
import { useState } from "react";
import Image from "next/image";

// ── Logo ────────────────────────────────────────────────
export function BuilderLogo({
  maxWidth = 200,
  src,
  shape = "auto",
}: {
  maxWidth?: number;
  src?: string;
  shape?: string;
  [k: string]: unknown;
}) {
  const { t } = useI18n();
  const resolvedSrc = useResolvedFileUrl(src);
  const borderRadius =
    shape === "circle" ? "50%" : shape === "square" ? "0" : shape === "rounded" ? "8px" : undefined;
  return (
    <div className="flex w-full items-center justify-center">
      <Image
        src={resolvedSrc || "/brand/app-logo-1024.png"}
        alt={t("studio.builder.preview.logoAlt")}
        width={200}
        height={80}
        unoptimized
        className="object-contain"
        style={{ maxWidth: `${maxWidth}px`, maxHeight: "80px", width: "auto", height: "auto", borderRadius }}
        onError={(e) => {
          (e.target as HTMLImageElement).style.display = "none";
        }}
      />
    </div>
  );
}

// ── Login Form ──────────────────────────────────────────
export function BuilderLoginForm({
  showSocial = true,
  showRemember = true,
  showForgot = true,
  showRegister = false,
}: {
  showSocial?: boolean;
  showRemember?: boolean;
  showForgot?: boolean;
  showRegister?: boolean;
  [k: string]: unknown;
}) {
  const { t } = useI18n();
  const [showPassword, setShowPassword] = useState(false);

  return (
    <div className="w-full" style={{ maxWidth: "var(--login-form-width, 380px)" }}>
      <form
        onSubmit={(e) => e.preventDefault()}
        className="flex flex-col"
        style={{ gap: "var(--login-element-gap, 16px)" }}
      >
        {/* Username */}
        <div className="space-y-2">
          <Label className="text-sm font-medium text-[var(--login-text,hsl(var(--foreground)))]">
            {t("studio.builder.preview.usernameLabel")}
          </Label>
          <div className="relative">
            <User
              className="absolute start-3 top-1/2 h-4 w-4 -translate-y-1/2 text-[var(--login-text-muted,hsl(var(--muted-foreground)))]"
              aria-hidden="true"
            />
            <Input
              placeholder={t("studio.builder.preview.usernamePlaceholder")}
              className="ps-9"
              readOnly
              style={{
                height: "var(--login-input-height, 44px)",
                borderRadius: "var(--login-radius-button, 8px)",
                borderColor: "var(--login-border, hsl(var(--border)))",
              }}
            />
          </div>
        </div>

        {/* Password */}
        <div className="space-y-2">
          <Label className="text-sm font-medium text-[var(--login-text,hsl(var(--foreground)))]">
            {t("studio.builder.preview.passwordLabel")}
          </Label>
          <div className="relative">
            <Lock
              className="absolute start-3 top-1/2 h-4 w-4 -translate-y-1/2 text-[var(--login-text-muted,hsl(var(--muted-foreground)))]"
              aria-hidden="true"
            />
            <Input
              type={showPassword ? "text" : "password"}
              placeholder="********"
              className="pe-9 ps-9"
              readOnly
              style={{
                height: "var(--login-input-height, 44px)",
                borderRadius: "var(--login-radius-button, 8px)",
                borderColor: "var(--login-border, hsl(var(--border)))",
              }}
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="absolute end-3 top-1/2 -translate-y-1/2 text-[var(--login-text-muted,hsl(var(--muted-foreground)))]"
              aria-label={t(showPassword ? "auth.hidePassword" : "auth.showPassword")}
            >
              {showPassword ? (
                <EyeOff className="h-4 w-4" aria-hidden="true" />
              ) : (
                <Eye className="h-4 w-4" aria-hidden="true" />
              )}
            </button>
          </div>
        </div>

        {/* Remember / Forgot */}
        {(showRemember || showForgot) && (
          <div className="flex items-center justify-between text-xs">
            {showRemember && (
              <label className="flex cursor-pointer items-center gap-2 text-[var(--login-text-muted,hsl(var(--muted-foreground)))]">
                <input type="checkbox" className="h-3.5 w-3.5 rounded-nx-sm" readOnly />
                {t("studio.builder.preview.rememberMe")}
              </label>
            )}
            {showForgot && (
              <span className="cursor-pointer text-[var(--login-primary,hsl(var(--primary)))] hover:underline">
                {t("studio.builder.preview.forgotPasswordLink")}
              </span>
            )}
          </div>
        )}

        {/* Login Button */}
        <Button
          type="submit"
          className="w-full text-sm font-semibold"
          style={{
            height: "var(--login-input-height, 44px)",
            backgroundColor: "var(--login-primary, hsl(var(--primary)))",
            borderRadius: "var(--login-radius-button, 8px)",
          }}
        >
          {t("studio.builder.preview.signIn")}
        </Button>

        {/* Register link */}
        {showRegister && (
          <p className="text-center text-xs text-[var(--login-text-muted,hsl(var(--muted-foreground)))]">
            {t("studio.builder.preview.noAccount")}{" "}
            <span className="cursor-pointer text-[var(--login-primary,hsl(var(--primary)))] hover:underline">
              {t("studio.builder.preview.register")}
            </span>
          </p>
        )}
      </form>

      {/* Social Login */}
      {showSocial && (
        <div className="mt-6 space-y-3">
          <div className="relative">
            <div className="absolute inset-0 flex items-center">
              <div className="w-full border-t border-[var(--login-border,hsl(var(--border)))]" />
            </div>
            <div className="relative flex justify-center text-xs">
              <span className="bg-[var(--login-surface,hsl(var(--background)))] px-2 text-[var(--login-text-muted,hsl(var(--muted-foreground)))]">
                {t("studio.builder.preview.orContinueWith")}
              </span>
            </div>
          </div>
          <div className="grid grid-cols-2 gap-2">
            <Button
              variant="outline"
              type="button"
              className="h-10 text-xs"
              style={{ borderRadius: "var(--login-radius-button, 8px)" }}
            >
              {t("studio.builder.preview.providerGoogle")}
            </Button>
            <Button
              variant="outline"
              type="button"
              className="h-10 text-xs"
              style={{ borderRadius: "var(--login-radius-button, 8px)" }}
            >
              {t("studio.builder.preview.providerMicrosoft")}
            </Button>
          </div>
        </div>
      )}
    </div>
  );
}

