export function BuilderCustomHtml({
  content = "",
  css = "",
}: {
  content?: string;
  css?: string;
  [k: string]: unknown;
}) {
  const { t } = useI18n();
  if (!content && !css) {
    return (
      <div className="w-full rounded-nx-control border border-dashed border-warning/30 bg-warning/5 p-4">
        <p className="text-xs text-warning">{t("studio.builder.preview.customHtmlTitle")}</p>
        <p className="mt-1 text-[10px] text-nx-ink-3">
          {t("studio.builder.preview.customHtmlHint")}
        </p>
      </div>
    );
  }
  // Author-supplied markup is sanitized before injection. Without this, an admin with
  // customization rights could store a <script> in a custom HTML block and have it execute
  // same-origin for every other admin who opens the branding studio — stored XSS with access
  // to the viewing admin's session. The CSS pass additionally blocks the `</style>` breakout,
  // which escapes the style context and executes regardless of how safe the CSS itself is.
  return (
    <div className="scripe-custom-html w-full">
      <style dangerouslySetInnerHTML={{ __html: CUSTOM_HTML_RESET + sanitizeCss(css || "") }} />
      <div dangerouslySetInnerHTML={{ __html: sanitizeRichHtml(content) }} />
    </div>
  );
}

// ── Video Background ────────────────────────────────────
export function BuilderVideoBg({
  src = "",
  poster = "",
  autoplay = true,
  muted = true,
}: {
  src?: string;
  poster?: string;
  autoplay?: boolean;
  muted?: boolean;
  [k: string]: unknown;
}) {
  const { t } = useI18n();
  // Called unconditionally, before the placeholder early return below.
  const resolvedSrc = useResolvedFileUrl(src);
  const resolvedPoster = useResolvedFileUrl(poster);
  if (!src || !resolvedSrc) {
    return (
      <div className="flex h-full min-h-[200px] w-full items-center justify-center rounded-nx-md border border-dashed border-[color:color-mix(in_srgb,var(--nx-accent)_30%,transparent)] bg-gradient-to-br from-[color:color-mix(in_srgb,var(--nx-accent)_10%,transparent)] to-info/10">
        <p className="text-xs text-nx-accent">{t("studio.builder.preview.videoBgPlaceholder")}</p>
      </div>
    );
  }
  return (
    <video
      src={resolvedSrc}
      poster={resolvedPoster || undefined}
      autoPlay={autoplay}
      muted={muted}
      loop
      playsInline
      className="h-full w-full rounded-nx-md object-cover"
    />
  );
}

