            } as Record<string, string>
          )[draft.bgImageFit] || "cover",
        "bg.image.position": draft.bgImagePosition,
        "bg.gradient":
          draft.bgType === "gradient"
            ? `linear-gradient(${draft.bgGradientDirection}, ${draft.bgGradientFrom}, ${draft.bgGradientTo})`
            : "",
        // ── Accessibility tokens ──
        // Focus & Keyboard
        "a11y.focusRing.enabled": `${draft.a11yFocusRingEnabled}`,
        "a11y.focusRing.color": draft.a11yFocusRingColor || draft.primaryColor,
        "a11y.focusRing.width": `${draft.a11yFocusRingWidth}px`,
        "a11y.focusRing.style": draft.a11yFocusRingStyle,
        "a11y.skipLink.enabled": `${draft.a11ySkipLinkEnabled}`,
        "a11y.highlightFocus": `${draft.a11yHighlightFocus}`,
        // Screen Reader
        "a11y.ariaLandmarks": `${draft.a11yAriaLandmarks}`,
        "a11y.formLabels.visible": `${draft.a11yFormLabelsVisible}`,
        "a11y.errorAnnounce": `${draft.a11yErrorAnnounce}`,
        "a11y.pageTitle": draft.a11yPageTitle,
        // Contrast & Colors
        "a11y.highContrast": `${draft.a11yHighContrastMode}`,
        "a11y.contrastPreset": draft.a11yContrastPreset,
        "a11y.saturation": `${draft.a11ySaturation}`,
        "a11y.highlightLinks": `${draft.a11yHighlightLinks}`,
        // Typography & Readability
        "a11y.minFontSize": `${draft.a11yMinFontSize}`,
        "a11y.contentScaling": `${draft.a11yContentScaling}`,
        "a11y.lineHeight": `${draft.a11yLineHeight}`,
        "a11y.letterSpacing": `${draft.a11yLetterSpacing}`,
        "a11y.wordSpacing": `${draft.a11yWordSpacing}`,
        "a11y.dyslexicFont": `${draft.a11yDyslexicFont}`,
        "a11y.textAlign": draft.a11yTextAlign,
        // Cursor & Reading Aids
        "a11y.cursorSize": draft.a11yCursorSize,
        "a11y.readingGuide": `${draft.a11yReadingGuide}`,
        "a11y.readingMask": `${draft.a11yReadingMask}`,
        // Motion & Animation
        "a11y.reducedMotion": draft.a11yReducedMotion,
        "a11y.animationDuration": `${draft.a11yAnimationDuration}`,
        "a11y.autoplayDisabled": `${draft.a11yAutoplayDisabled}`,
        "a11y.pauseAnimations": `${draft.a11yPauseAnimations}`,
        // Content & Media
        "a11y.hideImages": `${draft.a11yHideImages}`,
        "a11y.tooltips": `${draft.a11yTooltips}`,
        // Touch & Target Size
        "a11y.largeTargets": `${draft.a11yLargeTargets}`,
        "a11y.forcedColors": `${draft.a11yForcedColorsSupport}`,
      },
    });
  }, [draft]);

  const slotConfig = draft.slotConfig;
  // ── Build SlotConfigJson ──
  const buildSlotConfigJson = useCallback((): string => {
    return JSON.stringify(slotConfig);
  }, [slotConfig]);

  // ── Auto-save draft every 5s ──
  useEffect(() => {
    if (!isDirty || !branding) return; // Guard: skip if no tenant context

    if (autoSaveTimerRef.current) clearTimeout(autoSaveTimerRef.current);
    autoSaveTimerRef.current = setTimeout(async () => {
      try {
        const draftJson = buildDraftJson();
        const draftDashboardThemeJson = JSON.stringify(draft.dashboardSettings);
        if (targetTenantId) {
          // Drilldown: save draft to specific tenant via repository
          await repository.updateTenantSettingsById(targetTenantId, {
            draftBrandingJson: draftJson,
            draftDashboardThemeJson,
          });
        } else {
          // My tenant via repository
          await repository.updateMySettings({
            draftBrandingJson: draftJson,
            draftDashboardThemeJson,
          });
        }
        setLastSavedAt(new Date());
      } catch {
        // Silent fail — draft save is non-critical
      }
    }, 5000);

    return () => {
      if (autoSaveTimerRef.current) clearTimeout(autoSaveTimerRef.current);
    };
  }, [isDirty, draft, branding, buildDraftJson, repository]);

  // ── Publish ──
  const publishMutation = useMutation({
    mutationFn: async () => {
      const draftJson = buildDraftJson();
      const draftDashboardThemeJson = JSON.stringify(draft.dashboardSettings);
      if (targetTenantId) {
        // Drilldown: save draft then publish to specific tenant via repository
        // For drilldown, we write directly to live fields since there's no publish endpoint per-tenant
        await repository.updateTenantSettingsById(targetTenantId, {
          draftBrandingJson: draftJson,
          loginBrandingJson: draftJson, // Publish = copy draft to live
          dashboardThemeJson: draftDashboardThemeJson, // Also write to live
          draftDashboardThemeJson: null, // Clear draft
        });
      } else {
        // My tenant via repository — save draft dashboard, then publish (backend promotes draft→live)
        await repository.updateMySettings({
          draftBrandingJson: draftJson,
          draftDashboardThemeJson,
        });
        const currentVersion = (branding as any)?.settingsVersion ?? 0;
        await repository.publishBranding(currentVersion);
      }
    },
    onSuccess: () => {
      toastSuccess({ title: t("studio.publishSuccess") });
      setIsDirty(false);
      setLastSavedAt(new Date());
      queryClient.invalidateQueries({ queryKey: ["tenantSettings"] });
      queryClient.invalidateQueries({ queryKey: ["studio-branding"] });
      queryClient.invalidateQueries({ queryKey: ["customization"] });
    },
    onError: (error: Error) => {
      const isConflict = error.message?.includes("409") || error.message?.includes("conflict");
      toastError({
        title: isConflict
          ? t("studio.versionConflict")
          : t("studio.publishFailed"),
        description: error.message,
      });
    },
  });

  // ── Explicit Save Draft ──
  const saveDraftMutation = useMutation({
    mutationFn: async () => {
      const draftJson = buildDraftJson();
      const draftDashboardThemeJson = JSON.stringify(draft.dashboardSettings);
      if (targetTenantId) {
        await repository.updateTenantSettingsById(targetTenantId, {
          draftBrandingJson: draftJson,
          draftDashboardThemeJson,
        });
      } else {
        await repository.updateMySettings({
          draftBrandingJson: draftJson,
          draftDashboardThemeJson,
        });
      }
    },
    onSuccess: () => {
      toastSuccess({ title: t("studio.draftSaved") });
      setLastSavedAt(new Date());
    },
    onError: (error: Error) => {
      toastError({
        title: t("studio.draftSaveFailed"),
        description: error.message,
      });
    },
  });

  // ── Save Theme: Custom Fields ──
  const themeCustomFieldsQuery = useCustomFieldsFormFields(THEME_ENTITY_TYPE_KEY, undefined);

  const [themeCustomFieldValues, setThemeCustomFieldValues] = useState<Record<string, unknown>>(
    {}
  );

  const updateThemeCustomFieldValue = useCallback((name: string, value: unknown) => {
    setThemeCustomFieldValues((prev) => ({ ...prev, [name]: value }));
  }, []);

  // Full-resubmit, matching GenericCrudView's own contract: every currently
  // known custom field's effective value (edited-this-session or the fetched
  // default) is sent, not just the ones the user touched. Mirrors
  // useWebhookFormViewModel's / useDsrViewModel's identical helper.
  const themeFieldConfigs = themeCustomFieldsQuery.fieldConfigs;
  const saveThemeCustomFieldValues = useCallback(
    async (ownerId: string) => {
      // D5 (final whole-branch review, I3 follow-up): reject a stale/invalid
      // Select value client-side, with the real localized reason, BEFORE it
      // ever reaches saveValues and comes back as a 422 -- see
      // assertSelectCustomFieldValuesValid's own doc comment
      // (renderCustomFieldControl.tsx) for why this is the right integration
      // point. Throws CustomFieldValidationError, which saveTheme's own
      // catch block below distinguishes from a genuine API failure so it can
      // show the specific reason, not the generic fallback.
      assertSelectCustomFieldValuesValid(
        themeFieldConfigs,
        themeCustomFieldValues,
        t
      );

      const decoded: Record<string, unknown> = {};
      for (const fc of themeFieldConfigs) {
        const key = decodeCustomFieldName(fc.name);
        if (key === null) continue;
        const raw = themeCustomFieldValues[fc.name] ?? fc.defaultValue ?? "";
        decoded[key] = raw === "" ? null : raw;
      }
      if (Object.keys(decoded).length === 0) return;
      await getCustomFieldsExtension()?.saveValues(THEME_ENTITY_TYPE_KEY, ownerId, decoded);
    },
    [themeFieldConfigs, themeCustomFieldValues, t]
  );

  // ── Save Theme ──
  // No onSuccess here -- success side effects (toast) only fire from
  // saveTheme below once saveThemeCustomFieldValues has also settled, so a
  // custom-field save failure can never be masked by an immediate "saved"
  // toast that closes the dialog out from under it. Mirrors
  // useWebhookFormViewModel's createMutation.
  const saveThemeMutation = useMutation({
    mutationFn: async (themeInput: {
      name: string;
      slug: string;
      description?: string;
      authorName?: string;
      category: string;
      accentColor: string;
      themeDataJson: string;
    }) => {
      const { themeMarketplaceRepository } = customizationContainer;
      return await themeMarketplaceRepository.create({
        ...themeInput,
        version: "1.0.0",
        themeSchemaVersion: 1,
        isFree: true,
        pricingType: "Free",
        minTierLevel: 0,
        isAlsoBuyable: false,
        displayOrder: 999,
        isFeatured: false,
        isNew: true,
        hasDarkMode: false,
        hasAccessibilityPreset: false,
        hasContentBlocks: false,
        isSystem: false,
      });
    },
    onError: (err: any) => {
      const msg = err?.message || err?.response?.data?.error || t("common.error");
      toastError({
        title: t("studio.saveTheme.failed"),
        description: msg,
      });
    },
  });

  // Entity saves first, then custom fields -- a custom-field save failure
  // shows its own error and does NOT show the entity's own success toast,
  // then re-throws so SaveAsThemeModal knows to stay open with what the
  // user typed rather than pretend it saved. Mirrors useDsrViewModel's
  // handleSubmit / useWebhookFormViewModel's handleSubmit sequencing.
  const saveTheme = useCallback(
    async (themeInput: {
      name: string;
      slug: string;
      description?: string;
      authorName?: string;
      category: string;
      accentColor: string;
      themeDataJson: string;
    }) => {
      // Rejects (and skips the rest) if the create itself fails --
      // saveThemeMutation's own onError has already toasted; let it
      // propagate so SaveAsThemeModal's own catch knows not to reset/close.
      const created = await saveThemeMutation.mutateAsync(themeInput);
      try {
        await saveThemeCustomFieldValues(created.id);
      } catch (err) {
        toastError({
          title:
            err instanceof CustomFieldValidationError
              ? err.message
              : t("studio.saveTheme.customFieldsSaveError"),
        });
        // The theme itself WAS created -- re-throw only so the modal knows
        // to stay open with what the user typed, not to pretend nothing
        // happened.
        throw err;
      }
      toastSuccess({
        title: t("studio.saveTheme.success"),
        description: t("studio.saveTheme.successDesc"),
      });
      setThemeCustomFieldValues({});
    },
    [saveThemeMutation, saveThemeCustomFieldValues, toastError, toastSuccess, t]
  );

  // ── Discard (with confirmation) ──
  const discardMutation = useMutation({
    mutationFn: () => repository.discardDraft(),
    onSuccess: () => {
      toastSuccess({ title: t("studio.discardSuccess") });
      setIsDirty(false);
      setShowDiscardConfirm(false);
      // Restore to currently published design (all fields, not just a few)
      if (branding) {
        try {
          const restored = buildDraftFromBranding(branding, false); // false = use live only, skip draft
          setDraft(restored);
        } catch {
          setDraft(DEFAULT_DRAFT);
        }
      } else {
        setDraft(DEFAULT_DRAFT);
      }
      queryClient.invalidateQueries({ queryKey: ["tenantSettings"] });
      queryClient.invalidateQueries({ queryKey: ["studio-branding"] });
      queryClient.invalidateQueries({ queryKey: ["customization"] });
    },
    onError: (error: Error) => {
      setShowDiscardConfirm(false);
      toastError({
        title: t("studio.discardFailed"),
        description: error.message,
      });
    },
  });

  // Confirmation handlers for discard
  const requestDiscard = useCallback(() => setShowDiscardConfirm(true), []);
  const cancelDiscard = useCallback(() => setShowDiscardConfirm(false), []);
  const confirmDiscard = useCallback(() => discardMutation.mutate(), [discardMutation]);

  // ── Theme Preview (Preview any theme without applying it) ──
  const savedDraftRef = useRef<StudioDraft | null>(null);
  const [isPreviewingTheme, setIsPreviewingTheme] = useState(false);

  const previewTheme = useCallback(
    (themeDataJson: string) => {
      // Save current draft so we can restore it
      if (!savedDraftRef.current) {
        savedDraftRef.current = draft;
      }
      try {
        const parsed = JSON.parse(themeDataJson);

        // Support BOTH formats:
        //   1. Seeder format:  { colors: { primary, background, ... }, typography: { fontFamily }, spacing: { borderRadius } }
        //   2. Tokens format:  { tokens: { "color.primary", "font.body", "radius.card" } }
        const tokens = parsed.tokens || {};
        const colors = parsed.colors || {};
        const typography = parsed.typography || {};
        const spacing = parsed.spacing || {};

        // Helper to parse int from token string like "12px" -> 12
        const tInt = (key: string, fb?: number) => parseInt(tokens[key] || "") || fb || 0;
        const tFloat = (key: string, fb?: number) => parseFloat(tokens[key] || "") || fb || 0;

        const tempDraft: StudioDraft = {
          ...DEFAULT_DRAFT,
          layout: parsed.layout || DEFAULT_DRAFT.layout,
          headline: parsed.headline || "",
          subtitle: parsed.subtitle || "",
          companyName: parsed.companyName || draft.companyName,
          logoUrl: parsed.logoUrl || draft.logoUrl,
          faviconUrl: parsed.faviconUrl || draft.faviconUrl,
          copyrightText: parsed.copyrightText || draft.copyrightText,

          // ── Theme Mode ──
          themeMode: parsed.themeMode || DEFAULT_DRAFT.themeMode,

          // ── Light Palette — tokens first, then seeder colors, then defaults ──
          primaryColor: tokens["color.primary"] || colors.primary || DEFAULT_DRAFT.primaryColor,
          secondaryColor:
            tokens["color.secondary"] || colors.secondary || DEFAULT_DRAFT.secondaryColor,
          bgColor: tokens["color.background"] || colors.background || DEFAULT_DRAFT.bgColor,
          surfaceColor: tokens["color.surface"] || colors.surface || DEFAULT_DRAFT.surfaceColor,
          textColor: tokens["color.text"] || colors.text || DEFAULT_DRAFT.textColor,
          mutedColor: tokens["color.textMuted"] || colors.muted || DEFAULT_DRAFT.mutedColor,
          borderColor: tokens["color.border"] || colors.border || DEFAULT_DRAFT.borderColor,
          errorColor: tokens["color.error"] || colors.error || DEFAULT_DRAFT.errorColor,
          successColor: tokens["color.success"] || colors.success || DEFAULT_DRAFT.successColor,

          // ── Dark Palette ──
          darkPrimaryColor: tokens["dark.color.primary"] || DEFAULT_DRAFT.darkPrimaryColor,
          darkSecondaryColor: tokens["dark.color.secondary"] || DEFAULT_DRAFT.darkSecondaryColor,
          darkBgColor: tokens["dark.color.background"] || DEFAULT_DRAFT.darkBgColor,
          darkSurfaceColor: tokens["dark.color.surface"] || DEFAULT_DRAFT.darkSurfaceColor,
          darkTextColor: tokens["dark.color.text"] || DEFAULT_DRAFT.darkTextColor,
          darkMutedColor: tokens["dark.color.textMuted"] || DEFAULT_DRAFT.darkMutedColor,
          darkBorderColor: tokens["dark.color.border"] || DEFAULT_DRAFT.darkBorderColor,
          darkErrorColor: tokens["dark.color.error"] || DEFAULT_DRAFT.darkErrorColor,
          darkSuccessColor: tokens["dark.color.success"] || DEFAULT_DRAFT.darkSuccessColor,

          // ── Typography — tokens first, then seeder typography object ──
          fontFamily: tokens["font.body"] || typography.fontFamily || DEFAULT_DRAFT.fontFamily,
          fontFamilyAr: tokens["font.bodyAr"] || DEFAULT_DRAFT.fontFamilyAr,
          headingFont: tokens["font.heading"] || typography.headingFont || "",
          headingSize: tInt(
            "font.size.headline",
            typography.headingSize || DEFAULT_DRAFT.headingSize
          ),
          bodySize: tInt("font.size.subtitle", typography.bodySize || DEFAULT_DRAFT.bodySize),
          headingWeight: tInt("font.weight.heading", DEFAULT_DRAFT.headingWeight),
          bodyWeight: tInt("font.weight.body", DEFAULT_DRAFT.bodyWeight),
          lineHeight: tFloat("font.lineHeight", DEFAULT_DRAFT.lineHeight),
          letterSpacing: tFloat("font.letterSpacing", DEFAULT_DRAFT.letterSpacing),

          // ── Spacing — tokens first, then seeder spacing object ──
          borderRadius: tInt("radius.card", spacing.borderRadius || DEFAULT_DRAFT.borderRadius),
          btnRadius: tInt("radius.button", spacing.btnRadius || DEFAULT_DRAFT.btnRadius),
          formWidth: tInt("spacing.formWidth", spacing.formWidth || DEFAULT_DRAFT.formWidth),
          cardPadding: tInt(
            "spacing.cardPadding",
            spacing.cardPadding || DEFAULT_DRAFT.cardPadding
          ),
          elementGap: tInt("spacing.elementGap", DEFAULT_DRAFT.elementGap),
          inputHeight: tInt("spacing.inputHeight", DEFAULT_DRAFT.inputHeight),
          btnSize: parsed.btnSize || DEFAULT_DRAFT.btnSize,

          // ── Background ──
          bgType: parsed.bgType || DEFAULT_DRAFT.bgType,
          bgGradientDirection: parsed.bgGradientDirection || DEFAULT_DRAFT.bgGradientDirection,
          bgGradientFrom: parsed.bgGradientFrom || DEFAULT_DRAFT.bgGradientFrom,
          bgGradientTo: parsed.bgGradientTo || DEFAULT_DRAFT.bgGradientTo,
          bgImageUrl: tokens["bg.image"] || "",
          bgOverlayEnabled: parsed.bgOverlayEnabled ?? DEFAULT_DRAFT.bgOverlayEnabled,
          bgOverlayColor: parsed.bgOverlayColor || DEFAULT_DRAFT.bgOverlayColor,
          bgOverlayOpacity: tFloat("overlay.opacity", DEFAULT_DRAFT.bgOverlayOpacity),
          bgBlur: typeof parsed.bgBlur === "number" ? parsed.bgBlur : DEFAULT_DRAFT.bgBlur,

          // ── Dark Background ──
          darkBgType: parsed.darkBgType || DEFAULT_DRAFT.darkBgType,
          darkBgGradientDirection:
            parsed.darkBgGradientDirection || DEFAULT_DRAFT.darkBgGradientDirection,
          darkBgGradientFrom: parsed.darkBgGradientFrom || DEFAULT_DRAFT.darkBgGradientFrom,
          darkBgGradientTo: parsed.darkBgGradientTo || DEFAULT_DRAFT.darkBgGradientTo,
          darkBgImageUrl: tokens["dark.bg.image"] || "",
          darkBgOverlayEnabled: parsed.darkBgOverlayEnabled ?? DEFAULT_DRAFT.darkBgOverlayEnabled,
          darkBgOverlayColor: parsed.darkBgOverlayColor || DEFAULT_DRAFT.darkBgOverlayColor,
          darkBgOverlayOpacity: tFloat("dark.overlay.opacity", DEFAULT_DRAFT.darkBgOverlayOpacity),
          darkBgBlur:
            typeof parsed.darkBgBlur === "number" ? parsed.darkBgBlur : DEFAULT_DRAFT.darkBgBlur,

          // ── Custom CSS ──
          customCss: parsed.customCss || "",

          // ── Keep current slots, safe mode & builder state ──
          slotConfig: draft.slotConfig,
          safeMode: draft.safeMode,
          canvasMode: draft.canvasMode,
          canvasComponents: draft.canvasComponents,
          canvasGridRows: draft.canvasGridRows,
          canvasBackground: draft.canvasBackground,
          dashboardSettings: draft.dashboardSettings,

          // ── Import per-page overrides from theme (if present) ──
          pageOverrides: (() => {
            const themePages = parsed.pages as Record<string, any> | undefined;
            if (!themePages) return draft.pageOverrides;
            const merged = { ...draft.pageOverrides };
            for (const [pageId, pageData] of Object.entries(themePages)) {
              const typedPageId = pageId as keyof typeof merged;
              merged[typedPageId] = {
                ...(merged[typedPageId] || { inheritBackground: true }),
                layout: pageData.layout || merged[typedPageId]?.layout || "centered",
                headline: pageData.headline || merged[typedPageId]?.headline || "",
                subtitle: pageData.subtitle || merged[typedPageId]?.subtitle || "",
              };
            }
            return merged;
          })(),
        };
        setDraft(tempDraft);
        setIsPreviewingTheme(true);
      } catch {
        /* invalid JSON */
      }
    },
    [draft]
  );

  const exitThemePreview = useCallback(() => {
    if (savedDraftRef.current) {
      setDraft(savedDraftRef.current);
      savedDraftRef.current = null;
    }
    setIsPreviewingTheme(false);
  }, []);

  // ── Reset Branding ──
  const resetMutation = useMutation({
    mutationFn: async (resetType: "Published" | "GlobalDefault" | "FactoryDefault") => {
      await repository.resetBranding(resetType);
    },
    onSuccess: () => {
      toastSuccess({ title: t("studio.resetSuccess") });
      setIsDirty(false);
      setIsPreviewingTheme(false);
      savedDraftRef.current = null;
      queryClient.invalidateQueries({ queryKey: ["studio-branding"] });
      queryClient.invalidateQueries({ queryKey: ["customization"] });
    },
    onError: (error: Error) => {
      toastError({ title: t("studio.resetFailed"), description: error.message });
    },
  });

  // ── Refresh draft from server ──
  const refreshDraft = useCallback(async () => {
    await queryClient.invalidateQueries({ queryKey: ["studio-branding"] });
    setIsPreviewingTheme(false);
    savedDraftRef.current = null;
  }, [queryClient]);

  return {
    t,
    // Draft state
    draft,
    isDirty,
    lastSavedAt,
    updateDraft,
    batchUpdateDraft,
    buildDraftJson,
    buildSlotConfigJson,
    // Slots
    addBlock,
    removeBlock,
    moveBlock,
    updateBlock,
    // Device
    deviceSize,
    setDeviceSize,
    // Panels
    activePanel,
    setActivePanel,
    // Multi-page branding
    activeAuthPage,
    setActiveAuthPage,
    getPageOverride,
    setPageOverride,
    // Actions
    publish: () => publishMutation.mutate(),
    isPublishing: publishMutation.isPending,
    saveDraft: () => saveDraftMutation.mutate(),
    isSavingDraft: saveDraftMutation.isPending,
    saveTheme,
    isSavingTheme: saveThemeMutation.isPending,
    // Save Theme: Custom Fields
    themeCustomFieldConfigs: themeCustomFieldsQuery.fieldConfigs,
    themeCustomFieldsLoading: themeCustomFieldsQuery.isLoading,
    themeCustomFieldValues,
    updateThemeCustomFieldValue,
    refetchThemeCustomFields: themeCustomFieldsQuery.refetch,
    discard: requestDiscard,
    confirmDiscard,
    cancelDiscard,
    showDiscardConfirm,
    isDiscarding: discardMutation.isPending,
    // Theme Preview
    previewTheme,
    exitThemePreview,
    isPreviewingTheme,
    // Reset Branding
    resetBranding: (type: "Published" | "GlobalDefault" | "FactoryDefault") =>
      resetMutation.mutate(type),
    isResetting: resetMutation.isPending,
    // Refresh
    refreshDraft,
    // Loading & context
    isLoading: brandingQuery.isLoading,
    isTenantContext: true, // Backend always returns data (system defaults for system admin)
    // Drilldown metadata
    mode,
    targetTenantId,
    targetTenantName: options?.targetTenantName,
  };
}

/**
 * Theme Management ViewModel
 *
 * Orchestrates the theme management admin page (CRUD table).
 * System admin only — for creating, editing, duplicating,
 * deprecating, and deleting themes in the marketplace.
 *
 * All user-facing strings use i18n via t().
 *
 * @module customization/presentation
 */
"use client";

import { useCallback, useMemo } from "react";
import { customizationContainer } from "@modules/customization/di";
import { useI18n } from "@core/providers/i18n-provider";
import { useCrudViewModel } from "@core/crud/hooks/useCrudViewModel";
import type { CrudConfig } from "@core/crud/components/generic-crud-view";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { useEnhancedToast } from "@core/hooks/use-enhanced-toast";
import type { ThemeCard } from "../../domain/entities/ThemeCard";

/**
 * Exported constant defining parameters and fields for theme keys configurations.
 */
export const themeKeys = {
  all: ["themes-management"] as const,
  list: (filters: Record<string, unknown>) => [...themeKeys.all, "list", filters] as const,
  detail: (slug: string) => [...themeKeys.all, "detail", slug] as const,
};

/**
 * React hook/ViewModel orchestrating state and data flows for theme management view model.
 * Manages TanStack Query hooks, query cache keys, and repository fetch requests.
 */
export function useThemeManagementViewModel() {
  const { themeMarketplaceRepository } = customizationContainer;
  const { t } = useI18n();
  const queryClient = useQueryClient();
  const { success, error: toastError } = useEnhancedToast();

  // ============ Core CRUD ViewModel ============
  const vm = useCrudViewModel<ThemeCard, any, any>([...themeKeys.all], {
    getAll: async (params) => {
      const res = await themeMarketplaceRepository.getThemes({
        page: params.page,
        pageSize: params.pageSize,
        filters: {
          search: params.search || "",
          category: "",
          sortBy: "name",
        },
      });
      return {
        items: res.items || [],
        pagination: {
          itemsCount: res.totalCount,
          pageSize: params.pageSize,
          page: params.page,
          pagesCount: Math.ceil(res.totalCount / params.pageSize),
        },
      };
    },
    delete: async (id: string) => {
      const theme = vm.items.find((t) => t.id === id);
      if (theme) {
        await themeMarketplaceRepository.delete(theme.slug);
        success({
          title: t("studio.themeManagement.toast.deleted"),
          description: t("studio.themeManagement.toast.deletedDesc"),
        });
      }
    },
  });

  // ============ Duplicate Mutation ============
  const duplicateMutation = useMutation({
    mutationFn: (params: { slug: string; newSlug: string; newName: string }) =>
      themeMarketplaceRepository.duplicate(params.slug, params.newSlug, params.newName),
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: themeKeys.all });
      success({
        title: t("studio.themeManagement.toast.duplicated"),
        description: t("studio.themeManagement.toast.duplicatedDesc", {
          name: variables.newName,
        }) as string,
      });
    },
    onError: (err: Error) => {
      toastError({
        title: t("studio.themeManagement.toast.duplicateFailed"),
        description: err.message,
      });
    },
  });

  // ============ Deprecate Mutation ============
  const deprecateMutation = useMutation({
    mutationFn: (params: { slug: string; notice?: string; replacedBySlug?: string }) =>
      themeMarketplaceRepository.deprecate(params.slug, params.notice, params.replacedBySlug),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: themeKeys.all });
      success({
        title: t("studio.themeManagement.toast.deprecated"),
        description: t("studio.themeManagement.toast.deprecatedDesc"),
      });
    },
    onError: (err: Error) => {
      toastError({
        title: t("studio.themeManagement.toast.deprecateFailed"),
        description: err.message,
      });
    },
  });

  // ============ Toggle Favorite Mutation ============
  const favoriteMutation = useMutation({
    mutationFn: (slug: string) => themeMarketplaceRepository.toggleFavorite(slug),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: themeKeys.all });
    },
    onError: (err: Error) => {
      toastError({
        title: t("common.error"),
        description: err.message,
      });
    },
  });

  // ============ Actions ============
  const handleDuplicate = useCallback(
    (theme: ThemeCard) => {
      const newSlug = `${theme.slug}-copy-${Date.now().toString(36)}`;
      const copySuffix = t("studio.themeManagement.copySuffix");
      const newName = `${theme.name} ${copySuffix}`;
      duplicateMutation.mutate({ slug: theme.slug, newSlug, newName });
    },
    [duplicateMutation, t]
  );

  const handleDeprecate = useCallback(
    (theme: ThemeCard) => {
      const notice = t("studio.themeManagement.defaultDeprecationNotice");
      deprecateMutation.mutate({
        slug: theme.slug,
        notice,
      });
    },
    [deprecateMutation, t]
  );

  const handleToggleFavorite = useCallback(
    (theme: ThemeCard) => {
      favoriteMutation.mutate(theme.slug);
    },
    [favoriteMutation]
  );

  // ============ Config ============
  const items = vm.items;
  const itemsCount = vm.pagination.itemsCount;

  const getConfigBase = useCallback(
    (): Partial<CrudConfig<ThemeCard>> => ({
      getItemDisplayName: (item: ThemeCard) => item.name,
      deleteService: async (id: string) => {
        const theme = items.find((t) => t.id === id);
        if (theme) {
          await themeMarketplaceRepository.delete(theme.slug);
        }
      },
    }),
    [themeMarketplaceRepository, items]
  );

  // ============ Statistics ============
  const statistics = useMemo(() => {
    return {
      total: itemsCount || items.length,
      free: items.filter((t) => t.isFree).length,
      featured: items.filter((t) => t.isFeatured).length,
      system: items.filter((t) => t.isSystem).length,
      deprecated: items.filter((t) => t.isDeprecated).length,
    };
  }, [items, itemsCount]);

  return {
    vm,
    getConfigBase,
    handleDuplicate,
    handleDeprecate,
    handleToggleFavorite,
    isDuplicating: duplicateMutation.isPending,
    isDeprecating: deprecateMutation.isPending,
    statistics,
    t,
  };
}

