/**
 * Theme Management View
 *
 * Admin page for managing marketplace themes.
 * Uses GenericCrudView with rich columns, status badges,
 * and custom actions (duplicate, deprecate, delete).
 *
 * All user-facing strings use i18n via t().
 *
 * Route: /settings/themes (system admin only)
 *
 * @module customization/presentation
 */
"use client";

import { useMemo } from "react";
import { GenericCrudView } from "@core/crud/components/generic-crud-view";
import type { CrudConfig, CrudAction } from "@core/crud/components/generic-crud-view";
import type { ThemeCard } from "../../domain/entities/ThemeCard";
import { useThemeManagementViewModel } from "../viewmodels/useThemeManagementViewModel";
import { useI18n } from "@core/providers/i18n-provider";
import { useModuleLocales } from "@core/hooks/use-module-locales";
import { Badge } from "@core/ui/badge";
import { StatCard } from "@core/ui/stat-card";
import {
  Eye,
  Copy,
  Trash2,
  Star,
  Archive,
  Palette,
  Crown,
  Sparkles,
  Moon,
  Accessibility,
  Blocks,
  Users,
  Heart,
  TrendingUp,
} from "lucide-react";
import { useRouter } from "next/navigation";

// ── Prefix helper ──
const T = "studio.themeManagement";

/** Tier badge component */
function TierBadge({
  isFree,
  pricingType,
  minTierLevel,
}: {
  isFree: boolean;
  pricingType: string;
  minTierLevel: number;
}) {
  const { t } = useI18n();
  if (isFree) {
    return (
      <Badge
        variant="outline"
        className="border-success/20 bg-success/10 text-[10px] font-semibold text-success"
      >
        <Sparkles className="me-0.5 h-3 w-3" aria-hidden="true" />
        {t(`${T}.tier.free`)}
      </Badge>
    );
  }
  if (pricingType === "StandaloneOnly") {
    return (
      <Badge
        variant="outline"
        className="border-nx-accent text-[10px] font-semibold text-nx-accent"
      >
        <Crown className="me-0.5 h-3 w-3" aria-hidden="true" />
        {t(`${T}.tier.premium`)}
      </Badge>
    );
  }
  const tierMap: Record<number, string> = {
    0: t(`${T}.tier.free`),
    1: t(`${T}.tier.starter`),
    2: t(`${T}.tier.pro`),
    3: t(`${T}.tier.enterprise`),
  };
  return (
    <Badge
      variant="outline"
      className="border-info/20 bg-info/10 text-[10px] font-semibold text-info"
    >
      <Crown className="me-0.5 h-3 w-3" aria-hidden="true" />
      {tierMap[minTierLevel] || t(`${T}.tier.tierN`, { n: minTierLevel })}
    </Badge>
  );
}

/** Feature badges */
function FeatureBadges({ theme }: { theme: ThemeCard }) {
  const { t } = useI18n();
  return (
    <div className="flex flex-wrap gap-1">
      {theme.hasDarkMode && (
        <Badge
          variant="outline"
          className="h-4 border-nx-line bg-nx-raised px-1.5 py-0 text-[9px] text-nx-ink-2"
        >
          <Moon className="me-0.5 h-2.5 w-2.5" aria-hidden="true" />
          {t(`${T}.features.dark`)}
        </Badge>
      )}
      {theme.hasAccessibilityPreset && (
        <Badge
          variant="outline"
          className="h-4 border-info/40 bg-info/10 px-1.5 py-0 text-[9px] text-info"
        >
          <Accessibility className="me-0.5 h-2.5 w-2.5" aria-hidden="true" />
          {t(`${T}.features.a11y`)}
        </Badge>
      )}
      {theme.hasContentBlocks && (
        <Badge
          variant="outline"
          className="h-4 border-nx-accent px-1.5 py-0 text-[9px] text-nx-accent"
        >
          <Blocks className="me-0.5 h-2.5 w-2.5" aria-hidden="true" />
          {t(`${T}.features.blocks`)}
        </Badge>
      )}
    </div>
  );
}

/**
 * Presentation UI component rendering the theme management view.
 * Arranges layout boundaries and accessibility targets (WCAG, tab index) using the core design library (@core/ui/*).
 */
export function ThemeManagementView() {
  useModuleLocales(() => import("@modules/customization/studio/locales"), "customization-studio");
  const { t } = useI18n();
  const router = useRouter();
  const { vm, getConfigBase, handleDuplicate, handleDeprecate, handleToggleFavorite, statistics } =
    useThemeManagementViewModel();
  const configBase = getConfigBase();

  const config: CrudConfig<ThemeCard> = useMemo(
    () => ({
      titleKey: `${T}.title`,
      subtitleKey: `${T}.subtitle`,
      resource: "themes",
      columns: [
        {
          key: "name",
          label: t(`${T}.columns.theme`),
          sortable: true,
          render: (_val: unknown, item: ThemeCard) => (
            <div className="flex min-w-[200px] items-center gap-3">
              {/* Color accent swatch */}
              <div
                className="h-9 w-9 shrink-0 rounded-nx-md border border-nx-line shadow-nx-sm"
                style={{
                  background: item.accentColor
                    ? `linear-gradient(135deg, ${item.accentColor}, color-mix(in srgb, ${item.accentColor} 60%, black))`
                    : "linear-gradient(135deg, var(--nx-accent), color-mix(in srgb, var(--nx-accent) 60%, transparent))",
                }}
                aria-hidden="true"
              />
              <div className="flex min-w-0 flex-col">
                <div className="flex items-center gap-1.5">
                  <span className="truncate text-sm font-semibold text-nx-ink">{item.name}</span>
                  {item.isFeatured && (
                    <Star
                      className="h-3.5 w-3.5 shrink-0 fill-warning text-warning"
                      aria-hidden="true"
                    />
                  )}
                  {item.isNew && (
                    <Badge
                      variant="outline"
                      className="h-3.5 border-success/30 bg-success/10 px-1 py-0 text-[9px] text-success"
                    >
                      {t(`${T}.new`)}
                    </Badge>
                  )}
                  {item.isDeprecated && (
                    <Badge
                      variant="outline"
                      className="h-3.5 border-destructive/30 bg-destructive/10 px-1 py-0 text-[9px] text-destructive"
                    >
                      {t(`${T}.deprecated`)}
                    </Badge>
                  )}
                </div>
                <span className="max-w-[220px] truncate text-xs text-nx-ink-2">
                  {item.description || t(`${T}.noDescription`)}
                </span>
              </div>
            </div>
          ),
        },
        {
          key: "category",
          label: t(`${T}.columns.category`),
          sortable: true,
          render: (_val: unknown, item: ThemeCard) => (
            <Badge variant="outline" className="text-xs capitalize">
              <Palette className="me-1 h-3 w-3" aria-hidden="true" />
              {item.category || t(`${T}.uncategorized`)}
            </Badge>
          ),
        },
        {
          key: "pricingType",
          label: t(`${T}.columns.tier`),
          render: (_val: unknown, item: ThemeCard) => (
            <TierBadge
              isFree={item.isFree}
              pricingType={item.pricingType}
              minTierLevel={item.minTierLevel}
            />
          ),
        },
        {
          key: "features",
          label: t(`${T}.columns.features`),
          render: (_val: unknown, item: ThemeCard) => <FeatureBadges theme={item} />,
        },
        {
          key: "usageCount",
          label: t(`${T}.columns.usage`),
          sortable: true,
          render: (_val: unknown, item: ThemeCard) => (
            <div className="flex items-center gap-3">
              <div className="flex items-center gap-1 text-nx-ink-2">
                <Users className="h-3.5 w-3.5" aria-hidden="true" />
                <span className="text-xs font-medium">{item.usageCount}</span>
              </div>
              <div className="flex items-center gap-1 text-nx-ink-2">
                <Heart className="h-3.5 w-3.5" aria-hidden="true" />
                <span className="text-xs font-medium">{item.likeCount}</span>
              </div>
            </div>
          ),
        },
        {
          key: "isSystem",
          label: t(`${T}.columns.type`),
          render: (_val: unknown, item: ThemeCard) => (
            <Badge
              variant={item.isSystem ? "default" : "outline"}
              className={item.isSystem ? "bg-info text-[10px] text-info-foreground" : "text-[10px]"}
            >
              {item.isSystem ? t(`${T}.type.system`) : t(`${T}.type.custom`)}
            </Badge>
          ),
        },
      ],
      getItemDisplayName: configBase.getItemDisplayName,
      deleteService: configBase.deleteService,
      getActions: (_vmInstance: any, _tFn: any, handleDeleteFn: any): CrudAction<ThemeCard>[] => [
        {
          label: t(`${T}.actions.preview`),
          onClick: (item: ThemeCard) => router.push(`/customizer?preview=${item.slug}`),
          variant: "ghost" as const,
          icon: <Eye className="h-4 w-4" aria-hidden="true" />,
        },
        {
          label: t(`${T}.actions.duplicate`),
          onClick: (item: ThemeCard) => handleDuplicate(item),
          variant: "ghost" as const,
          icon: <Copy className="h-4 w-4" aria-hidden="true" />,
          requiredPermission: "themes:create",
        },
        {
          label: t(`${T}.actions.toggleFavorite`),
          onClick: (item: ThemeCard) => handleToggleFavorite(item),
          variant: "ghost" as const,
          icon: <Star className="h-4 w-4" aria-hidden="true" />,
        },
        {
          label: t(`${T}.actions.deprecate`),
          onClick: (item: ThemeCard) => handleDeprecate(item),
          variant: "ghost" as const,
          icon: <Archive className="h-4 w-4" aria-hidden="true" />,
          requiredPermission: "themes:update",
          confirmTitle: t(`${T}.confirm.deprecateTitle`),
          confirmDescription: t(`${T}.confirm.deprecateDescription`),
          confirmVariant: "default" as const,
        },
        {
          label: t("common.delete"),
          onClick: (item: ThemeCard) => handleDeleteFn?.(item),
          variant: "ghost" as const,
          className: "text-destructive hover:text-destructive",
          icon: <Trash2 className="h-4 w-4" aria-hidden="true" />,
          requiredPermission: "themes:delete",
          confirmTitle: t(`${T}.confirm.deleteTitle`),
          confirmDescription: t(`${T}.confirm.deleteDescription`),
          confirmVariant: "destructive" as const,
        },
      ],
    }),
    [t, configBase, handleDuplicate, handleDeprecate, handleToggleFavorite, router]
  );

  return (
    <div className="space-y-6">
      {/* ── Statistics Cards ── */}
      <div className="grid grid-cols-2 gap-4 sm:grid-cols-3 lg:grid-cols-5">
        <StatCard
          icon={Palette}
          tone="neutral"
          label={t(`${T}.stats.total`)}
          value={statistics.total}
        />
        <StatCard
          icon={Sparkles}
          tone="success"
          label={t(`${T}.stats.free`)}
          value={statistics.free}
        />
        <StatCard
          icon={Star}
          tone="warning"
          label={t(`${T}.stats.featured`)}
          value={statistics.featured}
        />
        <StatCard
          icon={TrendingUp}
          tone="info"
          label={t(`${T}.stats.system`)}
          value={statistics.system}
        />
        <StatCard
          icon={Archive}
          tone="danger"
          label={t(`${T}.stats.deprecated`)}
          value={statistics.deprecated}
        />
      </div>

      {/* ── CRUD Table ── */}
      <GenericCrudView viewModel={vm} config={config} />
    </div>
  );
}

/**
 * Customization Module DI Container
 *
 * Provides dependency injection for customization submodules:
 * Branding, Customizer Studio, Tenant Settings, Menus, Themes
 *
 * Aligns with the Customization microservice backend.
 * Backend API: CUSTOMIZATION
 */
import { getModuleApiService } from "@core/services/api-factory";

// Services
import { CustomizationService } from "./branding/src/data/services/CustomizationService";
import { TenantSettingsService } from "./tenant-settings/src/data/services/TenantSettingsService";
import { MenuService } from "./menus/src/data/services/MenuService";
import { ThemeMarketplaceService } from "./branding/src/data/services/ThemeMarketplaceService";
import { ThemeBundleService } from "./branding/src/data/services/ThemeBundleService";

// Repositories
import { CustomizationRepository } from "./branding/src/data/repositories/CustomizationRepository";
import { TenantSettingsRepository } from "./tenant-settings/src/data/repositories/TenantSettingsRepository";
import { MenuRepository } from "./menus/src/data/repositories/MenuRepository";
import { ThemeMarketplaceRepository } from "./branding/src/data/repositories/ThemeMarketplaceRepository";
import { ThemeBundleRepository } from "./branding/src/data/repositories/ThemeBundleRepository";

// Interfaces
import type { ICustomizationRepository } from "./branding/src/domain/interfaces/ICustomizationRepository";
import type { ICustomizationService } from "./branding/src/domain/interfaces/ICustomizationService";
import type { ITenantSettingsRepository } from "./tenant-settings/src/domain/interfaces/ITenantSettingsRepository";
import type { ITenantSettingsService } from "./tenant-settings/src/domain/interfaces/ITenantSettingsService";
import type { IMenuRepository } from "./menus/src/domain/interfaces/IMenuRepository";
import type { IThemeMarketplaceRepository } from "./branding/src/domain/interfaces/IThemeMarketplaceRepository";
import type { IThemeBundleRepository } from "./branding/src/domain/interfaces/IThemeBundleRepository";

export interface CustomizationContainer {
  // Services (directly exposed for settings/studio layers)
  customizationService: ICustomizationService;
  tenantSettingsService: ITenantSettingsService;
  // Repositories
  customizationRepository: ICustomizationRepository;
  tenantSettingsRepository: ITenantSettingsRepository;
  menuRepository: IMenuRepository;
  themeMarketplaceRepository: IThemeMarketplaceRepository;
  themeBundleRepository: IThemeBundleRepository;
}

let _container: CustomizationContainer | null = null;

/**
 * Get the customization container (lazy initialization)
 * Uses CUSTOMIZATION API service — separate microservice
 */
export function getCustomizationContainer(): CustomizationContainer {
  if (typeof window === "undefined") {
    const dummyProxy = new Proxy({} as any, {
      get() {
        return () => Promise.resolve({});
      },
    });
    return {
      customizationService: dummyProxy,
      tenantSettingsService: dummyProxy,
      customizationRepository: dummyProxy,
      tenantSettingsRepository: dummyProxy,
      menuRepository: dummyProxy,
      themeMarketplaceRepository: dummyProxy,
      themeBundleRepository: dummyProxy,
    };
  }

  if (!_container) {
    const apiService = getModuleApiService("CUSTOMIZATION");

    const customizationService = new CustomizationService(apiService);
    const tenantSettingsService = new TenantSettingsService(apiService);

    _container = {
      customizationService,
      tenantSettingsService,
      customizationRepository: new CustomizationRepository(customizationService),
      tenantSettingsRepository: new TenantSettingsRepository(tenantSettingsService),
      menuRepository: new MenuRepository(new MenuService(apiService)),
      themeMarketplaceRepository: new ThemeMarketplaceRepository(
        new ThemeMarketplaceService(apiService)
      ),
      themeBundleRepository: new ThemeBundleRepository(new ThemeBundleService(apiService)),
    };
  }

  return _container;
}

/**
 * Customization container accessor (for use in components)
 */
export const customizationContainer = {
  get customizationService() {
    return getCustomizationContainer().customizationService;
  },
  get customizationRepository() {
    return getCustomizationContainer().customizationRepository;
  },
  get tenantSettingsService() {
    return getCustomizationContainer().tenantSettingsService;
  },
  get tenantSettingsRepository() {
    return getCustomizationContainer().tenantSettingsRepository;
  },
  get menuRepository() {
    return getCustomizationContainer().menuRepository;
  },
  get themeMarketplaceRepository() {
    return getCustomizationContainer().themeMarketplaceRepository;
  },
  get themeBundleRepository() {
    return getCustomizationContainer().themeBundleRepository;
  },
};

/**
 * Customize Panel
 *
 * Right panel: inline editing for the selected menu item's overrides.
 * Shows name EN/AR, order, parent picker, hidden toggle.
 * Includes base values as reference and save/reset buttons.
 */
"use client";

import { useState, useMemo } from "react";
import { useI18n } from "@core/providers/i18n-provider";
import { Button } from "@core/ui/button";
import { Input } from "@core/ui/input";
import { Label } from "@core/ui/label";
import { Switch } from "@core/ui/switch";
import { Card, CardContent, CardHeader, CardTitle } from "@core/ui/card";
import { Separator } from "@core/ui/separator";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@core/ui/select";
import { EmptyState } from "@core/ui/empty-state";
import { resolveBilingualLabel } from "@core/common/utils";
import type { MenuTreeNode, MenuItemOverrideInfo } from "../../domain/entities/MenuItem";
import type { OverrideFormData, FlatMenuItem } from "../viewmodels/useMenuCustomizeViewModel";
import {
  Save,
  RotateCcw,
  FileText,
  FolderOpen,
  EyeOff,
  Eye,
  ArrowRight,
  ArrowLeft,
} from "lucide-react";

/* -------------------------------------------------------------------------- */
/*  Props                                                                      */
/* -------------------------------------------------------------------------- */

interface CustomizePanelProps {
  selectedNode: MenuTreeNode | null;
  selectedOverride: MenuItemOverrideInfo | null;
  formData: OverrideFormData | null;
  parentOptions: FlatMenuItem[];
  language: string;
  onSave: (data: OverrideFormData) => void;
  isSaving: boolean;
}

/* -------------------------------------------------------------------------- */
/*  Component                                                                  */
/* -------------------------------------------------------------------------- */

export function CustomizePanel({
  selectedNode,
  selectedOverride,
  formData,
  parentOptions,
  language,
  onSave,
  isSaving,
}: CustomizePanelProps) {
  const { t, direction } = useI18n();
  // Shows a value transforming into another — must follow reading direction.
  const TransformIcon = direction === "rtl" ? ArrowLeft : ArrowRight;

  // Local form state
  const [nameEn, setNameEn] = useState("");
  const [nameAr, setNameAr] = useState("");
  const [orderOverride, setOrderOverride] = useState<string>("");
  const [parentId, setParentId] = useState<string>("__none__");
  const [isHidden, setIsHidden] = useState(false);

  // Reset form when selection or override data changes
  const [prevFormData, setPrevFormData] = useState(formData);
  if (formData !== prevFormData) {
    setPrevFormData(formData);
    if (formData) {
      setNameEn(formData.nameEn);
      setNameAr(formData.nameAr);
      setOrderOverride(formData.orderOverride != null ? String(formData.orderOverride) : "");
      setParentId(formData.parentMenuItemIdOverride ?? "__none__");
      setIsHidden(formData.isHidden);
    }
  }

  // Check if form has changes compared to current override
  const hasChanges = useMemo(() => {
    if (!formData) return false;
    return (
      nameEn !== formData.nameEn ||
      nameAr !== formData.nameAr ||
      (orderOverride !== "" ? Number(orderOverride) : null) !== formData.orderOverride ||
      (parentId !== "__none__" ? parentId : null) !== formData.parentMenuItemIdOverride ||
      isHidden !== formData.isHidden
    );
  }, [nameEn, nameAr, orderOverride, parentId, isHidden, formData]);

  const handleSave = () => {
    onSave({
      nameEn,
      nameAr,
      orderOverride: orderOverride !== "" ? Number(orderOverride) : null,
      parentMenuItemIdOverride: parentId !== "__none__" ? parentId : null,
      isHidden,
    });
  };

  const handleReset = () => {
    if (formData) {
      setNameEn(formData.nameEn);
      setNameAr(formData.nameAr);
      setOrderOverride(formData.orderOverride != null ? String(formData.orderOverride) : "");
      setParentId(formData.parentMenuItemIdOverride ?? "__none__");
      setIsHidden(formData.isHidden);
    }
  };

  // ── Empty state ─────────────────────────────────────────────────────
  if (!selectedNode) {
    return (
      <Card>
        <CardContent>
          <EmptyState
            bare
            size="sm"
            icon={FileText}
            title={t("menus.selectItemToCustomize")}
            description={t("menus.selectItemHint")}
          />
        </CardContent>
      </Card>
    );
  }

  const displayName = resolveBilingualLabel(selectedNode.nameEn, selectedNode.nameAr, language);
  const hasChildren = selectedNode.children.length > 0;

  return (
    <Card>
      <CardHeader className="pb-4">
        <div className="flex items-center gap-2">
          {hasChildren ? (
            <FolderOpen className="h-5 w-5 shrink-0 text-nx-accent" aria-hidden="true" />
          ) : (
            <FileText className="h-5 w-5 shrink-0 text-nx-ink-3" aria-hidden="true" />
          )}
          <div className="min-w-0">
            <CardTitle className="truncate text-base">{displayName}</CardTitle>
            <p className="mt-0.5 text-xs text-nx-ink-3">{t("menus.customizeDesc")}</p>
          </div>
        </div>
      </CardHeader>

      <CardContent className="space-y-5">
        {/* ── Display Name Section ──────────────────── */}
        <div className="space-y-3">
          <h4 className="text-xs font-semibold uppercase tracking-wider text-nx-ink-3">
            {t("menus.overrideRename")}
          </h4>

          <div className="space-y-2">
            <div>
              <Label htmlFor="nameEn" className="text-xs">
                {t("menus.nameEn")}
              </Label>
              <Input
                id="nameEn"
                value={nameEn}
                onChange={(e) => setNameEn(e.target.value)}
                placeholder={selectedNode.nameEn}
                className="mt-1 h-8 text-sm"
              />
              {nameEn && nameEn !== selectedNode.nameEn && (
                <div className="mt-1 flex items-center gap-1.5 text-[10px] text-nx-ink-3">
                  <span className="line-through">{selectedNode.nameEn}</span>
                  <TransformIcon className="h-2.5 w-2.5" aria-hidden="true" />
                  <span className="font-medium text-nx-accent">{nameEn}</span>
                </div>
              )}
            </div>

            <div>
              <Label htmlFor="nameAr" className="text-xs">
                {t("menus.nameAr")}
              </Label>
              <Input
                id="nameAr"
                value={nameAr}
                onChange={(e) => setNameAr(e.target.value)}
                placeholder={selectedNode.nameAr}
                className="mt-1 h-8 text-sm"
                dir="rtl"
              />
              {nameAr && nameAr !== selectedNode.nameAr && (
                <div className="mt-1 flex items-center gap-1.5 text-[10px] text-nx-ink-3">
                  <span className="line-through">{selectedNode.nameAr}</span>
                  <TransformIcon className="h-2.5 w-2.5" aria-hidden="true" />
                  <span className="font-medium text-nx-accent">{nameAr}</span>
                </div>
              )}
            </div>
          </div>
        </div>

        <Separator />

        {/* ── Display Order Section ─────────────────── */}
        <div className="space-y-2">
          <h4 className="text-xs font-semibold uppercase tracking-wider text-nx-ink-3">
            {t("menus.overrideOrder")}
          </h4>
          <div>
            <Input
              type="number"
              value={orderOverride}
              onChange={(e) => setOrderOverride(e.target.value)}
              placeholder={String(selectedNode.order)}
              className="h-8 w-32 text-sm"
              min={0}
            />
            <p className="mt-1 text-[10px] text-nx-ink-3">{t("menus.orderHint")}</p>
          </div>
        </div>

        <Separator />

        {/* ── Parent Override Section ───────────────── */}
        <div className="space-y-2">
          <h4 className="text-xs font-semibold uppercase tracking-wider text-nx-ink-3">
            {t("menus.overrideParent")}
          </h4>
          <Select value={parentId} onValueChange={setParentId}>
            <SelectTrigger className="h-8 w-full text-sm">
              <SelectValue placeholder={t("menus.keepCurrentParent")} />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="__none__">{t("menus.keepCurrentParent")}</SelectItem>
              <SelectItem value="__root__">{t("menus.rootLevel")}</SelectItem>
              {parentOptions.map((item) => (
                <SelectItem key={item.id} value={item.id}>
                  <span style={{ paddingInlineStart: `${item.depth * 12}px` }}>
                    {resolveBilingualLabel(item.nameEn, item.nameAr, language)}
                  </span>
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        <Separator />

        {/* ── Visibility Section ───────────────────── */}
        <div className="space-y-2">
          <h4 className="text-xs font-semibold uppercase tracking-wider text-nx-ink-3">
            {t("menus.visibility")}
          </h4>
          <div className="flex items-center justify-between rounded-nx-md border border-nx-line p-3">
            <div className="flex items-center gap-2">
              {isHidden ? (
                <EyeOff className="h-4 w-4 text-destructive" aria-hidden="true" />
              ) : (
                <Eye className="h-4 w-4 text-success" aria-hidden="true" />
              )}
              <span className="text-sm text-nx-ink">
                {isHidden ? t("menus.itemHidden") : t("menus.itemVisible")}
              </span>
            </div>
            <Switch checked={!isHidden} onCheckedChange={(checked) => setIsHidden(!checked)} />
          </div>
        </div>

        <Separator />

        {/* ── Actions ──────────────────────────────── */}
        <div className="flex items-center gap-2 pt-1">
          <Button
            onClick={handleSave}
            disabled={!hasChanges}
            loading={isSaving}
            className="flex-1"
            size="sm"
          >
            {!isSaving && <Save className="me-1.5 h-4 w-4" aria-hidden="true" />}
            {t("common.save")}
          </Button>
          <Button variant="outline" onClick={handleReset} disabled={!hasChanges} size="sm">
            <RotateCcw className="me-1.5 h-4 w-4" aria-hidden="true" />
            {t("common.reset")}
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

/**
 * Menu Form Dialog
 *
 * Bilingual create / edit form for menu items.
 * Uses GenericModal + GenericForm for consistent form handling and working selects.
 * Supports workspace assignment for the Nexus dual-rail navigation system.
 */
"use client";

import { useMemo } from "react";
import { useI18n } from "@core/providers/i18n-provider";
import { GenericModal } from "@core/crud/components/generic-modal";
import { GenericForm, type FieldConfig } from "@core/ui/forms/generic-form";
import type { MenuTreeNode } from "../../domain/entities/MenuItem";
import type {
  CreateMenuItemRequest,
  UpdateMenuItemRequest,
} from "../../domain/entities/MenuItemRequests";
import { PAGE_REGISTRY } from "@core/common/pageRegistry";
import { useWorkspace } from "@core/providers/workspace-provider";
import { resolveBilingualLabel } from "@core/common/utils";

/* -------------------------------------------------------------------------- */
/*  Props                                                                      */
/* -------------------------------------------------------------------------- */

export interface MenuFormDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  mode: "create" | "edit";
  parentNode?: MenuTreeNode | null;
  editNode?: MenuTreeNode | null;
  onSubmit: (
    data: CreateMenuItemRequest | { id: string; request: UpdateMenuItemRequest }
  ) => Promise<void>;
  isPending: boolean;
}

/* -------------------------------------------------------------------------- */
/*  Constants                                                                   */
/* -------------------------------------------------------------------------- */

const CUSTOM_HREF_VALUE = "__custom__";

/* -------------------------------------------------------------------------- */
/*  Component                                                                  */
/* -------------------------------------------------------------------------- */

export function MenuFormDialog({
  open,
  onOpenChange,
  mode,
  parentNode,
  editNode,
  onSubmit,
  isPending,
}: MenuFormDialogProps) {
  const { t, language } = useI18n();
  const { workspaceGroups } = useWorkspace();

  // ── Workspace options ─────────────────────────────────────────────
  const workspaceOptions = useMemo(() => {
    const opts = workspaceGroups.map((ws) => ({
      value: ws.workspaceId,
      label: resolveBilingualLabel(ws.workspaceNameEn, ws.workspaceNameAr || ws.workspaceNameEn, language),
    }));
    // Prepend "Global (all workspaces)" option
    opts.unshift({
      value: "",
      label: t("menus.workspaceGlobal"),
    });
    return opts;
  }, [workspaceGroups, language, t]);

  // ── Build page options from PAGE_REGISTRY ──────────────────────────
  const pageOptions = useMemo(() => {
    const opts = PAGE_REGISTRY.map((page) => ({
      value: page.href,
      label: `${resolveBilingualLabel(page.labelEn, page.labelAr, language)}  ${page.href}`,
    }));
    // Add "Custom URL" option at the end
    opts.push({
      value: CUSTOM_HREF_VALUE,
      label: t("menus.customHref"),
    });
    return opts;
  }, [language, t]);

  // ── Check if an href matches a registered page ─────────────────────
  const isRegisteredPage = (h: string) => PAGE_REGISTRY.some((p) => p.href === h);

  // ── Compute initial values ─────────────────────────────────────────
  const initialValues = useMemo(() => {
    if (mode === "edit" && editNode) {
      const isCustom = !!editNode.href && !isRegisteredPage(editNode.href);
      return {
        href: isCustom ? CUSTOM_HREF_VALUE : (editNode.href ?? ""),
        customHref: isCustom ? editNode.href : "",
        slug: editNode.slug,
        nameEn: editNode.nameEn,
        nameAr: editNode.nameAr,
        icon: editNode.icon ?? "",
        resource: editNode.resource ?? "",
        workspaceId: editNode.workspaceId ?? "",
      };
    }
    return {
      href: "",
      customHref: "",
      slug: "",
      nameEn: "",
      nameAr: "",
      icon: "",
      resource: "",
      workspaceId: "",
    };
  }, [mode, editNode]);

  // ── Define form fields ─────────────────────────────────────────────
  const fields: FieldConfig[] = useMemo(
    () => [
      {
        name: "href",
        label: t("menus.href"),
        type: "searchable-select",
        options: pageOptions,
        placeholder: t("menus.selectPage"),
        searchPlaceholder: t("common.search"),
        onChange: (value: any, formData: Record<string, any>) => {
          if (value === CUSTOM_HREF_VALUE) {
            return { ...formData, href: CUSTOM_HREF_VALUE };
          }
          // Auto-fill from page definition
          const page = PAGE_REGISTRY.find((p) => p.href === value);
          if (page) {
            const updates: Record<string, any> = { ...formData, href: value, customHref: "" };
            if (!formData.slug?.trim())
              updates.slug = page.href.replace(/^\//, "").replace(/\//g, "-");
            if (!formData.nameEn?.trim()) updates.nameEn = page.labelEn;
            if (!formData.nameAr?.trim()) updates.nameAr = page.labelAr;
            if (!formData.icon?.trim() && page.icon) updates.icon = page.icon;
            if (!formData.resource?.trim() && page.resource) updates.resource = page.resource;
            return updates;
          }
          return { ...formData, href: value, customHref: "" };
        },
      },
      {
        name: "customHref",
        label: t("menus.customHref"),
        type: "text",
        placeholder: "/custom-page",
        isVisible: (formData) => formData.href === CUSTOM_HREF_VALUE,
      },
      {
        name: "slug",
        label: t("menus.slug"),
        type: "text",
        required: true,
        placeholder: "dashboard",
      },
      {
        name: "nameEn",
        label: t("menus.nameEn"),
        type: "text",
        required: true,
        placeholder: "Dashboard",
      },
      {
        name: "nameAr",
        label: t("menus.nameAr"),
        type: "text",
        placeholder: "لوحة التحكم",
      },
      {
        name: "icon",
        label: t("menus.icon"),
        type: "text",
        placeholder: "LayoutDashboard",
      },
      {
        name: "resource",
        label: t("menus.resource"),
        type: "text",
        placeholder: "users",
      },
      // ── Workspace assignment (only shown when workspaces exist) ──
      ...(workspaceGroups.length > 0
        ? [
            {
              name: "workspaceId",
              label: t("menus.workspace"),
              type: "select" as const,
              options: workspaceOptions,
              placeholder: t("menus.workspaceGlobal"),
            },
          ]
        : []),
    ],
    [t, pageOptions, workspaceGroups, workspaceOptions]
  );

  // ── Dialog title / description ─────────────────────────────────────
  const title =
    mode === "create"
      ? parentNode
        ? t("menus.addChildTitle")
        : t("menus.createTitle")
      : t("menus.editTitle");

  const description =
    mode === "create" && parentNode
      ? `${t("menus.addChildDesc")} "${parentNode.nameEn}"`
      : mode === "create"
        ? t("menus.createDesc")
        : t("menus.editDesc");

  // ── Handle submit ──────────────────────────────────────────────────
  const handleSubmit = async (data: Record<string, any>) => {
    const resolvedHref =
      data.href === CUSTOM_HREF_VALUE
        ? data.customHref?.trim() || undefined
        : data.href?.trim() || undefined;

    const workspaceId = data.workspaceId?.trim() || undefined;

    if (mode === "create") {
      await onSubmit({
        slug: data.slug.trim(),
        nameEn: data.nameEn.trim(),
        nameAr: data.nameAr?.trim() || data.nameEn.trim(),
        href: resolvedHref,
        icon: data.icon?.trim() || undefined,
        parentMenuItemId: parentNode?.id,
        resource: data.resource?.trim() || undefined,
        workspaceId,
      } as CreateMenuItemRequest);
    } else if (editNode) {
      await onSubmit({
        id: editNode.id,
        request: {
          slug: data.slug.trim(),
          nameEn: data.nameEn.trim(),
          nameAr: data.nameAr?.trim() || data.nameEn.trim(),
          href: resolvedHref,
          icon: data.icon?.trim() || undefined,
          order: editNode.order,
          parentMenuItemId: editNode.parentMenuItemId,
          resource: data.resource?.trim() || undefined,
          isActive: editNode.isActive,
          workspaceId,
        },
      });
    }
    onOpenChange(false);
  };

  return (
    <GenericModal
      open={open}
      onOpenChange={onOpenChange}
      title={title}
      description={description}
      size="md"
      formKey={`menu-form-${mode}-${editNode?.id ?? "new"}`}
    >
      <GenericForm
        key={`${mode}-${editNode?.id ?? "new"}`}
        fields={fields}
        initialValues={initialValues}
        onSubmit={handleSubmit}
        onCancel={() => onOpenChange(false)}
      />
    </GenericModal>
  );
}

