/**
 * RecycleBin ViewModel
 *
 * Handles all state management for the RecycleBin view.
 * Uses useQuery for fetching grouped data + custom restore mutation.
 * Provides tab management, client-side pagination, and search.
 *
 * SOLID: Single Responsibility - data fetching, tab state, pagination, restore action
 */
"use client";

import { useState, useMemo, useCallback } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { ecosystemContainer } from "@modules/ecosystem/di";
import { useI18n } from "@core/providers/i18n-provider";
import { usePermissions } from "@core/hooks/use-permission";
import { useEnhancedToast } from "@core/hooks/use-enhanced-toast";
import { SYSTEM_PERMISSIONS } from "@core/common/types/permissions";
import type { DeletedItem } from "../../domain/entities/DeletedItem";
import type { DeletedItemsGrouped } from "../../domain/interfaces/IRecycleBinRepository";

/**
 * Exported type defining parameters and fields for tab type configurations.
 */
export type TabType = "tenants" | "admins" | "users" | "roles" | "userGroups";

const RECYCLE_BIN_QUERY_KEY = ["recycle-bin"] as const;
const DEFAULT_PAGE_SIZE = 10;

/**
 * React hook/ViewModel orchestrating state and data flows for recycle bin view model.
 * Manages TanStack Query hooks, query cache keys, and repository fetch requests.
 */
export function useRecycleBinViewModel() {
  const { recycleBinRepository } = ecosystemContainer;
  const { t } = useI18n();
  const queryClient = useQueryClient();
  const permissions = usePermissions();
  const { success, error: toastError } = useEnhancedToast();

  // Tab state
  const [activeTab, setActiveTab] = useState<TabType>("tenants");

  // Per-tab pagination state
  const [tabPages, setTabPages] = useState<Record<TabType, number>>({
    tenants: 1,
    admins: 1,
    users: 1,
    roles: 1,
    userGroups: 1,
  });

  const [pageSize, setPageSize] = useState(DEFAULT_PAGE_SIZE);

  // Search state
  const [searchValue, setSearchValue] = useState("");

  // Restore dialog state
  const [restoreDialog, setRestoreDialog] = useState<{
    open: boolean;
    entityType: string;
    ids: string[];
    isPending: boolean;
  }>({
    open: false,
    entityType: "",
    ids: [],
    isPending: false,
  });

  // ============ Data Fetching ============
  const { data, isLoading, error } = useQuery<DeletedItemsGrouped>({
    queryKey: [...RECYCLE_BIN_QUERY_KEY],
    queryFn: () => recycleBinRepository.getAll(),
  });

  // ============ Restore Mutation ============
  const restoreMutation = useMutation({
    mutationFn: ({
      entityType,
      id,
      restoreAdmins,
    }: {
      entityType: string;
      id: string;
      restoreAdmins?: boolean;
    }) => recycleBinRepository.restore(entityType, id, restoreAdmins),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: [...RECYCLE_BIN_QUERY_KEY] });
      success({
        title: t("recycleBin.restored"),
        description: t("recycleBin.restoredDesc"),
      });
    },
    onError: (err: Error) => {
      toastError({
        title: t("common.error"),
        description: err.message,
      });
    },
  });

  // ============ Bulk Restore Mutation ============
  const bulkRestoreMutation = useMutation({
    mutationFn: (items: { entityType: string; id: string; restoreAdmins?: boolean }[]) =>
      recycleBinRepository.bulkRestore(items),
    onSuccess: (count) => {
      queryClient.invalidateQueries({ queryKey: [...RECYCLE_BIN_QUERY_KEY] });
      success({
        title: t("recycleBin.restored"),
        description: t("recycleBin.bulkRestoredDesc", { count }),
      });
    },
    onError: (err: Error) => {
      toastError({
        title: t("common.error"),
        description: err.message,
      });
    },
  });

  // ============ Computed Data ============
  const tabCounts = useMemo(
    () => ({
      tenants: data?.tenants?.length ?? 0,
      admins: data?.admins?.length ?? 0,
      users: data?.users?.length ?? 0,
      roles: data?.roles?.length ?? 0,
      userGroups: data?.userGroups?.length ?? 0,
    }),
    [data]
  );

  const totalCount = data?.totalCount ?? 0;

  // All items for the active tab (before search/pagination)
  const allTabItems: DeletedItem[] = useMemo(() => {
    if (!data) return [];
    return data[activeTab] ?? [];
  }, [data, activeTab]);

  // Filtered by search
  const filteredItems: DeletedItem[] = useMemo(() => {
    if (!searchValue.trim()) return allTabItems;
    const q = searchValue.toLowerCase();
    return allTabItems.filter(
      (item) =>
        item.name?.toLowerCase().includes(q) ||
        item.email?.toLowerCase().includes(q) ||
        item.tenantName?.toLowerCase().includes(q)
    );
  }, [allTabItems, searchValue]);

  // Client-side pagination
  const pagesCount = Math.max(1, Math.ceil(filteredItems.length / pageSize));
  // Clamp to the last valid page — a restore/bulk-restore can shrink filteredItems
  // below the page we were sitting on, which would otherwise render an empty list
  // while still claiming to be on a page past the new end (e.g. "page 3 of 2").
  const currentPage = Math.min(tabPages[activeTab], pagesCount);

  const paginatedItems: DeletedItem[] = useMemo(() => {
    const start = (currentPage - 1) * pageSize;
    return filteredItems.slice(start, start + pageSize);
  }, [filteredItems, currentPage, pageSize]);

  // ============ Pagination handlers ============
  const changePage = useCallback(
    (page: number) => {
      setTabPages((prev) => ({ ...prev, [activeTab]: page }));
    },
    [activeTab]
  );

  const changePageSize = useCallback((size: number) => {
    setPageSize(size);
    // Reset all tabs to page 1 when page size changes
    setTabPages({ tenants: 1, admins: 1, users: 1, roles: 1, userGroups: 1 });
  }, []);

  const handleTabChange = useCallback((tab: TabType) => {
    setActiveTab(tab);
    setSearchValue(""); // Clear search when switching tabs
  }, []);

  const handleSearchChange = useCallback(
    (value: string) => {
      setSearchValue(value);
      // Reset page to 1 when searching
      setTabPages((prev) => ({ ...prev, [activeTab]: 1 }));
    },
    [activeTab]
  );

  // ============ Permissions ============
  const canRestore = permissions.has(SYSTEM_PERMISSIONS.RECYCLE_BIN_RESTORE);

  // ============ Handlers ============

  const triggerRestore = useCallback(
    (entityType: string, id: string) => {
      if (entityType.toLowerCase() === "usergroup" || entityType.toLowerCase() === "usergroups") {
        setRestoreDialog({ open: true, entityType, ids: [id], isPending: false });
      } else {
        restoreMutation.mutate({ entityType, id });
      }
    },
    [restoreMutation]
  );

  const triggerBulkRestore = useCallback(
    (ids: string[]) => {
      if (ids.length === 0) return;

      // Determine entity type from the first item (all selected items should be of the same type via the active tab)
      const firstItem = allTabItems.find((ci) => ci.id === ids[0]);
      if (!firstItem) return;

      if (
        firstItem.entityType.toLowerCase() === "usergroup" ||
        firstItem.entityType.toLowerCase() === "usergroups"
      ) {
        setRestoreDialog({ open: true, entityType: firstItem.entityType, ids, isPending: false });
      } else {
        const items = ids
          .map((id) => {
            const item = allTabItems.find((ci) => ci.id === id);
            return item ? { entityType: item.entityType.toLowerCase(), id: item.id } : null;
          })
          .filter((i): i is { entityType: string; id: string } => i !== null);
        if (items.length > 0) {
          bulkRestoreMutation.mutate(items);
        }
      }
    },
    [allTabItems, bulkRestoreMutation]
  );

  const confirmRestore = useCallback(
    async (restoreAdmins: boolean) => {
      setRestoreDialog((s) => ({ ...s, isPending: true }));
      try {
        if (restoreDialog.ids.length === 1) {
          await restoreMutation.mutateAsync({
            entityType: restoreDialog.entityType,
            id: restoreDialog.ids[0],
            restoreAdmins,
          });
        } else {
          const items = restoreDialog.ids.map((id) => ({
            entityType: restoreDialog.entityType,
            id,
            restoreAdmins,
          }));
          await bulkRestoreMutation.mutateAsync(items);
        }
        setRestoreDialog({ open: false, entityType: "", ids: [], isPending: false });
      } catch (err: any) {
        toastError({ title: t("common.error"), description: err.message });
        setRestoreDialog((s) => ({ ...s, isPending: false }));
      }
    },
    [restoreDialog, restoreMutation, bulkRestoreMutation, toastError, t]
  );

  const handleRestore = useCallback(
    (entityType: string, id: string) => triggerRestore(entityType, id),
    [triggerRestore]
  );

  const handleBulkRestore = useCallback(
    (ids: string[]) => triggerBulkRestore(ids),
    [triggerBulkRestore]
  );

  return {
    // Data
    currentItems: paginatedItems,
    isLoading,
    error: error ? (error as Error).message : null,
    totalCount,

    // Tabs
    activeTab,
    setActiveTab: handleTabChange,
    tabCounts,

    // Search
    searchValue,
    handleSearchChange,

    // Pagination
    page: currentPage,
    pageSize,
    pagesCount,
    filteredCount: filteredItems.length,
    changePage,
    changePageSize,

    // Restore
    canRestore,
    isRestoring: restoreMutation.isPending,
    handleRestore,

    // Bulk Restore
    isBulkRestoring: bulkRestoreMutation.isPending,
    handleBulkRestore,

    // Dialog state
    restoreDialog,
    setRestoreDialog,
    confirmRestore,

    // Refresh
    refreshItems: () => queryClient.invalidateQueries({ queryKey: [...RECYCLE_BIN_QUERY_KEY] }),

    // i18n
    t,
  };
}

/**
 * Manage Roles Dialog
 *
 * Unified dialog for assigning/removing roles using multi-select.
 * Uses "Nuke & Pave" pattern via syncRoles endpoint.
 * Enforces "Strict Context" (no dropdown) and fixes ID mismatch via Code matching.
 */
"use client";

import { useState, useMemo } from "react";
import { Button } from "@core/ui/button";
import { Label } from "@core/ui/label";
import { Switch } from "@core/ui/switch";
import { GenericModal } from "@core/crud/components/generic-modal";
import { GenericSelect, type GenericSelectOption } from "@core/crud/components/generic-select";
import { ConfirmationDialog } from "@core/ui/confirmation-dialog";
import { LoadingSpinner } from "@core/ui/loading-spinner";
import { Shield } from "lucide-react";
import type { Admin } from "../../domain/entities/Admin";
import { useManageRolesViewModel } from "../viewmodels/useManageRolesViewModel";

interface ManageRolesDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  admin: Admin | null;
  tenantId?: string; // Explicit tenant context (e.g., from drill-down)
}

/**
 * Presentation UI component rendering the manage roles dialog.
 * Arranges layout boundaries and accessibility targets (WCAG, tab index) using the core design library (@core/ui/*). Coordinates text fields, submit indicators, and validation warning messages.
 */
export function ManageRolesDialog({ open, onOpenChange, admin, tenantId }: ManageRolesDialogProps) {
  // Strict Scope Calculation
  const scopeTenantId = tenantId || admin?.tenantId || "";

  const vm = useManageRolesViewModel({ adminId: admin?.id, scopeTenantId, open });
  const { t, rolesData, currentRoles, resolvedExtraRoles, isLoading, isSubmitting } = vm;

  // Form state
  const [selectedRoleIds, setSelectedRoleIds] = useState<string[]>([]);
  const [inheritToChildren, setInheritToChildren] = useState(false);
  // Assigning/removing roles takes effect immediately on Save (nuke & pave) —
  // gate it behind the same confirmation step as "Transfer Protection" and
  // "Resend setup email" elsewhere in this view (F-69).
  const [confirmOpen, setConfirmOpen] = useState(false);

  // Transform available roles to options. Merges in roles resolved by code
  // (see useManageRolesViewModel) that fell outside the first fetched page —
  // otherwise a role the admin already has beyond page 1 would render as a
  // raw, unlabelled id, or be missing entirely (F-68).
  const roleOptions: GenericSelectOption[] = useMemo(() => {
    const byId = new Map<string, GenericSelectOption>();
    (rolesData?.items ?? [])
      .filter((role) => (role.tenantId || "") === scopeTenantId) // Double check strict scope
      .forEach((role) => byId.set(role.id, vm.mapRoleOption(role)));
    resolvedExtraRoles.forEach((role) => {
      if (!byId.has(role.id)) byId.set(role.id, vm.mapRoleOption(role));
    });
    return Array.from(byId.values());
  }, [rolesData, resolvedExtraRoles, scopeTenantId, vm]);

  // Logic: Map Current Roles to Available Options using ROLE CODE
  const rolesLen = rolesData?.items?.length ?? 0;
  const currentLen = currentRoles?.length ?? -1;

  const [prevOpen, setPrevOpen] = useState(open);
  const [prevCurrentRoles, setPrevCurrentRoles] = useState(currentRoles);
  const [prevRolesData, setPrevRolesData] = useState(rolesData);
  const [prevResolvedExtraRoles, setPrevResolvedExtraRoles] = useState(resolvedExtraRoles);
  const [prevScopeTenantId, setPrevScopeTenantId] = useState(scopeTenantId);

  if (
    open !== prevOpen ||
    currentRoles !== prevCurrentRoles ||
    rolesData !== prevRolesData ||
    resolvedExtraRoles !== prevResolvedExtraRoles ||
    scopeTenantId !== prevScopeTenantId
  ) {
    setPrevOpen(open);
    setPrevCurrentRoles(currentRoles);
    setPrevRolesData(rolesData);
    setPrevResolvedExtraRoles(resolvedExtraRoles);
    setPrevScopeTenantId(scopeTenantId);

    if (open && currentRoles && rolesData?.items) {
      const scopedCurrentRoles = currentRoles.filter((r) => (r.tenantId || "") === scopeTenantId);
      const matchedIds: string[] = [];
      scopedCurrentRoles.forEach((cr) => {
        const match = rolesData.items.find((ar) => ar.code === cr.roleCode);
        if (match) matchedIds.push(match.id);
      });
      // Fold in roles resolved by code because the first fetched page didn't
      // contain them — without this, Save (nuke & pave) would silently drop
      // any role the admin has beyond page 1.
      resolvedExtraRoles.forEach((role) => matchedIds.push(role.id));
      setSelectedRoleIds(matchedIds);
      setInheritToChildren(scopedCurrentRoles.some((r) => r.inheritToChildren));
    } else if (open && !currentRoles && !rolesData) {
      setSelectedRoleIds([]);
      setInheritToChildren(false);
    }
  }

  const handleSave = () => {
    setConfirmOpen(true);
  };

  const handleConfirmSave = async () => {
    await vm.syncRoles(selectedRoleIds, inheritToChildren, onOpenChange);
    setConfirmOpen(false);
  };

  return (
    <GenericModal
      open={open}
      onOpenChange={onOpenChange}
      title={t("admin.role.manageTitle")}
      description={`${t("admin.role.manageDescription")} ${admin?.displayName || ""}`}
      size="md"
    >
      <div className="space-y-4 py-2">
        {isLoading ? (
          <LoadingSpinner size="md" />
        ) : (
          <>
            {/* Scope Indicator (Informational Only) */}
            <div className="flex justify-between rounded-nx-sm bg-nx-raised p-2 text-xs text-nx-ink-2">
              <span>{t("admin.role.currentScope")}:</span>
              <span className="font-medium text-nx-ink">
                {scopeTenantId ? t("admin.role.tenantWrapper") : t("admin.role.systemScope")}
              </span>
            </div>

            {/* Role Multi-Selection */}
            <div className="space-y-2">
              <Label className="flex items-center gap-2">
                <Shield className="h-4 w-4" aria-hidden="true" />
                {t("admin.role.selectRoles")} *
              </Label>
              <GenericSelect
                options={roleOptions}
                value={selectedRoleIds}
                onValueChange={(val: string | string[]) =>
                  setSelectedRoleIds(Array.isArray(val) ? val : [val])
                }
                placeholder={t("admin.role.selectRolePlaceholder")}
                type="multi"
                // Server-side search so a role beyond the first fetched page
                // can actually be found (and kept or removed) instead of
                // being invisible in the picker (F-68).
                searchType="server"
                onServerSearch={vm.searchRoles}
              />
              <p className="text-xs text-nx-ink-3">{t("admin.role.selectRolesHelp")}</p>
              <p className="text-xs text-nx-ink-3">{t("roles.priorityHint")}</p>
            </div>

            {/* Inherit Toggle (only if tenant context) */}
            {scopeTenantId && (
              <div className="flex items-center justify-between rounded-nx-lg border border-nx-line p-3">
                <div className="space-y-0.5">
                  <Label htmlFor="inherit" className="cursor-pointer">
                    {t("admin.role.inheritToChildren")}
                  </Label>
                  <p className="text-xs text-nx-ink-3">{t("admin.role.inheritToChildrenHelp")}</p>
                </div>
                <Switch
                  id="inherit"
                  checked={inheritToChildren}
                  onCheckedChange={setInheritToChildren}
                />
              </div>
            )}
          </>
        )}

        <div className="mt-4 flex justify-end gap-2 border-t border-nx-line pt-4">
          <Button variant="outline" onClick={() => onOpenChange(false)} disabled={isSubmitting}>
            {t("common.cancel")}
          </Button>
          <Button onClick={handleSave} loading={isSubmitting} disabled={isLoading}>
            {t("admin.role.saveRoles")}
          </Button>
        </div>
      </div>

      <ConfirmationDialog
        open={confirmOpen}
        onOpenChange={setConfirmOpen}
        variant="warning"
        title={t("admin.role.saveRoles")}
        description={`${t("admin.role.manageDescription")} ${admin?.displayName || ""}`}
        confirmText={t("admin.role.saveRoles")}
        cancelText={t("common.cancel")}
        onConfirm={handleConfirmSave}
        isLoading={isSubmitting}
      />
    </GenericModal>
  );
}

