/**
 * @file useAdminOperations.ts
 * @description Custom React hook managing operations, mutations, and search logic for the Admins feature.
 * Extracted from useAdminsViewModel to comply with the 300-line warning threshold.
 */

import { useCallback } from "react";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { useI18n } from "@core/providers/i18n-provider";
import { useServices } from "@core/providers/service-provider";
import { useEnhancedToast } from "@core/hooks/use-enhanced-toast";
import { useAppStore } from "@core/store/useAppStore";
import { identityContainer } from "@modules/identity/di";
import { qk } from "@core/common/query-keys";
import { useCoreImpersonation } from "@core/hooks/use-auth-bridge";
import type { FieldOption } from "@core/ui/forms/generic-form";
import type { AssignRoleRequest, TransferAdminRequest } from "../../domain/entities/AdminRequests";
import type { Admin } from "../../domain/entities/Admin";
import { resolveBilingualLabel } from "@core/common/utils";

/**
 * Parameters for the useAdminOperations hook.
 */
interface AdminOperationsParams {
  tenantId?: string;
  contextTenantId?: string;
  useMyTenant?: boolean;
  queryKey: string[];
  refreshItems: () => Promise<void>;
}

/**
 * Custom hook encapsulating mutations (create, update, toggle active, reset password, impersonate, transfer)
 * and search helpers for roles and groups.
 *
 * @param params Operational parameters including tenant context and data query key.
 * @returns Mutations, handlers, and search callbacks.
 */
export function useAdminOperations(params: AdminOperationsParams) {
  const { tenantId, contextTenantId, useMyTenant, queryKey, refreshItems } = params;

  const { adminRepository, roleRepository, userGroupRepository } = identityContainer;
  const { t, language } = useI18n();
  const queryClient = useQueryClient();
  const { success, error: toastError } = useEnhancedToast();
  const { authRepository } = useServices();
  const setAuth = useAppStore((state) => state.setAuth);

  // Toggle active status mutation — optimistic update
  const toggleActiveMutation = useMutation({
    mutationFn: ({ id, isActive }: { id: string; isActive: boolean }) =>
      adminRepository.setActive(id, isActive),
    onMutate: async ({ id, isActive }) => {
      await queryClient.cancelQueries({ queryKey: qk.admins.all });
      const previous = queryClient.getQueryData(queryKey);
      queryClient.setQueryData(queryKey, (old: any) => {
        if (!old || typeof old !== "object") return old;
        const data = old as { items?: Array<{ id: string; isActive: boolean }> };
        if (!data.items) return old;
        return {
          ...data,
          items: data.items.map((item) => (item.id === id ? { ...item, isActive } : item)),
        };
      });
      return { previous };
    },
    onError: (err: Error, __, context?: { previous: unknown }) => {
      if (context?.previous !== undefined) {
        queryClient.setQueryData(queryKey, context.previous);
      }
      toastError({ title: t("common.error"), description: err.message });
    },
    onSuccess: (_, { isActive }) => {
      success({
        title: isActive ? t("admin.activated") : t("admin.deactivated"),
        description: isActive ? t("admin.activatedDesc") : t("admin.deactivatedDesc"),
      });
    },
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: qk.admins.all });
    },
  });

  // Assign role mutation
  const assignRoleMutation = useMutation({
    mutationFn: ({ adminId, request }: { adminId: string; request: AssignRoleRequest }) =>
      adminRepository.assignRole(adminId, request),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: qk.admins.all });
      success({
        title: t("admin.role.assigned"),
        description: t("admin.role.assignedDesc"),
      });
    },
    onError: (err: Error) => {
      toastError({ title: t("common.error"), description: err.message });
    },
  });

  // Remove role mutation
  const removeRoleMutation = useMutation({
    mutationFn: ({
      adminId,
      roleId,
      tenantId: rTenantId,
    }: {
      adminId: string;
      roleId: string;
      tenantId?: string;
    }) => adminRepository.removeRole(adminId, roleId, rTenantId),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: qk.admins.all });
      success({
        title: t("admin.role.removed"),
        description: t("admin.role.removedDesc"),
      });
    },
    onError: (err: Error) => {
      toastError({ title: t("common.error"), description: err.message });
    },
  });

  // Reset password mutation
  const resetPasswordMutation = useMutation({
    mutationFn: ({ adminId, newPassword }: { adminId: string; newPassword: string }) =>
      adminRepository.resetPassword(adminId, newPassword),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: qk.admins.all });
      success({
        title: t("admin.passwordReset"),
        description: t("admin.passwordResetDesc"),
      });
    },
    onError: (err: Error) => {
      toastError({ title: t("common.error"), description: err.message });
    },
  });

  // Manual account setup mutation — sets a password directly for an email-invited admin
  // who hasn't activated yet, as an alternative to resending the setup email.
  const manualSetupMutation = useMutation({
    mutationFn: ({
      adminId,
      newPassword,
      confirmPassword,
      mustChangePassword,
    }: {
      adminId: string;
      newPassword: string;
      confirmPassword: string;
      mustChangePassword: boolean;
    }) =>
      adminRepository.manualSetup(adminId, newPassword, confirmPassword, mustChangePassword),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: qk.admins.all });
      success({
        title: t("admin.manualSetupSuccess"),
        description: t("admin.manualSetupSuccessDesc"),
      });
    },
    onError: (err: Error) => {
      toastError({ title: t("common.error"), description: err.message });
    },
  });

  // Impersonation — resolved through the core auth bridge. The previous registry lookup fell back
  // to `startImpersonation: () => {}` whenever the `@modules/auth` barrel had not been imported,
  // which silently turned the "impersonate" action into a no-op button.
  const { startImpersonation, isImpersonationLoading } = useCoreImpersonation();

  // Transfer mutation
  const transferMutation = useMutation({
    mutationFn: ({ id, request }: { id: string; request: TransferAdminRequest }) =>
      adminRepository.transfer(id, request),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: qk.admins.all });
      success({
        title: t("admin.transferred"),
        description: t("admin.transferredDesc"),
      });
    },
    onError: (err: Error) => {
      toastError({ title: t("common.error"), description: err.message });
    },
  });

  // Transfer Protection mutation
  const transferProtectionMutation = useMutation({
    mutationFn: ({ targetAdminId }: { targetAdminId: string }) =>
      adminRepository.transferProtection({ targetAdminId }),
    onSuccess: async () => {
      queryClient.invalidateQueries({ queryKey: qk.admins.all });
      try {
        const user = await authRepository.getMe();
        if (user) {
          setAuth(user, user.permissions || [], []);
        }
      } catch {
        // Silently fail
      }
      success({
        title: t("admin.protectionTransferred"),
        description: t("admin.protectionTransferredDesc"),
      });
    },
    onError: (err: Error) => {
      toastError({ title: t("common.error"), description: err.message });
    },
  });

  // Resend Setup Email mutation
  const resendSetupEmailMutation = useMutation({
    mutationFn: ({ adminId }: { adminId: string }) => adminRepository.resendSetupEmail(adminId),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: qk.admins.all });
      success({
        title: t("admin.setupEmailResent"),
        description: t("admin.setupEmailResentDesc"),
      });
    },
    onError: (err: Error) => {
      toastError({ title: t("common.error"), description: err.message });
    },
  });

  // Bulk mutations
  const bulkActivateMutation = useMutation({
    mutationFn: (ids: string[]) => adminRepository.bulkActivate(ids),
    onSuccess: (count) => {
      queryClient.invalidateQueries({ queryKey: qk.admins.all });
      success({
        title: t("admin.bulk.activated"),
        description: t("admin.bulk.activatedDesc", { count }),
      });
    },
  });

  const bulkDeactivateMutation = useMutation({
    mutationFn: (ids: string[]) => adminRepository.bulkDeactivate(ids),
    onSuccess: (count) => {
      queryClient.invalidateQueries({ queryKey: qk.admins.all });
      success({
        title: t("admin.bulk.deactivated"),
        description: t("admin.bulk.deactivatedDesc", { count }),
      });
    },
  });

  const bulkDeleteMutation = useMutation({
    mutationFn: (ids: string[]) => adminRepository.bulkDelete(ids),
    onSuccess: (count) => {
      queryClient.invalidateQueries({ queryKey: qk.admins.all });
      success({
        title: t("admin.bulk.deleted"),
        description: t("admin.bulk.deletedDesc", { count }),
      });
    },
  });

  // Handlers
  const handleDelete = useCallback(
    async (admin: Admin) => {
      await adminRepository.delete(admin.id);
      await refreshItems();
    },
    [adminRepository, refreshItems]
  );

  const handleToggleActive = useCallback(
    (id: string, isActive: boolean) => toggleActiveMutation.mutateAsync({ id, isActive }),
    [toggleActiveMutation]
  );

  const handleAssignRole = useCallback(
    (adminId: string, request: AssignRoleRequest) =>
      assignRoleMutation.mutateAsync({ adminId, request }),
    [assignRoleMutation]
  );

  const handleRemoveRole = useCallback(
    (adminId: string, roleId: string, rTenantId?: string) =>
      removeRoleMutation.mutateAsync({ adminId, roleId, tenantId: rTenantId }),
    [removeRoleMutation]
  );

  const handleResetPassword = useCallback(
    (adminId: string, newPassword: string) =>
      resetPasswordMutation.mutateAsync({ adminId, newPassword }),
    [resetPasswordMutation]
  );

  const handleRoleSearch = useCallback(
    async (query: string): Promise<FieldOption[]> => {
      try {
        const roleSearchTenantId = tenantId ?? contextTenantId ?? undefined;
        const isExplicitTenant = !!tenantId;
        const result =
          useMyTenant && !isExplicitTenant
            ? await roleRepository.getMyTenantRoles({ search: query, page: 1, pageSize: 20 })
            : await roleRepository.getAll({
                search: query,
                page: 1,
                pageSize: 20,
                tenantId: roleSearchTenantId,
                strict: true,
              });

        return (result.items || []).map((role) => ({
          value: role.id,
          label: resolveBilingualLabel(role.nameEn, role.nameAr, language),
        }));
      } catch {
        return [];
      }
    },
    [roleRepository, tenantId, contextTenantId, language, useMyTenant]
  );

  const handleGroupSearch = useCallback(
    async (query: string): Promise<FieldOption[]> => {
      try {
        const groupSearchTenantId = tenantId ?? contextTenantId ?? undefined;
        const isExplicitTenant = !!tenantId;
        const result =
          useMyTenant && !isExplicitTenant
            ? await userGroupRepository.getMyTenantGroups({
                search: query,
                page: 1,
                pageSize: 20,
              })
            : await userGroupRepository.getAll({
                search: query,
                page: 1,
                pageSize: 20,
                tenantId: groupSearchTenantId,
              });

        return (result.items || []).map((g) => ({
          value: g.id,
          label: resolveBilingualLabel(g.nameEn, g.nameAr, language),
        }));
      } catch {
        return [];
      }
    },
    [userGroupRepository, useMyTenant, tenantId, contextTenantId, language]
  );

  return {
    handleDelete,
    handleToggleActive,
    handleAssignRole,
    handleRemoveRole,
    handleResetPassword,
    handleImpersonate: (id: string) => startImpersonation(id),
    handleTransfer: (id: string, request: TransferAdminRequest) =>
      transferMutation.mutate({ id, request }),
    handleTransferProtection: (targetAdminId: string) =>
      transferProtectionMutation.mutate({ targetAdminId }),
    handleResendSetupEmail: (adminId: string) => resendSetupEmailMutation.mutate({ adminId }),
    handleManualSetup: (
      adminId: string,
      newPassword: string,
      confirmPassword: string,
      mustChangePassword: boolean
    ) =>
      manualSetupMutation.mutateAsync({
        adminId,
        newPassword,
        confirmPassword,
        mustChangePassword,
      }),
    handleBulkActivate: (ids: string[]) => bulkActivateMutation.mutate(ids),
    handleBulkDeactivate: (ids: string[]) => bulkDeactivateMutation.mutate(ids),
    handleBulkDelete: (ids: string[]) => bulkDeleteMutation.mutate(ids),

    isTogglingActive: toggleActiveMutation.isPending,
    isAssigningRole: assignRoleMutation.isPending,
    isRemovingRole: removeRoleMutation.isPending,
    isResettingPassword: resetPasswordMutation.isPending,
    isImpersonating: isImpersonationLoading,
    isTransferring: transferMutation.isPending,
    isTransferringProtection: transferProtectionMutation.isPending,
    isResendingSetupEmail: resendSetupEmailMutation.isPending,
    isManualSettingUp: manualSetupMutation.isPending,
    handleRoleSearch,
    handleGroupSearch,
    t,
  };
}

/**
 * Admin Roles ViewModel
 *
 * Handles logic for Assign/View/Remove roles dialogs.
 * Separates state and data fetching from the UI components.
 */
"use client";

import { useState, useCallback, useMemo } from "react";
import { useQuery } from "@tanstack/react-query";
import { identityContainer } from "@modules/identity/di";
import { useI18n } from "@core/providers/i18n-provider";
import type { Admin, AdminRoleData } from "../../domain/entities/Admin";
import type { AssignRoleRequest } from "../../domain/entities/AdminRequests";
import type { GenericSelectOption } from "@core/crud/components/generic-select";
import { resolveBilingualLabel } from "@core/common/utils";

/**
 * React hook/ViewModel orchestrating state and data flows for admin roles view model.
 * Manages TanStack Query hooks, query cache keys, and repository fetch requests.
 */
export function useAdminRolesViewModel(
  admin: Admin | null,
  onAssignRole: (request: AssignRoleRequest) => Promise<void>,
  onRemoveRole: (roleId: string, tenantId?: string) => Promise<void>,
  forcedTenantId?: string
) {
  const { t, language } = useI18n();
  const { roleRepository, tenantRepository, adminRepository } = identityContainer;

  // Effective tenant context: explicit force > admin's own tenant
  const effectiveTenantId = forcedTenantId || admin?.tenantId;

  // ============ Assign Role Logic ============
  const [assignRoleIds, setAssignRoleIds] = useState<string[]>([]);
  const [assignTenantId, setAssignTenantId] = useState<string>("");
  const [inheritToChildren, setInheritToChildren] = useState(false);

  // Fetch roles for dropdown
  // Trigger fetch when:
  // 1. Dialog is open (enabled: !!admin)
  // 2. effectiveTenantId changes (forced context)
  // 3. assignTenantId changes (user selected scope)
  const targetTenantId = effectiveTenantId || assignTenantId;

  const { data: rolesData, isLoading: isLoadingRoles } = useQuery({
    queryKey: ["roles-for-select", targetTenantId],
    queryFn: () =>
      roleRepository.getAll({
        page: 1,
        pageSize: 100,
        tenantId: targetTenantId || undefined,
        strict: true,
      }),
    enabled: !!admin,
  });

  // Fetch tenants for dropdown (only if no tenant context determined)
  const { data: tenantsTree, isLoading: isLoadingTenants } = useQuery({
    queryKey: ["tenants-tree-for-select"],
    queryFn: () => tenantRepository.getTree(),
    enabled: !!admin && !effectiveTenantId,
  });

  // Transform roles options
  const roleOptions: GenericSelectOption[] = useMemo(
    () =>
      (rolesData?.items ?? []).map((role) => ({
        value: role.id,
        label: resolveBilingualLabel(role.nameEn, role.nameAr, language),
        description: resolveBilingualLabel(
          role.descriptionEn ?? "",
          role.descriptionAr ?? "",
          language
        ),
        uniqueKey: role.code, // Use code for stable selection if IDs rotate
      })),
    [rolesData, language]
  );

  // Transform tenants tree
  // Transform tenants tree
  const transformTenants = useCallback(function transform(nodes: any[]): GenericSelectOption[] {
    return nodes.map((node) => ({
      value: node.id,
      label: node.name,
      children: node.children?.length > 0 ? transform(node.children) : undefined,
    }));
  }, []);

  const tenantOptions: GenericSelectOption[] = useMemo(
    () => [
      { value: "", label: t("admin.role.globalScope") },
      ...(Array.isArray(tenantsTree) ? transformTenants(tenantsTree) : []),
    ],
    [tenantsTree, transformTenants, t]
  );

  const resetAssignForm = useCallback(() => {
    setAssignRoleIds([]);
    setAssignTenantId(effectiveTenantId || "");
    setInheritToChildren(false);
  }, [effectiveTenantId]);

  const handleAssignSubmit = async () => {
    if (assignRoleIds.length === 0) return;

    // AssignRoleRequest only accepts single roleId, so we must loop
    // In a real app, a bulk endpoint would be better
    const promises = assignRoleIds.map((roleId) =>
      onAssignRole({
        roleId: roleId,
        tenantId: assignTenantId || undefined,
        inheritToChildren: assignTenantId ? inheritToChildren : undefined,
      })
    );

    try {
      await Promise.all(promises);
      resetAssignForm();
    } catch (error) {
      // Error is handled by the mutation wrapper in the View,
      // but we catch here to prevent reset if partial failure?
      // For now let it bubble up.
      throw error;
    }
  };

  // ============ View Roles Logic ============
  const {
    data: currentRoles = [],
    isLoading: isLoadingCurrentRoles,
    refetch: refetchRoles,
  } = useQuery({
    queryKey: ["admin-roles", admin?.id],
    queryFn: async (): Promise<AdminRoleData[]> => {
      if (!admin?.id) return [];
      return adminRepository.getRoles(admin.id);
    },
    enabled: !!admin?.id,
  });

  // ============ Exports ============
  return {
    // Data
    roleOptions,
    tenantOptions,
    currentRoles,

    // Loading States
    isLoadingRoles,
    isLoadingTenants,
    isLoadingCurrentRoles,

    // Form State
    assignRoleIds,
    setAssignRoleIds,
    assignTenantId,
    setAssignTenantId,
    inheritToChildren,
    setInheritToChildren,
    effectiveTenantId,

    // Actions
    resetAssignForm,
    handleAssignSubmit,
    refetchRoles,

    t, // Pass t for UI
  };
}

"use client";

import { useMemo } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useI18n } from "@core/providers/i18n-provider";
import { useEnhancedToast } from "@core/hooks/use-enhanced-toast";
import { identityContainer } from "@modules/identity/di";
import { resolveBilingualLabel } from "@core/common/utils";
import type { GenericSelectOption } from "@core/crud/components/generic-select";
import type { SyncRoleAssignment } from "../../domain/interfaces/IAdminRepository";

interface UseManageRolesViewModelProps {
  adminId?: string;
  scopeTenantId: string;
  open: boolean;
}

// Stable empty-array reference. `useQuery`'s `data` is `undefined` whenever the
// query is disabled (the common case — most admins have no roles outside the
// first fetched page, so `missingRoleCodes` stays empty and this query never
// runs). A `= []` default in the destructuring below would mint a NEW array
// every render, and ManageRolesDialog's render-phase state sync compares this
// value by reference (`resolvedExtraRoles !== prevResolvedExtraRoles`) — a
// fresh reference every render makes that comparison never settle, which is
// an infinite render loop ("Too many re-renders").
const EMPTY_RESOLVED_ROLES: never[] = [];

/**
 * React hook/ViewModel orchestrating state and data flows for manage roles view model.
 * Manages TanStack Query hooks, query cache keys, and repository fetch requests.
 */
export function useManageRolesViewModel({
  adminId,
  scopeTenantId,
  open,
}: UseManageRolesViewModelProps) {
  const { t, language } = useI18n();
  const toast = useEnhancedToast();
  const queryClient = useQueryClient();
  const { roleRepository, adminRepository } = identityContainer;

  const mapRoleOption = (role: {
    id: string;
    nameEn: string;
    nameAr: string;
    descriptionEn?: string;
    descriptionAr?: string;
  }): GenericSelectOption => ({
    value: role.id,
    label: resolveBilingualLabel(role.nameEn, role.nameAr, language),
    description: resolveBilingualLabel(role.descriptionEn ?? "", role.descriptionAr ?? "", language),
  });

  // Fetch available roles (first page — default browse list before the admin
  // types a search query)
  const { data: rolesData, isLoading: isLoadingRoles } = useQuery({
    queryKey: ["roles-for-manage", scopeTenantId],
    queryFn: () =>
      scopeTenantId
        ? roleRepository.getAll({
            page: 1,
            pageSize: 100,
            tenantId: scopeTenantId,
            strict: true,
          })
        : roleRepository.getMyTenantRoles({
            page: 1,
            pageSize: 100,
          }),
    enabled: open && !!adminId,
  });

  // Fetch current roles
  const { data: currentRoles, isLoading: isLoadingCurrentRoles } = useQuery({
    queryKey: ["admin-roles", adminId],
    queryFn: async () => {
      if (!adminId) return [];
      return adminRepository.getRoles(adminId);
    },
    enabled: open && !!adminId,
  });

  // ── F-68 fix ────────────────────────────────────────────────────────────
  // Roles are matched by CODE (see ManageRolesDialog header comment — the
  // admin-roles endpoint's roleId doesn't line up with Role.id), against
  // whatever page of roles happened to be fetched above. For a tenant with
  // more than 100 roles, an admin's currently-assigned role can sit outside
  // that page: it goes both invisible in the picker AND silently dropped by
  // the "nuke & pave" syncRoles call on Save, because it was never in
  // `selectedRoleIds` to begin with.
  //
  // Resolve those specific codes individually (cheap — there are normally
  // zero or a handful) so they can be shown with a real label and folded
  // back into the sync payload, instead of just vanishing.
  const scopedCurrentRoles = useMemo(
    () => (currentRoles ?? []).filter((r) => (r.tenantId || "") === scopeTenantId),
    [currentRoles, scopeTenantId]
  );
  const missingRoleCodes = useMemo(() => {
    const fetchedCodes = new Set((rolesData?.items ?? []).map((r) => r.code));
    return Array.from(
      new Set(
        scopedCurrentRoles.filter((r) => !fetchedCodes.has(r.roleCode)).map((r) => r.roleCode)
      )
    );
  }, [scopedCurrentRoles, rolesData]);

  const { data: resolvedExtraRoles = EMPTY_RESOLVED_ROLES, isLoading: isResolvingExtraRoles } = useQuery({
    queryKey: ["roles-for-manage-resolve", scopeTenantId, missingRoleCodes],
    queryFn: async () => {
      const found = await Promise.all(
        missingRoleCodes.map(async (code) => {
          const page = scopeTenantId
            ? await roleRepository.getAll({
                page: 1,
                pageSize: 5,
                tenantId: scopeTenantId,
                search: code,
                strict: true,
              })
            : await roleRepository.getMyTenantRoles({ page: 1, pageSize: 5, search: code });
          return page.items.find((r) => r.code === code) ?? null;
        })
      );
      return found.filter((r): r is NonNullable<typeof r> => !!r);
    },
    enabled: open && !!adminId && missingRoleCodes.length > 0,
  });

  // Sync roles mutation
  const syncMutation = useMutation({
    mutationFn: async ({
      selectedRoleIds,
      inheritToChildren,
    }: {
      selectedRoleIds: string[];
      inheritToChildren: boolean;
    }) => {
      if (!adminId) throw new Error("No admin selected");

      const assignments: SyncRoleAssignment[] = selectedRoleIds.map((roleId) => ({
        roleId,
        tenantId: scopeTenantId || undefined,
        inheritToChildren: scopeTenantId ? inheritToChildren : undefined,
      }));

      await adminRepository.syncRoles(adminId, assignments, scopeTenantId || undefined);
    },
  });

  return {
    t,
    language,
    rolesData,
    currentRoles,
    // Currently-assigned roles resolved by code because they fell outside the
    // first fetched page — merge into both the picker's options and the
    // initial selection so Save can't silently drop them (F-68).
    resolvedExtraRoles,
    mapRoleOption,
    isLoading: isLoadingRoles || isLoadingCurrentRoles || isResolvingExtraRoles,
    // Real server-side search so the picker can find (and the admin can
    // deliberately keep or remove) any role, not just the first 100.
    searchRoles: async (query: string): Promise<GenericSelectOption[]> => {
      try {
        const page = scopeTenantId
          ? await roleRepository.getAll({
              page: 1,
              pageSize: 50,
              tenantId: scopeTenantId,
              search: query,
              strict: true,
            })
          : await roleRepository.getMyTenantRoles({ page: 1, pageSize: 50, search: query });
        return page.items.map(mapRoleOption);
      } catch {
        return [];
      }
    },
    syncRoles: async (
      selectedRoleIds: string[],
      inheritToChildren: boolean,
      onOpenChange: (open: boolean) => void
    ) => {
      try {
        await syncMutation.mutateAsync({ selectedRoleIds, inheritToChildren });
        toast.success({ title: t("admin.role.syncSuccess") });
        queryClient.invalidateQueries({ queryKey: ["admin-roles", adminId] });
        queryClient.invalidateQueries({ queryKey: ["admins"] });
        onOpenChange(false);
      } catch (error: any) {
        toast.error({ title: error?.message || t("common.error") });
      }
    },
    isSubmitting: syncMutation.isPending,
  };
}

