          {/* Admin Scope Badge */}
          {item.enabledForAdmins && (
            <Badge
              variant="outline"
              className="h-5 gap-1 border-[color:color-mix(in_srgb,var(--nx-accent)_30%,transparent)] bg-nx-accent-wash text-[10px] font-medium text-nx-accent"
            >
