/**
 * Presentation UI component rendering the create tenant dialog.
 * Arranges layout boundaries and accessibility targets (WCAG, tab index) using the core design library (@core/ui/*). Coordinates text fields, submit indicators, and validation warning messages.
 */
export function CreateTenantDialog({
  open,
  onOpenChange,
  parentTenant,
  form,
  setForm,
  onSubmit,
  isLoading,
  onSearchEditions,
  cachedEditions = [],
  availablePromotions,
  isLoadingPromotions,
  onEditionChange,
  onSubscriptionTypeChange,
}: CreateTenantDialogProps) {
  const { t } = useI18n();

  // Track selected edition locally to compute subscriptionType options
  const [selectedEditionId, setSelectedEditionId] = useState(form.editionId);
  const [selectedPromotionId, setSelectedPromotionId] = useState("");

  // Reset local state when dialog opens
  const [prevOpen, setPrevOpen] = useState(open);
  const [prevFormEditionId, setPrevFormEditionId] = useState(form.editionId);
  if (open !== prevOpen || form.editionId !== prevFormEditionId) {
    setPrevOpen(open);
    setPrevFormEditionId(form.editionId);
    if (open) {
      setSelectedEditionId(form.editionId);
      setSelectedPromotionId("");
    }
  }

  // Determine if selected promotion requires a code
  const selectedPromo = useMemo(() => {
    if (!selectedPromotionId) return null;
    return availablePromotions.find((p) => p.id === selectedPromotionId) ?? null;
  }, [selectedPromotionId, availablePromotions]);

  const requiresPromoCode = selectedPromo?.requiresCode ?? false;

  const title = parentTenant ? t("tenant.createChild") : t("tenant.createTenant");
  const description = parentTenant
    ? `${t("tenant.createChildDescription")} "${parentTenant.name}".`
    : t("tenant.createDescription");

  const fields: FieldConfig[] = useMemo(
    () => [
      {
        name: "name",
        label: t("tenant.name"),
        type: "text",
        required: true,
        maxLength: 100,
        placeholder: t("tenant.namePlaceholder"),
      },
      {
        name: "code",
        label: t("tenant.code"),
        type: "text",
        required: true,
        placeholder: t("tenant.codePlaceholder"),
        onChange: (val: string, formData: Record<string, unknown>) => ({
          ...formData,
          code: val.toUpperCase(),
        }),
      },
      {
        name: "description",
        label: t("tenant.descriptionLabel"),
        type: "textarea",
        placeholder: t("tenant.descriptionPlaceholder"),
      },
      // ── Step 2: Admin Info ──
      {
        name: "adminEmail",
        label: t("tenant.adminEmail"),
        type: "text",
        required: true,
        placeholder: t("tenant.adminEmailPlaceholder"),
      },
      {
        name: "adminUsername",
        label: t("tenant.adminUsername"),
        type: "text",
        placeholder: t("tenant.adminUsernamePlaceholder"),
      },
      // ── Step 3: Edition & Billing ──
      {
        name: "editionId",
        label: t("tenant.editionLabel"),
        type: "server-select",
        required: true,
        placeholder: t("tenant.editionPlaceholder"),
        searchPlaceholder: t("common.search"),
        searchType: "server",
        onServerSearch: onSearchEditions,
        onChange: (value: string, formData: Record<string, unknown>) => {
          setTimeout(() => {
            setSelectedEditionId(value);
            setSelectedPromotionId("");
            onEditionChange(value);
            // Preserve ALL current user input (name, code, etc.) from formData
            setForm({
              name: formData.name || "",
              code: formData.code || "",
              description: formData.description || "",
              adminEmail: formData.adminEmail || "",
              adminUsername: formData.adminUsername || "",
              editionId: value,
              subscriptionType: "",
              currency: formData.currency || "USD",
              promotionId: "",
              promoCode: "",
            });
          }, 0);
          return { editionId: value, subscriptionType: "", promotionId: "", promoCode: "" };
        },
      },
      {
        name: "subscriptionType",
        label: t("tenant.subscriptionType"),
        type: "select",
        required: true,
        isVisible: (formData: Record<string, unknown>) => {
          if (!formData.editionId) return false;
          const selectedEd = cachedEditions.find((ed) => ed.id === selectedEditionId);
          if (!selectedEd) return true;
          const hasLifetime = selectedEd.allowLifetime !== false;
          const hasMonthly = selectedEd.allowMonthly !== false;
          const hasYearly = selectedEd.allowYearly !== false;
          const hasTrial = selectedEd.allowTrial !== false;
          return hasLifetime || hasMonthly || hasYearly || hasTrial;
        },
        options: (() => {
          const selectedEd = cachedEditions.find((ed) => ed.id === selectedEditionId);
          const opts: { value: string; label: string }[] = [];
          if (selectedEd?.allowLifetime !== false)
            opts.push({
              value: "Lifetime",
              label: t("tenant.subscriptionTypes.lifetime"),
            });
          if (selectedEd?.allowMonthly !== false)
            opts.push({
              value: "Monthly",
              label: t("tenant.subscriptionTypes.monthly"),
            });
          if (selectedEd?.allowYearly !== false)
            opts.push({ value: "Yearly", label: t("tenant.subscriptionTypes.yearly") });
          if (selectedEd?.allowTrial !== false)
            opts.push({
              value: "Trial",
              label: t("tenant.subscriptionTypes.trial"),
            });
          return opts;
        })(),
        onChange: (value: string, formData: Record<string, unknown>) => {
          setTimeout(() => {
            setSelectedPromotionId("");
            onSubscriptionTypeChange(value);
            // Preserve ALL current user input from formData
            setForm({
              name: formData.name || "",
              code: formData.code || "",
              description: formData.description || "",
              adminEmail: formData.adminEmail || "",
              adminUsername: formData.adminUsername || "",
              editionId: formData.editionId || "",
              subscriptionType: value,
              currency: formData.currency || "USD",
              promotionId: "",
              promoCode: "",
            });
          }, 0);
          return { subscriptionType: value, promotionId: "", promoCode: "" };
        },
      },
      {
        name: "currency",
        label: t("tenant.billingCurrency"),
        type: "select",
        required: true,
        isVisible: (formData: Record<string, unknown>) =>
          !!formData.editionId && !!formData.subscriptionType,
        options: SUPPORTED_CURRENCIES.map((c) => ({
          value: c.code,
          label: `${c.flag} ${c.code} — ${c.name}`,
        })),
      },
      // ── Promotion Picker (select dropdown — data from View) ──
      {
        name: "promotionId",
        label: t("tenant.entitlementLabels.promotionsTitle"),
        type: "select",
        loading: isLoadingPromotions,
        isVisible: (formData: Record<string, unknown>) =>
          !!formData.editionId && !!formData.subscriptionType,
        options: [
          {
            value: "__none__",
            label: t("tenant.entitlementLabels.promotionsNoPromotion"),
          },
          ...availablePromotions.map((p) => ({
            value: p.id,
            label: `${p.name} — ${p.type === "Percentage" ? `${p.discountValue}% off` : `$${p.discountValue} off`}${p.requiresCode ? " (Code)" : ""}`,
          })),
        ],
        onChange: (value: string, formData: Record<string, unknown>) => {
          const actualValue = value === "__none__" ? "" : value;
          setTimeout(() => {
            setSelectedPromotionId(actualValue);
            // Preserve ALL current user input from formData
            setForm({
              name: formData.name || "",
              code: formData.code || "",
              description: formData.description || "",
              adminEmail: formData.adminEmail || "",
              adminUsername: formData.adminUsername || "",
              editionId: formData.editionId || "",
              subscriptionType: formData.subscriptionType || "",
              currency: formData.currency || "USD",
              promotionId: actualValue,
              promoCode: "",
            });
          }, 0);
          return { promotionId: value, promoCode: "" };
        },
      },
      // ── Conditional Promo Code input ──
      {
        name: "promoCode",
        label: t("tenant.promoCode"),
        type: "text",
        isVisible: () => requiresPromoCode,
        placeholder: t("tenant.promoCodePlaceholder"),
        onChange: (val: string, formData: Record<string, unknown>) => ({
          ...formData,
          promoCode: val.toUpperCase(),
        }),
      },
    ],
    [
      t,
      onSearchEditions,
      selectedEditionId,
      cachedEditions,
      availablePromotions,
      requiresPromoCode,
      isLoadingPromotions,
      onEditionChange,
      onSubscriptionTypeChange,
      setForm,
    ]
  );

  const handleSubmit = async (data: Record<string, unknown>) => {
    const promoId = data.promotionId === "__none__" ? "" : data.promotionId || "";
    const resolvedData: CreateFormState = {
      name: data.name,
      code: data.code,
      description: data.description || "",
      adminEmail: data.adminEmail || "",
      adminUsername: data.adminUsername || "",
      editionId: data.editionId,
      subscriptionType: data.subscriptionType || "",
      currency: data.currency || "USD",
      promotionId: promoId,
      promoCode: data.promoCode || "",
    };
    setForm(resolvedData);
    await onSubmit(resolvedData);
  };

  return (
    <GenericModal
      open={open}
      onOpenChange={onOpenChange}
      title={title}
      description={description}
      size="md"
      formKey="create-tenant-form"
    >
      <GenericForm
        key={`create-tenant-${open}`}
        fields={fields}
        initialValues={form}
        onSubmit={handleSubmit}
        onCancel={() => onOpenChange(false)}
      />
    </GenericModal>
  );
}

