/**
 * Tenant Permissions Dialog ViewModel
 *
 * BACKEND-GROUPED: Uses tenantRepository.getTenantPermissionsGrouped which returns
 * PermissionModuleGroup[] (Module → Category → Permissions).
 * Zero client-side reduce/useMemo groupBy in this viewmodel.
 * Client-side only: search FILTER (structure-preserving, not grouping).
 *
 * Clean Architecture: ViewModel → Repository (via DI) → Service → API
 * No direct API calls. No data-layer mapper imports.
 *
 * @module tenants/presentation/viewmodels
 */
"use client";

import { useState, useMemo, useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useEnhancedToast } from "@core/hooks/use-enhanced-toast";
import { useI18n } from "@core/providers/i18n-provider";
import { appLogger } from "@core/common/logger";
import { identityContainer } from "@modules/identity/di";
import type { Permission, PermissionModuleGroup } from "@modules/identity/core";

/**
 * Interface defining property specifications, keys types, and structural contract rules for use tenant permissions dialog props.
 */
export interface UseTenantPermissionsDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  tenantId: string;
  tenantName: string;
  parentTenantId?: string | null;
}

/**
 * Interface defining property specifications, keys types, and structural contract rules for use tenant permissions dialog result.
 */
export interface UseTenantPermissionsDialogResult {
  // State
  search: string;
  setSearch: (value: string) => void;
  selectedCodes: Set<string>;
  /** Check if a module card is expanded. */
  isModuleExpanded: (moduleKey: string) => boolean;
  /** Toggle a single module open/closed without affecting others. */
  toggleModule: (moduleKey: string) => void;
  /** Per-module expanded category keys. */
  expandedGroups: Record<string, string[]>;
  setModuleExpanded: (moduleKey: string, openKeys: string[]) => void;

  // Data — backend-grouped, client-search-filtered (NO client-side groupBy)
  groupedModules: PermissionModuleGroup[];
  totalCount: number;
  selectedCount: number;
  isLoading: boolean;
  hasParent: boolean;

  // Actions
  toggle: (code: string) => void;
  toggleGroup: (codes: string[]) => void;
  expandAll: () => void;
  collapseAll: () => void;
  save: () => void;
  isSaving: boolean;

  // Helpers
  getName: (p: Permission) => string;
  isChecked: (code: string) => boolean;
  getGroupStats: (codes: string[]) => {
    count: number;
    total: number;
    allChecked: boolean;
    someChecked: boolean;
  };
}

/**
 * React hook/ViewModel orchestrating state and data flows for tenant permissions dialog.
 * Manages TanStack Query hooks, query cache keys, and repository fetch requests.
 */
export function useTenantPermissionsDialog({
  open,
  onOpenChange,
  tenantId,
  tenantName,
  parentTenantId,
}: UseTenantPermissionsDialogProps): UseTenantPermissionsDialogResult {
  const { t, language } = useI18n();
  const { success: toastSuccess, error: toastError } = useEnhancedToast();
  const queryClient = useQueryClient();

  const [search, setSearch] = useState("");
  const [selectedCodes, setSelectedCodes] = useState<Set<string>>(new Set());
  const [expandedModules, setExpandedModules] = useState<Set<string>>(new Set());
  const [expandedGroups, setExpandedGroups] = useState<Record<string, string[]>>({});

  // Track which tenant we have already initialized selections for
  const [initializedTenantId, setInitializedTenantId] = useState<string | null>(null);

  // ── Reset state when dialog closes ──
  // useEffect prevents the React render-body setState anti-pattern.
  useEffect(() => {
    if (!open) {
      queueMicrotask(() => {
        setSearch("");
        setSelectedCodes(new Set());
        setExpandedModules(new Set());
        setExpandedGroups({});
        setInitializedTenantId(null);
      });
    }
  }, [open]);

  // ── Reset when the target tenant changes while dialog is open ──
  useEffect(() => {
    if (open && tenantId) {
      queueMicrotask(() => {
        setSearch("");
        setSelectedCodes(new Set());
        setExpandedModules(new Set());
        setExpandedGroups({});
        setInitializedTenantId(null);
      });
    }
  }, [open, tenantId]);

  // ── Fetch PARENT's available permissions GROUPED from backend ──
  // Uses Repository (Clean Architecture), NOT direct service calls.
  // Returns PermissionModuleGroup[] (Module → Category → Permissions)
  const { data: parentPermissionGroups = [], isLoading: loadingParent } = useQuery({
    queryKey: ["parent-permissions-grouped", parentTenantId],
    queryFn: async () => {
      try {
        appLogger.debug(
          "[ViewModel] Fetching grouped permissions via Repository, parentTenantId:",
          parentTenantId
        );

        if (parentTenantId) {
          // Child tenant: get parent's permissions grouped from repository
          return identityContainer.tenantRepository.getTenantPermissionsGrouped(parentTenantId);
        } else {
          // Root tenant fallback: get creation permissions (flat), wrap as grouped
          const flatPermissions = await identityContainer.tenantRepository.getCreationPermissions();
          return groupFlatPermissions(flatPermissions);
        }
      } catch (error) {
        appLogger.error("Failed to fetch available permissions", error);
        return [];
      }
    },
    enabled: open && !!tenantId,
  });

  // ── Fetch TENANT's current permissions (flat, for selection init) ──
  // Uses Repository (Clean Architecture) — mapper is in the repo layer.
  const { data: tenantPermissions = [], isLoading: loadingTenant } = useQuery({
    queryKey: ["tenant-current-permissions-service", tenantId],
    queryFn: async () => {
      try {
        appLogger.debug(
          "[ViewModel] Fetching tenant's current permissions via Repository:",
          tenantId
        );
        return identityContainer.tenantRepository.getTenantPermissions(tenantId);
      } catch (error) {
        appLogger.error("Failed to fetch tenant permissions", error);
        return [];
      }
    },
    enabled: open && !!tenantId,
  });

  // Flat permission list derived from groups (for toggle/lookup logic only)
  const allPermissions = useMemo((): Permission[] => {
    return parentPermissionGroups.flatMap((m) => m.categories.flatMap((c) => c.permissions));
  }, [parentPermissionGroups]);

  // ── Initialize selected codes from tenant's permissions (once per tenant) ──
  // useEffect is the correct place for derived state initialization.
  useEffect(() => {
    if (
      !open ||
      !tenantId ||
      allPermissions.length === 0 ||
      loadingTenant ||
      initializedTenantId === tenantId
    ) {
      return;
    }

    const validCodes = new Set(allPermissions.map((p) => p.code));
    const tenantCodes = tenantPermissions.map((p) => p.code);
    const selectedFromTenant = tenantCodes.filter((code: string) => validCodes.has(code));

    // Auto-expand accordion categories that have selected permissions.
    // Key format matches AccordionItem value: `${module}-${category}`.
    const groupsWithSelection = new Set<string>();
    allPermissions.forEach((p) => {
      if (selectedFromTenant.includes(p.code)) {
        const mod = p.module || "General";
        const cat = p.category || p.resource || "General";
        groupsWithSelection.add(`${mod}-${cat}`);
      }
    });
    // Build per-module record: { [moduleKey]: categoryKey[] }
    const perModuleExpanded: Record<string, string[]> = {};
    const modulesWithSelection = new Set<string>();
    groupsWithSelection.forEach((key) => {
      const dashIdx = key.indexOf("-");
      const mod = dashIdx !== -1 ? key.slice(0, dashIdx) : key;
      perModuleExpanded[mod] = [...(perModuleExpanded[mod] ?? []), key];
      modulesWithSelection.add(mod);
    });

    queueMicrotask(() => {
      setSelectedCodes(new Set(selectedFromTenant));
      setExpandedModules(new Set(modulesWithSelection));
      setExpandedGroups(perModuleExpanded);
      setInitializedTenantId(tenantId);
    });
  }, [open, tenantId, allPermissions, tenantPermissions, loadingTenant, initializedTenantId]);

  // Save mutation — uses repository for write operations
  const saveMutation = useMutation({
    mutationFn: async () => {
      const selectedIds = allPermissions.filter((p) => selectedCodes.has(p.code)).map((p) => p.id);
      await identityContainer.tenantRepository.updateTenantPermissions(tenantId, selectedIds);
    },
    onSuccess: () => {
      toastSuccess({ title: t("tenant.permissionsSaved") });
      queryClient.invalidateQueries({ queryKey: ["tenant-current-permissions-service", tenantId] });
      queryClient.invalidateQueries({ queryKey: ["parent-permissions-grouped"] });
      queryClient.invalidateQueries({ queryKey: ["tenant-stats", tenantId] });
      queryClient.invalidateQueries({ queryKey: ["tenants"] });
      onOpenChange(false);
    },
    onError: (error: Error) => {
      toastError({
        title: t("tenant.permissionsSaveError"),
        description: error.message,
      });
    },
  });

  // Toggle handlers
  const toggle = (code: string) => {
    setSelectedCodes((prev) => {
      const next = new Set(prev);
      next.has(code) ? next.delete(code) : next.add(code);
      return next;
    });
  };

  const toggleGroup = (codes: string[]) => {
    const allSelected = codes.every((c) => selectedCodes.has(c));
    setSelectedCodes((prev) => {
      const next = new Set(prev);
      codes.forEach((c) => (allSelected ? next.delete(c) : next.add(c)));
      return next;
    });
  };

  // ── Per-module expand state updater ──
  // Only touches one module's slice — all other modules remain unchanged.
  const setModuleExpanded = (moduleKey: string, openKeys: string[]) => {
    setExpandedGroups((prev) => ({ ...prev, [moduleKey]: openKeys }));
  };

  // ── Toggle a single module open/closed (manual — no Radix interference) ──
  const toggleModule = (moduleKey: string) => {
    setExpandedModules((prev) => {
      const next = new Set(prev);
      if (next.has(moduleKey)) {
        next.delete(moduleKey);
      } else {
        next.add(moduleKey);
      }
      return next;
    });
  };

  const isModuleExpanded = (moduleKey: string) => expandedModules.has(moduleKey);

  // Expand / Collapse ALL — controls both module-level AND category-level
  const expandAll = () => {
    const allModuleKeys = new Set(parentPermissionGroups.map((m) => m.module));
    const perModule: Record<string, string[]> = {};
    parentPermissionGroups.forEach((m) => {
      perModule[m.module] = m.categories.map((c) => `${m.module}-${c.category}`);
    });
    setExpandedModules(allModuleKeys);
    setExpandedGroups(perModule);
  };

  const collapseAll = () => {
    setExpandedModules(new Set());
    setExpandedGroups({});
  };

  // ── Client-side SEARCH FILTER only — preserves group structure from backend ──
  const groupedModules = useMemo((): PermissionModuleGroup[] => {
    if (!search.trim()) return parentPermissionGroups;

    const q = search.toLowerCase();
    return parentPermissionGroups
      .map((moduleGroup) => ({
        ...moduleGroup,
        categories: moduleGroup.categories
          .map((categoryGroup) => ({
            ...categoryGroup,
            permissions: categoryGroup.permissions.filter((p) => {
              const name = p.getLocalizedName(language);
              return name.toLowerCase().includes(q) || p.code.toLowerCase().includes(q);
            }),
          }))
          .filter((c) => c.permissions.length > 0),
      }))
      .filter((m) => m.categories.length > 0);
  }, [parentPermissionGroups, search, language]);

  // Helpers
  const getName = (p: Permission) => p.getLocalizedName(language);
  const isChecked = (code: string) => selectedCodes.has(code);

  const getGroupStats = (codes: string[]) => {
    const count = codes.filter((c) => selectedCodes.has(c)).length;
    return {
      count,
      total: codes.length,
      allChecked: count === codes.length,
      someChecked: count > 0 && count < codes.length,
    };
  };

  return {
    // State
    search,
    setSearch,
    selectedCodes,
    isModuleExpanded,
    toggleModule,
    expandedGroups,
    setModuleExpanded,

    // Data — backend-grouped, client-search-filtered
    groupedModules,
    totalCount: allPermissions.length,
    selectedCount: selectedCodes.size,
    isLoading: loadingParent || loadingTenant,
    hasParent: !!parentTenantId,

    // Actions
    toggle,
    toggleGroup,
    expandAll,
    collapseAll,
    save: () => saveMutation.mutate(),
    isSaving: saveMutation.isPending,

    // Helpers
    getName,
    isChecked,
    getGroupStats,
  };
}

/**
 * Utility: group a flat Permission[] by module → category.
 * Used ONLY as a fallback when the backend doesn't provide a grouped endpoint
 * (e.g., creation permissions for root tenants).
 */
function groupFlatPermissions(permissions: Permission[]): PermissionModuleGroup[] {
  const moduleMap = new Map<string, Map<string, Permission[]>>();

  for (const p of permissions) {
    const mod = p.module || "General";
    const cat = p.category || p.resource || "General";

    if (!moduleMap.has(mod)) moduleMap.set(mod, new Map());
    const catMap = moduleMap.get(mod)!;
    if (!catMap.has(cat)) catMap.set(cat, []);
    catMap.get(cat)!.push(p);
  }

  return Array.from(moduleMap.entries()).map(([module, catMap]) => ({
    module,
    categories: Array.from(catMap.entries()).map(([category, perms]) => ({
      category,
      permissions: perms,
    })),
  }));
}

/**
 * Tenant User Groups ViewModel
 *
 * Orchestrator ViewModel for managing user groups within a tenant.
 * Follows SOLID principles: composes existing ViewModels and provides
 * all data/operations for the TenantUserGroupsTab View.
 *
 * Architecture: View → ViewModel → Repository → Service → API
 *
 * @module tenants/presentation/viewmodels
 */
"use client";

import { useMemo, useCallback } from "react";
import { useI18n } from "@core/providers/i18n-provider";
import type { FieldConfig } from "@core/ui/forms/generic-form";
import { useRouter } from "next/navigation";

// User Groups module imports
import type { UserGroupListItem } from "@modules/identity/core";
import { useUserGroupsViewModel } from "@modules/identity/core";

interface UseTenantUserGroupsViewModelParams {
  tenantId: string;
  tenantName: string;
}

/**
 * Result interface for the ViewModel
 * Defines exactly what the View receives - Interface Segregation Principle
 */
export interface TenantUserGroupsViewModelResult {
  // Core CRUD ViewModel (delegated)
  groupsVm: ReturnType<typeof useUserGroupsViewModel>["vm"];

  // Form Fields (Dynamic based on create/edit)
  createFields: FieldConfig[];
  editFields: FieldConfig[];

  // Initial Values
  createInitialValues: Record<string, unknown>;
  getEditInitialValues: (item: UserGroupListItem) => Record<string, unknown>;

  // Table Columns Config
  columns: Array<{
    key: string;
    label: string;
    sortable?: boolean;
    render?: (value: unknown, item?: UserGroupListItem) => React.ReactNode;
  }>;

  // Actions
  onViewGroup: (groupId: string) => void;

  // Labels & Metadata
  title: string;
  subtitle: string;
  tenantId: string;

  // Delete service
  deleteService: (id: string) => Promise<void>;

  // Cascade Dialogs and actions
  triggerDelete: (ids: string[]) => void;
  triggerStatus: (ids: string[], isActive: boolean) => void;
  deleteDialog: { open: boolean; ids: string[]; isPending: boolean };
  setDeleteDialog: React.Dispatch<
    React.SetStateAction<{ open: boolean; ids: string[]; isPending: boolean }>
  >;
  statusDialog: { open: boolean; ids: string[]; isActive: boolean; isPending: boolean };
  setStatusDialog: React.Dispatch<
    React.SetStateAction<{ open: boolean; ids: string[]; isActive: boolean; isPending: boolean }>
  >;
  confirmDelete: (cascadeAdmins: boolean) => Promise<void>;
  confirmStatus: (cascadeAdmins: boolean) => Promise<void>;
}

/**
 * React hook/ViewModel orchestrating state and data flows for tenant user groups view model.
 * Handles active states updates, form fields validations, and browser navigation controllers.
 */
export function useTenantUserGroupsViewModel({
  tenantId,
  tenantName,
}: UseTenantUserGroupsViewModelParams): TenantUserGroupsViewModelResult {
  const { t, language } = useI18n();
  const router = useRouter();

  // Delegate to core user groups ViewModel - Dependency Inversion Principle
  const {
    vm: groupsVm,
    getConfigBase,
    triggerDelete,
    triggerStatus,
    deleteDialog,
    setDeleteDialog,
    statusDialog,
    setStatusDialog,
    confirmDelete,
    confirmStatus,
  } = useUserGroupsViewModel({ tenantId });

  // ─────────────────────────────────────────────────────────────────
  // Navigation Actions
  // ─────────────────────────────────────────────────────────────────
  const onViewGroup = useCallback(
    (groupId: string) => {
      router.push(`/user-groups/${groupId}`);
    },
    [router]
  );

  // ─────────────────────────────────────────────────────────────────
  // Configuration Base (From Core UserGroups module)
  // ─────────────────────────────────────────────────────────────────
  const configBase = getConfigBase(t);

  const createFields = useMemo(() => configBase.createFields, [configBase]);
  const editFields = useMemo(() => configBase.editFields, [configBase]);
  const createInitialValues = useMemo(
    () => ({ ...configBase.createInitialValues, tenantId }),
    [configBase, tenantId]
  );
  const getEditInitialValues = useCallback(
    (item: UserGroupListItem) => configBase.editInitialValues(item),
    [configBase]
  );

  // ─────────────────────────────────────────────────────────────────
  // Table Columns Configuration
  // ─────────────────────────────────────────────────────────────────
  const columns = useMemo(
    () => [
      {
        key: "name",
        label: t("userGroups.name"),
        sortable: true,
      },
      {
        key: "code",
        label: t("userGroups.code"),
      },
      {
        key: "description",
        label: t("userGroups.descriptionCol"),
      },
      {
        key: "memberCount",
        label: t("userGroups.members"),
      },
      {
        key: "roleCount",
        label: t("userGroups.roles"),
      },
      {
        key: "createdAt",
        label: t("common.createdAt"),
      },
    ],
    [t]
  );

  // ─────────────────────────────────────────────────────────────────
  // Labels
  // ─────────────────────────────────────────────────────────────────
  const title = t("tenant.manageGroups");
  const subtitle = t("tenant.groupsDescription").replace("{tenant}", tenantName);

  return {
    groupsVm,
    createFields,
    editFields,
    createInitialValues,
    getEditInitialValues,
    columns,
    onViewGroup,
    title,
    subtitle,
    tenantId,
    deleteService: configBase.deleteService,
    triggerDelete,
    triggerStatus,
    deleteDialog,
    setDeleteDialog,
    statusDialog,
    setStatusDialog,
    confirmDelete,
    confirmStatus,
  };
}

/**
 * Add Members Dialog
 *
 * Multi-select dialog to add admins to a user group.
 * Fetches available admins, filters out existing members, and calls addMembers.
 */
"use client";

import { useState, useMemo } from "react";
import { Button } from "@core/ui/button";
import { Label } from "@core/ui/label";
import { GenericModal } from "@core/crud/components/generic-modal";
import { GenericSelect, type GenericSelectOption } from "@core/crud/components/generic-select";
import { LoadingSpinner } from "@core/ui/loading-spinner";
import { Users } from "lucide-react";
import { useAddMembersViewModel } from "../viewmodels/useAddMembersViewModel";

interface AddMembersDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  groupId: string;
  existingMemberIds: string[];
  onSubmit: (adminIds: string[]) => void;
  isSubmitting?: boolean;
  tenantId?: string;
}

/**
 * Presentation UI component rendering the add members dialog.
 * Arranges layout boundaries and accessibility targets (WCAG, tab index) using the core design library (@core/ui/*).
 */
export function AddMembersDialog({
  open,
  onOpenChange,
  groupId,
  existingMemberIds,
  onSubmit,
  isSubmitting,
  tenantId,
}: AddMembersDialogProps) {
  const { t, language, adminsData, isLoading } = useAddMembersViewModel({
    groupId,
    tenantId,
    open,
  });
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  // Filter out existing members
  const adminOptions: GenericSelectOption[] = useMemo(() => {
    const existingSet = new Set(existingMemberIds);
    return (adminsData?.items ?? [])
      .filter((admin) => !existingSet.has(admin.id))
      .map((admin) => ({
        value: admin.id,
        label: `${admin.firstName} ${admin.lastName}`,
        description: admin.email || admin.username,
      }));
  }, [adminsData, existingMemberIds]);

  const handleSave = () => {
    if (selectedIds.length > 0) {
      onSubmit(selectedIds);
      setSelectedIds([]);
    }
  };

  const handleClose = (v: boolean) => {
    if (!v) setSelectedIds([]);
    onOpenChange(v);
  };

  return (
    <GenericModal
      open={open}
      onOpenChange={handleClose}
      title={t("userGroups.membersTab.addMembers")}
      description={t("userGroups.membersTab.addMembersDesc")}
      size="md"
    >
      <div className="space-y-4 py-2">
        {isLoading ? (
          <LoadingSpinner />
        ) : (
          <div className="space-y-2">
            <Label className="flex items-center gap-2">
              <Users className="h-4 w-4" aria-hidden="true" />
              {t("userGroups.membersTab.selectMembers")} *
            </Label>
            <GenericSelect
              options={adminOptions}
              value={selectedIds}
              onValueChange={(val: string | string[]) =>
                setSelectedIds(Array.isArray(val) ? val : [val])
              }
              placeholder={t("userGroups.membersTab.selectMembersPlaceholder")}
              type="multi"
            />
            {adminOptions.length === 0 && (
              <p className="text-xs text-nx-ink-3">
                {t("userGroups.membersTab.allAdminsAssigned")}
              </p>
            )}
          </div>
        )}

        <div className="mt-4 flex justify-end gap-2 border-t border-nx-line pt-4">
          <Button variant="outline" onClick={() => handleClose(false)} disabled={isSubmitting}>
            {t("common.cancel")}
          </Button>
          <Button
            onClick={handleSave}
            loading={isSubmitting}
            disabled={isLoading || selectedIds.length === 0}
          >
            {t("userGroups.membersTab.addSelected")}
          </Button>
        </div>
      </div>
    </GenericModal>
  );
}

/**
 * Assign to Group Dialog
 *
 * Reusable dialog for assigning an admin or role to one or more user groups.
 * Used cross-module from Admins and Roles pages.
 *
 * Features:
 * - Multi-group selection (assign to multiple groups at once)
 * - Smart tenant endpoint selection (Super Admin vs Tenant Admin)
 * - Server-side search with debounce
 * - Progress feedback for multi-group assignment
 */
"use client";

import { useState, useEffect } from "react";
import { Button } from "@core/ui/button";
import { Label } from "@core/ui/label";
import { GenericModal } from "@core/crud/components/generic-modal";
import { GenericSelect, type GenericSelectOption } from "@core/crud/components/generic-select";
import { Users } from "lucide-react";
import { useCurrentTenantId } from "@core/providers/tenant-context-provider";
import { useAssignToGroupViewModel } from "../viewmodels/useAssignToGroupViewModel";

interface AssignToGroupDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** The admin to add to groups */
  adminId?: string;
  adminIds?: string[];
  adminName?: string;
  /** The role to add to groups */
  roleId?: string;
  roleIds?: string[];
  roleName?: string;
  /** Which mode */
  mode: "admin" | "role";
  /** For scoping groups to a specific tenant (e.g., from Tenant Detail) */
  tenantId?: string;
  /** If true, attempt to scope strictly to logged-in user's tenant (falls back to getAll for super admins) */
  useMyTenant?: boolean;
}

/**
 * Presentation UI component rendering the assign to group dialog.
 * Arranges layout boundaries and accessibility targets (WCAG, tab index) using the core design library (@core/ui/*).
 */
export function AssignToGroupDialog({
  open,
  onOpenChange,
  adminId,
  adminIds,
  adminName,
  roleId,
  roleIds,
  roleName,
  mode,
  tenantId,
  useMyTenant,
}: AssignToGroupDialogProps) {
  const vm = useAssignToGroupViewModel({ tenantId, useMyTenant, onOpenChange });
  const { t, language, fetchGroups, isPending } = vm;

  // Multi-select state
  const [selectedGroupIds, setSelectedGroupIds] = useState<string[]>([]);
  const [searchOptions, setSearchOptions] = useState<GenericSelectOption[]>([]);
  const [isSearching, setIsSearching] = useState(false);

  // Tenant context
  const currentUserTenantId = useCurrentTenantId();

  const handleSearchGroups = async (term: string) => {
    setIsSearching(true);
    try {
      const options = await fetchGroups(term);
      setSearchOptions(options);
      return options;
    } finally {
      setIsSearching(false);
    }
  };

  // Initial load when dialog opens + reset on close
  useEffect(() => {
    queueMicrotask(() => {
      if (open) {
        handleSearchGroups("");
      } else {
        setSearchOptions([]);
        setSelectedGroupIds([]);
      }
    });
  }, [open, tenantId, useMyTenant, currentUserTenantId]);

  const handleSave = () => {
    if (mode === "admin") {
      const targetAdminIds = adminIds ?? (adminId ? [adminId] : []);
      vm.addMembers(targetAdminIds, selectedGroupIds);
    } else {
      const targetRoleIds = roleIds ?? (roleId ? [roleId] : []);
      vm.addRoles(targetRoleIds, selectedGroupIds);
    }
  };

  const handleClose = (v: boolean) => {
    if (!v) setSelectedGroupIds([]);
    onOpenChange(v);
  };

  const entityName = mode === "admin" ? adminName || "" : roleName || "";
  const isBulk = (mode === "admin" ? (adminIds?.length ?? 0) : (roleIds?.length ?? 0)) > 0;
  const bulkCount = mode === "admin" ? (adminIds?.length ?? 0) : (roleIds?.length ?? 0);

  return (
    <GenericModal
      open={open}
      onOpenChange={handleClose}
      title={t("userGroups.assignToGroups")}
      description={
        isBulk
          ? `${t("userGroups.assignBulkDesc")} ${bulkCount} ${mode === "admin" ? t("admin.admins") : t("roles.roles")}`
          : `${t("userGroups.assignToGroupDesc")} ${entityName}`
      }
      size="md"
    >
      <div className="space-y-4 py-2">
        <div className="space-y-2">
          <Label className="flex items-center gap-2">
            <Users className="h-4 w-4" aria-hidden="true" />
            {t("userGroups.selectGroups")} *
          </Label>
          <GenericSelect
            options={searchOptions}
            value={selectedGroupIds}
            onValueChange={(val: string | string[]) =>
              setSelectedGroupIds(Array.isArray(val) ? val : [val])
            }
            placeholder={t("userGroups.selectGroupsPlaceholder")}
            type="multi"
            searchType="server"
            onServerSearch={handleSearchGroups}
            loading={isSearching}
          />
          {selectedGroupIds.length > 0 && (
            <p className="text-xs text-nx-ink-3">
              {t("userGroups.selectedCount", { count: selectedGroupIds.length })}
            </p>
          )}
        </div>

        <div className="mt-4 flex justify-end gap-2 border-t border-nx-line pt-4">
          <Button variant="outline" onClick={() => handleClose(false)} disabled={isPending}>
            {t("common.cancel")}
          </Button>
          <Button
            onClick={handleSave}
            loading={isPending}
            disabled={isSearching || selectedGroupIds.length === 0}
          >
            {t("userGroups.assignAction")}
            {selectedGroupIds.length > 0 && ` (${selectedGroupIds.length})`}
          </Button>
        </div>
      </div>
    </GenericModal>
  );
}

"use client";

import { useQuery } from "@tanstack/react-query";
import { useI18n } from "@core/providers/i18n-provider";
import { identityContainer } from "@modules/identity/di";

interface UseSetRestrictionsViewModelProps {
  tenantId?: string;
  open: boolean;
}

/**
 * React hook/ViewModel orchestrating state and data flows for set restrictions view model.
 * Manages TanStack Query hooks, query cache keys, and repository fetch requests.
 */
export function useSetRestrictionsViewModel({ tenantId, open }: UseSetRestrictionsViewModelProps) {
  const { t } = useI18n();

  // Fetch available permissions to distinct their resources
  const { data: availablePermissions = [], isLoading: isLoadingPermissions } = useQuery({
    queryKey: ["restrictions-available-permissions", tenantId],
    queryFn: async () => {
      try {
        if (tenantId) {
          return await identityContainer.tenantService.getTenantPermissions(tenantId);
        } else {
          return await identityContainer.tenantService.getCreationPermissions();
        }
      } catch (e) {
        return [];
      }
    },
    enabled: open,
    staleTime: 5 * 60 * 1000,
  });

  return {
    t,
    availablePermissions,
    isLoadingPermissions,
  };
}

/**
 * User Groups List View
 *
 * Main list page for user group management.
