                  <Check className="h-3.5 w-3.5 text-success" />
                ) : (
                  <Copy className="h-3.5 w-3.5" />
                )}
              </Button>
            </div>
            <p className="mt-2 flex items-center gap-1.5 font-sans text-[10px] text-nx-ink-3">
              <Code2 className="h-3.5 w-3.5 shrink-0" />
              <span>
                Replace the placeholder with the plaintext token generated during creation.
              </span>
            </p>
          </TabsContent>

          {/* Node.js Content */}
          <TabsContent value="node" className="space-y-3 outline-none">
            <div className="relative">
              <pre className="select-all overflow-x-auto rounded-nx-md border border-nx-line bg-nx-raised p-4 font-mono text-xs leading-relaxed text-nx-ink">
                <code>{nodeCode}</code>
              </pre>
              <Button
                size="icon"
                variant="ghost"
                className="absolute end-2.5 top-2.5 h-7 w-7 text-nx-ink-3 hover:bg-nx-hover hover:text-nx-ink"
                onClick={() => handleCopy(nodeCode, "node")}
              >
                {copiedTab === "node" ? (
                  <Check className="h-3.5 w-3.5 text-success" />
                ) : (
                  <Copy className="h-3.5 w-3.5" />
                )}
              </Button>
            </div>
          </TabsContent>

          {/* .NET Content */}
          <TabsContent value="dotnet" className="space-y-3 outline-none">
            <div className="relative">
              <pre className="select-all overflow-x-auto rounded-nx-md border border-nx-line bg-nx-raised p-4 font-mono text-xs leading-relaxed text-nx-ink">
                <code>{dotnetCode}</code>
              </pre>
              <Button
                size="icon"
                variant="ghost"
                className="absolute end-2.5 top-2.5 h-7 w-7 text-nx-ink-3 hover:bg-nx-hover hover:text-nx-ink"
                onClick={() => handleCopy(dotnetCode, "dotnet")}
              >
                {copiedTab === "dotnet" ? (
                  <Check className="h-3.5 w-3.5 text-success" />
                ) : (
                  <Copy className="h-3.5 w-3.5" />
                )}
              </Button>
            </div>
          </TabsContent>
        </Tabs>
      </CardContent>
    </Card>
  );
}

"use client";

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardFooter } from "@core/ui/card";
import { Button } from "@core/ui/button";
import { Input } from "@core/ui/input";
import { Label } from "@core/ui/label";
import { Textarea } from "@core/ui/textarea";
import type { ApiKeyDetail, UpdateApiKeyDetailRequest } from "../../domain/entities/ApiKeyDetail";
import { useI18n } from "@core/providers/i18n-provider";

interface ApiKeySettingsPanelProps {
  detail: ApiKeyDetail;
  isUpdating: boolean;
  onUpdate: (request: UpdateApiKeyDetailRequest) => void;
  /** Gates editing/saving — mirrors the backend's apikeys.update requirement. */
  canUpdate: boolean;
}

export function ApiKeySettingsPanel({
  detail,
  isUpdating,
  onUpdate,
  canUpdate,
}: ApiKeySettingsPanelProps) {
  const { t } = useI18n();

  const [name, setName] = useState(detail.name);
  const [description, setDescription] = useState(detail.description);
  const [rateLimit, setRateLimit] = useState(detail.rateLimitPerMinute?.toString() ?? "");
  const [burstPercent, setBurstPercent] = useState(detail.burstAllowancePercent?.toString() ?? "");
  const [monthlyQuota, setMonthlyQuota] = useState(detail.monthlyQuota?.toString() ?? "");
  const [quotaResetDay, setQuotaResetDay] = useState(detail.quotaResetDay.toString());
  const [alertThreshold, setAlertThreshold] = useState(detail.alertThresholdPercent.toString());
  const [ipWhitelist, setIpWhitelist] = useState(detail.ipWhitelist ?? "");

  const hasChanges =
    name !== detail.name ||
    description !== detail.description ||
    rateLimit !== (detail.rateLimitPerMinute?.toString() ?? "") ||
    burstPercent !== (detail.burstAllowancePercent?.toString() ?? "") ||
    monthlyQuota !== (detail.monthlyQuota?.toString() ?? "") ||
    quotaResetDay !== detail.quotaResetDay.toString() ||
    alertThreshold !== detail.alertThresholdPercent.toString() ||
    ipWhitelist !== (detail.ipWhitelist ?? "");

  // Combines both gates the fields/button already render off of: the key must be usable
  // (isActive) AND the caller must actually hold apikeys.update. Backend enforcement was
  // always intact for this — this is closing the frontend-only defense-in-depth gap.
  const canEdit = detail.isActive && canUpdate;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!canEdit) return;

    onUpdate({
      name,
      description,
      rateLimitPerMinute: rateLimit ? parseInt(rateLimit) : null,
      burstAllowancePercent: burstPercent ? parseInt(burstPercent) : null,
      monthlyQuota: monthlyQuota ? parseInt(monthlyQuota) : null,
      quotaResetDay: parseInt(quotaResetDay),
      alertThresholdPercent: parseInt(alertThreshold),
      ipWhitelist: ipWhitelist || null,
    });
  };

  return (
    <form onSubmit={handleSubmit}>
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-sm font-semibold">
            {t("apikeys.settings.title")}
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid gap-4 md:grid-cols-2">
            <div className="space-y-1.5">
              <Label htmlFor="key-name">{t("apikeys.settings.name")}</Label>
              <Input
                id="key-name"
                value={name}
                onChange={(e) => setName(e.target.value)}
                required
                disabled={!canEdit}
              />
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="rate-limit">
                {t("apikeys.settings.rateLimit")}
              </Label>
              <Input
                id="rate-limit"
                type="number"
                value={rateLimit}
                onChange={(e) => setRateLimit(e.target.value)}
                placeholder={t("apikeys.settings.rateLimitPlaceholder")}
                disabled={!canEdit}
              />
            </div>
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="key-desc">{t("apikeys.settings.desc")}</Label>
            <Textarea
              id="key-desc"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              rows={2}
              placeholder={t("apikeys.settings.descPlaceholder")}
              disabled={!canEdit}
            />
          </div>

          <div className="grid gap-4 md:grid-cols-3">
            <div className="space-y-1.5">
              <Label htmlFor="monthly-quota">
                {t("apikeys.settings.quota")}
              </Label>
              <Input
                id="monthly-quota"
                type="number"
                value={monthlyQuota}
                onChange={(e) => setMonthlyQuota(e.target.value)}
                placeholder={t("apikeys.settings.quotaPlaceholder")}
                disabled={!canEdit}
              />
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="reset-day">
                {t("apikeys.settings.resetDay")}
              </Label>
              <Input
                id="reset-day"
                type="number"
                min={1}
                max={28}
                value={quotaResetDay}
                onChange={(e) => setQuotaResetDay(e.target.value)}
                required
                disabled={!canEdit}
              />
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="alert-threshold">
                {t("apikeys.settings.alert")}
              </Label>
              <Input
                id="alert-threshold"
                type="number"
                min={0}
                max={100}
                value={alertThreshold}
                onChange={(e) => setAlertThreshold(e.target.value)}
                required
                disabled={!canEdit}
              />
            </div>
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="ip-whitelist">
              {t("apikeys.settings.whitelist")}
            </Label>
            <Input
              id="ip-whitelist"
              value={ipWhitelist}
              onChange={(e) => setIpWhitelist(e.target.value)}
              placeholder="e.g. 192.168.1.1, 10.0.0.0/24 (Leave empty to allow all)"
              disabled={!canEdit}
            />
          </div>
        </CardContent>
        {canUpdate && (
          <CardFooter className="justify-end border-t border-nx-line bg-nx-raised px-6 py-3">
            <Button type="submit" size="sm" disabled={!hasChanges || isUpdating || !canEdit}>
              {isUpdating ? t("common.saving") : t("common.saveChanges")}
            </Button>
          </CardFooter>
        )}
      </Card>
    </form>
  );
}

/**
 * API Keys List View
 *
 * Renders the developer API Key management interface.
 * Uses GenericCrudView for table, filters, and standard columns.
 * Displays generated key plain text in a secure Dialog upon creation.
 */
"use client";

import { useMemo } from "react";
import { useRouter } from "next/navigation";
import { GenericCrudView } from "@core/crud/components/generic-crud-view";
import type { CrudConfig, CrudAction } from "@core/crud/components/generic-crud-view";
import { useI18n } from "@core/providers/i18n-provider";
import { useApiKeysViewModel } from "../viewmodels/useApiKeysViewModel";
import { useModuleLocales } from "@core/hooks/use-module-locales";
import { Badge } from "@core/ui/badge";
import { Popover, PopoverContent, PopoverTrigger } from "@core/ui/popover";
import { GeneratedKeyDialog } from "../components/GeneratedKeyDialog";
import { ApiKey } from "../../domain/entities/ApiKey";
import { Key, Trash2, Eye } from "lucide-react";
import { formatUtc } from "@core/common/utils";

export function ApiKeysView() {
  useModuleLocales(() => import("../../../locales"), "apikeys");

  const { t } = useI18n();
  const router = useRouter();
  const { vm, getConfigBase, generatedKey, setGeneratedKey } = useApiKeysViewModel();
  const configBase = getConfigBase();

  // Configure GenericCrudView
  const config: CrudConfig<ApiKey> = useMemo(
    () => ({
      titleKey: "apikeys.title",
      subtitleKey: "apikeys.description",
      resource: "apikeys",
      entityTypeKey: "integrations.api-key",
      columns: [
        {
          key: "name",
          label: t("apikeys.name"),
          sortable: true,
          render: (_val: unknown, item: ApiKey) => (
            <div className="flex items-center gap-2">
              <Key className="h-4 w-4 shrink-0 text-nx-accent" />
              <span
                onClick={() => router.push(`/integrations/apikeys/${item.id}`)}
                className="cursor-pointer text-sm font-semibold hover:text-nx-accent hover:underline"
              >
                {item.name || t("apikeys.untitled")}
              </span>
            </div>
          ),
        },
        {
          key: "prefix",
          label: t("apikeys.prefix"),
          render: (_val: unknown, item: ApiKey) => (
            <span className="rounded-nx-sm border border-nx-line bg-nx-raised px-2 py-0.5 font-mono text-xs">
              {item.prefix}...
            </span>
          ),
        },
        {
          key: "status",
          label: t("apikeys.statusLabel"),
          render: (_val: unknown, item: ApiKey) => {
            const status = item.status;
            let variant: "default" | "secondary" | "outline" | "destructive" = "default";
            let className = "";

            if (status === "active") {
              variant = "default";
              className = "bg-success/15 text-success hover:bg-success/15";
            } else if (status === "expired") {
              variant = "outline";
              className = "bg-warning/15 text-warning hover:bg-warning/15 border-warning/40";
            } else {
              variant = "destructive";
              className = "bg-destructive/15 text-destructive hover:bg-destructive/15";
            }

            return (
              <Badge variant={variant} className={`text-xs ${className}`}>
                {t(`apikeys.status.${status}`)}
              </Badge>
            );
          },
        },
        {
          key: "scopes",
          label: t("apikeys.scopes"),
          render: (_val: unknown, item: ApiKey) => {
            const list = item.scopesList;
            if (list.length === 0) return <span className="text-xs text-nx-ink-3">—</span>;

            const limit = 2;
            const visible = list.slice(0, limit);
            const extraCount = list.length - limit;

            return (
              <div className="flex max-w-[280px] flex-wrap items-center gap-1">
                {visible.map((scope) => (
                  <Badge
                    key={scope}
                    variant="secondary"
                    className="shrink-0 border border-[color:color-mix(in_srgb,var(--nx-accent)_25%,transparent)] bg-nx-accent-wash px-2 py-0.5 font-mono text-[10px] text-nx-accent"
                  >
                    {scope}
                  </Badge>
                ))}
                {extraCount > 0 && (
                  <Popover>
                    <PopoverTrigger asChild>
                      <Badge
                        variant="outline"
                        className="shrink-0 cursor-pointer border border-[color:color-mix(in_srgb,var(--nx-accent)_30%,transparent)] bg-[color:color-mix(in_srgb,var(--nx-accent)_15%,transparent)] px-2 py-0.5 font-mono text-[10px] text-nx-accent hover:bg-[color:color-mix(in_srgb,var(--nx-accent)_25%,transparent)]"
                      >
                        +{extraCount} {t("apikeys.more")}
                      </Badge>
                    </PopoverTrigger>
                    <PopoverContent className="w-[320px] p-3 text-xs" align="start">
                      <p className="mb-2 font-semibold text-nx-ink">{t("apikeys.allScopes")}:</p>
                      <div className="flex max-h-[160px] flex-wrap gap-1 overflow-y-auto pe-1">
                        {list.map((scope) => (
                          <Badge
                            key={scope}
                            variant="secondary"
                            className="border border-[color:color-mix(in_srgb,var(--nx-accent)_25%,transparent)] bg-nx-accent-wash px-2 py-0.5 font-mono text-[10px] text-nx-accent"
                          >
                            {scope}
                          </Badge>
                        ))}
                      </div>
                    </PopoverContent>
                  </Popover>
                )}
              </div>
            );
          },
        },
        {
          key: "createdAt",
          label: t("apikeys.createdAt"),
          render: (_val: unknown, item: ApiKey) => (
            <span className="font-mono text-xs text-nx-ink-3">
              {item.createdAt ? formatUtc(item.createdAt, "MMM d, yyyy") : "—"}
            </span>
          ),
        },
        {
          key: "expiresAt",
          label: t("apikeys.expiresAt"),
          render: (_val: unknown, item: ApiKey) => (
            <span className="font-mono text-xs text-nx-ink-3">
              {item.expiresAt ? (
                formatUtc(item.expiresAt, "MMM d, yyyy")
              ) : (
                <span className="font-sans font-normal text-success">
                  {t("apikeys.neverExpires")}
                </span>
              )}
            </span>
          ),
        },
      ],
      createFields: configBase.createFields || [],
      createInitialValues: configBase.createInitialValues,
      getItemDisplayName: configBase.getItemDisplayName,
      deleteService: configBase.deleteService,
      permissions: configBase.permissions,
      getActions: (
        _vmInstance: unknown,
        tFn: (key: string) => string,
        handleDeleteFn?: (item: ApiKey) => void
      ): CrudAction<ApiKey>[] => [
        {
          label: tFn("apikeys.viewDetails"),
          onClick: (item: ApiKey) => router.push(`/integrations/apikeys/${item.id}`),
          variant: "ghost" as const,
          icon: <Eye className="h-4 w-4" />,
          requiredPermission: "apikeys.view",
        },
        {
          label: tFn("apikeys.revoke"),
          onClick: (item: ApiKey) => handleDeleteFn?.(item),
          variant: "ghost" as const,
          className: "text-destructive hover:text-destructive/90",
          icon: <Trash2 className="h-4 w-4" />,
          requiredPermission: "apikeys.delete",
          confirmTitle: tFn("apikeys.revokeConfirmTitle"),
          confirmDescription: tFn("apikeys.revokeConfirmDesc"),
          confirmVariant: "destructive" as const,
        },
      ],
    }),
    [t, configBase]
  );

  return (
    <div className="space-y-5">
      {/* Main CRUD Table */}
      <GenericCrudView viewModel={vm} config={config} />

      {/* Generated Token Success Dialog (Show Once Modal) */}
      <GeneratedKeyDialog generatedKey={generatedKey} onClose={() => setGeneratedKey(null)} />
    </div>
  );
}

"use client";

import React, { useMemo } from "react";
