// Main Builder Panel
// ═══════════════════════════════════════════════════════════
interface DashboardBuilderPanelProps {
  initialCanvas?: DashboardBuilderCanvas;
  onCanvasChange?: (canvas: DashboardBuilderCanvas) => void;
}

export function DashboardBuilderPanel({
  initialCanvas,
  onCanvasChange,
}: DashboardBuilderPanelProps) {
  const { t } = useI18n();
  const store = useDashboardBuilderStore();
  const [dragActiveType, setDragActiveType] = useState<DashboardWidgetType | null>(null);

  // Initialize from props
  useEffect(() => {
    if (initialCanvas) {
      store.initialize(initialCanvas);
    }
  }, []);

  // Keyboard shortcuts
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === "z" && !e.shiftKey) {
        e.preventDefault();
        store.undo();
      }
      if ((e.ctrlKey || e.metaKey) && e.key === "z" && e.shiftKey) {
        e.preventDefault();
        store.redo();
      }
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, []);

  // Notify parent on changes
  const storeWidgets = store.widgets;
  const storeGridRows = store.gridRows;
  const storeEnabled = store.enabled;
  useEffect(() => {
    onCanvasChange?.(store.toCanvas());
  }, [storeWidgets, storeGridRows, storeEnabled, onCanvasChange, store]);

  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 5 } }));

  const handleDragStart = useCallback((event: DragStartEvent) => {
    const type = event.active.data.current?.type as DashboardWidgetType;
    if (type) setDragActiveType(type);
  }, []);

  const handleDragEnd = useCallback(
    (event: DragEndEvent) => {
      setDragActiveType(null);
      if (!event.over) return;
      const type = event.active.data.current?.type as DashboardWidgetType;
      const source = event.active.data.current?.source as string;
      if (source === "palette" && type) {
        store.addWidget(type);
      }
    },
    [store]
  );

  const dragActiveEntry = dragActiveType
    ? WIDGET_CATALOG.find((c) => c.type === dragActiveType)
    : undefined;

  return (
    <DndContext sensors={sensors} onDragStart={handleDragStart} onDragEnd={handleDragEnd}>
      <div className="flex h-full flex-col">
        {/* Toolbar */}
        <div className="flex items-center justify-between border-b border-nx-line px-3 py-2">
          <div className="flex items-center gap-1">
            <Button
              variant="ghost"
              size="icon"
              className="h-7 w-7"
              disabled={!store.canUndo}
              onClick={() => store.undo()}
              aria-label={t("dashboard.builder.undoShortcut")}
            >
              <Undo2 className="h-3.5 w-3.5" aria-hidden="true" />
            </Button>
            <Button
              variant="ghost"
              size="icon"
              className="h-7 w-7"
              disabled={!store.canRedo}
              onClick={() => store.redo()}
              aria-label={t("dashboard.builder.redoShortcut")}
            >
              <Redo2 className="h-3.5 w-3.5" aria-hidden="true" />
            </Button>
            <Separator orientation="vertical" className="mx-1 h-5" />
            <Button
              variant="ghost"
              size="icon"
              className="h-7 w-7"
              onClick={() => store.reset()}
              aria-label={t("dashboard.builder.reset")}
            >
              <RotateCcw className="h-3.5 w-3.5" aria-hidden="true" />
            </Button>
          </div>
          <div className="flex items-center gap-2">
            <Label className="text-xs">{t("dashboard.builder.gridRows")}</Label>
            <div className="flex items-center gap-1">
              <button
                type="button"
                className={cn(ICON_CONTROL, "p-0.5")}
                aria-label={t("dashboard.builder.fewerRows")}
                onClick={() => store.setGridRows(store.gridRows - 1)}
              >
                <MinusIcon className="h-3 w-3" aria-hidden="true" />
              </button>
              <span className="min-w-[20px] text-center text-xs font-medium tabular-nums text-nx-ink">
                {store.gridRows}
              </span>
              <button
                type="button"
                className={cn(ICON_CONTROL, "p-0.5")}
                aria-label={t("dashboard.builder.moreRows")}
                onClick={() => store.setGridRows(store.gridRows + 1)}
              >
                <PlusIcon className="h-3 w-3" aria-hidden="true" />
              </button>
            </div>
          </div>
        </div>

        <div className="flex flex-1 overflow-hidden">
          {/* Left: Palette + Props */}
          <div className="w-[220px] flex-shrink-0 border-e border-nx-line">
            <ScrollArea className="h-full">
              <div className="space-y-1 p-2">
                <h4 className="px-1 text-[11px] font-semibold uppercase tracking-wider text-nx-ink-3">
                  {t("dashboard.builder.palette.title")}
                </h4>
                {WIDGET_CATALOG.map((entry) => (
                  <PaletteItem key={entry.type} {...entry} />
                ))}
              </div>
              <Separator />
              <WidgetPropsPanel />
            </ScrollArea>
          </div>

          {/* Right: Canvas */}
          <div className="flex-1 overflow-auto p-4">
            <BuilderCanvas onSelectWidget={(id) => store.selectWidget(id)} />
          </div>
        </div>
      </div>

      {/* Drag Overlay */}
      <DragOverlay>
        {dragActiveType && (
          <div className="rounded-nx-control border border-nx-accent bg-nx-popover px-3 py-2 shadow-nx-popover">
            <span className="text-xs font-medium text-nx-ink">
              {dragActiveEntry ? t(dragActiveEntry.labelKey) : dragActiveType}
            </span>
          </div>
        )}
      </DragOverlay>
    </DndContext>
  );
}

"use client";

import { create } from "zustand";
import {
  parseDashboardThemeJson,
  DEFAULT_DASHBOARD_THEME,
  type DashboardThemeConfig,
} from "../../domain/entities/DashboardThemeConfig";
import { STORAGE_KEYS } from "@core/config/storage-keys";

interface DashboardThemeState {
  isStudioOpen: boolean;
  setIsStudioOpen: (open: boolean) => void;
  draft: DashboardThemeConfig;
  setDraft: (
    draft: DashboardThemeConfig | ((prev: DashboardThemeConfig) => DashboardThemeConfig)
  ) => void;
  persistedConfig: DashboardThemeConfig;
  setPersistedConfig: (config: DashboardThemeConfig) => void;
  initialize: () => void;
  updateDraft: <K extends keyof DashboardThemeConfig>(
    key: K,
    value: DashboardThemeConfig[K]
  ) => void;
  updateNested: (section: keyof DashboardThemeConfig, field: string, value: unknown) => void;
  discardDraft: () => void;
  resetToDefault: () => void;
}

/**
 * React hook/ViewModel orchestrating state and data flows for dashboard theme store.
 * Handles active states updates, form fields validations, and browser navigation controllers.
 */
export const useDashboardThemeStore = create<DashboardThemeState>((set, get) => ({
  isStudioOpen: false,
  setIsStudioOpen: (open) => set({ isStudioOpen: open }),
  draft: { ...DEFAULT_DASHBOARD_THEME },
  setDraft: (draft) =>
    set((state) => ({
      draft: typeof draft === "function" ? draft(state.draft) : draft,
    })),
  persistedConfig: { ...DEFAULT_DASHBOARD_THEME },
  setPersistedConfig: (config) => set({ persistedConfig: config }),
  initialize: () => {
    if (typeof window === "undefined") return;
    const stored = localStorage.getItem(STORAGE_KEYS.PREF_DASHBOARD_SETTINGS);
    const parsed = parseDashboardThemeJson(stored);
    set({ persistedConfig: parsed, draft: parsed });
  },
  updateDraft: (key, value) =>
    set((state) => ({
      draft: { ...state.draft, [key]: value },
    })),
  updateNested: (section, field, value) =>
    set((state) => ({
      draft: {
        ...state.draft,
        [section]: {
          ...(state.draft[section] as object),
          [field]: value,
        },
      },
    })),
  discardDraft: () =>
    set((state) => ({
      draft: state.persistedConfig,
      isStudioOpen: false,
    })),
  resetToDefault: () =>
    set((state) => ({
      draft: {
        ...DEFAULT_DASHBOARD_THEME,
        theme: state.persistedConfig.theme,
        sidebarCollapsed: state.persistedConfig.sidebarCollapsed,
        language: state.persistedConfig.language,
      },
    })),
}));

