                ? t("platformHealth.kpis.servicesAffected", { count: 1 }) || "1 service affected"
                : t("platformHealth.kpis.servicesAffectedPlural", { count: activeIncidents.length }) ||
                  `${activeIncidents.length} services affected`}
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import React from "react";
import { AlertCircle, CheckCircle2, ShieldCheck, Clock, Layers } from "lucide-react";
import { useI18n } from "@core/providers/i18n-provider";
import type { HealthIncident } from "../../domain/entities/PlatformHealth";

interface IncidentDetailPanelProps {
  incident: HealthIncident | null;
  isLoading?: boolean;
}

export function IncidentDetailPanel({
  incident,
  isLoading = false,
}: IncidentDetailPanelProps) {
  const { t } = useI18n();

  if (!incident) {
    return (
      <div className="rounded-xl border border-border bg-card p-6 shadow-xs flex flex-col items-center justify-center text-center min-h-[280px]">
        <div className="w-12 h-12 rounded-full bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 flex items-center justify-center mb-3">
          <ShieldCheck className="h-6 w-6" />
        </div>
        <h3 className="text-base font-bold text-foreground">
          {t("platformHealth.incidents.noActiveIncidentsTitle") || "No Active Incidents"}
        </h3>
        <p className="text-xs text-muted-foreground max-w-sm mt-1">
          {t("platformHealth.incidents.noActiveIncidentsDesc") ||
            "All monitored services and external dependencies are operating within normal parameters."}
        </p>
      </div>
    );
  }

  const isInvestigating =
    incident.status.toLowerCase() === "investigating" ||
    incident.status.toLowerCase() === "degraded";
  const isResolved = incident.status.toLowerCase() === "resolved";

  return (
    <div className="rounded-xl border border-border bg-card p-4 sm:p-5 shadow-xs flex flex-col gap-4">
      {/* Header */}
      <div className="flex items-center justify-between border-b border-border/60 pb-3">
        <div className="flex items-center gap-2.5">
          <div
            className={`w-8 h-8 rounded-lg border flex items-center justify-center shrink-0 ${
              isInvestigating
                ? "bg-rose-500/10 border-rose-500/20 text-rose-400"
                : "bg-emerald-500/10 border-emerald-500/20 text-emerald-400"
            }`}
          >
            {isInvestigating ? (
              <AlertCircle className="h-4.5 w-4.5" />
            ) : (
              <CheckCircle2 className="h-4.5 w-4.5" />
            )}
          </div>
          <div>
            <h2 className="text-base font-bold tracking-tight text-foreground">
              {t("platformHealth.incidents.detailsTitle") || "Incident Details"}
            </h2>
            <div className="flex items-center gap-1.5 text-xs text-muted-foreground font-mono">
              <Clock className="h-3 w-3" />
              <span>
                {new Date(incident.detectedAt).toLocaleString([], {
                  month: "short",
                  day: "numeric",
                  hour: "2-digit",
                  minute: "2-digit",
                })}
              </span>
            </div>
          </div>
        </div>

        {/* Status Pill */}
        <span
          className={`inline-flex items-center px-2.5 py-1 rounded-md text-xs font-semibold border ${
            isInvestigating
              ? "bg-rose-500/15 text-rose-400 border-rose-500/30"
              : isResolved
              ? "bg-emerald-500/15 text-emerald-400 border-emerald-500/30"
              : "bg-sky-500/15 text-sky-400 border-sky-500/30"
          }`}
        >
          {incident.status}
        </span>
      </div>

      {/* Incident Title & Meta */}
      <div>
        <h3 className="text-base font-bold text-foreground leading-snug">
          {incident.title}
        </h3>
      </div>

      {/* Summary */}
      <div className="rounded-lg border border-border/60 bg-muted/20 p-3">
        <div className="text-[11px] font-bold uppercase tracking-wider text-muted-foreground mb-1">
          {t("platformHealth.incidents.summary") || "Summary"}
        </div>
        <p className="text-xs text-foreground/90 leading-relaxed">
          {incident.description}
        </p>
      </div>

      {/* Affected Service & Impact */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
        <div className="rounded-lg border border-border/60 bg-card/60 p-3">
          <div className="text-[11px] font-bold uppercase tracking-wider text-muted-foreground mb-1">
            {t("platformHealth.incidents.affectedService") || "Affected Service"}
          </div>
          <div className="text-sm font-semibold text-foreground flex items-center gap-2">
            <Layers className="h-4 w-4 text-primary" />
            <span>{incident.affectedService}</span>
          </div>
        </div>

        <div className="rounded-lg border border-border/60 bg-card/60 p-3">
          <div className="text-[11px] font-bold uppercase tracking-wider text-muted-foreground mb-1">
            {t("platformHealth.incidents.impact") || "Operational Impact"}
          </div>
          <p className="text-xs text-muted-foreground leading-snug">
            {incident.impact || "Standard operational latency threshold exceeded."}
          </p>
        </div>
      </div>

      {/* Investigation Timeline */}
      <div className="pt-2 border-t border-border/60">
        <div className="text-[11px] font-bold uppercase tracking-wider text-muted-foreground mb-2">
          {t("platformHealth.incidents.timeline") || "Investigation Timeline"}
        </div>
        <div className="space-y-2 text-xs">
          <div className="flex items-start gap-2">
            <span className="h-2 w-2 rounded-full bg-primary mt-1 shrink-0" />
            <div>
              <span className="font-semibold text-foreground">Detected:</span>{" "}
              <span className="text-muted-foreground">
                Automated health probe logged status change at{" "}
                {new Date(incident.detectedAt).toLocaleTimeString()}.
              </span>
            </div>
          </div>
          {incident.resolvedAt && (
            <div className="flex items-start gap-2">
              <span className="h-2 w-2 rounded-full bg-emerald-500 mt-1 shrink-0" />
              <div>
                <span className="font-semibold text-emerald-400">Resolved:</span>{" "}
                <span className="text-muted-foreground">
                  Metrics returned to normal operating limits at{" "}
                  {new Date(incident.resolvedAt).toLocaleTimeString()}.
                </span>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import Link from "next/link";
import { useI18n } from "@core/providers/i18n-provider";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
} from "@core/ui/sheet";
import { Badge } from "@core/ui/badge";
import { Button } from "@core/ui/button";
import { Separator } from "@core/ui/separator";
import {
  Check,
  Copy,
  ExternalLink,
  Clock,
  User,
  Globe,
  Terminal,
  FileCode,
} from "lucide-react";
import { formatDateTimeUtc } from "@core/common/utils";
import type { SecurityChange } from "../../domain/entities/SecurityEntities";

interface EventDetailsDrawerProps {
  event: SecurityChange | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function EventDetailsDrawer({
  event,
  open,
  onOpenChange,
}: EventDetailsDrawerProps) {
  const { t } = useI18n();
  const [copied, setCopied] = useState(false);

  if (!event) return null;

  const handleCopyId = () => {
    if (event.id) {
      navigator.clipboard.writeText(event.id);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const auditUrl = `/audit?search=${encodeURIComponent(
    event.username || event.ipAddress || event.eventType
  )}`;

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent side="right" className="w-full sm:max-w-md p-6 space-y-6 overflow-y-auto">
        <SheetHeader className="space-y-2">
          <div className="flex items-center gap-2">
            <Badge
              variant={event.isSuccess ? "success" : "destructive"}
              className="text-[10px] uppercase font-bold"
            >
              {event.isSuccess ? "Success" : "Failed / Blocked"}
            </Badge>
            <span className="text-xs text-muted-foreground font-mono" dir="ltr">
              {event.eventType}
            </span>
          </div>

          <SheetTitle className="text-lg font-bold">
            {event.eventType} Event Details
          </SheetTitle>
          <SheetDescription className="text-xs text-muted-foreground">
            Authoritative security audit record captured by Identity telemetry.
          </SheetDescription>
        </SheetHeader>

        <Separator />

        {/* Core Attributes */}
        <div className="space-y-4 text-xs">
          {/* Timestamp */}
          <div className="flex items-start gap-3">
            <Clock className="h-4 w-4 text-muted-foreground mt-0.5" />
            <div className="flex-1">
              <span className="font-semibold text-foreground">Timestamp (UTC)</span>
              <p className="text-muted-foreground mt-0.5 tabular-nums">
                {formatDateTimeUtc(event.timestamp)}
              </p>
            </div>
          </div>

          {/* Actor */}
          <div className="flex items-start gap-3">
            <User className="h-4 w-4 text-muted-foreground mt-0.5" />
            <div className="flex-1">
              <div className="flex items-center gap-2">
                <span className="font-semibold text-foreground">Actor</span>
                {event.isAdmin && (
                  <Badge variant="outline" className="text-[9px] px-1 py-0">
                    Admin
                  </Badge>
                )}
              </div>
              <p className="text-muted-foreground mt-0.5">
                {event.username || "System / Unauthenticated"}
              </p>
            </div>
          </div>

          {/* IP Address */}
          <div className="flex items-start gap-3">
            <Globe className="h-4 w-4 text-muted-foreground mt-0.5" />
            <div className="flex-1">
              <span className="font-semibold text-foreground">Source IP Address</span>
              <p className="text-muted-foreground mt-0.5 font-mono" dir="ltr">
                {event.ipAddress || "—"}
              </p>
            </div>
          </div>

          {/* Endpoint / Method */}
          {(event.endpoint || event.httpMethod) && (
            <div className="flex items-start gap-3">
              <Terminal className="h-4 w-4 text-muted-foreground mt-0.5" />
              <div className="flex-1">
                <span className="font-semibold text-foreground">Endpoint</span>
                <p className="text-muted-foreground mt-0.5 font-mono text-[11px]" dir="ltr">
                  {event.httpMethod ? `[${event.httpMethod}] ` : ""}
                  {event.endpoint || "—"}
                </p>
              </div>
            </div>
          )}

          {/* Entity Context */}
          {event.entityType && (
            <div className="flex items-start gap-3">
              <FileCode className="h-4 w-4 text-muted-foreground mt-0.5" />
              <div className="flex-1">
                <span className="font-semibold text-foreground">Target Resource</span>
                <p className="text-muted-foreground mt-0.5">
                  {event.entityType} {event.entityId ? `(${event.entityId})` : ""}
                </p>
              </div>
            </div>
          )}

          {/* Error Message */}
          {event.errorMessage && (
            <div className="rounded-md border border-destructive/30 bg-destructive/10 p-3 space-y-1">
              <span className="font-semibold text-destructive">Failure Detail</span>
              <p className="text-muted-foreground text-[11px] leading-relaxed">
                {event.errorMessage}
              </p>
            </div>
          )}

          {/* Event / Correlation ID */}
          <div className="rounded-lg border border-border/80 bg-muted/30 p-3 space-y-2">
            <div className="flex items-center justify-between">
              <span className="text-[11px] font-semibold text-muted-foreground">
                Audit Record ID
              </span>
              <Button
                variant="ghost"
                size="sm"
                onClick={handleCopyId}
                className="h-6 px-1.5 text-[11px] gap-1 text-primary hover:text-primary"
              >
                {copied ? <Check className="h-3 w-3" /> : <Copy className="h-3 w-3" />}
                <span>{copied ? "Copied" : "Copy"}</span>
              </Button>
            </div>
            <p className="font-mono text-[11px] text-foreground break-all select-all" dir="ltr">
              {event.id}
            </p>
          </div>
        </div>

        <Separator />

        {/* Drawer Actions */}
        <div className="space-y-2 pt-2">
          <Button variant="default" asChild className="w-full gap-2 text-xs">
            <Link href={auditUrl} onClick={() => onOpenChange(false)}>
              <ExternalLink className="h-3.5 w-3.5" />
              <span>Investigate in Audit Log</span>
            </Link>
          </Button>

          <Button
            variant="outline"
            onClick={() => onOpenChange(false)}
            className="w-full text-xs"
          >
            Close
          </Button>
        </div>
      </SheetContent>
    </Sheet>
  );
}

"use client";
/**
 * useAnalyticsViewModel — Main viewmodel hook for the Revenue Analytics dashboard.
 *
 * Provides TanStack Query-based data fetching for all analytics tabs:
 * Overview, MRR Movement, Cohort, LTV, Forecast, and Health Scores.
 */
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useState, useCallback } from "react";
import { entitlementsContainer } from "@modules/entitlements/di";
import type { UpdateReportPreferenceRequest } from "../../domain/entities/AnalyticsEntities";

const QUERY_KEYS = {
  overview: (months: number) => ["analytics", "overview", months],
  mrrMovement: (months: number) => ["analytics", "mrr-movement", months],
  cohort: (months: number) => ["analytics", "cohort", months],
  ltv: () => ["analytics", "ltv"],
  forecast: (months: number) => ["analytics", "forecast", months],
  healthScores: (page: number, pageSize: number) => ["analytics", "health-scores", page, pageSize],
  reportPreferences: () => ["analytics", "report-preferences"],
};

/**
 * Exported type defining parameters and fields for analytics tab configurations.
 */
export type AnalyticsTab =
  | "overview"
  | "revenue"
  | "retention"
  | "ltv"
  | "forecast"
  | "health"
  | "reports";

/**
 * React hook/ViewModel orchestrating state and data flows for analytics view model.
 * Manages TanStack Query hooks, query cache keys, and repository fetch requests.
 */
export function useAnalyticsViewModel() {
  const { analyticsRepository } = entitlementsContainer;
  const queryClient = useQueryClient();

  // ── Tab & filter state ──
  const [activeTab, setActiveTab] = useState<AnalyticsTab>("overview");
  const [months, setMonths] = useState(12);
  const [forecastMonths, setForecastMonths] = useState(6);
  const [healthPage, setHealthPage] = useState(1);
  const [healthPageSize, setHealthPageSize] = useState(20);

  // ── Overview ──
  const overviewQuery = useQuery({
    queryKey: QUERY_KEYS.overview(months),
    queryFn: () => analyticsRepository.getOverview(months),
    enabled: activeTab === "overview",
    staleTime: 5 * 60 * 1000, // 5 min
  });

  // ── MRR Movement ──
  const mrrQuery = useQuery({
    queryKey: QUERY_KEYS.mrrMovement(months),
    queryFn: () => analyticsRepository.getMrrMovement(months),
    enabled: activeTab === "revenue",
    staleTime: 5 * 60 * 1000,
  });

  // ── Cohort Analysis ──
  const cohortQuery = useQuery({
    queryKey: QUERY_KEYS.cohort(months),
    queryFn: () => analyticsRepository.getCohortAnalysis(months),
    enabled: activeTab === "retention",
    staleTime: 10 * 60 * 1000, // 10 min — heavy computation
  });

  // ── LTV by Edition ──
  const ltvQuery = useQuery({
    queryKey: QUERY_KEYS.ltv(),
    queryFn: () => analyticsRepository.getLtvByEdition(),
    enabled: activeTab === "ltv",
    staleTime: 10 * 60 * 1000,
  });

  // ── Revenue Forecast ──
  const forecastQuery = useQuery({
    queryKey: QUERY_KEYS.forecast(forecastMonths),
    queryFn: () => analyticsRepository.getForecast(forecastMonths),
    enabled: activeTab === "forecast",
    staleTime: 15 * 60 * 1000, // 15 min — expensive
  });

  // ── Health Scores ──
  const healthQuery = useQuery({
    queryKey: QUERY_KEYS.healthScores(healthPage, healthPageSize),
    queryFn: () => analyticsRepository.getHealthScores(healthPage, healthPageSize),
    enabled: activeTab === "health",
    staleTime: 5 * 60 * 1000,
  });

  // ── Report Preferences ──
  const preferencesQuery = useQuery({
    queryKey: QUERY_KEYS.reportPreferences(),
    queryFn: () => analyticsRepository.getReportPreferences(),
    staleTime: 30 * 60 * 1000, // 30 min — rarely changes
  });

  const updatePreferencesMutation = useMutation({
    mutationFn: (data: UpdateReportPreferenceRequest) =>
      analyticsRepository.updateReportPreferences(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["analytics", "report-preferences"] });
    },
  });

  // ── Export ──
  const exportMutation = useMutation({
    mutationFn: (format: string) =>
      analyticsRepository.exportAnalytics({
        format,
        includeMrrMovement: true,
        includeCohort: true,
        includeHealth: true,
        includeForecast: true,
      }),
    onSuccess: (blob, format) => {
      downloadBlob(
        blob,
        `analytics-export.${format === "xlsx" ? "xlsx" : format === "pdf" ? "pdf" : "csv"}`
      );
    },
  });

  const generateReportMutation = useMutation({
    mutationFn: () => analyticsRepository.generateReport({ currency: "USD" }),
    onSuccess: (blob) => {
      downloadBlob(blob, `analytics-report-${new Date().toISOString().slice(0, 10)}.pdf`);
    },
  });

  // ── Handlers ──
  const handleTabChange = useCallback((tab: AnalyticsTab) => {
    setActiveTab(tab);
  }, []);

  const handleMonthsChange = useCallback((m: number) => {
    setMonths(m);
  }, []);

  const handleForecastMonthsChange = useCallback((m: number) => {
    setForecastMonths(m);
  }, []);

  const handleHealthPageChange = useCallback((page: number) => {
    setHealthPage(page);
  }, []);

  const handleExport = useCallback(
    async (format: string) => {
      await exportMutation.mutateAsync(format);
    },
    [exportMutation]
  );

  const handleGenerateReport = useCallback(async () => {
    await generateReportMutation.mutateAsync();
  }, [generateReportMutation]);

  return {
    // State
    activeTab,
    months,
    forecastMonths,
    healthPage,
    healthPageSize,

    // Queries
    overview: overviewQuery.data,
    overviewLoading: overviewQuery.isLoading,
    overviewError: overviewQuery.error,
    overviewRefetch: overviewQuery.refetch,
    mrrMovement: mrrQuery.data,
    mrrLoading: mrrQuery.isLoading,
    mrrError: mrrQuery.error,
    mrrRefetch: mrrQuery.refetch,
    cohort: cohortQuery.data,
    cohortLoading: cohortQuery.isLoading,
    cohortError: cohortQuery.error,
    cohortRefetch: cohortQuery.refetch,
    ltv: ltvQuery.data,
    ltvLoading: ltvQuery.isLoading,
    ltvError: ltvQuery.error,
    ltvRefetch: ltvQuery.refetch,
    forecast: forecastQuery.data,
    forecastLoading: forecastQuery.isLoading,
    forecastError: forecastQuery.error,
    forecastRefetch: forecastQuery.refetch,
    health: healthQuery.data,
    healthLoading: healthQuery.isLoading,
    healthError: healthQuery.error,
    healthRefetch: healthQuery.refetch,
    reportPreferences: preferencesQuery.data,
    reportPreferencesLoading: preferencesQuery.isLoading,
    reportPreferencesError: preferencesQuery.error,
    reportPreferencesRefetch: preferencesQuery.refetch,

    // Mutations
    updatePreferences: updatePreferencesMutation.mutateAsync,
    isUpdatingPreferences: updatePreferencesMutation.isPending,
    handleExport,
    isExporting: exportMutation.isPending,
    handleGenerateReport,
    isGeneratingReport: generateReportMutation.isPending,

    // Handlers
    handleTabChange,
    handleMonthsChange,
    handleForecastMonthsChange,
    handleHealthPageChange,
  };
}

/** Trigger a browser file download from a Blob. */
function downloadBlob(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

