"use client";

import { useMemo } from "react";
import { useRouter } from "next/navigation";
import { GenericCrudView } from "@core/crud/components/generic-crud-view";
import type { CrudConfig, CrudAction } from "@core/crud/components/generic-crud-view";
import { useEditionsViewModel } from "../viewmodels/useEditionsViewModel";
import { useI18n } from "@core/providers/i18n-provider";
import type { Edition } from "../../domain/entities/Edition";
import { Badge } from "@core/ui/badge";
import { Pencil, Trash2, Eye, Settings2, Columns, AlertCircle } from "lucide-react";
import { formatUtc } from "@core/common/utils";
import { useModuleLocales } from "@core/hooks/use-module-locales";

/**
 * Presentation UI component rendering the editions view.
 * Arranges layout boundaries and accessibility targets (WCAG, tab index) using the core design library (@core/ui/*). Coordinates text fields, submit indicators, and validation warning messages.
 */
export function EditionsView() {
  useModuleLocales(() => import("../../../locales"), "editions");
  const { t, language } = useI18n();
  const vm = useEditionsViewModel();
  const router = useRouter();

  const config: CrudConfig<Edition> = useMemo(
    () => ({
      titleKey: "entitlements.editions.title",
      subtitleKey: "entitlements.editions.description",
      resource: "editions",
      customActions: [
        {
          label: t("entitlements.editions.comparison.heroTitle"),
          onClick: async () => {
            router.push("/entitlements/editions/compare");
          },
          variant: "outline" as const,
          icon: <Columns className="h-4 w-4" />,
        },
      ],
      onCreateClick: () => router.push("/entitlements/editions/create"),
      columns: [
        {
          key: "name",
          label: t("entitlements.editions.editionName"),
          sortable: true,
        },
        {
          key: "displayName",
          label: t("entitlements.editions.displayName"),
          render: (_val: unknown, edition: Edition) => edition.getDisplayName(language),
        },
        {
          key: "features",
          label: t("entitlements.editions.featureCount"),
          render: (_val: unknown, edition: Edition) => (
            <Badge variant="secondary">{edition.featureCount}</Badge>
          ),
        },
        {
          key: "category",
          label: t("entitlements.features.category"),
          render: (_val: unknown, edition: Edition) =>
            edition.category ? (
              <Badge variant="secondary">{edition.category}</Badge>
            ) : (
              <span className="text-nx-ink-3">—</span>
            ),
        },
        {
          key: "baseMonthlyPriceUsd",
          label: t("entitlements.pricing.price"),
          render: (_val: unknown, edition: Edition) => {
            const price = edition.baseMonthlyPriceUsd;
            if (price == null || price === 0) {
              return <span className="text-nx-ink-3">—</span>;
            }
            const formatted = new Intl.NumberFormat("en-US", {
              style: "currency",
              currency: "USD",
              minimumFractionDigits: 0,
            }).format(price);
            return (
              <span className="text-sm font-medium tabular-nums text-success">
                {formatted}
                <span className="text-xs text-nx-ink-3">/mo</span>
              </span>
            );
          },
        },
        {
          key: "isRetired",
          label: t("entitlements.editions.status"),
          render: (_val: unknown, edition: Edition) => (
            <Badge variant={edition.isRetired ? "destructive" : "success"}>
              {edition.isRetired ? t("entitlements.editions.retired") : t("common.active")}
            </Badge>
          ),
        },
        {
          key: "createdAt",
          label: t("common.createdAt"),
          render: (value: string) => (value ? formatUtc(value, "MMM d, yyyy") : "-"),
        },
      ],
      getItemDisplayName: (edition: Edition) => edition.getDisplayName(language),
      deleteService: (id: string) => vm.deleteItem(id),
      getActions: (
        vmInstance: ReturnType<typeof useEditionsViewModel>,
        tFn: (key: string) => string,
        handleDeleteFn: ((item: Edition) => void) | undefined
      ): CrudAction<Edition>[] => [
        {
          label: tFn("common.view"),
          onClick: (item: Edition) => router.push(`/entitlements/editions/${item.id}/overview`),
          variant: "ghost" as const,
          icon: <Eye className="h-4 w-4" />,
        },
        {
          label: tFn("common.edit"),
          onClick: (item: Edition) => router.push(`/entitlements/editions/${item.id}/edit`),
          variant: "ghost" as const,
          icon: <Pencil className="h-4 w-4" />,
        },
        {
          label: tFn("entitlements.editions.manageFeatures"),
          onClick: (item: Edition) => vmInstance.navigateToFeatures(item.id),
          variant: "ghost" as const,
          icon: <Settings2 className="h-4 w-4" />,
        },
        {
          label: tFn("common.delete"),
          onClick: (item: Edition) => handleDeleteFn?.(item),
          variant: "ghost" as const,
          className: "text-destructive hover:text-destructive/80",
          icon: <Trash2 className="h-4 w-4" />,
          show: (item: Edition) => !item.isSystem,
        },
      ],
    }),
    [t, vm, language]
  );

  return (
    <>
      {vm.allEditionsError && (
        <div className="mb-4 flex items-center gap-2 rounded-nx-md border border-warning/30 bg-warning/10 px-4 py-3 text-sm text-warning">
          <AlertCircle className="h-4 w-4 shrink-0" />
          <span>{t("entitlements.editions.allEditionsLoadError")}</span>
        </div>
      )}
      <GenericCrudView viewModel={vm} config={config} />
    </>
  );
}

"use client";

import { useState, useCallback, useMemo } from "react";
import { useQuery } from "@tanstack/react-query";
import { entitlementsContainer } from "@modules/entitlements/di";
import type {
  ConvertLeadParams,
  EditionForConversion,
  EditionFeatureGroup,
  FeatureOverride,
} from "../../domain/interfaces/ILeadsRepository";
import type { PlatformLead } from "../../domain/entities/PlatformLead";

// ── Types ─────────────────────────────────────────────────────────────────────

/**
 * Exported type defining parameters and fields for wizard step configurations.
 */
export type WizardStep = 1 | 2 | 3 | 4;

/**
 * Interface defining property specifications, keys types, and structural contract rules for step2 state.
 */
export interface Step2State {
  tenantCode: string;
  adminEmail: string;
  subscriptionType: string;
  currency: string;
  useCustomPrice: boolean;
  negotiatedAmount: string;
  negotiatedCurrency: string;
  conversionNote: string;
}

const STEP2_DEFAULTS: Step2State = {
  tenantCode: "",
  adminEmail: "",
  subscriptionType: "",
  currency: "USD",
  useCustomPrice: false,
  negotiatedAmount: "",
  negotiatedCurrency: "USD",
  conversionNote: "",
};

// ── Hook ──────────────────────────────────────────────────────────────────────

/**
 * React hook/ViewModel orchestrating state and data flows for convert wizard view model.
 * Manages TanStack Query hooks, query cache keys, and repository fetch requests.
 */
export function useConvertWizardViewModel(
  open: boolean,
  lead: PlatformLead | null,
  onConvert: (params: ConvertLeadParams) => Promise<void>,
  onClose: () => void,
  isConverting: boolean
) {
  const { leadsRepository } = entitlementsContainer;

  // ── Step navigation ────────────────────────────────────────────────────────
  const [step, setStep] = useState<WizardStep>(1);

  // ── Step 1 state ───────────────────────────────────────────────────────────
  const [selectedEditionOverride, setSelectedEditionOverride] =
    useState<EditionForConversion | null>(null);

  // ── Step 2 state ───────────────────────────────────────────────────────────
  const [s2, setS2] = useState<Step2State>(STEP2_DEFAULTS);
  const [amountError, setAmountError] = useState("");

  // ── Step 3 state ───────────────────────────────────────────────────────────
  const [overrides, setOverrides] = useState<Record<string, string>>({});
  const [expandedCategories, setExpandedCategories] = useState<Set<string>>(new Set());

  // ── Queries ────────────────────────────────────────────────────────────────
  const editionsQuery = useQuery({
    queryKey: ["conversion-editions"],
    queryFn: () => leadsRepository.getEditionsForConversion(),
    enabled: open,
    staleTime: 5 * 60 * 1000,
  });

  // Auto-select requested edition from lead
  const editions = editionsQuery.data;
  const leadEditionKey = lead?.editionKey?.toLowerCase();
  const selectedEdition =
    selectedEditionOverride ??
    (lead && editions
      ? editions.find((e) => e.name.toLowerCase() === leadEditionKey) ?? null
      : null);

  const featuresQuery = useQuery({
    queryKey: ["conversion-edition-features", selectedEdition?.id],
    queryFn: () => leadsRepository.getEditionFeaturesForConversion(selectedEdition!.id),
    enabled: !!selectedEdition && step >= 3,
    staleTime: 5 * 60 * 1000,
  });

  const featureGroups: EditionFeatureGroup[] = featuresQuery.data ?? [];

  // ── Override count ─────────────────────────────────────────────────────────
  const overrideCount = useMemo(() => {
    if (!featureGroups.length) return 0;
    return Object.keys(overrides).filter((fid) => {
      const feature = featureGroups.flatMap((g) => g.features).find((f) => f.featureId === fid);
      return feature && overrides[fid] !== feature.editionValue;
    }).length;
  }, [overrides, featureGroups]);

  // ── Helpers ────────────────────────────────────────────────────────────────
  const validateAmount = useCallback((val: string): boolean => {
    if (!val.trim()) {
      setAmountError("Amount is required.");
      return false;
    }
    const n = parseFloat(val);
    if (isNaN(n) || n <= 0) {
      setAmountError("Enter a valid positive amount.");
      return false;
    }
    setAmountError("");
    return true;
  }, []);

  const initOverrides = useCallback((groups: EditionFeatureGroup[]) => {
    const initial: Record<string, string> = {};
    groups.forEach((g) =>
      g.features.forEach((f) => {
        initial[f.featureId] = f.editionValue;
      })
    );
    setOverrides(initial);
    setExpandedCategories(new Set(groups.map((g) => g.category)));
  }, []);

  const toggleCategory = useCallback((cat: string) => {
    setExpandedCategories((prev) => {
      const next = new Set(prev);
      next.has(cat) ? next.delete(cat) : next.add(cat);
      return next;
    });
  }, []);

  const resetWizard = useCallback(() => {
    setStep(1);
    setSelectedEditionOverride(null);
    setS2(STEP2_DEFAULTS);
    setAmountError("");
    setOverrides({});
    setExpandedCategories(new Set());
  }, []);

  const handleClose = useCallback(() => {
    if (isConverting) return;
    resetWizard();
    onClose();
  }, [isConverting, resetWizard, onClose]);

  const featuresData = featuresQuery.data;
  const handleNext = useCallback(async () => {
    if (step === 1) {
      if (!selectedEdition) return;
      setStep(2);
      if (selectedEdition.isContactSalesOnly) {
        setS2((prev) => ({ ...prev, useCustomPrice: true }));
      }
    } else if (step === 2) {
      if (s2.useCustomPrice && !validateAmount(s2.negotiatedAmount)) return;
      setStep(3);
      if (featuresData) initOverrides(featuresData);
    } else if (step === 3) {
      setStep(4);
    }
  }, [step, selectedEdition, s2, validateAmount, featuresData, initOverrides]);

  const handleBack = useCallback(() => {
    if (step > 1) setStep((prev) => (prev - 1) as WizardStep);
  }, [step]);

  const handleSubmit = useCallback(async () => {
    const featureOverrides: FeatureOverride[] = Object.entries(overrides)
      .filter(([fid, val]) => {
        const feature = featureGroups.flatMap((g) => g.features).find((f) => f.featureId === fid);
        return feature && val !== feature.editionValue;
      })
      .map(([featureId, value]) => ({ featureId, value }));

    const negotiatedAmount =
      s2.useCustomPrice && s2.negotiatedAmount.trim() ? parseFloat(s2.negotiatedAmount) : undefined;

    await onConvert({
      editionId: selectedEdition?.id,
      tenantCode: s2.tenantCode.trim() || undefined,
      adminEmail: s2.adminEmail.trim() || undefined,
      subscriptionType: s2.subscriptionType || undefined,
      currency: s2.currency || undefined,
      conversionNote: s2.conversionNote.trim() || undefined,
      negotiatedAmount,
      negotiatedCurrency: s2.useCustomPrice ? s2.negotiatedCurrency : undefined,
      featureOverrides: featureOverrides.length > 0 ? featureOverrides : undefined,
    });
  }, [overrides, featureGroups, s2, selectedEdition, onConvert]);

  const handleOverrideChange = useCallback((featureId: string, value: string) => {
    setOverrides((p) => ({ ...p, [featureId]: value }));
  }, []);

  const handleAmountChange = useCallback(
    (val: string) => {
      setS2((p) => ({ ...p, negotiatedAmount: val }));
      if (amountError) validateAmount(val);
    },
    [amountError, validateAmount]
  );

  return {
    step,
    selectedEdition,
    setSelectedEdition: setSelectedEditionOverride,
    s2,
    setS2,
    amountError,
    overrides,
    expandedCategories,
    featureGroups,
    overrideCount,
    isLoadingEditions: editionsQuery.isLoading,
    editions: editionsQuery.data,
    isLoadingFeatures: featuresQuery.isLoading,
    handleClose,
    handleNext,
    handleBack,
    handleSubmit,
    toggleCategory,
    handleOverrideChange,
    handleAmountChange,
  };
}

import type {
  IOnboardingQuestionRepository,
  OnboardingQuestionsListParams,
} from "../../domain/interfaces/IOnboardingQuestionRepository";
import type { IOnboardingQuestionService } from "../../domain/interfaces/IOnboardingQuestionService";
import type {
  CreateOnboardingQuestionRequest,
  UpdateOnboardingQuestionRequest,
  AnswerOptionRequest,
} from "../../domain/entities/OnboardingQuestionRequests";
import { OnboardingQuestionMapper } from "../mappers/OnboardingQuestionMapper";
import type {
  OnboardingQuestion,
  AnswerOptionData,
} from "../../domain/entities/OnboardingQuestion";
import type { PagedResult } from "@core/interfaces/common.interface";

/**
 * Repository layer implementing client request queries for onboarding question.
 * Calls base API service routines and resolves DTO objects mapping to domain entities.
 */
export class OnboardingQuestionRepository implements IOnboardingQuestionRepository {
  constructor(private readonly service: IOnboardingQuestionService) {}

  async getAll(params: OnboardingQuestionsListParams): Promise<PagedResult<OnboardingQuestion>> {
    const result = await this.service.getAll(params);
    return {
      items: result.items.map((m) => OnboardingQuestionMapper.toEntity(m)),
      totalCount: result.totalCount,
      pageNumber: result.pageNumber,
      pageSize: result.pageSize,
      totalPages: result.totalPages,
      hasNextPage: result.pageNumber < result.totalPages,
      hasPreviousPage: result.pageNumber > 1,
    };
  }

  async getById(id: string): Promise<OnboardingQuestion> {
    const model = await this.service.getById(id);
    return OnboardingQuestionMapper.toEntity(model);
  }

  async create(request: CreateOnboardingQuestionRequest): Promise<string> {
    const result = await this.service.create(request);
    return result.id;
  }

  async update(id: string, request: UpdateOnboardingQuestionRequest): Promise<void> {
    await this.service.update(id, request);
  }

  async delete(id: string): Promise<void> {
    await this.service.delete(id);
  }

  async listOptions(questionId: string): Promise<AnswerOptionData[]> {
    try {
      const models = await this.service.listOptions(questionId);
      return models.map((m) => ({
        id: m.id,
        value: m.value,
        labelEn: m.labelEn,
        labelAr: m.labelAr,
        sublabelEn: m.sublabelEn,
        sublabelAr: m.sublabelAr,
        iconKey: m.iconKey,
        sortOrder: m.sortOrder,
        signalWeight: m.signalWeight,
        isActive: m.isActive,
      }));
    } catch (error) {
      // Fallback to fetching the entire question if the options sub-resource endpoint is not yet active/recompiled
      const question = await this.getById(questionId);
      return question.options;
    }
  }

  async createOption(questionId: string, request: AnswerOptionRequest): Promise<string> {
    const result = await this.service.createOption(questionId, request);
    return result.id;
  }

  async updateOption(
    questionId: string,
    optionId: string,
    request: AnswerOptionRequest
  ): Promise<void> {
    await this.service.updateOption(questionId, optionId, request);
  }

  async deleteOption(questionId: string, optionId: string): Promise<void> {
    await this.service.deleteOption(questionId, optionId);
  }

  async reorderOptions(questionId: string, orderedIds: string[]): Promise<void> {
    await this.service.reorderOptions(questionId, orderedIds);
  }
}

/**
 * Feature Overrides ViewModel
 *
 * Manages per-tenant feature overrides: fetching overrides + resolved features,
 * setting overrides, and removing them.
 * Uses repository (not service directly) per clean architecture.
 * Owns pagination state and all logic — View is pure UI.
 */
"use client";

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { entitlementsContainer } from "@modules/entitlements/di";
import { useEnhancedToast } from "@core/hooks/use-enhanced-toast";
import { useI18n } from "@core/providers/i18n-provider";
import { useState, useCallback, useMemo } from "react";
import { parseLocalizedNumber } from "@core/utils/number-parser";

const ITEMS_PER_PAGE = 10;

/**
 * React hook/ViewModel orchestrating state and data flows for overrides view model.
 * Manages TanStack Query hooks, query cache keys, and repository fetch requests.
 */
export function useOverridesViewModel(tenantId: string) {
  const { overrideRepository } = entitlementsContainer;
  const queryClient = useQueryClient();
  const { success, error: showError } = useEnhancedToast();
  const { t } = useI18n();

  // ─── Pagination & Search state ───────────────────────
  const [resolvedSearch, setResolvedSearch] = useState("");
  const [resolvedPage, setResolvedPage] = useState(1);
  const [overridesPage, setOverridesPage] = useState(1);

  // ─── Dialog state ──────────────────────────────────
  const [editingFeature, setEditingFeature] = useState<{
    featureId: string;
    featureName: string;
    valueType: string;
    currentValue: string;
  } | null>(null);
  const [overrideValue, setOverrideValue] = useState("");
  const [overrideReason, setOverrideReason] = useState("");

  // ─── Cost dialog state ──────────────────────────────
  const [costOverrideId, setCostOverrideId] = useState<string | null>(null);
  const [costAmount, setCostAmount] = useState("");
  const [costReason, setCostReason] = useState("");

  // Per-row pending state — keyed by feature id so removing one override
  // never busies/disables the Remove button on the other rows.
  const [pendingRemoveFeatureIds, setPendingRemoveFeatureIds] = useState<Set<string>>(new Set());

  // ─── Query keys ────────────────────────────────────
  const overridesKey = ["entitlements", "overrides", tenantId];
  const resolvedKey = ["entitlements", "resolved", tenantId];

  // ─── Fetch overrides ───────────────────────────────
  const overridesQuery = useQuery({
    queryKey: overridesKey,
    queryFn: () => overrideRepository.getOverrides(tenantId),
    enabled: !!tenantId,
  });

  // ─── Fetch resolved features ──────────────────────
  const resolvedQuery = useQuery({
    queryKey: resolvedKey,
    queryFn: () => overrideRepository.getResolved(tenantId),
    enabled: !!tenantId,
  });

  const overrides = overridesQuery.data ?? [];
  const resolvedFeatures = resolvedQuery.data ?? [];

  // ─── Filtered & Paginated data ─────────────────────
  const filteredResolved = useMemo(() => {
    if (!resolvedSearch) return resolvedFeatures;
    const searchLower = resolvedSearch.toLowerCase();
    return resolvedFeatures.filter(
      (f) =>
        f.key.toLowerCase().includes(searchLower) ||
        f.nameEn.toLowerCase().includes(searchLower) ||
        f.nameAr.toLowerCase().includes(searchLower)
    );
  }, [resolvedFeatures, resolvedSearch]);

  const resolvedTotalPages = Math.max(1, Math.ceil(filteredResolved.length / ITEMS_PER_PAGE));
  const safeResolvedPage = Math.min(resolvedPage, resolvedTotalPages);
  const paginatedResolved = useMemo(
    () =>
      filteredResolved.slice(
        (safeResolvedPage - 1) * ITEMS_PER_PAGE,
        safeResolvedPage * ITEMS_PER_PAGE
      ),
    [filteredResolved, safeResolvedPage]
  );

  const overridesTotalPages = Math.max(1, Math.ceil(overrides.length / ITEMS_PER_PAGE));
  const safeOverridesPage = Math.min(overridesPage, overridesTotalPages);
  const paginatedOverrides = useMemo(
    () =>
      overrides.slice((safeOverridesPage - 1) * ITEMS_PER_PAGE, safeOverridesPage * ITEMS_PER_PAGE),
    [overrides, safeOverridesPage]
  );

  // ─── Invalidation helper ───────────────────────────
  const invalidate = useCallback(() => {
    queryClient.invalidateQueries({ queryKey: overridesKey });
    queryClient.invalidateQueries({ queryKey: resolvedKey });
    queryClient.invalidateQueries({ queryKey: ["tenant-subscriptions", tenantId] });
    queryClient.invalidateQueries({ queryKey: ["tenants"] });
    queryClient.invalidateQueries({ queryKey: ["tenant", tenantId] });
  }, [queryClient, overridesKey, resolvedKey, tenantId]);

  // ─── Set override mutation ─────────────────────────
  const setOverrideMutation = useMutation({
    mutationFn: (params: { featureId: string; value: string; reason?: string }) =>
      overrideRepository.setOverride(tenantId, params.featureId, {
        value: params.value,
        reason: params.reason,
      }),
    onSuccess: () => {
      invalidate();
      success({
        title: t("entitlements.overrides.overrideSet"),
        description: t("entitlements.overrides.overrideSetDesc"),
      });
      setEditingFeature(null);
      setOverrideValue("");
      setOverrideReason("");
    },
    onError: (err: Error) => showError({ title: t("common.error"), description: err.message }),
  });

  // ─── Remove override mutation ──────────────────────
  const removeOverrideMutation = useMutation({
    mutationFn: (featureId: string) => overrideRepository.removeOverride(tenantId, featureId),
    onMutate: (featureId) => {
      setPendingRemoveFeatureIds((prev) => new Set(prev).add(featureId));
    },
    onSuccess: () => {
      invalidate();
      success({
        title: t("entitlements.overrides.overrideRemoved"),
        description: t("entitlements.overrides.overrideRemovedDesc"),
      });
    },
    onError: (err: Error) => showError({ title: t("common.error"), description: err.message }),
    onSettled: (_data, _err, featureId) => {
      setPendingRemoveFeatureIds((prev) => {
        const next = new Set(prev);
        next.delete(featureId);
        return next;
      });
    },
  });

  // ─── Set override cost mutation ──────────────────────
  const setCostMutation = useMutation({
    mutationFn: (params: { overrideId: string; amountUsd: number; reason?: string }) =>
      overrideRepository.setOverrideCost(params.overrideId, params.amountUsd, params.reason),
    onSuccess: () => {
      invalidate();
      success({
        title: t("entitlements.overrides.costSet"),
        description: t("entitlements.overrides.costSetDesc"),
      });
      setCostOverrideId(null);
      setCostAmount("");
      setCostReason("");
    },
    onError: (err: Error) => showError({ title: t("common.error"), description: err.message }),
  });

  // ─── Remove override cost mutation ───────────────────
  const removeCostMutation = useMutation({
    mutationFn: (overrideId: string) => overrideRepository.removeOverrideCost(overrideId),
    onSuccess: () => {
      invalidate();
      success({
        title: t("entitlements.overrides.costRemoved"),
        description: t("entitlements.overrides.costRemovedDesc"),
      });
    },
    onError: (err: Error) => showError({ title: t("common.error"), description: err.message }),
  });

  // ─── Dialog actions ────────────────────────────────
  const openSetOverride = useCallback(
    (featureId: string, featureName: string, valueType: string, currentValue: string) => {
      setEditingFeature({ featureId, featureName, valueType, currentValue });
      setOverrideValue(currentValue);
      setOverrideReason("");
    },
    []
  );

  const submitOverride = useCallback(() => {
    if (!editingFeature) return;
    setOverrideMutation.mutate({
      featureId: editingFeature.featureId,
      value: overrideValue,
      reason: overrideReason || undefined,
    });
  }, [editingFeature, overrideValue, overrideReason, setOverrideMutation]);

  // ─── Public interface ──────────────────────────────
  return {
    // Data
    isLoading: overridesQuery.isLoading || resolvedQuery.isLoading,
    error: overridesQuery.error || resolvedQuery.error,

    // Overrides tab
    overrides,
    paginatedOverrides,
    overridesPage: safeOverridesPage,
    overridesTotalPages,
    setOverridesPage,

    // Resolved features tab
    resolvedFeatures,
    paginatedResolved,
    resolvedPage: safeResolvedPage,
    resolvedTotalPages,
    setResolvedPage,
    resolvedSearch,
    setResolvedSearch,

    // Set override dialog
    editingFeature,
    overrideValue,
    overrideReason,
    setOverrideValue,
    setOverrideReason,
    openSetOverride,
    closeSetOverride: () => setEditingFeature(null),
    submitOverride,
    isSaving: setOverrideMutation.isPending,

    // Remove override
    removeOverride: removeOverrideMutation.mutate,
    isRemoving: (featureId: string) => pendingRemoveFeatureIds.has(featureId),

    // Cost adjustment
    costOverrideId,
    costAmount,
    costReason,
    setCostAmount,
    setCostReason,
    openCostDialog: (overrideId: string) => {
      setCostOverrideId(overrideId);
      setCostAmount("");
      setCostReason("");
    },
    closeCostDialog: () => setCostOverrideId(null),
    submitCost: () => {
      if (!costOverrideId || !costAmount) return;
      setCostMutation.mutate({
        overrideId: costOverrideId,
        amountUsd: parseLocalizedNumber(costAmount) ?? 0,
        reason: costReason || undefined,
      });
    },
    isSavingCost: setCostMutation.isPending,
    removeCost: removeCostMutation.mutate,
    isRemovingCost: removeCostMutation.isPending,
  };
}

/**
 * Payment Gateway Settings ViewModel
 *
 * Fetches enabled gateways from the backend and exposes them
 * for the settings view. Read-only dashboard for platform admins.
 */
"use client";

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { entitlementsContainer } from "@modules/entitlements/di";
import { useEnhancedToast } from "@core/hooks/use-enhanced-toast";
import { useI18n } from "@core/providers/i18n-provider";
import { chartColor } from "@core/ui/chart";
/**
 * Interface defining property specifications, keys types, and structural contract rules for gateway info.
 */
export interface GatewayInfo {
  gateway: string;
  enabled: boolean;
  isDefault: boolean;
  supportsRecurring: boolean;
  supportsBillingPortal: boolean;
  supportedFeatures: string[];
  displayName: string;
  description: string;
  color: string;
  icon: "stripe" | "paypal" | "paymob" | "manual";
  features: string[];
}

const GATEWAY_META: Record<
  string,
  Pick<GatewayInfo, "displayName" | "description" | "color" | "icon" | "features">
> = {
  Stripe: {
    displayName: "Stripe",
    description: "stripeDesc",
    color: chartColor(4),
    icon: "stripe",
    features: [
      "recurring",
      "billingPortal",
      "multiCurrency",
      "webhooks",
      "refunds",
      "paymentLinks",
      "threeDSecure",
    ],
  },
  PayPal: {
    displayName: "PayPal",
    description: "paypalDesc",
    color: chartColor(1),
    icon: "paypal",
    features: ["recurring", "multiCurrency", "webhooks", "refunds", "paymentLinks"],
  },
  Paymob: {
    displayName: "Paymob",
    description: "paymobDesc",
    color: chartColor(3),
    icon: "paymob",
    features: ["checkout", "mobileWallet", "menaCurrencies", "tokenizedRecurring", "webhooks"],
  },
  Manual: {
    displayName: "Manual",
    description: "Manual payment processing — no online gateway",
    color: "var(--nx-ink-3)",
    icon: "manual",
    features: [],
  },
};

/**
 * React hook/ViewModel orchestrating state and data flows for payment gateways view model.
 * Manages TanStack Query hooks, query cache keys, and repository fetch requests.
 */
export function usePaymentGatewaysViewModel() {
  const { billingRepository } = entitlementsContainer;
  const queryClient = useQueryClient();
  const { success, error: showError } = useEnhancedToast();
  const { t } = useI18n();

  // Per-row pending state — keyed by gateway id so mutating one card never
  // busies/disables the others in the list.
  const [pendingTestGateways, setPendingTestGateways] = useState<Set<string>>(new Set());
  const [pendingToggleGateways, setPendingToggleGateways] = useState<Set<string>>(new Set());

  const { data, isLoading, error, refetch } = useQuery({
    queryKey: ["payment-gateways"],
    queryFn: async () => {
      return billingRepository.getGateways();
    },
    staleTime: 5 * 60 * 1000, // 5 minutes
  });

  const gateways: GatewayInfo[] = (data?.gateways ?? []).map((gw) => {
    const meta = GATEWAY_META[gw.gateway] ?? {
      displayName: gw.gateway,
      description: "",
      color: "var(--nx-ink-3)",
      icon: "manual" as const,
      features: [],
    };
    return {
      ...gw,
      ...meta,
      features: meta.features,
    };
  });

  const defaultGateway = data?.defaultGateway ?? "Stripe";
  const enabledCount = gateways.filter((g) => g.enabled).length;

  const testConnectionMutation = useMutation({
    mutationFn: (gateway: string) => billingRepository.testGatewayConnection(gateway),
    onMutate: (gateway) => {
      setPendingTestGateways((prev) => new Set(prev).add(gateway));
    },
    onSuccess: (res) => {
      success({ title: t("billing.gateways.testSuccess"), description: res.message });
    },
    onError: (err: Error & { response?: { data?: { error?: string } } }) => {
      const errorMessage = err.response?.data?.error || err.message;
      showError({ title: t("billing.gateways.testFailed"), description: errorMessage });
    },
    onSettled: (_data, _err, gateway) => {
      setPendingTestGateways((prev) => {
        const next = new Set(prev);
        next.delete(gateway);
        return next;
      });
    },
  });

  const toggleStatusMutation = useMutation({
    mutationFn: ({ gateway, enabled }: { gateway: string; enabled: boolean }) =>
      billingRepository.toggleGatewayStatus(gateway, enabled),
    onMutate: ({ gateway }) => {
      setPendingToggleGateways((prev) => new Set(prev).add(gateway));
    },
    onSuccess: (res: { actionRequired?: string; message: string }) => {
      if (res.actionRequired === "config_change") {
        showError({
          title: t("billing.gateways.configRequired"),
          description: res.message,
        });
      } else {
        success({ title: t("billing.gateways.toggleSuccess"), description: res.message });
        refetch();
      }
    },
    onError: (err: Error & { response?: { data?: { error?: string } } }) => {
      const errorMessage = err.response?.data?.error || err.message;
      showError({ title: t("billing.gateways.toggleFailed"), description: errorMessage });
    },
    onSettled: (_data, _err, { gateway }) => {
      setPendingToggleGateways((prev) => {
        const next = new Set(prev);
        next.delete(gateway);
        return next;
      });
    },
  });

  return {
    gateways,
    defaultGateway,
    enabledCount,
    totalCount: gateways.length,
    isLoading,
    error: error?.message,
    refetch,
    testConnection: (gateway: string) => testConnectionMutation.mutate(gateway),
    isTestingConnection: (gateway: string) => pendingTestGateways.has(gateway),
    toggleStatus: (gateway: string, enabled: boolean) =>
      toggleStatusMutation.mutate({ gateway, enabled }),
    isTogglingStatus: (gateway: string) => pendingToggleGateways.has(gateway),
  };
}

/**
 * CommissionRateConfig
 * Dialog for setting or clearing a per-tenant commission rate override.
 * Shows the 3-level resolution hierarchy clearly.
 */
"use client";

import { useEffect, useMemo } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@core/ui/dialog";
import { Button } from "@core/ui/button";
import { Input } from "@core/ui/input";
import { Badge } from "@core/ui/badge";
import {
  Form,
  FormField,
  FormItem,
  FormLabel,
  FormControl,
  FormDescription,
  FormMessage,
} from "@core/ui/form";
import { Info, X } from "lucide-react";
import type { ConnectAccountListItem } from "../../domain/entities/ConnectAccount";

type RateTarget = ConnectAccountListItem & { commissionRate?: number };

interface CommissionRateConfigProps {
  account: RateTarget | null;
  isOpen: boolean;
  onClose: () => void;
  onSave: (tenantId: string, rate: number | null) => void;
  isSaving: boolean;
  t: (key: string) => string;
}

interface RateFormValues {
  rate: string;
}

function buildSchema(t: (key: string) => string) {
  return z.object({
    rate: z.string().refine(
      (val) => {
        if (val === "") return true;
        const parsed = parseFloat(val);
        return !isNaN(parsed) && parsed >= 0 && parsed <= 50;
      },
      { message: t("entitlements.stripeConnect.commissionRateInvalid") }
    ),
  });
}

function toDefaultValues(account: RateTarget): RateFormValues {
  return { rate: account.commissionRate != null ? (account.commissionRate * 100).toFixed(2) : "" };
}

interface CommissionRateFormProps {
  account: RateTarget;
  onClose: () => void;
  onSave: (tenantId: string, rate: number | null) => void;
  isSaving: boolean;
  t: (key: string) => string;
}

/**
 * The dialog's body — a real react-hook-form instance so the field wears the
 * shared Form anatomy (label/control/hint/error on one rhythm, aria-invalid
 * driving the input's error skin) instead of hand-rolled state + a bare
 * validation string.
 */
function CommissionRateForm({ account, onClose, onSave, isSaving, t }: CommissionRateFormProps) {
  const schema = useMemo(() => buildSchema(t), [t]);
  const form = useForm<RateFormValues>({
    resolver: zodResolver(schema),
    defaultValues: toDefaultValues(account),
  });

  const tenantId = account.tenantId;
  const commissionRate = account.commissionRate;
  useEffect(() => {
    form.reset(toDefaultValues(account));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tenantId, commissionRate]);

  const onSubmit = (values: RateFormValues) => {
    if (values.rate === "") {
      onSave(account.tenantId, null);
      return;
    }
    onSave(account.tenantId, parseFloat(values.rate) / 100);
  };

  const handleClear = () => {
    form.setValue("rate", "", { shouldValidate: true });
    onSave(account.tenantId, null);
  };

  const effectiveRatePercent =
    account.effectiveCommissionRate != null
      ? (account.effectiveCommissionRate * 100).toFixed(2)
      : "—";

  const rateValue = form.watch("rate");

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4 py-2">
        {/* Effective rate display */}
        <div className="space-y-2 rounded-nx-md border border-nx-line bg-nx-raised p-3">
          <div className="flex items-center gap-2 text-sm font-medium text-nx-ink">
            <Info className="h-4 w-4 shrink-0 text-nx-ink-3" aria-hidden="true" />
            <span>
              {t("entitlements.stripeConnect.effectiveRate")}:{" "}
              <span className="tabular-nums">{effectiveRatePercent}%</span>
            </span>
          </div>
          <p className="text-xs leading-relaxed text-nx-ink-2">
            {t("entitlements.stripeConnect.effectiveRateDesc")}
          </p>
          {/* Resolution chain badges */}
          <div className="mt-1 flex flex-wrap gap-1">
            {(["tenantOverride", "editionRate", "globalDefault"] as const).map((level) => (
              <Badge key={level} variant="outline" className="font-normal">
                {t(`entitlements.stripeConnect.rateLevel.${level}`)}
              </Badge>
            ))}
          </div>
        </div>

        {/* Rate input */}
        <FormField
          control={form.control}
          name="rate"
          render={({ field }) => (
            <FormItem>
              <FormLabel>{t("entitlements.stripeConnect.commissionRateOverride")} (%)</FormLabel>
              <div className="flex gap-2">
                <FormControl>
                  <Input
                    type="number"
                    min={0}
                    max={50}
                    step={0.01}
                    placeholder={t("entitlements.stripeConnect.commissionRatePlaceholder")}
                    {...field}
                  />
                </FormControl>
                {rateValue !== "" && (
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    onClick={() => form.setValue("rate", "", { shouldValidate: true })}
                    aria-label={t("common.clearSelection")}
                  >
                    <X className="h-4 w-4" aria-hidden="true" />
                  </Button>
                )}
              </div>
              <FormDescription>
                {t("entitlements.stripeConnect.commissionRateFieldHint")}
              </FormDescription>
              <FormMessage />
            </FormItem>
          )}
        />

        <DialogFooter className="gap-2">
          {account.commissionRate != null && (
            <Button type="button" variant="outline" onClick={handleClear} disabled={isSaving}>
              {t("entitlements.stripeConnect.commissionRateClearAction")}
            </Button>
          )}
          <Button type="button" variant="ghost" onClick={onClose} disabled={isSaving}>
            {t("common.cancel")}
          </Button>
          <Button type="submit" loading={isSaving}>
            {t("common.save")}
          </Button>
        </DialogFooter>
      </form>
    </Form>
  );
}

/**
 * Presentation UI component rendering the commission rate config.
 * Arranges layout boundaries and accessibility targets (WCAG, tab index) using the core design library (@core/ui/*). Coordinates text fields, submit indicators, and validation warning messages.
 */
export function CommissionRateConfig({
  account,
  isOpen,
  onClose,
  onSave,
  isSaving,
  t,
}: CommissionRateConfigProps) {
  if (!account) return null;

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="sm:max-w-[480px]">
        <DialogHeader>
          <DialogTitle>{t("entitlements.stripeConnect.commissionRateOverride")}</DialogTitle>
          <DialogDescription>
            {t("entitlements.stripeConnect.commissionRateDesc")}
          </DialogDescription>
        </DialogHeader>

        <CommissionRateForm
          key={account.tenantId}
          account={account}
          onClose={onClose}
          onSave={onSave}
          isSaving={isSaving}
          t={t}
        />
      </DialogContent>
    </Dialog>
  );
}

