/**
 * @file useSubscriptionsViewModel.ts
 * @description ViewModel managing tenant edition subscriptions lifecycle (assign, change, suspend, resume, cancel).
 * Exposes billing portals, payment flows, and promo codes. Uses runtime DI registry decoupling.
 */

"use client";

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { entitlementsContainer } from "@modules/entitlements/di";
import { getTenantRepository } from "@core/services/module-bridges";
import { useEnhancedToast } from "@core/hooks/use-enhanced-toast";
import { useI18n } from "@core/providers/i18n-provider";
import { useState, useCallback, useEffect, useMemo } from "react";
import { parseLocalizedNumber } from "@core/utils/number-parser";
import type { EditionPromotionData } from "@modules/entitlements/core";

/**
 * React hook/ViewModel orchestrating state and data flows for subscriptions view model.
 * Manages TanStack Query hooks, query cache keys, and repository fetch requests.
 */
export function useSubscriptionsViewModel(tenantId: string) {
  const { subscriptionRepository, editionRepository, billingRepository } = entitlementsContainer;
  const queryClient = useQueryClient();
  const { success, error: showError } = useEnhancedToast();
  const { t } = useI18n();

  // ─── Dialog state ───────────────────────────────────
  const [showAssignDialog, setShowAssignDialog] = useState(false);
  const [showChangeDialog, setShowChangeDialog] = useState(false);
  const [showSuspendDialog, setShowSuspendDialog] = useState(false);
  const [showCancelDialog, setShowCancelDialog] = useState(false);
  const [showConvertDialog, setShowConvertDialog] = useState(false);
  const [showCurrencyDialog, setShowCurrencyDialog] = useState(false);
  const [newCurrency, setNewCurrency] = useState("USD");
  // ── Billing dialog state ──
  const [showCheckoutDialog, setShowCheckoutDialog] = useState(false);
  const [showCancelGatewayDialog, setShowCancelGatewayDialog] = useState(false);
  const [showGatewayDialog, setShowGatewayDialog] = useState(false);
  const [gatewayAction, setGatewayAction] = useState<"generate" | "send" | null>(null);
  const [checkoutUrl, setCheckoutUrl] = useState("");
  const [checkoutQrCode, setCheckoutQrCode] = useState<string | null>(null);
  const [checkoutEmailSent, setCheckoutEmailSent] = useState(false);
  const [cancelImmediately, setCancelImmediately] = useState(false);

  // ─── Form state ─────────────────────────────────────
  const [selectedEditionId, setSelectedEditionId] = useState("");
  const [subscriptionType, setSubscriptionType] = useState("Monthly");
  const [endDate, setEndDate] = useState("");
  const [expiryBehavior, setExpiryBehavior] = useState("Fallback");
  const [suspendReason, setSuspendReason] = useState("");
  const [cancelReason, setCancelReason] = useState("");
  const [useFallback, setUseFallback] = useState(false);
  const [convertType, setConvertType] = useState("Monthly");
  const [promoCode, setPromoCode] = useState("");
  const [currency, setCurrency] = useState("USD");
  const [selectedPromotionId, setSelectedPromotionId] = useState<string | null>(null);
  const [refundType, setRefundType] = useState("None");
  const [customRefundAmount, setCustomRefundAmount] = useState<string>("");
  const [skipPayment, setSkipPayment] = useState(false);

  // ─── Query keys ─────────────────────────────────────
  const queryKey = ["entitlements", "subscriptions", tenantId];

  // ─── Fetch subscriptions ────────────────────────────
  const subscriptionsQuery = useQuery({
    queryKey,
    queryFn: () => subscriptionRepository.getByTenant(tenantId),
    enabled: !!tenantId,
  });

  // ─── Fetch tenant detail (for admin email) ─────────
  // Resolved through the core bridge. This used to read the runtime component registry, whose
  // `tenantRepository` key is registered by the `@modules/identity` barrel — a barrel no route
  // imports — so the guard below was permanently false and the admin email never loaded.
  const tenantQuery = useQuery({
    queryKey: ["tenant", tenantId],
    queryFn: async () => {
      const tenantRepository = await getTenantRepository();
      return tenantRepository.getById(tenantId);
    },
    enabled: !!tenantId,
  });
  const tenantAdminEmail = tenantQuery.data?.adminEmail;

  const items = subscriptionsQuery.data ?? [];
  const activeSubscription = items.find((s) => s.status === "Active" || s.status === "Trialing");
  const suspendedSubscription = items.find((s) => s.status === "Suspended");
  const pendingPaymentSubscription = items.find((s) => s.status === "PendingPayment");
  const isTrialing = activeSubscription?.status === "Trialing";
  const isDowngraded = activeSubscription?.isDowngraded ?? false;

  // GAP-I: Detect if this is a free edition (totalAmount = 0 or no amount)
  const isFreeEdition = activeSubscription ? (activeSubscription.totalAmount ?? 0) === 0 : false;

  // ─── Invalidation helper ────────────────────────────
  const invalidate = useCallback(() => {
    queryClient.invalidateQueries({ queryKey });
    // Cross-invalidate: refresh tenant detail page and subscription card
    queryClient.invalidateQueries({ queryKey: ["tenant-subscriptions", tenantId] });
    queryClient.invalidateQueries({ queryKey: ["tenant", tenantId] });
    queryClient.invalidateQueries({ queryKey: ["tenant-entitlements", tenantId] });
    queryClient.invalidateQueries({ queryKey: ["tenants"] });
  }, [queryClient, queryKey, tenantId]);

  // ─── Reset form ─────────────────────────────────────
  const resetForm = useCallback(() => {
    setSelectedEditionId("");
    setSubscriptionType("Monthly");
    setEndDate("");
    setExpiryBehavior("Fallback");
    setSuspendReason("");
    setCancelReason("");
    setUseFallback(false);
    setConvertType("Monthly");
    setPromoCode("");
    setCurrency("USD");
    setSelectedPromotionId(null);
    setRefundType("None");
    setCustomRefundAmount("");
    setSkipPayment(false);
  }, []);

  // ─── Auto-calculate endDate on type change ────────
  useEffect(() => {
    queueMicrotask(() => {
      const now = new Date();
      switch (subscriptionType) {
        case "Monthly":
          now.setDate(now.getDate() + 30);
          setEndDate(now.toISOString().split("T")[0]);
          break;
        case "Yearly":
          now.setDate(now.getDate() + 365);
          setEndDate(now.toISOString().split("T")[0]);
          break;
        case "Trial":
          now.setDate(now.getDate() + 14);
          setEndDate(now.toISOString().split("T")[0]);
          break;
        case "Lifetime":
        default:
          setEndDate("");
          break;
      }
    });
  }, [subscriptionType]);

  // ─── Mutation helper ─────────────────────────────────
  const useActionMutation = <T>(
    mutationFn: (params: T) => Promise<unknown>,
    successKey: string,
    descKey: string,
    onDone?: () => void
  ) =>
    useMutation({
      mutationFn,
      onSuccess: () => {
        invalidate();
        success({ title: t(successKey), description: t(descKey) });
        onDone?.();
        resetForm();
      },
      onError: (err: Error) => showError({ title: t("common.error"), description: err.message }),
    });

  // ── Downgrade impact: fetch when Change dialog is open with a target edition ──
  const downgradeImpactQuery = useQuery({
    queryKey: ["entitlements", "subscriptions", tenantId, "downgrade-impact", selectedEditionId],
    queryFn: () => subscriptionRepository.getDowngradeImpact(tenantId, selectedEditionId),
    enabled: showChangeDialog && !!selectedEditionId && !!tenantId,
    staleTime: 30_000,
  });

  // ── Fetch promotions for selected edition ───────────────────
  const promotionsQuery = useQuery({
    queryKey: ["entitlements", "editions", selectedEditionId, "promotions"],
    queryFn: () => editionRepository.getPromotions(selectedEditionId),
    enabled: !!selectedEditionId,
  });

  const allPromotions: EditionPromotionData[] = promotionsQuery.data ?? [];

  // Filter promotions by billing cycle and active status
  const availablePromotions = useMemo((): EditionPromotionData[] => {
    return allPromotions.filter((p) => {
      if (!p.isActive) return false;
      // Check expiry
      if (p.validUntil && new Date(p.validUntil) < new Date()) return false;
      // Check not started
      if (p.validFrom && new Date(p.validFrom) > new Date()) return false;
      // Check redemption limit
      if (p.maxRedemptions != null && p.currentRedemptions >= p.maxRedemptions) return false;
      // Filter by applicable billing cycle
      if (p.applicableCycle) {
        if (p.applicableCycle !== subscriptionType) return false;
      }
      return true;
    });
  }, [allPromotions, subscriptionType]);

  // Get the selected promotion object
  const selectedPromotion = useMemo(() => {
    if (!selectedPromotionId) return null;
    return availablePromotions.find((p) => p.id === selectedPromotionId) ?? null;
  }, [selectedPromotionId, availablePromotions]);

  // Does the selected promotion require a code?
  const requiresPromoCode = selectedPromotion?.requiresCode ?? false;

  // Reset promotion when edition or subscription type changes
  useEffect(() => {
    queueMicrotask(() => {
      setSelectedPromotionId(null);
      setPromoCode("");
    });
  }, [selectedEditionId, subscriptionType]);

  // ─── Mutations ──────────────────────────────────────

  const assignMutation = useActionMutation(
    (params: {
      editionId: string;
      type: string;
      endDate?: string;
      expiryBehavior?: string;
      promoCode?: string;
      currency?: string;
      promotionId?: string;
      skipPayment?: boolean;
    }) => subscriptionRepository.assign(tenantId, params),
    "entSubscriptions.assigned",
    "entSubscriptions.assignedDesc",
    () => setShowAssignDialog(false)
  );

  const changeMutation = useActionMutation(
    (params: {
      editionId: string;
      type: string;
      promoCode?: string;
      currency?: string;
      promotionId?: string;
    }) => subscriptionRepository.change(tenantId, params),
    "entSubscriptions.changed",
    "entSubscriptions.changedDesc",
    () => setShowChangeDialog(false)
  );

  const renewMutation = useActionMutation(
    (type: string) => subscriptionRepository.renew(tenantId, type),
    "entSubscriptions.renewed",
    "entSubscriptions.renewedDesc"
  );

  const convertMutation = useActionMutation(
    (type: string) => subscriptionRepository.convertTrial(tenantId, type),
    "entSubscriptions.converted",
    "entSubscriptions.convertedDesc",
    () => setShowConvertDialog(false)
  );

  const suspendMutation = useActionMutation(
    (params: {
      reason: string;
      useFallback: boolean;
      refundType: string;
      customRefundAmount?: number;
    }) =>
      subscriptionRepository.suspend(
        tenantId,
        params.reason,
        params.useFallback,
        params.refundType,
        params.customRefundAmount
      ),
    "entSubscriptions.suspended",
    "entSubscriptions.suspendedDesc",
    () => setShowSuspendDialog(false)
  );

  const resumeMutation = useActionMutation(
    (type?: string) => subscriptionRepository.resume(tenantId, type),
    "entSubscriptions.resumed",
    "entSubscriptions.resumedDesc"
  );

  const cancelMutation = useActionMutation(
    (params: {
      reason?: string;
      useFallback: boolean;
      refundType: string;
      customRefundAmount?: number;
    }) =>
      subscriptionRepository.cancel(
        tenantId,
        params.reason,
        params.useFallback,
        params.refundType,
        params.customRefundAmount
      ),
    "entSubscriptions.canceled",
    "entSubscriptions.canceledDesc",
    () => setShowCancelDialog(false)
  );

  const resyncMutation = useActionMutation(
    () => subscriptionRepository.resync(tenantId),
    "entSubscriptions.resynced",
    "entSubscriptions.resyncedDesc"
  );

  const revokeMutation = useActionMutation(
    (id: string) => subscriptionRepository.revoke(id),
    "entSubscriptions.revoked",
    "entSubscriptions.revokedDesc"
  );

  const changeCurrencyMutation = useActionMutation(
    (cur: string) => subscriptionRepository.changeCurrency(tenantId, cur),
    "entSubscriptions.currencyChanged",
    "entSubscriptions.currencyChangedDesc",
    () => setShowCurrencyDialog(false)
  );

  // ─── Submit helpers ─────────────────────────────────
  const submitAssign = useCallback(() => {
    assignMutation.mutate({
      editionId: selectedEditionId,
      type: subscriptionType,
      endDate: endDate || undefined,
      expiryBehavior,
      promoCode: requiresPromoCode ? promoCode || undefined : undefined,
      currency: currency || undefined,
      promotionId: selectedPromotionId || undefined,
      skipPayment: skipPayment || undefined,
    });
  }, [
    assignMutation,
    selectedEditionId,
    subscriptionType,
    endDate,
    expiryBehavior,
    promoCode,
    currency,
    selectedPromotionId,
    requiresPromoCode,
    skipPayment,
  ]);

  const submitChange = useCallback(() => {
    changeMutation.mutate({
      editionId: selectedEditionId,
      type: subscriptionType,
      promoCode: requiresPromoCode ? promoCode || undefined : undefined,
      currency: currency || undefined,
      promotionId: selectedPromotionId || undefined,
    });
  }, [
    changeMutation,
    selectedEditionId,
    subscriptionType,
    promoCode,
    currency,
    selectedPromotionId,
    requiresPromoCode,
  ]);

  const submitSuspend = useCallback(() => {
    const parsed = customRefundAmount ? parseLocalizedNumber(customRefundAmount) : undefined;
    suspendMutation.mutate({
      reason: suspendReason,
      useFallback,
      refundType,
      customRefundAmount: parsed && parsed > 0 ? parsed : undefined,
    });
  }, [suspendMutation, suspendReason, useFallback, refundType, customRefundAmount]);

  const submitCancel = useCallback(() => {
    const parsed = customRefundAmount ? parseLocalizedNumber(customRefundAmount) : undefined;
    cancelMutation.mutate({
      reason: cancelReason,
      useFallback,
      refundType,
      customRefundAmount: parsed && parsed > 0 ? parsed : undefined,
    });
  }, [cancelMutation, cancelReason, useFallback, refundType, customRefundAmount]);

  const submitConvert = useCallback(() => {
    convertMutation.mutate(convertType);
  }, [convertMutation, convertType]);

  // ─── Billing mutations ──────────────────────────────
  const checkoutMutation = useMutation({
    mutationFn: async (options?: { sendToEmail?: string; gatewayOverride?: string }) => {
      // Allow checkout for both active and pending-payment subscriptions
      const targetSubscription = activeSubscription ?? pendingPaymentSubscription;
      if (!targetSubscription) throw new Error("No active subscription");
      const result = await billingRepository.createCheckoutSession(tenantId, {
        editionId: targetSubscription.editionId,
        subscriptionType: targetSubscription.type,
        currency: targetSubscription.currency,
        promoCode: targetSubscription.appliedPromoCode,
        successUrl: `${window.location.origin}/entitlements/subscriptions?checkout=success`,
        cancelUrl: `${window.location.origin}/entitlements/subscriptions?checkout=canceled`,
        generateQrCode: true,
        sendToEmail: options?.sendToEmail,
        gatewayOverride: options?.gatewayOverride,
      });
      return result;
    },
    onSuccess: (result) => {
      setCheckoutUrl(result.url);
      setCheckoutQrCode(result.qrCodeBase64 ?? null);
      setCheckoutEmailSent(result.emailSent ?? false);
      setShowCheckoutDialog(true);
      invalidate();
      success({ title: t("billing.checkoutSuccess"), description: "" });
    },
    onError: (err: Error) => showError({ title: t("common.error"), description: err.message }),
  });

  const portalMutation = useMutation({
    mutationFn: async () => {
      const result = await billingRepository.createBillingPortal(tenantId, window.location.href);
      return result;
    },
    onSuccess: (result) => {
      window.open(result.url, "_blank");
      success({
        title: t("billing.portalSuccess"),
        description: t("billing.dialogs.portalOpened"),
      });
    },
    onError: (err: Error) => showError({ title: t("common.error"), description: err.message }),
  });

  const cancelGatewayMutation = useMutation({
    mutationFn: async (immediately: boolean) => {
      await billingRepository.cancelGatewaySubscription(tenantId, immediately);
    },
    onSuccess: () => {
      invalidate();
      setShowCancelGatewayDialog(false);
      setCancelImmediately(false);
      success({ title: t("billing.cancelSuccess"), description: "" });
    },
    onError: (err: Error) => showError({ title: t("common.error"), description: err.message }),
  });

  const submitCancelGateway = useCallback(() => {
    cancelGatewayMutation.mutate(cancelImmediately);
  }, [cancelGatewayMutation, cancelImmediately]);

  // ─── Public interface ───────────────────────────────
  return {
    // Data
    items,
    isLoading: subscriptionsQuery.isLoading,
    error: subscriptionsQuery.error,
    hasActiveSubscription: !!activeSubscription,
    hasSuspendedSubscription: !!suspendedSubscription,
    hasPendingPaymentSubscription: !!pendingPaymentSubscription,
    isFreeEdition,
    isTrialing,
    isDowngraded,
    activeSubscription,
    pendingPaymentSubscription,

    // Assign dialog
    showAssignDialog,
    setShowAssignDialog,
    submitAssign,
    isAssigning: assignMutation.isPending,

    // Change dialog
    showChangeDialog,
    setShowChangeDialog,
    submitChange,
    isChanging: changeMutation.isPending,
    downgradeImpact: downgradeImpactQuery.data ?? null,
    isLoadingDowngradeImpact: downgradeImpactQuery.isLoading,

    // Suspend dialog
    showSuspendDialog,
    setShowSuspendDialog: (open: boolean) => {
      setShowSuspendDialog(open);
      if (!open) resetForm(); // Reset shared state on dialog close
    },
    submitSuspend,
    isSuspending: suspendMutation.isPending,
    suspendReason,
    setSuspendReason,

    // Cancel dialog
    showCancelDialog,
    setShowCancelDialog: (open: boolean) => {
      setShowCancelDialog(open);
      if (!open) resetForm(); // Reset shared state on dialog close
    },
    submitCancel,
    isCanceling: cancelMutation.isPending,
    cancelReason,
    setCancelReason,

    // Convert trial dialog
    showConvertDialog,
    setShowConvertDialog,
    submitConvert,
    isConverting: convertMutation.isPending,
    convertType,
    setConvertType,

    // Resume (no dialog — direct action)
    resumeSubscription: () => resumeMutation.mutate(undefined),
    isResuming: resumeMutation.isPending,

    // Renew (direct action)
    renewSubscription: (type: string) => renewMutation.mutate(type),
    isRenewing: renewMutation.isPending,

    // Resync (direct action)
    resyncPermissions: () => resyncMutation.mutate(undefined as never),
    isResyncing: resyncMutation.isPending,

    // Revoke
    revokeSubscription: revokeMutation.mutate,
    isRevoking: revokeMutation.isPending,

    // Change Currency
    showCurrencyDialog,
    setShowCurrencyDialog,
    newCurrency,
    setNewCurrency,
    submitChangeCurrency: () => changeCurrencyMutation.mutate(newCurrency),
    isChangingCurrency: changeCurrencyMutation.isPending,

    // Shared form state
    selectedEditionId,
    setSelectedEditionId,
    subscriptionType,
    setSubscriptionType,
    endDate,
    setEndDate,
    expiryBehavior,
    setExpiryBehavior,
    useFallback,
    setUseFallback,
    promoCode,
    setPromoCode,
    currency,
    setCurrency,
    skipPayment,
    setSkipPayment,

    // Smart promotion picker
    availablePromotions,
    selectedPromotionId,
    setSelectedPromotionId,
    selectedPromotion,
    requiresPromoCode,
    isLoadingPromotions: promotionsQuery.isLoading,

    // Refund options (for suspend/cancel)
    refundType,
    setRefundType,
    customRefundAmount,
    setCustomRefundAmount,

    // Billing actions — dual mode: generate only vs generate & send
    openGatewaySelection: (action: "generate" | "send") => {
      setGatewayAction(action);
      setShowGatewayDialog(true);
    },
    handleGatewaySelected: (gateway: string) => {
      setShowGatewayDialog(false);
      if (gatewayAction === "generate") {
        checkoutMutation.mutate({ gatewayOverride: gateway });
      } else if (gatewayAction === "send") {
        const targetEmail = tenantAdminEmail;
        if (!targetEmail) {
          showError({
            title: t("common.error"),
            description: t("billing.errors.noAdminEmail"),
          });
          return;
        }
        checkoutMutation.mutate({ sendToEmail: targetEmail, gatewayOverride: gateway });
      }
    },
    generatePaymentLink: () => checkoutMutation.mutate(undefined), // Fallback if no gateway selection
    sendPaymentLink: (email?: string) => {
      // Fallback if no gateway selection
      const targetEmail = email || tenantAdminEmail;
      if (!targetEmail) {
        showError({
          title: t("common.error"),
          description: t("billing.errors.noAdminEmail"),
        });
        return;
      }
      checkoutMutation.mutate({ sendToEmail: targetEmail });
    },
    tenantAdminEmail,
    isSendingPaymentLink: checkoutMutation.isPending,
    openBillingPortal: () => portalMutation.mutate(),
    isOpeningPortal: portalMutation.isPending,
    submitCancelGateway,
    isCancelingGateway: cancelGatewayMutation.isPending,

    // Billing dialog state
    showCheckoutDialog,
    setShowCheckoutDialog,
    showCancelGatewayDialog,
    setShowCancelGatewayDialog,
    showGatewayDialog,
    setShowGatewayDialog,
    checkoutUrl,
    checkoutQrCode,
    checkoutEmailSent,
    cancelImmediately,
    setCancelImmediately,
  };
}

/**
 * FeaturesTab — Interactive Feature Assignment Editor for TenantPlan Detail
 *
 * NOW USES LIFTED STATE from the viewmodel (passed via props).
 * This ensures state persists when the user switches tabs.
 *
 * Grouping comes 100% from the backend via useTenantPlanDetailViewModel:
 * - groupedByCategory: assigned features grouped by category (backend-structured)
 * - availableGrouped: unassigned active features grouped by category (backend-structured)
 *
 * ZERO client-side useMemo+reduce for grouping — backend does all of it.
 */
"use client";

import { useState, useCallback } from "react";
import { Badge } from "@core/ui/badge";
import { Button } from "@core/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@core/ui/card";
import { EmptyState } from "@core/ui/empty-state";
import {
  Zap,
  ChevronDown,
  ChevronRight,
  ChevronsUpDown,
  Plus,
  Save,
  CheckCircle2,
} from "lucide-react";
import { cn } from "@core/common/utils";
import type {
  TenantPlan,
  TenantFeatureDefinition,
  TenantFeatureDefinitionCategoryGroup,
} from "../../domain/entities/TenantPlan";
import { FeatureCatalogPicker } from "./features-tab/FeatureCatalogPicker";
import { FeatureRow } from "./features-tab/FeatureRow";
import Link from "next/link";

// ── Types from the viewmodel (passed as props) ──
interface AssignedFeatureItem {
  definition: TenantFeatureDefinition;
  value: string;
  overrideLabel?: string;
  isModified: boolean;
  isNew: boolean;
}

interface AssignedFeatureCategoryGroup {
  category: string;
  items: AssignedFeatureItem[];
}

interface FeaturesTabProps {
  plan: TenantPlan;
  /** Total count of active features (for badge: assigned/total) */
  totalActiveFeatureCount: number;
  /** Assigned features pre-grouped by category — backend-structured, zero client-side groupBy */
  groupedByCategory: AssignedFeatureCategoryGroup[];
  /** Unassigned active features pre-grouped by category — for FeatureCatalogPicker */
  availableGrouped: TenantFeatureDefinitionCategoryGroup[];
  /** Lifted state from viewmodel */
  localFeatures: Map<string, { value: string; overrideLabel?: string }>;
  setFeatureValue: (defId: string, value: string) => void;
  addFeature: (def: TenantFeatureDefinition) => void;
  removeFeature: (defId: string) => void;
  hasChanges: boolean;
  onSave: () => void;
  isSaving: boolean;
  t: (key: string) => string;
  language: string;
}

/**
 * Presentation UI component rendering the features tab.
 * Arranges layout boundaries and accessibility targets (WCAG, tab index) using the core design library (@core/ui/*).
 */
export function FeaturesTab({
  plan,
  totalActiveFeatureCount,
  groupedByCategory,
  availableGrouped,
  setFeatureValue,
  addFeature,
  removeFeature,
  hasChanges,
  onSave,
  isSaving,
  t,
  language,
}: FeaturesTabProps) {
  const [collapsedCategories, setCollapsedCategories] = useState<Record<string, boolean>>({});
  const [showPicker, setShowPicker] = useState(false);

  // Total assigned count across all groups
  const assignedCount = groupedByCategory.reduce((sum, g) => sum + g.items.length, 0);

  // ── Handlers ──
  const handleAddFeature = useCallback(
    (def: TenantFeatureDefinition) => {
      addFeature(def);
      setShowPicker(false);
    },
    [addFeature]
  );

  const toggleCategory = useCallback((cat: string) => {
    setCollapsedCategories((prev) => ({ ...prev, [cat]: !prev[cat] }));
  }, []);

  const toggleAll = useCallback(() => {
    const allCollapsed = groupedByCategory.every((g) => collapsedCategories[g.category]);
    const newState: Record<string, boolean> = {};
    for (const g of groupedByCategory) {
      newState[g.category] = !allCollapsed;
    }
    setCollapsedCategories(newState);
  }, [collapsedCategories, groupedByCategory]);

  const allCollapsed =
    groupedByCategory.length > 0 && groupedByCategory.every((g) => collapsedCategories[g.category]);

  const hasAvailable = availableGrouped.some((g) => g.definitions.length > 0);

  // ── Empty Catalog State ──
  if (totalActiveFeatureCount === 0) {
    return (
      <Card>
        <CardContent>
          <EmptyState
            bare
            icon={Zap}
            title={t("entitlements.featureDefinitions.emptyCatalog")}
            action={
              <Button variant="outline" size="sm" asChild>
                <Link href="/entitlements/tenant-feature-definitions">
                  <Plus className="me-1 h-4 w-4" aria-hidden="true" />
                  {t("entitlements.featureDefinitions.goToCatalog")}
                </Link>
              </Button>
            }
          />
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-4">
      {/* ─────── TOOLBAR ─────── */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Zap className="h-5 w-5 text-nx-accent" aria-hidden="true" />
          <h2 className="text-lg font-semibold">{t("entitlements.tenantPlans.tabFeatures")}</h2>
          <Badge variant="secondary" className="text-xs">
            {assignedCount}/{totalActiveFeatureCount}
          </Badge>
          {hasChanges && (
            <Badge variant="warning" className="text-xs">
              {t("common.unsavedChanges")}
            </Badge>
          )}
        </div>

        <div className="flex items-center gap-2">
          {groupedByCategory.length > 1 && (
            <Button variant="ghost" size="sm" onClick={toggleAll}>
              <ChevronsUpDown className="me-1 h-4 w-4" aria-hidden="true" />
              {allCollapsed ? t("common.expandAll") : t("common.collapseAll")}
            </Button>
          )}
          <Button variant="ghost" size="sm" asChild>
            <Link href="/entitlements/tenant-feature-definitions">
              {t("entitlements.featureDefinitions.manageCatalog")}
            </Link>
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={() => setShowPicker(true)}
            disabled={!hasAvailable}
          >
            <Plus className="me-1 h-4 w-4" aria-hidden="true" />
            {t("entitlements.featureDefinitions.addFeature")}
          </Button>
          <Button size="sm" onClick={onSave} disabled={!hasChanges} loading={isSaving}>
            {!isSaving && <Save className="me-1 h-4 w-4" aria-hidden="true" />}
            {t("common.save")}
          </Button>
        </div>
      </div>

      {/* ─────── FEATURE CATALOG PICKER DIALOG ─────── */}
      {showPicker && (
        <FeatureCatalogPicker
          availableGrouped={availableGrouped}
          onSelect={handleAddFeature}
          onClose={() => setShowPicker(false)}
          t={t}
          language={language}
        />
      )}

      {/* ─────── FEATURE GROUPS ─────── */}
      {groupedByCategory.length === 0 ? (
        <Card>
          <CardContent>
            <EmptyState
              bare
              icon={CheckCircle2}
              title={t("entitlements.tenantPlans.noFeatures")}
              description={t("entitlements.tenantPlans.noFeaturesHint")}
            />
          </CardContent>
        </Card>
      ) : (
        groupedByCategory.map(({ category, items }) => {
          const isCollapsed = collapsedCategories[category] ?? false;

          return (
            <Card key={category} className="overflow-hidden">
              <CardHeader className="py-3">
                <Button
                  type="button"
                  variant="ghost"
                  onClick={() => toggleCategory(category)}
                  aria-expanded={!isCollapsed}
                  className={cn(
                    "flex h-auto w-full items-center justify-between gap-2 p-0 rounded-nx-sm text-start hover:bg-transparent",
                    "transition-colors duration-nx-micro ease-nx-enter motion-reduce:transition-none",
                    "focus-visible:shadow-nx-focus focus-visible:outline-none"
                  )}
                >
                  <div className="flex items-center gap-2">
                    {isCollapsed ? (
                      <ChevronRight
                        className="h-4 w-4 shrink-0 text-nx-ink-3 rtl:rotate-180"
                        aria-hidden="true"
                      />
                    ) : (
                      <ChevronDown className="h-4 w-4 shrink-0 text-nx-ink-3" aria-hidden="true" />
                    )}
                    <CardTitle className="text-base">{category}</CardTitle>
                  </div>
                  <Badge variant="outline">{items.length}</Badge>
                </Button>
              </CardHeader>

              {!isCollapsed && (
                <CardContent className="pt-0">
                  <div className="divide-y divide-nx-line">
                    {items.map((item) => (
                      <FeatureRow
                        key={item.definition.id}
                        definition={item.definition}
                        value={item.value}
                        isModified={item.isModified}
                        isNew={item.isNew}
                        onValueChange={(v) => setFeatureValue(item.definition.id, v)}
                        onRemove={() => removeFeature(item.definition.id)}
                        language={language}
                        t={t}
                      />
                    ))}
                  </div>
                </CardContent>
              )}
            </Card>
          );
        })
      )}
    </div>
  );
}

