          placeholder: t("customField.placeholders.optionEn"), searchPlaceholder: t("customField.placeholders.optionAr"),
          addLabel: t("customField.actions.addOption"), removeLabel: t("customField.actions.removeOption"),
          emptyHint: t("customField.placeholders.optionsEmpty"),
          isVisible: (form: Record<string, unknown>) =>
            VALUE_TYPE_CATALOG[form.valueType as CustomFieldValueTypeName]?.hasOptions ?? false,
        },
        ...buildEditLayoutFields({ fieldGroupField, classificationFields, t }),
      ],
      createInitialValues: {
        entityTypeKey: "", key: "", labelEn: "", labelAr: "", placeholderEn: "", placeholderAr: "", valueType: "Text", sensitivity: "None",
        isExportable: true, validatorKind: "", validatorParam: "", fieldGroupId: "", [REFERENCE_TARGET_FIELD_NAME]: UNPINNED_REFERENCE_TARGET,
        optionsSource: "custom", optionSetVersionId: "", options: "", isRequired: false, sortOrder: 0, scope: getInitialCustomFieldScope(isPlatformContext),
      },
      editInitialValues: buildCustomFieldEditInitialValues,
      getItemDisplayName: (item: CustomField) => item.labelEn || item.key,
      deleteService: (id: string) => vm.deleteItem(id),
      getActions: (_vmInstance, tFn) =>
        buildCustomFieldActions(tFn, {
          openDetail: subFeatures.openDetail, openEditModal: (item) => vm.openEditModal(item),
          canUpdate, canDelete, canViewHistory, canViewUsage, canViewOptionSets, isPlatformContext,
          openBinding: subFeatures.optionSetBinding.openBinding, openUsage: subFeatures.insight.openUsage,
          visibilityRulesCanView: subFeatures.visibilityRules.canView, openRules: subFeatures.visibilityRules.openRules,
          convertValueTypeCanUpdate: subFeatures.convertValueType.canUpdate, openConvert: subFeatures.convertValueType.openConvert,
          fieldVersionsCanView: subFeatures.fieldVersions.canView, openVersions: subFeatures.fieldVersions.openVersions,
          openHistory: subFeatures.insight.openHistory, requestDelete: subFeatures.insight.requestDelete,
          refreshItems: () => vm.refreshItems(),
        }),
    }),
    [
      t, language, vm, columns, entityTypeOptions, noFrontendScreenDescription, valueTypeOptions, validatorKindOptions,
      validatorParamFields, referenceTargetFields, fieldGroupField, scopeField, optionSetOptions, isEntityTypesError,
      canViewFieldGroups, canViewOptionSets, canManageKeys, canViewHistory, canViewUsage, canUpdate, canDelete,
      subFeatures, handleEntityTypeChange, refetchEntityTypes, classificationFields,
      isPlatformContext,
    ]
  );

  const items = vm.items as CustomField[] | undefined;
  const insightFieldLabel = useCallback((fieldId: string | null): string => {
    if (!fieldId) return "";
    const row = items?.find((item) => item.id === fieldId);
    return row ? row.labelEn || row.key : "";
  }, [items]);

  return (
    <>
      <GenericCrudView viewModel={vm} config={config} />
      <CustomFieldDialogsContainer
        detailFieldId={subFeatures.detailFieldId} closeDetail={subFeatures.closeDetail} insightFieldLabel={insightFieldLabel}
        canUpdate={canUpdate} isPlatformContext={isPlatformContext} vm={vm} insight={subFeatures.insight}
        optionSetBinding={subFeatures.optionSetBinding} visibilityRules={subFeatures.visibilityRules}
        convertValueType={subFeatures.convertValueType} fieldVersions={subFeatures.fieldVersions}
      />
    </>
  );
});

/**
 * Definition export dialog — Wave 6 row 6.4
 *
 * One scope choice and one action: pick an entity type (or all of them), press Export, get an `.xlsx`
 * of the field definitions on disk.
 *
 * CONTAINER CHOICE: a `Dialog`, matching `SchemaExportDialog`, `FieldImpactDialog` and
 * `FieldHistoryDialog` — everything the definitions screen opens over itself. It is NOT the inline-panel
 * shape `FieldGroupEditor` uses: that panel exists because it is a four-input form on a route page of
 * its own, whereas this is a one-choice action launched from a header on a screen the admin wants to
 * stay on. Nothing here nests a modal inside a modal, which is the constraint row 5.6 spent a commit
 * establishing for this module.
 *
 * THE REFUSAL GETS ITS OWN ALERT, AND IT IS NOT DESTRUCTIVE-COLOURED
 * -----------------------------------------------------------------
 * Past the server's row cap the export is REFUSED rather than truncated. That is a working system
 * declining a request, not a fault, so it renders as a `warning` with the cap and the remedy named —
 * and the generic error line is suppressed while it shows, because an admin reading both would
 * reasonably conclude two things went wrong.
 *
 * WHY THE 'INCLUDED IN EXPORTS' NOTE IS IN THE DIALOG AT ALL
 * ---------------------------------------------------------
 * Because the flag's name invites exactly the wrong inference. It means "values of this field are
 * included in export" — a statement about VALUES — and the handler reports it as a column while
 * deliberately never filtering on it. An admin who assumed it filtered would read a complete workbook
 * as a partial one, so the dialog says which of the two it is before the file is downloaded.
 */
"use client";

import React from "react";
import { AlertCircle, Download, FileSpreadsheet, Info } from "lucide-react";
import { Button } from "@core/ui/button";
import { Label } from "@core/ui/label";
import { Alert, AlertDescription, AlertTitle } from "@core/ui/alert";
import { ErrorMessage } from "@core/ui/error-message";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@core/ui/dialog";
import { GenericSelect } from "@core/crud/components/generic-select";
import { useI18n } from "@core/providers/i18n-provider";
import {
  ALL_ENTITY_TYPES_VALUE,
  useDefinitionExportViewModel,
} from "../viewmodels/useDefinitionExportViewModel";

export interface DefinitionExportDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function DefinitionExportDialog({ open, onOpenChange }: DefinitionExportDialogProps) {
  const { t, language } = useI18n();
  const vm = useDefinitionExportViewModel();

  /**
   * The scope options, led by the "all entity types" sentinel.
   *
   * The sentinel is FIRST and is the default: an admin auditing their field configuration usually
   * wants the whole list, and narrowing is the second thought — which is also the remedy the row-cap
   * refusal points at.
   */
  const entityTypes = vm.entityTypes ?? [];
  const entityTypeOptions = React.useMemo(
    () => [
      { value: ALL_ENTITY_TYPES_VALUE, label: t("definitionExport.allEntityTypes") },
      ...entityTypes.map((item) => ({
        value: item.key,
        label: `${language === "ar" ? item.displayNameAr : item.displayNameEn} (${item.key})`,
      })),
    ],
    [entityTypes, language, t]
  );

  const handleOpenChange = React.useCallback(
    (next: boolean) => {
      // Reset on CLOSE, not on open: a dialog that clears itself while the admin is reading which
      // file just landed would erase the only report of it.
      if (!next) vm.reset();
      onOpenChange(next);
    },
    [onOpenChange, vm]
  );

  const exported = vm.lastExport;

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent className="sm:max-w-lg">
        <DialogHeader>
          <DialogTitle>{t("definitionExport.title")}</DialogTitle>
          <DialogDescription>{t("definitionExport.description")}</DialogDescription>
        </DialogHeader>

        <div className="flex flex-col gap-4">
          <div className="flex flex-col gap-1.5">
            <Label htmlFor="definition-export-entity-type">
              {t("definitionExport.entityType")}
            </Label>
            <GenericSelect
              id="definition-export-entity-type"
              // GenericSelect's trigger is a role="combobox" DIV, so the <Label htmlFor> above
              // computes no accessible name for it. aria-label is opt-in on this component and must
              // be passed explicitly -- every CustomFields site already does.
              aria-label={t("definitionExport.entityType")}
              type="single"
              options={entityTypeOptions}
              value={vm.entityTypeKey}
              onValueChange={(value: string | string[]) =>
                vm.setEntityTypeKey(typeof value === "string" ? value : (value[0] ?? ""))
              }
              placeholder={t("definitionExport.entityTypePlaceholder")}
              loading={vm.isEntityTypesLoading}
              disabled={vm.isExporting}
            />
            <p className="text-sm text-muted-foreground">
              {t("definitionExport.entityTypeHint")}
            </p>

            {/* A failed entity-type fetch is NOT fatal here, unlike on the field-group screen where a
                scope is mandatory: the sentinel above still exports everything. So this reports the
                failure and offers a retry rather than blocking the action. */}
            {vm.isEntityTypesError && (
              <ErrorMessage
                size="sm"
                message={t("definitionExport.loadFailed")}
                onRetry={() => vm.refetchEntityTypes()}
              />
            )}
          </div>

          <p className="flex items-start gap-2 text-sm text-muted-foreground">
            <FileSpreadsheet className="mt-0.5 h-4 w-4 shrink-0" aria-hidden="true" />
            <span>{t("definitionExport.contents")}</span>
          </p>

          <p
            className="flex items-start gap-2 text-sm text-muted-foreground"
            data-testid="definition-export-exportable-note"
          >
            <Info className="mt-0.5 h-4 w-4 shrink-0" aria-hidden="true" />
            <span>{t("definitionExport.exportableNote")}</span>
          </p>

          {/* The refusal, before the generic error line and instead of it. */}
          {vm.isRowCapRefused && (
            <Alert variant="warning" data-testid="definition-export-refused">
              <AlertCircle />
              <AlertTitle>{t("definitionExport.refused.title")}</AlertTitle>
              <AlertDescription>
                {t("definitionExport.refused.description", { max: vm.maxExportRows })}
              </AlertDescription>
            </Alert>
          )}

          {vm.isError && !vm.isRowCapRefused && (
            <p className="flex items-start gap-2 text-sm text-destructive" role="alert">
              <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" aria-hidden="true" />
              <span>{vm.errorMessage ?? t("definitionExport.toast.exportFailed")}</span>
            </p>
          )}

          {/* Nothing was saved, and saying so is the point: an `.xlsx` that a spreadsheet refuses to
              open is a worse outcome than a clear refusal. */}
          {exported && !exported.isUsable && (
            <Alert variant="destructive" data-testid="definition-export-unexpected-file">
              <AlertCircle />
              <AlertTitle>{t("definitionExport.unexpectedFile.title")}</AlertTitle>
              <AlertDescription>{t("definitionExport.unexpectedFile.description")}</AlertDescription>
            </Alert>
          )}

          {/* The file WAS saved -- by the download manager, so there is no name or size to report. */}
          {vm.wasIntercepted && (
            <Alert variant="info" data-testid="definition-export-intercepted">
              <Info />
              <AlertTitle>{t("definitionExport.intercepted.title")}</AlertTitle>
              <AlertDescription>{t("definitionExport.intercepted.description")}</AlertDescription>
            </Alert>
          )}

          {exported && exported.isUsable && (
            <p className="text-sm" role="status" data-testid="definition-export-result">
              {t("definitionExport.result", {
                fileName: exported.fileName,
                size: exported.formattedSize(),
              })}
            </p>
          )}
        </div>

        <DialogFooter>
          <Button
            variant="outline"
            onClick={() => handleOpenChange(false)}
            disabled={vm.isExporting}
          >
            {t("common.close")}
          </Button>
          <Button onClick={vm.exportDefinitions} disabled={vm.isExporting}>
            <Download className="me-2 h-4 w-4 shrink-0" aria-hidden="true" />
            {vm.isExporting ? t("definitionExport.exporting") : t("definitionExport.exportAction")}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

/**
 * Field Groups Administration Screen
 *
 * Route: `/custom-fields/field-groups`.
 * Lists one entity type's groups in their configured display order and enables
 * creating, renaming, reordering, and deleting field groups.
 */
"use client";

import { useCallback, useMemo, useState } from "react";
import Link from "next/link";
import { useI18n } from "@core/providers/i18n-provider";
import { useModuleLocales } from "@core/hooks/use-module-locales";
import { usePermission } from "@core/hooks/use-permission";
import { PageHeader } from "@core/ui/page-header";
import { Button } from "@core/ui/button";
import { Label } from "@core/ui/label";
import { EmptyState } from "@core/ui/empty-state";
import { ErrorMessage } from "@core/ui/error-message";
import { Alert, AlertDescription, AlertTitle } from "@core/ui/alert";
import { ConfirmationDialog } from "@core/ui/confirmation-dialog";
import { GenericSelect, type GenericSelectOption } from "@core/crud/components/generic-select";
import { ChevronLeft, ChevronRight, FolderTree, Globe2, Plus } from "lucide-react";
import { CUSTOM_FIELDS_PERMISSIONS } from "../../../../permission-constants";
import { useFieldGroupViewModel } from "../viewmodels/useFieldGroupViewModel";
import { FieldGroupList } from "../components/FieldGroupList";
import { FieldGroupEditor, type FieldGroupFormValues } from "../components/FieldGroupEditor";
import type { FieldGroup } from "../../domain/entities/FieldGroup";

export function FieldGroupListView() {
  useModuleLocales(() => import("../../../locales"), "customFieldGroups");
  useModuleLocales(
    () => import("../../../../custom-field/locales"),
    "customFields"
  );
  const { t, language, direction } = useI18n();
  const BackIcon = direction === "rtl" ? ChevronRight : ChevronLeft;

  const [entityTypeKey, setEntityTypeKey] = useState("");
  const [pendingDelete, setPendingDelete] = useState<FieldGroup | null>(null);
  const [draggedId, setDraggedId] = useState<string | null>(null);
  const [dropTargetId, setDropTargetId] = useState<string | null>(null);

  const canCreate = usePermission(CUSTOM_FIELDS_PERMISSIONS.FIELD_GROUP_CREATE);

  const vm = useFieldGroupViewModel(entityTypeKey);

  const entityTypes = vm.entityTypes ?? [];
  const entityTypeOptions: GenericSelectOption[] = useMemo(
    () =>
      entityTypes.map((item) => ({
        value: item.key,
        label: `${language === "ar" ? item.displayNameAr : item.displayNameEn} (${item.key})`,
      })),
    [entityTypes, language]
  );

  const editingGroup = vm.groups.find((group) => group.id === vm.editingId) ?? null;

  const rowLabels = useMemo(
    () => ({
      moveUp: t("fieldGroup.moveUp"),
      moveDown: t("fieldGroup.moveDown"),
      edit: t("common.edit"),
      delete: t("common.delete"),
      global: t("fieldGroup.global"),
      sortOrder: t("fieldGroup.fields.sortOrder"),
    }),
    [t]
  );

  const editingId = vm.editingId;
  const isPlatformContext = vm.isPlatformContext;
  const editorLabels = useMemo(
    () => ({
      heading: editingId ? t("fieldGroup.editTitle") : t("fieldGroup.addNew"),
      stableKey: t("fieldGroup.fields.stableKey"),
      stableKeyHint: t("fieldGroup.fields.stableKeyHint"),
      labelEn: t("fieldGroup.fields.labelEn"),
      labelAr: t("fieldGroup.fields.labelAr"),
      sortOrder: t("fieldGroup.fields.sortOrder"),
      isGlobal: t("fieldGroup.fields.isGlobal"),
      isGlobalDescription: isPlatformContext
        ? t("fieldGroup.isGlobalDescription.platformContext")
        : t("fieldGroup.isGlobalDescription.tenantContext"),
      save: t("common.save"),
      cancel: t("common.cancel"),
    }),
    [t, editingId, isPlatformContext]
  );

  const handleSubmit = useCallback(
    async (values: FieldGroupFormValues) => {
      try {
        if (vm.editingId !== null) {
          await vm.updateGroup({
            id: vm.editingId,
            input: {
              labelEn: values.labelEn,
              labelAr: values.labelAr.length > 0 ? values.labelAr : null,
              sortOrder: values.sortOrder,
            },
          });
        } else {
          await vm.createGroup({
            entityTypeKey,
            stableKey: values.stableKey,
            labelEn: values.labelEn,
            labelAr: values.labelAr.length > 0 ? values.labelAr : null,
            sortOrder: values.sortOrder,
            isGlobal: values.isGlobal,
          });
        }
        vm.closeEditor();
      } catch {
        // Errors are surfaced via mutation callbacks
      }
    },
    [entityTypeKey, vm]
  );

  const handleConfirmDelete = useCallback(async () => {
    if (!pendingDelete) return;
    const deletedId = pendingDelete.id;
    try {
      await vm.deleteGroup(deletedId);
      setPendingDelete(null);
      if (vm.editingId === deletedId) vm.closeEditor();
    } catch {
      // Handled via mutation callback
    }
  }, [pendingDelete, vm]);

  const handleDrop = useCallback(
    (targetId: string) => {
      if (draggedId) vm.moveBefore(draggedId, targetId);
      setDraggedId(null);
      setDropTargetId(null);
    },
    [draggedId, vm]
  );

  const isEditorOpen = vm.isCreating || vm.editingId !== null;

  return (
    <div className="flex flex-col gap-6 pb-12">
      <PageHeader
        icon={FolderTree}
        title={t("fieldGroup.title")}
        description={t("fieldGroup.description")}
        eyebrow={
          <Link href="/custom-fields">
            <Button variant="ghost" size="sm">
              <BackIcon className="me-2 h-4 w-4 shrink-0" aria-hidden="true" />
              {t("common.back")}
            </Button>
          </Link>
        }
        actions={
          canCreate && entityTypeKey.length > 0 && !isEditorOpen ? (
            <Button size="sm" onClick={vm.startCreate}>
              <Plus className="me-2 h-4 w-4 shrink-0" aria-hidden="true" />
              {t("fieldGroup.addNew")}
            </Button>
          ) : undefined
        }
      />

      {vm.isPlatformContext && (
        <Alert variant="info">
          <Globe2 />
          <AlertTitle>{t("fieldGroup.platformContext.title")}</AlertTitle>
          <AlertDescription>{t("fieldGroup.platformContext.description")}</AlertDescription>
        </Alert>
      )}

      <div className="flex max-w-md flex-col gap-1.5">
        <Label htmlFor="field-group-entity-type">{t("fieldGroup.fields.entityTypeKey")}</Label>
        <GenericSelect
          id="field-group-entity-type"
          aria-label={t("fieldGroup.fields.entityTypeKey")}
          type="single"
          options={entityTypeOptions}
          value={entityTypeKey}
          onValueChange={(value: string | string[]) => {
            setEntityTypeKey(typeof value === "string" ? value : (value[0] ?? ""));
            vm.closeEditor();
          }}
          placeholder={t("fieldGroup.placeholders.entityTypeKey")}
          loading={vm.isEntityTypesLoading}
        />
        {vm.isEntityTypesError && (
          <ErrorMessage
            size="sm"
            message={t("customField.entityTypesLoadFailed")}
            onRetry={() => vm.refetchEntityTypes()}
          />
        )}
      </div>

      {entityTypeKey.length === 0 ? (
        <EmptyState
          icon={FolderTree}
          title={t("fieldGroup.selectEntityType.title")}
          description={t("fieldGroup.selectEntityType.description")}
        />
      ) : vm.isGroupsError ? (
        <ErrorMessage
          message={t("fieldGroup.loadFailed")}
          onRetry={() => vm.refetchGroups()}
        />
      ) : (
        <div className="flex flex-col gap-4">
          {isEditorOpen && (
            <FieldGroupEditor
              key={vm.editingId ?? "create"}
              group={editingGroup}
              labels={editorLabels}
              canChooseScope={vm.isSuperAdmin}
              isPlatformContext={vm.isPlatformContext}
              isSaving={vm.isSaving}
              onSubmit={handleSubmit}
              onCancel={vm.closeEditor}
            />
          )}

          {vm.groups.length === 0 && !vm.isGroupsLoading ? (
            <EmptyState
              icon={FolderTree}
              title={t("fieldGroup.noItems.title")}
              description={t("fieldGroup.noItems.description")}
            />
          ) : (
            <FieldGroupList
              groups={vm.groups}
              language={language}
              labels={rowLabels}
              canMutate={vm.canMutate}
              canMoveUp={vm.canMoveUp}
              canMoveDown={vm.canMoveDown}
              isReordering={vm.isReordering}
              onMoveUp={vm.moveUp}
              onMoveDown={vm.moveDown}
              onEdit={vm.startEdit}
              onDelete={setPendingDelete}
              draggedId={draggedId}
              dropTargetId={dropTargetId}
              onDragStart={setDraggedId}
              onDragEnd={() => {
                setDraggedId(null);
                setDropTargetId(null);
              }}
              onDragEnterRow={setDropTargetId}
              onDropOnRow={handleDrop}
            />
          )}
        </div>
      )}

      <ConfirmationDialog
        open={pendingDelete !== null}
        onOpenChange={(open) => {
          if (!open) setPendingDelete(null);
        }}
        variant="destructive"
        title={t("fieldGroup.deleteTitle")}
        description={t("fieldGroup.deleteConfirm", {
          name: pendingDelete?.displayLabel(language) ?? "",
        })}
        confirmText={t("common.delete")}
        cancelText={t("common.cancel")}
        isLoading={vm.isDeleting}
        onConfirm={handleConfirmDelete}
      />
    </div>
  );
}

