    adminName
      .trim()
      .split(/\s+/)
      .slice(0, 2)
      .map((s) => s[0]?.toUpperCase())
      .join("") || "SA";

  return (
    <Card className="w-full max-w-lg border border-border bg-card shadow-lg rounded-2xl overflow-hidden">
      <CardHeader className="text-center pb-2 pt-8">
        <div className="mx-auto mb-4 flex h-14 w-14 items-center justify-center rounded-2xl bg-primary/10 text-primary border border-primary/20 shadow-xs">
          <CheckCircle2 className="h-7 w-7" />
        </div>
        <CardTitle className="text-2xl font-bold tracking-tight text-foreground">
          {t("auth.accountSetup.welcomeTitle", { tenant: tenantName || BRAND.name })}
        </CardTitle>
        <CardDescription className="text-sm text-muted-foreground mt-1">
          {t("auth.accountSetup.welcomeSubtitle")}
        </CardDescription>
      </CardHeader>

      <CardContent className="space-y-6 pt-2 pb-8 px-6 sm:px-8">
        {/* Administrator Credentials Summary Box */}
        <div className="rounded-xl border border-border bg-muted/20 p-4 space-y-3 min-w-0">
          <div className="flex items-center gap-3.5 min-w-0">
            <Avatar className="h-12 w-12 border border-border shadow-xs shrink-0">
              {profileImageUrl ? (
                <AvatarImage src={profileImageUrl} alt={adminName} className="object-cover" />
              ) : null}
              <AvatarFallback className="bg-primary/10 text-sm font-bold text-primary">
                {initials}
              </AvatarFallback>
            </Avatar>
            <div className="space-y-1 min-w-0 flex-1">
              <div className="flex items-center gap-2 min-w-0">
                <span className="font-semibold text-foreground text-sm truncate">
                  {adminName || "Administrator"}
                </span>
                {adminUsername && (
                  <Badge
                    variant="secondary"
                    className="text-[10px] font-mono px-1.5 py-0 shrink-0 max-w-[140px] truncate"
                  >
                    @{adminUsername}
                  </Badge>
                )}
              </div>
              <p className="text-xs text-muted-foreground truncate">{adminEmail}</p>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-2 pt-2 border-t border-border/40 text-xs min-w-0">
            <div className="space-y-0.5 min-w-0">
              <span className="text-muted-foreground">{t("auth.accountSetup.organization")}</span>
              <p className="font-medium text-foreground truncate">{tenantName || "—"}</p>
            </div>
            <div className="space-y-0.5 min-w-0">
              <span className="text-muted-foreground">Assigned Role</span>
              <p className="font-medium text-foreground flex items-center gap-1 truncate">
                <Shield className="h-3 w-3 text-primary shrink-0" />
                <span className="truncate">{t("auth.accountSetup.superAdminRole")}</span>
              </p>
            </div>
          </div>
        </div>

        {/* Security Notice */}
        <p className="text-center text-xs text-muted-foreground">
          {t("auth.accountSetup.securityNotice")}
        </p>

        {/* Launch Workspace CTA */}
        <Button
          size="lg"
          className="w-full gap-2 font-semibold shadow-xs"
          onClick={() => {
            const redirectUrl = adminEmail
              ? `/login?email=${encodeURIComponent(adminEmail)}`
              : "/login";
            router.push(redirectUrl);
          }}
        >
          <span>{t("auth.accountSetup.enterWorkspace")}</span>
          <ArrowRight className="h-4 w-4" />
        </Button>
      </CardContent>
    </Card>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { getAuthContainer } from "@modules/auth/di";
import type {
  SetupTokenInfo,
  SetupCustomField,
} from "../../domain/entities";

/**
 * PageState defines the active lifecycle state of the account setup view:
 * - "loading": Token validation is currently in progress.
 * - "valid": The token is valid and the setup form is ready for input.
 * - "invalid": The token is invalid, expired, or missing.
 * - "activating": The administrator setup request is currently submitting.
 * - "success": The setup was completed successfully.
 * - "error": An error occurred during account activation.
 */
export type PageState = "loading" | "valid" | "invalid" | "activating" | "success" | "error";

/**
 * SetupStep represents the 4 discrete onboarding stages:
 * 1: Security (Password & Confirm Password, live policy meter, strength checks)
 * 2: Profile (First Name, Last Name, Phone, Avatar dropzone, verified email/username)
 * 3: Attributes & Compliance (Dynamic custom fields with encryption badges)
 * 4: Launch Celebration (Workspace activation summary & direct access CTA)
 */
export type SetupStep = 1 | 2 | 3 | 4;

/**
 * useAccountSetupViewModel is the custom presentation hook / ViewModel for SetupAccountView.
 * It manages token validation, 4-stage stepper navigation, live password strength,
 * administrator profile customization, avatar uploads, and dynamic compliance attributes.
 *
 * @param params Settings, active token, and localized validation messages.
 * @returns ViewModel state properties, user credentials input binding, and trigger callbacks.
 */
export function useAccountSetupViewModel(params: {
  token: string;
  missingTokenMessage: string;
  invalidTokenMessage: string;
  validationFailedMessage: string;
  activationFailedMessage: string;
  activationUnexpectedMessage: string;
  passwordValidationMessages: {
    minLength: string;
    hasUpper: string;
    hasLower: string;
    hasNumber: string;
    hasSpecial: string;
    matches: string;
  };
}) {
  const {
    token,
    missingTokenMessage,
    invalidTokenMessage,
    validationFailedMessage,
    activationFailedMessage,
    activationUnexpectedMessage,
    passwordValidationMessages,
  } = params;

  // ── Lifecycle & Stepper State ──
  const [pageState, setPageState] = useState<PageState>(!token ? "invalid" : "loading");
  const [currentStep, setCurrentStep] = useState<SetupStep>(1);
  const [tokenData, setTokenData] = useState<SetupTokenInfo | null>(null);
  const [errorMessage, setErrorMessage] = useState<string>(!token ? missingTokenMessage : "");
  const [validationErrors, setValidationErrors] = useState<string[]>([]);

  // ── Stage 1: Security State ──
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);

  // ── Stage 2: Profile State ──
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [phoneNumber, setPhoneNumber] = useState("");
  const [profileImageUrl, setProfileImageUrl] = useState("");
  const [avatarError, setAvatarError] = useState<string | null>(null);

  // ── Stage 3: Attributes & Compliance State ──
  const [customFields, setCustomFields] = useState<SetupCustomField[]>([]);
  const [isLoadingCustomFields, setIsLoadingCustomFields] = useState(false);
  const [customFieldValues, setCustomFieldValues] = useState<Record<string, unknown>>({});

  // ── Password Policy Constraints ──
  const passwordMinLength = tokenData?.passwordMinLength ?? 8;
  const passwordRequireUppercase = tokenData?.passwordRequireUppercase !== false;
  const passwordRequireNumber = tokenData?.passwordRequireNumber !== false;
  const passwordRequireSpecial = tokenData?.passwordRequireSpecial === true;

  const passwordChecks = useMemo(
    () => ({
      minLength: password.length >= passwordMinLength,
      hasUpper: passwordRequireUppercase ? /[A-Z]/.test(password) : true,
      hasLower: /[a-z]/.test(password),
      hasNumber: passwordRequireNumber ? /\d/.test(password) : true,
      hasSpecial: passwordRequireSpecial ? /[^A-Za-z0-9]/.test(password) : true,
      matches: password === confirmPassword && confirmPassword.length > 0,
    }),
    [
      confirmPassword,
      password,
      passwordMinLength,
      passwordRequireNumber,
      passwordRequireSpecial,
      passwordRequireUppercase,
    ]
  );

  const isPasswordValid = useMemo(
    () => Object.values(passwordChecks).every(Boolean),
    [passwordChecks]
  );

  const passwordScore = useMemo(() => {
    let passed = 0;
    let total = 0;
    total++;
    if (passwordChecks.minLength) passed++;
    total++;
    if (passwordChecks.hasLower) passed++;
    if (passwordRequireUppercase) {
      total++;
      if (passwordChecks.hasUpper) passed++;
    }
    if (passwordRequireNumber) {
      total++;
      if (passwordChecks.hasNumber) passed++;
    }
    if (passwordRequireSpecial) {
      total++;
      if (passwordChecks.hasSpecial) passed++;
    }
    total++;
    if (passwordChecks.matches) passed++;
    return Math.round((passed / total) * 100);
  }, [
    passwordChecks,
    passwordRequireNumber,
    passwordRequireSpecial,
    passwordRequireUppercase,
  ]);

  const passwordEntropy = useMemo(() => {
    if (!password) return 0;
    let pool = 0;
    if (/[a-z]/.test(password)) pool += 26;
    if (/[A-Z]/.test(password)) pool += 26;
    if (/\d/.test(password)) pool += 10;
    if (/[^A-Za-z0-9]/.test(password)) pool += 32;
    if (pool === 0) return 0;
    return password.length * Math.log2(pool);
  }, [password]);

  // ── Profile Validation ──
  const isProfileValid = useMemo(() => firstName.trim().length > 0, [firstName]);

  // ── Stage 3: Attributes & Compliance State ──
  const [attributesTouched, setAttributesTouched] = useState(false);

  // ── Attributes Field-Level Errors & Overall Validity ──
  const customFieldErrors = useMemo(() => {
    const errors: Record<string, string> = {};
    for (const field of customFields) {
      if (field.isRequired) {
        const val = customFieldValues[field.key];
        const isEmpty =
          val === undefined ||
          val === null ||
          (typeof val === "string" && val.trim() === "") ||
          (Array.isArray(val) && val.length === 0);

        if (isEmpty) {
          errors[field.key] = "This field is required";
        }
      }
    }
    return errors;
  }, [customFields, customFieldValues]);

  const isAttributesValid = useMemo(() => {
    return Object.keys(customFieldErrors).length === 0;
  }, [customFieldErrors]);

  // ── Avatar Photo Handler ──
  const handleAvatarUpload = useCallback((file: File) => {
    setAvatarError(null);
    if (!file.type.startsWith("image/")) {
      setAvatarError("Please select a valid image file (PNG, JPG, WEBP).");
      return;
    }
    if (file.size > 2 * 1024 * 1024) {
      setAvatarError("Image size must be less than 2MB.");
      return;
    }
    const reader = new FileReader();
    reader.onload = () => {
      if (typeof reader.result === "string") {
        setProfileImageUrl(reader.result);
      }
    };
    reader.readAsDataURL(file);
  }, []);

  const removeAvatar = useCallback(() => {
    setProfileImageUrl("");
    setAvatarError(null);
  }, []);

  // ── Custom Field Value Mutator ──
  const setCustomFieldValue = useCallback((key: string, value: unknown) => {
    setCustomFieldValues((prev) => ({ ...prev, [key]: value }));
  }, []);

  // ── Token Validation & Setup Context Fetch ──
  useEffect(() => {
    if (!token) return;

    let cancelled = false;

    async function validate() {
      try {
        const result = await getAuthContainer().accountSetupRepository.validateToken(token);
        if (cancelled) return;

        if (result.isValid) {
          setTokenData(result);
          if (result.firstName) setFirstName(result.firstName);
          if (result.lastName) setLastName(result.lastName);
          if (result.phoneNumber) setPhoneNumber(result.phoneNumber);
          if (result.profileImageUrl) setProfileImageUrl(result.profileImageUrl);
          setPageState("valid");

          // Load active custom fields for identity.admin
          try {
            setIsLoadingCustomFields(true);
            const fields = await getAuthContainer().accountSetupRepository.getCustomFields(token);
            if (cancelled) return;
            setCustomFields(fields || []);
            const initialVals: Record<string, unknown> = {};
            for (const f of fields || []) {
              if (f.currentValue !== undefined && f.currentValue !== null) {
                initialVals[f.key] = f.currentValue;
              }
            }
            setCustomFieldValues(initialVals);
          } catch (fieldErr) {
            console.warn("Failed to fetch setup custom fields:", fieldErr);
          } finally {
            if (!cancelled) setIsLoadingCustomFields(false);
          }
        } else {
          setPageState("invalid");
          setErrorMessage(result.error || result.errorMessage || invalidTokenMessage);
        }
      } catch (err: unknown) {
        if (cancelled) return;
        const details = (
          err as { details?: { error?: string; message?: string; errorMessage?: string } }
        )?.details;
        setPageState("invalid");
        setErrorMessage(
          details?.error || details?.errorMessage || details?.message || validationFailedMessage
        );
      }
    }

    validate();
    return () => {
      cancelled = true;
    };
  }, [invalidTokenMessage, token, validationFailedMessage]);

  // ── Final Activation Handler ──
  const activate = useCallback(async () => {
    setValidationErrors([]);

    if (!isPasswordValid) {
      setCurrentStep(1);
      const errors: string[] = [];
      const minLengthVal = tokenData?.passwordMinLength ?? 8;
      if (!passwordChecks.minLength) {
        errors.push(passwordValidationMessages.minLength.replace("{{min}}", String(minLengthVal)));
      }
      if (!passwordChecks.hasUpper) errors.push(passwordValidationMessages.hasUpper);
      if (!passwordChecks.hasLower) errors.push(passwordValidationMessages.hasLower);
      if (!passwordChecks.hasNumber) errors.push(passwordValidationMessages.hasNumber);
      if (!passwordChecks.hasSpecial) errors.push(passwordValidationMessages.hasSpecial);
      if (!passwordChecks.matches) errors.push(passwordValidationMessages.matches);
      setValidationErrors(errors);
      return;
    }

    if (!isProfileValid) {
      setCurrentStep(2);
      return;
    }

    if (!isAttributesValid) {
      setAttributesTouched(true);
      setCurrentStep(3);
      return;
    }

    setPageState("activating");
    try {
      const result = await getAuthContainer().accountSetupRepository.activateAccount({
        token,
        password,
        confirmPassword,
        firstName: firstName.trim() || undefined,
        lastName: lastName.trim() || undefined,
        phoneNumber: phoneNumber.trim() || undefined,
        profileImageUrl: profileImageUrl.trim() || undefined,
        customFieldValues:
          Object.keys(customFieldValues).length > 0 ? customFieldValues : undefined,
      });

      if (result.success) {
        setPageState("success");
        setCurrentStep(4);
      } else {
        setPageState("error");
        setErrorMessage(result.error || result.errorMessage || activationFailedMessage);
      }
    } catch (err: unknown) {
      const details = (
        err as { details?: { error?: string; message?: string; errorMessage?: string } }
      )?.details;
      setPageState("error");
      setErrorMessage(
        details?.error || details?.errorMessage || details?.message || activationUnexpectedMessage
      );
    }
  }, [
    activationFailedMessage,
    activationUnexpectedMessage,
    confirmPassword,
    customFieldValues,
    firstName,
    isAttributesValid,
    isPasswordValid,
    isProfileValid,
    lastName,
    password,
    passwordChecks,
    passwordMinLength,
    passwordValidationMessages,
    phoneNumber,
    profileImageUrl,
    token,
  ]);

  // ── Stepper Navigation ──
  const canProceedToNext = useMemo(() => {
    if (currentStep === 1) return isPasswordValid;
    if (currentStep === 2) return isProfileValid;
    if (currentStep === 3) return isAttributesValid;
    return true;
  }, [currentStep, isPasswordValid, isProfileValid, isAttributesValid]);

  const hasCustomFields = customFields.length > 0;

  const goToNextStep = useCallback(() => {
    setValidationErrors([]);
    if (currentStep === 1) {
      if (!isPasswordValid) return;
      setCurrentStep(2);
    } else if (currentStep === 2) {
      if (!isProfileValid) return;
      if (hasCustomFields) {
        setCurrentStep(3);
      } else {
        void activate();
      }
    } else if (currentStep === 3) {
      setAttributesTouched(true);
      if (!isAttributesValid) return;
      void activate();
    }
  }, [
    currentStep,
    isPasswordValid,
    isProfileValid,
    hasCustomFields,
    isAttributesValid,
    activate,
  ]);

  const goToPrevStep = useCallback(() => {
    setValidationErrors([]);
    if (currentStep > 1 && currentStep < 4) {
      setCurrentStep((s) => (s - 1) as SetupStep);
    }
  }, [currentStep]);

  const goToStep = useCallback(
    (step: SetupStep) => {
      if (step === 1) {
        setCurrentStep(1);
      } else if (step === 2 && isPasswordValid) {
        setCurrentStep(2);
      } else if (step === 3 && isPasswordValid && isProfileValid && hasCustomFields) {
        setCurrentStep(3);
      }
    },
    [isPasswordValid, isProfileValid, hasCustomFields]
  );

  const retry = useCallback(() => {
    setErrorMessage("");
    setPageState("valid");
  }, []);

  return {
    pageState,
    setPageState,
    currentStep,
    setCurrentStep,
    tokenData,
    errorMessage,
    validationErrors,

    // Step 1: Security
    password,
    setPassword,
    confirmPassword,
    setConfirmPassword,
    showPassword,
    setShowPassword,
    showConfirm,
    setShowConfirm,
    passwordChecks,
    passwordScore,
    passwordEntropy,
    isPasswordValid,

    // Step 2: Profile
    firstName,
    setFirstName,
    lastName,
    setLastName,
    phoneNumber,
    setPhoneNumber,
    profileImageUrl,
    setProfileImageUrl,
    avatarError,
    handleAvatarUpload,
    removeAvatar,
    isProfileValid,

    // Step 3: Custom Fields
    customFields,
    isLoadingCustomFields,
    customFieldValues,
    setCustomFieldValue,
    customFieldErrors,
    attributesTouched,
    setAttributesTouched,
    isAttributesValid,

    // Stepper Navigation
    canProceedToNext,
    goToNextStep,
    goToPrevStep,
    goToStep,

    // Execution
    activate,
    retry,
  };
}

/**
 * useAuthLogin — Shared Login Mutation Hook
 *
 * Used by useLoginViewModel (signin submodule) and exported for external use.
 * Flow: View → ViewModel → useAuthLogin → AuthRepository → AuthService → API
 *
 * @module auth/core/presentation
 */
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { useServices } from "@core/providers/service-provider";
import { useAppStore } from "@core/store/useAppStore";
import { LoginRequest } from "../../../domain/entities/Auth";

/**
 * React hook/ViewModel orchestrating state and data flows for auth login.
 * Coordinates query synchronization (TanStack Query) with application client store indicators (Zustand) and returns validation fields.
 */
export function useAuthLogin() {
  const { authRepository } = useServices();
  const setAuth = useAppStore((state) => state.setAuth);
  const setSubscriptionInfo = useAppStore((state) => state.setSubscriptionInfo);
  const setDefaultRedirectPath = useAppStore((state) => state.setDefaultRedirectPath);
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({
      identifier,
      password,
      tenantId,
      tenantCode,
      isPlatformAdmin,
      staySignedIn,
    }: {
      identifier: string;
      password: string;
      tenantId?: string;
      tenantCode?: string;
      isPlatformAdmin?: boolean;
      staySignedIn?: boolean;
    }) => {
      // Construct domain entity — repository handles mapping to API model
      const request = new LoginRequest({
        identifier,
        password,
        tenantId,
        isPlatformAdmin,
        staySignedIn,
      });
      return authRepository.login(request);
    },
    onSuccess: async (result, variables) => {
      const {
        user,
        subscriptionStatus,
        gracePhase,
        editionName,
        mustChangePassword,
        defaultRedirectPath,
      } = result;

      // 1. Set user in store with permissions and roles
      setAuth(user, user.permissions || [], [], true);

      // 2. Store subscription status for payment wall / grace banner
      setSubscriptionInfo(subscriptionStatus, gracePhase, editionName);

      // 2b. Store must-change-password flag for route guard enforcement
      useAppStore.getState().setMustChangePassword(mustChangePassword ?? false);

      // 2c. Store backend-provided redirect path — authoritative, not guessed
      setDefaultRedirectPath(defaultRedirectPath ?? "/");

      // 3. Persist tenant code for tenant-aware logout redirect
      if (variables.tenantCode) {
        useAppStore.getState().setTenantCode(variables.tenantCode);
      }

      // 4. Skip navigation & data fetch if user must change password first
      // They'll be redirected to /change-password immediately — no need to load menus
      if (!mustChangePassword) {
        // v2: NavigationProvider's TanStack queries fire automatically when
        // isAuthenticated becomes true — no explicit refresh call needed here.
        // Just invalidate cached queries to ensure fresh data on protected pages.
        queryClient.invalidateQueries();
      }
    },
  });
}

"use client";

/**
 * Cookie-Based Impersonation Hook
 *
 * Clean Architecture:
 * View → ViewModel → useImpersonation → AuthRepository → AuthService → API
 *
 * Impersonation state is persisted in sessionStorage ("scr_impersonating")
 * so the header banner survives page reloads within the same tab.
 *
 * Flow:
 * 1. startImpersonation(adminId) → repo.impersonate(adminId)
 *    → AuthService.impersonate() → POST /v1/auth/admin/impersonate/{id}
 *    → CookieAuthMiddleware sets httpOnly cookie for refresh token
 *    → AuthRepository stores access token + sets sessionStorage flag
 *    → Page reload → refresh works via httpOnly cookie → banner shows
 *
 * 2. stopImpersonation() → repo.stopImpersonation()
 *    → AuthService.stopImpersonation() → POST /v1/auth/admin/stop-impersonation
 *    → Backend reads ImpersonatorAdminId from current refresh token
 *    → Generates new tokens for original admin
 *    → CookieAuthMiddleware replaces httpOnly cookie
 *    → AuthRepository restores original admin session + clears sessionStorage flag
 */

import { useState, useCallback, useEffect } from "react";
import { useEnhancedToast } from "@core/hooks/use-enhanced-toast";
import { useQueryClient } from "@tanstack/react-query";
import { appLogger } from "@core/common/logger";
import { getAuthContainer } from "@modules/auth/di";
import { STORAGE_KEYS } from "@core/config/storage-keys";
import { authBroadcast } from "@core/common/broadcast-auth";

/**
 * Check if we're currently impersonating (read from sessionStorage).
 * This survives page reloads within the same tab but not new tabs.
 */
function getImpersonationState(): boolean {
  if (typeof window === "undefined") return false;
  return sessionStorage.getItem(STORAGE_KEYS.IMPERSONATING) === "true";
}

/**
 * React hook/ViewModel orchestrating state and data flows for impersonation.
 * Manages TanStack Query hooks, query cache keys, and repository fetch requests.
 */
export function useImpersonation() {
  const { success, error: toastError } = useEnhancedToast();
  const queryClient = useQueryClient();
  // Initialize from sessionStorage so impersonation state survives page reloads
  const [isImpersonating, setIsImpersonating] = useState(getImpersonationState);
  const [isImpersonationLoading, setIsImpersonationLoading] = useState(false);

  // Subscribe to cross-tab impersonation events so all open tabs update instantly
  useEffect(() => {
    authBroadcast.onImpersonation((type) => {
      if (type === "start") {
        setIsImpersonating(true);
        // Invalidate all queries so menu items refetch with impersonated identity
        queryClient.invalidateQueries();
      } else {
        setIsImpersonating(false);
        // Clear navigation cache so menu reloads with restored identity
        getAuthContainer().authRepository.clearNavigationCaches();
        queryClient.invalidateQueries();
      }
    });
    // Note: authBroadcast is a singleton — no cleanup needed
  }, [queryClient]);

  /**
   * Start impersonating another admin.
   * Uses AuthRepository → AuthService (clean architecture).
   */
  const startImpersonation = useCallback(
    async (adminId: string) => {
      setIsImpersonationLoading(true);
      try {
        const repo = getAuthContainer().authRepository;
        await repo.impersonate(adminId);

        setIsImpersonating(true);
        success({
          title: "Impersonation started",
          description: "You are now viewing as another admin.",
        });
        appLogger.auth(`Impersonation started for admin: ${adminId}`);

        // Purge all workspace navigation caches so the new identity loads fresh data
        repo.clearNavigationCaches();

        // Navigate to home with full reload — fresh data with new identity
        window.location.href = "/";
      } catch (err) {
        appLogger.error("Impersonation failed:", err);
        toastError({
          title: "Impersonation failed",
          description: err instanceof Error ? err.message : "Unknown error",
        });
      } finally {
        setIsImpersonationLoading(false);
      }
    },
    [success, toastError]
  );

  /**
   * Stop impersonation and restore original admin session.
   * Uses AuthRepository → AuthService (clean architecture).
   */
  const stopImpersonation = useCallback(async () => {
    setIsImpersonationLoading(true);
    try {
      const repo = getAuthContainer().authRepository;
      await repo.stopImpersonation();

      setIsImpersonating(false);
      success({
        title: "Impersonation ended",
        description: "Your original session has been restored.",
      });
      appLogger.auth("Impersonation stopped, original admin restored");

      // Purge all workspace navigation caches so the original admin loads fresh data
      repo.clearNavigationCaches();

      // Navigate to home with full reload — fresh data with original identity
      window.location.href = "/";
    } catch (err) {
      appLogger.error("Stop impersonation failed:", err);
      toastError({
        title: "Stop impersonation failed",
        description: err instanceof Error ? err.message : "Unknown error",
      });
    } finally {
      setIsImpersonationLoading(false);
    }
  }, [queryClient, success, toastError]);

  return {
    isImpersonating,
    isImpersonationLoading,
    startImpersonation,
    stopImpersonation,
  };
}

"use client";

import { useI18n } from "@core/providers/i18n-provider";
import { Button } from "@core/ui/button";
import { LoadingSpinner } from "@core/ui/loading-spinner";
import { Mail, Fingerprint, Smartphone, QrCode } from "lucide-react";
import type { LoginFormData } from "../viewmodels/use-login-viewmodel";
import { CredentialsFormHeader } from "./CredentialsFormHeader";
import { MethodChipsSection } from "./MethodChipsSection";
import { IdentifierInput } from "./IdentifierInput";
import { CredentialsPasswordInput } from "./CredentialsPasswordInput";
import { FormOptions } from "./FormOptions";
import { UnactivatedAccountAlert } from "./UnactivatedAccountAlert";
import { CredentialsErrorAlert } from "./CredentialsErrorAlert";

interface CredentialsFormProps {
  formData: LoginFormData;
  showPassword: boolean;
  isLoading: boolean;
  isFormValid: boolean;
  error: string;
  shakeKey: number;
  isRTL: boolean;
  isPlatformMode?: boolean;
  updateField: (field: keyof LoginFormData, value: unknown) => void;
  togglePasswordVisibility: () => void;
  handleLogin: () => void;
  onMagicLinkRequest?: (identifier: string) => void;
  onSwitchToPasskey?: () => void;
  onSwitchToPhoneOtp?: () => void;
  onSwitchToQrLogin?: () => void;
  errorAnnounce?: boolean;
  isAccountNotActivated?: boolean;
  accountNotActivatedMessage?: string;
  cooldownSeconds?: number;
  onResendSetupEmail?: () => void;
}

/**
 * Presentation UI component rendering the credentials form using @core/ui/* design system.
 */
export function CredentialsForm({
  formData,
  showPassword,
  isLoading,
  isFormValid,
  error,
  shakeKey,
  isRTL,
  isPlatformMode = false,
  updateField,
  togglePasswordVisibility,
  handleLogin,
  onMagicLinkRequest,
  onSwitchToPasskey,
  onSwitchToPhoneOtp,
  onSwitchToQrLogin,
  errorAnnounce = true,
  isAccountNotActivated = false,
  accountNotActivatedMessage = "",
  cooldownSeconds = 0,
  onResendSetupEmail,
}: CredentialsFormProps) {
  const { t } = useI18n();
  const arrow = isRTL ? "←" : "→";

  /* ── Method chip data ─────────────────────────────── */
  const methodChips = [
    onMagicLinkRequest && {
      key: "magic",
      icon: <Mail className="h-[13px] w-[13px]" aria-hidden="true" />,
      label: t("auth.magicLink.chip") || "Magic link",
      onClick: () => onMagicLinkRequest(formData.identifier),
    },
    onSwitchToPasskey && {
      key: "passkey",
      icon: <Fingerprint className="h-[13px] w-[13px]" aria-hidden="true" />,
      label: t("auth.passkey.chip") || "Passkey",
      onClick: onSwitchToPasskey,
    },
    onSwitchToPhoneOtp && {
      key: "phone",
      icon: <Smartphone className="h-[13px] w-[13px]" aria-hidden="true" />,
      label: t("auth.phoneOtp.chip") || "Phone OTP",
      onClick: onSwitchToPhoneOtp,
    },
    onSwitchToQrLogin && {
      key: "qr",
      icon: <QrCode className="h-[13px] w-[13px]" aria-hidden="true" />,
      label: t("auth.qr.chip") || "QR code",
      onClick: onSwitchToQrLogin,
    },
  ].filter(Boolean) as Array<{ key: string; icon: React.ReactNode; label: string; onClick: () => void }>;

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        if (!isLoading && isFormValid) handleLogin();
      }}
      className="flex flex-col gap-[var(--login-gap,16px)]"
      role="form"
      aria-label={t("auth.loginFormAriaLabel")}
      noValidate
    >
      {/* ── Heading: eyebrow + title + subtitle ────────── */}
      <CredentialsFormHeader t={t} />

      {/* ── Alerts ───────── */}
      {isAccountNotActivated ? (
        <UnactivatedAccountAlert
          t={t}
          accountNotActivatedMessage={accountNotActivatedMessage}
          cooldownSeconds={cooldownSeconds}
          isLoading={isLoading}
          onResendSetupEmail={onResendSetupEmail}
        />
      ) : error ? (
        <CredentialsErrorAlert
          error={error}
          shakeKey={shakeKey}
          errorAnnounce={errorAnnounce}
          t={t}
        />
      ) : null}

      {/* ── Identifier ─────────────────────────────────── */}
      <IdentifierInput
        value={formData.identifier}
        onChange={(val) => updateField("identifier", val)}
        disabled={isLoading}
        hasError={!!error}
        t={t}
      />

      {/* ── Password ───────────────────────────────────── */}
      <CredentialsPasswordInput
        value={formData.password}
        onChange={(val) => updateField("password", val)}
        showPassword={showPassword}
        onToggleShowPassword={togglePasswordVisibility}
        disabled={isLoading}
        hasError={!!error}
        t={t}
      />

      {/* ── Stay signed in + Forgot password (same row) ── */}
      <FormOptions
        staySignedIn={formData.staySignedIn}
        onStaySignedInChange={(val) => updateField("staySignedIn", val)}
        disabled={isLoading}
        t={t}
      />

      {/* ── Primary CTA with inner shine ──────────────── */}
      <Button
        type="submit"
        disabled={!isFormValid || isLoading}
        className="relative mt-1 flex h-[var(--login-input-height,48px)] w-full items-center justify-center gap-2 overflow-hidden rounded-xl text-[15px] font-semibold text-white shadow-none transition-all active:scale-[0.98] disabled:opacity-50"
        style={{
          background: "var(--sx-cta-gradient, hsl(var(--primary)))",
          boxShadow: "var(--sx-cta-shadow, none)",
          border: 0,
        }}
      >
        {/* Inner shine overlay */}
        <span
          className="pointer-events-none absolute inset-0"
          style={{ background: "var(--sx-cta-shine)" }}
          aria-hidden="true"
        />
        <span className="relative z-[1] inline-flex items-center justify-center gap-2">
          {isLoading ? (
            <>
              <LoadingSpinner size="inline" showText={false} />
              {t("auth.signingIn")}
            </>
          ) : (
            <>
              {t("auth.loginButton")}
              <span className="opacity-85">{arrow}</span>
            </>
          )}
        </span>
      </Button>

      {/* ── Method chips (pills, directly below CTA) ──── */}
      <MethodChipsSection methodChips={methodChips} isLoading={isLoading} t={t} />
    </form>
  );
}

