"use client";

import { useState, useCallback } from "react";
import { useDocsI18n } from "../../providers/DocsI18nProvider";

interface CodeBlockProps {
  code: string;
  language: string;
  filename?: string;
  highlightLines?: number[];
}

/**
 * Minimal syntax tokenizer — covers keywords, strings, comments, types, functions.
 * No external dependency like Prism.js needed.
 */
function tokenize(code: string, language: string): { text: string; className: string }[][] {
  const lines = code.split("\n");

  // Language-specific keyword sets
  const csharpKeywords = new Set([
    "public",
    "private",
    "protected",
    "internal",
    "static",
    "class",
    "interface",
    "record",
    "struct",
    "enum",
    "namespace",
    "using",
    "var",
    "new",
    "return",
    "if",
    "else",
    "switch",
    "case",
    "break",
    "for",
    "foreach",
    "while",
    "do",
    "try",
    "catch",
    "finally",
    "throw",
    "async",
    "await",
    "void",
    "string",
    "int",
    "bool",
    "double",
    "float",
    "decimal",
    "long",
    "byte",
    "null",
    "true",
    "false",
    "readonly",
    "const",
    "override",
    "virtual",
    "abstract",
    "sealed",
    "partial",
    "this",
    "base",
    "typeof",
    "is",
    "as",
    "in",
    "out",
    "ref",
    "where",
    "get",
    "set",
    "value",
    "yield",
    "default",
    "object",
    "Task",
    "List",
    "Dictionary",
  ]);
  const tsKeywords = new Set([
    "import",
    "export",
    "from",
    "const",
    "let",
    "var",
    "function",
    "return",
    "if",
    "else",
    "for",
    "while",
    "do",
    "switch",
    "case",
    "break",
    "continue",
    "new",
    "this",
    "class",
    "extends",
    "implements",
    "interface",
    "type",
    "enum",
    "async",
    "await",
    "try",
    "catch",
    "finally",
    "throw",
    "typeof",
    "instanceof",
    "in",
    "of",
    "null",
    "undefined",
    "true",
    "false",
    "void",
    "never",
    "any",
    "string",
    "number",
    "boolean",
    "readonly",
    "abstract",
    "static",
    "public",
    "private",
    "protected",
    "default",
    "as",
    "is",
    "keyof",
    "infer",
    "satisfies",
  ]);
  const sqlKeywords = new Set([
    "SELECT",
    "FROM",
    "WHERE",
    "INSERT",
    "INTO",
    "VALUES",
    "UPDATE",
    "SET",
    "DELETE",
    "CREATE",
    "TABLE",
    "ALTER",
    "DROP",
    "INDEX",
    "JOIN",
    "LEFT",
    "RIGHT",
    "INNER",
    "OUTER",
    "ON",
    "AND",
    "OR",
    "NOT",
    "NULL",
    "PRIMARY",
    "KEY",
    "FOREIGN",
    "REFERENCES",
    "UNIQUE",
    "DEFAULT",
    "ORDER",
    "BY",
    "GROUP",
    "HAVING",
    "LIMIT",
    "OFFSET",
    "AS",
    "DISTINCT",
    "COUNT",
    "SUM",
    "AVG",
    "MAX",
    "MIN",
    "LIKE",
    "IN",
    "BETWEEN",
    "EXISTS",
    "CASE",
    "WHEN",
    "THEN",
    "ELSE",
    "END",
    "IS",
    "INT",
    "VARCHAR",
    "TEXT",
    "BOOLEAN",
    "DATETIME",
    "NVARCHAR",
    "BIT",
    "IDENTITY",
    "CONSTRAINT",
    "CASCADE",
    "GO",
    "EXEC",
    "DECLARE",
  ]);

  const lang = language.toLowerCase();
  let keywords: Set<string>;
  let commentStart: string;
  let multiCommentStart: string;
  let multiCommentEnd: string;

  if (lang === "csharp" || lang === "cs" || lang === "c#") {
    keywords = csharpKeywords;
    commentStart = "//";
    multiCommentStart = "/*";
    multiCommentEnd = "*/";
  } else if (lang === "sql") {
    keywords = sqlKeywords;
    commentStart = "--";
    multiCommentStart = "/*";
    multiCommentEnd = "*/";
  } else {
    keywords = tsKeywords;
    commentStart = "//";
    multiCommentStart = "/*";
    multiCommentEnd = "*/";
  }

  return lines.map((line) => {
    const tokens: { text: string; className: string }[] = [];
    let i = 0;

    while (i < line.length) {
      // Comments
      if (line.slice(i).startsWith(commentStart)) {
        tokens.push({ text: line.slice(i), className: "token-comment" });
        break;
      }

      // Strings (double quote)
      if (line[i] === '"' || line[i] === "'") {
        const quote = line[i];
        let end = i + 1;
        while (end < line.length && line[end] !== quote) {
          if (line[end] === "\\") end++;
          end++;
        }
        end = Math.min(end + 1, line.length);
        tokens.push({ text: line.slice(i, end), className: "token-string" });
        i = end;
        continue;
      }

      // Template literals
      if (line[i] === "`") {
        let end = i + 1;
        while (end < line.length && line[end] !== "`") {
          if (line[end] === "\\") end++;
          end++;
        }
        end = Math.min(end + 1, line.length);
        tokens.push({ text: line.slice(i, end), className: "token-string" });
        i = end;
        continue;
      }

      // Decorators / Attributes
      if (line[i] === "@" || (line[i] === "[" && /^[A-Z]/.test(line[i + 1] || ""))) {
        let end = i + 1;
        while (end < line.length && /[\w.]/.test(line[end])) end++;
        if (line[end] === "]") end++;
        tokens.push({ text: line.slice(i, end), className: "token-decorator" });
        i = end;
        continue;
      }

      // Numbers
      if (/[0-9]/.test(line[i]) && (i === 0 || !/[\w]/.test(line[i - 1]))) {
        let end = i;
        while (end < line.length && /[0-9.]/.test(line[end])) end++;
        tokens.push({ text: line.slice(i, end), className: "token-number" });
        i = end;
        continue;
      }

      // Words
      if (/[a-zA-Z_$]/.test(line[i])) {
        let end = i;
        while (end < line.length && /[\w$]/.test(line[end])) end++;
        const word = line.slice(i, end);

        if (keywords.has(word)) {
          tokens.push({ text: word, className: "token-keyword" });
        } else if (/^[A-Z]/.test(word) && word.length > 1) {
          tokens.push({ text: word, className: "token-type" });
        } else if (line[end] === "(") {
          tokens.push({ text: word, className: "token-function" });
        } else {
          tokens.push({ text: word, className: "" });
        }
        i = end;
        continue;
      }

      // Operators
      if (/[+\-*/%=<>!&|^~?:]/.test(line[i])) {
        let end = i + 1;
        while (end < line.length && /[+\-*/%=<>!&|^~?:]/.test(line[end])) end++;
        tokens.push({ text: line.slice(i, end), className: "token-operator" });
        i = end;
        continue;
      }

      // Punctuation
      if (/[{}()[\],;.]/.test(line[i])) {
        tokens.push({ text: line[i], className: "token-punctuation" });
        i++;
        continue;
      }

      // Whitespace and other chars
      tokens.push({ text: line[i], className: "" });
      i++;
    }

    return tokens;
  });
}

/**
 * Presentation UI component rendering the code block.
 * Arranges layout boundaries and accessibility targets (WCAG, tab index) using the core design library (@core/ui/*).
 */
const LANG_LABELS: Record<string, string> = {
  csharp: "C#",
  cs: "C#",
  "c#": "C#",
  typescript: "TypeScript",
  ts: "TypeScript",
  javascript: "JavaScript",
  js: "JavaScript",
  jsx: "JSX",
  tsx: "TSX",
  json: "JSON",
  http: "HTTP",
  sql: "SQL",
  bash: "Shell",
  shell: "Shell",
  sh: "Shell",
  yaml: "YAML",
  yml: "YAML",
  xml: "XML",
  html: "HTML",
  css: "CSS",
  text: "Text",
  plaintext: "Text",
};

export function CodeBlock({ code, language, filename, highlightLines }: CodeBlockProps) {
  const { t } = useDocsI18n();
  const [copied, setCopied] = useState(false);

  const handleCopy = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(code);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      // fallback
    }
  }, [code]);

  const langLabel = LANG_LABELS[language?.toLowerCase() ?? ""] ?? language ?? "Code";
  const tokenizedLines = tokenize(code.trim(), language);
  const highlightSet = new Set(highlightLines || []);

  const sampleName = filename ? `${langLabel} — ${filename}` : langLabel;

  return (
    <div className="docs-code-block">
      <div className="docs-code-header">
        <div style={{ display: "flex", alignItems: "center", gap: "0.75rem" }}>
          {filename && <span className="docs-code-filename">{filename}</span>}
          <span className="docs-code-lang">{langLabel}</span>
        </div>
        <button
          type="button"
          className="docs-code-copy"
          data-copied={copied}
          onClick={handleCopy}
          aria-label={t("common.copyCodeSample", { sample: sampleName })}
        >
          {copied ? (
            <>
              <svg
                width="12"
                height="12"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                aria-hidden="true"
              >
                <polyline points="20 6 9 17 4 12" />
              </svg>
              {t("common.codeCopied")}
            </>
          ) : (
            <>
              <svg
                width="12"
                height="12"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                aria-hidden="true"
              >
                <rect width="14" height="14" x="8" y="8" rx="2" ry="2" />
                <path d="M4 16c-1.1 0-2-.9-2-2V4c0-1.1.9-2 2-2h10c1.1 0 2 .9 2 2" />
              </svg>
              {t("common.copyCode")}
            </>
          )}
        </button>
      </div>
      {/* A horizontally scrollable region must be reachable by keyboard, or a
          long line is simply unreadable without a mouse. */}
      <pre className="docs-code-pre" tabIndex={0} role="region" aria-label={sampleName}>
        <code>
          {tokenizedLines.map((lineTokens, lineIdx) => {
            const isHighlighted = highlightSet.has(lineIdx + 1);
            const lineContent = lineTokens.map((token, tokIdx) => (
              <span key={tokIdx} className={token.className || undefined}>
                {token.text}
              </span>
            ));

            return (
              <span
                key={lineIdx}
                className={isHighlighted ? "docs-code-line-highlight" : undefined}
              >
                {lineContent}
                {lineIdx < tokenizedLines.length - 1 ? "\n" : ""}
              </span>
            );
          })}
        </code>
      </pre>
    </div>
  );
}

"use client";

/**
 * DocsI18nProvider — Isolated i18n context for the documentation portal.
 *
 * Architecture (v2 — Zero-Flash Eager Loading):
 * 1. ALL docs translations are eagerly loaded via docs-registry.ts.
 *    They're merged into the registry so translations are available
 *    on the VERY FIRST render — zero flash, zero useEffect race conditions.
 * 2. loadSection() is a harmless no-op kept for backward compatibility.
 * 3. All 7 language dictionaries are available synchronously at import time,
 *    enabling instant language switching with zero network requests.
 *
 * Supports 7 languages: en, ar, fr, ru, zh, es, de
 */

import type React from "react";
import { createContext, useContext, useState, useEffect, useCallback, useMemo } from "react";
import {
  allDocsEn,
  allDocsAr,
  allDocsFr,
  allDocsRu,
  allDocsZh,
  allDocsEs,
  allDocsDe,
} from "../../locales/docs-registry";

// ─── Types ─────────────────────────────────────────────────────
/**
 * Exported type defining parameters and fields for doc language configurations.
 */
export type DocLanguage = "en" | "ar" | "fr" | "ru" | "zh" | "es" | "de";
/**
 * Exported type defining parameters and fields for doc direction configurations.
 */
export type DocDirection = "ltr" | "rtl";
/**
 * Exported type defining parameters and fields for doc scope configurations.
 */
export type DocScope = "technical" | "commercial";

/**
 * Interface defining property specifications, keys types, and structural contract rules for doc language info.
 */
export interface DocLanguageInfo {
  code: DocLanguage;
  label: string;
  nativeLabel: string;
  direction: DocDirection;
}

/**
 * Exported constant defining parameters and fields for d o c_ l a n g u a g e s configurations.
 */
export const DOC_LANGUAGES: DocLanguageInfo[] = [
  { code: "en", label: "English", nativeLabel: "English", direction: "ltr" },
  { code: "ar", label: "Arabic", nativeLabel: "العربية", direction: "rtl" },
  { code: "fr", label: "French", nativeLabel: "Français", direction: "ltr" },
  { code: "ru", label: "Russian", nativeLabel: "Русский", direction: "ltr" },
  { code: "zh", label: "Chinese", nativeLabel: "中文", direction: "ltr" },
  { code: "es", label: "Spanish", nativeLabel: "Español", direction: "ltr" },
  { code: "de", label: "German", nativeLabel: "Deutsch", direction: "ltr" },
];

// ─── EAGER REGISTRY — All translations available at import time ──
const globalRegistry: Record<DocLanguage, Record<string, unknown>> = {
  en: allDocsEn,
  ar: allDocsAr,
  fr: allDocsFr,
  ru: allDocsRu,
  zh: allDocsZh,
  es: allDocsEs,
  de: allDocsDe,
};

const DOCS_LANG_KEY = "docs-language";

// ─── Context ───────────────────────────────────────────────────
interface DocsI18nContextType {
  language: DocLanguage;
  direction: DocDirection;
  setLanguage: (lang: DocLanguage) => void;
  t: (key: string, params?: Record<string, unknown>) => string;
  languages: DocLanguageInfo[];
  currentLanguageInfo: DocLanguageInfo;
  /** @deprecated No longer needed — all translations are eagerly loaded. */
  loadSection: (slug: string) => void;
}

const DocsI18nContext = createContext<DocsI18nContextType | undefined>(undefined);

// ─── Provider ──────────────────────────────────────────────────
/**
 * Presentation UI component rendering the docs i18n provider.
 * Arranges layout boundaries and accessibility targets (WCAG, tab index) using the core design library (@core/ui/*).
 */
export function DocsI18nProvider({
  children,
  scope = "technical",
}: {
  children: React.ReactNode;
  scope?: DocScope;
}) {
  const [language, setLanguageState] = useState<DocLanguage>("en");

  const currentLanguageInfo = useMemo(
    () => DOC_LANGUAGES.find((l) => l.code === language) ?? DOC_LANGUAGES[0],
    [language]
  );

  const direction = currentLanguageInfo.direction;

  // ── loadSection is now a no-op (backward compat) ─────────────
  const loadSection = useCallback((_slug: string) => {}, []);

  // ── Translation function ─────────────────────────────────────
  const t = useCallback(
    (key: string, params?: Record<string, unknown>): string => {
      const keys = key.split(".");

      // Lookup chain: current language → English fallback
      const sources: Record<string, unknown>[] = [];
      if (language !== "en") sources.push(globalRegistry[language]);
      sources.push(globalRegistry.en);

      for (const source of sources) {
        let value: unknown = source;
        let found = true;

        for (const k of keys) {
          if (value && typeof value === "object" && k in value) {
            value = value[k];
          } else {
            found = false;
            break;
          }
        }

        if (found && typeof value === "string") {
          if (params) {
            return value.replace(/\{\{(\w+)\}\}/g, (match, paramKey) =>
              params[paramKey] !== undefined ? String(params[paramKey]) : match
            );
          }
          return value;
        }
      }

      return key;
    },
    [language]
  );

  const setLanguage = useCallback((lang: DocLanguage) => {
    setLanguageState(lang);
    try {
      localStorage.setItem(DOCS_LANG_KEY, lang);
    } catch {
      /* noop */
    }
  }, []);

  // Hydrate language preference from localStorage (after mount — client side only)
  useEffect(() => {
    try {
      const saved = localStorage.getItem(DOCS_LANG_KEY) as DocLanguage | null;
      if (saved && DOC_LANGUAGES.some((l) => l.code === saved)) {
        queueMicrotask(() => {
          setLanguageState(saved);
        });
      }
    } catch {
      /* noop */
    }
  }, []);

  // ── Document direction / language / font class ───────────────
  // Mirrors the app-wide i18n provider, which owns the same three DOM
  // side-effects. The docs portal renders inside that provider, so both write
  // <html dir/lang> and the body font class. Every write below is skipped when
  // the DOM already carries the target value: two unconditional writers race on
  // hydration and produce either a mismatch warning or a visible flash.
  useEffect(() => {
    if (document.documentElement.dir !== direction) {
      document.documentElement.dir = direction;
    }
    if (document.documentElement.lang !== language) {
      document.documentElement.lang = language;
    }

    const fontClass = direction === "rtl" ? "font-arabic" : "font-english";
    const staleFontClass = direction === "rtl" ? "font-english" : "font-arabic";
    const bodyClasses = document.body.classList;
    if (!bodyClasses.contains(fontClass)) {
      bodyClasses.add(fontClass);
    }
    if (bodyClasses.contains(staleFontClass)) {
      bodyClasses.remove(staleFontClass);
    }
  }, [direction, language]);

  const contextValue = useMemo(
    () => ({
      language,
      direction,
      setLanguage,
      t,
      languages: DOC_LANGUAGES,
      currentLanguageInfo,
      loadSection,
    }),
    [language, direction, setLanguage, t, currentLanguageInfo, loadSection]
  );

  // Note: isHydrated is only used to restore the saved language from localStorage.
  // Since all translations are eagerly loaded (zero-flash), we do NOT block rendering.
  // The language preference is applied after mount — first render always uses "en"
  // which immediately switches to the stored preference without unknown visible flash.

  return <DocsI18nContext.Provider value={contextValue}>{children}</DocsI18nContext.Provider>;
}

// ─── Hook ──────────────────────────────────────────────────────
/**
 * React hook/ViewModel orchestrating state and data flows for docs i18n.
 * Handles active states updates, form fields validations, and browser navigation controllers.
 */
export function useDocsI18n(): DocsI18nContextType {
  const context = useContext(DocsI18nContext);
  if (context === undefined) {
    return {
      language: "en",
      direction: "ltr",
      setLanguage: () => {},
      t: (key: string) => key,
      languages: DOC_LANGUAGES,
      currentLanguageInfo: DOC_LANGUAGES[0],
      loadSection: () => {},
    };
  }
  return context;
}

"use client";

import React from "react";
import { Globe } from "lucide-react";
import { useI18n } from "@core/providers/i18n-provider";
import {
  PlatformActivityMapProps,
  RegionNodeInfo,
  EnrichedCountryData,
  useMapPanZoom,
  useMapData,
  MapSvgCanvas,
  MapControls,
  MapTooltip,
  MapRegionalSidebar,
} from "./activity-map";

export type { RegionNodeInfo, EnrichedCountryData, PlatformActivityMapProps };

export function PlatformActivityMap({
  summary,
  loginActivity,
  recentActivity = [],
  healthVm,
  regionNodes = [],
  isLoading = false,
}: PlatformActivityMapProps) {
  const { t } = useI18n();

  const { enrichedCountries, activeCountries, sortedCountries, countryStyles } =
    useMapData(regionNodes, summary, recentActivity);

  const {
    vb,
    mapStageRef,
    svgRef,
    isDraggingRef,
    hasDraggedRef,
    selectedCountry,
    hoveredCountry,
    setHoveredCountry,
    resetMap,
    zoomAt,
    handleCountrySelect,
    handlePointerDown,
