          <span className="flex items-center gap-1.5">
            <span className="h-2 w-2 rounded-full bg-slate-500 opacity-60" />
            <span className="hidden sm:inline">{t("platformCommandCenter.activity.legendLowActivity") || "Low Activity"}</span>
