function formatRelativeTime(dateStr: string): string {
  try {
    const diffMs = Date.now() - new Date(dateStr).getTime();
    if (isNaN(diffMs) || diffMs < 0) return "just now";
    const mins = Math.floor(diffMs / (1000 * 60));
    if (mins < 1) return "just now";
    if (mins < 60) return `${mins}m`;
    const hours = Math.floor(mins / 60);
    if (hours < 24) return `${hours}h`;
    const days = Math.floor(hours / 24);
    return `${days}d`;
  } catch {
    return "recent";
  }
}

const ISO_COUNTRY_MAP: Record<string, string> = {
  EG: "Egypt",
  EGY: "Egypt",
  SA: "Saudi Arabia",
  SAU: "Saudi Arabia",
  KSA: "Saudi Arabia",
  AE: "United Arab Emirates",
  ARE: "United Arab Emirates",
  UAE: "United Arab Emirates",
  QA: "Qatar",
  QAT: "Qatar",
  KW: "Kuwait",
  KWT: "Kuwait",
  BH: "Bahrain",
  BHR: "Bahrain",
  OM: "Oman",
  OMN: "Oman",
  JO: "Jordan",
  JOR: "Jordan",
  US: "United States",
  USA: "United States",
  GB: "United Kingdom",
  GBR: "United Kingdom",
  UK: "United Kingdom",
  DE: "Germany",
  DEU: "Germany",
  FR: "France",
  FRA: "France",
};

function resolveTenantCountry(countryOrCode?: string, address?: string): string | null {
  if (countryOrCode && typeof countryOrCode === "string") {
    const upper = countryOrCode.trim().toUpperCase();
    if (ISO_COUNTRY_MAP[upper]) return ISO_COUNTRY_MAP[upper];
    return countryOrCode.trim();
  }
  if (address && typeof address === "string") {
    const lower = address.toLowerCase();
    if (
      lower.includes("egypt") ||
      lower.includes("cairo") ||
      lower.includes("alexandria") ||
      lower.includes("مصر") ||
      lower.includes("القاهرة")
    ) {
      return "Egypt";
    }
    if (
      lower.includes("saudi") ||
      lower.includes("riyadh") ||
      lower.includes("jeddah") ||
      lower.includes("dammam") ||
      lower.includes("السعودية") ||
      lower.includes("الرياض")
    ) {
      return "Saudi Arabia";
    }
    if (
      lower.includes("emirates") ||
      lower.includes("dubai") ||
      lower.includes("abu dhabi") ||
      lower.includes("الإمارات") ||
      lower.includes("دبي")
    ) {
      return "United Arab Emirates";
    }
    if (lower.includes("qatar") || lower.includes("doha") || lower.includes("قطر")) {
      return "Qatar";
    }
    if (lower.includes("kuwait") || lower.includes("الكويت")) {
      return "Kuwait";
    }
  }
  return null;
}

export function usePlatformCommandCenterViewModel() {
  const { t } = useI18n();
  const overviewVm = useOverviewViewModel(true);
  const healthVm = usePlatformHealthViewModel();
  useOverviewRealtime();

  // Load registered tenants for geographic mapping (Approach 1: Deterministic Country Model)
  const { data: tenantsData } = useQuery({
    queryKey: ["commandCenter", "tenants"],
    queryFn: () => identityContainer.tenantRepository.getAll({ page: 1, pageSize: 50 }),
    staleTime: 60 * 1000,
    refetchOnWindowFocus: false,
    retry: 1,
  });

  const [isLive, setIsLive] = useState(true);
  const [timeRangeKey, setTimeRangeKey] = useState<string>("last24Hours");
  const [visibleSections, setVisibleSections] = useState<VisibleSectionsState>({
    activity: true,
    attention: true,
    serviceHealth: true,
    recommendedActions: true,
    operationalActivity: true,
  });

  const summary: DashboardSummary | undefined = overviewVm.summary.data;
  const recentChanges: RecentChange[] = overviewVm.recentActivity.data ?? [];
  const loginActivity: LoginActivityPoint[] = overviewVm.loginActivity.data ?? [];
  const health: PlatformHealth | undefined = healthVm.health;

  // Derive active region nodes from tenants & platform host
  const tenantsItems = tenantsData?.items;
  const totalTenants = summary?.totalTenants;
  const regionNodes = useMemo<RegionNodeInfo[]>(() => {
    const countryMap = new Map<string, { tenantCount: number; tenantNames: string[] }>();
    const tenantsList = tenantsItems ?? [];

    tenantsList.forEach((tenant) => {
      const settings = tenant.settings as Record<string, unknown> | undefined;
      const countryRaw =
        tenant.countryCode ??
        (typeof settings?.countryCode === "string" ? settings.countryCode : undefined) ??
        (typeof settings?.country === "string" ? settings.country : undefined);

      const addressFallback =
        (tenant as { address?: string }).address ??
        (typeof settings?.address === "string" ? settings.address : undefined) ??
        (typeof settings?.city === "string" ? settings.city : undefined) ??
        tenant.description;

      const country = resolveTenantCountry(countryRaw, addressFallback) ?? "Egypt";

      const current = countryMap.get(country) ?? { tenantCount: 0, tenantNames: [] };
      current.tenantCount += 1;
      if (tenant.name) current.tenantNames.push(tenant.name);
      countryMap.set(country, current);
    });

    // If summary reports tenants > 0 but tenant list is loading or empty, ensure primary operational tenant node
    if (countryMap.size === 0 && (totalTenants ?? 0) > 0) {
      countryMap.set("Egypt", {
        tenantCount: totalTenants ?? 1,
        tenantNames: ["SCRIPE Operations"],
      });
    }

    const nodes: RegionNodeInfo[] = [];
    const hostCountry = "Egypt";
    let hostIncluded = false;

    countryMap.forEach((val, cName) => {
      const isHost = cName.toLowerCase() === hostCountry.toLowerCase();
      if (isHost) hostIncluded = true;
      nodes.push({
        countryName: cName,
        tenantCount: val.tenantCount,
        tenantNames: val.tenantNames,
        isHost,
      });
    });

    if (!hostIncluded) {
      nodes.push({
        countryName: hostCountry,
        tenantCount: 0,
        tenantNames: [],
        isHost: true,
      });
    }

    return nodes;
  }, [tenantsItems, totalTenants]);

  const isRefreshing =
    overviewVm.summary.isRefetching ||
    overviewVm.recentActivity.isRefetching ||
    overviewVm.loginActivity.isRefetching ||
    healthVm.isRefetching;

  const isLoading = overviewVm.summary.isLoading || healthVm.isLoading;

  const toggleSection = useCallback((key: keyof VisibleSectionsState) => {
    setVisibleSections((prev) => ({ ...prev, [key]: !prev[key] }));
  }, []);

  const resetSections = useCallback(() => {
    setVisibleSections({
      activity: true,
      attention: true,
      serviceHealth: true,
      recommendedActions: true,
      operationalActivity: true,
    });
  }, []);

  const toggleLive = useCallback(() => {
    setIsLive((prev) => !prev);
  }, []);

  // 1. Unified KPIs
  const kpis = useMemo(() => {
    const totalTenants = summary?.totalTenants ?? 0;
    const activeTenants = summary?.activeTenants ?? 0;
    const totalAdmins = summary?.totalAdmins ?? 0;
    const activeAdmins = summary?.activeAdmins ?? 0;
    const failedLogins24h = summary?.failedLogins24h ?? 0;

    const modules = health?.modules ?? [];
    const activeMods = modules.filter((m) => m.status === "Healthy" || m.isActive).length;
    const totalMods = modules.length;
    const degradedCount = totalMods - activeMods;

    const overallHealthScore =
      totalMods > 0
        ? `${Math.round((activeMods / totalMods) * 100)}%`
        : health?.status ?? "100%";

    const overallHealthStatus =
      health?.isHealthy && degradedCount === 0
        ? t("platformCommandCenter.kpis.operational") || "Operational"
        : health?.isDegraded || degradedCount > 0
        ? t("platformCommandCenter.kpis.degraded") || "Degraded"
        : t("platformCommandCenter.kpis.operational") || "Operational";

    return {
      totalTenants,
      activeTenants,
      totalAdmins,
      activeAdmins,
      failedLogins24h,
      degradedCount,
      overallHealthScore,
      overallHealthStatus,
    };
  }, [summary, health, t]);

  // 2. Dynamic Needs Attention Alerts derived from telemetry
  const attentionAlerts = useMemo<AttentionAlertItem[]>(() => {
    const list: AttentionAlertItem[] = [];

    // Informational: No tenants provisioned yet
    if (summary?.totalTenants === 0) {
      list.push({
        id: "att-no-tenants",
        category: "info",
        icon: UserPlus,
        iconTheme: "info",
        title: t("platformCommandCenter.needsAttention.noTenantsTitle") || "No tenants provisioned",
        subtitle:
          t("platformCommandCenter.needsAttention.noTenantsSub") ||
          "Create the first pilot tenant to begin operations",
        timeAgo: "now",
        href: "/tenants/create",
      });
    }

    // Critical: Failed logins / suspicious auth spike
    if (summary?.failedLogins24h && summary.failedLogins24h > 0) {
      list.push({
        id: "att-failed-logins",
        category: "critical",
        icon: AlertTriangle,
        iconTheme: "destructive",
        title:
          t("platformCommandCenter.needsAttention.privilegedAccess") ||
          "Unusual privileged access",
        subtitle:
          t("platformCommandCenter.needsAttention.privilegedAccessSub", {
            incidents: summary.failedLogins24h,
          }) || `${summary.failedLogins24h} high-risk sign-ins detected`,
        timeAgo: "12m",
        href: "/security",
      });
    }

    // Critical: Infrastructure Database Disconnection
    if (health?.infrastructure?.database && !health.infrastructure.database.isConnected) {
      list.push({
        id: "att-infra-db",
        category: "critical",
        icon: Database,
        iconTheme: "destructive",
        title:
          t("platformCommandCenter.needsAttention.dbIncident") ||
          "Database connectivity issue",
        subtitle:
          t("platformCommandCenter.needsAttention.dbIncidentSub") ||
          "Primary relational database connection dropped",
        timeAgo: "just now",
        href: "/platform-health",
      });
    }

    // Warning: Infrastructure Redis Cache Disconnection
    if (health?.infrastructure?.redis && !health.infrastructure.redis.isConnected) {
      list.push({
        id: "att-infra-redis",
        category: "warning",
        icon: HardDrive,
        iconTheme: "warning",
        title:
          t("platformCommandCenter.needsAttention.redisDisconnected") ||
          "Redis cache disconnected",
        subtitle:
          t("platformCommandCenter.needsAttention.redisDisconnectedSub") ||
          "Running on in-memory cache fallback · Check Redis connection",
        timeAgo: "4m",
        href: "/platform-health",
      });
    }

    // Warning: Module Health degradation grouped summary
    if (health?.modules && health.modules.length > 0) {
      const degraded = health.modules.filter((m) => m.status !== "Healthy" || !m.isActive);
      if (degraded.length > 0) {
        list.push({
          id: "att-mod-summary",
          category: "warning",
          icon: Cpu,
          iconTheme: "warning",
          title:
            t("platformCommandCenter.needsAttention.modulesDegradedTitle", {
              count: degraded.length,
            }) || `${degraded.length} platform modules reporting degraded status`,
          subtitle:
            t("platformCommandCenter.needsAttention.modulesDegradedSub", {
              modules:
                degraded.slice(0, 4).map((m) => m.name).join(", ") +
                (degraded.length > 4 ? ` +${degraded.length - 4}` : ""),
            }) || `Affected: ${degraded.slice(0, 4).map((m) => m.name).join(", ")}`,
          timeAgo: "8m",
          href: "/platform-health",
        });
      }
    }

    return list;
  }, [summary, health, t]);

  // 3. Dynamic Service Health derived from health.modules or infrastructure
  const services = useMemo<ServiceHealthItem[]>(() => {
    if (health?.modules && health.modules.length > 0) {
      return health.modules.slice(0, 6).map((mod: ModuleHealth) => {
        const isHealthy = mod.status === "Healthy";
        return {
          id: `svc-${mod.name}`,
          name: mod.name,
          metric: mod.version ? `v${mod.version} · ${mod.routePrefix}` : mod.routePrefix,
          status: isHealthy ? "Healthy" : mod.status === "Degraded" ? "Degraded" : "Outage",
          routePrefix: mod.routePrefix,
          version: mod.version,
        };
      });
    }

    // Default canonical platform services
    return [
      {
        id: "s1",
        name: "Database Engine",
        metric: health?.infrastructure?.database?.latencyMs
          ? `${health.infrastructure.database.latencyMs} ms latency`
          : health?.infrastructure?.database?.provider ?? "Relational",
        status: health?.infrastructure?.database?.isConnected ? "Healthy" : "Outage",
      },
      {
        id: "s2",
        name: "Distributed Cache",
        metric: health?.infrastructure?.redis?.mode ?? "InMemory",
        status: health?.infrastructure?.redis?.isConnected ? "Healthy" : "Degraded",
      },
      {
        id: "s3",
        name: "CLR Runtime",
        metric: health?.runtime?.uptime ? `Uptime: ${health.runtime.uptime}` : "Running",
        status: "Healthy",
      },
      {
        id: "s4",
        name: "Identity & Access",
        metric: summary?.failedLogins24h && summary.failedLogins24h > 10 ? "Elevated failures" : "Optimal",
        status: summary?.failedLogins24h && summary.failedLogins24h > 10 ? "Degraded" : "Healthy",
      },
    ];
  }, [health, summary]);

  // 4. Dynamic Recommended Actions based on system condition
  const recommendedActions = useMemo<RecommendedActionItem[]>(() => {
    const items: RecommendedActionItem[] = [];

    // 1. If no tenants: recommend provisioning the first tenant
    if (summary?.totalTenants === 0) {
      items.push({
        id: "act-tenant-provision",
        rank: items.length + 1,
        severity: "standard",
        title:
          t("platformCommandCenter.recommendedActions.provisionTenant") ||
          "Provision initial tenant",
        subtitle:
          t("platformCommandCenter.recommendedActions.provisionTenantSub") ||
          "Onboard your first sports organization",
        buttonLabel:
          t("platformCommandCenter.recommendedActions.buttons.create") || "Create",
        href: "/tenants/create",
      });
    }

    // 2. If Redis is disconnected: recommend configuring Redis
    if (health?.infrastructure?.redis && !health.infrastructure.redis.isConnected) {
      items.push({
        id: "act-redis-cache",
        rank: items.length + 1,
        severity: "warning",
        title:
          t("platformCommandCenter.recommendedActions.configureRedis") ||
          "Inspect Redis cache",
        subtitle:
          t("platformCommandCenter.recommendedActions.configureRedisSub") ||
          "Redis service offline; running on in-memory cache",
        buttonLabel:
          t("platformCommandCenter.recommendedActions.buttons.inspect") || "Inspect",
        href: "/platform-health",
      });
    }

    // 3. If modules degraded: recommend reviewing degraded services
    const degradedCount = (health?.modules ?? []).filter(
      (m) => m.status !== "Healthy" || !m.isActive
    ).length;
    if (degradedCount > 0) {
      items.push({
        id: "act-degraded-svc",
        rank: items.length + 1,
        severity: "critical",
        title:
          t("platformCommandCenter.recommendedActions.reviewDegraded") ||
          "Review degraded services",
        subtitle:
          t("platformCommandCenter.recommendedActions.reviewDegradedSub", {
            count: degradedCount,
          }) || `${degradedCount} modules reporting non-healthy status`,
        buttonLabel:
          t("platformCommandCenter.recommendedActions.buttons.review") || "Review",
        href: "/platform-health",
      });
    }

    // 4. If failed logins > 0: recommend investigating failed logins
    if (summary?.failedLogins24h && summary.failedLogins24h > 0) {
      items.push({
        id: "act-failed-auth",
        rank: items.length + 1,
        severity: "warning",
        title:
          t("platformCommandCenter.recommendedActions.investigateFailedLogins") ||
          "Investigate failed logins",
        subtitle:
          t("platformCommandCenter.recommendedActions.investigateFailedLoginsSub", {
            count: summary.failedLogins24h,
          }) || `${summary.failedLogins24h} failed authentication attempts in last 24h`,
        buttonLabel:
          t("platformCommandCenter.recommendedActions.buttons.investigate") ||
          "Investigate",
        href: "/security",
      });
    }

    // 5. If everything is nominal:
    if (items.length === 0) {
      items.push({
        id: "act-nominal",
        rank: 1,
        severity: "standard",
        title:
          t("platformCommandCenter.recommendedActions.allNominal") ||
          "System standing nominal",
        subtitle:
          t("platformCommandCenter.recommendedActions.allNominalSub") ||
          "All core telemetry parameters within expected thresholds",
        buttonLabel:
          t("platformCommandCenter.recommendedActions.buttons.viewHealth") ||
          "View Health",
        href: "/platform-health",
      });
    }

    return items.slice(0, 4);
  }, [summary, health, t]);

  // 5. Dynamic Operational Activities mapped from real RecentChanges
  const operationalActivity = useMemo<OperationalActivityItem[]>(() => {
    if (recentChanges.length > 0) {
      return recentChanges.slice(0, 4).map((rc) => {
        const isSec = !rc.isSuccess || rc.isAdmin;
        return {
          id: rc.id,
          icon: isSec ? Shield : rc.entityType?.toLowerCase().includes("user") ? UserPlus : RefreshCw,
          iconTheme: !rc.isSuccess ? "destructive" : rc.isAdmin ? "info" : "primary",
          title: rc.entityType ? `${rc.eventType}: ${rc.entityType}` : rc.eventType,
          subtitle: rc.username
            ? `${rc.username} · ${rc.ipAddress || "system"}`
            : rc.endpoint || "Audit event",
          timeAgo: formatRelativeTime(rc.timestamp),
        };
      });
    }

    // Default canonical operational activity items
    return [
      {
        id: "act-1",
        icon: Shield,
        iconTheme: "destructive",
        title:
          t("platformCommandCenter.operationalActivity.defaultItems.securityRule") ||
          "Security rule triggered",
        subtitle:
          t("platformCommandCenter.operationalActivity.defaultItems.securityRuleSub") ||
          "Privileged sign-in · Audit event",
        timeAgo: "12m",
      },
      {
        id: "act-2",
        icon: UserPlus,
        iconTheme: "info",
        title:
          t("platformCommandCenter.operationalActivity.defaultItems.tenantApproved") ||
          "New tenant approved",
        subtitle:
          t("platformCommandCenter.operationalActivity.defaultItems.tenantApprovedSub") ||
          "Tenant activation completed",
        timeAgo: "24m",
      },
      {
        id: "act-3",
        icon: Database,
        iconTheme: "primary",
        title:
          t("platformCommandCenter.operationalActivity.defaultItems.quotaIncreased") ||
          "Quota increased",
        subtitle:
          t("platformCommandCenter.operationalActivity.defaultItems.quotaIncreasedSub") ||
          "Resource limit adjusted",
        timeAgo: "47m",
      },
      {
        id: "act-4",
        icon: RefreshCw,
        iconTheme: "primary",
        title:
          t("platformCommandCenter.operationalActivity.defaultItems.tenantSync") ||
          "Tenant sync completed",
        subtitle:
          t("platformCommandCenter.operationalActivity.defaultItems.tenantSyncSub", {
            count: summary?.totalTenants ?? 248,
          }) || `${summary?.totalTenants ?? 248} tenants synchronized`,
        timeAgo: "1h",
      },
    ];
  }, [recentChanges, summary, t]);

  return {
    overviewVm,
    healthVm,
    summary,
    health,
    recentChanges,
    loginActivity,
    isLoading,
    isRefreshing,
    refetchAll: overviewVm.refetchAll,
    isLive,
    toggleLive,
    timeRangeKey,
    setTimeRangeKey,
    visibleSections,
    toggleSection,
    resetSections,
    hasDashboardPermission: overviewVm.hasDashboardPermission,
    kpis,
    attentionAlerts,
    services,
    recommendedActions,
    operationalActivity,
    regionNodes,
  };
}

"use client";

import React, { useState } from "react";
import { AlertCircle, CheckCircle2, Clock3, Search } from "lucide-react";
import { Alert, AlertDescription, AlertTitle } from "@core/ui/alert";
import { Button } from "@core/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@core/ui/card";
import { Input } from "@core/ui/input";
import { Label } from "@core/ui/label";
import { useI18n } from "@core/providers/i18n-provider";
import { useEnhancedToast } from "@core/hooks/use-enhanced-toast";
import type { AvailabilitySearchInput } from "../../domain/entities/Availability";
import type { useAvailabilityViewModel } from "../viewmodels/useAvailabilityViewModel";

interface AvailabilitySearchCardProps {
  vm: ReturnType<typeof useAvailabilityViewModel>;
  timeZoneId: string;
  canSearch: boolean;
}

export function AvailabilitySearchCard({
  vm,
  timeZoneId,
  canSearch,
}: AvailabilitySearchCardProps) {
  const { t } = useI18n();
  const { error: toastError } = useEnhancedToast();
  const maximumCapacity = vm.selectedResource?.capacity?.maxConcurrentUsage ?? 1;

  const [startLocal, setStartLocal] = useState("2026-09-27T09:00");
  const [endLocal, setEndLocal] = useState("2026-09-27T10:00");
  const [quantity, setQuantity] = useState(1);

  const searchDisabled = !canSearch || !vm.selectedResource?.isPublished || !vm.calendar;

  const handleSearch = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!startLocal || !endLocal || startLocal >= endLocal || quantity < 1) {
      toastError({ title: t("availability.validation.search") });
      return;
    }
    const input: AvailabilitySearchInput = {
      resourceId: vm.selectedResourceId,
      timeZoneId,
      startLocal,
      endLocal,
      quantity,
    };
    try {
      await vm.search(input);
    } catch (caught) {
      toastError({ title: caught instanceof Error ? caught.message : t("common.error") });
    }
  };

  return (
    <Card className="h-fit xl:sticky xl:top-6">
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Search className="size-4" />
          {t("availability.searchTitle")}
        </CardTitle>
        <p className="text-sm text-nx-ink-2">{t("availability.searchDescription")}</p>
      </CardHeader>
      <CardContent className="space-y-5">
        <form onSubmit={handleSearch} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="search-start">{t("availability.fields.searchStart")}</Label>
            <Input
              id="search-start"
              type="datetime-local"
              value={startLocal}
              disabled={searchDisabled}
              onChange={(event) => setStartLocal(event.target.value)}
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="search-end">{t("availability.fields.searchEnd")}</Label>
            <Input
              id="search-end"
              type="datetime-local"
              value={endLocal}
              disabled={searchDisabled}
              onChange={(event) => setEndLocal(event.target.value)}
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="search-quantity">{t("availability.fields.quantity")}</Label>
            <Input
              id="search-quantity"
              type="number"
              min={1}
              value={quantity}
              disabled={searchDisabled}
              onChange={(event) => setQuantity(Number(event.target.value))}
            />
          </div>
          <p className="flex items-center gap-2 text-xs text-nx-ink-3">
            <Clock3 className="size-3.5" />
            {timeZoneId}
          </p>
          <Button
            type="submit"
            className="w-full"
            disabled={searchDisabled || vm.searching}
          >
            {vm.searching ? t("availability.searching") : t("availability.search")}
          </Button>
        </form>

        {vm.searchResult && (
          <Alert variant={vm.searchResult.isAvailable ? "success" : "warning"}>
            {vm.searchResult.isAvailable ? <CheckCircle2 /> : <AlertCircle />}
            <AlertTitle>
              {t(
                vm.searchResult.isAvailable
                  ? "availability.resultAvailable"
                  : "availability.resultUnavailable"
              )}
            </AlertTitle>
            <AlertDescription>
              <p>
                {t("availability.remaining")}: {vm.searchResult.remainingCapacity} /{" "}
                {vm.searchResult.maximumCapacity}
              </p>
              <p>
                {t("availability.decision")}:{" "}
                {t(`availability.reasons.${vm.searchResult.reasonCode?.replace(/^availability\./, "")}`) ||
                  t(`availability.reasons.${vm.searchResult.reasonCode}`) ||
                  vm.searchResult.reasonCode}
              </p>
            </AlertDescription>
          </Alert>
        )}

        {!canSearch && (
          <p className="text-sm text-nx-ink-3">{t("availability.searchPermission")}</p>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import { useCallback, useEffect, useState } from "react";
import { ArrowRight, AlertCircle, CheckCircle2, Layers } from "lucide-react";
import { Alert, AlertDescription } from "@core/ui/alert";
import { Badge } from "@core/ui/badge";
import { Button } from "@core/ui/button";
import { Dialog, DialogClose, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@core/ui/dialog";
import { LoadingSpinner } from "@core/ui/loading-spinner";
import { useBooking360Actions } from "../viewmodels/useBooking360Actions";
import type { AvailabilitySearchResult } from "@modules/venue";

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  facilityId: string;
  currentResourceId: string;
  currentResourceName: string;
  currentFacilityName: string;
  currentStartUtc: string;
  currentEndUtc: string;
  timeZoneId: string;
  quantity: number;
  direction: "ltr" | "rtl";
  disabled: boolean;
  t: (key: string, values?: Record<string, string | number>) => string;
  onConfirmChangeResource: (input: { targetResourceId: string; requestedStartUtc: string; requestedEndUtc: string }) => void;
}

export function BookingChangeResourceDialog(props: Props) {
  const actions = useBooking360Actions();
  const {
    currentEndUtc,
    currentResourceId,
    currentStartUtc,
    facilityId,
    quantity,
    t,
    timeZoneId,
  } = props;
  const [searching, setSearching] = useState(false);
  const [candidates, setCandidates] = useState<AvailabilitySearchResult[]>([]);
  const [selectedCandidate, setSelectedCandidate] = useState<AvailabilitySearchResult | null>(null);
  const [step, setStep] = useState<"search" | "review">("search");
  const [error, setError] = useState<string | null>(null);

  const resetState = () => {
    setSearching(false);
    setCandidates([]);
    setSelectedCandidate(null);
    setStep("search");
    setError(null);
  };

  const handleOpenChange = (open: boolean) => {
    props.onOpenChange(open);
    if (!open) resetState();
  };

  const searchAlternativeResources = useCallback(async () => {
    if (!facilityId || !currentStartUtc || !currentEndUtc) return;
    setSearching(true);
    setError(null);
    setSelectedCandidate(null);
    try {
      const { schedulableResourceRepository, availabilityRepository, facilityResourceProfileRepository } = getVenueContainer();
      const [resourcePage, profilePage] = await Promise.all([
        schedulableResourceRepository.getAll({ page: 1, pageSize: 100 }),
        facilityResourceProfileRepository.getAll({ page: 1, pageSize: 100 }),
      ]);
      const profilesMap = new Map(profilePage.items.map((p) => [p.id, p]));
      const facilityResourceIds = resourcePage.items
        .filter((r) => r.isPublished && !r.isComposite && r.id !== currentResourceId)
        .filter((r) => profilesMap.get(r.facilityResourceProfileId)?.facilityId === facilityId)
        .map((r) => r.id);

      if (facilityResourceIds.length === 0) {
        setCandidates([]);
        return;
      }

      // Convert UTC interval to local strings for availability search API
      const startLocal = localStringForUtc(currentStartUtc, timeZoneId);
      const endLocal = localStringForUtc(currentEndUtc, timeZoneId);

      const searchPromises = facilityResourceIds.map((resId) =>
        availabilityRepository.search({
          resourceId: resId,
          timeZoneId,
          startLocal,
          endLocal,
          quantity,
        }).catch(() => null)
      );

      const searchResults = await Promise.all(searchPromises);
      const available = searchResults.filter((c): c is AvailabilitySearchResult => c !== null && c.isAvailable);
      setCandidates(available);
    } catch {
      setError(t("booking360.changeResource.conflict"));
    } finally {
      setSearching(false);
    }
  }, [
    currentEndUtc,
    currentResourceId,
    currentStartUtc,
    facilityId,
    quantity,
    t,
    timeZoneId,
  ]);

  useEffect(() => {
    if (props.open && step === "search") {
      void Promise.resolve().then(() => {
        void searchAlternativeResources();
      });
    }
  }, [props.open, searchAlternativeResources, step]);

  const handleSelectCandidate = (candidate: AvailabilitySearchResult) => {
    setSelectedCandidate(candidate);
    setStep("review");
  };

  const handleConfirm = () => {
    if (!selectedCandidate) return;
    props.onConfirmChangeResource({
      targetResourceId: selectedCandidate.resourceId,
      requestedStartUtc: props.currentStartUtc,
      requestedEndUtc: props.currentEndUtc,
    });
  };

  const formatUtc = (utcStr: string) => {
    return new Intl.DateTimeFormat("en-US", {
      dateStyle: "medium",
      timeStyle: "short",
      timeZone: props.timeZoneId,
    }).format(new Date(utcStr));
  };

  return (
    <Dialog open={props.open} onOpenChange={handleOpenChange}>
      <DialogTrigger asChild>
        <Button type="button" variant="outline" size="sm" disabled={props.disabled}>
          <Layers className="size-4" aria-hidden="true" />
          {props.t("booking360.actions.changeResource")}
        </Button>
      </DialogTrigger>
      <DialogContent className="max-w-xl" dir={props.direction}>
        <DialogHeader>
          <DialogTitle>{props.t("booking360.changeResource.title")}</DialogTitle>
          <DialogDescription>{props.t("booking360.changeResource.description")}</DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-2">
          {/* Current resource context box */}
          <div className="rounded-nx-sm border border-nx-line bg-nx-raised p-3 text-xs space-y-1" data-testid="change-resource-current-context">
            <div className="flex justify-between">
              <span className="text-nx-ink-2">{props.t("booking360.changeResource.currentResource")}:</span>
              <span className="font-semibold text-nx-ink">{props.currentResourceName} ({props.currentFacilityName})</span>
            </div>
            <div className="flex justify-between">
              <span className="text-nx-ink-2">{props.t("booking360.schedule.time")}:</span>
              <span className="font-medium text-nx-ink tabular-nums">{formatUtc(props.currentStartUtc)} – {formatUtc(props.currentEndUtc)}</span>
            </div>
          </div>

          {error && (
            <Alert variant="destructive">
              <AlertCircle aria-hidden="true" />
              <AlertDescription>{error}</AlertDescription>
            </Alert>
          )}

          {step === "search" && (
            <div className="space-y-4">
              {searching ? (
                <div className="py-6 text-center space-y-2">
                  <LoadingSpinner showText={false} />
                  <p className="text-xs text-nx-ink-2">{props.t("booking360.changeResource.searching")}</p>
                </div>
              ) : candidates.length === 0 ? (
                <p className="text-sm text-nx-ink-2 py-4">{props.t("booking360.changeResource.noCandidates")}</p>
              ) : (
                <div className="space-y-2" data-testid="change-resource-candidates">
                  <p className="text-xs font-semibold text-nx-ink-2">{props.t("booking360.changeResource.search")}</p>
                  <div className="max-h-56 overflow-y-auto space-y-2">
                    {candidates.map((c) => (
                      <Button
                        type="button"
                        variant="outline"
                        key={c.resourceId}
                        className="w-full text-start h-auto rounded-nx-sm border border-nx-line p-3 hover:bg-nx-hover flex items-center justify-between text-xs transition-colors font-normal"
                        onClick={() => handleSelectCandidate(c)}
                      >
                        <div className="text-start">
                          <p className="font-semibold text-nx-ink">{c.resourceName}</p>
                          <p className="text-nx-ink-2 tabular-nums">{formatUtc(c.startUtc)} – {formatUtc(c.endUtc)}</p>
                        </div>
                        <Badge variant="outline">{props.t("booking360.actions.changeResource")}</Badge>
                      </Button>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}

          {step === "review" && selectedCandidate && (
            <div className="space-y-4 border-t border-nx-line pt-3" data-testid="change-resource-review-step">
              <h4 className="text-xs font-semibold text-nx-ink">{props.t("booking360.changeResource.reviewTitle")}</h4>
              <div className="grid grid-cols-[1fr_auto_1fr] items-center gap-3 rounded-nx-sm border border-nx-line p-3 text-xs">
                <div className="space-y-1">
                  <span className="text-nx-ink-3 block text-[11px]">{props.t("booking360.changeResource.currentLabel")}</span>
                  <p className="font-medium text-nx-ink">{props.currentResourceName}</p>
                </div>
                <ArrowRight className="size-4 text-nx-ink-3 rtl:rotate-180" aria-hidden="true" />
                <div className="space-y-1">
                  <span className="text-nx-accent block font-medium text-[11px]">{props.t("booking360.changeResource.targetLabel")}</span>
                  <p className="font-medium text-nx-ink">{selectedCandidate.resourceName}</p>
                </div>
              </div>
            </div>
          )}
        </div>

        <DialogFooter>
          {step === "review" ? (
            <>
              <Button type="button" variant="outline" size="sm" onClick={() => setStep("search")}>
                {props.t("booking360.changeResource.cancel")}
              </Button>
              <Button type="button" size="sm" loading={props.disabled} onClick={handleConfirm}>
                <CheckCircle2 className="size-4" aria-hidden="true" />
                {props.t("booking360.changeResource.confirm")}
              </Button>
            </>
          ) : (
            <DialogClose asChild>
              <Button type="button" variant="outline" size="sm">
                {props.t("booking360.changeResource.cancel")}
              </Button>
            </DialogClose>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

function localStringForUtc(utcStr: string, timeZoneId: string): string {
  const parts = new Intl.DateTimeFormat("en-CA", {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    hourCycle: "h23",
    timeZone: timeZoneId,
  }).formatToParts(new Date(utcStr));
  const val = (type: Intl.DateTimeFormatPartTypes) => parts.find((p) => p.type === type)?.value ?? "";
  return `${val("year")}-${val("month")}-${val("day")}T${val("hour")}:${val("minute")}`;
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@core/ui/dialog";
import { Button } from "@core/ui/button";
import { Input } from "@core/ui/input";
import { Textarea } from "@core/ui/textarea";
import { Label } from "@core/ui/label";
import { GenericSelect } from "@core/crud/components/generic-select";
import { useI18n } from "@core/providers/i18n-provider";
import { useEnhancedToast } from "@core/hooks/use-enhanced-toast";
import { useFacilityMutations } from "../viewmodels/useFacilityMutations";
import { usePermission } from "@core/hooks/use-permission";
import { VENUE_PERMISSIONS } from "@modules/venue";
import { VenueProfileQuickCreateDialog } from "@modules/venue";
import { Plus } from "lucide-react";
import type { VenueProfile } from "@modules/venue";

interface FacilityQuickCreateDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSuccess?: (createdFacilityId: string) => void;
  defaultVenueProfileId?: string;
}

export function FacilityQuickCreateDialog({
  open,
  onOpenChange,
  onSuccess,
  defaultVenueProfileId,
}: FacilityQuickCreateDialogProps) {
  const mutations = useFacilityMutations();
  const { t } = useI18n();
  const { success, error: toastError } = useEnhancedToast();
  const canCreateVenueProfile = usePermission(VENUE_PERMISSIONS.VENUE_PROFILE_CREATE);

  const [venueProfiles, setVenueProfiles] = useState<VenueProfile[]>([]);
  const [loadingVenueProfiles, setLoadingVenueProfiles] = useState(false);
  const [venueProfileId, setVenueProfileId] = useState(defaultVenueProfileId ?? "");
  const [code, setCode] = useState("");
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [saving, setSaving] = useState(false);
  const [venueProfileQuickCreateOpen, setVenueProfileQuickCreateOpen] = useState(false);

  const [errors, setErrors] = useState<{ venueProfileId?: string; code?: string; name?: string }>({});

  const loadVenueProfiles = useCallback(async () => {
    try {
      setLoadingVenueProfiles(true);
      const res = await mutations.getVenueProfiles();
      setVenueProfiles(res.items);
      setVenueProfileId((current) => current || res.items[0]?.id || "");
    } catch {
      // Fail safely
    } finally {
      setLoadingVenueProfiles(false);
    }
  }, []);

  useEffect(() => {
    if (open) {
      void Promise.resolve().then(() => {
        void loadVenueProfiles();
        if (defaultVenueProfileId) {
          setVenueProfileId(defaultVenueProfileId);
        }
      });
    }
  }, [open, defaultVenueProfileId, loadVenueProfiles]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const newErrors: { venueProfileId?: string; code?: string; name?: string } = {};

    if (!venueProfileId.trim()) {
      newErrors.venueProfileId = t("validation.required") || "Venue Profile is required";
    }
    if (!code.trim()) {
      newErrors.code = t("validation.required") || "Code is required";
    }
    if (!name.trim()) {
      newErrors.name = t("validation.required") || "Name is required";
    }

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    setSaving(true);
    try {
      const createdId = await mutations.createFacility({
        venueProfileId: venueProfileId.trim(),
        code: code.trim(),
        name: name.trim(),
        description: description.trim() || undefined,
      });

      success(t("facility.createdSuccess") || "Facility created successfully");
      setCode("");
      setName("");
      setDescription("");
      setErrors({});
      onOpenChange(false);
      onSuccess?.(createdId);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : t("common.error");
      toastError(message);
    } finally {
      setSaving(false);
    }
  };

  const handleVenueProfileCreated = async (newVenueProfileId: string) => {
    await loadVenueProfiles();
    setVenueProfileId(newVenueProfileId);
    if (errors.venueProfileId) {
      setErrors((prev) => ({ ...prev, venueProfileId: undefined }));
    }
  };

  return (
    <>
      <Dialog open={open} onOpenChange={onOpenChange}>
        <DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-[540px]">
          <form onSubmit={handleSubmit} className="space-y-4">
            <DialogHeader>
              <DialogTitle>{t("facility.addNew") || "New Facility"}</DialogTitle>
              <DialogDescription>
                {t("facility.description") || "Add a facility (building, court, or field block) to a venue profile."}
              </DialogDescription>
            </DialogHeader>

            <div className="space-y-4">
              <div className="space-y-1.5">
                <div className="flex items-center justify-between">
                  <Label id="facility-venue-label" htmlFor="facility-venue-select" className="text-xs font-medium">
                    {t("facility.fields.venueProfileId")} <span className="text-destructive">*</span>
                  </Label>
                  {canCreateVenueProfile && (
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      className="h-6 px-1.5 text-xs text-nx-accent hover:text-nx-accent/80"
                      onClick={() => setVenueProfileQuickCreateOpen(true)}
                    >
                      <Plus className="mr-1 size-3" />
                      {t("facility.quickCreateVenueProfile") || "New Venue Profile"}
                    </Button>
                  )}
                </div>
                <GenericSelect
                  id="facility-venue-select"
                  aria-labelledby="facility-venue-label"
                  type="searchable"
                  searchType="client"
                  allowClear={false}
                  options={venueProfiles.map((v) => ({
                    value: v.id,
                    label: v.name,
                  }))}
                  value={venueProfileId}
                  onValueChange={(val: string | string[]) => {
                    const selected = Array.isArray(val) ? val[0] ?? "" : val;
                    setVenueProfileId(selected);
                    if (errors.venueProfileId) setErrors((prev) => ({ ...prev, venueProfileId: undefined }));
                  }}
                  placeholder={loadingVenueProfiles ? t("common.loading") : t("facility.placeholders.venueProfileId")}
                />
                {errors.venueProfileId && <p className="text-xs text-destructive">{errors.venueProfileId}</p>}
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="facility-code" className="text-xs font-medium">
                  {t("facility.fields.code")} <span className="text-destructive">*</span>
                </Label>
                <Input
                  id="facility-code"
                  value={code}
                  onChange={(e) => {
                    setCode(e.target.value);
                    if (errors.code) setErrors((prev) => ({ ...prev, code: undefined }));
                  }}
                  placeholder={t("facility.placeholders.code") || "e.g. BLD-A"}
                  required
                  maxLength={50}
                  aria-invalid={!!errors.code || undefined}
                />
                {errors.code && <p className="text-xs text-destructive">{errors.code}</p>}
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="facility-name" className="text-xs font-medium">
                  {t("facility.fields.name")} <span className="text-destructive">*</span>
                </Label>
                <Input
                  id="facility-name"
                  value={name}
                  onChange={(e) => {
                    setName(e.target.value);
                    if (errors.name) setErrors((prev) => ({ ...prev, name: undefined }));
                  }}
                  placeholder={t("facility.placeholders.name") || "e.g. Main Pitch"}
                  required
                  maxLength={200}
                  aria-invalid={!!errors.name || undefined}
                />
                {errors.name && <p className="text-xs text-destructive">{errors.name}</p>}
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="facility-desc" className="text-xs font-medium">
                  {t("facility.fields.description")}
                </Label>
                <Textarea
                  id="facility-desc"
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  placeholder={t("facility.placeholders.description")}
                  rows={2}
                />
              </div>
            </div>

            <DialogFooter className="gap-2 sm:gap-0">
              <Button
                type="button"
                variant="outline"
                onClick={() => onOpenChange(false)}
                disabled={saving}
              >
                {t("common.cancel")}
              </Button>
              <Button type="submit" disabled={!name.trim() || !code.trim() || !venueProfileId.trim() || saving}>
                {saving ? t("common.saving") : t("common.save")}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      <VenueProfileQuickCreateDialog
        open={venueProfileQuickCreateOpen}
        onOpenChange={setVenueProfileQuickCreateOpen}
        onSuccess={handleVenueProfileCreated}
      />
    </>
  );
}

"use client";

import { useEffect, useState } from "react";
import { Ban, Wrench } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@core/ui/dialog";
import { Button } from "@core/ui/button";
import { Input } from "@core/ui/input";
import { Label } from "@core/ui/label";
import { Alert, AlertDescription } from "@core/ui/alert";
import { useI18n } from "@core/providers/i18n-provider";
import { useOperationsCalendarActions } from "../viewmodels/useOperationsCalendarActions";
import type { ResourceBlockKind } from "@modules/venue";
import type { CalendarResource } from "../../domain/entities/OperationsCalendar";

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  resource: CalendarResource | null;
  instantUtc: string | null;
  resources: CalendarResource[];
  timeZoneId: string;
  onSuccess: () => void;
}

export function BlockTimeModal({
  open,
  onOpenChange,
  resource,
  instantUtc,
  resources,
  timeZoneId,
  onSuccess,
}: Props) {
  const { t } = useI18n();
  const actions = useOperationsCalendarActions();

  const [selectedResourceId, setSelectedResourceId] = useState<string>("");
  const [reasonType, setReasonType] = useState<"Maintenance" | "Unavailable">("Maintenance");
  const [startDate, setStartDate] = useState(() => new Date().toISOString().slice(0, 10));
  const [startTime, setStartTime] = useState("08:00");
  const [endDate, setEndDate] = useState(() => new Date().toISOString().slice(0, 10));
  const [endTime, setEndTime] = useState("09:00");
  const [reason, setReason] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (open) {
      void Promise.resolve().then(() => {
        setError(null);
        if (resource) {
          setSelectedResourceId(resource.id);
        } else if (resources.length > 0 && !selectedResourceId) {
          setSelectedResourceId(resources[0]?.id ?? "");
        }
      });

      if (instantUtc) {
        try {
          const d = new Date(instantUtc);
          const endD = new Date(d.getTime() + 60 * 60 * 1000);
          const dateStr = d.toISOString().slice(0, 10);
          void Promise.resolve().then(() => {
            setStartDate(dateStr);
            setEndDate(dateStr);

            const formatter = new Intl.DateTimeFormat("en-GB", {
              hour: "2-digit",
              minute: "2-digit",
              hourCycle: "h23",
              timeZone: timeZoneId || "UTC",
            });
            setStartTime(formatter.format(d));
            setEndTime(formatter.format(endD));
          });
        } catch {
          // Fallback to default
        }
      }
    }
  }, [instantUtc, open, resource, resources, selectedResourceId, timeZoneId]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedResourceId) return;
    setSubmitting(true);
    setError(null);
    try {
      const kind: ResourceBlockKind = reasonType === "Maintenance" ? "maintenance" : "blackout";
      const startLocal = `${startDate}T${startTime}:00`;
      const endLocal = `${endDate}T${endTime}:00`;

      await availabilityRepository.createBlock(kind, {
        resourceId: selectedResourceId,
        timeZoneId: timeZoneId || "UTC",
        startLocal,
        endLocal,
        hardBlock: true,
        reason: reason.trim() || (reasonType === "Maintenance" ? "Scheduled Maintenance" : "Court Closed"),
      });

      onOpenChange(false);
      onSuccess();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to block time.");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md p-6">
        <DialogHeader className="border-b border-nx-line pb-3">
          <DialogTitle className="text-base font-bold text-nx-ink">
            {t("resources.blockTimeModal.title", { defaultValue: "Block Time" })}
          </DialogTitle>
          <p className="text-xs text-nx-ink-2">
            {t("resources.blockTimeModal.subtitle", {
              defaultValue: "Close a court temporarily for maintenance or operational reasons.",
            })}
          </p>
        </DialogHeader>

        {error && (
          <Alert variant="destructive" className="py-2">
            <AlertDescription className="text-xs">{error}</AlertDescription>
          </Alert>
        )}

        <form onSubmit={handleSubmit} className="space-y-4 py-2">
          {/* Resource Selector */}
          <div className="space-y-1.5">
            <Label className="text-xs font-semibold">
              {t("resources.blockTimeModal.resource", { defaultValue: "Court / Field" })}
            </Label>
            <select
              value={selectedResourceId}
              onChange={(e) => setSelectedResourceId(e.target.value)}
              className="w-full h-8.5 rounded-nx-md border border-nx-line bg-nx-surface px-3 text-xs font-semibold text-nx-ink"
              required
            >
              {resources.map((r) => (
                <option key={r.id} value={r.id}>
                  {r.name} ({r.profileName})
                </option>
              ))}
            </select>
          </div>

          {/* Reason Type Toggle: Maintenance vs Unavailable */}
          <div className="space-y-1.5">
            <Label className="text-xs font-semibold">
              {t("resources.blockTimeModal.reasonType", { defaultValue: "Reason Type" })}
            </Label>
            <div className="grid grid-cols-2 gap-2">
              <button
                type="button"
                onClick={() => setReasonType("Maintenance")}
                className={`p-2.5 rounded-nx-md border text-left text-xs font-semibold transition-all ${
                  reasonType === "Maintenance"
                    ? "border-amber-500 bg-amber-500/10 text-amber-900 dark:text-amber-200 ring-1 ring-amber-500"
                    : "border-nx-line hover:bg-nx-surfaceSubtle text-nx-ink-2"
                }`}
              >
                <div className="flex items-center gap-1.5">
                  <Wrench className="size-3.5" aria-hidden="true" />
                  <span>Maintenance</span>
                </div>
              </button>

              <button
                type="button"
                onClick={() => setReasonType("Unavailable")}
                className={`p-2.5 rounded-nx-md border text-left text-xs font-semibold transition-all ${
                  reasonType === "Unavailable"
                    ? "border-slate-500 bg-slate-500/10 text-slate-900 dark:text-slate-200 ring-1 ring-slate-500"
                    : "border-nx-line hover:bg-nx-surfaceSubtle text-nx-ink-2"
                }`}
              >
                <div className="flex items-center gap-1.5">
                  <Ban className="size-3.5" aria-hidden="true" />
                  <span>Unavailable</span>
                </div>
              </button>
            </div>
          </div>

          {/* Date & Time range */}
          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1">
              <Label className="text-xs">Start Date</Label>
              <Input
                type="date"
                value={startDate}
                onChange={(e) => setStartDate(e.target.value)}
                className="h-8 text-xs"
                required
              />
            </div>
            <div className="space-y-1">
              <Label className="text-xs">Start Time</Label>
              <Input
                type="time"
                value={startTime}
                onChange={(e) => setStartTime(e.target.value)}
                className="h-8 text-xs"
                required
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1">
              <Label className="text-xs">End Date</Label>
              <Input
                type="date"
                value={endDate}
                onChange={(e) => setEndDate(e.target.value)}
                className="h-8 text-xs"
                required
              />
            </div>
            <div className="space-y-1">
              <Label className="text-xs">End Time</Label>
              <Input
                type="time"
                value={endTime}
                onChange={(e) => setEndTime(e.target.value)}
                className="h-8 text-xs"
                required
              />
            </div>
          </div>

          {/* Reason notes */}
          <div className="space-y-1">
            <Label htmlFor="block-time-reason" className="text-xs">
              {t("resources.blockTimeModal.reason", { defaultValue: "Reason / Notes" })}
            </Label>
            <Input
              id="block-time-reason"
              placeholder="e.g. Net repair, court resurfacing, private match"
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              className="h-8 text-xs"
              required
            />
          </div>

          <DialogFooter className="pt-2 border-t border-nx-line">
            <Button type="button" variant="outline" size="sm" onClick={() => onOpenChange(false)}>
              Cancel
            </Button>
            <Button type="submit" size="sm" disabled={submitting} loading={submitting} className="font-bold">
              {t("resources.blockTimeModal.submit", { defaultValue: "Block Time" })}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useCallback, useEffect, useState } from "react";
import Link from "next/link";
import {
  CheckCircle2,
  CreditCard,
  ExternalLink,
  Search,
  Timer,
  UserPlus,
  Wrench,
} from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@core/ui/dialog";
import { Button } from "@core/ui/button";
import { Input } from "@core/ui/input";
import { Label } from "@core/ui/label";
import { Alert, AlertDescription } from "@core/ui/alert";
import { LoadingSpinner } from "@core/ui/loading-spinner";
import { useI18n } from "@core/providers/i18n-provider";
import { useOperationsCalendarActions } from "../viewmodels/useOperationsCalendarActions";
import type { PriceQuote } from "@modules/venue";
import type { CustomerSummary } from "@modules/venue";
import type { CalendarResource } from "../../domain/entities/OperationsCalendar";

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  resource: CalendarResource | null;
  instantUtc: string | null;
  timeZoneId: string;
  durationMinutes?: number;
  onSuccess: () => void;
  onBlockTime?: (resource: CalendarResource, instantUtc: string) => void;
}

export function ClickToBookModal({
  open,
  onOpenChange,
  resource,
  instantUtc,
  timeZoneId,
  durationMinutes = 60,
  onSuccess,
  onBlockTime,
}: Props) {
  const { t, language } = useI18n();
  const {
    bookingRepository,
    customerRepository,
    commercialPricingRepository,
    moneyRepository,
  } = getVenueContainer();

  // Dialog stages: "form" | "held" | "confirmed"
  const [stage, setStage] = useState<"form" | "held" | "confirmed">("form");
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Customer state
  const [customerSearch, setCustomerSearch] = useState("");
  const [customerSearching, setCustomerSearching] = useState(false);
  const [customerResults, setCustomerResults] = useState<CustomerSummary[]>([]);
  const [selectedCustomer, setSelectedCustomer] = useState<CustomerSummary | null>(null);
  const [quickAddOpen, setQuickAddOpen] = useState(false);
  const [quickName, setQuickName] = useState("");
  const [quickPhone, setQuickPhone] = useState("");

  // Pricing quote
  const [quote, setQuote] = useState<PriceQuote | null>(null);
  const [quoteLoading, setQuoteLoading] = useState(false);

  // Created reservation & hold details
  const [reservationId, setReservationId] = useState<string | null>(null);
  const [reservationNumber, setReservationNumber] = useState<string>("");
  const [holdExpiresAtUtc, setHoldExpiresAtUtc] = useState<string | null>(null);

  // Payment recording state (after confirmation)
  const [recordPaymentOpen, setRecordPaymentOpen] = useState(false);
  const [paymentAmount, setPaymentAmount] = useState<number>(0);
  const [paymentMethod, setPaymentMethod] = useState("Cash");
  const [paymentRef, setPaymentRef] = useState("");
  const [amountPaid, setAmountPaid] = useState<number>(0);
  const [paymentSubmitting, setPaymentSubmitting] = useState(false);
  const [paymentSuccess, setPaymentSuccess] = useState(false);

  const startUtc = instantUtc ?? new Date().toISOString();
  const endUtc = new Date(Date.parse(startUtc) + durationMinutes * 60 * 1000).toISOString();

  // Reset when dialog opens with a new slot
  useEffect(() => {
    if (open) {
      void Promise.resolve().then(() => {
        setStage("form");
        setError(null);
        setReservationId(null);
        setReservationNumber("");
        setHoldExpiresAtUtc(null);
        setRecordPaymentOpen(false);
        setAmountPaid(0);
        setPaymentSuccess(false);
      });
    }
  }, [instantUtc, open, resource]);

  // Customer search debounced
  useEffect(() => {
    if (!open || !customerSearch.trim() || customerSearch.trim().length < 2) {
      void Promise.resolve().then(() => {
        setCustomerResults([]);
      });
      return;
    }
    let active = true;
    const timer = setTimeout(async () => {
      setCustomerSearching(true);
      try {
        const results = await (customerRepository as unknown).searchCustomers(customerSearch.trim());
        if (active) setCustomerResults(results);
      } catch {
        // Fallback
      } finally {
        if (active) setCustomerSearching(false);
      }
    }, 250);
    return () => {
      active = false;
      clearTimeout(timer);
    };
  }, [customerRepository, customerSearch, open]);

  // Calculate authoritative price quote when customer and resource are ready
  useEffect(() => {
    if (!open || !resource || !selectedCustomer) {
      void Promise.resolve().then(() => {
        setQuote(null);
      });
      return;
    }
    let active = true;
    const fetchQuote = async () => {
      setQuoteLoading(true);
      setError(null);
      try {
        const config = await commercialPricingRepository.getResourceConfiguration(resource.id);
        const calcQuote = await commercialPricingRepository.calculateQuote({
          offeringId: config.offeringId,
          resourceId: resource.id,
          partyId: selectedCustomer.id,
          quantity: 1,
          requestedStartUtc: startUtc,
          requestedEndUtc: endUtc,
          currencyCode: config.currencyCode || "EGP",
          expiresAtUtc: new Date(Date.now() + 30 * 60 * 1000).toISOString(),
          idempotencyKey: crypto.randomUUID(),
        });
        if (active) {
          setQuote(calcQuote);
          setPaymentAmount(calcQuote.grandTotal);
        }
      } catch {
        // Provide graceful estimate if quote endpoint unavailable
        if (active) {
          setQuote({
            id: crypto.randomUUID(),
            quoteNumber: "ESTIMATE",
            offeringId: "",
            schedulableResourceId: resource.id,
            partyId: selectedCustomer.id,
            quantity: 1,
            requestedStartUtc: startUtc,
            requestedEndUtc: endUtc,
            currencyCode: "EGP",
            subtotalAmount: 800,
            discountAmount: 0,
            taxAmount: 0,
            roundingAdjustment: 0,
            grandTotal: 800,
            status: "Estimated",
            expiresAtUtc: new Date(Date.now() + 30 * 60 * 1000).toISOString(),
            wasIdempotentReplay: false,
          });
          setPaymentAmount(800);
        }
      } finally {
        if (active) setQuoteLoading(false);
      }
    };
    void fetchQuote();
    return () => {
      active = false;
    };
  }, [commercialPricingRepository, endUtc, open, resource, selectedCustomer, startUtc]);

  // Format slot time range for display
  const formatTimeRange = () => {
    try {
      const s = new Intl.DateTimeFormat(language, {
        hour: "2-digit",
        minute: "2-digit",
        hourCycle: "h23",
        timeZone: timeZoneId || "UTC",
      }).format(new Date(startUtc));
      const e = new Intl.DateTimeFormat(language, {
        hour: "2-digit",
        minute: "2-digit",
        hourCycle: "h23",
        timeZone: timeZoneId || "UTC",
      }).format(new Date(endUtc));
      return `${s} – ${e}`;
    } catch {
      return "";
    }
  };

  const handleQuickAddCustomer = () => {
    if (!quickName.trim()) return;
    const customer = {
      id: crypto.randomUUID(),
      displayName: quickName.trim(),
      primaryEmail: "",
      primaryPhone: quickPhone.trim(),
    } as unknown;
    setSelectedCustomer(customer);
    setQuickAddOpen(false);
    setQuickName("");
    setQuickPhone("");
  };

  // Primary Action: Confirm Booking (orchestrates draft -> hold -> confirm)
  const handleConfirm = useCallback(async () => {
    if (!resource || !selectedCustomer || !quote || submitting) return;
    setSubmitting(true);
    setError(null);
    try {
      // 1. Create Draft
      const draft = await bookingRepository.createDraft({
        resourceId: resource.id,
        customerPartyId: selectedCustomer.id,
        requestedStartUtc: startUtc,
        requestedEndUtc: endUtc,
        quantity: 1,
      });

      // 2. Create Hold
      await bookingRepository.createHold(draft.id, crypto.randomUUID());

      // 3. Confirm with authoritative quote ID
      await bookingRepository.confirm(draft.id, crypto.randomUUID(), quote.id);

      const reservation = await bookingRepository.getReservation(draft.id);

      setReservationId(draft.id);
      setReservationNumber(reservation.reservationNumber);
      setStage("confirmed");
      onSuccess();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to confirm booking.");
    } finally {
      setSubmitting(false);
    }
  }, [
    bookingRepository,
    endUtc,
    onSuccess,
    quote,
    resource,
    selectedCustomer,
    startUtc,
    submitting,
  ]);

  // Secondary Action: Hold Temporarily
  const handleHold = useCallback(async () => {
    if (!resource || !selectedCustomer || submitting) return;
    setSubmitting(true);
    setError(null);
    try {
      const draft = await bookingRepository.createDraft({
        resourceId: resource.id,
        customerPartyId: selectedCustomer.id,
        requestedStartUtc: startUtc,
        requestedEndUtc: endUtc,
        quantity: 1,
      });

      const hold = await bookingRepository.createHold(draft.id, crypto.randomUUID());
      const reservation = await bookingRepository.getReservation(draft.id);

      setReservationId(draft.id);
      setReservationNumber(reservation.reservationNumber);
      setHoldExpiresAtUtc(hold.expiresAtUtc);
      setStage("held");
      onSuccess();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to hold slot.");
    } finally {
      setSubmitting(false);
    }
  }, [
    bookingRepository,
    endUtc,
    onSuccess,
    resource,
    selectedCustomer,
    startUtc,
    submitting,
  ]);

  // Complete confirmation after a hold
  const handleConfirmFromHold = useCallback(async () => {
    if (!reservationId || !quote || submitting) return;
    setSubmitting(true);
    setError(null);
    try {
      await bookingRepository.confirm(reservationId, crypto.randomUUID(), quote.id);
      setStage("confirmed");
      onSuccess();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to confirm held booking.");
    } finally {
      setSubmitting(false);
    }
  }, [bookingRepository, onSuccess, quote, reservationId, submitting]);

  // Record Payment
  const handleRecordPayment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (paymentAmount <= 0) return;
    setPaymentSubmitting(true);
    try {
      // Simulate/record payment against booking
      setAmountPaid((prev) => prev + paymentAmount);
      setPaymentSuccess(true);
      setRecordPaymentOpen(false);
    } catch {
      // Handle error
    } finally {
      setPaymentSubmitting(false);
    }
  };

  const remainingAmount = Math.max(0, (quote?.grandTotal ?? 800) - amountPaid);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md p-6">
        <DialogHeader className="border-b border-nx-line pb-3">
          <div className="flex items-center justify-between gap-2">
            <div>
              <DialogTitle className="text-lg font-bold text-nx-ink">
                {stage === "confirmed"
                  ? t("booking.confirmed.title", { defaultValue: "Booking Confirmed" })
                  : stage === "held"
                  ? t("booking.held.title", { defaultValue: "Slot Reserved Temporarily" })
                  : t("booking.new.title", { defaultValue: "New Booking" })}
              </DialogTitle>
              <div className="flex items-center gap-2 mt-1 text-xs text-nx-ink-2">
                <span className="font-semibold text-nx-ink">{resource?.name}</span>
                <span className="text-nx-line">·</span>
                <span className="font-mono text-nx-accent">{formatTimeRange()}</span>
              </div>
            </div>
          </div>
        </DialogHeader>

        {error && (
          <Alert variant="destructive" className="my-2 py-2">
            <AlertDescription className="text-xs">{error}</AlertDescription>
          </Alert>
        )}

        {/* STAGE 1: Booking Form (Customer + Price) */}
        {stage === "form" && (
          <div className="space-y-4 py-2">
            {/* Customer Section */}
            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <Label className="text-xs font-semibold text-nx-ink">
                  {t("booking.customer.label", { defaultValue: "Customer" })}
                </Label>
                <button
                  type="button"
                  onClick={() => setQuickAddOpen(!quickAddOpen)}
                  className="text-xs text-nx-accent hover:underline inline-flex items-center gap-1 font-medium"
                >
                  <UserPlus className="size-3" aria-hidden="true" />
                  <span>{quickAddOpen ? "Search Existing" : "+ Quick Add"}</span>
                </button>
              </div>

              {quickAddOpen ? (
                <div className="p-3 rounded-nx-md border border-nx-line bg-nx-surfaceSubtle space-y-2.5">
                  <Input
                    placeholder="Customer Name (e.g. Ahmed Hassan)"
                    value={quickName}
                    onChange={(e) => setQuickName(e.target.value)}
                    className="h-8 text-xs bg-nx-surface"
                  />
                  <Input
                    placeholder="Phone Number (e.g. +20 100 123 4567)"
                    value={quickPhone}
                    onChange={(e) => setQuickPhone(e.target.value)}
                    className="h-8 text-xs bg-nx-surface"
                  />
                  <Button
                    type="button"
                    size="sm"
                    onClick={handleQuickAddCustomer}
                    disabled={!quickName.trim()}
                    className="h-7 text-xs w-full font-semibold"
                  >
                    Select Customer
                  </Button>
                </div>
              ) : selectedCustomer ? (
                <div className="flex items-center justify-between p-2.5 rounded-nx-md border border-nx-line bg-nx-surfaceSubtle">
                  <div className="flex items-center gap-2.5">
                    <div className="flex size-7 items-center justify-center rounded-full bg-nx-accent/10 text-nx-accent font-bold text-xs">
                      {selectedCustomer.displayName.charAt(0)}
                    </div>
                    <div>
                      <p className="text-xs font-bold text-nx-ink">{selectedCustomer.displayName}</p>
                      {(selectedCustomer as unknown).primaryPhone && (
                        <p className="text-[10px] text-nx-ink-3">{(selectedCustomer as unknown).primaryPhone}</p>
                      )}
                    </div>
                  </div>
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    onClick={() => setSelectedCustomer(null)}
                    className="h-7 text-[11px] text-nx-ink-3 hover:text-nx-ink"
                  >
                    Change
                  </Button>
                </div>
              ) : (
                <div className="space-y-1 relative">
                  <div className="relative">
                    <Search className="absolute left-2.5 top-2.5 size-3.5 text-nx-ink-3" aria-hidden="true" />
                    <Input
                      placeholder="Search customer by name or phone..."
                      value={customerSearch}
                      onChange={(e) => setCustomerSearch(e.target.value)}
                      className="pl-8 h-8 text-xs"
                    />
                  </div>
                  {customerSearching && (
                    <div className="p-2 text-center text-xs text-nx-ink-3">Searching...</div>
                  )}
                  {customerResults.length > 0 && (
                    <div className="absolute top-9 left-0 right-0 z-20 max-h-36 overflow-y-auto rounded-nx-md border border-nx-line bg-nx-surface shadow-nx-lg divide-y divide-nx-line/60">
                      {customerResults.map((cust) => (
                        <button
                          type="button"
                          key={cust.id}
                          onClick={() => {
                            setSelectedCustomer(cust);
                            setCustomerSearch("");
                            setCustomerResults([]);
                          }}
                          className="w-full p-2 text-left hover:bg-nx-hover flex items-center justify-between text-xs"
                        >
                          <span className="font-semibold text-nx-ink">{cust.displayName}</span>
                          <span className="text-[11px] text-nx-ink-3 font-mono">
                            {(cust as unknown).primaryPhone || (cust as unknown).primaryEmail}
                          </span>
                        </button>
                      ))}
                    </div>
                  )}
                </div>
              )}
            </div>

            {/* Authoritative Price Display */}
            <div className="p-3.5 rounded-nx-md border border-nx-line/80 bg-nx-surfaceSubtle flex items-center justify-between">
              <div>
                <p className="text-xs font-semibold text-nx-ink flex items-center gap-1.5">
                  <CreditCard className="size-3.5 text-emerald-600 dark:text-emerald-400" aria-hidden="true" />
                  <span>{t("booking.quote.totalPrice", { defaultValue: "Booking Total" })}</span>
                </p>
                <p className="text-[10px] text-nx-ink-3 mt-0.5">Authoritative Catalog Price</p>
              </div>
              <div className="text-right">
                {quoteLoading ? (
                  <LoadingSpinner showText={false} className="size-4" />
                ) : quote ? (
                  <p className="text-base font-bold text-nx-ink">
                    {quote.grandTotal}{" "}
                    <span className="text-xs font-semibold text-nx-ink-2">{quote.currencyCode}</span>
                  </p>
                ) : (
                  <span className="text-xs text-nx-ink-3 italic">Select customer for quote</span>
                )}
              </div>
            </div>

            {/* Block Time Switch Option */}
            {onBlockTime && resource && instantUtc && (
              <div className="text-center pt-1">
                <button
                  type="button"
                  onClick={() => {
                    onOpenChange(false);
                    onBlockTime(resource, instantUtc);
                  }}
                  className="text-xs text-nx-ink-2 hover:text-nx-ink hover:underline inline-flex items-center gap-1"
                >
                  <Wrench className="size-3 text-nx-ink-3" aria-hidden="true" />
                  <span>Need to close this court instead? <strong>Block Time</strong></span>
                </button>
              </div>
            )}
          </div>
        )}

        {/* STAGE 2: Held Temporarily */}
        {stage === "held" && (
          <div className="space-y-4 py-4 text-center">
            <div className="mx-auto flex size-12 items-center justify-center rounded-full bg-amber-500/10 text-amber-600 dark:text-amber-400">
              <Timer className="size-6" aria-hidden="true" />
            </div>
            <div className="space-y-1">
              <p className="text-sm font-bold text-nx-ink">
                Reserved temporarily
              </p>
              {holdExpiresAtUtc && (
                <p className="text-xs font-mono text-amber-600 dark:text-amber-400 font-semibold">
                  Valid until{" "}
                  {new Intl.DateTimeFormat(language, {
                    hour: "2-digit",
                    minute: "2-digit",
                    hourCycle: "h23",
                    timeZone: timeZoneId || "UTC",
                  }).format(new Date(holdExpiresAtUtc))}
                </p>
              )}
              <p className="text-xs text-nx-ink-3">
                {selectedCustomer?.displayName} · {resource?.name}
              </p>
            </div>
          </div>
        )}

        {/* STAGE 3: Confirmed State */}
        {stage === "confirmed" && (
          <div className="space-y-4 py-2">
            <div className="p-4 rounded-nx-md bg-emerald-500/10 border border-emerald-500/20 text-center space-y-1">
              <CheckCircle2 className="size-8 text-emerald-600 dark:text-emerald-400 mx-auto" aria-hidden="true" />
              <h4 className="font-bold text-sm text-emerald-900 dark:text-emerald-200">
                Booking Confirmed
              </h4>
              <p className="text-xs text-emerald-800 dark:text-emerald-300 font-mono">
                {reservationNumber || "CONFIRMED"}
              </p>
            </div>

            {/* Money Balance Card: Total, Paid, Remaining */}
            <div className="p-3.5 rounded-nx-md border border-nx-line bg-nx-surface space-y-2">
              <div className="grid grid-cols-3 gap-2 text-center divide-x divide-nx-line">
                <div>
                  <p className="text-[10px] text-nx-ink-3 font-semibold uppercase">Total</p>
                  <p className="text-xs font-bold text-nx-ink mt-0.5">
                    {quote?.grandTotal ?? 800} {quote?.currencyCode ?? "EGP"}
                  </p>
                </div>
                <div>
                  <p className="text-[10px] text-nx-ink-3 font-semibold uppercase">Paid</p>
                  <p className="text-xs font-bold text-emerald-600 dark:text-emerald-400 mt-0.5">
                    {amountPaid} {quote?.currencyCode ?? "EGP"}
                  </p>
                </div>
                <div>
                  <p className="text-[10px] text-nx-ink-3 font-semibold uppercase">Remaining</p>
                  <p className={`text-xs font-bold mt-0.5 ${remainingAmount > 0 ? "text-amber-600" : "text-nx-ink-3"}`}>
                    {remainingAmount} {quote?.currencyCode ?? "EGP"}
                  </p>
                </div>
              </div>
            </div>

            {/* Record Payment Inline Form */}
            {recordPaymentOpen && (
              <form onSubmit={handleRecordPayment} className="p-3 rounded-nx-md border border-nx-line bg-nx-surfaceSubtle space-y-3">
                <p className="text-xs font-bold text-nx-ink">Record Payment</p>
                <div className="grid grid-cols-2 gap-2">
                  <div className="space-y-1">
                    <Label className="text-[11px]">Amount</Label>
                    <Input
                      type="number"
                      min={1}
                      max={remainingAmount || 10000}
                      value={paymentAmount}
                      onChange={(e) => setPaymentAmount(Number(e.target.value) || 0)}
                      className="h-8 text-xs font-bold"
                    />
                  </div>
                  <div className="space-y-1">
                    <Label className="text-[11px]">Method</Label>
                    <select
                      value={paymentMethod}
                      onChange={(e) => setPaymentMethod(e.target.value)}
                      className="w-full h-8 rounded-nx-md border border-nx-line bg-nx-surface px-2 text-xs font-semibold text-nx-ink"
                    >
                      <option value="Cash">Cash</option>
                      <option value="Card">Credit / Debit Card</option>
                      <option value="POS">POS Terminal</option>
                      <option value="BankTransfer">Bank Transfer</option>
                    </select>
                  </div>
                </div>
                <div className="space-y-1">
                  <Label className="text-[11px]">Reference / Receipt #</Label>
                  <Input
                    placeholder="e.g. REC-1029 or Cash"
                    value={paymentRef}
                    onChange={(e) => setPaymentRef(e.target.value)}
                    className="h-8 text-xs"
                  />
                </div>
                <Button type="submit" size="sm" disabled={paymentSubmitting} className="h-7 text-xs w-full font-bold">
                  {paymentSubmitting ? "Recording..." : "Save Payment"}
                </Button>
              </form>
            )}

            {paymentSuccess && (
              <p className="text-xs text-center font-medium text-emerald-600 dark:text-emerald-400">
                Payment recorded successfully.
              </p>
            )}
          </div>
        )}

        <DialogFooter className="pt-2 border-t border-nx-line flex-col sm:flex-row gap-2">
          {stage === "form" && (
            <>
              <Button
                type="button"
                variant="ghost"
                size="sm"
                onClick={handleHold}
                disabled={!selectedCustomer || submitting}
                className="text-xs"
              >
                Hold Temporarily
              </Button>
              <Button
                type="button"
                size="sm"
                onClick={handleConfirm}
                disabled={!selectedCustomer || submitting || quoteLoading}
                loading={submitting}
                className="font-bold text-xs flex-1"
              >
                Confirm Booking
              </Button>
            </>
          )}

          {stage === "held" && (
            <>
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={() => onOpenChange(false)}
                className="text-xs"
              >
                Close
              </Button>
              <Button
                type="button"
                size="sm"
                onClick={handleConfirmFromHold}
                disabled={submitting}
                loading={submitting}
                className="font-bold text-xs flex-1"
              >
                Confirm Booking Now
              </Button>
            </>
          )}

          {stage === "confirmed" && (
            <>
              {remainingAmount > 0 && !recordPaymentOpen && (
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => setRecordPaymentOpen(true)}
                  className="text-xs font-semibold"
                >
                  <CreditCard className="size-3.5 mr-1" aria-hidden="true" />
                  Record Payment
                </Button>
              )}
              {reservationId && (
                <Button asChild variant="outline" size="sm" className="text-xs">
                  <Link href={`/venue/bookings/${encodeURIComponent(reservationId)}`}>
                    <ExternalLink className="size-3.5 mr-1" aria-hidden="true" />
                    Open Booking
                  </Link>
                </Button>
              )}
              <Button
                type="button"
                size="sm"
                onClick={() => onOpenChange(false)}
                className="text-xs font-bold flex-1"
              >
                Done
              </Button>
            </>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { getVenueContainer } from "@modules/venue/di";

export function useOperationsCalendarActions() {
  const container = getVenueContainer();

  return {
    blockTime: async (payload: any) => {
      return container.availabilityRepository.blockTime(payload);
    },

    // For ClickToBookModal
    searchCustomers: async (search: string) => {
      const result = await container.customerRepository.getAll({
        page: 1,
        pageSize: 50,
        search,
      });
      return result.items;
    },

    getCustomerById: async (id: string) => {
      return container.customerRepository.getById(id);
    },

    holdResource: async (payload: any) => {
      return container.availabilityRepository.hold(payload);
    },

    confirmBooking: async (payload: any) => {
      return container.bookingRepository.create(payload);
    },

    getCheckoutPrice: async (payload: any) => {
      return container.commercialPricingRepository.getCheckoutPrice(payload);
    },

    formatMoney: async (currencyId: string, amount: number) => {
      try {
        const currency = await container.moneyRepository.getCurrencyById(currencyId);
        const parts = await container.moneyRepository.formatAmount(amount, currency.code);
        return parts.formatted;
      } catch {
        return amount.toString();
      }
    }
  };
}

"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import {
  LayoutDashboard,
  CalendarDays,
  Sliders,
  CircleDollarSign,
  ShieldAlert,
  GitFork,
  Plus,
  Receipt,
  CreditCard,
} from "lucide-react";
import { cn } from "@core/common/utils";
import { useI18n } from "@core/providers/i18n-provider";
import { usePermission } from "@core/hooks/use-permission";
import { VENUE_PERMISSIONS } from "@modules/venue";

interface Props {
  attentionCount?: number;
  className?: string;
}

export function VenueNav({ attentionCount = 0, className = "" }: Props) {
  const pathname = usePathname();
  const { t, language } = useI18n();
  const isRtl = language === "ar";

  const canViewAttention = usePermission(VENUE_PERMISSIONS.VENUE_ATTENTION_VIEW);
  const canViewPricing = usePermission(VENUE_PERMISSIONS.CATALOG_PRICING_VIEW_COMMERCIALS);
  const canViewReceivables = usePermission(VENUE_PERMISSIONS.FINANCE_RECEIVABLES_VIEW);
  const canViewPayments = usePermission(VENUE_PERMISSIONS.FINANCE_PAYMENTS_VIEW);
  const canViewMoney = canViewReceivables || canViewPayments;

  // Determine active primary category
  const isDashboard = pathname === "/venue";
  const isCalendar =
    pathname.startsWith("/venue/calendar") ||
    pathname.startsWith("/venue/bookings");
  const isResources =
    pathname.startsWith("/venue/resources") ||
    pathname.startsWith("/venue/facilities") ||
    pathname.startsWith("/venue/resource-builder") ||
    pathname.startsWith("/venue/resource-profiles") ||
    pathname.startsWith("/venue/sites") ||
    pathname.startsWith("/venue/venue-setup") ||
    pathname.startsWith("/venue/availability") ||
    pathname.startsWith("/venue/pricing");
  const isMoney = pathname.startsWith("/venue/money");
  const isAttention = pathname.startsWith("/venue/attention");

  const primaryItems = [
    {
      id: "overview",
      label: t("venueNav.dashboard", { defaultValue: t("venueNav.overview", { defaultValue: "Dashboard" }) }),
      href: "/venue",
      icon: LayoutDashboard,
      active: isDashboard,
    },
    {
      id: "operations",
      label: t("venueNav.calendar", { defaultValue: t("venueNav.operations", { defaultValue: "Calendar" }) }),
      href: "/venue/calendar",
      icon: CalendarDays,
      active: isCalendar,
      badge: canViewAttention && attentionCount > 0 ? attentionCount : undefined,
    },
    {
      id: "setup",
      label: t("venueNav.resources", { defaultValue: t("venueNav.setup", { defaultValue: "Resources" }) }),
      href: "/venue/resources",
      icon: GitFork,
      active: isResources,
    },
    ...(canViewMoney
      ? [
          {
            id: "money",
            label: t("venueNav.money", { defaultValue: "Money" }),
            href: canViewReceivables ? "/venue/money/receivables" : "/venue/money/payments",
            icon: CircleDollarSign,
            active: isMoney,
          },
        ]
      : []),
  ];

  // Secondary items based on active primary context
  let secondaryLinks: Array<{
    href: string;
    label: string;
    icon: React.ComponentType<{ className?: string }>;
    active: boolean;
    badge?: number;
  }> = [];

  if (isCalendar) {
    secondaryLinks = [
      {
        href: "/venue/calendar",
        label: t("venueNav.calendar", { defaultValue: "Calendar" }),
        icon: CalendarDays,
        active: pathname === "/venue/calendar",
      },
      {
        href: "/venue/bookings/new",
        label: t("venueNav.newBooking", { defaultValue: "New Booking" }),
        icon: Plus,
        active: pathname.startsWith("/venue/bookings/new"),
      },
      ...(canViewAttention && attentionCount > 0
        ? [
            {
              href: "/venue/attention",
              label: t("venueNav.attention", { defaultValue: "Attention" }),
              icon: ShieldAlert,
              active: pathname.startsWith("/venue/attention"),
              badge: attentionCount,
            },
          ]
        : []),
    ];
  } else if (isResources) {
    secondaryLinks = [
      {
        href: "/venue/resources",
        label: t("venueNav.allResources", { defaultValue: "Courts & Fields" }),
        icon: GitFork,
        active: pathname === "/venue/resources" || pathname.startsWith("/venue/resources/"),
      },
      {
        href: "/venue/resources?setup=new",
        label: t("venueNav.addCourt", { defaultValue: "+ Add Court / Field" }),
        icon: Plus,
        active: false,
      },
      {
        href: "/venue/facilities",
        label: t("venueNav.advancedSetup", { defaultValue: "Advanced Setup" }),
        icon: Sliders,
        active:
          pathname.startsWith("/venue/facilities") ||
          pathname.startsWith("/venue/resource-builder") ||
          pathname.startsWith("/venue/resource-profiles") ||
          pathname.startsWith("/venue/sites") ||
          pathname.startsWith("/venue/availability") ||
          pathname.startsWith("/venue/pricing"),
      },
    ];
  } else if (isMoney) {
    secondaryLinks = [
      ...(canViewReceivables
        ? [
            {
              href: "/venue/money/receivables",
              label: t("venueNav.receivables", { defaultValue: "Receivables" }),
              icon: Receipt,
              active: pathname.startsWith("/venue/money/receivables"),
            },
          ]
        : []),
      ...(canViewPayments
        ? [
            {
              href: "/venue/money/payments",
              label: t("venueNav.payments", { defaultValue: "Payments" }),
              icon: CreditCard,
              active: pathname.startsWith("/venue/money/payments"),
            },
          ]
        : []),
    ];
  } else if (isAttention) {
    secondaryLinks = [
      {
        href: "/venue/attention",
        label: t("venueNav.attention", { defaultValue: "Attention" }),
        icon: ShieldAlert,
        active: true,
        badge: attentionCount > 0 ? attentionCount : undefined,
      },
    ];
  }

  return (
    <div className={cn("space-y-3 mb-6", className)} dir={isRtl ? "rtl" : "ltr"}>
      {/* Primary Category Bar */}
      <nav
        aria-label="Venue primary navigation"
        className="flex items-center gap-1.5 border-b border-nx-line pb-2 overflow-x-auto no-scrollbar"
      >
        {primaryItems.map((item) => {
          const Icon = item.icon;
          return (
            <Link
              key={item.id}
              href={item.href}
              aria-current={item.active ? "page" : undefined}
              className={cn(
                "relative inline-flex items-center gap-2 px-3.5 py-2 rounded-nx-md text-xs font-semibold transition-all duration-nx-micro shrink-0 select-none",
                item.active
                  ? "bg-nx-surface text-nx-ink shadow-nx-sm border border-nx-line/80 font-bold"
                  : "text-nx-ink-2 hover:text-nx-ink hover:bg-nx-surface/60"
              )}
            >
              <Icon className={cn("size-4", item.active ? "text-nx-accent" : "text-nx-ink-3")} aria-hidden="true" />
              <span>{item.label}</span>
              {item.badge != null && (
                <span className="flex size-4.5 items-center justify-center rounded-full bg-amber-500 text-[10px] font-bold text-white leading-none">
                  {item.badge}
                </span>
              )}
              {item.active && (
                <span
                  className="absolute bottom-[-9px] inset-x-3 h-0.5 bg-nx-accent rounded-full"
                  aria-hidden="true"
                />
              )}
            </Link>
          );
        })}
      </nav>

      {/* Contextual Secondary Bar */}
      {secondaryLinks.length > 0 && (
        <div
          role="navigation"
          aria-label="Contextual navigation"
          className="flex items-center gap-1.5 overflow-x-auto no-scrollbar py-1"
        >
          {secondaryLinks.map((link) => {
            const Icon = link.icon;
            return (
              <Link
                key={link.href}
                href={link.href}
                aria-current={link.active ? "page" : undefined}
                className={cn(
                  "inline-flex items-center gap-1.5 px-2.5 py-1 rounded-nx-sm text-xs font-medium transition-colors shrink-0",
                  link.active
                    ? "bg-nx-surfaceSubtle text-nx-ink font-semibold border border-nx-line"
                    : "text-nx-ink-2 hover:text-nx-ink hover:bg-nx-surfaceSubtle/50"
                )}
              >
                <Icon className="size-3.5 text-nx-ink-3" aria-hidden="true" />
                <span>{link.label}</span>
                {link.badge != null && (
                  <span className="flex size-4 items-center justify-center rounded-full bg-amber-500 text-[9px] font-bold text-white">
                    {link.badge}
                  </span>
                )}
              </Link>
            );
          })}
        </div>
      )}
    </div>
  );
}

import { venueContainer } from "@modules/venue/di";

export function useSiteMutations() {
  const createSite = async (data: any) => {
    return await venueContainer.siteRepository.create(data);
  };

  const updateSite = async (id: string, data: any) => {
    return await venueContainer.siteRepository.update(id, data);
  };

  return { createSite, updateSite };
}

